import React, { createContext, useContext, useEffect, useMemo, useState, useCallback } from "react";
import axios from "axios";

const API = "http://localhost:5000";
const PermissionsContext = createContext(null);

const pickArray = (p) =>
  Array.isArray(p) ? p
  : Array.isArray(p?.data) ? p.data
  : Array.isArray(p?.recordset) ? p.recordset
  : [];

// ------------------------------------------------------------
// Normalization
//   ModuleName / PermissionName in the DB are free-text and
//   case-inconsistent ("Reorder" vs "reorder", "Products" vs
//   "product"). Normalize both sides of every comparison.
// ------------------------------------------------------------
const norm = (s) => String(s ?? "").trim().toLowerCase();

// Coerce the various shapes a flag can take (1 / 0 / true / false
// / "1" / "0" / "true" / "false"). Using bare truthiness would
// treat the string "0" as granted.
const isGranted = (v) => {
  if (v === true) return true;
  if (v === false || v == null) return false;
  if (typeof v === "number") return v !== 0;
  if (typeof v === "string") {
    const t = v.trim().toLowerCase();
    return t !== "" && t !== "0" && t !== "false" && t !== "no";
  }
  return Boolean(v);
};

export function PermissionsProvider({ cashierID, children }) {
  const [permissions, setPermissions] = useState([]);
  const [loading, setLoading]         = useState(false);
  const [error, setError]             = useState("");

  const load = useCallback(async () => {
    if (!cashierID) { setPermissions([]); return; }
    setLoading(true); setError("");
    const urls = [
      `${API}/cashiers/${cashierID}/permissions`,
      `${API}/${cashierID}/permissions`,
    ];
    try {
      let lastErr;
      for (const url of urls) {
        try {
          const res = await axios.get(url);
          setPermissions(pickArray(res.data));
          return;
        } catch (e) { lastErr = e; }
      }
      throw lastErr;
    } catch (e) {
      console.error("[Permissions] load failed:", e);
      setError(e?.message || "Unable to load permissions");
      setPermissions([]);
    } finally { setLoading(false); }
  }, [cashierID]);

  useEffect(() => { load(); }, [load]);

  // ----------------------------------------------------------
  // Index: normalized module name -> { row, byName }
  //   byName maps normalized PermissionName -> row, so callers
  //   can look up by module only or by module + permission name.
  // ----------------------------------------------------------
  const index = useMemo(() => {
    const map = new Map();
    for (const p of permissions) {
      const key = norm(p?.ModuleName);
      if (!key) continue;

      let entry = map.get(key);
      if (!entry) {
        entry = { row: p, byName: new Map() };
        map.set(key, entry);
      } else if (process.env.NODE_ENV !== "production") {
        // Duplicate module row for this cashier — surface it once
        // rather than silently picking the first.
        console.warn(
          "[Permissions] duplicate ModuleName after normalization:",
          p?.ModuleName
        );
      }

      const pname = norm(p?.PermissionName);
      if (pname && !entry.byName.has(pname)) {
        entry.byName.set(pname, p);
      }
    }
    return map;
  }, [permissions]);

  const can = useCallback(
    (moduleName, permissionName, action = "CanView") => {
      if (!permissions.length) return false;

      const entry = index.get(norm(moduleName));
      if (!entry) return false;

      const row =
        permissionName
          ? entry.byName.get(norm(permissionName)) ?? entry.row
          : entry.row;

      return isGranted(row?.[action]);
    },
    [index, permissions.length]
  );

  const canAny = useCallback(
    (moduleName, action = "CanView") => {
      const entry = index.get(norm(moduleName));
      if (!entry) return false;
      return isGranted(entry.row?.[action]);
    },
    [index]
  );

  return (
    <PermissionsContext.Provider
      value={{ permissions, loading, error, reload: load, can, canAny }}
    >
      {children}
    </PermissionsContext.Provider>
  );
}

export function usePermissions() {
  const ctx = useContext(PermissionsContext);
  if (!ctx) throw new Error("usePermissions must be used inside <PermissionsProvider>");
  return ctx;
}