// SalesRegister.jsx
import React, {
    useCallback,
    useContext,
    useEffect,
    useMemo,
    useState
} from "react";

import axios from "axios";
import {
    Download,
    Calendar,
    DollarSign,
    TrendingUp,
    Package,
    FileText,
    RefreshCw,
    Loader2,
    ChevronRight,
    ChevronDown,
    Filter,
    BarChart3
} from "lucide-react";

import { AuthContext } from "../pos/SERVER/AuthContext.js";

const API_URL = "http://localhost:5000";

/* =========================================================
   AXIOS INTERCEPTOR — attach auth token
========================================================= */

axios.interceptors.request.use((config) => {
    try {
        const token =
            localStorage.getItem("token") ||
            localStorage.getItem("authToken") ||
            localStorage.getItem("jwt");
        config.headers = config.headers || {};
        if (token && !config.headers.Authorization) {
            config.headers.Authorization = `Bearer ${token}`;
        }
    } catch { /* ignore */ }
    return config;
});

/* =========================================================
   HELPERS
========================================================= */

const getLocationID = (user) =>
    Number(
        user?.LocationID ??
        user?.locationID ??
        user?.locationid ??
        user?.location ??
        0
    );

const formatMoney = (value) => {
    const n = Number(value || 0);
    return n.toLocaleString("en-US", {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
    });
};

const formatNumber = (value, decimals = 2) => {
    const n = Number(value || 0);
    return n.toLocaleString("en-US", {
        minimumFractionDigits: decimals,
        maximumFractionDigits: decimals
    });
};

const formatInt = (value) => Number(value || 0).toLocaleString("en-US");

const toDateInput = (d) => {
    const dt = d instanceof Date ? d : new Date(d);
    const yyyy = dt.getFullYear();
    const mm = String(dt.getMonth() + 1).padStart(2, "0");
    const dd = String(dt.getDate()).padStart(2, "0");
    return `${yyyy}-${mm}-${dd}`;
};

const todayStr = () => toDateInput(new Date());

/* =========================================================
   CUSTOMER TYPES
========================================================= */

const CUSTOMER_TYPES = [
    { value: "", label: "All Types" },
    { value: "1", label: "Walk-in" },
    { value: "2", label: "Regular" },
    { value: "3", label: "Wholesale" },
    { value: "4", label: "VIP" }
];

const PAYMENT_METHODS = [
    { value: "", label: "All Methods" },
    { value: "CASH", label: "Cash" },
    { value: "CREDIT", label: "Credit" },
    { value: "CARD", label: "Card" },
    { value: "VOUCHER", label: "Voucher" },
    { value: "CHECK", label: "Check" },
    { value: "TRANSFER", label: "Transfer" },
    { value: "SPLIT", label: "Split" }
];

/* =========================================================
   TAB DEFINITIONS
========================================================= */

const TABS = [
    { key: "billwise",    label: "Bill-wise" },
    { key: "productwise", label: "Products" },
    { key: "supplierwise", label: "Suppliers" },
    { key: "departmentwise", label: "Departments" }
];

/* =========================================================
   COMPONENT
========================================================= */

export default function SalesRegister() {
    const { user } = useContext(AuthContext);
    const userLocationID = useMemo(() => getLocationID(user), [user]);

    /* =====================================================
       FILTER STATE
    ===================================================== */

    const [fromDate, setFromDate] = useState(todayStr());
    const [toDate, setToDate]     = useState(todayStr());
    const [locationID, setLocationID] = useState("");
    const [customerType, setCustomerType] = useState("");
    const [paymentMethod, setPaymentMethod] = useState("");

    const [quickRange, setQuickRange] = useState("today");

    const applyQuickRange = (range) => {
        setQuickRange(range);
        const now = new Date();

        if (range === "today") {
            setFromDate(toDateInput(now));
            setToDate(toDateInput(now));
        } else if (range === "3days") {
            const from = new Date(now);
            from.setDate(from.getDate() - 2);
            setFromDate(toDateInput(from));
            setToDate(toDateInput(now));
        } else if (range === "7days") {
            const from = new Date(now);
            from.setDate(from.getDate() - 6);
            setFromDate(toDateInput(from));
            setToDate(toDateInput(now));
        }
    };

    /* =====================================================
       UI STATE
    ===================================================== */

    const [activeTab, setActiveTab] = useState("billwise");
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState("");

    const [summary, setSummary] = useState({
        totalSales: 0,
        customerReturns: 0,
        netSales: 0,
        netProfit: 0,
        itemsSold: 0,
        invoiceCount: 0,
        avgInvoice: 0
    });

    const [billwise, setBillwise] = useState([]);
    const [productwise, setProductwise] = useState([]);
    const [supplierwise, setSupplierwise] = useState([]);
    const [departmentwise, setDepartmentwise] = useState([]);
    const [locations, setLocations] = useState([]);
    const [dailyTrend, setDailyTrend] = useState([]);
    const [expandedBill, setExpandedBill] = useState(null);

    /* =====================================================
       LOAD LOCATIONS (once)
    ===================================================== */

    useEffect(() => {
        (async () => {
            try {
                const res = await axios.get(`${API_URL}/api/sales-register/locations`);
                const list = Array.isArray(res.data?.data) ? res.data.data : [];
                setLocations(list);
            } catch {
                setLocations([]);
            }
        })();
    }, []);

    /* =====================================================
       FETCH FUNCTIONS
    ===================================================== */

    const buildParams = () => ({
        fromDate,
        toDate,
        locationID: locationID || undefined,
        customerType: customerType || undefined,
        paymentMethod: paymentMethod || undefined
    });

    const loadSummary = useCallback(async () => {
        const res = await axios.get(`${API_URL}/api/sales-register/summary`, { params: buildParams() });
        if (res.data?.success) {
            setSummary(res.data.data || {});
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [fromDate, toDate, locationID, customerType, paymentMethod]);

    const loadBillwise = useCallback(async () => {
        const res = await axios.get(`${API_URL}/api/sales-register/billwise`, { params: buildParams() });
        setBillwise(res.data?.data || []);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [fromDate, toDate, locationID, customerType, paymentMethod]);

    const loadProductwise = useCallback(async () => {
        const res = await axios.get(`${API_URL}/api/sales-register/productwise`, { params: buildParams() });
        setProductwise(res.data?.data || []);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [fromDate, toDate, locationID, customerType, paymentMethod]);

    const loadSupplierwise = useCallback(async () => {
        const res = await axios.get(`${API_URL}/api/sales-register/supplierwise`, { params: buildParams() });
        setSupplierwise(res.data?.data || []);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [fromDate, toDate, locationID, customerType, paymentMethod]);

    const loadDepartmentwise = useCallback(async () => {
        const res = await axios.get(`${API_URL}/api/sales-register/departmentwise`, { params: buildParams() });
        setDepartmentwise(res.data?.data || []);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [fromDate, toDate, locationID, customerType, paymentMethod]);

    const loadDailyTrend = useCallback(async () => {
        const res = await axios.get(`${API_URL}/api/sales-register/daily-trend`, { params: buildParams() });
        setDailyTrend(res.data?.data || []);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [fromDate, toDate, locationID, customerType, paymentMethod]);

    const loadAll = useCallback(async () => {
        setLoading(true);
        setError("");
        try {
            await Promise.all([
                loadSummary(),
                loadBillwise(),
                loadProductwise(),
                loadSupplierwise(),
                loadDepartmentwise(),
                loadDailyTrend()
            ]);
        } catch (err) {
            console.error("Sales register load error:", err);
            setError(err.response?.data?.message || err.message || "Failed to load sales register");
        } finally {
            setLoading(false);
        }
    }, [loadSummary, loadBillwise, loadProductwise, loadSupplierwise, loadDepartmentwise, loadDailyTrend]);

    useEffect(() => { loadAll(); }, [loadAll]);

    /* =====================================================
       EXPORT TO CSV
    ===================================================== */

    const exportCSV = () => {
        const rows = [];

        const addTitle = (title) => rows.push([title]);

        const addHeader = (headers) => rows.push(headers);

        const addRow = (values) => rows.push(values);

        addTitle(`Sales Register — ${fromDate} to ${toDate}`);
        addTitle("");

        addTitle("Summary");
        addHeader(["Total Sales", "Customer Returns", "Net Sales", "Net Profit", "Items Sold", "Invoices", "Avg Invoice"]);
        addRow([
            summary.totalSales, summary.customerReturns, summary.netSales,
            summary.netProfit, summary.itemsSold, summary.invoiceCount, summary.avgInvoice
        ]);
        addTitle("");

        addTitle("Bill-wise");
        addHeader(["Receipt", "Date", "Customer", "Cashier", "Qty", "Gross", "Net", "Discount", "Cost", "Profit"]);
        billwise.forEach((b) => addRow([
            b.Receipt, b.SaleDate, b.CustomerName, b.Cashier,
            b.Qty, b.GrossAmount, b.NetAmount, b.LineDiscount, b.CostAmount, b.Profit
        ]));
        addTitle("");

        addTitle("Product-wise");
        addHeader(["Product Code", "Product Name", "Bills", "Qty", "Gross", "Net", "Discount", "Cost", "Profit"]);
        productwise.forEach((p) => addRow([
            p.ProductCode, p.ProductName, p.BillsCount, p.Qty,
            p.GrossAmount, p.NetAmount, p.LineDiscount, p.CostAmount, p.Profit
        ]));
        addTitle("");

        addTitle("Supplier-wise");
        addHeader(["Supplier", "Bills", "Products", "Qty", "Gross", "Net", "Profit"]);
        supplierwise.forEach((s) => addRow([
            s.SupplierName, s.BillsCount, s.ProductsCount, s.Qty,
            s.GrossAmount, s.NetAmount, s.Profit
        ]));
        addTitle("");

        addTitle("Department-wise");
        addHeader(["Department", "Bills", "Products", "Qty", "Gross", "Net", "Profit"]);
        departmentwise.forEach((d) => addRow([
            d.DepartmentName, d.BillsCount, d.ProductsCount, d.Qty,
            d.GrossAmount, d.NetAmount, d.Profit
        ]));

        const csv = rows
            .map((r) => r.map((cell) => {
                const s = String(cell ?? "");
                return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
            }).join(","))
            .join("\n");

        const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = `sales-register-${fromDate}-to-${toDate}.csv`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    };

    /* =====================================================
       DERIVED
    ===================================================== */

    const profitMargin = useMemo(() => {
        if (!summary.netSales || summary.netSales <= 0) return 0;
        return (summary.netProfit / summary.netSales) * 100;
    }, [summary]);

    const maxTrend = useMemo(() => {
        if (!dailyTrend.length) return 1;
        return Math.max(...dailyTrend.map((d) => Number(d.GrossAmount || 0)), 1);
    }, [dailyTrend]);

    /* =====================================================
       RENDER
    ===================================================== */

    return (
        <div className="min-h-screen p-5" style={{ background: "#FAF7F0" }}>
            <div className="max-w-[1400px] mx-auto">

                {/* HEADER */}
                <div className="flex flex-wrap items-center justify-between gap-3 mb-5">
                    <div>
                        <h1 className="text-3xl font-bold text-gray-900">
                            Sales Register
                        </h1>
                        <p className="text-sm text-gray-500 mt-1">
                            Bill-wise, product, supplier and department sales
                        </p>
                    </div>

                    <div className="flex items-center gap-2">
                        <button
                            type="button"
                            onClick={loadAll}
                            disabled={loading}
                            className="flex items-center gap-2 px-4 py-2 rounded-lg bg-white border border-gray-200 text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:opacity-50"
                        >
                            {loading ? <Loader2 size={16} className="animate-spin" /> : <RefreshCw size={16} />}
                            Refresh
                        </button>
                        <button
                            type="button"
                            onClick={exportCSV}
                            className="flex items-center gap-2 px-4 py-2 rounded-lg bg-white border border-gray-200 text-sm font-medium text-gray-700 hover:bg-gray-50"
                        >
                            <Download size={16} />
                            Export
                        </button>
                    </div>
                </div>

                {/* ERROR */}
                {error && (
                    <div className="mb-5 px-4 py-3 rounded-xl bg-red-50 border border-red-200 text-sm text-red-700">
                        {error}
                    </div>
                )}

                {/* FILTERS */}
                <div className="rounded-2xl bg-white border border-gray-200 shadow-sm p-5 mb-5">
                    <h2 className="text-base font-bold text-gray-900 mb-4">Filters</h2>

                    <div className="grid grid-cols-1 md:grid-cols-4 gap-5">
                        {/* DATE RANGE */}
                        <div className="md:col-span-2">
                            <label className="block text-xs font-semibold text-gray-600 mb-2">Date Range</label>
                            <div className="flex gap-1 mb-2">
                                {[
                                    { key: "today", label: "Today" },
                                    { key: "3days", label: "3 Days" },
                                    { key: "7days", label: "7 Days" }
                                ].map((opt) => (
                                    <button
                                        key={opt.key}
                                        type="button"
                                        onClick={() => applyQuickRange(opt.key)}
                                        className={`px-3 py-1.5 rounded-full text-xs font-semibold transition-colors ${
                                            quickRange === opt.key
                                                ? "bg-amber-500 text-white"
                                                : "bg-gray-100 text-gray-600 hover:bg-gray-200"
                                        }`}
                                    >
                                        {opt.label}
                                    </button>
                                ))}
                            </div>
                            <div className="flex items-center gap-2">
                                <Calendar size={16} className="text-gray-400" />
                                <input
                                    type="date"
                                    value={fromDate}
                                    onChange={(e) => { setFromDate(e.target.value); setQuickRange("custom"); }}
                                    className="flex-1 h-9 rounded-lg border border-gray-200 bg-white px-3 text-sm outline-none focus:ring-2 focus:ring-amber-200"
                                />
                                <span className="text-gray-400 text-sm">–</span>
                                <input
                                    type="date"
                                    value={toDate}
                                    onChange={(e) => { setToDate(e.target.value); setQuickRange("custom"); }}
                                    className="flex-1 h-9 rounded-lg border border-gray-200 bg-white px-3 text-sm outline-none focus:ring-2 focus:ring-amber-200"
                                />
                            </div>
                        </div>

                        {/* LOCATION */}
                        <div>
                            <label className="block text-xs font-semibold text-gray-600 mb-2">Location</label>
                            <select
                                value={locationID}
                                onChange={(e) => setLocationID(e.target.value)}
                                className="w-full h-9 rounded-lg border border-gray-200 bg-white px-3 text-sm outline-none focus:ring-2 focus:ring-amber-200"
                            >
                                <option value="">All Locations</option>
                                {locations.map((loc) => (
                                    <option key={loc.LocationID} value={loc.LocationID}>
                                        {loc.LocationName}
                                    </option>
                                ))}
                                {!locations.length && userLocationID > 0 && (
                                    <option value={userLocationID}>My Location ({userLocationID})</option>
                                )}
                            </select>
                        </div>

                        {/* CUSTOMER TYPE */}
                        <div>
                            <label className="block text-xs font-semibold text-gray-600 mb-2">Customer Type</label>
                            <select
                                value={customerType}
                                onChange={(e) => setCustomerType(e.target.value)}
                                className="w-full h-9 rounded-lg border border-gray-200 bg-white px-3 text-sm outline-none focus:ring-2 focus:ring-amber-200"
                            >
                                {CUSTOMER_TYPES.map((c) => (
                                    <option key={c.value} value={c.value}>{c.label}</option>
                                ))}
                            </select>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-4 gap-5 mt-4">
                        {/* PAYMENT METHOD */}
                        <div>
                            <label className="block text-xs font-semibold text-gray-600 mb-2">Payment Method</label>
                            <select
                                value={paymentMethod}
                                onChange={(e) => setPaymentMethod(e.target.value)}
                                className="w-full h-9 rounded-lg border border-gray-200 bg-white px-3 text-sm outline-none focus:ring-2 focus:ring-amber-200"
                            >
                                {PAYMENT_METHODS.map((p) => (
                                    <option key={p.value} value={p.value}>{p.label}</option>
                                ))}
                            </select>
                        </div>
                    </div>
                </div>

                {/* SUMMARY CARDS */}
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-3 mb-5">
                    <SummaryCard
                        title="Total Sales"
                        value={`Rs.${formatMoney(summary.totalSales)}`}
                        sub={`${formatInt(summary.invoiceCount)} invoices`}
                        icon={<DollarSign size={16} />}
                        iconColor="text-gray-500"
                    />
                    <SummaryCard
                        title="Customer Returns"
                        value={`Rs.${formatMoney(summary.customerReturns)}`}
                        sub="0.00 items returned"
                        valueClass="text-red-500"
                        icon={<RefreshCw size={16} />}
                        iconColor="text-red-400"
                    />
                    <SummaryCard
                        title="Net Sales"
                        value={`Rs.${formatMoney(summary.netSales)}`}
                        sub="Sales – returns"
                        icon={<DollarSign size={16} />}
                        iconColor="text-amber-500"
                        highlight
                    />
                    <SummaryCard
                        title="Net Profit"
                        value={`Rs.${formatMoney(summary.netProfit)}`}
                        sub={`${profitMargin.toFixed(2)}% margin`}
                        subClass="text-green-600"
                        icon={<TrendingUp size={16} />}
                        iconColor="text-gray-500"
                    />
                    <SummaryCard
                        title="Items Sold"
                        value={formatNumber(summary.itemsSold)}
                        sub="Total quantity"
                        icon={<Package size={16} />}
                        iconColor="text-gray-500"
                    />
                    <SummaryCard
                        title="Avg per Invoice"
                        value={`Rs.${formatMoney(summary.avgInvoice)}`}
                        sub="Net average value"
                        icon={<FileText size={16} />}
                        iconColor="text-gray-500"
                    />
                </div>

                {/* DAILY SALES TREND */}
                {dailyTrend.length > 0 && (
                    <div className="rounded-2xl bg-white border border-gray-200 shadow-sm p-5 mb-5">
                        <h2 className="text-lg font-bold text-gray-900 mb-4">Daily Sales Trend</h2>
                        <div className="flex items-end gap-3 h-52 border-l border-b border-dashed border-gray-200 pl-3 pb-3">
                            {dailyTrend.map((d) => {
                                const heightPct = (Number(d.GrossAmount || 0) / maxTrend) * 100;
                                return (
                                    <div key={String(d.SaleDate)} className="flex-1 flex flex-col items-center justify-end h-full">
                                        <div
                                            className="w-full rounded-t-md bg-amber-500 hover:bg-amber-600 transition-all"
                                            style={{ height: `${Math.max(4, heightPct)}%` }}
                                            title={`Rs.${formatMoney(d.GrossAmount)}`}
                                        />
                                        <div className="text-[10px] text-gray-500 mt-1">
                                            {new Date(d.SaleDate).toLocaleDateString("en-US", {
                                                month: "short", day: "2-digit"
                                            })}
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                )}

                {/* TABS */}
                <div className="rounded-t-2xl bg-white border border-gray-200 border-b-0 shadow-sm px-3 pt-3 overflow-x-auto">
                    <div className="flex items-center gap-1 min-w-max">
                        {TABS.map((tab) => (
                            <button
                                key={tab.key}
                                type="button"
                                onClick={() => setActiveTab(tab.key)}
                                className={`px-4 py-2 rounded-t-lg text-sm font-semibold transition-colors ${
                                    activeTab === tab.key
                                        ? "bg-amber-50 text-amber-700 border border-amber-200 border-b-white"
                                        : "text-gray-600 hover:text-gray-900 hover:bg-gray-50"
                                }`}
                            >
                                {tab.label}
                            </button>
                        ))}
                    </div>
                </div>

                {/* TAB CONTENT */}
                <div className="rounded-b-2xl bg-white border border-gray-200 shadow-sm p-5">
                    {loading && (
                        <div className="flex items-center justify-center py-16 text-gray-500">
                            <Loader2 size={22} className="animate-spin mr-2" />
                            Loading data…
                        </div>
                    )}

                    {!loading && activeTab === "billwise" && (
                        <BillwiseTable
                            rows={billwise}
                            expandedBill={expandedBill}
                            setExpandedBill={setExpandedBill}
                        />
                    )}

                    {!loading && activeTab === "productwise" && (
                        <ProductwiseTable rows={productwise} />
                    )}

                    {!loading && activeTab === "supplierwise" && (
                        <SupplierwiseTable rows={supplierwise} />
                    )}

                    {!loading && activeTab === "departmentwise" && (
                        <DepartmentwiseTable rows={departmentwise} />
                    )}
                </div>
            </div>
        </div>
    );
}

/* =========================================================
   SUMMARY CARD
========================================================= */

function SummaryCard({ title, value, sub, subClass = "", valueClass = "", icon, iconColor, highlight }) {
    return (
        <div
            className={`rounded-2xl bg-white border shadow-sm p-4 ${
                highlight ? "border-amber-300" : "border-gray-200"
            }`}
        >
            <div className="flex items-center justify-between mb-2">
                <span className="text-xs font-semibold text-gray-600">{title}</span>
                <span className={iconColor}>{icon}</span>
            </div>
            <div className={`text-xl font-bold ${valueClass || "text-gray-900"}`}>{value}</div>
            <div className={`text-xs mt-1 ${subClass || "text-gray-500"}`}>{sub}</div>
        </div>
    );
}

/* =========================================================
   BILL-WISE TABLE
========================================================= */

function BillwiseTable({ rows, expandedBill, setExpandedBill }) {
    if (!rows.length) {
        return <EmptyState message="No bills found for the selected filters" />;
    }

    return (
        <div className="overflow-x-auto">
            <table className="w-full">
                <thead>
                    <tr className="border-b border-gray-200 bg-gray-50">
                        <Th className="w-10"></Th>
                        <Th>Receipt</Th>
                        <Th>Date</Th>
                        <Th>Customer</Th>
                        <Th>Cashier</Th>
                        <Th align="right">Qty</Th>
                        <Th align="right">Gross</Th>
                        <Th align="right">Discount</Th>
                        <Th align="right">Net</Th>
                        <Th align="right">Cost</Th>
                        <Th align="right">Profit</Th>
                    </tr>
                </thead>
                <tbody>
                    {rows.map((b) => {
                        const expanded = expandedBill === b.Receipt;
                        return (
                            <React.Fragment key={b.Receipt}>
                                <tr
                                    className="border-b border-gray-100 hover:bg-amber-50/40 cursor-pointer"
                                    onClick={() => setExpandedBill(expanded ? null : b.Receipt)}
                                >
                                    <Td className="text-gray-400">
                                        {expanded ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
                                    </Td>
                                    <Td className="font-semibold text-gray-900">{b.Receipt}</Td>
                                    <Td>{new Date(b.SaleDate).toLocaleString()}</Td>
                                    <Td>{b.CustomerName || "—"}</Td>
                                    <Td>{b.Cashier || "—"}</Td>
                                    <Td align="right">{formatNumber(b.Qty)}</Td>
                                    <Td align="right">{formatMoney(b.GrossAmount)}</Td>
                                    <Td align="right" className="text-amber-700">
                                        {formatMoney(b.LineDiscount)}
                                    </Td>
                                    <Td align="right" className="font-semibold">
                                        {formatMoney(b.NetAmount)}
                                    </Td>
                                    <Td align="right" className="text-gray-500">
                                        {formatMoney(b.CostAmount)}
                                    </Td>
                                    <Td align="right" className="font-semibold text-green-600">
                                        {formatMoney(b.Profit)}
                                    </Td>
                                </tr>
                                {expanded && (
                                    <tr className="bg-amber-50/50">
                                        <td colSpan={11} className="px-4 py-3">
                                            <div className="text-xs font-semibold text-gray-600 mb-2">
                                                Lines in receipt {b.Receipt}
                                            </div>
                                            <BillLines receipt={b.Receipt} />
                                        </td>
                                    </tr>
                                )}
                            </React.Fragment>
                        );
                    })}
                </tbody>
            </table>
        </div>
    );
}

function BillLines({ receipt }) {
    const [lines, setLines] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        (async () => {
            try {
                setLoading(true);
                const res = await axios.get(`${API_URL}/api/sales-register/billwise/lines`, {
                    params: { receipt }
                });
                setLines(res.data?.data || []);
            } catch {
                setLines([]);
            } finally {
                setLoading(false);
            }
        })();
    }, [receipt]);

    if (loading) {
        return <div className="text-xs text-gray-500 flex items-center gap-2"><Loader2 size={14} className="animate-spin" /> Loading lines…</div>;
    }
    if (!lines.length) {
        return <div className="text-xs text-gray-500">No line detail available.</div>;
    }

    return (
        <table className="w-full text-xs">
            <thead>
                <tr className="text-gray-500 border-b border-amber-200">
                    <th className="text-left py-1">Code</th>
                    <th className="text-left py-1">Product</th>
                    <th className="text-right py-1">Qty</th>
                    <th className="text-right py-1">Gross</th>
                    <th className="text-right py-1">Disc %</th>
                    <th className="text-right py-1">Disc Amt</th>
                    <th className="text-right py-1">Net</th>
                </tr>
            </thead>
            <tbody>
                {lines.map((l, i) => (
                    <tr key={i} className="border-b border-amber-100/50">
                        <td className="py-1">{l.ProductCode}</td>
                        <td className="py-1">{l.Descrip}</td>
                        <td className="py-1 text-right">{formatNumber(l.Qty)}</td>
                        <td className="py-1 text-right">{formatMoney(l.Amount)}</td>
                        <td className="py-1 text-right">{formatNumber(l.FixedDiscountPercentage)}</td>
                        <td className="py-1 text-right">{formatMoney(l.FixedDiscount)}</td>
                        <td className="py-1 text-right font-semibold">{formatMoney(l.Nett)}</td>
                    </tr>
                ))}
            </tbody>
        </table>
    );
}

