/* =========================================================
   SMALL UI PRIMITIVES
========================================================= */

function Th({ children, align = "left", className = "" }) {
    return (
        <th className={`px-3 py-3 text-xs font-semibold text-gray-600 uppercase tracking-wide text-${align} ${className}`}>
            {children}
        </th>
    );
}

function Td({ children, align = "left", className = "" }) {
    return (
        <td className={`px-3 py-3 text-sm text-gray-700 text-${align} ${className}`}>
            {children}
        </td>
    );
}

function EmptyState({ message }) {
    return (
        <div className="py-16 text-center text-sm text-gray-400">
            <BarChart3 size={40} className="mx-auto mb-3 opacity-40" />
            {message}
        </div>
    );
}