import React, { useEffect, useMemo, useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import {
  Plus,
  ArrowLeftRight,
  Building2,
  Calendar,
  Printer,
  Download,
  Bell,
  Filter,
  FileText,
  DollarSign,
  TrendingUp,
  TrendingDown,
  Search,
  X,
  RefreshCw,
  CheckCircle,
  AlertCircle,
} from "lucide-react";

const API = "http://localhost:5000/api";

export default function CashOnHand() {

  /* =====================================================
     STATE
  ===================================================== */

  const [accounts, setAccounts] = useState([]);

  const [transactions, setTransactions] = useState([]);

  const [loading, setLoading] = useState(false);

  const [error, setError] = useState("");

  const [selectedAccount, setSelectedAccount] = useState("");

  const [fromDate, setFromDate] = useState(
    getDateBefore(7)
  );

  const [toDate, setToDate] = useState(
    getToday()
  );

  const [filterType, setFilterType] =
    useState("All Transactions");

  const [activeTab, setActiveTab] =
    useState("statement");

  const [showExpense, setShowExpense] =
    useState(false);

  const [showTransfer, setShowTransfer] =
    useState(false);

  const [showSupplier, setShowSupplier] =
    useState(false);

  const [message, setMessage] =
    useState("");

  const [messageType, setMessageType] =
    useState("success");

  const navigate = useNavigate();

  /* =====================================================
     EXPENSE ACCOUNTS
  ===================================================== */

  const [expenseAccounts, setExpenseAccounts] =
    useState([]);


  /* =====================================================
     FORM STATE
  ===================================================== */

  const [expenseForm, setExpenseForm] =
    useState({
      AccountId: "",
      fAccountId: "",
      amount: "",
      description: "",
      referenceNo: "",
    });


  const [transferForm, setTransferForm] =
    useState({
      fromAccountId: "",
      toAccountId: "",
      amount: "",
      description: "",
      referenceNo: "",
    });


  const [supplierForm, setSupplierForm] =
    useState({
      amount: "",
      supplierName: "",
      description: "",
      referenceNo: "",
    });


  /* =====================================================
     LOAD EXPENSE ACCOUNTS
  ===================================================== */

  async function loadExpenseAccounts() {

    try {

      const response = await axios.get(
        `${API}/acc`
      );

      const data =
        Array.isArray(response.data?.data)
          ? response.data.data
          : [];

      setExpenseAccounts(data);

    } catch (err) {

      console.error(
        "loadExpenseAccounts error:",
        err
      );

      setExpenseAccounts([]);

      setError(
        err.response?.data?.message ||
        "Unable to load expense accounts."
      );

    }

  }


  /* =====================================================
     SELECTED ACCOUNT
  ===================================================== */

  const selectedAccountData =
    accounts.find(
      (account) =>
        String(
          account.AccountID ??
          account.id
        ) ===
        String(selectedAccount)
    );


  /* =====================================================
     SUMMARY
     -----------------------------------------------------
     - openingBalance: from API if provided, else
                       storedBalance − period movement
     - balance:        real "as of now" balance — uses the
                       account's stored balance when the API
                       exposes one, otherwise falls back to
                       openingBalance + netMovement so the
                       card always reconciles with the table.
  ===================================================== */

  const summary = useMemo(() => {

    const credits = transactions.reduce(
      (total, item) =>
        total + Number(item.Credit || 0),
      0
    );

    const debits = transactions.reduce(
      (total, item) =>
        total + Number(item.Debit || 0),
      0
    );

    const netMovement = credits - debits;

    // Prefer a backend-provided opening balance if present
    const apiOpening = Number(
      selectedAccountData?.OpeningBalance ??
      selectedAccountData?.openingBalance ??
      NaN
    );

    // Did the API actually give us a stored balance?
    const hasStored =
      selectedAccountData?.HasStoredBalance === true;

    const storedBalance = Number(
      selectedAccountData?.StoredBalance ?? 0
    );

    // Derive opening balance:
    //   - from the API when supplied, OR
    //   - back-computed from stored balance − period movement
    const openingBalance = Number.isFinite(apiOpening)
      ? apiOpening
      : storedBalance - netMovement;

    // Current balance:
    //   * stored balance when the API provides one (DB truth)
    //   * otherwise openingBalance + netMovement so the card
    //     stays in sync with the last row of the table
    const currentBalance = hasStored
      ? storedBalance
      : openingBalance + netMovement;

    return {
      credits,
      debits,
      netMovement,
      openingBalance,
      balance: currentBalance,
      calculatedBalance: openingBalance + netMovement,
      count: transactions.length,
    };

  }, [transactions, selectedAccountData]);


  /* =====================================================
     LOAD ACCOUNTS + EXPENSE ACCOUNTS ON MOUNT
  ===================================================== */

  useEffect(() => {

    loadAccounts();

    loadExpenseAccounts();

  }, []);


  /* =====================================================
     RELOAD TRANSACTIONS WHEN FILTERS CHANGE
  ===================================================== */

  useEffect(() => {

    if (selectedAccount) {

      loadTransactions();

    }

  }, [
    selectedAccount,
    fromDate,
    toDate,
    filterType,
  ]);


  /* =====================================================
     LOAD ACCOUNTS
     -----------------------------------------------------
     * Normalises the payload so AccountID / AccountName /
       StoredBalance are always present.
     * Preserves the current selection on refresh; only
       auto-selects the first account on initial load.
  ===================================================== */

  async function loadAccounts() {

    try {

      setError("");

      const response =
        await axios.get(
          `${API}/accounts`
        );

      const rawData =
        response.data?.accounts ??
        response.data?.data ??
        [];

      const data =
        Array.isArray(rawData)
          ? rawData
          : [];

      // Normalise so StoredBalance is always available
      const normalized = data.map((raw) => {

        const hasStored =
          raw.StoredBalance !== undefined ||
          raw.storedBalance !== undefined ||
          raw.balance !== undefined;

        return {
          ...raw,
          AccountID: raw.AccountID ?? raw.id ?? null,
          AccountName:
            raw.AccountName ?? raw.name ?? "",
          StoredBalance: Number(
            raw.StoredBalance ??
            raw.storedBalance ??
            raw.balance ??
            0
          ),
          HasStoredBalance: hasStored,
        };

      });

      setAccounts(normalized);

      // Preserve selection on refresh; auto-select only once.
      setSelectedAccount((prev) => {

        const stillExists = normalized.some(
          (a) =>
            String(a.AccountID) === String(prev)
        );

        if (prev && stillExists) {
          return prev;
        }

        return normalized.length > 0
          ? String(normalized[0].AccountID)
          : "";

      });

    } catch (err) {

      console.error(
        "loadAccounts error:",
        err
      );

      setAccounts([]);

      setSelectedAccount("");

      setError(
        err.response?.data?.message ||
        "Unable to load cash accounts."
      );

    }

  }


  /* =====================================================
     LOAD TRANSACTIONS
  ===================================================== */

  async function loadTransactions() {

    if (!selectedAccount) {

      setTransactions([]);

      return;

    }


    try {

      setLoading(true);

      setError("");


      const response =
        await axios.get(
          `${API}/cash-transactions`,
          {
            params: {
              accountId:
                selectedAccount,

              fromDate,

              toDate,

              type:
                filterType,
            },
          }
        );


      setTransactions(
        Array.isArray(response.data?.data)
          ? response.data.data
          : []
      );


    } catch (err) {

      console.error(
        "loadTransactions error:",
        err
      );

      setError(
        err.response?.data?.message ||
        "Unable to load transactions."
      );

      setTransactions([]);

    } finally {

      setLoading(false);

    }

  }


  /* =====================================================
     REFRESH AFTER MUTATION
     -----------------------------------------------------
     Re-fetch accounts (so StoredBalance reflects the new
     DB state) AND the ledger rows — keeps the Current
     Balance card and the table in sync.
  ===================================================== */

  async function refreshAfterMutation() {

    await Promise.all([
      loadAccounts(),
      loadTransactions(),
    ]);

  }


  /* =====================================================
     ADD EXPENSE
  ===================================================== */

  async function saveExpense(e) {

    e.preventDefault();


    if (!expenseForm.AccountId) {

      showMessage(
        "Please select an expense account.",
        "error"
      );

      return;

    }


    if (
      !expenseForm.amount ||
      Number(expenseForm.amount) <= 0
    ) {

      showMessage(
        "Please enter a valid amount.",
        "error"
      );

      return;

    }


    try {

      setLoading(true);


      const response =
        await axios.post(
          `${API}/cash-transactions/expense`,
          {

            accountId:
              expenseForm.AccountId,

            faccountId:
              expenseForm.fAccountId,

            amount:
              Number(expenseForm.amount),

            description:
              expenseForm.description,

            referenceNo:
              expenseForm.referenceNo,

            createdBy:
              "Admin",
          }
        );


      if (response.data.success) {

        showMessage(
          "Expense saved successfully",
          "success"
        );


        setExpenseForm({
          AccountId: "",
          fAccountId: "",
          amount: "",
          description: "",
          referenceNo: "",
        });


        setShowExpense(false);


        await refreshAfterMutation();

      } else {

        showMessage(
          response.data.message ||
          "Unable to save expense",
          "error"
        );

      }


    } catch (err) {

      console.error(
        "saveExpense error:",
        err
      );

      showMessage(
        err.response?.data?.message ||
        "Unable to save expense",
        "error"
      );

    } finally {

      setLoading(false);

    }

  }


  /* =====================================================
     ADD TRANSFER
  ===================================================== */

  async function saveTransfer(e) {

    e.preventDefault();


    if (
      !transferForm.fromAccountId ||
      !transferForm.toAccountId
    ) {

      showMessage(
        "Please select both accounts.",
        "error"
      );

      return;

    }


    if (
      String(
        transferForm.fromAccountId
      ) ===
      String(
        transferForm.toAccountId
      )
    ) {

      showMessage(
        "From Account and To Account cannot be the same.",
        "error"
      );

      return;

    }


    if (
      !transferForm.amount ||
      Number(transferForm.amount) <= 0
    ) {

      showMessage(
        "Please enter a valid amount.",
        "error"
      );

      return;

    }


    try {

      setLoading(true);


      const response =
        await axios.post(
          `${API}/cash-transactions/transfer`,
          {
            fromAccountId:
              transferForm.fromAccountId,

            toAccountId:
              transferForm.toAccountId,

            amount:
              Number(transferForm.amount),

            description:
              transferForm.description,

            referenceNo:
              transferForm.referenceNo,

            locationId:
              null,

            sessionId:
              null,

            createdBy:
              "Admin",
          }
        );


      if (response.data.success) {

        showMessage(
          "Transfer completed successfully",
          "success"
        );


        setTransferForm({
          fromAccountId: "",
          toAccountId: "",
          amount: "",
          description: "",
          referenceNo: "",
        });


        setShowTransfer(false);


        await refreshAfterMutation();

      } else {

        showMessage(
          response.data.message ||
          "Unable to complete transfer",
          "error"
        );

      }


    } catch (err) {

      console.error(
        "saveTransfer error:",
        err
      );

      showMessage(
        err.response?.data?.message ||
        "Unable to complete transfer",
        "error"
      );

    } finally {

      setLoading(false);

    }

  }


  /* =====================================================
     SUPPLIER PAYMENT
  ===================================================== */

  async function saveSupplierPayment(e) {

    e.preventDefault();


    if (
      !supplierForm.supplierName
    ) {

      showMessage(
        "Supplier name is required.",
        "error"
      );

      return;

    }


    if (
      !supplierForm.amount ||
      Number(supplierForm.amount) <= 0
    ) {

      showMessage(
        "Please enter a valid amount.",
        "error"
      );

      return;

    }


    try {

      setLoading(true);


      const response =
        await axios.post(
          `${API}/cash-transactions/supplier-payment`,
          {
            accountId:
              selectedAccount,

            amount:
              Number(supplierForm.amount),

            supplierName:
              supplierForm.supplierName,

            description:
              supplierForm.description,

            referenceNo:
              supplierForm.referenceNo,

            locationId:
              null,

            sessionId:
              null,

            createdBy:
              "Admin",
          }
        );


      if (response.data.success) {

        showMessage(
          "Supplier payment saved successfully",
          "success"
        );


        setSupplierForm({
          amount: "",
          supplierName: "",
          description: "",
          referenceNo: "",
        });


        setShowSupplier(false);


        await refreshAfterMutation();

      } else {

        showMessage(
          response.data.message ||
          "Unable to save supplier payment",
          "error"
        );

      }


    } catch (err) {

      console.error(
        "saveSupplierPayment error:",
        err
      );

      showMessage(
        err.response?.data?.message ||
        "Unable to save supplier payment",
        "error"
      );

    } finally {

      setLoading(false);

    }

  }


  /* =====================================================
     MESSAGE
  ===================================================== */

  function showMessage(text, type) {

    setMessage(text);

    setMessageType(type);


    setTimeout(() => {

      setMessage("");

    }, 4000);

  }


  /* =====================================================
     TODAY
  ===================================================== */

  function setToday() {

    setFromDate(
      getToday()
    );

    setToDate(
      getToday()
    );

  }


  /* =====================================================
     PRINT
  ===================================================== */

  function printReport() {

    window.print();

  }


  /* =====================================================
     CSV EXPORT
     -----------------------------------------------------
     Computes running balance client-side so the exported
     file reconciles with the on-screen table.
  ===================================================== */

  function exportCSV() {

    if (!transactions.length) {

      showMessage(
        "No transactions to export.",
        "error"
      );

      return;

    }


    const headers = [
      "Date",
      "Type",
      "Description",
      "Debit",
      "Credit",
      "Balance",
      "Reference",
    ];


    let runningBalance = Number(
      summary.openingBalance || 0
    );


    const rows =
      transactions.map((item) => {

        const debit = Number(item.Debit || 0);
        const credit = Number(item.Credit || 0);

        runningBalance += credit - debit;

        return [

          formatDateTime(
            item.TransactionDate
          ),

          item.TransactionType || "",

          item.Description || "",

          debit.toFixed(2),

          credit.toFixed(2),

          runningBalance.toFixed(2),

          item.ReferenceNo || "",

        ];

      });


    const csv = [

      headers,

      ...rows,

    ]
      .map((row) =>
        row
          .map((value) =>
            `"${String(value)
              .replace(/"/g, '""')}"`
          )
          .join(",")
      )
      .join("\n");


    const blob =
      new Blob(
        [csv],
        {
          type:
            "text/csv;charset=utf-8;",
        }
      );


    const url =
      URL.createObjectURL(blob);


    const link =
      document.createElement("a");


    link.href = url;


    link.download =
      `cash-statement-${fromDate}-${toDate}.csv`;


    link.click();


    URL.revokeObjectURL(url);

  }


  /* =====================================================
     OPEN EXPENSE MODAL
  ===================================================== */

  function openExpenseModal() {

    setExpenseForm({
      AccountId: "",
      fAccountId: "",
      amount: "",
      description: "",
      referenceNo: "",
    });

    setShowExpense(true);

  }


  /* =====================================================
     RENDER
  ===================================================== */

  return (

    <div className="min-h-screen bg-white text-slate-900">


      {/* =================================================
          HEADER
      ================================================= */}

      <div className="px-7 pt-7">

        <div className="flex flex-col gap-5 lg:flex-row lg:items-center lg:justify-between">

          <div>

            <h1 className="text-3xl font-bold">
              Cash on Hand
            </h1>

            <p className="mt-1 text-slate-500">
              View detailed cash on hand
              account statements
            </p>

          </div>


          <div className="flex flex-wrap gap-2">


            {/* ADD EXPENSE */}

            <button
              onClick={openExpenseModal}
              className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-medium shadow-sm hover:bg-slate-50"
            >

              <Plus size={17} />

              Add Expense

            </button>


            {/* ADD TRANSFER */}

            <button
              onClick={() =>
                setShowTransfer(true)
              }
              className="flex items-center gap-2 rounded-xl bg-amber-500 px-4 py-2.5 text-sm font-semibold text-white shadow-sm hover:bg-amber-600"
            >

              <ArrowLeftRight size={17} />

              Add Transfer

            </button>


            {/* SUPPLIER PAYMENT — navigates to its own page */}

            <button
              onClick={() =>
                navigate("/supplier-payment")
              }
              className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-medium shadow-sm hover:bg-slate-50"
            >

              <Building2 size={17} />

              Supplier Payment

            </button>


            {/* TODAY */}

            <button
              onClick={setToday}
              className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-medium shadow-sm hover:bg-slate-50"
            >

              <Calendar size={17} />

              Today

            </button>


            {/* PRINT */}

            <button
              onClick={printReport}
              className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-medium shadow-sm hover:bg-slate-50"
            >

              <Printer size={17} />

              Print Report

            </button>


            {/* CSV */}

            <button
              onClick={exportCSV}
              className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-medium shadow-sm hover:bg-slate-50"
            >

              <Download size={17} />

              Export CSV

            </button>


            {/* PRICE UPDATES */}

            <button
              className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-medium shadow-sm hover:bg-slate-50"
            >

              <Bell size={17} />

              Price Updates

            </button>

          </div>

        </div>


        {/* =================================================
            TABS
        ================================================= */}

        <div className="mt-6 flex w-fit rounded-xl bg-slate-100 p-1">

          <button
            onClick={() =>
              setActiveTab("statement")
            }
            className={`rounded-lg px-5 py-2 text-sm font-medium ${
              activeTab === "statement"
                ? "bg-white shadow-sm"
                : "text-slate-500"
            }`}
          >

            Statement

          </button>


          <button
            onClick={() =>
              setActiveTab("summary")
            }
            className={`rounded-lg px-5 py-2 text-sm font-medium ${
              activeTab === "summary"
                ? "bg-white shadow-sm"
                : "text-slate-500"
            }`}
          >

            Summary

          </button>

        </div>

      </div>


      {/* =================================================
          MESSAGE
      ================================================= */}

      {message && (

        <div className="mx-7 mt-5">

          <div
            className={`flex items-center gap-3 rounded-xl border px-4 py-3 ${
              messageType === "success"
                ? "border-green-200 bg-green-50 text-green-700"
                : "border-red-200 bg-red-50 text-red-700"
            }`}
          >

            {messageType === "success"
              ? <CheckCircle size={18} />
              : <AlertCircle size={18} />
            }

            {message}

          </div>

        </div>

      )}


      {/* =================================================
          ERROR
      ================================================= */}

      {error && (

        <div className="mx-7 mt-5">

          <div className="flex items-center gap-3 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-red-700">

            <AlertCircle size={18} />

            {error}

          </div>

        </div>

      )}


      {/* =================================================
          FILTERS
      ================================================= */}

      <div className="mx-7 mt-6 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">

        <div className="mb-5 flex items-center gap-2">

          <Filter size={20} />

          <h2 className="text-xl font-semibold">
            Filters
          </h2>

        </div>


        <div className="grid grid-cols-1 gap-5 md:grid-cols-2 xl:grid-cols-4">


          {/* ACCOUNT */}

          <div>

            <label className="mb-2 block text-sm font-medium">
              Cash Account
            </label>


            <select
              value={selectedAccount}
              onChange={(e) =>
                setSelectedAccount(
                  e.target.value
                )
              }
              className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 outline-none focus:border-amber-500"
            >

              <option value="">
                Select Cash Account
              </option>


              {accounts.map((account) => {

                const accountId =
                  account.AccountID ??
                  account.id;

                const accountName =
                  account.AccountName ??
                  account.name ??
                  `Account ${accountId}`;

                return (

                  <option
                    key={accountId}
                    value={accountId}
                  >

                    {accountName}

                  </option>

                );

              })}

            </select>

          </div>


          {/* FROM */}

          <div>

            <label className="mb-2 block text-sm font-medium">
              From Date
            </label>


            <input
              type="date"
              value={fromDate}
              onChange={(e) =>
                setFromDate(
                  e.target.value
                )
              }
              className="w-full rounded-xl border border-slate-200 px-4 py-3 outline-none focus:border-amber-500"
            />

          </div>


          {/* TO */}

          <div>

            <label className="mb-2 block text-sm font-medium">
              To Date
            </label>


            <input
              type="date"
              value={toDate}
              onChange={(e) =>
                setToDate(
                  e.target.value
                )
              }
              className="w-full rounded-xl border border-slate-200 px-4 py-3 outline-none focus:border-amber-500"
            />

          </div>


          {/* TYPE */}

          <div>

            <label className="mb-2 block text-sm font-medium">
              Filter Type
            </label>


            <select
              value={filterType}
              onChange={(e) =>
                setFilterType(
                  e.target.value
                )
              }
              className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 outline-none focus:border-amber-500"
            >

              <option value="All Transactions">
                All Transactions
              </option>

              <option value="Expense">
                Expense
              </option>

              <option value="Transfer">
                Transfer
              </option>

              <option value="Supplier Payment">
                Supplier Payment
              </option>

            </select>

          </div>

        </div>

      </div>


      {/* =================================================
          SUMMARY CARDS
      ================================================= */}

      <div className="mx-7 mt-5 grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4">


        {/* Current Balance — uses stored/DB balance when available,
            otherwise falls back to openingBalance + netMovement */}
        <SummaryCard
          icon={
            <DollarSign size={20} />
          }
          title="Current Balance"
          value={summary.balance}
          className="text-blue-600"
        />


        <SummaryCard
          icon={
            <TrendingUp size={20} />
          }
          title="Total Credits"
          value={summary.credits}
          className="text-green-600"
        />


        <SummaryCard
          icon={
            <TrendingDown size={20} />
          }
          title="Total Debits"
          value={summary.debits}
          className="text-red-600"
        />


        <SummaryCard
          icon={
            <FileText size={20} />
          }
          title="Transactions"
          value={summary.count}
          number
          className="text-purple-600"
        />

      </div>


      {/* =================================================
          STATEMENT TAB
      ================================================= */}

      {activeTab === "statement" && (

        <div className="mx-7 mt-5 mb-10 rounded-2xl border border-slate-200 bg-white shadow-sm">


          {/* HEADER */}

          <div className="border-b border-slate-200 px-6 py-5">

            <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">

              <div className="flex items-center gap-3">

                <FileText
                  size={22}
                  className="text-slate-700"
                />


                <div>

                  <h2 className="text-xl font-semibold">

                    Statement

                    {selectedAccountData
                      ? ` - ${
                          selectedAccountData.AccountName ??
                          selectedAccountData.name ??
                          ""
                        }`
                      : ""}

                    {selectedAccountData?.AccountNumber
                      ? ` - ${
                          selectedAccountData.AccountNumber
                        }`
                      : ""}

                  </h2>


                  <p className="text-sm text-slate-500">

                    {fromDate}

                    {" → "}

                    {toDate}

                  </p>

                </div>

              </div>


              <button
                onClick={refreshAfterMutation}
                className="flex items-center justify-center gap-2 rounded-xl border border-slate-200 px-4 py-2 text-sm hover:bg-slate-50"
              >

                <RefreshCw
                  size={16}
                  className={
                    loading
                      ? "animate-spin"
                      : ""
                  }
                />

                Refresh

              </button>

            </div>

          </div>


          {/* TABLE */}

          <div className="overflow-x-auto">

            <table className="w-full min-w-[1000px] text-sm">

              <thead className="bg-slate-50">

                <tr>

                  <th className="px-5 py-4 text-left font-semibold text-slate-600">
                    Date
                  </th>

                  <th className="px-5 py-4 text-left font-semibold text-slate-600">
                    Type
                  </th>

                  <th className="px-5 py-4 text-left font-semibold text-slate-600">
                    Description
                  </th>

                  <th className="px-5 py-4 text-right font-semibold text-slate-600">
                    Amount
                  </th>

                  <th className="px-5 py-4 text-right font-semibold text-slate-600">
                    Balance
                  </th>

                  <th className="px-5 py-4 text-left font-semibold text-slate-600">
                    Reference
                  </th>

                </tr>

              </thead>


              <tbody>


                {/* LOADING */}

                {loading && (

                  <tr>

                    <td
                      colSpan="6"
                      className="py-12 text-center"
                    >

                      <RefreshCw
                        size={25}
                        className="mx-auto animate-spin text-amber-500"
                      />

                      <p className="mt-3 text-slate-500">
                        Loading transactions...
                      </p>

                    </td>

                  </tr>

                )}


                {/* EMPTY */}

                {!loading &&
                  transactions.length === 0 && (

                    <tr>

                      <td
                        colSpan="6"
                        className="py-12 text-center text-slate-500"
                      >

                        <Search
                          size={30}
                          className="mx-auto mb-3"
                        />

                        No transactions found
                        for the selected filters.

                      </td>

                    </tr>

                  )}


                {/* ROWS — running balance computed client-side */}

                {!loading &&
                  transactions.length > 0 &&
                  (() => {

                    let runningBalance = Number(
                      summary.openingBalance || 0
                    );

                    return (
                      <>

                        {/* OPENING BALANCE */}

                        <tr className="border-t border-slate-100 bg-slate-50">

                          <td
                            colSpan="4"
                            className="px-5 py-3 text-sm font-semibold text-slate-700"
                          >
                            Opening Balance
                          </td>

                          <td className="px-5 py-3 text-right font-mono text-sm font-semibold text-slate-700">
                            Rs.{formatMoney(summary.openingBalance)}
                          </td>

                          <td></td>

                        </tr>


                        {/* TRANSACTIONS */}

                        {transactions.map((item) => {

                          const debit =
                            Number(item.Debit || 0);

                          const credit =
                            Number(item.Credit || 0);

                          runningBalance += credit - debit;

                          const isCredit = credit > 0;

                          const amount =
                            isCredit ? credit : debit;

                          return (

                            <tr
                              key={
                                item.TransactionID ??
                                item.AccountTransactionID
                              }
                              className="border-t border-slate-100 hover:bg-slate-50"
                            >


                              {/* DATE */}

                              <td className="whitespace-nowrap px-5 py-4">

                                {formatDateTime(
                                  item.TransactionDate
                                )}

                              </td>


                              {/* TYPE */}

                              <td className="px-5 py-4">

                                <TransactionBadge
                                  type={
                                    item.TransactionType
                                  }
                                />

                              </td>


                              {/* DESCRIPTION */}

                              <td className="max-w-[400px] px-5 py-4">

                                <div className="truncate">

                                  {item.Description ||
                                    "-"}

                                </div>

                              </td>


                              {/* AMOUNT */}

                              <td
                                className={`px-5 py-4 text-right font-semibold ${
                                  isCredit
                                    ? "text-green-600"
                                    : "text-red-600"
                                }`}
                              >

                                {isCredit
                                  ? "+"
                                  : "-"}

                                {" "}Rs.

                                {formatMoney(
                                  amount
                                )}

                              </td>


                              {/* BALANCE — computed, not from API */}

                              <td
                                className={`px-5 py-4 text-right font-mono font-semibold ${
                                  runningBalance < 0
                                    ? "text-red-600"
                                    : "text-slate-900"
                                }`}
                              >

                                Rs.

                                {formatMoney(
                                  runningBalance
                                )}

                              </td>


                              {/* REFERENCE */}

                              <td className="px-5 py-4 text-slate-500">

                                {item.ReferenceNo ||
                                  "-"}

                              </td>

                            </tr>

                          );

                        })}

                      </>
                    );

                  })()}

              </tbody>

            </table>

          </div>

        </div>

      )}


      {/* =================================================
          SUMMARY TAB
      ================================================= */}

      {activeTab === "summary" && (

        <div className="mx-7 mt-5 mb-10 rounded-2xl border border-slate-200 p-6">

          <h2 className="text-xl font-semibold">
            Cash Summary
          </h2>


          <div className="mt-5 grid gap-5 md:grid-cols-2 xl:grid-cols-4">


            {/* MONEY IN */}

            <div className="rounded-xl bg-green-50 p-5">

              <p className="text-sm text-green-700">
                Total Money In
              </p>

              <p className="mt-2 text-2xl font-bold text-green-700">

                Rs.

                {formatMoney(
                  summary.credits
                )}

              </p>

            </div>


            {/* MONEY OUT */}

            <div className="rounded-xl bg-red-50 p-5">

              <p className="text-sm text-red-700">
                Total Money Out
              </p>

              <p className="mt-2 text-2xl font-bold text-red-700">

                Rs.

                {formatMoney(
                  summary.debits
                )}

              </p>

            </div>


            {/* PERIOD MOVEMENT */}

            <div className="rounded-xl bg-slate-100 p-5">

              <p className="text-sm text-slate-700">
                Period Movement
              </p>

              <p
                className={`mt-2 text-2xl font-bold ${
                  summary.netMovement < 0
                    ? "text-red-600"
                    : "text-green-700"
                }`}
              >

                Rs.

                {formatMoney(
                  summary.netMovement
                )}

              </p>

            </div>


            {/* CURRENT BALANCE */}

            <div className="rounded-xl bg-blue-50 p-5">

              <p className="text-sm text-blue-700">
                Net Cash (Current Balance)
              </p>

              <p className="mt-2 text-2xl font-bold text-blue-700">

                Rs.

                {formatMoney(
                  summary.balance
                )}

              </p>

            </div>

          </div>

        </div>

      )}


      {/* =================================================
          EXPENSE MODAL
      ================================================= */}

      {showExpense && (

        <Modal
          title="Add Expense"
          onClose={() =>
            setShowExpense(false)
          }
        >

          <form
            onSubmit={saveExpense}
            className="space-y-4"
          >


            {/* CASH ACCOUNT */}

            <div>

              <label className="mb-2 block text-sm font-medium">

                Cash Account

                <span className="text-red-500">
                  {" "}*
                </span>

              </label>


              <select
                value={
                  expenseForm.fAccountId
                }
                onChange={(e) =>
                  setExpenseForm({
                    ...expenseForm,
                    fAccountId:
                      e.target.value,
                  })
                }
                required
                className="w-full rounded-xl border border-slate-200 px-4 py-3"
              >

                <option value="">
                  Select account
                </option>


                {accounts.map(
                  (account) => {

                    const faccountId =
                      account.AccountID ??
                      account.id;

                    const faccountName =
                      account.AccountName ??
                      account.name ??
                      `Account ${faccountId}`;


                    return (

                      <option
                        key={faccountId}
                        value={faccountId}
                      >

                        {faccountName}

                      </option>

                    );

                  }
                )}

              </select>

            </div>


            {/* EXPENSE ACCOUNT */}

            <div>

              <label className="mb-2 block text-sm font-medium">

                Expense Account

                <span className="text-red-500">
                  {" "}*
                </span>

              </label>


              <select
                value={
                  expenseForm.AccountId
                }
                onChange={(e) =>
                  setExpenseForm({
                    ...expenseForm,
                    AccountId:
                      e.target.value,
                  })
                }
                required
                className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 outline-none focus:border-amber-500 focus:ring-2 focus:ring-amber-100"
              >

                <option value="">
                  Select Expense Account
                </option>


                {expenseAccounts.map(
                  (account) => {

                    const accountId =
                      account.AccountID ??
                      account.id;

                    const accountName =
                      account.AccountName ??
                      account.name ??
                      `Account ${accountId}`;


                    return (

                      <option
                        key={accountId}
                        value={accountId}
                      >

                        {accountName}

                      </option>

                    );

                  }
                )}

              </select>

            </div>


            {/* AMOUNT */}

            <FormInput
              label="Amount"
              type="number"
              value={
                expenseForm.amount
              }
              onChange={(value) =>
                setExpenseForm({
                  ...expenseForm,
                  amount: value,
                })
              }
              required
            />


            {/* DESCRIPTION */}

            <FormInput
              label="Description"
              value={
                expenseForm.description
              }
              onChange={(value) =>
                setExpenseForm({
                  ...expenseForm,
                  description: value,
                })
              }
              placeholder="Description"
            />


            {/* REFERENCE */}

            <FormInput
              label="Reference No"
              value={
                expenseForm.referenceNo
              }
              onChange={(value) =>
                setExpenseForm({
                  ...expenseForm,
                  referenceNo: value,
                })
              }
            />


            <ModalButtons
              onCancel={() =>
                setShowExpense(false)
              }
              loading={loading}
            />

          </form>

        </Modal>

      )}


      {/* =================================================
          TRANSFER MODAL
      ================================================= */}

      {showTransfer && (

        <Modal
          title="Add Transfer"
          onClose={() =>
            setShowTransfer(false)
          }
        >

          <form
            onSubmit={saveTransfer}
            className="space-y-4"
          >


            {/* FROM ACCOUNT */}

            <div>

              <label className="mb-2 block text-sm font-medium">
                From Account
              </label>


              <select
                value={
                  transferForm.fromAccountId
                }
                onChange={(e) =>
                  setTransferForm({
                    ...transferForm,
                    fromAccountId:
                      e.target.value,
                  })
                }
                required
                className="w-full rounded-xl border border-slate-200 px-4 py-3"
              >

                <option value="">
                  Select account
                </option>


                {accounts.map(
                  (account) => {

                    const accountId =
                      account.AccountID ??
                      account.id;

                    const accountName =
                      account.AccountName ??
                      account.name ??
                      `Account ${accountId}`;


                    return (

                      <option
                        key={accountId}
                        value={accountId}
                      >

                        {accountName}

                      </option>

                    );

                  }
                )}

              </select>

            </div>


            {/* TO ACCOUNT */}

            <div>

              <label className="mb-2 block text-sm font-medium">
                To Account
              </label>


              <select
                value={
                  transferForm.toAccountId
                }
                onChange={(e) =>
                  setTransferForm({
                    ...transferForm,
                    toAccountId:
                      e.target.value,
                  })
                }
                required
                className="w-full rounded-xl border border-slate-200 px-4 py-3"
              >

                <option value="">
                  Select account
                </option>


                {accounts.map(
                  (account) => {

                    const accountId =
                      account.AccountID ??
                      account.id;

                    const accountName =
                      account.AccountName ??
                      account.name ??
                      `Account ${accountId}`;


                    return (

                      <option
                        key={accountId}
                        value={accountId}
                      >

                        {accountName}

                      </option>

                    );

                  }
                )}

              </select>

            </div>


            {/* AMOUNT */}

            <FormInput
              label="Amount"
              type="number"
              value={
                transferForm.amount
              }
              onChange={(value) =>
                setTransferForm({
                  ...transferForm,
                  amount: value,
                })
              }
              required
            />


            {/* DESCRIPTION */}

            <FormInput
              label="Description"
              value={
                transferForm.description
              }
              onChange={(value) =>
                setTransferForm({
                  ...transferForm,
                  description: value,
                })
              }
            />


            {/* REFERENCE */}

            <FormInput
              label="Reference No"
              value={
                transferForm.referenceNo
              }
              onChange={(value) =>
                setTransferForm({
                  ...transferForm,
                  referenceNo: value,
                })
              }
            />


            <ModalButtons
              onCancel={() =>
                setShowTransfer(false)
              }
              loading={loading}
            />

          </form>

        </Modal>

      )}


      {/* =================================================
          SUPPLIER PAYMENT MODAL
          (kept for backwards compatibility — header button
          now navigates to /supplier-payment)
      ================================================= */}

      {showSupplier && (

        <Modal
          title="Supplier Payment"
          onClose={() =>
            setShowSupplier(false)
          }
        >

          <form
            onSubmit={saveSupplierPayment}
            className="space-y-4"
          >


            {/* SUPPLIER NAME */}

            <FormInput
              label="Supplier Name"
              value={
                supplierForm.supplierName
              }
              onChange={(value) =>
                setSupplierForm({
                  ...supplierForm,
                  supplierName: value,
                })
              }
              required
            />


            {/* AMOUNT */}

            <FormInput
              label="Amount"
              type="number"
              value={
                supplierForm.amount
              }
              onChange={(value) =>
                setSupplierForm({
                  ...supplierForm,
                  amount: value,
                })
              }
              required
            />


            {/* DESCRIPTION */}

            <FormInput
              label="Description"
              value={
                supplierForm.description
              }
              onChange={(value) =>
                setSupplierForm({
                  ...supplierForm,
                  description: value,
                })
              }
            />


            {/* REFERENCE */}

            <FormInput
              label="Reference No"
              value={
                supplierForm.referenceNo
              }
              onChange={(value) =>
                setSupplierForm({
                  ...supplierForm,
                  referenceNo: value,
                })
              }
            />


            <ModalButtons
              onCancel={() =>
                setShowSupplier(false)
              }
              loading={loading}
            />

          </form>

        </Modal>

      )}

    </div>

  );

}


/* =====================================================
   SUMMARY CARD
===================================================== */

function SummaryCard({
  icon,
  title,
  value,
  className,
  number,
}) {

  return (

    <div className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">

      <div className="flex items-center gap-3">

        <div className={className}>
          {icon}
        </div>

        <span className="text-sm text-slate-500">
          {title}
        </span>

      </div>


      <p
        className={`mt-2 text-2xl font-bold ${
          number
            ? "text-slate-900"
            : ""
        }`}
      >

        {number
          ? value
          : `Rs.${formatMoney(value)}`}

      </p>

    </div>

  );

}


/* =====================================================
   TRANSACTION BADGE
===================================================== */

function TransactionBadge({ type }) {

  let style =
    "bg-slate-100 text-slate-700";


  if (
    type === "Expense" ||
    type === "DEBIT"
  ) {

    style =
      "bg-red-50 text-red-700";

  } else if (
    type === "Transfer"
  ) {

    style =
      "bg-amber-50 text-amber-700";

  } else if (
    type === "Supplier Payment"
  ) {

    style =
      "bg-purple-50 text-purple-700";

  } else if (
    type === "Credit" ||
    type === "CREDIT"
  ) {

    style =
      "bg-green-50 text-green-700";

  }


  return (

    <span
      className={`rounded-full px-3 py-1 text-xs font-semibold ${style}`}
    >

      {type || "Transaction"}

    </span>

  );

}


/* =====================================================
   MODAL
===================================================== */

function Modal({
  title,
  children,
  onClose,
}) {

  return (

    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4">

      <div className="w-full max-w-lg rounded-2xl bg-white shadow-2xl">

        <div className="flex items-center justify-between border-b border-slate-200 px-6 py-4">

          <h2 className="text-xl font-bold">
            {title}
          </h2>


          <button
            onClick={onClose}
            type="button"
            className="rounded-lg p-2 hover:bg-slate-100"
          >

            <X size={20} />

          </button>

        </div>


        <div className="p-6">

          {children}

        </div>

      </div>

    </div>

  );

}


/* =====================================================
   FORM INPUT
===================================================== */

function FormInput({
  label,
  type = "text",
  value,
  onChange,
  placeholder,
  required,
}) {

  return (

    <div>

      <label className="mb-2 block text-sm font-medium">

        {label}

        {required && (

          <span className="text-red-500">
            {" "}*
          </span>

        )}

      </label>


      <input
        type={type}
        value={value}
        onChange={(e) =>
          onChange(
            e.target.value
          )
        }
        placeholder={placeholder}
        required={required}
        min={
          type === "number"
            ? "0.01"
            : undefined
        }
        step={
          type === "number"
            ? "0.01"
            : undefined
        }
        className="w-full rounded-xl border border-slate-200 px-4 py-3 outline-none focus:border-amber-500 focus:ring-2 focus:ring-amber-100"
      />

    </div>

  );

}


/* =====================================================
   MODAL BUTTONS
===================================================== */

function ModalButtons({
  onCancel,
  loading,
}) {

  return (

    <div className="flex justify-end gap-3 pt-3">


      <button
        type="button"
        onClick={onCancel}
        className="rounded-xl border border-slate-200 px-5 py-2.5 text-sm font-medium"
      >

        Cancel

      </button>


      <button
        type="submit"
        disabled={loading}
        className="rounded-xl bg-amber-500 px-5 py-2.5 text-sm font-semibold text-white hover:bg-amber-600 disabled:opacity-50"
      >

        {loading
          ? "Saving..."
          : "Save"}

      </button>

    </div>

  );

}


/* =====================================================
   HELPERS
===================================================== */

function getToday() {

  const date =
    new Date();


  return date
    .toISOString()
    .split("T")[0];

}


function getDateBefore(days) {

  const date =
    new Date();


  date.setDate(
    date.getDate() - days
  );


  return date
    .toISOString()
    .split("T")[0];

}


function formatMoney(value) {

  return Number(
    value || 0
  ).toLocaleString(
    "en-LK",
    {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }
  );

}


function formatDateTime(value) {

  if (!value) {
    return "-";
  }


  const date =
    new Date(value);


  if (
    Number.isNaN(
      date.getTime()
    )
  ) {

    return value;

  }


  return date.toLocaleString(
    "en-GB",
    {
      day: "2-digit",
      month: "2-digit",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    }
  );

}