
import React, { useState, useEffect, useCallback } from 'react';
import axios from 'axios';
import {
  Search,
  Calendar,
  Download,
  RefreshCw,
  ChevronLeft,
  ChevronRight,
  Eye,
  X,
  Printer,
  Edit
} from 'lucide-react';

const API_BASE_URL = 'http://localhost:5000/api';

const SalesHistory = () => {
  const [invoices, setInvoices] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const [payType, setPayType] = useState('All Payments');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalRecords, setTotalRecords] = useState(0);
  const limit = 10;

  const [selectedInvoice, setSelectedInvoice] = useState(null);
  const [invoiceDetails, setInvoiceDetails] = useState(null);
  const [loadingDetails, setLoadingDetails] = useState(false);
  const [printing, setPrinting] = useState(false);

  // --------------------------------------------------
  // SEARCH DEBOUNCE
  // --------------------------------------------------
  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedSearch(searchTerm);
      setPage(1);
    }, 500);

    return () => clearTimeout(handler);
  }, [searchTerm]);

  // --------------------------------------------------
  // FETCH SALES HISTORY
  // --------------------------------------------------
  const fetchSalesHistory = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      const response = await axios.get(
        `${API_BASE_URL}/sales/history`,
        {
          params: {
            search: debouncedSearch,
            payType,
            startDate,
            endDate,
            page,
            limit
          }
        }
      );

      setInvoices(response.data.data || []);
      setTotalPages(response.data.totalPages || 1);
      setTotalRecords(response.data.total || 0);

    } catch (err) {
      console.error('Error fetching sales history:', err);
      setError(
        'Failed to load sales data. Please check your database connection.'
      );
    } finally {
      setLoading(false);
    }
  }, [
    debouncedSearch,
    payType,
    startDate,
    endDate,
    page
  ]);

  useEffect(() => {
    fetchSalesHistory();
  }, [fetchSalesHistory]);

  // --------------------------------------------------
  // FETCH INVOICE DETAILS
  // --------------------------------------------------
  const handleRowClick = async (invoice) => {
    setSelectedInvoice(invoice);
    setInvoiceDetails(null);
    setLoadingDetails(true);

    try {
      const response = await axios.get(
        `${API_BASE_URL}/sales/history/${invoice.Receipt}`
      );

      setInvoiceDetails(response.data);

    } catch (err) {
      console.error('Error fetching invoice details:', err);
      setInvoiceDetails(null);
    } finally {
      setLoadingDetails(false);
    }
  };

  // --------------------------------------------------
  // CLOSE DETAILS
  // --------------------------------------------------
  const closeDetailsPanel = () => {
    setSelectedInvoice(null);
    setInvoiceDetails(null);
  };

  // --------------------------------------------------
  // FORMAT CURRENCY
  // --------------------------------------------------
  const formatCurrency = (amount) => {
    const safeAmount = Number(amount) || 0;

    return new Intl.NumberFormat('en-LK', {
      style: 'currency',
      currency: 'LKR',
      minimumFractionDigits: 2
    })
      .format(safeAmount)
      .replace('LKR', 'Rs.');
  };

  // --------------------------------------------------
  // FORMAT DATE
  // --------------------------------------------------
  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';

    const date = new Date(dateString);

    return date.toLocaleDateString('en-GB', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  // --------------------------------------------------
  // GET PAPER WIDTH FROM POS SETTINGS
  // --------------------------------------------------
  const getPaperWidth = (paperSize) => {
    const value = String(paperSize || '')
      .trim()
      .toUpperCase()
      .replace(/\s+/g, '');

    switch (value) {
      case '58':
      case '58MM':
        return '58mm';

      case '76':
      case '76MM':
        return '76mm';

      case '80':
      case '80MM':
        return '80mm';

      case 'A5':
        return '148mm';

      case 'A4':
        return '210mm';

      default:
        // Default thermal receipt size
        return '80mm';
    }
  };

  // --------------------------------------------------
  // DIRECT BROWSER PRINT
  // --------------------------------------------------
  const handlePrint = async () => {
    if (!invoiceDetails) {
      alert('Invoice details are not loaded yet.');
      return;
    }

    if (printing) return;

    setPrinting(true);

    try {
      // ----------------------------------------------
      // GET POS SETTINGS
      // ----------------------------------------------
      const settingsResponse = await axios.get(
        `${API_BASE_URL}/pos-settings?id=1`
      );

      const posSettings = settingsResponse.data?.data || {};

      const paperWidth = getPaperWidth(
        posSettings.PaperSize
      );

      // ----------------------------------------------
      // INVOICE DATA
      // ----------------------------------------------
      const receiptNo = invoiceDetails.Receipt || '';
      const invoiceDate = invoiceDetails.RecDate
        ? formatDate(invoiceDetails.RecDate)
        : '';

      const customer =
        invoiceDetails.Customer || 'Walk-in Customer';

      const paymentMethod =
        invoiceDetails.PaymentMethod || 'Cash';

      const saleType =
        invoiceDetails.SaleTypeID || '';

      const total =
        Number(invoiceDetails.TotalAmount) || 0;

      const items =
        Array.isArray(invoiceDetails.itemsList)
          ? invoiceDetails.itemsList
          : [];

      // ----------------------------------------------
      // POS SETTINGS
      // ----------------------------------------------
      const companyName =
        posSettings.CompanyName || '';

      const companyAddress =
        posSettings.CompanyAddress || '';

      const companyPhone =
        posSettings.CompanyPhone || '';

      const companyEmail =
        posSettings.CompanyEmail || '';

      const taxNumber =
        posSettings.TaxNumber || '';

      const invoiceTitle =
        posSettings.InvoiceTitle || 'INVOICE';

      const invoiceHeader =
        posSettings.InvoiceHeader || '';

      const invoiceFooter =
        posSettings.InvoiceFooter || '';

      const invoiceNotes =
        posSettings.InvoiceNotes || '';

      const currency =
        posSettings.Currency || 'LKR';

      const showCustomer =
        posSettings.ShowCustomer !== false;

      const showCustomerAddress =
        posSettings.ShowCustomerAddress === true;

      const showCustomerPhone =
        posSettings.ShowCustomerPhone === true;

      const showPaymentMethod =
        posSettings.ShowPaymentMethod !== false;

      const showDateTime =
        posSettings.ShowDateTime !== false;

      const showTax =
        posSettings.ShowTax === true;

      // ----------------------------------------------
      // BUILD ITEM ROWS
      // ----------------------------------------------
      const itemRows = items
        .map((item) => {
          const description =
            item.Descrip || '';

          const qty =
            Number(item.Qty) || 0;

          const price =
            Number(item.Price) || 0;

          const amount =
            Number(item.Amount) ||
            qty * price;

          const unit =
            item.UnitOfMeasureName || '';

          return `
            <div class="item">
              <div class="item-name">
                ${description}
              </div>

              <div class="item-row">
                <span>
                  ${qty} ${unit}
                  × ${formatCurrency(price)}
                </span>

                <span>
                  ${formatCurrency(amount)}
                </span>
              </div>
            </div>
          `;
        })
        .join('');

      // ----------------------------------------------
      // PRINT WINDOW
      // ----------------------------------------------
      const printWindow = window.open(
        '',
        '_blank',
        'width=500,height=700'
      );

      if (!printWindow) {
        alert(
          'Print window was blocked by the browser. Please allow pop-ups for this application.'
        );

        return;
      }

      // ----------------------------------------------
      // PRINT HTML
      // ----------------------------------------------
      printWindow.document.open();

      printWindow.document.write(`
        <!DOCTYPE html>

        <html>
        <head>

          <meta charset="UTF-8" />

          <title>
            ${invoiceTitle} - ${receiptNo}
          </title>

          <style>

            @page {
              size: ${paperWidth} auto;
              margin: 0;
            }

            * {
              box-sizing: border-box;
            }

            html,
            body {
              width: ${paperWidth};
              margin: 0;
              padding: 0;
              background: white;
            }

            body {
              font-family:
                Arial,
                Helvetica,
                sans-serif;

              font-size: 12px;
              color: #000;

              -webkit-print-color-adjust: exact;
              print-color-adjust: exact;
            }

            .receipt {
              width: 100%;
              padding: 4mm;
              margin: 0;
            }

            .center {
              text-align: center;
            }

            .left {
              text-align: left;
            }

            .right {
              text-align: right;
            }

            .company-name {
              font-size: 17px;
              font-weight: bold;
              margin-bottom: 2px;
            }

            .company-info {
              font-size: 10px;
              line-height: 1.35;
            }

            .title {
              font-size: 15px;
              font-weight: bold;
              margin-top: 8px;
              margin-bottom: 5px;
            }

            .header-text {
              font-size: 10px;
              margin: 4px 0;
              white-space: pre-line;
            }

            .line {
              border-top: 1px dashed #000;
              margin: 7px 0;
            }

            .info {
              font-size: 11px;
              line-height: 1.5;
            }

            .info-row {
              display: flex;
              justify-content: space-between;
              gap: 5px;
            }

            .items {
              margin-top: 5px;
            }

            .item {
              margin-bottom: 6px;
            }

            .item-name {
              font-weight: bold;
              word-break: break-word;
            }

            .item-row {
              display: flex;
              justify-content: space-between;
              gap: 5px;
              font-size: 11px;
            }

            .total {
              display: flex;
              justify-content: space-between;
              font-size: 15px;
              font-weight: bold;
              margin-top: 5px;
            }

            .tax {
              display: flex;
              justify-content: space-between;
              font-size: 11px;
            }

            .footer {
              text-align: center;
              font-size: 10px;
              line-height: 1.4;
              margin-top: 10px;
              white-space: pre-line;
            }

            .duplicate {
              text-align: center;
              font-weight: bold;
              font-size: 13px;
              margin-top: 10px;
              border-top: 1px dashed #000;
              border-bottom: 1px dashed #000;
              padding: 5px 0;
            }

            @media print {

              html,
              body {
                width: ${paperWidth};
                margin: 0;
                padding: 0;
              }

              .receipt {
                width: 100%;
                margin: 0;
              }

            }

          </style>

        </head>

        <body>

          <div class="receipt">

            <!-- COMPANY -->
            <div class="center">

              ${
                companyName
                  ? `
                    <div class="company-name">
                      ${companyName}
                    </div>
                  `
                  : ''
              }

              ${
                companyAddress
                  ? `
                    <div class="company-info">
                      ${companyAddress}
                    </div>
                  `
                  : ''
              }

              ${
                companyPhone
                  ? `
                    <div class="company-info">
                      Tel: ${companyPhone}
                    </div>
                  `
                  : ''
              }

              ${
                companyEmail
                  ? `
                    <div class="company-info">
                      ${companyEmail}
                    </div>
                  `
                  : ''
              }

              ${
                taxNumber && showTax
                  ? `
                    <div class="company-info">
                      Tax No: ${taxNumber}
                    </div>
                  `
                  : ''
              }

            </div>

            ${
              invoiceHeader
                ? `
                  <div class="header-text center">
                    ${invoiceHeader}
                  </div>
                `
                : ''
            }

            <div class="title center">
              ${invoiceTitle}
            </div>

            <div class="line"></div>

            <!-- INVOICE INFO -->
            <div class="info">

              <div class="info-row">
                <span>Invoice</span>
                <span>${receiptNo}</span>
              </div>

              ${
                showDateTime
                  ? `
                    <div class="info-row">
                      <span>Date</span>
                      <span>${invoiceDate}</span>
                    </div>
                  `
                  : ''
              }

              ${
                showCustomer
                  ? `
                    <div class="info-row">
                      <span>Customer</span>
                      <span>${customer}</span>
                    </div>
                  `
                  : ''
              }

              ${
                showCustomerAddress &&
                invoiceDetails.CustomerAddress
                  ? `
                    <div>
                      Address:
                      ${invoiceDetails.CustomerAddress}
                    </div>
                  `
                  : ''
              }

              ${
                showCustomerPhone &&
                invoiceDetails.CustomerPhone
                  ? `
                    <div>
                      Phone:
                      ${invoiceDetails.CustomerPhone}
                    </div>
                  `
                  : ''
              }

              ${
                showPaymentMethod
                  ? `
                    <div class="info-row">
                      <span>Payment</span>
                      <span>${paymentMethod}</span>
                    </div>
                  `
                  : ''
              }

              ${
                saleType
                  ? `
                    <div class="info-row">
                      <span>Type</span>
                      <span>${saleType}</span>
                    </div>
                  `
                  : ''
              }

            </div>

            <div class="line"></div>

            <!-- ITEMS -->
            <div class="items">

              ${itemRows}

            </div>

            <div class="line"></div>

            <!-- TOTAL -->
            <div class="total">
              <span>TOTAL</span>
              <span>${formatCurrency(total)}</span>
            </div>

            <div class="info-row" style="margin-top: 4px;">
              <span>Currency</span>
              <span>${currency}</span>
            </div>

            <!-- DUPLICATE -->
            <div class="duplicate">
              DUPLICATE
            </div>

            ${
              invoiceNotes
                ? `
                  <div class="footer">
                    ${invoiceNotes}
                  </div>
                `
                : ''
            }

            ${
              invoiceFooter
                ? `
                  <div class="footer">
                    ${invoiceFooter}
                  </div>
                `
                : ''
            }

          </div>

        </body>
        </html>
      `);

      printWindow.document.close();

      // ----------------------------------------------
      // OPEN BROWSER PRINT DIALOG
      // ----------------------------------------------
      setTimeout(() => {
        try {
          printWindow.focus();
          printWindow.print();

          // Close print tab after print dialog is handled
          setTimeout(() => {
            try {
              printWindow.close();
            } catch (closeError) {
              console.warn(
                'Could not close print window:',
                closeError
              );
            }
          }, 1000);

        } catch (printError) {
          console.error(
            'Print error:',
            printError
          );
        }
      }, 400);

    } catch (err) {
      console.error(
        'DIRECT PRINT ERROR:',
        err
      );

      alert(
        'Unable to print invoice. Please check POS settings.'
      );

    } finally {
      setPrinting(false);
    }
  };

  return (
    <div className="flex h-screen bg-gray-50 overflow-hidden font-sans">

      {/* ==================================================
          MAIN CONTENT
      ================================================== */}

      <div
        className={`
          flex-1
          flex
          flex-col
          p-6
          overflow-y-auto
          transition-all
          duration-300
          ${selectedInvoice ? 'pr-4' : ''}
        `}
      >

        {/* HEADER */}
        <div className="flex justify-between items-center mb-6">

          <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
            <span className="text-gray-800">
              📄 Sales History
            </span>
          </h1>

          <div className="flex gap-2">

            <button
              onClick={fetchSalesHistory}
              className="flex items-center gap-2 px-4 py-2 bg-white border rounded-lg hover:bg-gray-50"
            >
              <RefreshCw size={16} />
              Refresh
            </button>

            <button
              className="flex items-center gap-2 px-4 py-2 bg-white border rounded-lg hover:bg-gray-50"
            >
              <Download size={16} />
              Export CSV
            </button>

          </div>

        </div>

        {/* FILTERS */}
        <div className="bg-white p-4 rounded-xl border shadow-sm mb-6 flex flex-wrap gap-4 items-end">

          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1">
              Search
            </label>

            <div className="relative">

              <Search
                size={16}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"
              />

              <input
                type="text"
                value={searchTerm}
                onChange={(e) =>
                  setSearchTerm(e.target.value)
                }
                placeholder="Invoice / customer..."
                className="pl-9 pr-3 py-2 border rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
              />

            </div>
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1">
              Payment
            </label>

            <select
              value={payType}
              onChange={(e) => {
                setPayType(e.target.value);
                setPage(1);
              }}
              className="px-3 py-2 border rounded-lg"
            >
              <option>All Payments</option>
              <option>Cash</option>
              <option>Card</option>
              <option>Credit</option>
            </select>
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1">
              Start Date
            </label>

            <div className="relative">

              <Calendar
                size={16}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"
              />

              <input
                type="date"
                value={startDate}
                onChange={(e) => {
                  setStartDate(e.target.value);
                  setPage(1);
                }}
                className="pl-9 pr-3 py-2 border rounded-lg"
              />

            </div>
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1">
              End Date
            </label>

            <div className="relative">

              <Calendar
                size={16}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"
              />

              <input
                type="date"
                value={endDate}
                onChange={(e) => {
                  setEndDate(e.target.value);
                  setPage(1);
                }}
                className="pl-9 pr-3 py-2 border rounded-lg"
              />

            </div>
          </div>

        </div>

        {/* ERROR */}
        {error && (
          <div className="mb-4 p-4 bg-red-50 border border-red-200 text-red-700 rounded-lg">
            {error}
          </div>
        )}

        {/* TABLE */}
        <div className="bg-white rounded-xl border shadow-sm flex-1 overflow-hidden flex flex-col">

          <div className="overflow-auto">

            <table className="w-full text-sm">

              <thead className="bg-gray-50 border-b">

                <tr>

                  <th className="text-left px-4 py-3">
                    Invoice
                  </th>

                  <th className="text-left px-4 py-3">
                    Date
                  </th>

                  <th className="text-left px-4 py-3">
                    Customer
                  </th>

                  <th className="text-left px-4 py-3">
                    Payment
                  </th>

                  <th className="text-left px-4 py-3">
                    Type
                  </th>

                  <th className="text-right px-4 py-3">
                    Items
                  </th>

                  <th className="text-right px-4 py-3">
                    Amount
                  </th>

                </tr>

              </thead>

              <tbody>

                {loading ? (

                  <tr>

                    <td
                      colSpan="7"
                      className="text-center py-10 text-gray-500"
                    >
                      Loading...
                    </td>

                  </tr>

                ) : invoices.length === 0 ? (

                  <tr>

                    <td
                      colSpan="7"
                      className="text-center py-10 text-gray-500"
                    >
                      No sales found.
                    </td>

                  </tr>

                ) : (

                  invoices.map((sale) => (

                    <tr
                      key={sale.Receipt}
                      onClick={() =>
                        handleRowClick(sale)
                      }
                      className="border-b hover:bg-gray-50 cursor-pointer"
                    >

                      <td className="px-4 py-3 font-medium">
                        {sale.Receipt}
                      </td>

                      <td className="px-4 py-3">
                        {formatDate(sale.RecDate)}
                      </td>

                      <td className="px-4 py-3">
                        {sale.Customer || 'Walk-in'}
                      </td>

                      <td className="px-4 py-3">
                        {sale.PayTypeID || '-'}
                      </td>

                      <td className="px-4 py-3">
                        {sale.SaleTypeID || '-'}
                      </td>

                      <td className="px-4 py-3 text-right">
                        {sale.ItemCount || 0}
                      </td>

                      <td className="px-4 py-3 text-right font-medium">
                        {formatCurrency(sale.Amount)}
                      </td>

                    </tr>

                  ))

                )}

              </tbody>

            </table>

          </div>

        </div>

        {/* PAGINATION */}
        <div className="p-4 border-t flex justify-between items-center">

          <span className="text-sm text-gray-500">
            Total Records: {totalRecords}
          </span>

          <div className="flex items-center gap-2">

            <button
              disabled={page <= 1}
              onClick={() =>
                setPage((p) => Math.max(1, p - 1))
              }
              className="p-2 border rounded-lg disabled:opacity-40"
            >
              <ChevronLeft size={18} />
            </button>

            <span className="text-sm">
              Page {page} of {totalPages}
            </span>

            <button
              disabled={page >= totalPages}
              onClick={() =>
                setPage((p) =>
                  Math.min(totalPages, p + 1)
                )
              }
              className="p-2 border rounded-lg disabled:opacity-40"
            >
              <ChevronRight size={18} />
            </button>

          </div>

        </div>

      </div>

      {/* ==================================================
          INVOICE DETAILS PANEL
      ================================================== */}

      {selectedInvoice && (

        <div className="w-[400px] border-l bg-white shadow-2xl flex flex-col shrink-0">

          {/* PANEL HEADER */}
          <div className="p-5 border-b flex justify-between items-center">

            <div>
              <h2 className="font-bold text-lg">
                Invoice Details
              </h2>

              <p className="text-sm text-gray-500">
                {selectedInvoice.Receipt}
              </p>
            </div>

            <div className="flex gap-2">

              {/* DIRECT PRINT BUTTON */}
              <button
                title="Print"
                onClick={handlePrint}
                disabled={
                  loadingDetails ||
                  !invoiceDetails ||
                  printing
                }
                className={`
                  p-2 rounded-lg
                  border
                  transition
                  ${
                    printing
                      ? 'opacity-50 cursor-wait'
                      : 'hover:bg-gray-100'
                  }
                `}
              >
                <Printer size={18} />
              </button>

              <button
                title="Edit"
                className="p-2 rounded-lg border hover:bg-gray-100"
              >
                <Edit size={18} />
              </button>

              <button
                onClick={closeDetailsPanel}
                title="Close"
                className="p-2 rounded-lg border hover:bg-gray-100"
              >
                <X size={18} />
              </button>

            </div>

          </div>

          {/* DETAILS */}
          <div className="flex-1 overflow-y-auto p-5 space-y-6">

            {loadingDetails ? (

              <div className="text-center py-10 text-gray-500">
                Loading invoice...
              </div>

            ) : invoiceDetails ? (

              <>
                <div>

                  <h3 className="font-semibold mb-2">
                    Invoice
                  </h3>

                  <div className="text-sm space-y-1">

                    <div className="flex justify-between">
                      <span className="text-gray-500">
                        Receipt
                      </span>

                      <span>
                        {invoiceDetails.Receipt}
                      </span>
                    </div>

                    <div className="flex justify-between">
                      <span className="text-gray-500">
                        Date
                      </span>

                      <span>
                        {formatDate(
                          invoiceDetails.RecDate
                        )}
                      </span>
                    </div>

                  </div>

                </div>

                <div>

                  <h3 className="font-semibold mb-2">
                    Customer
                  </h3>

                  <div className="text-sm">
                    {invoiceDetails.Customer ||
                      'Walk-in Customer'}
                  </div>

                </div>

                <div>

                  <h3 className="font-semibold mb-2">
                    Payment
                  </h3>

                  <div className="text-sm">

                    {invoiceDetails.PaymentMethod ||
                      '-'}

                  </div>

                </div>

                <div>

                  <h3 className="font-semibold mb-2">
                    Items
                  </h3>

                  <div className="space-y-3">

                    {invoiceDetails.itemsList?.map(
                      (item) => (

                        <div
                          key={item.TransactionDetID}
                          className="border-b pb-2"
                        >

                          <div className="font-medium">
                            {item.Descrip}
                          </div>

                          <div className="flex justify-between text-sm text-gray-500">

                            <span>
                              {item.Qty}{' '}
                              {item.UnitOfMeasureName}
                              {' × '}
                              {formatCurrency(
                                item.Price
                              )}
                            </span>

                            <span>
                              {formatCurrency(
                                item.Amount
                              )}
                            </span>

                          </div>

                        </div>

                      )
                    )}

                  </div>

                </div>

              </>

            ) : (

              <div className="text-center py-10 text-red-500">
                Failed to load invoice details.
              </div>

            )}

          </div>

          {/* TOTAL */}
          {invoiceDetails && (

            <div className="p-5 border-t">

              <div className="flex justify-between items-center">

                <span className="font-semibold">
                  Total
                </span>

                <span className="text-xl font-bold">
                  {formatCurrency(
                    invoiceDetails.TotalAmount
                  )}
                </span>

              </div>

            </div>

          )}

        </div>

      )}

    </div>
  );
};

export default SalesHistory;

