import React, { useEffect, useMemo, useState } from "react";
import axios from "axios";

import {
  Plus,
  Download,
  Upload,
  Search,
  Filter,
  ChevronDown,
  X,
  Pencil,
  RefreshCw,
  CheckCircle2,
  User,
  Building2,
  CreditCard,
  WalletCards,
  Receipt,
} from "lucide-react";

const API_URL = "http://localhost:5000/api";

/* =========================================================
   ACCOUNT TYPES
========================================================= */

const ACCOUNT_TYPES = [
  {
    value: "cash",
    label: "Cash on Hand",
    icon: WalletCards,
  },
  {
    value: "card_sale",
    label: "Card Sale",
    icon: CreditCard,
  },
  {
    value: "third_party_check",
    label: "Third-Party Check",
    icon: Receipt,
  },
  {
    value: "bank_account",
    label: "Bank Account",
    icon: Building2,
  },
  {
    value: "credit_card",
    label: "Credit Card",
    icon: CreditCard,
  },
  {
    value: "expenses",
    label: "Expenses",
    icon: WalletCards,
  },
  {
    value: "active_account",
    label: "Active Account",
    icon: Building2,
  },
  {
    value: "owner_account",
    label: "Owner Account",
    icon: User,
  },
  {
    value: "other",
    label: "Other",
    icon: WalletCards,
  },
];

/* =========================================================
   HELPERS
========================================================= */

const formatMoney = (value) => {
  const amount = Number(value || 0);

  return `Rs.${amount.toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;
};

const getTypeLabel = (type) => {
  const found = ACCOUNT_TYPES.find(
    (item) => item.value === type
  );

  return found?.label || type || "-";
};

/* =========================================================
   ACCOUNT CARD
========================================================= */

function AccountCard({ type, accounts }) {
  const total = accounts.reduce(
    (sum, account) =>
      sum + Number(account.balance || 0),
    0
  );

  const Icon = type.icon;

  return (
    <div className="rounded-xl border border-gray-300 bg-white p-6 shadow-sm">
      <div className="mb-3 flex items-center justify-between">
        <span className="text-sm font-medium text-gray-800">
          {type.label}
        </span>

        <Icon
          size={18}
          className="text-gray-500"
        />
      </div>

      <div
        className={`text-2xl font-bold ${
          total < 0
            ? "text-red-600"
            : "text-gray-950"
        }`}
      >
        {formatMoney(total)}
      </div>

      <div className="mt-1 text-xs text-gray-500">
        {accounts.length}{" "}
        {accounts.length === 1
          ? "account"
          : "accounts"}
      </div>
    </div>
  );
}

/* =========================================================
   CREATE / EDIT MODAL
========================================================= */

function AccountModal({
  account,
  onClose,
  onSave,
  saving,
}) {
  const [form, setForm] = useState({
    name: account?.name || "",
    type: account?.type || "",
    detailType: account?.detailType || "",
    description: account?.description || "",
  });

  const isEdit = Boolean(account);

  const handleChange = (field, value) => {
    setForm((previous) => ({
      ...previous,
      [field]: value,
    }));
  };

  const handleSubmit = (event) => {
    event.preventDefault();

    if (!form.name.trim()) {
      alert("Please enter account name.");
      return;
    }

    if (!form.type) {
      alert("Please select account type.");
      return;
    }

    onSave(form);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4">
      <div className="w-full max-w-[510px] rounded-2xl bg-white shadow-2xl">

        {/* HEADER */}

        <div className="flex items-start justify-between px-6 pt-6">

          <div>
            <h2 className="text-xl font-bold text-gray-900">
              {isEdit
                ? "Edit Account"
                : "Create New Account"}
            </h2>

            <p className="mt-1 text-sm text-gray-500">
              {isEdit
                ? "Update account information"
                : "Add a new account to your system"}
            </p>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="rounded-full p-1 text-gray-500 hover:bg-gray-100"
          >
            <X size={20} />
          </button>

        </div>

        {/* FORM */}

        <form
          onSubmit={handleSubmit}
          className="space-y-5 px-6 pb-6 pt-5"
        >

          {/* ACCOUNT NAME */}

          <div>
            <label className="mb-2 block text-sm font-medium text-gray-900">
              Account Name
            </label>

            <input
              type="text"
              value={form.name}
              onChange={(event) =>
                handleChange(
                  "name",
                  event.target.value
                )
              }
              placeholder="Enter account name"
              className="h-11 w-full rounded-xl border border-gray-200 px-3 text-sm outline-none focus:border-orange-500 focus:ring-2 focus:ring-orange-100"
            />
          </div>

          {/* ACCOUNT TYPE */}

          <div>
            <label className="mb-2 block text-sm font-medium text-gray-900">
              Account Type
            </label>

            <div className="relative">

              <select
                value={form.type}
                onChange={(event) =>
                  handleChange(
                    "type",
                    event.target.value
                  )
                }
                className="h-11 w-full appearance-none rounded-xl border border-gray-200 bg-white px-3 text-sm outline-none focus:border-orange-500 focus:ring-2 focus:ring-orange-100"
              >
                <option value="">
                  Select account type
                </option>

                {ACCOUNT_TYPES.map((type) => (
                  <option
                    key={type.value}
                    value={type.value}
                  >
                    {type.label}
                  </option>
                ))}
              </select>

              <ChevronDown
                size={18}
                className="pointer-events-none absolute right-3 top-3 text-gray-500"
              />

            </div>
          </div>

          {/* DETAIL TYPE */}

          <div>
            <label className="mb-2 block text-sm font-medium text-gray-900">
              Detail Type
            </label>

            <input
              type="text"
              value={form.detailType}
              onChange={(event) =>
                handleChange(
                  "detailType",
                  event.target.value
                )
              }
              placeholder="e.g. Current, Savings, Cash"
              className="h-11 w-full rounded-xl border border-gray-200 px-3 text-sm outline-none focus:border-orange-500 focus:ring-2 focus:ring-orange-100"
            />
          </div>

          {/* DESCRIPTION */}

          <div>
            <label className="mb-2 block text-sm font-medium text-gray-900">
              Description
            </label>

            <textarea
              value={form.description}
              onChange={(event) =>
                handleChange(
                  "description",
                  event.target.value
                )
              }
              placeholder="Account description"
              rows={3}
              className="w-full rounded-xl border border-gray-200 px-3 py-2 text-sm outline-none focus:border-orange-500 focus:ring-2 focus:ring-orange-100"
            />
          </div>

          {/* BUTTONS */}

          <div className="flex justify-end gap-2 pt-1">

            <button
              type="button"
              onClick={onClose}
              disabled={saving}
              className="rounded-xl border border-gray-200 px-5 py-2.5 text-sm font-medium text-gray-800 hover:bg-gray-50"
            >
              Cancel
            </button>

            <button
              type="submit"
              disabled={saving}
              className="rounded-xl bg-orange-500 px-5 py-2.5 text-sm font-semibold text-white hover:bg-orange-600 disabled:cursor-not-allowed disabled:opacity-60"
            >
              {saving
                ? "Saving..."
                : isEdit
                ? "Update Account"
                : "Create Account"}
            </button>

          </div>

        </form>
      </div>
    </div>
  );
}

/* =========================================================
   ACCOUNT TABLE
========================================================= */

function AccountsTable({
  accounts,
  onEdit,
  onToggleStatus,
}) {
  return (
    <div className="rounded-2xl border border-gray-300 bg-white shadow-sm">

      <div className="px-6 pb-3 pt-6">

        <h2 className="text-2xl font-bold text-gray-950">
          All Accounts ({accounts.length})
        </h2>

        <p className="mt-1 text-sm text-gray-500">
          View and manage all your business accounts
        </p>

      </div>

      <div className="overflow-x-auto px-5 pb-5">

        <table className="w-full min-w-[1000px] border-collapse">

          <thead>
            <tr className="border-b border-gray-300">

              <th className="px-4 py-4 text-left text-sm font-medium text-gray-600">
                Account Name
              </th>

              <th className="px-4 py-4 text-left text-sm font-medium text-gray-600">
                Type
              </th>

              <th className="px-4 py-4 text-left text-sm font-medium text-gray-600">
                Bank/Details
              </th>

              <th className="px-4 py-4 text-left text-sm font-medium text-gray-600">
                Balance
              </th>

              <th className="px-4 py-4 text-left text-sm font-medium text-gray-600">
                Status
              </th>

              <th className="px-4 py-4 text-left text-sm font-medium text-gray-600">
                Created By
              </th>

              <th className="px-4 py-4 text-left text-sm font-medium text-gray-600">
                Actions
              </th>

            </tr>
          </thead>

          <tbody>

            {accounts.map((account) => (

              <tr
                key={account.id}
                className="border-b border-gray-200 hover:bg-gray-50"
              >

                <td className="px-4 py-4">

                  <div className="font-medium text-gray-900">
                    {account.name}
                  </div>

                  {account.description && (
                    <div className="mt-1 max-w-[280px] truncate text-xs text-gray-500">
                      {account.description}
                    </div>
                  )}

                </td>

                <td className="px-4 py-4">

                  <span className="rounded-full bg-gray-100 px-3 py-1 text-xs font-medium text-gray-700">
                    {account.typeLabel ||
                      getTypeLabel(account.type)}
                  </span>

                </td>

                <td className="px-4 py-4 text-sm text-gray-700">
                  {account.detailType || "-"}
                </td>

                <td
                  className={`px-4 py-4 text-sm font-semibold ${
                    Number(account.balance) < 0
                      ? "text-red-600"
                      : "text-gray-900"
                  }`}
                >
                  {formatMoney(account.balance)}
                </td>

                <td className="px-4 py-4">

                  <span
                    className={`rounded-full px-3 py-1 text-xs font-medium ${
                      account.status === "Active"
                        ? "bg-orange-500 text-white"
                        : "bg-gray-200 text-gray-600"
                    }`}
                  >
                    {account.status}
                  </span>

                </td>

                <td className="px-4 py-4 text-sm italic text-gray-500">
                  {account.createdBy || "Unknown"}
                </td>

                <td className="px-4 py-4">

                  <div className="flex items-center gap-2">

                    <button
                      type="button"
                      onClick={() =>
                        onEdit(account)
                      }
                      title="Edit Account"
                      className="rounded-xl border border-gray-200 p-2 hover:bg-gray-100"
                    >
                      <Pencil size={16} />
                    </button>

                    <button
                      type="button"
                      onClick={() =>
                        onToggleStatus(account)
                      }
                      className="rounded-xl border border-gray-200 px-3 py-2 text-xs font-medium hover:bg-gray-100"
                    >
                      {account.status === "Active"
                        ? "Deactivate"
                        : "Activate"}
                    </button>

                  </div>

                </td>

              </tr>

            ))}

            {accounts.length === 0 && (
              <tr>

                <td
                  colSpan="7"
                  className="px-4 py-12 text-center text-sm text-gray-500"
                >
                  No accounts found.
                </td>

              </tr>
            )}

          </tbody>

        </table>

      </div>
    </div>
  );
}

/* =========================================================
   RECONCILIATION
========================================================= */

function Reconciliation({
  accounts,
  summary,
  loading,
  onRefresh,
}) {
  return (
    <div>

      {/* HEADER */}

      <div className="flex flex-col justify-between gap-4 md:flex-row md:items-center">

        <div>

          <h1 className="text-2xl font-bold text-gray-950">
            Account Balance Reconciliation
          </h1>

          <p className="text-sm text-gray-500">
            Compare stored vs calculated account balances
          </p>

        </div>

        <button
          type="button"
          onClick={onRefresh}
          disabled={loading}
          className="flex items-center justify-center gap-2 rounded-xl border border-gray-200 bg-white px-5 py-2.5 text-sm font-medium hover:bg-gray-50 disabled:opacity-50"
        >
          <RefreshCw
            size={17}
            className={
              loading
                ? "animate-spin"
                : ""
            }
          />

          Refresh
        </button>

      </div>

      {/* SUMMARY */}

      <div className="mt-5 grid gap-4 md:grid-cols-3">

        <div className="rounded-xl border border-gray-300 bg-white p-6">

          <p className="text-sm text-gray-500">
            Total Accounts
          </p>

          <p className="mt-2 text-3xl font-bold text-gray-950">
            {summary.totalAccounts}
          </p>

        </div>

        <div className="rounded-xl border border-gray-300 bg-white p-6">

          <p className="text-sm text-gray-500">
            With Variance
          </p>

          <p className="mt-2 text-3xl font-bold text-orange-500">
            {summary.withVariance}
          </p>

        </div>

        <div className="rounded-xl border border-gray-300 bg-white p-6">

          <p className="text-sm text-gray-500">
            Total Variance
          </p>

          <p className="mt-2 text-3xl font-bold text-red-500">
            {formatMoney(summary.totalVariance)}
          </p>

        </div>

      </div>

      {/* STATUS */}

      <div
        className={`mt-4 flex items-center gap-2 rounded-xl border px-4 py-4 text-sm ${
          summary.withVariance === 0
            ? "border-green-200 bg-green-50 text-green-700"
            : "border-red-200 bg-red-50 text-red-700"
        }`}
      >

        <CheckCircle2 size={19} />

        {summary.withVariance === 0
          ? "All account balances reconciled!"
          : `${summary.withVariance} account(s) have balance variance.`}

      </div>

      {/* TABLE */}

      <div className="mt-4 rounded-2xl border border-gray-300 bg-white shadow-sm">

        <div className="px-6 pb-4 pt-6">

          <h2 className="text-2xl font-bold text-gray-950">
            Account Balance Comparison
          </h2>

          <p className="mt-1 text-sm text-gray-500">
            Formula: Credits - Debits = Calculated Balance
          </p>

        </div>

        <div className="overflow-x-auto px-5 pb-5">

          <table className="w-full min-w-[1000px] border-collapse">

            <thead>

              <tr className="border-b border-gray-300">

                <th className="px-4 py-4 text-left text-sm font-medium text-gray-600">
                  Account
                </th>

                <th className="px-4 py-4 text-left text-sm font-medium text-gray-600">
                  Stored Balance
                </th>

                <th className="px-4 py-4 text-left text-sm font-medium text-gray-600">
                  Calculated Balance
                </th>

                <th className="px-4 py-4 text-left text-sm font-medium text-gray-600">
                  Variance
                </th>

                <th className="px-4 py-4 text-left text-sm font-medium text-gray-600">
                  Total Credits
                </th>

                <th className="px-4 py-4 text-left text-sm font-medium text-gray-600">
                  Total Debits
                </th>

              </tr>

            </thead>

            <tbody>

              {accounts.map((account) => {

                const variance =
                  Number(account.variance || 0);

                return (
                  <tr
                    key={account.accountId}
                    className="border-b border-gray-200 hover:bg-gray-50"
                  >

                    <td className="px-4 py-4">

                      <div className="font-medium text-gray-900">
                        {account.accountName}
                      </div>

                      <div className="text-xs text-gray-500">
                        {account.accountType}
                      </div>

                    </td>

                    <td className="px-4 py-4 font-mono text-sm">
                      {formatMoney(
                        account.storedBalance
                      )}
                    </td>

                    <td className="px-4 py-4 font-mono text-sm">
                      {formatMoney(
                        account.calculatedBalance
                      )}
                    </td>

                    <td
                      className={`px-4 py-4 font-mono text-sm font-medium ${
                        Math.abs(variance) > 0.01
                          ? "text-red-500"
                          : "text-green-600"
                      }`}
                    >
                      {formatMoney(variance)}
                    </td>

                    <td className="px-4 py-4 font-mono text-sm text-green-600">
                      {formatMoney(
                        account.totalCredits
                      )}
                    </td>

                    <td className="px-4 py-4 font-mono text-sm text-red-500">
                      {formatMoney(
                        account.totalDebits
                      )}
                    </td>

                  </tr>
                );
              })}

              {accounts.length === 0 && (
                <tr>

                  <td
                    colSpan="6"
                    className="px-4 py-12 text-center text-sm text-gray-500"
                  >
                    No reconciliation data found.
                  </td>

                </tr>
              )}

            </tbody>

          </table>

        </div>
      </div>

    </div>
  );
}

/* =========================================================
   MAIN ACCOUNTS PAGE
========================================================= */

export default function Accounts() {

  const [activeTab, setActiveTab] =
    useState("accounts");

  const [accounts, setAccounts] =
    useState([]);

  const [reconciliation, setReconciliation] =
    useState([]);

  const [summary, setSummary] =
    useState({
      totalAccounts: 0,
      withVariance: 0,
      totalVariance: 0,
    });

  const [showModal, setShowModal] =
    useState(false);

  const [editingAccount, setEditingAccount] =
    useState(null);

  const [search, setSearch] =
    useState("");

  const [typeFilter, setTypeFilter] =
    useState("all");

  const [loading, setLoading] =
    useState(false);

  const [saving, setSaving] =
    useState(false);

  const [error, setError] =
    useState("");

  /* =======================================================
     LOAD ACCOUNTS
  ======================================================= */

  const loadAccounts = async () => {

    try {

      setLoading(true);
      setError("");

      const response = await axios.get(
        `${API_URL}/account`
      );

      if (response.data.success) {

        setAccounts(
          response.data.accounts || []
        );

      } else {

        setError(
          response.data.message ||
            "Failed to load accounts"
        );
      }

    } catch (err) {

      console.error(
        "LOAD ACCOUNTS ERROR:",
        err
      );

      setError(
        err.response?.data?.message ||
          "Cannot connect to server"
      );

    } finally {

      setLoading(false);

    }
  };

  /* =======================================================
     LOAD RECONCILIATION
  ======================================================= */

  const loadReconciliation = async () => {

    try {

      setLoading(true);
      setError("");

      const response = await axios.get(
        `${API_URL}/accounts/reconciliation`
      );

      if (response.data.success) {

        setReconciliation(
          response.data.accounts || []
        );

        setSummary(
          response.data.summary || {
            totalAccounts: 0,
            withVariance: 0,
            totalVariance: 0,
          }
        );

      } else {

        setError(
          response.data.message ||
            "Failed to load reconciliation"
        );
      }

    } catch (err) {

      console.error(
        "RECONCILIATION ERROR:",
        err
      );

      setError(
        err.response?.data?.message ||
          "Cannot load reconciliation"
      );

    } finally {

      setLoading(false);

    }
  };

  /* =======================================================
     INITIAL LOAD
  ======================================================= */

  useEffect(() => {

    loadAccounts();

  }, []);

  /* =======================================================
     FILTER ACCOUNTS
  ======================================================= */

  const filteredAccounts = useMemo(() => {

    const searchText =
      search.trim().toLowerCase();

    return accounts.filter((account) => {

      const matchesSearch =
        !searchText ||
        account.name
          ?.toLowerCase()
          .includes(searchText) ||
        account.typeLabel
          ?.toLowerCase()
          .includes(searchText) ||
        account.detailType
          ?.toLowerCase()
          .includes(searchText);

      const matchesType =
        typeFilter === "all" ||
        account.type === typeFilter;

      return (
        matchesSearch &&
        matchesType
      );
    });

  }, [
    accounts,
    search,
    typeFilter,
  ]);

  /* =======================================================
     CREATE ACCOUNT
  ======================================================= */

  const createAccount = async (form) => {

    try {

      setSaving(true);

      const response = await axios.post(
        `${API_URL}/accounts`,
        {
          name: form.name.trim(),
          type: form.type,
          detailType:
            form.detailType.trim(),
          description:
            form.description.trim(),
          createdBy: "Admin",
        }
      );

      if (!response.data.success) {

        throw new Error(
          response.data.message ||
            "Failed to create account"
        );
      }

      setShowModal(false);

      await loadAccounts();

      alert(
        "Account created successfully."
      );

    } catch (err) {

      console.error(
        "CREATE ACCOUNT ERROR:",
        err
      );

      alert(
        err.response?.data?.message ||
          err.message ||
          "Failed to create account"
      );

    } finally {

      setSaving(false);

    }
  };

  /* =======================================================
     UPDATE ACCOUNT
  ======================================================= */

  const updateAccount = async (form) => {

    if (!editingAccount) return;

    try {

      setSaving(true);

      const response = await axios.put(
        `${API_URL}/accounts/${editingAccount.id}`,
        {
          name: form.name.trim(),
          type: form.type,
          detailType:
            form.detailType.trim(),
          description:
            form.description.trim(),
          modifiedBy: "Admin",
        }
      );

      if (!response.data.success) {

        throw new Error(
          response.data.message ||
            "Failed to update account"
        );
      }

      setShowModal(false);
      setEditingAccount(null);

      await loadAccounts();

      alert(
        "Account updated successfully."
      );

    } catch (err) {

      console.error(
        "UPDATE ACCOUNT ERROR:",
        err
      );

      alert(
        err.response?.data?.message ||
          err.message ||
          "Failed to update account"
      );

    } finally {

      setSaving(false);

    }
  };

  /* =======================================================
     SAVE ACCOUNT
  ======================================================= */

  const handleSaveAccount = async (form) => {

    if (editingAccount) {

      await updateAccount(form);

    } else {

      await createAccount(form);

    }
  };

  /* =======================================================
     TOGGLE STATUS
  ======================================================= */

  const toggleStatus = async (account) => {

    const isActive =
      account.status !== "Active";

    try {

      setLoading(true);

      const response = await axios.put(
        `${API_URL}/accounts/${account.id}/status`,
        {
          isActive,
        }
      );

      if (!response.data.success) {

        throw new Error(
          response.data.message ||
            "Failed to update status"
        );
      }

      await loadAccounts();

    } catch (err) {

      console.error(
        "STATUS ERROR:",
        err
      );

      alert(
        err.response?.data?.message ||
          err.message ||
          "Failed to update status"
      );

      setLoading(false);
    }
  };

  /* =======================================================
     OPEN CREATE
  ======================================================= */

  const openCreateModal = () => {

    setEditingAccount(null);
    setShowModal(true);

  };

  /* =======================================================
     OPEN EDIT
  ======================================================= */

  const openEditModal = (account) => {

    setEditingAccount(account);
    setShowModal(true);

  };

  /* =======================================================
     CLOSE MODAL
  ======================================================= */

  const closeModal = () => {

    if (saving) return;

    setShowModal(false);
    setEditingAccount(null);

  };

  /* =======================================================
     DOWNLOAD CSV TEMPLATE
  ======================================================= */

  const downloadTemplate = () => {

    const csv = [
      "Account Name,Account Type,Detail Type,Description",
      "HNB OUTLET,Bank Account,HNB BANK,Main bank account",
      "Cash Counter 01,Cash on Hand,Cash,Main cash counter",
      "Main Bank Account,Bank Account,Savings,Business bank",
    ].join("\n");

    const blob = new Blob(
      [csv],
      {
        type: "text/csv;charset=utf-8;",
      }
    );

    const url =
      URL.createObjectURL(blob);

    const link =
      document.createElement("a");

    link.href = url;
    link.download =
      "accounts_template.csv";

    document.body.appendChild(link);

    link.click();

    document.body.removeChild(link);

    URL.revokeObjectURL(url);
  };

  /* =======================================================
     IMPORT
  ======================================================= */

  const handleImport = (event) => {

    const file =
      event.target.files?.[0];

    if (!file) return;

    alert(
      `Selected file: ${file.name}\n\nCSV/Excel import API can be connected here.`
    );

    event.target.value = "";
  };

  /* =======================================================
     TAB CHANGE
  ======================================================= */

  const changeTab = (tab) => {

    setActiveTab(tab);

    if (tab === "reconciliation") {

      loadReconciliation();

    }
  };

  /* =======================================================
     RENDER
  ======================================================= */

  return (
    <div className="min-h-screen bg-white px-6 py-6 md:px-8">

      {/* =================================================
          HEADER
      ================================================= */}

      <div>

        <h1 className="text-3xl font-bold text-gray-950">
          Accounts Management
        </h1>

        <p className="mt-1 text-base text-gray-500">
          Manage your business accounts and track balances
        </p>

      </div>

      {/* =================================================
          TABS
      ================================================= */}

      <div className="mt-5 inline-flex rounded-xl bg-gray-100 p-1">

        <button
          type="button"
          onClick={() =>
            changeTab("accounts")
          }
          className={`rounded-lg px-4 py-2 text-sm font-medium ${
            activeTab === "accounts"
              ? "bg-white text-gray-950 shadow-sm"
              : "text-gray-600 hover:text-gray-900"
          }`}
        >
          Accounts
        </button>

        <button
          type="button"
          onClick={() =>
            changeTab("reconciliation")
          }
          className={`rounded-lg px-4 py-2 text-sm font-medium ${
            activeTab === "reconciliation"
              ? "bg-white text-gray-950 shadow-sm"
              : "text-gray-600 hover:text-gray-900"
          }`}
        >
          Account Reconciliation
        </button>

      </div>

      {/* =================================================
          ERROR
      ================================================= */}

      {error && (
        <div className="mt-5 flex items-center justify-between rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">

          <span>{error}</span>

          <button
            type="button"
            onClick={() => setError("")}
            className="font-bold"
          >
            ×
          </button>

        </div>
      )}

      {/* =================================================
          ACCOUNTS TAB
      ================================================= */}

      {activeTab === "accounts" && (
        <>

          {/* TOOLBAR */}

          <div className="mt-6 flex flex-wrap gap-2">

            <button
              type="button"
              onClick={downloadTemplate}
              className="flex items-center gap-2 rounded-xl border border-gray-200 bg-white px-4 py-2.5 text-sm font-medium hover:bg-gray-50"
            >
              <Download size={17} />
              Download Template
            </button>

            <label className="flex cursor-pointer items-center gap-2 rounded-xl border border-gray-200 bg-white px-4 py-2.5 text-sm font-medium hover:bg-gray-50">

              <Upload size={17} />

              Import Accounts

              <input
                type="file"
                accept=".csv,.xlsx,.xls"
                onChange={handleImport}
                className="hidden"
              />

            </label>

            <button
              type="button"
              onClick={openCreateModal}
              className="flex items-center gap-2 rounded-xl bg-orange-500 px-5 py-2.5 text-sm font-semibold text-white hover:bg-orange-600"
            >
              <Plus size={18} />
              Add Account
            </button>

            <button
              type="button"
              onClick={loadAccounts}
              disabled={loading}
              className="flex items-center gap-2 rounded-xl border border-gray-200 bg-white px-4 py-2.5 text-sm font-medium hover:bg-gray-50 disabled:opacity-50"
            >
              <RefreshCw
                size={17}
                className={
                  loading
                    ? "animate-spin"
                    : ""
                }
              />
              Refresh
            </button>

          </div>

          {/* FILTERS */}

          <div className="mt-6 rounded-2xl border border-gray-300 bg-white p-6 shadow-sm">

            <div className="mb-6 flex items-center gap-2">

              <Filter size={21} />

              <h2 className="text-xl font-bold text-gray-900">
                Filters
              </h2>

            </div>

            <div className="grid gap-4 md:grid-cols-2">

              {/* TYPE */}

              <div>

                <label className="mb-2 block text-sm font-medium text-gray-900">
                  Account Type
                </label>

                <div className="relative">

                  <select
                    value={typeFilter}
                    onChange={(event) =>
                      setTypeFilter(
                        event.target.value
                      )
                    }
                    className="h-11 w-full appearance-none rounded-xl border border-gray-200 bg-white px-3 text-sm outline-none focus:border-orange-500"
                  >

                    <option value="all">
                      All Types
                    </option>

                    {ACCOUNT_TYPES.map(
                      (type) => (
                        <option
                          key={type.value}
                          value={type.value}
                        >
                          {type.label}
                        </option>
                      )
                    )}

                  </select>

                  <ChevronDown
                    size={18}
                    className="pointer-events-none absolute right-3 top-3 text-gray-500"
                  />

                </div>

              </div>

              {/* SEARCH */}

              <div>

                <label className="mb-2 block text-sm font-medium text-gray-900">
                  Search
                </label>

                <div className="relative">

                  <Search
                    size={18}
                    className="absolute left-3 top-3 text-gray-500"
                  />

                  <input
                    type="text"
                    value={search}
                    onChange={(event) =>
                      setSearch(
                        event.target.value
                      )
                    }
                    placeholder="Search accounts..."
                    className="h-11 w-full rounded-xl border border-gray-200 pl-10 pr-3 text-sm outline-none focus:border-orange-500"
                  />

                </div>

              </div>

            </div>

          </div>

          {/* ACCOUNT CARDS */}

          <div className="mt-6 grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">

            {ACCOUNT_TYPES.map((type) => {

              const typeAccounts =
                accounts.filter(
                  (account) =>
                    account.type ===
                    type.value
                );

              return (
                <AccountCard
                  key={type.value}
                  type={type}
                  accounts={typeAccounts}
                />
              );
            })}

          </div>

          {/* TABLE */}

          <div className="mt-6">

            {loading && accounts.length === 0 ? (

              <div className="rounded-2xl border border-gray-300 bg-white py-16 text-center">

                <RefreshCw
                  size={30}
                  className="mx-auto animate-spin text-orange-500"
                />

                <p className="mt-3 text-sm text-gray-500">
                  Loading accounts...
                </p>

              </div>

            ) : (

              <AccountsTable
                accounts={
                  filteredAccounts
                }
                onEdit={
                  openEditModal
                }
                onToggleStatus={
                  toggleStatus
                }
              />

            )}

          </div>

        </>
      )}

      {/* =================================================
          RECONCILIATION TAB
      ================================================= */}

      {activeTab === "reconciliation" && (
        <div className="mt-6">

          <Reconciliation
            accounts={
              reconciliation
            }
            summary={summary}
            loading={loading}
            onRefresh={
              loadReconciliation
            }
          />

        </div>
      )}

      {/* =================================================
          MODAL
      ================================================= */}

      {showModal && (
        <AccountModal
          account={editingAccount}
          onClose={closeModal}
          onSave={
            handleSaveAccount
          }
          saving={saving}
        />
      )}

    </div>
  );
}