import React, { useEffect, useMemo, useRef, useState } from "react";
import {
  AlignCenter,
  AlignLeft,
  AlignRight,
  Barcode,
  Eye,
  Grid3X3,
  Move,
  Printer,
  RotateCcw,
  Save,
  Settings2,
  Trash2,
} from "lucide-react";
import axios from "axios";

const API = "http://localhost:5000";

const PAGE_PRESETS = [
  { name: "80 × 50 mm", width: 80, height: 50 },
  { name: "100 × 60 mm", width: 100, height: 60 },
  { name: "120 × 70 mm", width: 120, height: 70 },
  { name: "A6", width: 148, height: 105 },
  { name: "210 × 99 mm", width: 210, height: 99 },
];

const ELEMENT_DEFINITIONS = {
  title: {
    label: "Gift Voucher",
    type: "text",
    text: "GIFT VOUCHER",
  },
  voucherType: {
    label: "Voucher Type",
    type: "text",
    text: "{VoucherType}",
  },
  voucherValue: {
    label: "Voucher Value",
    type: "text",
    text: "Rs. {VoucherValue}",
  },
  voucherNo: {
    label: "Voucher No",
    type: "text",
    text: "{VoucherNo}",
  },
  serial: {
    label: "Voucher Serial",
    type: "text",
    text: "{VoucherSerial}",
  },
  barcode: {
    label: "Barcode",
    type: "barcode",
    text: "{VoucherSerial}",
  },
  expiryDate: {
    label: "Expiry Date",
    type: "text",
    text: "Valid Until: {ExpiryDate}",
  },
  status: {
    label: "Status",
    type: "text",
    text: "Status: {Status}",
  },
  footer: {
    label: "Footer",
    type: "text",
    text: "Thank you for choosing us!",
  },
};

const createElement = (id, x = 10, y = 10) => ({
  id,
  ...ELEMENT_DEFINITIONS[id],
  x,
  y,
  width: id === "barcode" ? 60 : 70,
  height: id === "barcode" ? 15 : 10,
  fontSize:
    id === "title"
      ? 18
      : id === "voucherValue"
        ? 20
        : 10,
  bold:
    id === "title" ||
    id === "voucherValue" ||
    id === "voucherNo",
  align: "center",
  visible: true,
});

const DEFAULT_LAYOUT = {
  page: {
    width: 100,
    height: 60,
    unit: "mm",
    orientation: "landscape",
    gridSize: 5,
    showGrid: true,
    snapToGrid: true,
    zoom: 100,
    border: true,
  },

  elements: [
    createElement("title", 15, 5),
    createElement("voucherType", 15, 16),
    createElement("voucherValue", 15, 26),
    createElement("voucherNo", 15, 39),
    createElement("serial", 15, 48),
    createElement("barcode", 20, 57),
    createElement("expiryDate", 15, 75),
    createElement("status", 15, 84),
    createElement("footer", 15, 94),
  ],
};

const SAMPLE_VOUCHER = {
  VoucherType: "Gift Voucher",
  VoucherValue: 1000,
  VoucherNo: "GV-000001",
  VoucherSerial: "123456789012",
  ExpiryDate: "31/12/2026",
  Status: "Available",
};

function replaceVariables(text, voucher) {
  if (!text) return "";

  return text
    .replaceAll(
      "{VoucherType}",
      voucher.VoucherType ?? ""
    )
    .replaceAll(
      "{VoucherValue}",
      Number(voucher.VoucherValue ?? 0).toFixed(2)
    )
    .replaceAll(
      "{VoucherNo}",
      voucher.VoucherNo ?? ""
    )
    .replaceAll(
      "{VoucherSerial}",
      voucher.VoucherSerial ?? ""
    )
    .replaceAll(
      "{ExpiryDate}",
      voucher.ExpiryDate ?? ""
    )
    .replaceAll(
      "{Status}",
      voucher.Status ?? ""
    );
}

function VoucherTemplate({
  voucherTypeId = 1,
  voucher = SAMPLE_VOUCHER,
}) {
  const [layout, setLayout] =
    useState(DEFAULT_LAYOUT);

  const [selectedId, setSelectedId] =
    useState("title");

  const [message, setMessage] =
    useState("");

  const [loading, setLoading] =
    useState(false);

  const canvasRef = useRef(null);

  const selectedElement = useMemo(
    () =>
      layout.elements.find(
        item => item.id === selectedId
      ),
    [layout.elements, selectedId]
  );

  /*
   * --------------------------------------------------
   * Load layout
   * --------------------------------------------------
   */

  useEffect(() => {
    if (!voucherTypeId) return;

    loadLayout();
  }, [voucherTypeId]);

  const loadLayout = async () => {
    try {
      setLoading(true);

      const response = await axios.get(
        `${API}/voucher-templates/${voucherTypeId}`
      );

      if (response.data?.layout) {
        setLayout(
          typeof response.data.layout === "string"
            ? JSON.parse(response.data.layout)
            : response.data.layout
        );
      }
    } catch (error) {
      if (error.response?.status !== 404) {
        console.error(
          "Unable to load voucher template",
          error
        );
      }
    } finally {
      setLoading(false);
    }
  };

  /*
   * --------------------------------------------------
   * Save
   * --------------------------------------------------
   */

  const saveLayout = async () => {
    if (!voucherTypeId) {
      setMessage(
        "Please select a voucher type first."
      );
      return;
    }

    try {
      setLoading(true);

      await axios.post(
        `${API}/voucher-templates`,
        {
          voucherTypeId,
          layout,
        }
      );

      setMessage(
        "Voucher template saved successfully."
      );
    } catch (error) {
      console.error(error);

      setMessage(
        error.response?.data?.message ||
          "Unable to save voucher template."
      );
    } finally {
      setLoading(false);

      setTimeout(() => {
        setMessage("");
      }, 3000);
    }
  };

  /*
   * --------------------------------------------------
   * Update page
   * --------------------------------------------------
   */

  const updatePage = (field, value) => {
    setLayout(previous => ({
      ...previous,
      page: {
        ...previous.page,
        [field]: value,
      },
    }));
  };

  /*
   * --------------------------------------------------
   * Update element
   * --------------------------------------------------
   */

  const updateElement = (id, field, value) => {
    setLayout(previous => ({
      ...previous,
      elements: previous.elements.map(
        element =>
          element.id === id
            ? {
                ...element,
                [field]: value,
              }
            : element
      ),
    }));
  };

  /*
   * --------------------------------------------------
   * Add element
   * --------------------------------------------------
   */

  const addElement = id => {
    if (
      layout.elements.some(
        element => element.id === id
      )
    ) {
      setSelectedId(id);
      return;
    }

    const element = createElement(
      id,
      10,
      10
    );

    setLayout(previous => ({
      ...previous,
      elements: [
        ...previous.elements,
        element,
      ],
    }));

    setSelectedId(id);
  };

  /*
   * --------------------------------------------------
   * Delete element
   * --------------------------------------------------
   */

  const deleteElement = id => {
    setLayout(previous => ({
      ...previous,
      elements: previous.elements.filter(
        element => element.id !== id
      ),
    }));

    if (selectedId === id) {
      setSelectedId(null);
    }
  };

  /*
   * --------------------------------------------------
   * Drag/drop from palette
   * --------------------------------------------------
   */

  const handlePaletteDragStart = (
    event,
    id
  ) => {
    event.dataTransfer.setData(
      "voucher-element",
      id
    );
  };

  const handleCanvasDrop = event => {
    event.preventDefault();

    const id =
      event.dataTransfer.getData(
        "voucher-element"
      );

    if (!id || !canvasRef.current) return;

    const rect =
      canvasRef.current.getBoundingClientRect();

    const pageWidth =
      layout.page.width;

    const pageHeight =
      layout.page.height;

    const scale =
      rect.width / pageWidth;

    let x =
      (event.clientX - rect.left) / scale;

    let y =
      (event.clientY - rect.top) / scale;

    if (layout.page.snapToGrid) {
      const grid =
        Number(layout.page.gridSize) || 1;

      x = Math.round(x / grid) * grid;
      y = Math.round(y / grid) * grid;
    }

    const existing =
      layout.elements.find(
        element => element.id === id
      );

    if (existing) {
      updateElement(id, "x", x);
      updateElement(id, "y", y);
      setSelectedId(id);
      return;
    }

    const element = createElement(
      id,
      x,
      y
    );

    setLayout(previous => ({
      ...previous,
      elements: [
        ...previous.elements,
        element,
      ],
    }));

    setSelectedId(id);
  };

  /*
   * --------------------------------------------------
   * Drag existing element
   * --------------------------------------------------
   */

  const handlePointerDown = (
    event,
    element
  ) => {
    event.preventDefault();
    event.stopPropagation();

    setSelectedId(element.id);

    const canvas =
      canvasRef.current;

    if (!canvas) return;

    const rect =
      canvas.getBoundingClientRect();

    const scale =
      rect.width / layout.page.width;

    const startX =
      event.clientX;

    const startY =
      event.clientY;

    const originalX =
      element.x;

    const originalY =
      element.y;

    const move = moveEvent => {
      let x =
        originalX +
        (moveEvent.clientX - startX) /
          scale;

      let y =
        originalY +
        (moveEvent.clientY - startY) /
          scale;

      if (layout.page.snapToGrid) {
        const grid =
          Number(layout.page.gridSize) ||
          1;

        x =
          Math.round(x / grid) * grid;

        y =
          Math.round(y / grid) * grid;
      }

      x = Math.max(
        0,
        Math.min(
          layout.page.width -
            element.width,
          x
        )
      );

      y = Math.max(
        0,
        Math.min(
          layout.page.height -
            element.height,
          y
        )
      );

      updateElement(
        element.id,
        "x",
        Number(x.toFixed(2))
      );

      updateElement(
        element.id,
        "y",
        Number(y.toFixed(2))
      );
    };

    const up = () => {
      window.removeEventListener(
        "pointermove",
        move
      );

      window.removeEventListener(
        "pointerup",
        up
      );
    };

    window.addEventListener(
      "pointermove",
      move
    );

    window.addEventListener(
      "pointerup",
      up
    );
  };

  /*
   * --------------------------------------------------
   * Reset
   * --------------------------------------------------
   */

  const resetLayout = () => {
    setLayout(
      JSON.parse(
        JSON.stringify(DEFAULT_LAYOUT)
      )
    );

    setSelectedId("title");
  };

  /*
   * --------------------------------------------------
   * Page preset
   * --------------------------------------------------
   */

  const applyPreset = event => {
    const value =
      event.target.value;

    if (!value) return;

    const preset =
      PAGE_PRESETS.find(
        item => item.name === value
      );

    if (!preset) return;

    updatePage(
      "width",
      preset.width
    );

    updatePage(
      "height",
      preset.height
    );

    updatePage(
      "unit",
      "mm"
    );
  };

  /*
   * --------------------------------------------------
   * Print
   * --------------------------------------------------
   */

  const printVoucher = () => {
    const printWindow =
      window.open(
        "",
        "_blank",
        "width=900,height=700"
      );

    if (!printWindow) return;

    const pageWidth =
      layout.page.width;

    const pageHeight =
      layout.page.height;

    const unit =
      layout.page.unit;

    const elements =
      layout.elements
        .filter(
          element => element.visible
        )
        .map(element => {

          const text =
            replaceVariables(
              element.text,
              voucher
            );

          const align =
            element.align || "center";

          if (
            element.type === "barcode"
          ) {
            return `
              <div
                style="
                  position:absolute;
                  left:${element.x}${unit};
                  top:${element.y}${unit};
                  width:${element.width}${unit};
                  height:${element.height}${unit};
                  display:flex;
                  align-items:center;
                  justify-content:${getJustify(
                    align
                  )};
                  overflow:hidden;
                "
              >
                <div
                  style="
                    font-family:monospace;
                    font-size:${element.fontSize}px;
                    letter-spacing:3px;
                    white-space:nowrap;
                  "
                >
                  || ${voucher.VoucherSerial} ||
                </div>
              </div>
            `;
          }

          return `
            <div
              style="
                position:absolute;
                left:${element.x}${unit};
                top:${element.y}${unit};
                width:${element.width}${unit};
                height:${element.height}${unit};
                display:flex;
                align-items:center;
                justify-content:${getJustify(
                  align
                )};
                overflow:hidden;
                font-size:${element.fontSize}px;
                font-weight:${
                  element.bold
                    ? 700
                    : 400
                };
                text-align:${align};
                white-space:nowrap;
              "
            >
              ${escapeHtml(text)}
            </div>
          `;
        })
        .join("");

    printWindow.document.write(`
      <!DOCTYPE html>
      <html>
      <head>

        <title>Gift Voucher</title>

        <style>

          @page {
            size:
              ${pageWidth}${unit}
              ${pageHeight}${unit};
            margin:0;
          }

          html,
          body {
            margin:0;
            padding:0;
          }

          .voucher-page {
            position:relative;
            width:${pageWidth}${unit};
            height:${pageHeight}${unit};
            overflow:hidden;
            ${
              layout.page.border
                ? "border:1px solid #000;"
                : ""
            }
          }

        </style>

      </head>

      <body>

        <div class="voucher-page">
          ${elements}
        </div>

        <script>
          window.onload = function() {
            window.print();
          };
        </script>

      </body>
      </html>
    `);

    printWindow.document.close();
  };

  const scale =
    layout.page.zoom / 100;

  const canvasWidth =
    layout.page.width *
    3 *
    scale;

  const canvasHeight =
    layout.page.height *
    3 *
    scale;

  return (
    <div className="bg-white rounded-xl shadow p-5">

      {/* HEADER */}

      <div className="
        flex
        flex-wrap
        items-center
        justify-between
        gap-3
        mb-5
      ">

        <div>
          <h2 className="
            text-xl
            font-bold
            text-gray-800
          ">
            Voucher Layout Design
          </h2>

          <p className="
            text-sm
            text-gray-500
            mt-1
          ">
            Drag voucher fields onto the page,
            position them and customize the layout.
          </p>
        </div>

        <div className="flex gap-2">

          <button
            onClick={resetLayout}
            className="
              px-4 py-2
              border rounded-lg
              hover:bg-gray-50
            "
          >
            <RotateCcw
              size={16}
              className="inline mr-2"
            />
            Reset
          </button>

          <button
            onClick={saveLayout}
            disabled={loading}
            className="
              px-4 py-2
              bg-blue-600
              text-white
              rounded-lg
              hover:bg-blue-700
              disabled:opacity-50
            "
          >
            <Save
              size={16}
              className="inline mr-2"
            />
            {loading
              ? "Saving..."
              : "Save Layout"}
          </button>

          <button
            onClick={printVoucher}
            className="
              px-4 py-2
              bg-orange-500
              text-white
              rounded-lg
              hover:bg-orange-600
            "
          >
            <Printer
              size={16}
              className="inline mr-2"
            />
            Print
          </button>

        </div>

      </div>

      {message && (
        <div className="
          mb-4
          px-4 py-3
          rounded-lg
          bg-green-50
          border border-green-200
          text-green-700
        ">
          {message}
        </div>
      )}

      <div className="
        grid
        grid-cols-1
        xl:grid-cols-[230px_minmax(500px,1fr)_280px]
        gap-5
      ">

        {/* ELEMENT PALETTE */}

        <div className="
          border
          rounded-xl
          p-4
        ">

          <h3 className="
            font-semibold
            mb-3
          ">
            Elements
          </h3>

          <div className="space-y-2">

            {Object.entries(
              ELEMENT_DEFINITIONS
            ).map(([id, definition]) => (

              <div
                key={id}
                draggable
                onDragStart={event =>
                  handlePaletteDragStart(
                    event,
                    id
                  )
                }
                onClick={() =>
                  addElement(id)
                }
                className="
                  flex
                  items-center
                  gap-2
                  px-3
                  py-3
                  border
                  rounded-lg
                  cursor-grab
                  hover:bg-gray-50
                  hover:border-blue-400
                "
              >

                {definition.type ===
                "barcode" ? (
                  <Barcode size={17} />
                ) : (
                  <Move size={17} />
                )}

                <span className="text-sm">
                  {definition.label}
                </span>

              </div>

            ))}

          </div>

          <div className="
            mt-5
            p-3
            bg-blue-50
            rounded-lg
            text-xs
            text-blue-700
          ">
            Drag an element onto the voucher
            page or click it to add it.
          </div>

        </div>


        {/* DESIGN CANVAS */}

        <div className="
          border
          rounded-xl
          p-5
          bg-gray-100
          overflow-auto
        ">

          <div className="
            flex
            justify-center
            items-start
            min-h-[600px]
          ">

            <div
              ref={canvasRef}
              onDragOver={event =>
                event.preventDefault()
              }
              onDrop={handleCanvasDrop}
              className="
                relative
                bg-white
                shadow-xl
              "
              style={{
                width: `${canvasWidth}px`,
                height: `${canvasHeight}px`,
                border: layout.page.border
                  ? "1px solid #555"
                  : "none",

                backgroundImage:
                  layout.page.showGrid
                    ? `
                      linear-gradient(
                        to right,
                        #e5e7eb 1px,
                        transparent 1px
                      ),
                      linear-gradient(
                        to bottom,
                        #e5e7eb 1px,
                        transparent 1px
                      )
                    `
                    : "none",

                backgroundSize: `
                  ${
                    layout.page.gridSize *
                    3 *
                    scale
                  }px
                  ${
                    layout.page.gridSize *
                    3 *
                    scale
                  }px
                `,
              }}
            >

              {layout.elements.map(
                element => {

                  if (
                    !element.visible
                  ) {
                    return null;
                  }

                  const selected =
                    element.id ===
                    selectedId;

                  return (
                    <div
                      key={element.id}
                      onPointerDown={event =>
                        handlePointerDown(
                          event,
                          element
                        )
                      }
                      onClick={() =>
                        setSelectedId(
                          element.id
                        )
                      }
                      className={`
                        absolute
                        flex
                        items-center
                        px-1
                        overflow-hidden
                        select-none
                        cursor-move
                        rounded
                        ${
                          selected
                            ? "ring-2 ring-blue-500 bg-blue-50/70"
                            : "hover:ring-1 hover:ring-gray-300"
                        }
                      `}
                      style={{
                        left:
                          element.x *
                          3 *
                          scale,

                        top:
                          element.y *
                          3 *
                          scale,

                        width:
                          element.width *
                          3 *
                          scale,

                        height:
                          element.height *
                          3 *
                          scale,

                        justifyContent:
                          getJustify(
                            element.align
                          ),

                        textAlign:
                          element.align,

                        fontSize:
                          element.fontSize,

                        fontWeight:
                          element.bold
                            ? 700
                            : 400,
                      }}
                    >

                      {element.type ===
                      "barcode" ? (

                        <div className="
                          font-mono
                          tracking-[3px]
                          text-xs
                          whitespace-nowrap
                        ">
                          ||{" "}
                          {
                            voucher.VoucherSerial
                          }{" "}
                          ||
                        </div>

                      ) : (

                        replaceVariables(
                          element.text,
                          voucher
                        )

                      )}

                    </div>
                  );
                }
              )}

            </div>

          </div>

          <div className="
            flex
            justify-center
            gap-2
            mt-3
            text-sm
            text-gray-500
          ">
            <Eye size={16} />

            Live Preview

            <span>
              {layout.page.width} ×{" "}
              {layout.page.height}{" "}
              {layout.page.unit}
            </span>
          </div>

        </div>


        {/* SETTINGS */}

        <div className="
          border
          rounded-xl
          p-4
          space-y-5
        ">

          <div className="
            flex
            items-center
            gap-2
            font-semibold
          ">
            <Settings2 size={18} />
            Page Settings
          </div>


          {/* PAGE SIZE */}

          <div>

            <label className="
              text-xs
              text-gray-500
              block mb-1
            ">
              Preset
            </label>

            <select
              defaultValue=""
              onChange={applyPreset}
              className="
                w-full
                border
                rounded-lg
                px-3
                py-2
              "
            >

              <option value="">
                Custom
              </option>

              {PAGE_PRESETS.map(
                preset => (
                  <option
                    key={preset.name}
                    value={preset.name}
                  >
                    {preset.name}
                  </option>
                )
              )}

            </select>

          </div>


          <div className="
            grid
            grid-cols-2
            gap-2
          ">

            <NumberInput
              label="Width"
              value={layout.page.width}
              onChange={value =>
                updatePage(
                  "width",
                  value
                )
              }
            />

            <NumberInput
              label="Height"
              value={layout.page.height}
              onChange={value =>
                updatePage(
                  "height",
                  value
                )
              }
            />

          </div>


          <div>

            <label className="
              text-xs
              text-gray-500
              block mb-1
            ">
              Unit
            </label>

            <select
              value={layout.page.unit}
              onChange={event =>
                updatePage(
                  "unit",
                  event.target.value
                )
              }
              className="
                w-full
                border
                rounded-lg
                px-3 py-2
              "
            >

              <option value="mm">
                Millimetres
              </option>

              <option value="px">
                Pixels
              </option>

            </select>

          </div>


          <div>

            <label className="
              text-xs
              text-gray-500
              block mb-1
            ">
              Orientation
            </label>

            <select
              value={
                layout.page.orientation
              }
              onChange={event =>
                updatePage(
                  "orientation",
                  event.target.value
                )
              }
              className="
                w-full
                border
                rounded-lg
                px-3 py-2
              "
            >

              <option value="landscape">
                Landscape
              </option>

              <option value="portrait">
                Portrait
              </option>

            </select>

          </div>


          {/* GRID */}

          <div className="
            border-t
            pt-4
          ">

            <div className="
              flex
              items-center
              gap-2
              font-semibold
              mb-3
            ">
              <Grid3X3 size={17} />
              Grid
            </div>

            <label className="
              flex
              gap-2
              text-sm
              mb-2
            ">

              <input
                type="checkbox"
                checked={
                  layout.page.showGrid
                }
                onChange={event =>
                  updatePage(
                    "showGrid",
                    event.target.checked
                  )
                }
              />

              Show grid

            </label>

            <label className="
              flex
              gap-2
              text-sm
            ">

              <input
                type="checkbox"
                checked={
                  layout.page.snapToGrid
                }
                onChange={event =>
                  updatePage(
                    "snapToGrid",
                    event.target.checked
                  )
                }
              />

              Snap to grid

            </label>

            <NumberInput
              label="Grid size"
              value={
                layout.page.gridSize
              }
              onChange={value =>
                updatePage(
                  "gridSize",
                  value
                )
              }
            />

          </div>


          {/* ZOOM */}

          <div>

            <label className="
              text-xs
              text-gray-500
              block mb-1
            ">
              Zoom: {layout.page.zoom}%
            </label>

            <input
              type="range"
              min="50"
              max="200"
              step="10"
              value={
                layout.page.zoom
              }
              onChange={event =>
                updatePage(
                  "zoom",
                  Number(
                    event.target.value
                  )
                )
              }
              className="w-full"
            />

          </div>


          {/* ELEMENT SETTINGS */}

          {selectedElement && (

            <div className="
              border-t
              pt-4
            ">

              <div className="
                font-semibold
                mb-3
              ">
                Element Settings
              </div>


              <div className="
                text-sm
                font-medium
                mb-3
              ">
                {selectedElement.label}
              </div>


              {/* X/Y */}

              <div className="
                grid
                grid-cols-2
                gap-2
              ">

                <NumberInput
                  label="X"
                  value={
                    selectedElement.x
                  }
                  onChange={value =>
                    updateElement(
                      selectedId,
                      "x",
                      value
                    )
                  }
                />

                <NumberInput
                  label="Y"
                  value={
                    selectedElement.y
                  }
                  onChange={value =>
                    updateElement(
                      selectedId,
                      "y",
                      value
                    )
                  }
                />

              </div>


              {/* WIDTH HEIGHT */}

              <div className="
                grid
                grid-cols-2
                gap-2
                mt-2
              ">

                <NumberInput
                  label="Width"
                  value={
                    selectedElement.width
                  }
                  onChange={value =>
                    updateElement(
                      selectedId,
                      "width",
                      value
                    )
                  }
                />

                <NumberInput
                  label="Height"
                  value={
                    selectedElement.height
                  }
                  onChange={value =>
                    updateElement(
                      selectedId,
                      "height",
                      value
                    )
                  }
                />

              </div>


              {/* TEXT */}

              {selectedElement.type ===
                "text" && (

                <div className="mt-3">

                  <label className="
                    text-xs
                    text-gray-500
                    block mb-1
                  ">
                    Text
                  </label>

                  <input
                    value={
                      selectedElement.text
                    }
                    onChange={event =>
                      updateElement(
                        selectedId,
                        "text",
                        event.target.value
                      )
                    }
                    className="
                      w-full
                      border
                      rounded-lg
                      px-3 py-2
                    "
                  />

                  <p className="
                    text-[11px]
                    text-gray-400
                    mt-1
                  ">
                    Variables:
                    {" "}
                    {"{VoucherType}"}
                    {" "}
                    {"{VoucherValue}"}
                    {" "}
                    {"{VoucherNo}"}
                    {" "}
                    {"{VoucherSerial}"}
                    {" "}
                    {"{ExpiryDate}"}
                    {" "}
                    {"{Status}"}
                  </p>

                </div>
              )}


              {/* FONT */}

              <div className="mt-3">

                <NumberInput
                  label="Font size"
                  value={
                    selectedElement.fontSize
                  }
                  onChange={value =>
                    updateElement(
                      selectedId,
                      "fontSize",
                      value
                    )
                  }
                />

              </div>


              {/* ALIGNMENT */}

              <div className="mt-3">

                <label className="
                  text-xs
                  text-gray-500
                  block mb-1
                ">
                  Alignment
                </label>

                <div className="
                  flex
                  border
                  rounded-lg
                  overflow-hidden
                ">

                  {[
                    {
                      value: "left",
                      icon: (
                        <AlignLeft
                          size={16}
                        />
                      ),
                    },
                    {
                      value: "center",
                      icon: (
                        <AlignCenter
                          size={16}
                        />
                      ),
                    },
                    {
                      value: "right",
                      icon: (
                        <AlignRight
                          size={16}
                        />
                      ),
                    },
                  ].map(item => (

                    <button
                      key={item.value}
                      type="button"
                      onClick={() =>
                        updateElement(
                          selectedId,
                          "align",
                          item.value
                        )
                      }
                      className={`
                        flex-1
                        py-2
                        flex
                        justify-center
                        ${
                          selectedElement.align ===
                          item.value
                            ? "bg-blue-600 text-white"
                            : "hover:bg-gray-50"
                        }
                      `}
                    >
                      {item.icon}
                    </button>

                  ))}

                </div>

              </div>


              <label className="
                flex
                gap-2
                text-sm
                mt-3
              ">

                <input
                  type="checkbox"
                  checked={
                    selectedElement.bold
                  }
                  onChange={event =>
                    updateElement(
                      selectedId,
                      "bold",
                      event.target.checked
                    )
                  }
                />

                Bold

              </label>


              <label className="
                flex
                gap-2
                text-sm
                mt-2
              ">

                <input
                  type="checkbox"
                  checked={
                    selectedElement.visible
                  }
                  onChange={event =>
                    updateElement(
                      selectedId,
                      "visible",
                      event.target.checked
                    )
                  }
                />

                Visible

              </label>


              <button
                type="button"
                onClick={() =>
                  deleteElement(
                    selectedId
                  )
                }
                className="
                  w-full
                  mt-4
                  py-2
                  border
                  border-red-200
                  text-red-600
                  rounded-lg
                  hover:bg-red-50
                "
              >

                <Trash2
                  size={16}
                  className="inline mr-2"
                />

                Remove Element

              </button>

            </div>
          )}

        </div>

      </div>

    </div>
  );
}


/*
 * --------------------------------------------------
 * SMALL COMPONENTS
 * --------------------------------------------------
 */

function NumberInput({
  label,
  value,
  onChange,
}) {
  return (
    <div>

      <label className="
        text-xs
        text-gray-500
        block mb-1
      ">
        {label}
      </label>

      <input
        type="number"
        value={value}
        onChange={event =>
          onChange(
            Number(event.target.value)
          )
        }
        className="
          w-full
          border
          rounded-lg
          px-2
          py-2
        "
      />

    </div>
  );
}


function getJustify(align) {
  if (align === "left")
    return "flex-start";

  if (align === "right")
    return "flex-end";

  return "center";
}


function escapeHtml(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

export default VoucherTemplate;