import React, { useContext, useEffect, useState } from "react";
import axios from "axios";
import { AuthContext } from "./SERVER/AuthContext.js";

// ← PERM: shared adapter
import { usePermissions } from "../hooks/usePermissions.jsx";

function Catagory() {
  const { user } = useContext(AuthContext);

  const API_URL = "http://localhost:5000";

  // =========================================================
  // PERMISSIONS                                            // ← PERM
  // =========================================================
  const { can, loading: permissionsLoading } = usePermissions();    // ← PERM

  const canViewCategory   = can("Category", "View");               // ← PERM
  const canAddCategory    = can("Category", "Add");                // ← PERM
  const canEditCategory   = can("Category", "Edit");               // ← PERM
  const canDeleteCategory = can("Category", "Delete");             // ← PERM

  const emptyForm = {
    InvCategoryID: "",
    Department: "",
    categorycode: "",
    categoryname: "",
    Remark: "",
    username: "",
  };

  const [form, setForm] = useState(emptyForm);

  const [departments, setDepartments] = useState([]);
  const [categories, setCategories] = useState([]);

  const [search, setSearch] = useState("");

  const [loadingDepartments, setLoadingDepartments] = useState(false);
  const [loadingCategories, setLoadingCategories] = useState(false);
  const [loadingCode, setLoadingCode] = useState(false);
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState(false);

  const [editing, setEditing] = useState(false);

  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  // =========================================================
  // INITIAL LOAD
  // =========================================================
  useEffect(() => {
    // ← PERM: don't hit the API if user can't view
    if (!canViewCategory) return;

    loadDepartments();
    loadCategories();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [canViewCategory]);                                          // ← PERM

  // =========================================================
  // USER
  // =========================================================
  useEffect(() => {
    setForm((prev) => ({ ...prev, username: user?.username || "" }));
  }, [user]);

  // =========================================================
  // LOAD DEPARTMENTS
  // =========================================================
  const loadDepartments = async () => {
    try {
      setLoadingDepartments(true);
      setError("");

      const response = await axios.get(`${API_URL}/departments`);
      console.log("DEPARTMENT RESPONSE:", response.data);

      let data = [];
      if (Array.isArray(response.data)) data = response.data;
      else if (Array.isArray(response.data?.data)) data = response.data.data;
      else if (Array.isArray(response.data?.departments)) data = response.data.departments;

      setDepartments(data);
    } catch (err) {
      console.error("LOAD DEPARTMENTS ERROR:", err.response?.data || err);
      setError(err.response?.data?.message || "Unable to load departments.");
    } finally {
      setLoadingDepartments(false);
    }
  };

  // =========================================================
  // LOAD CATEGORIES
  // =========================================================
  const loadCategories = async () => {
    try {
      setLoadingCategories(true);

      const response = await axios.get(`${API_URL}/categories`);
      console.log("CATEGORY RESPONSE:", response.data);

      let data = [];
      if (Array.isArray(response.data)) data = response.data;
      else if (Array.isArray(response.data?.data)) data = response.data.data;
      else if (Array.isArray(response.data?.categories)) data = response.data.categories;

      setCategories(data);
    } catch (err) {
      console.error("LOAD CATEGORIES ERROR:", err.response?.data || err);
      setError(err.response?.data?.message || "Unable to load categories.");
    } finally {
      setLoadingCategories(false);
    }
  };

  // =========================================================
  // INPUT CHANGE
  // =========================================================
  const handleChange = (e) => {
    const { name, value } = e.target;

    setForm((prev) => ({ ...prev, [name]: value }));

    setMessage("");
    setError("");
  };

  // =========================================================
  // GENERATE CATEGORY CODE (New)
  // =========================================================
  const handleNew = async () => {
    // ← PERM
    if (!canAddCategory) {
      setError("You do not have permission to create categories.");
      return;
    }

    try {
      setLoadingCode(true);
      setMessage("");
      setError("");

      const response = await axios.get(`${API_URL}/categorycode`);
      console.log("CATEGORY CODE RESPONSE:", response.data);

      let data = [];
      if (Array.isArray(response.data)) data = response.data;
      else if (Array.isArray(response.data?.data)) data = response.data.data;

      let nextCode = "C001";

      if (data.length > 0) {
        const lastCode = data[0]?.CategoryCode ?? data[0]?.categorycode ?? "";
        const numberPart = parseInt(String(lastCode).replace(/\D/g, ""), 10);

        if (!Number.isNaN(numberPart)) {
          nextCode = `C${String(numberPart + 1).padStart(3, "0")}`;
        }
      }

      setForm((prev) => ({
        ...prev,
        InvCategoryID: "",
        categorycode: nextCode,
        categoryname: "",
        Remark: "",
        username: user?.username || prev.username || "",
      }));

      setEditing(false);
      setMessage(`New category code generated: ${nextCode}`);
    } catch (err) {
      console.error("CATEGORY CODE ERROR:", err.response?.data || err);
      setError(
        err.response?.data?.message || "Unable to generate category code."
      );
    } finally {
      setLoadingCode(false);
    }
  };

  // =========================================================
  // SAVE / UPDATE
  // =========================================================
  const handleSubmit = async (e) => {
    e.preventDefault();

    setMessage("");
    setError("");

    // ----- Permission guards -----                            // ← PERM
    if (editing && !canEditCategory) {
      setError("You do not have permission to edit categories.");
      return;
    }
    if (!editing && !canAddCategory) {
      setError("You do not have permission to create categories.");
      return;
    }

    const department   = String(form?.Department ?? "").trim();
    const categorycode = String(form?.categorycode ?? "").trim();
    const categoryname = String(form?.categoryname ?? "").trim();
    const Remark       = String(form?.Remark ?? "").trim();
    const username     = String(user?.username || form?.username || "").trim();

    // ----- Validation -----
    if (!department) {
      setError("Please select a department.");
      return;
    }
    if (!categorycode) {
      setError("Please generate or enter category code.");
      return;
    }
    if (!categoryname) {
      setError("Please enter category name.");
      return;
    }
    if (categorycode.length > 15) {
      setError("Category code cannot exceed 15 characters.");
      return;
    }
    if (categoryname.length > 50) {
      setError("Category name cannot exceed 50 characters.");
      return;
    }
    if (Remark.length > 150) {
      setError("Remark cannot exceed 150 characters.");
      return;
    }

    const requestData = {
      Department: department,
      categorycode,
      categoryname,
      Remark: Remark || null,
      username: username || null,
    };

    console.log("CATEGORY REQUEST DATA:", requestData);

    try {
      setSaving(true);

      if (editing) {
        const response = await axios.put(
          `${API_URL}/category/${form.InvCategoryID}`,
          requestData,
          { headers: { "Content-Type": "application/json" } }
        );
        setMessage(response.data?.message || "Category updated successfully.");
      } else {
        const response = await axios.post(
          `${API_URL}/category`,
          requestData,
          { headers: { "Content-Type": "application/json" } }
        );
        setMessage(response.data?.message || "Category saved successfully.");
      }

      setForm({ ...emptyForm, username: user?.username || "" });
      setEditing(false);

      await loadCategories();
    } catch (err) {
      console.error("CATEGORY SAVE ERROR:", err.response?.data || err);
      setError(err.response?.data?.message || "Error saving category.");
    } finally {
      setSaving(false);
    }
  };

  // =========================================================
  // EDIT
  // =========================================================
  const handleEdit = (category) => {
    // ← PERM
    if (!canEditCategory) {
      setError("You do not have permission to edit categories.");
      return;
    }

    const categoryId = category?.InvCategoryID ?? category?.invCategoryID ?? "";
    const department = category?.Department      ?? category?.department      ?? "";
    const code       = category?.CategoryCode    ?? category?.categorycode    ?? "";
    const name       = category?.CategoryName    ?? category?.categoryname    ?? "";
    const remark     = category?.Remark          ?? category?.remark          ?? "";

    setForm({
      InvCategoryID: categoryId,
      Department: department,
      categorycode: code,
      categoryname: name,
      Remark: remark,
      username: user?.username || "",
    });

    setEditing(true);
    setMessage(`Editing ${code}`);
    setError("");

    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  // =========================================================
  // DELETE
  // =========================================================
  const handleDelete = async (category) => {
    // ← PERM
    if (!canDeleteCategory) {
      setError("You do not have permission to delete categories.");
      return;
    }

    const categoryId   = category?.InvCategoryID ?? category?.invCategoryID ?? "";
    const categoryCode = category?.CategoryCode  ?? category?.categorycode  ?? "";
    const categoryName = category?.CategoryName  ?? category?.categoryname  ?? "";

    if (!categoryId) {
      setError("Category ID not found.");
      return;
    }

    const confirmed = window.confirm(
      `Are you sure you want to delete this category?\n\n${categoryCode} - ${categoryName}`
    );
    if (!confirmed) return;

    try {
      setDeleting(true);
      setMessage("");
      setError("");

      const response = await axios.delete(`${API_URL}/category/${categoryId}`);
      setMessage(response.data?.message || "Category deleted successfully.");

      if (String(form.InvCategoryID) === String(categoryId)) {
        setForm({ ...emptyForm, username: user?.username || "" });
        setEditing(false);
      }

      await loadCategories();
    } catch (err) {
      console.error("DELETE CATEGORY ERROR:", err.response?.data || err);
      setError(err.response?.data?.message || "Error deleting category.");
    } finally {
      setDeleting(false);
    }
  };

  // =========================================================
  // CLEAR
  // =========================================================
  const handleClear = () => {
    setForm({ ...emptyForm, username: user?.username || "" });
    setEditing(false);
    setMessage("");
    setError("");
  };

  // =========================================================
  // SEARCH
  // =========================================================
  const searchText = String(search || "").toLowerCase().trim();

  const filteredCategories = categories.filter((category) => {
    const code = String(
      category?.CategoryCode ?? category?.categorycode ?? ""
    ).toLowerCase();

    const name = String(
      category?.CategoryName ?? category?.categoryname ?? ""
    ).toLowerCase();

    const department = String(
      category?.Department ?? category?.department ?? ""
    ).toLowerCase();

    return (
      code.includes(searchText) ||
      name.includes(searchText) ||
      department.includes(searchText)
    );
  });

  // =========================================================
  // COMPUTED                                               // ← PERM
  // =========================================================
  const saveAllowed = (editing && canEditCategory) || (!editing && canAddCategory);
  const readOnlyEdit = editing && !canEditCategory;

  // =========================================================
  // ACCESS GATE                                            // ← PERM
  // =========================================================
  if (permissionsLoading) {
    return (
      <div className="min-h-screen bg-gray-100 p-6 flex items-center justify-center text-gray-500">
        Checking permissions…
      </div>
    );
  }

  if (!canViewCategory) {
    return (
      <div className="min-h-screen bg-gray-100 p-6">
        <div className="mx-auto max-w-xl mt-20 rounded-xl border border-red-200 bg-red-50 p-8 text-center">
          <h2 className="text-lg font-bold text-red-700">Access Denied</h2>
          <p className="text-sm text-red-600 mt-2">
            You do not have permission to view Category Master.
          </p>
          <p className="text-xs text-red-400 mt-3">
            Module: <code>Category</code>
          </p>
        </div>
      </div>
    );
  }

  // =========================================================
  // RENDER
  // =========================================================
  return (
    <div className="min-h-screen bg-gray-100 p-4 sm:p-6">
      <div className="mx-auto max-w-7xl">

        {/* HEADER */}
        <div className="mb-5 rounded-xl border border-gray-200 bg-white shadow-sm">
          <div className="flex flex-col gap-4 px-5 py-4 md:flex-row md:items-center md:justify-between">
            <div>
              <h1 className="text-2xl font-bold text-gray-800">Category Master</h1>
              <p className="mt-1 text-sm text-gray-500">Manage product categories</p>
            </div>

            <div className="flex items-center gap-3">
              {/* ← PERM: read-only badge */}
              {readOnlyEdit && (
                <span className="rounded-full bg-slate-200 px-3 py-1 text-xs font-semibold text-slate-600">
                  READ ONLY
                </span>
              )}

              <div className="rounded-lg border border-gray-200 bg-gray-50 px-5 py-2">
                <p className="text-xs text-gray-500">Logged User</p>
                <p className="font-semibold text-gray-800">
                  {user?.username || "Not logged in"}
                </p>
              </div>
            </div>
          </div>
        </div>

        {/* SUCCESS */}
        {message && (
          <div className="mb-4 rounded-lg border border-green-200 bg-green-50 px-4 py-3 text-sm font-medium text-green-700">
            ✓ {message}
          </div>
        )}

        {/* ERROR */}
        {error && (
          <div className="mb-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700">
            ⚠ {error}
          </div>
        )}

        {/* FORM */}
        <div className="mb-6 overflow-hidden rounded-xl border border-gray-200 bg-white shadow-lg">
          <div className="flex items-center justify-between border-b border-gray-200 bg-gray-50 px-5 py-4">
            <div>
              <h2 className="text-lg font-semibold text-gray-800">
                {editing ? "Edit Category" : "Category Information"}
              </h2>
              {editing && (
                <p className="mt-1 text-xs text-orange-600">
                  Editing existing category
                </p>
              )}
            </div>

            {editing && (
              <span className="rounded-full bg-orange-100 px-3 py-1 text-xs font-bold text-orange-700">
                EDIT MODE
              </span>
            )}
          </div>

          <form onSubmit={handleSubmit} className="p-5">
            <div className="grid grid-cols-1 gap-5 md:grid-cols-2">

              {/* DEPARTMENT */}
              <div className="md:col-span-2">
                <label className="mb-1.5 block text-sm font-semibold text-gray-700">
                  Department <span className="ml-1 text-red-500">*</span>
                </label>

                <select
                  name="Department"
                  value={form.Department || ""}
                  onChange={handleChange}
                  disabled={loadingDepartments}
                  className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2.5 text-sm text-gray-800 outline-none transition focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 disabled:bg-gray-100"
                >
                  <option value="">
                    {loadingDepartments ? "Loading departments..." : "-- Select Department --"}
                  </option>

                  {departments.map((department, index) => {
                    const id =
                      department?.InvDepartmentID ??
                      department?.DepartmentID ??
                      department?.id ??
                      index;

                    const code =
                      department?.DepartmentCode ?? department?.departmentcode ?? "";
                    const name =
                      department?.DepartmentName ?? department?.departmentname ?? "";
                    const value = code && name ? `${code} - ${name}` : code || name;

                    if (!value) return null;

                    return (
                      <option key={id} value={value}>
                        {value}
                      </option>
                    );
                  })}
                </select>

                {form.Department && (
                  <p className="mt-1 text-xs text-gray-500">
                    Selected: {form.Department}
                  </p>
                )}

                {!loadingDepartments && departments.length === 0 && (
                  <p className="mt-1 text-xs text-red-500">No departments found.</p>
                )}
              </div>

              {/* CATEGORY CODE */}
              <div>
                <label className="mb-1.5 block text-sm font-semibold text-gray-700">
                  Category Code <span className="ml-1 text-red-500">*</span>
                </label>

                <div className="flex gap-2">
                  <input
                    type="text"
                    name="categorycode"
                    value={form.categorycode || ""}
                    onChange={handleChange}
                    maxLength={15}
                    disabled={editing}
                    placeholder="C001"
                    className="w-full rounded-lg border border-gray-300 bg-gray-50 px-3 py-2.5 text-sm font-semibold text-gray-800 outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 disabled:bg-gray-100"
                  />

                  {/* ← PERM: New button only when user can Add */}
                  {!editing && canAddCategory && (
                    <button
                      type="button"
                      onClick={handleNew}
                      disabled={loadingCode}
                      className="min-w-[90px] rounded-lg bg-indigo-600 px-4 py-2.5 text-sm font-semibold text-white hover:bg-indigo-700 disabled:bg-gray-400"
                    >
                      {loadingCode ? "..." : "New"}
                    </button>
                  )}
                </div>

                <p className="mt-1 text-xs text-gray-500">Maximum 15 characters</p>
              </div>

              {/* CATEGORY NAME */}
              <div>
                <label className="mb-1.5 block text-sm font-semibold text-gray-700">
                  Category Name <span className="ml-1 text-red-500">*</span>
                </label>

                <input
                  type="text"
                  name="categoryname"
                  value={form.categoryname || ""}
                  onChange={handleChange}
                  maxLength={50}
                  placeholder="Enter category name"
                  className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm text-gray-800 outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200"
                />

                <p className="mt-1 text-right text-xs text-gray-400">
                  {String(form.categoryname || "").length}/50
                </p>
              </div>

              {/* REMARK */}
              <div className="md:col-span-2">
                <label className="mb-1.5 block text-sm font-semibold text-gray-700">
                  Remark
                </label>

                <textarea
                  name="Remark"
                  value={form.Remark || ""}
                  onChange={handleChange}
                  maxLength={150}
                  rows={3}
                  placeholder="Enter remark..."
                  className="w-full resize-none rounded-lg border border-gray-300 px-3 py-2.5 text-sm text-gray-800 outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200"
                />

                <p className="mt-1 text-right text-xs text-gray-400">
                  {String(form.Remark || "").length}/150
                </p>
              </div>
            </div>

            {/* BUTTONS */}
            <div className="mt-6 flex flex-col gap-3 border-t border-gray-200 pt-5 sm:flex-row sm:justify-end">
              <button
                type="button"
                onClick={handleClear}
                disabled={saving || deleting}
                className="rounded-lg border border-gray-300 bg-white px-6 py-2.5 text-sm font-semibold text-gray-700 hover:bg-gray-100 disabled:opacity-50"
              >
                Clear
              </button>

              {/* ← PERM: Save button only when user has Add/Edit */}
              {saveAllowed && (
                <button
                  type="submit"
                  disabled={saving || deleting || loadingDepartments}
                  className={`rounded-lg px-8 py-2.5 text-sm font-semibold text-white ${
                    editing
                      ? "bg-orange-600 hover:bg-orange-700"
                      : "bg-indigo-600 hover:bg-indigo-700"
                  } disabled:bg-gray-400`}
                >
                  {saving ? "Saving..." : editing ? "Update Category" : "Save Category"}
                </button>
              )}

              {/* ← PERM: helper text when blocked */}
              {readOnlyEdit && (
                <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-2.5 text-xs font-semibold text-slate-500">
                  You have read-only access — editing is disabled.
                </div>
              )}

              {!editing && !canAddCategory && (
                <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-2.5 text-xs font-semibold text-slate-500">
                  You do not have permission to create new categories.
                </div>
              )}
            </div>
          </form>
        </div>

        {/* CATEGORY LIST */}
        <div className="overflow-hidden rounded-xl border border-gray-200 bg-white shadow-lg">
          <div className="flex flex-col gap-3 border-b border-gray-200 bg-gray-50 px-5 py-4 md:flex-row md:items-center md:justify-between">
            <div>
              <h2 className="text-lg font-semibold text-gray-800">Category List</h2>
              <p className="text-xs text-gray-500">
                {filteredCategories.length} record(s)
              </p>
            </div>

            <input
              type="text"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search category..."
              className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2.5 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 md:w-80"
            />
          </div>

          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-100">
                <tr>
                  <th className="px-4 py-3 text-left text-xs font-bold uppercase text-gray-600">#</th>
                  <th className="px-4 py-3 text-left text-xs font-bold uppercase text-gray-600">Code</th>
                  <th className="px-4 py-3 text-left text-xs font-bold uppercase text-gray-600">Category Name</th>
                  <th className="px-4 py-3 text-left text-xs font-bold uppercase text-gray-600">Department</th>
                  <th className="px-4 py-3 text-left text-xs font-bold uppercase text-gray-600">Remark</th>
                  <th className="px-4 py-3 text-center text-xs font-bold uppercase text-gray-600">Actions</th>
                </tr>
              </thead>

              <tbody className="divide-y divide-gray-200 bg-white">
                {loadingCategories ? (
                  <tr>
                    <td colSpan="6" className="px-4 py-10 text-center text-sm text-gray-500">
                      Loading categories...
                    </td>
                  </tr>
                ) : filteredCategories.length === 0 ? (
                  <tr>
                    <td colSpan="6" className="px-4 py-10 text-center text-sm text-gray-500">
                      No categories found.
                    </td>
                  </tr>
                ) : (
                  filteredCategories.map((category, index) => {
                    const categoryId =
                      category?.InvCategoryID ?? category?.invCategoryID ?? "";
                    const code =
                      category?.CategoryCode ?? category?.categorycode ?? "";
                    const name =
                      category?.CategoryName ?? category?.categoryname ?? "";
                    const department =
                      category?.Department ?? category?.department ?? "";
                    const remark =
                      category?.Remark ?? category?.remark ?? "";

                    return (
                      <tr
                        key={categoryId || `${code}-${index}`}
                        className="hover:bg-gray-50"
                      >
                        <td className="px-4 py-3 text-sm text-gray-500">{index + 1}</td>

                        <td className="px-4 py-3">
                          <span className="rounded-md bg-indigo-50 px-2.5 py-1 text-sm font-bold text-indigo-700">
                            {code}
                          </span>
                        </td>

                        <td className="px-4 py-3 text-sm font-semibold text-gray-800">
                          {name}
                        </td>

                        <td className="px-4 py-3 text-sm text-gray-600">
                          {department || "-"}
                        </td>

                        <td className="max-w-xs truncate px-4 py-3 text-sm text-gray-500">
                          {remark || "-"}
                        </td>

                        {/* ← PERM: gate the action buttons */}
                        <td className="px-4 py-3">
                          <div className="flex justify-center gap-2">
                            {canEditCategory && (
                              <button
                                type="button"
                                onClick={() => handleEdit(category)}
                                disabled={deleting}
                                className="rounded-lg bg-blue-600 px-3 py-2 text-xs font-semibold text-white hover:bg-blue-700 disabled:opacity-50"
                              >
                                ✏️ Edit
                              </button>
                            )}

                            {canDeleteCategory && (
                              <button
                                type="button"
                                onClick={() => handleDelete(category)}
                                disabled={deleting}
                                className="rounded-lg bg-red-600 px-3 py-2 text-xs font-semibold text-white hover:bg-red-700 disabled:opacity-50"
                              >
                                🗑️ Delete
                              </button>
                            )}

                            {!canEditCategory && !canDeleteCategory && (
                              <span className="text-xs text-slate-400">
                                No actions
                              </span>
                            )}
                          </div>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
        </div>

      </div>
    </div>
  );
}

export default Catagory;