import React, { useEffect, useState } from "react";
import axios from "axios";

const API = "http://localhost:5000";

export default function ProductPriceChange() {

  const [products, setProducts] = useState([]);
  const [search, setSearch] = useState("");

  const [priceMode, setPriceMode] = useState("retail");

  const [tiers, setTiers] = useState([]);

  const [loading, setLoading] = useState(false);

  // --------------------------------------------------
  // LOAD PRODUCTS
  // --------------------------------------------------

  const loadProducts = async () => {

    try {

      setLoading(true);

      const token = localStorage.getItem("token");

      const response = await axios.get(
        `${API}/product-price`,
        {
          params: {
            search
          },
          headers: {
            Authorization: `Bearer ${token}`
          }
        }
      );

      if (response.data.success) {

        setProducts(response.data.products);

        setTiers(response.data.tiers || []);

      }

    } catch (error) {

      console.error(
        "PRODUCT PRICE ERROR:",
        error
      );

    } finally {

      setLoading(false);

    }
  };

  useEffect(() => {

    loadProducts();

  }, []);

  // --------------------------------------------------
  // UPDATE PRODUCT
  // --------------------------------------------------

  const updateProduct = async (
    productID,
    field,
    value
  ) => {

    try {

      const token = localStorage.getItem("token");

      await axios.put(
        `${API}/product-price/${productID}`,
        {
          [field]: Number(value)
        },
        {
          headers: {
            Authorization: `Bearer ${token}`
          }
        }
      );

    } catch (error) {

      console.error(
        "PRICE UPDATE ERROR:",
        error
      );

    }

  };

  // --------------------------------------------------
  // UPDATE TIER
  // --------------------------------------------------

  const updateTier = (
    tierID,
    field,
    value
  ) => {

    setTiers(prev =>
      prev.map(tier =>
        tier.ProductPriceTierID === tierID
          ? {
              ...tier,
              [field]: value
            }
          : tier
      )
    );

  };

  // --------------------------------------------------
  // ADD TIER
  // --------------------------------------------------

  const addTier = async () => {

    try {

      const token = localStorage.getItem("token");

      const product = products[0];

      if (!product) {

        alert("Select a product first");

        return;

      }

      const response = await axios.post(
        `${API}/product-price/tier`,
        {
          productID:
            product.InvProductMasterID,

          productCode:
            product.ProductCode,

          qtyFrom: 1,

          qtyTo: 99,

          cashPrice:
            product.SellingPrice || 0,

          creditPrice:
            product.SellingPrice || 0,

          locationID:
            product.LocationID || 0
        },
        {
          headers: {
            Authorization:
              `Bearer ${token}`
          }
        }
      );

      if (response.data.success) {

        loadProducts();

      }

    } catch (error) {

      console.error(
        "ADD TIER ERROR:",
        error
      );

    }

  };

  // --------------------------------------------------
  // FILTER
  // --------------------------------------------------

  const filteredProducts =
    products.filter(product => {

      const text =
        `${product.ProductCode || ""}
         ${product.ProductName || ""}
         ${product.BarCode || ""}`
        .toLowerCase();

      return text.includes(
        search.toLowerCase()
      );

    });

  return (

    <div className="min-h-screen bg-white p-6">

      {/* HEADER */}

      <div className="flex items-start justify-between mb-6">

        <div>

          <h1 className="text-3xl font-bold text-gray-900">
            Product Management
          </h1>

          <p className="text-gray-500 mt-1">
            Manage your product inventory
          </p>

        </div>

        <div className="flex gap-2">

          <button
            className="
              px-5 py-3
              border border-gray-200
              rounded-xl
              bg-white
              hover:bg-gray-50
            "
          >
            ✎ Quick Edit Mode
          </button>

          <button
            className="
              px-5 py-3
              rounded-xl
              bg-orange-500
              text-white
              font-semibold
            "
          >
            ◇ Exit Price Change
          </button>

          <button
            className="
              px-5 py-3
              rounded-xl
              bg-orange-500
              text-white
              font-semibold
            "
          >
            ＋ Add Product
          </button>

          <button
            className="
              px-5 py-3
              rounded-xl
              border
              border-gray-200
              bg-white
            "
          >
            ⚖ Scale Download
          </button>

        </div>

      </div>


      {/* MAIN CARD */}

      <div className="
        border
        border-gray-300
        rounded-2xl
        overflow-hidden
      ">

        {/* CARD HEADER */}

        <div className="p-6">

          <div className="
            flex
            items-center
            justify-between
          ">

            <h2 className="text-2xl font-bold">

              📦 Products ({filteredProducts.length})

            </h2>

          </div>


          {/* SEARCH */}

          <div className="
            flex
            gap-4
            mt-5
          ">

            <div className="relative w-96">

              <span className="
                absolute
                left-3
                top-3
                text-gray-400
              ">
                🔍
              </span>

              <input
                value={search}
                onChange={e =>
                  setSearch(e.target.value)
                }
                placeholder="Search products..."
                className="
                  w-full
                  border
                  border-gray-200
                  rounded-xl
                  pl-10
                  pr-4
                  py-3
                  outline-none
                  focus:ring-2
                  focus:ring-orange-400
                "
              />

            </div>


            <select
              className="
                border
                border-gray-200
                rounded-xl
                px-5
                py-3
              "
            >
              <option>All Types</option>
            </select>


            <select
              className="
                border
                border-gray-200
                rounded-xl
                px-5
                py-3
              "
            >
              <option>All</option>
            </select>

          </div>


          {/* TABS */}

          <div className="
            flex
            justify-between
            items-center
            mt-6
          ">

            <div className="flex gap-2">

              <button
                onClick={() =>
                  setPriceMode("retail")
                }
                className={`
                  px-5
                  py-3
                  rounded-xl
                  font-semibold
                  ${
                    priceMode === "retail"
                      ? "bg-orange-500 text-white"
                      : "border bg-white"
                  }
                `}
              >
                Retail Prices
              </button>


              <button
                onClick={() =>
                  setPriceMode("wholesale")
                }
                className={`
                  px-5
                  py-3
                  rounded-xl
                  font-semibold
                  ${
                    priceMode === "wholesale"
                      ? "bg-orange-500 text-white"
                      : "border bg-white"
                  }
                `}
              >
                Wholesale Prices
              </button>

            </div>


            <button
              className="
                px-5
                py-3
                rounded-xl
                bg-gray-100
              "
            >
              📄 Excel Bulk Update
            </button>

          </div>


          {/* MODE MESSAGE */}

          <div className="
            mt-4
            bg-orange-50
            border-l-4
            border-orange-500
            p-3
            text-sm
            text-gray-600
          ">

            {priceMode === "retail"
              ? "Retail Mode - Changes sync to Wholesale"
              : "Wholesale Price Mode"}

          </div>

        </div>


        {/* TABLE */}

        <div className="
          overflow-x-auto
          max-h-[600px]
          overflow-y-auto
        ">

          <table className="
            min-w-[1500px]
            w-full
            border-collapse
          ">

            <thead>

              {/* GROUP HEADERS */}

              <tr>

                <th
                  colSpan="6"
                  className="
                    bg-blue-100
                    border
                    px-4
                    py-4
                    text-gray-600
                  "
                >
                  Product Master
                </th>

                <th
                  colSpan="4"
                  className="
                    bg-green-100
                    border
                    px-4
                    py-4
                    text-gray-600
                  "
                >
                  Quantity Price Tiers
                </th>

              </tr>


              {/* COLUMN HEADERS */}

              <tr>

                <th className="bg-blue-50 border p-3">
                  Code
                </th>

                <th className="bg-blue-50 border p-3">
                  Product
                </th>

                <th className="bg-blue-50 border p-3">
                  Cost
                </th>

                <th className="bg-blue-50 border p-3">
                  MRP
                </th>

                <th className="bg-blue-50 border p-3">
                  Stock
                </th>

                <th className="bg-blue-50 border p-3">
                  Q1 Base
                  <div className="text-xs">
                    Cash / Credit
                  </div>
                </th>


                <th className="bg-green-50 border p-3">
                  Q100
                  <div className="text-xs">
                    Cash / Credit
                  </div>
                </th>

                <th className="bg-green-50 border p-3">
                  Q5000
                  <div className="text-xs">
                    Cash / Credit
                  </div>
                </th>

                <th className="bg-green-50 border p-3">
                  Q10000
                  <div className="text-xs">
                    Cash / Credit
                  </div>
                </th>

                <th className="bg-green-50 border p-3">
                  ＋
                </th>

              </tr>

            </thead>


            <tbody>

              {filteredProducts.map(
                product => {

                  const productTiers =
                    tiers.filter(
                      t =>
                        Number(
                          t.ProductID
                        ) ===
                        Number(
                          product.InvProductMasterID
                        )
                    );

                  return (

                    <tr
                      key={
                        product.InvProductMasterID
                      }
                      className="hover:bg-gray-50"
                    >

                      {/* CODE */}

                      <td className="border p-3">
                        {product.ProductCode}
                      </td>


                      {/* PRODUCT */}

                      <td className="border p-3">

                        <div className="font-medium">

                          {product.ProductName}

                        </div>

                      </td>


                      {/* COST */}

                      <td className="border p-2">

                        <input
                          type="number"
                          defaultValue={
                            product.CostPrice
                          }
                          onBlur={e =>
                            updateProduct(
                              product.InvProductMasterID,
                              "CostPrice",
                              e.target.value
                            )
                          }
                          className="
                            w-20
                            border
                            rounded
                            p-2
                            text-right
                          "
                        />

                      </td>


                      {/* MRP */}

                      <td className="border p-2">

                        <input
                          type="number"
                          defaultValue={
                            product.MaximumPrice ||
                            product.SellingPrice
                          }
                          className="
                            w-20
                            border
                            rounded
                            p-2
                            text-right
                          "
                        />

                      </td>


                      {/* STOCK */}

                      <td className="
                        border
                        p-3
                        text-center
                      ">

                        {product.Stock ?? "-"}

                      </td>


                      {/* BASE PRICE */}

                      <td className="border p-2">

                        <div className="flex gap-1">

                          <input
                            type="number"
                            value={
                              product.SellingPrice ||
                              ""
                            }
                            onChange={e => {

                              const value =
                                e.target.value;

                              setProducts(prev =>
                                prev.map(p =>
                                  p.InvProductMasterID ===
                                  product.InvProductMasterID
                                    ? {
                                        ...p,
                                        SellingPrice:
                                          value
                                      }
                                    : p
                                )
                              );

                            }}
                            onBlur={e =>
                              updateProduct(
                                product.InvProductMasterID,
                                "SellingPrice",
                                e.target.value
                              )
                            }
                            className="
                              w-20
                              border
                              rounded
                              p-2
                            "
                          />

                          <input
                            type="number"
                            value={
                              product.WholesalePrice ||
                              ""
                            }
                            className="
                              w-20
                              border
                              rounded
                              p-2
                            "
                            readOnly={
                              priceMode ===
                              "retail"
                            }
                          />

                        </div>

                      </td>


                      {/* Q100 */}

                      <TierCell
                        product={product}
                        tiers={productTiers}
                        quantity={100}
                        updateTier={updateTier}
                      />


                      {/* Q5000 */}

                      <TierCell
                        product={product}
                        tiers={productTiers}
                        quantity={5000}
                        updateTier={updateTier}
                      />


                      {/* Q10000 */}

                      <TierCell
                        product={product}
                        tiers={productTiers}
                        quantity={10000}
                        updateTier={updateTier}
                      />


                      {/* ADD */}

                      <td className="border text-center">

                        <button
                          onClick={addTier}
                          className="
                            text-orange-500
                            text-2xl
                            font-bold
                          "
                        >
                          +
                        </button>

                      </td>

                    </tr>

                  );

                }
              )}

            </tbody>

          </table>

        </div>

      </div>

    </div>

  );
}


// --------------------------------------------------
// TIER CELL
// --------------------------------------------------

function TierCell({
  product,
  tiers,
  quantity,
  updateTier
}) {

  const tier =
    tiers.find(
      t =>
        Number(t.QtyFrom) <= quantity &&
        (
          t.QtyTo == null ||
          Number(t.QtyTo) >= quantity
        )
    );

  if (!tier) {

    return (

      <td className="border text-center">

        <button className="
          text-orange-500
          text-xl
          font-bold
        ">
          +
        </button>

      </td>

    );

  }

  return (

    <td className="border p-2">

      <div className="flex gap-1">

        <input
          type="number"
          value={tier.CashPrice}
          onChange={e =>
            updateTier(
              tier.ProductPriceTierID,
              "CashPrice",
              e.target.value
            )
          }
          className="
            w-20
            border
            rounded
            p-2
          "
        />

        <input
          type="number"
          value={tier.CreditPrice}
          onChange={e =>
            updateTier(
              tier.ProductPriceTierID,
              "CreditPrice",
              e.target.value
            )
          }
          className="
            w-20
            border
            rounded
            p-2
          "
        />

      </div>

    </td>

  );
}