import React, { useCallback, useEffect, useMemo, useState } from "react";
import axios from "axios";
import {
    ArrowRight,
    ArrowRightLeft,
    Calendar,
    ChevronDown,
    FileText,
    Filter,
    Plus,
    RefreshCw,
    X,
    AlertCircle,
    CheckCircle,
} from "lucide-react";

const API_URL = "http://localhost:5000/api";

/* =========================================================
   HELPERS
   ========================================================= */

const formatMoney = (value) => {
    const n = Number(value) || 0;
    return `Rs.${n.toLocaleString("en-US", {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
    })}`;
};

const formatDate = (value) => {
    if (!value) return "-";
    const d = new Date(value);
    if (Number.isNaN(d.getTime())) return "-";
    return d.toLocaleDateString("en-US", {
        month: "short",
        day: "2-digit",
        year: "numeric",
    });
};

/* =========================================================
   COMPONENT
   ========================================================= */

const AccountTransfer = () => {
    const [accounts, setAccounts] = useState([]);
    const [transfers, setTransfers] = useState([]);

    const [loadingAccounts, setLoadingAccounts] = useState(false);
    const [loadingTransfers, setLoadingTransfers] = useState(false);

    const [error, setError] = useState("");
    const [successMessage, setSuccessMessage] = useState("");

    const [showModal, setShowModal] = useState(false);

    // Filters
    const [filterFromAccount, setFilterFromAccount] = useState("");
    const [filterToAccount, setFilterToAccount] = useState("");
    const [fromDate, setFromDate] = useState("");
    const [toDate, setToDate] = useState("");

    // Form
    const [formData, setFormData] = useState({
        fromAccountId: "",
        toAccountId: "",
        amount: "",
        description: "",
        referenceNo: "",
        transferDate: new Date().toISOString().split("T")[0],
    });
    const [saving, setSaving] = useState(false);

    /* =========================================================
       LOAD ACCOUNTS
       ========================================================= */

    const loadAccounts = useCallback(async () => {
        try {
            setLoadingAccounts(true);
            const res = await axios.get(`${API_URL}/accounts`);
            if (!res.data?.success) throw new Error("Failed to load accounts");

            const list = res.data.accounts || res.data.data || [];

            setAccounts(
                list.map((a) => ({
                    id: a.AccountID ?? a.id,
                    name: a.AccountName ?? a.name ?? "Unknown",
                    balance: Number(a.StoredBalance ?? a.balance ?? 0),
                    type: a.AccountType ?? a.type ?? "",
                }))
            );
        } catch (err) {
            console.error(err);
            setError(err.message);
        } finally {
            setLoadingAccounts(false);
        }
    }, []);

    /* =========================================================
       LOAD TRANSFERS
       ========================================================= */

    const loadTransfers = useCallback(async () => {
        try {
            setLoadingTransfers(true);
            setError("");

            const params = {};
            if (filterFromAccount) params.fromAccountId = filterFromAccount;
            if (filterToAccount) params.toAccountId = filterToAccount;
            if (fromDate) params.fromDate = fromDate;
            if (toDate) params.toDate = toDate;

            const res = await axios.get(`${API_URL}/accounts-transfers`, {
                params,
            });

            if (!res.data?.success) throw new Error("Failed to load transfers");

            setTransfers(res.data.data || []);
        } catch (err) {
            console.error(err);
            setTransfers([]);
            setError(err.message);
        } finally {
            setLoadingTransfers(false);
        }
    }, [filterFromAccount, filterToAccount, fromDate, toDate]);

    useEffect(() => {
        loadAccounts();
    }, [loadAccounts]);

    useEffect(() => {
        loadTransfers();
    }, [loadTransfers]);

    /* =========================================================
       SUMMARY — total of debits (i.e. transfer amount, not doubled)
       ========================================================= */

    const summary = useMemo(() => {
        const count = transfers.length;
        const total = transfers.reduce(
            (sum, t) => sum + Number(t.Amount || 0),
            0
        );
        return { count, total };
    }, [transfers]);

    /* =========================================================
       CLEAR FILTERS
       ========================================================= */

    const clearFilters = () => {
        setFilterFromAccount("");
        setFilterToAccount("");
        setFromDate("");
        setToDate("");
    };

    /* =========================================================
       MODAL OPEN / CLOSE
       ========================================================= */

    const openModal = () => {
        setError("");
        setSuccessMessage("");
        setFormData({
            fromAccountId: "",
            toAccountId: "",
            amount: "",
            description: "",
            referenceNo: "",
            transferDate: new Date().toISOString().split("T")[0],
        });
        setShowModal(true);
    };

    const closeModal = () => {
        if (saving) return;
        setShowModal(false);
    };

    /* =========================================================
       SUBMIT
       ========================================================= */

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError("");
        setSuccessMessage("");

        const from = Number(formData.fromAccountId);
        const to = Number(formData.toAccountId);
        const amount = Number(formData.amount);

        if (!from || !to) return setError("Select both accounts.");
        if (from === to) return setError("Accounts must be different.");
        if (!amount || amount <= 0) return setError("Enter a valid amount.");

        try {
            setSaving(true);

            const res = await axios.post(
                `${API_URL}/cash-transactions/transfer`,
                {
                    fromAccountId: from,
                    toAccountId: to,
                    amount,
                    description: formData.description?.trim() || "",
                    referenceNo: formData.referenceNo?.trim() || "",
                    transferDate: formData.transferDate,
                    createdBy: "Admin",
                }
            );

            if (!res.data?.success)
                throw new Error(res.data?.message || "Transfer failed");

            setSuccessMessage("Transfer completed successfully.");
            setShowModal(false);
            await loadAccounts();
            await loadTransfers();
        } catch (err) {
            console.error(err);
            setError(err.response?.data?.message || err.message);
        } finally {
            setSaving(false);
        }
    };

    /* =========================================================
       RENDER
       ========================================================= */

    return (
        <div className="min-h-screen bg-gray-50 p-4 sm:p-6">
            {/* ============ HEADER ============ */}
            <div className="mb-5 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
                <div>
                    <h1 className="text-3xl font-bold text-gray-900">
                        Account Transfers
                    </h1>
                    <p className="mt-1 text-sm text-gray-500">
                        Transfer funds between accounts
                    </p>
                </div>

                <div className="flex gap-2">
                    <button
                        type="button"
                        onClick={openModal}
                        disabled={loadingAccounts || accounts.length < 2}
                        className="inline-flex items-center gap-2 rounded-xl bg-amber-500 px-5 py-3 text-sm font-semibold text-white shadow-sm transition hover:bg-amber-600 disabled:cursor-not-allowed disabled:opacity-50"
                    >
                        <Plus size={18} />
                        New Transfer
                    </button>

                    <button
                        type="button"
                        className="inline-flex items-center gap-2 rounded-xl border border-gray-300 bg-white px-5 py-3 text-sm font-semibold text-gray-700 shadow-sm transition hover:bg-gray-50"
                    >
                        <FileText size={18} />
                        Transfer Cheques
                    </button>
                </div>
            </div>

            {/* ============ ALERTS ============ */}
            {successMessage && (
                <div className="mb-5 flex items-center justify-between rounded-xl border border-green-200 bg-green-50 px-4 py-3 text-green-700">
                    <div className="flex items-center gap-2">
                        <CheckCircle size={18} />
                        <span className="text-sm font-medium">
                            {successMessage}
                        </span>
                    </div>
                    <button onClick={() => setSuccessMessage("")}>
                        <X size={18} />
                    </button>
                </div>
            )}

            {error && (
                <div className="mb-5 flex items-center justify-between rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-red-700">
                    <div className="flex items-center gap-2">
                        <AlertCircle size={18} />
                        <span className="text-sm font-medium">{error}</span>
                    </div>
                    <button onClick={() => setError("")}>
                        <X size={18} />
                    </button>
                </div>
            )}

            {/* ============ SUMMARY ============ */}
            <div className="mb-6 max-w-md rounded-2xl border border-gray-200 bg-white p-6 shadow-sm">
                <div className="flex items-center justify-between">
                    <div>
                        <p className="text-sm font-medium text-gray-600">
                            Total Transfers
                        </p>
                        <p className="mt-2 text-2xl font-bold text-gray-900">
                            {formatMoney(summary.total)}
                        </p>
                        <p className="mt-1 text-xs text-gray-500">
                            {summary.count} transfer
                            {summary.count === 1 ? "" : "s"}
                        </p>
                    </div>
                    <div className="text-gray-400">
                        <ArrowRightLeft size={22} />
                    </div>
                </div>
            </div>

            {/* ============ TRANSFER HISTORY ============ */}
            <div className="overflow-hidden rounded-2xl border border-gray-200 bg-white shadow-sm">
                {/* Header */}
                <div className="flex flex-col gap-4 border-b border-gray-200 px-6 py-5 sm:flex-row sm:items-center sm:justify-between">
                    <div>
                        <h2 className="text-xl font-bold text-gray-900">
                            Transfer History
                        </h2>
                        <p className="mt-1 text-sm text-gray-500">
                            View and filter account transfers
                        </p>
                    </div>

                    <div className="flex gap-2">
                        <button
                            type="button"
                            onClick={clearFilters}
                            className="inline-flex items-center gap-2 rounded-xl border border-gray-300 bg-white px-4 py-2 text-sm font-medium text-gray-700 transition hover:bg-gray-50"
                        >
                            <Filter size={15} />
                            Clear Filters
                        </button>

                        <button
                            type="button"
                            onClick={loadTransfers}
                            disabled={loadingTransfers}
                            className="inline-flex items-center gap-2 rounded-xl border border-gray-300 bg-white px-4 py-2 text-sm font-medium text-gray-700 transition hover:bg-gray-50 disabled:opacity-50"
                        >
                            <RefreshCw
                                size={15}
                                className={loadingTransfers ? "animate-spin" : ""}
                            />
                            Refresh
                        </button>
                    </div>
                </div>

                {/* Filters */}
                <div className="grid grid-cols-1 gap-4 border-b border-gray-200 px-6 py-4 md:grid-cols-2 xl:grid-cols-4">
                    <div>
                        <label className="mb-1.5 block text-sm font-medium text-gray-700">
                            From Account
                        </label>
                        <div className="relative">
                            <select
                                value={filterFromAccount}
                                onChange={(e) =>
                                    setFilterFromAccount(e.target.value)
                                }
                                className="w-full appearance-none rounded-lg border border-gray-300 bg-white px-3 py-2.5 pr-10 text-sm outline-none focus:border-amber-500 focus:ring-2 focus:ring-amber-100"
                            >
                                <option value="">All accounts</option>
                                {accounts.map((a) => (
                                    <option key={a.id} value={a.id}>
                                        {a.name}
                                    </option>
                                ))}
                            </select>
                            <ChevronDown
                                size={16}
                                className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400"
                            />
                        </div>
                    </div>

                    <div>
                        <label className="mb-1.5 block text-sm font-medium text-gray-700">
                            To Account
                        </label>
                        <div className="relative">
                            <select
                                value={filterToAccount}
                                onChange={(e) =>
                                    setFilterToAccount(e.target.value)
                                }
                                className="w-full appearance-none rounded-lg border border-gray-300 bg-white px-3 py-2.5 pr-10 text-sm outline-none focus:border-amber-500 focus:ring-2 focus:ring-amber-100"
                            >
                                <option value="">All accounts</option>
                                {accounts.map((a) => (
                                    <option key={a.id} value={a.id}>
                                        {a.name}
                                    </option>
                                ))}
                            </select>
                            <ChevronDown
                                size={16}
                                className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400"
                            />
                        </div>
                    </div>

                    <div>
                        <label className="mb-1.5 block text-sm font-medium text-gray-700">
                            From Date
                        </label>
                        <div className="relative">
                            <input
                                type="date"
                                value={fromDate}
                                onChange={(e) => setFromDate(e.target.value)}
                                className="w-full rounded-lg border border-gray-300 px-3 py-2.5 pr-10 text-sm outline-none focus:border-amber-500 focus:ring-2 focus:ring-amber-100"
                            />
                            <Calendar
                                size={16}
                                className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400"
                            />
                        </div>
                    </div>

                    <div>
                        <label className="mb-1.5 block text-sm font-medium text-gray-700">
                            To Date
                        </label>
                        <div className="relative">
                            <input
                                type="date"
                                value={toDate}
                                onChange={(e) => setToDate(e.target.value)}
                                className="w-full rounded-lg border border-gray-300 px-3 py-2.5 pr-10 text-sm outline-none focus:border-amber-500 focus:ring-2 focus:ring-amber-100"
                            />
                            <Calendar
                                size={16}
                                className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400"
                            />
                        </div>
                    </div>
                </div>

                {/* Table */}
                <div className="overflow-x-auto">
                    <table className="min-w-full">
                        <thead className="border-b border-gray-200 bg-white">
                            <tr>
                                <th className="px-6 py-4 text-left text-xs font-semibold uppercase tracking-wide text-gray-500">
                                    Date
                                </th>
                                <th className="px-6 py-4 text-left text-xs font-semibold uppercase tracking-wide text-gray-500">
                                    From Account
                                </th>
                                <th />
                                <th className="px-6 py-4 text-left text-xs font-semibold uppercase tracking-wide text-gray-500">
                                    To Account
                                </th>
                                <th className="px-6 py-4 text-left text-xs font-semibold uppercase tracking-wide text-gray-500">
                                    Description
                                </th>
                                <th className="px-6 py-4 text-left text-xs font-semibold uppercase tracking-wide text-gray-500">
                                    Reference
                                </th>
                                <th className="px-6 py-4 text-right text-xs font-semibold uppercase tracking-wide text-gray-500">
                                    Amount
                                </th>
                            </tr>
                        </thead>

                        <tbody className="divide-y divide-gray-100">
                            {loadingTransfers && (
                                <tr>
                                    <td colSpan={7} className="px-6 py-12 text-center">
                                        <div className="flex items-center justify-center gap-2 text-sm text-gray-500">
                                            <RefreshCw size={18} className="animate-spin" />
                                            Loading transfers...
                                        </div>
                                    </td>
                                </tr>
                            )}

                            {!loadingTransfers && transfers.length === 0 && (
                                <tr>
                                    <td colSpan={7} className="px-6 py-16 text-center">
                                        <div className="flex flex-col items-center">
                                            <div className="mb-3 rounded-full bg-gray-100 p-4">
                                                <ArrowRightLeft size={24} className="text-gray-400" />
                                            </div>
                                            <p className="font-medium text-gray-700">
                                                No transfers found
                                            </p>
                                            <p className="mt-1 text-sm text-gray-500">
                                                Adjust filters or create a new transfer.
                                            </p>
                                        </div>
                                    </td>
                                </tr>
                            )}

                            {!loadingTransfers &&
                                transfers.map((row) => (
                                    <tr
                                        key={row.DebitTxID}
                                        className="transition hover:bg-gray-50"
                                    >
                                        <td className="whitespace-nowrap px-6 py-4 text-sm text-gray-700">
                                            <div className="flex items-center gap-2">
                                                <Calendar size={14} className="text-gray-400" />
                                                {formatDate(row.TransferDate)}
                                            </div>
                                        </td>

                                        <td className="px-6 py-4 text-sm font-semibold text-gray-900">
                                            {row.FromAccountName || "-"}
                                        </td>

                                        <td className="px-2 text-gray-400">
                                            <ArrowRight size={16} />
                                        </td>

                                        <td className="px-6 py-4 text-sm font-semibold text-gray-900">
                                            {row.ToAccountName || "-"}
                                        </td>

                                        <td className="max-w-xs px-6 py-4 text-sm text-gray-600">
                                            <div className="truncate" title={row.Description || ""}>
                                                {row.Description || "-"}
                                            </div>
                                        </td>

                                        <td className="px-6 py-4 text-sm text-gray-500">
                                            {row.ReferenceNo || "-"}
                                        </td>

                                        <td className="whitespace-nowrap px-6 py-4 text-right text-sm font-bold text-gray-900">
                                            {formatMoney(row.Amount)}
                                        </td>
                                    </tr>
                                ))}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* ============ MODAL ============ */}
            {showModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
                    <div className="w-full max-w-md overflow-hidden rounded-2xl bg-white shadow-2xl">
                        <div className="flex items-center justify-between border-b px-5 py-4">
                            <div>
                                <h2 className="text-lg font-bold text-gray-900">
                                    Account Transfer
                                </h2>
                                <p className="text-xs text-gray-500">
                                    Transfer funds between accounts
                                </p>
                            </div>
                            <button
                                type="button"
                                onClick={closeModal}
                                className="rounded-lg p-2 text-gray-400 hover:bg-gray-100"
                            >
                                <X size={18} />
                            </button>
                        </div>

                        <form onSubmit={handleSubmit} className="space-y-4 px-5 py-4">
                            <div>
                                <label className="mb-1.5 block text-sm font-medium text-gray-700">
                                    From Account *
                                </label>
                                <select
                                    value={formData.fromAccountId}
                                    onChange={(e) =>
                                        setFormData((p) => ({
                                            ...p,
                                            fromAccountId: e.target.value,
                                        }))
                                    }
                                    required
                                    className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm focus:border-amber-500 focus:ring-2 focus:ring-amber-100"
                                >
                                    <option value="">Select source</option>
                                    {accounts.map((a) => (
                                        <option key={a.id} value={a.id}>
                                            {a.name} — {formatMoney(a.balance)}
                                        </option>
                                    ))}
                                </select>
                            </div>

                            <div>
                                <label className="mb-1.5 block text-sm font-medium text-gray-700">
                                    To Account *
                                </label>
                                <select
                                    value={formData.toAccountId}
                                    onChange={(e) =>
                                        setFormData((p) => ({
                                            ...p,
                                            toAccountId: e.target.value,
                                        }))
                                    }
                                    required
                                    className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm focus:border-amber-500 focus:ring-2 focus:ring-amber-100"
                                >
                                    <option value="">Select destination</option>
                                    {accounts
                                        .filter(
                                            (a) =>
                                                String(a.id) !==
                                                String(formData.fromAccountId)
                                        )
                                        .map((a) => (
                                            <option key={a.id} value={a.id}>
                                                {a.name}
                                            </option>
                                        ))}
                                </select>
                            </div>

                            <div>
                                <label className="mb-1.5 block text-sm font-medium text-gray-700">
                                    Amount *
                                </label>
                                <input
                                    type="number"
                                    min="0.01"
                                    step="0.01"
                                    value={formData.amount}
                                    onChange={(e) =>
                                        setFormData((p) => ({
                                            ...p,
                                            amount: e.target.value,
                                        }))
                                    }
                                    required
                                    placeholder="0.00"
                                    className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm focus:border-amber-500 focus:ring-2 focus:ring-amber-100"
                                />
                            </div>

                            <div>
                                <label className="mb-1.5 block text-sm font-medium text-gray-700">
                                    Transfer Date *
                                </label>
                                <input
                                    type="date"
                                    value={formData.transferDate}
                                    onChange={(e) =>
                                        setFormData((p) => ({
                                            ...p,
                                            transferDate: e.target.value,
                                        }))
                                    }
                                    required
                                    className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm focus:border-amber-500 focus:ring-2 focus:ring-amber-100"
                                />
                            </div>

                            <div>
                                <label className="mb-1.5 block text-sm font-medium text-gray-700">
                                    Reference
                                </label>
                                <input
                                    type="text"
                                    value={formData.referenceNo}
                                    onChange={(e) =>
                                        setFormData((p) => ({
                                            ...p,
                                            referenceNo: e.target.value,
                                        }))
                                    }
                                    className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm focus:border-amber-500 focus:ring-2 focus:ring-amber-100"
                                />
                            </div>

                            <div>
                                <label className="mb-1.5 block text-sm font-medium text-gray-700">
                                    Description
                                </label>
                                <textarea
                                    rows={3}
                                    value={formData.description}
                                    onChange={(e) =>
                                        setFormData((p) => ({
                                            ...p,
                                            description: e.target.value,
                                        }))
                                    }
                                    className="w-full resize-none rounded-lg border border-gray-300 px-3 py-2.5 text-sm focus:border-amber-500 focus:ring-2 focus:ring-amber-100"
                                />
                            </div>

                            {error && (
                                <div className="rounded-lg bg-red-50 px-3 py-2.5 text-sm text-red-600">
                                    {error}
                                </div>
                            )}

                            <div className="flex justify-end gap-3 border-t pt-4">
                                <button
                                    type="button"
                                    onClick={closeModal}
                                    disabled={saving}
                                    className="rounded-lg border border-gray-300 px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:opacity-50"
                                >
                                    Cancel
                                </button>
                                <button
                                    type="submit"
                                    disabled={saving}
                                    className="rounded-lg bg-amber-500 px-4 py-2 text-sm font-semibold text-white hover:bg-amber-600 disabled:opacity-50"
                                >
                                    {saving ? "Processing..." : "Complete Transfer"}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default AccountTransfer;