import React, { useContext, useEffect, useMemo, useState } from "react";
import { Menu, X, Trash2, ShoppingCart, Plus, Minus, Lock } from "lucide-react";
import { useNavigate } from "react-router-dom";
import { AuthContext } from "./SERVER/AuthContext.js";

// ← PERM
import { usePermissions } from "../hooks/usePermissions.jsx";

const PRODUCT_API = "http://localhost:5000/PRODUCTS";
const DEPARTMENT_API = "http://localhost:5000/Department";

// ------------------------------------------------------------
// Modules that guard this page                             // ← PERM
// ------------------------------------------------------------
const PRODUCT_MODULE = "Product";                          // ← PERM
const SALES_MODULE   = "Sale";                             // ← PERM (change to "POS" or "Sales" if that's what your DB uses)

export default function Catalog() {
  const navigate = useNavigate();
  const { user } = useContext(AuthContext);

  // =====================================================
  // PERMISSIONS                                            // ← PERM
  // =====================================================
  const {
    can,
    canField,
    loading: permissionsLoading,
  } = usePermissions();                                     // ← PERM

  const canViewProducts     = can(PRODUCT_MODULE, "View");       // ← PERM
  const canSell             = can(SALES_MODULE, "Add");          // ← PERM  (cart add + checkout)
  const canViewSellingPrice = canField(PRODUCT_MODULE, "SellingPrice"); // ← PERM

  // =====================================================
  // SIDEBAR
  // =====================================================
  const [isOpen, setIsOpen] = useState(true);

  // =====================================================
  // PRODUCTS
  // =====================================================
  const [products, setProducts] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [selectedDepartment, setSelectedDepartment] = useState("All");
  const [search, setSearch] = useState("");
  const [loadingProducts, setLoadingProducts] = useState(false);
  const [loadingDepartments, setLoadingDepartments] = useState(false);
  const [error, setError] = useState("");

  // =====================================================
  // CART
  // =====================================================
  const [cart, setCart] = useState([]);
  const [cartOpen, setCartOpen] = useState(false);

  // =====================================================
  // LOAD PRODUCTS
  // =====================================================
  const loadProducts = async () => {
    try {
      setLoadingProducts(true);
      setError("");

      const location = user?.location || "";
      const url = `${PRODUCT_API}?location=${encodeURIComponent(location)}`;
      const response = await fetch(url);

      if (!response.ok) {
        throw new Error(`Product API returned ${response.status}`);
      }

      const data = await response.json();
      const productData = Array.isArray(data) ? data : data.products || [];
      setProducts(productData);
    } catch (err) {
      console.error("LOAD PRODUCTS ERROR:", err);
      setError(err.message || "Unable to load products");
      setProducts([]);
    } finally {
      setLoadingProducts(false);
    }
  };

  // =====================================================
  // LOAD DEPARTMENTS
  // =====================================================
  const loadDepartments = async () => {
    try {
      setLoadingDepartments(true);
      const response = await fetch(DEPARTMENT_API);

      if (!response.ok) {
        throw new Error(`Department API returned ${response.status}`);
      }

      const data = await response.json();
      const departmentData = Array.isArray(data) ? data : data.departments || [];
      setDepartments(departmentData);
    } catch (err) {
      console.error("LOAD DEPARTMENTS ERROR:", err);
      setDepartments([]);
    } finally {
      setLoadingDepartments(false);
    }
  };

  // =====================================================
  // PAGE LOAD
  // =====================================================
  useEffect(() => {
    // ← PERM: skip network if user can't even view products
    if (!canViewProducts) return;
    if (permissionsLoading) return;

    loadProducts();
    loadDepartments();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.location, canViewProducts, permissionsLoading]);  // ← PERM

  // =====================================================
  // FILTER PRODUCTS
  // =====================================================
  const filteredProducts = useMemo(() => {
    const searchText = search.toLowerCase().trim();

    return products.filter((product) => {
      const productName = String(product?.ProductName || "").toLowerCase();
      const productCode = String(product?.ProductCode || "").toLowerCase();
      const barcode = String(
        product?.BarCode || product?.Barcode || ""
      ).toLowerCase();
      const department = String(product?.Department || "");

      const matchesSearch =
        !searchText ||
        productName.includes(searchText) ||
        productCode.includes(searchText) ||
        barcode.includes(searchText);

      const matchesDepartment =
        selectedDepartment === "All" || department === selectedDepartment;

      return matchesSearch && matchesDepartment;
    });
  }, [products, search, selectedDepartment]);

  // =====================================================
  // ADD TO CART
  // =====================================================
  const addToCart = (product) => {
    // ← PERM
    if (!canSell) {
      alert("You do not have permission to add items to a sale.");
      return;
    }

    setCart((previousCart) => {
      const productCode = product.ProductCode;
      const existing = previousCart.find(
        (item) => item.ProductCode === productCode
      );

      if (existing) {
        return previousCart.map((item) => {
          if (item.ProductCode === productCode) {
            return { ...item, qty: item.qty + 1 };
          }
          return item;
        });
      }

      return [...previousCart, { ...product, qty: 1 }];
    });

    setCartOpen(true);
  };

  // =====================================================
  // INCREASE QTY
  // =====================================================
  const increaseQty = (productCode) => {
    if (!canSell) return;                                   // ← PERM
    setCart((previousCart) =>
      previousCart.map((item) =>
        item.ProductCode === productCode
          ? { ...item, qty: item.qty + 1 }
          : item
      )
    );
  };

  // =====================================================
  // DECREASE QTY
  // =====================================================
  const decreaseQty = (productCode) => {
    if (!canSell) return;                                   // ← PERM
    setCart((previousCart) =>
      previousCart
        .map((item) => {
          if (item.ProductCode === productCode) {
            return { ...item, qty: item.qty - 1 };
          }
          return item;
        })
        .filter((item) => item.qty > 0)
    );
  };

  // =====================================================
  // DELETE CART ITEM
  // =====================================================
  const deleteCartItem = (productCode) => {
    if (!canSell) return;                                   // ← PERM
    setCart((previousCart) =>
      previousCart.filter((item) => item.ProductCode !== productCode)
    );
  };

  // =====================================================
  // CART COUNT
  // =====================================================
  const cartItemCount = useMemo(() => {
    return cart.reduce((total, item) => total + Number(item.qty || 0), 0);
  }, [cart]);

  // =====================================================
  // CART TOTAL
  // =====================================================
  const cartTotal = useMemo(() => {
    return cart.reduce((total, item) => {
      const price = Number(item.SellingPrice || 0);
      const discount = Number(item.FixedDiscountPercentage || 0);
      const qty = Number(item.qty || 0);
      const discountedPrice = price - (price * discount) / 100;
      return total + discountedPrice * qty;
    }, 0);
  }, [cart]);

  // =====================================================
  // FORMAT MONEY
  // =====================================================
  const money = (value) => Number(value || 0).toFixed(2);

  // =====================================================
  // MASKED MONEY — used when user lacks price visibility  // ← PERM
  // =====================================================
  const priceOrMask = (value) =>
    canViewSellingPrice ? money(value) : "—";               // ← PERM

  // =====================================================
  // CHECKOUT
  // =====================================================
  const handleCheckout = () => {
    // ← PERM
    if (!canSell) {
      alert("You do not have permission to apply a sale.");
      return;
    }

    if (cart.length === 0) {
      alert("Cart is empty");
      return;
    }

    console.log("CHECKOUT CART:", cart);
    console.log("TOTAL:", cartTotal);

    if (canViewSellingPrice) {
      alert(`Total Amount: ${money(cartTotal)}`);
    } else {
      alert("Sale applied (total hidden by permissions).");
    }

    /*
      Later: navigate("/POS", { state: { cart } });
    */
  };

  // =====================================================
  // IMAGE
  // =====================================================
  const getProductImage = (product) => {
    if (!product) {
      return "https://via.placeholder.com/500x400?text=No+Image";
    }

    if (product.ProductImage) {
      if (typeof product.ProductImage === "string") {
        return product.ProductImage;
      }

      if (product.ProductImage.data) {
        try {
          const bytes = product.ProductImage.data;
          let binary = "";
          bytes.forEach((byte) => {
            binary += String.fromCharCode(byte);
          });
          return `data:image/jpeg;base64,${btoa(binary)}`;
        } catch (error) {
          console.error("IMAGE CONVERSION ERROR:", error);
        }
      }
    }

    return "https://via.placeholder.com/500x400?text=No+Image";
  };

  // =====================================================
  // LOGOUT
  // =====================================================
  const handleLogout = () => {
    localStorage.removeItem("user");
    localStorage.removeItem("token");
    navigate("/");
  };

  // =====================================================
  // ACCESS GATE                                            // ← PERM
  // =====================================================
  if (permissionsLoading) {
    return (
      <div className="min-h-screen bg-gray-100 flex items-center justify-center text-gray-500">
        Checking permissions…
      </div>
    );
  }

  if (!canViewProducts) {
    return (
      <div className="min-h-screen bg-gray-100 flex items-center justify-center p-6">
        <div className="max-w-xl w-full rounded-xl border border-red-200 bg-red-50 p-8 text-center">
          <Lock className="mx-auto text-red-500 mb-3" size={32} />
          <h2 className="text-lg font-bold text-red-700">Access Denied</h2>
          <p className="text-sm text-red-600 mt-2">
            You do not have permission to view the product catalog.
          </p>
          <p className="text-xs text-red-400 mt-3">
            Module: <code>{PRODUCT_MODULE}</code>
          </p>
          <button
            onClick={handleLogout}
            className="mt-6 rounded-lg bg-red-600 px-5 py-2 text-sm font-semibold text-white hover:bg-red-700"
          >
            Log out
          </button>
        </div>
      </div>
    );
  }

  // =====================================================
  // UI
  // =====================================================
  return (
    <div className="min-h-screen bg-gray-100 flex">

      {/* LEFT SIDEBAR */}
      <aside
        className={`bg-slate-800 text-white min-h-screen p-5 pt-8 relative duration-300 shrink-0 ${
          isOpen ? "w-64" : "w-20"
        }`}
      >
        <button
          type="button"
          onClick={() => setIsOpen(!isOpen)}
          className="absolute -right-3 top-9 bg-white text-black rounded-full p-1 shadow"
        >
          {isOpen ? <X size={18} /> : <Menu size={18} />}
        </button>

        {isOpen && <h1 className="text-2xl font-bold mb-8">MPOS</h1>}

        <ul className="space-y-3">
          <li>
            <button
              type="button"
              onClick={() => navigate("/home")}
              className="w-full text-left hover:bg-slate-700 p-3 rounded-lg"
            >
              {isOpen ? "Home" : "⌂"}
            </button>
          </li>

          <li>
            <button
              type="button"
              onClick={() => navigate("/Dashboard")}
              className="w-full text-left bg-slate-700 hover:bg-slate-600 p-3 rounded-lg"
            >
              {isOpen ? "Catalog" : "🛒"}
            </button>
          </li>

          <li>
            <button
              type="button"
              onClick={() => navigate("/Settingss")}
              className="w-full text-left hover:bg-slate-700 p-3 rounded-lg"
            >
              {isOpen ? "Settings" : "⚙"}
            </button>
          </li>

          <li>
            <button
              type="button"
              onClick={handleLogout}
              className="w-full text-left hover:bg-red-700 p-3 rounded-lg"
            >
              {isOpen ? "Logout" : "↪"}
            </button>
          </li>
        </ul>
      </aside>

      {/* MAIN */}
      <main className="flex-1 min-w-0">

        {/* HEADER */}
        <header className="bg-indigo-600 text-white shadow-md">
          <div className="px-6 py-4 flex flex-col md:flex-row md:items-center md:justify-between gap-4">
            <div>
              <h1 className="text-2xl font-bold">Product Catalogue</h1>
              <p className="text-indigo-100 text-sm">
                Select products and add them to cart
              </p>
            </div>

            <div className="flex items-center gap-3">
              <input
                type="text"
                placeholder="Search product..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="w-full md:w-80 px-4 py-2.5 rounded-lg text-black outline-none"
              />

              <button
                type="button"
                onClick={() => setCartOpen(true)}
                className="relative bg-white text-indigo-600 p-3 rounded-lg hover:bg-gray-100"
              >
                <ShoppingCart size={24} />
                {cartItemCount > 0 && (
                  <span className="absolute -top-2 -right-2 bg-red-500 text-white min-w-6 h-6 rounded-full text-xs font-bold flex items-center justify-center px-1">
                    {cartItemCount}
                  </span>
                )}
              </button>
            </div>
          </div>
        </header>

        {/* ← PERM: read-only banner when user can view but not sell */}
        {!canSell && (
          <div className="mx-4 md:mx-6 mt-4 flex items-center gap-2 rounded-lg border border-amber-200 bg-amber-50 px-4 py-2 text-sm text-amber-700">
            <Lock size={14} /> Read-only mode — you cannot add items to a sale or check out.
          </div>
        )}

        {/* CONTENT */}
        <div className="p-4 md:p-6 flex flex-col lg:flex-row gap-6">

          {/* DEPARTMENT */}
          <aside className="w-full lg:w-64 bg-white rounded-xl shadow-md p-5 h-fit">
            <h2 className="text-lg font-bold mb-4">Departments</h2>

            <button
              type="button"
              onClick={() => setSelectedDepartment("All")}
              className={`w-full text-left px-4 py-2.5 rounded-lg mb-2 font-semibold ${
                selectedDepartment === "All"
                  ? "bg-indigo-600 text-white"
                  : "bg-gray-100 hover:bg-gray-200"
              }`}
            >
              All Products
            </button>

            {loadingDepartments ? (
              <p className="text-gray-500 text-sm">Loading departments...</p>
            ) : departments.length === 0 ? (
              <p className="text-gray-500 text-sm">No departments found</p>
            ) : (
              <div className="space-y-2">
                {departments.map((department, index) => {
                  const departmentName = department.DepartmentName;
                  const departmentCode = department.DepartmentCode || index;
                  return (
                    <button
                      type="button"
                      key={departmentCode}
                      onClick={() => setSelectedDepartment(departmentName)}
                      className={`w-full text-left px-4 py-2.5 rounded-lg ${
                        selectedDepartment === departmentName
                          ? "bg-indigo-600 text-white"
                          : "bg-gray-100 hover:bg-gray-200"
                      }`}
                    >
                      {departmentName}
                    </button>
                  );
                })}
              </div>
            )}
          </aside>

          {/* PRODUCTS */}
          <section className="flex-1">
            <div className="flex justify-between items-center mb-5">
              <div>
                <h2 className="text-xl font-bold">Products</h2>
                <p className="text-gray-500 text-sm">
                  Showing {filteredProducts.length} product(s)
                </p>
              </div>

              {selectedDepartment !== "All" && (
                <button
                  type="button"
                  onClick={() => setSelectedDepartment("All")}
                  className="text-sm text-indigo-600 font-semibold"
                >
                  Clear Filter
                </button>
              )}
            </div>

            {error && (
              <div className="mb-5 bg-red-100 border border-red-300 text-red-700 px-4 py-3 rounded-lg">
                {error}
              </div>
            )}

            {loadingProducts ? (
              <div className="bg-white rounded-xl shadow p-10 text-center text-gray-500">
                Loading products...
              </div>
            ) : filteredProducts.length === 0 ? (
              <div className="bg-white rounded-xl shadow p-10 text-center text-gray-500">
                No products found.
              </div>
            ) : (
              <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-5">
                {filteredProducts.map((product) => (
                  <div
                    key={product.ProductCode}
                    className="bg-white rounded-xl shadow-md overflow-hidden hover:shadow-xl transition"
                  >
                    <div className="h-52 bg-gray-100">
                      <img
                        src={getProductImage(product)}
                        alt={product.ProductName}
                        className="w-full h-full object-cover"
                        onError={(e) => {
                          e.currentTarget.src =
                            "https://via.placeholder.com/500x400?text=No+Image";
                        }}
                      />
                    </div>

                    <div className="p-4">
                      <div className="flex justify-between gap-2">
                        <span className="text-xs bg-indigo-100 text-indigo-600 px-2 py-1 rounded">
                          {product.Department || "Product"}
                        </span>
                        <span className="text-xs text-gray-500">
                          {product.ProductCode}
                        </span>
                      </div>

                      <h3 className="mt-3 text-lg font-semibold text-gray-800 min-h-14">
                        {product.ProductName}
                      </h3>

                      <div className="mt-3">
                        {/* ← PERM: hide actual price if user can't see SellingPrice */}
                        <span className="text-2xl font-bold text-indigo-600">
                          {priceOrMask(product.SellingPrice)}
                        </span>
                      </div>

                      {/* ← PERM: add-to-cart button only when user can sell */}
                      {canSell ? (
                        <button
                          type="button"
                          onClick={() => addToCart(product)}
                          className="w-full mt-4 bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2.5 rounded-lg font-semibold flex items-center justify-center gap-2"
                        >
                          <ShoppingCart size={18} />
                          Add Cart
                        </button>
                      ) : (
                        <div className="w-full mt-4 rounded-lg bg-slate-100 px-4 py-2.5 text-center text-xs font-semibold text-slate-500">
                          Selling disabled
                        </div>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </section>
        </div>
      </main>

      {/* CART MODAL */}
      {cartOpen && (
        <div
          className="fixed inset-0 z-50 bg-black bg-opacity-50 flex items-center justify-center p-4"
          onClick={() => setCartOpen(false)}
        >
          <div
            className="bg-white rounded-xl shadow-2xl w-full max-w-5xl max-h-[90vh] overflow-hidden"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Cart Header */}
            <div className="bg-indigo-600 text-white px-5 py-4 flex items-center justify-between">
              <div>
                <h2 className="text-xl font-bold">Shopping Cart</h2>
                <p className="text-sm text-indigo-100">
                  {cartItemCount} item(s)
                </p>
              </div>

              <button
                type="button"
                onClick={() => setCartOpen(false)}
                className="hover:bg-indigo-500 p-2 rounded-lg"
              >
                <X size={22} />
              </button>
            </div>

            {/* Cart Body */}
            <div className="overflow-y-auto max-h-[60vh] p-5">
              {cart.length === 0 ? (
                <div className="py-16 text-center text-gray-500">
                  <ShoppingCart size={50} className="mx-auto mb-4 text-gray-300" />
                  <p className="text-lg">Cart is empty</p>
                </div>
              ) : (
                <div className="overflow-x-auto">
                  <table className="min-w-full border">
                    <thead className="bg-gray-100">
                      <tr>
                        <th className="px-4 py-3 text-left text-sm">Code</th>
                        <th className="px-4 py-3 text-left text-sm">Product</th>
                        <th className="px-4 py-3 text-right text-sm">Price</th>
                        <th className="px-4 py-3 text-center text-sm">Discount</th>
                        <th className="px-4 py-3 text-center text-sm">Qty</th>
                        <th className="px-4 py-3 text-right text-sm">Amount</th>
                        <th className="px-4 py-3 text-center text-sm">Action</th>
                      </tr>
                    </thead>

                    <tbody>
                      {cart.map((item) => {
                        const price = Number(item.SellingPrice || 0);
                        const discount = Number(item.FixedDiscountPercentage || 0);
                        const netPrice = price - (price * discount) / 100;
                        const amount = netPrice * item.qty;

                        return (
                          <tr
                            key={item.ProductCode}
                            className="border-t hover:bg-gray-50"
                          >
                            <td className="px-4 py-3 text-sm font-semibold">
                              {item.ProductCode}
                            </td>
                            <td className="px-4 py-3 text-sm">{item.ProductName}</td>

                            {/* ← PERM: masked money */}
                            <td className="px-4 py-3 text-right text-sm">
                              {priceOrMask(price)}
                            </td>
                            <td className="px-4 py-3 text-center text-sm">
                              {priceOrMask(discount)}%
                            </td>

                            {/* Quantity — disabled when !canSell */}
                            <td className="px-4 py-3">
                              <div className="flex items-center justify-center gap-2">
                                <button
                                  type="button"
                                  onClick={() => decreaseQty(item.ProductCode)}
                                  disabled={!canSell}
                                  className="bg-gray-200 hover:bg-gray-300 p-1.5 rounded disabled:opacity-50"
                                >
                                  <Minus size={15} />
                                </button>

                                <span className="min-w-8 text-center font-semibold">
                                  {item.qty}
                                </span>

                                <button
                                  type="button"
                                  onClick={() => increaseQty(item.ProductCode)}
                                  disabled={!canSell}
                                  className="bg-gray-200 hover:bg-gray-300 p-1.5 rounded disabled:opacity-50"
                                >
                                  <Plus size={15} />
                                </button>
                              </div>
                            </td>

                            <td className="px-4 py-3 text-right font-bold">
                              {priceOrMask(amount)}
                            </td>

                            <td className="px-4 py-3 text-center">
                              <button
                                type="button"
                                onClick={() => deleteCartItem(item.ProductCode)}
                                disabled={!canSell}
                                className="text-red-500 hover:text-red-700 p-2 disabled:opacity-50"
                              >
                                <Trash2 size={18} />
                              </button>
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              )}
            </div>

            {/* Cart Footer */}
            <div className="border-t bg-gray-50 px-5 py-4">
              <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
                <div>
                  <p className="text-gray-500">Total Items</p>
                  <p className="font-bold">{cartItemCount}</p>
                </div>

                <div className="text-right">
                  <p className="text-gray-500">Total Amount</p>
                  <p className="text-2xl font-bold text-indigo-600">
                    {priceOrMask(cartTotal)}
                  </p>
                </div>

                <div className="flex gap-3">
                  <button
                    type="button"
                    onClick={() => setCart([])}
                    disabled={!canSell}
                    className="bg-red-500 hover:bg-red-600 text-white px-5 py-2.5 rounded-lg font-semibold disabled:opacity-50"
                  >
                    Clear
                  </button>

                  <button
                    type="button"
                    disabled={cart.length === 0 || !canSell}
                    onClick={handleCheckout}
                    className="bg-indigo-600 hover:bg-indigo-700 disabled:bg-gray-300 text-white px-6 py-2.5 rounded-lg font-semibold"
                  >
                    Apply Bill
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}