import React, { useContext, useEffect, useMemo, useState } from "react";
import axios from "axios";
import { AuthContext } from "./SERVER/AuthContext.js";

// ← PERM
import { usePermissions } from "../hooks/usePermissions.jsx";

const API_URL = "http://localhost:5000";

const EMPTY_FORM = {
  companycode: "",
  companyname: "",
  address: "",
  mobileno: "",
};

function Company() {
  const { user } = useContext(AuthContext);

  // ============================================================
  // PERMISSIONS                                              // ← PERM
  // ============================================================
  const { can, loading: permissionsLoading } = usePermissions();   // ← PERM

  const canViewCompany   = can("Company", "View");                 // ← PERM
  const canAddCompany    = can("Company", "Add");                  // ← PERM
  const canEditCompany   = can("Company", "Edit");                 // ← PERM
  const canDeleteCompany = can("Company", "Delete");               // ← PERM

  // ============================================================
  // STATE
  // ============================================================

  const [form, setForm] = useState(EMPTY_FORM);
  const [companies, setCompanies] = useState([]);
  const [searchText, setSearchText] = useState("");
  const [editingId, setEditingId] = useState(null);

  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [deletingId, setDeletingId] = useState(null);
  const [generatingCode, setGeneratingCode] = useState(false);

  // ============================================================
  // API RESPONSE HELPER
  // ============================================================

  const getResponseData = (response) => {
    if (Array.isArray(response?.data)) return response.data;
    if (Array.isArray(response?.data?.data)) return response.data.data;
    if (Array.isArray(response?.data?.recordset)) return response.data.recordset;
    return [];
  };

  // ============================================================
  // LOAD COMPANIES
  // ============================================================

  const loadCompanies = async () => {
    try {
      setLoading(true);

      const response = await axios.get(`${API_URL}/Companies`);
      const data = getResponseData(response);

      setCompanies(data);
    } catch (error) {
      console.error("GET COMPANIES ERROR:", error);
      alert(
        error?.response?.data?.message ||
          error?.response?.data?.error ||
          "Error loading companies."
      );
    } finally {
      setLoading(false);
    }
  };

  // ============================================================
  // LOAD ON PAGE OPEN
  // ============================================================

  useEffect(() => {
    // ← PERM: wait for permissions + skip network if user can't view
    if (permissionsLoading) return;
    if (!canViewCompany) return;

    loadCompanies();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [canViewCompany, permissionsLoading]);                 // ← PERM

  // ============================================================
  // HANDLE INPUT
  // ============================================================

  const handleChange = (event) => {
    const { name, value } = event.target;
    setForm((previous) => ({ ...previous, [name]: value }));
  };

  // ============================================================
  // GENERATE COMPANY CODE
  // ============================================================

  const generateCompanyCode = async () => {
    // ← PERM
    if (!canAddCompany) {
      alert("You do not have permission to create companies.");
      return;
    }

    try {
      setGeneratingCode(true);

      const response = await axios.get(`${API_URL}/Companycode?q=`);

      let data = [];
      if (Array.isArray(response.data)) data = response.data;
      else if (Array.isArray(response.data?.data)) data = response.data.data;

      if (data.length === 0) {
        setForm((previous) => ({ ...previous, companycode: "01" }));
        return;
      }

      const lastRecord = data[0];
      const lastCode =
        lastRecord?.CompanyCode || lastRecord?.companycode || "";

      const numericPart = String(lastCode).replace(/\D/g, "");
      const lastNumber = parseInt(numericPart, 10);
      const nextNumber = Number.isNaN(lastNumber) ? 1 : lastNumber + 1;
      const nextCode = String(nextNumber).padStart(2, "0");

      setForm((previous) => ({ ...previous, companycode: nextCode }));
    } catch (error) {
      console.error("COMPANY CODE ERROR:", error);
      alert(
        error?.response?.data?.message || "Error generating company code."
      );
    } finally {
      setGeneratingCode(false);
    }
  };

  // ============================================================
  // NEW COMPANY
  // ============================================================

  const handleNew = async () => {
    // ← PERM
    if (!canAddCompany) {
      alert("You do not have permission to create companies.");
      return;
    }

    setEditingId(null);
    setForm(EMPTY_FORM);
    await generateCompanyCode();
  };

  // ============================================================
  // CLEAR FORM
  // ============================================================

  const handleClear = () => {
    setEditingId(null);
    setForm(EMPTY_FORM);
  };

  // ============================================================
  // VALIDATE FORM
  // ============================================================

  const validateForm = () => {
    if (!form.companycode.trim()) {
      alert("Please enter Company Code.");
      return false;
    }
    if (!form.companyname.trim()) {
      alert("Please enter Company Name.");
      return false;
    }
    if (!form.address.trim()) {
      alert("Please enter Address.");
      return false;
    }
    if (!form.mobileno.trim()) {
      alert("Please enter Mobile Number.");
      return false;
    }
    return true;
  };

  // ============================================================
  // SAVE / UPDATE COMPANY
  // ============================================================

  const handleSubmit = async (event) => {
    event.preventDefault();

    // ----- Permission guards (before validation) -----        // ← PERM
    if (editingId !== null && !canEditCompany) {
      alert("You do not have permission to edit companies.");
      return;
    }
    if (editingId === null && !canAddCompany) {
      alert("You do not have permission to create companies.");
      return;
    }

    if (!validateForm()) return;

    try {
      setSaving(true);

      const payload = {
        companycode: form.companycode.trim(),
        companyname: form.companyname.trim(),
        address: form.address.trim(),
        mobileno: form.mobileno.trim(),
        username: user?.username || "",
      };

      let response;

      if (editingId !== null) {
        response = await axios.put(
          `${API_URL}/Company/${editingId}`,
          payload
        );
      } else {
        response = await axios.post(`${API_URL}/Company`, payload);
      }

      const message =
        response?.data?.message ||
        (editingId !== null
          ? "Company updated successfully."
          : "Company saved successfully.");

      alert(message);

      setForm(EMPTY_FORM);
      setEditingId(null);

      await loadCompanies();
    } catch (error) {
      console.error("SAVE COMPANY ERROR:", error);
      alert(
        error?.response?.data?.message ||
          error?.response?.data?.error ||
          "Error saving company."
      );
    } finally {
      setSaving(false);
    }
  };

  // ============================================================
  // EDIT COMPANY
  // ============================================================

  const handleEdit = (company) => {
    // ← PERM
    if (!canEditCompany) {
      alert("You do not have permission to edit companies.");
      return;
    }

    const id =
      company?.CompanyID ??
      company?.companyID ??
      company?.companyId ??
      company?.ID ??
      company?.Id ??
      company?.id;

    if (id === undefined || id === null) {
      alert("CompanyID was not returned from the server.");
      return;
    }

    setEditingId(id);
    setForm({
      companycode: company?.CompanyCode ?? company?.companycode ?? "",
      companyname: company?.CompanyName ?? company?.companyname ?? "",
      address: company?.Address ?? company?.address ?? "",
      mobileno:
        company?.MobileNo ??
        company?.mobileno ??
        company?.Mobile ??
        company?.mobile ??
        "",
    });

    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  // ============================================================
  // DELETE COMPANY
  // ============================================================

  const handleDelete = async (company) => {
    // ← PERM
    if (!canDeleteCompany) {
      alert("You do not have permission to delete companies.");
      return;
    }

    const id =
      company?.CompanyID ??
      company?.companyID ??
      company?.companyId ??
      company?.ID ??
      company?.Id ??
      company?.id;

    if (id === undefined || id === null) {
      alert("CompanyID was not returned from the server.");
      return;
    }

    const companyName =
      company?.CompanyName ?? company?.companyname ?? "this company";

    const confirmed = window.confirm(
      `Are you sure you want to delete "${companyName}"?`
    );
    if (!confirmed) return;

    try {
      setDeletingId(id);

      const response = await axios.delete(`${API_URL}/Company/${id}`);

      alert(response?.data?.message || "Company deleted successfully.");

      if (String(editingId) === String(id)) {
        setEditingId(null);
        setForm(EMPTY_FORM);
      }

      await loadCompanies();
    } catch (error) {
      console.error("DELETE COMPANY ERROR:", error);
      alert(
        error?.response?.data?.message ||
          error?.response?.data?.error ||
          "Error deleting company."
      );
    } finally {
      setDeletingId(null);
    }
  };

  // ============================================================
  // SEARCH
  // ============================================================

  const filteredCompanies = useMemo(() => {
    const search = searchText.trim().toLowerCase();
    if (!search) return companies;

    return companies.filter((company) => {
      const code = company?.CompanyCode ?? company?.companycode ?? "";
      const name = company?.CompanyName ?? company?.companyname ?? "";
      const address = company?.Address ?? company?.address ?? "";
      const mobile =
        company?.MobileNo ?? company?.mobileno ?? company?.Mobile ?? "";

      const text = [code, name, address, mobile].join(" ").toLowerCase();
      return text.includes(search);
    });
  }, [companies, searchText]);

  // ============================================================
  // COMPUTED                                                 // ← PERM
  // ============================================================
  const isEditing = editingId !== null;
  const saveAllowed =
    (isEditing && canEditCompany) || (!isEditing && canAddCompany);
  const readOnlyEdit = isEditing && !canEditCompany;

  // ============================================================
  // ACCESS GATE                                              // ← PERM
  // ============================================================
  if (permissionsLoading) {
    return (
      <div className="min-h-screen bg-gray-100 flex items-center justify-center text-gray-500">
        Checking permissions…
      </div>
    );
  }

  if (!canViewCompany) {
    return (
      <div className="min-h-screen bg-gray-100 p-6">
        <div className="mx-auto max-w-xl mt-20 rounded-xl border border-red-200 bg-red-50 p-8 text-center">
          <h2 className="text-lg font-bold text-red-700">Access Denied</h2>
          <p className="text-sm text-red-600 mt-2">
            You do not have permission to view Company Master.
          </p>
          <p className="text-xs text-red-400 mt-3">
            Module: <code>Company</code>
          </p>
        </div>
      </div>
    );
  }

  // ============================================================
  // RENDER
  // ============================================================

  return (
    <div className="min-h-screen bg-gray-100 p-4 md:p-6">
      <div className="mx-auto max-w-7xl">

        {/* PAGE HEADER */}
        <div className="mb-6 rounded-xl bg-white p-5 shadow-md">
          <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
            <div>
              <h1 className="text-2xl font-bold text-gray-800">
                Company Master
              </h1>
              <p className="mt-1 text-sm text-gray-500">
                Create and manage companies
              </p>
            </div>

            <div className="flex items-center gap-3">
              {/* ← PERM: read-only badge */}
              {readOnlyEdit && (
                <span className="rounded-full bg-slate-200 px-3 py-1 text-xs font-semibold text-slate-600">
                  READ ONLY
                </span>
              )}

              <div className="rounded-lg bg-indigo-50 px-4 py-2 text-sm text-indigo-700">
                <span className="font-semibold">User:</span>{" "}
                {user?.username || "No user logged in"}
              </div>
            </div>
          </div>
        </div>

        {/* COMPANY FORM */}
        <div className="mb-6 rounded-xl bg-white p-5 shadow-md">
          <div className="mb-5 flex flex-col gap-3 border-b pb-4 sm:flex-row sm:items-center sm:justify-between">
            <div>
              <h2 className="text-xl font-bold text-gray-800">
                {isEditing ? "Edit Company" : "New Company"}
              </h2>
              {isEditing && (
                <p className="mt-1 text-sm text-orange-600">
                  Editing existing company
                </p>
              )}
            </div>

            <div className="flex flex-wrap gap-2">
              {/* ← PERM: New button only when user can Add */}
              {canAddCompany && (
                <button
                  type="button"
                  onClick={handleNew}
                  disabled={generatingCode || saving}
                  className="rounded-lg bg-indigo-600 px-5 py-2.5 text-sm font-semibold text-white shadow-sm transition hover:bg-indigo-700 disabled:cursor-not-allowed disabled:opacity-50"
                >
                  {generatingCode ? "Generating..." : "New"}
                </button>
              )}

              <button
                type="button"
                onClick={handleClear}
                disabled={saving}
                className="rounded-lg bg-gray-500 px-5 py-2.5 text-sm font-semibold text-white shadow-sm transition hover:bg-gray-600 disabled:cursor-not-allowed disabled:opacity-50"
              >
                Clear
              </button>
            </div>
          </div>

          <form onSubmit={handleSubmit} className="space-y-5">

            {/* COMPANY CODE + GENERATE */}
            <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
              <div className="md:col-span-2">
                <label className="mb-1.5 block text-sm font-semibold text-gray-700">
                  Company Code <span className="ml-1 text-red-500">*</span>
                </label>
                <input
                  type="text"
                  name="companycode"
                  value={form.companycode}
                  onChange={handleChange}
                  placeholder="Enter company code"
                  autoComplete="off"
                  disabled={isEditing}
                  className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2.5 text-sm outline-none transition focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 disabled:bg-gray-100 disabled:text-gray-500"
                  required
                />
              </div>

              <div className="flex items-end">
                {/* ← PERM: Generate button only when user can Add */}
                {canAddCompany && (
                  <button
                    type="button"
                    onClick={generateCompanyCode}
                    disabled={generatingCode || isEditing}
                    className="w-full rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white transition hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
                  >
                    {generatingCode ? "Generating..." : "Generate Code"}
                  </button>
                )}
              </div>
            </div>

            {/* COMPANY NAME */}
            <div>
              <label className="mb-1.5 block text-sm font-semibold text-gray-700">
                Company Name <span className="ml-1 text-red-500">*</span>
              </label>
              <input
                type="text"
                name="companyname"
                value={form.companyname}
                onChange={handleChange}
                placeholder="Enter company name"
                autoComplete="off"
                className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm outline-none transition focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200"
                required
              />
            </div>

            {/* ADDRESS */}
            <div>
              <label className="mb-1.5 block text-sm font-semibold text-gray-700">
                Address <span className="ml-1 text-red-500">*</span>
              </label>
              <textarea
                name="address"
                value={form.address}
                onChange={handleChange}
                placeholder="Enter company address"
                rows={3}
                className="w-full resize-none rounded-lg border border-gray-300 px-3 py-2.5 text-sm outline-none transition focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200"
                required
              />
            </div>

            {/* MOBILE */}
            <div>
              <label className="mb-1.5 block text-sm font-semibold text-gray-700">
                Mobile Number <span className="ml-1 text-red-500">*</span>
              </label>
              <input
                type="text"
                name="mobileno"
                value={form.mobileno}
                onChange={handleChange}
                placeholder="Enter mobile number"
                autoComplete="off"
                className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm outline-none transition focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200"
                required
              />
            </div>

            {/* USERNAME */}
            <div>
              <label className="mb-1.5 block text-sm font-semibold text-gray-700">
                User
              </label>
              <input
                type="text"
                value={user?.username || ""}
                readOnly
                className="w-full rounded-lg border border-gray-200 bg-gray-100 px-3 py-2.5 text-sm text-gray-600 outline-none"
              />
            </div>

            {/* FORM BUTTONS */}
            <div className="flex flex-col gap-3 border-t pt-5 sm:flex-row sm:justify-end">
              {isEditing && (
                <button
                  type="button"
                  onClick={handleClear}
                  disabled={saving}
                  className="rounded-lg bg-gray-500 px-8 py-3 text-sm font-semibold text-white transition hover:bg-gray-600 disabled:opacity-50"
                >
                  Cancel Edit
                </button>
              )}

              {/* ← PERM: Save button only when saveAllowed */}
              {saveAllowed && (
                <button
                  type="submit"
                  disabled={saving}
                  className="rounded-lg bg-green-600 px-8 py-3 text-sm font-semibold text-white shadow-sm transition hover:bg-green-700 disabled:cursor-not-allowed disabled:opacity-50"
                >
                  {saving
                    ? "Saving..."
                    : isEditing
                    ? "Update Company"
                    : "Save Company"}
                </button>
              )}

              {/* ← PERM: helper text when blocked */}
              {readOnlyEdit && (
                <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 text-xs font-semibold text-slate-500">
                  You have read-only access — editing is disabled.
                </div>
              )}

              {!isEditing && !canAddCompany && (
                <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 text-xs font-semibold text-slate-500">
                  You do not have permission to create new companies.
                </div>
              )}
            </div>
          </form>
        </div>

        {/* COMPANY LIST */}
        <div className="rounded-xl bg-white p-5 shadow-md">
          <div className="mb-5 flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
            <div>
              <h2 className="text-xl font-bold text-gray-800">
                Company List
              </h2>
              <p className="mt-1 text-sm text-gray-500">
                {filteredCompanies.length} company
                {filteredCompanies.length !== 1 ? "ies" : ""}
              </p>
            </div>

            <div className="flex flex-col gap-2 sm:flex-row">
              <input
                type="text"
                value={searchText}
                onChange={(event) => setSearchText(event.target.value)}
                placeholder="Search company..."
                className="w-full rounded-lg border border-gray-300 px-4 py-2.5 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 sm:w-72"
              />
              <button
                type="button"
                onClick={loadCompanies}
                disabled={loading}
                className="rounded-lg bg-gray-700 px-5 py-2.5 text-sm font-semibold text-white transition hover:bg-gray-800 disabled:cursor-not-allowed disabled:opacity-50"
              >
                {loading ? "Loading..." : "Refresh"}
              </button>
            </div>
          </div>

          <div className="overflow-hidden rounded-lg border border-gray-200">
            <div className="overflow-x-auto">
              <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="whitespace-nowrap px-4 py-3 text-left text-xs font-bold uppercase tracking-wider text-gray-600">#</th>
                    <th className="whitespace-nowrap px-4 py-3 text-left text-xs font-bold uppercase tracking-wider text-gray-600">Code</th>
                    <th className="whitespace-nowrap px-4 py-3 text-left text-xs font-bold uppercase tracking-wider text-gray-600">Company Name</th>
                    <th className="whitespace-nowrap px-4 py-3 text-left text-xs font-bold uppercase tracking-wider text-gray-600">Address</th>
                    <th className="whitespace-nowrap px-4 py-3 text-left text-xs font-bold uppercase tracking-wider text-gray-600">Mobile</th>
                    <th className="whitespace-nowrap px-4 py-3 text-center text-xs font-bold uppercase tracking-wider text-gray-600">Actions</th>
                  </tr>
                </thead>

                <tbody className="divide-y divide-gray-200 bg-white">
                  {loading ? (
                    <tr>
                      <td colSpan="6" className="px-4 py-12 text-center">
                        <div className="flex flex-col items-center justify-center">
                          <div className="mb-3 h-8 w-8 animate-spin rounded-full border-4 border-gray-200 border-t-indigo-600" />
                          <p className="text-sm text-gray-500">Loading companies...</p>
                        </div>
                      </td>
                    </tr>
                  ) : filteredCompanies.length === 0 ? (
                    <tr>
                      <td colSpan="6" className="px-4 py-12 text-center">
                        <p className="font-medium text-gray-500">No companies found</p>
                        {searchText && (
                          <p className="mt-1 text-sm text-gray-400">Try another search.</p>
                        )}
                      </td>
                    </tr>
                  ) : (
                    filteredCompanies.map((company, index) => {
                      const id =
                        company?.CompanyID ??
                        company?.companyID ??
                        company?.companyId ??
                        company?.ID ??
                        company?.Id ??
                        company?.id;

                      const companyCode =
                        company?.CompanyCode ?? company?.companycode ?? "";
                      const companyName =
                        company?.CompanyName ?? company?.companyname ?? "";
                      const address =
                        company?.Address ?? company?.address ?? "";
                      const mobile =
                        company?.MobileNo ??
                        company?.mobileno ??
                        company?.Mobile ??
                        "";

                      return (
                        <tr
                          key={id ?? index}
                          className="transition hover:bg-gray-50"
                        >
                          <td className="whitespace-nowrap px-4 py-3 text-sm text-gray-600">
                            {index + 1}
                          </td>
                          <td className="whitespace-nowrap px-4 py-3 text-sm font-semibold text-indigo-600">
                            {companyCode}
                          </td>
                          <td className="whitespace-nowrap px-4 py-3 text-sm font-semibold text-gray-800">
                            {companyName}
                          </td>
                          <td className="max-w-xs px-4 py-3 text-sm text-gray-600">
                            <div className="truncate">{address}</div>
                          </td>
                          <td className="whitespace-nowrap px-4 py-3 text-sm text-gray-600">
                            {mobile}
                          </td>

                          {/* ← PERM: gate the action buttons */}
                          <td className="whitespace-nowrap px-4 py-3">
                            <div className="flex justify-center gap-2">
                              {canEditCompany && (
                                <button
                                  type="button"
                                  onClick={() => handleEdit(company)}
                                  disabled={deletingId !== null}
                                  className="rounded-lg bg-blue-600 px-4 py-2 text-xs font-semibold text-white transition hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
                                >
                                  Edit
                                </button>
                              )}

                              {canDeleteCompany && (
                                <button
                                  type="button"
                                  onClick={() => handleDelete(company)}
                                  disabled={deletingId !== null}
                                  className="rounded-lg bg-red-600 px-4 py-2 text-xs font-semibold text-white transition hover:bg-red-700 disabled:cursor-not-allowed disabled:opacity-50"
                                >
                                  {String(deletingId) === String(id)
                                    ? "Deleting..."
                                    : "Delete"}
                                </button>
                              )}

                              {!canEditCompany && !canDeleteCompany && (
                                <span className="text-xs text-slate-400">
                                  No actions
                                </span>
                              )}
                            </div>
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>

      </div>
    </div>
  );
}

export default Company;