
import React, {
    useCallback,
    useContext,
    useEffect,
    useMemo,
    useState
} from "react";
import axios from "axios";
import {
    ArrowRight,
    Check,
    ChevronDown,
    ClipboardList,
    Loader2,
    Package,
    Plus,
    RefreshCw,
    Search,
    Trash2,
    X
} from "lucide-react";
import { AuthContext } from "../pos/SERVER/AuthContext.js";

const API_URL = "http://localhost:5000";

/* ============================================================
   HELPERS
============================================================ */

const todayString = () => {
    const d = new Date();

    return [
        d.getFullYear(),
        String(d.getMonth() + 1).padStart(2, "0"),
        String(d.getDate()).padStart(2, "0")
    ].join("-");
};

const emptyForm = {
    togNo: "",
    togDate: todayString(),
    fromLocationID: "",
    toLocationID: "",
    referenceNo: "",
    remark: ""
};

const toNumber = (value, fallback = 0) => {
    if (
        value === null ||
        value === undefined ||
        value === ""
    ) {
        return fallback;
    }

    const number = Number(value);

    return Number.isFinite(number)
        ? number
        : fallback;
};

const firstValue = (...values) => {
    for (const value of values) {
        if (
            value !== undefined &&
            value !== null &&
            String(value).trim() !== ""
        ) {
            return value;
        }
    }

    return "";
};

const getRows = (data) => {
    if (Array.isArray(data)) {
        return data;
    }

    if (Array.isArray(data?.data)) {
        return data.data;
    }

    if (Array.isArray(data?.recordset)) {
        return data.recordset;
    }

    if (Array.isArray(data?.products)) {
        return data.products;
    }

    if (Array.isArray(data?.locations)) {
        return data.locations;
    }

    if (Array.isArray(data?.togs)) {
        return data.togs;
    }

    if (Array.isArray(data?.grns)) {
        return data.grns;
    }

    if (Array.isArray(data?.items)) {
        return data.items;
    }

    if (Array.isArray(data?.details)) {
        return data.details;
    }

    return [];
};

/* ============================================================
   PRODUCT HELPERS
============================================================ */

const getProductCode = (row) =>
    String(
        firstValue(
            row?.ProductCode,
            row?.productCode,
            row?.productcode,
            row?.StockCode,
            row?.stockCode,
            row?.stockcode
        )
    ).trim();

const getProductName = (row) =>
    String(
        firstValue(
            row?.ProductName,
            row?.productName,
            row?.productname
        )
    ).trim();

const getStock = (row) =>
    toNumber(
        firstValue(
            row?.Stock,
            row?.stock,
            row?.CurrentStock,
            row?.currentStock,
            row?.currentstock,
            row?.AvailableStock,
            row?.availableStock,
            0
        )
    );

const getQty = (row) =>
    toNumber(
        firstValue(
            row?.Qty,
            row?.qty,
            row?.Quantity,
            row?.quantity,
            row?.TransferQty,
            row?.transferQty,
            row?.ReceivedQty,
            row?.receivedQty,
            row?.receivedqty,
            0
        )
    );

const getCostPrice = (row) =>
    toNumber(
        firstValue(
            row?.CostPrice,
            row?.costPrice,
            row?.costprice,
            0
        )
    );

const getSellingPrice = (row) =>
    toNumber(
        firstValue(
            row?.SellingPrice,
            row?.sellingPrice,
            row?.sellingprice,
            0
        )
    );

/* ============================================================
   LOCATION HELPERS
============================================================ */

const getLocationID = (row) =>
    firstValue(
        row?.LocationID,
        row?.locationID,
        row?.locationId,
        row?.locationid,
        row?.ID,
        row?.id
    );

const getLocationNameFromRow = (row) =>
    String(
        firstValue(
            row?.LocationName,
            row?.locationName,
            row?.locationname,
            row?.LocationCode,
            row?.locationCode,
            row?.locationcode,
            row?.Name,
            row?.name,
            ""
        )
    ).trim();

/* ============================================================
   DOCUMENT HELPERS
============================================================ */

const getTOGNumber = (row) =>
    firstValue(
        row?.TOGNo,
        row?.togNo,
        row?.togno,
        row?.TOGNumber,
        row?.togNumber
    );

const getGRNNumber = (row) =>
    firstValue(
        row?.GRNNo,
        row?.grnNo,
        row?.grnno,
        row?.GRNNumber,
        row?.grnnumber
    );

/* ============================================================
   COMPONENT
============================================================ */

function TOG() {
    const { user } = useContext(AuthContext);

    const username =
        user?.username ||
        user?.Username ||
        localStorage.getItem("username") ||
        "";

    /* ========================================================
       FORM
    ======================================================== */

    const [form, setForm] = useState({
        ...emptyForm
    });

    /* ========================================================
       DATA
    ======================================================== */

    const [locations, setLocations] = useState([]);
    const [products, setProducts] = useState([]);
    const [items, setItems] = useState([]);

    /* ========================================================
       LOADING
    ======================================================== */

    const [loadingLocations, setLoadingLocations] =
        useState(false);

    const [loadingNumber, setLoadingNumber] =
        useState(false);

    const [loadingProducts, setLoadingProducts] =
        useState(false);

    const [saving, setSaving] = useState(false);

    const [loadingRecall, setLoadingRecall] =
        useState(false);

    /* ========================================================
       SEARCH
    ======================================================== */

    const [productSearch, setProductSearch] =
        useState("");

    /* ========================================================
       MESSAGES
    ======================================================== */

    const [message, setMessage] = useState("");
    const [error, setError] = useState("");

    /* ========================================================
       RECALL
    ======================================================== */

    const [showRecall, setShowRecall] =
        useState(false);

    const [recallType, setRecallType] =
        useState("GRN");

    const [recallSearch, setRecallSearch] =
        useState("");

    const [togList, setTogList] = useState([]);
    const [grnList, setGrnList] = useState([]);

    /* ========================================================
       CLEAR MESSAGES
    ======================================================== */

    const clearMessages = () => {
        setMessage("");
        setError("");
    };

    /* ========================================================
       LOCATION OPTIONS
    ======================================================== */

    const locationOptions = useMemo(() => {
        const seen = new Set();

        return locations
            .map((row) => {
                const id = getLocationID(row);

                return {
                    id: id,
                    name: getLocationNameFromRow(row)
                };
            })
            .filter((row) => {
                if (
                    row.id === "" ||
                    row.id === null ||
                    row.id === undefined
                ) {
                    return false;
                }

                const key = String(row.id);

                if (seen.has(key)) {
                    return false;
                }

                seen.add(key);

                return true;
            });
    }, [locations]);

    /* ========================================================
       LOCATION NAME
    ======================================================== */

    const getLocationName = useCallback(
        (locationID) => {
            if (
                locationID === "" ||
                locationID === null ||
                locationID === undefined
            ) {
                return "";
            }

            const row = locations.find(
                (location) =>
                    String(
                        getLocationID(location)
                    ) === String(locationID)
            );

            return row
                ? getLocationNameFromRow(row)
                : "";
        },
        [locations]
    );

    /* ========================================================
       LOAD TOG NUMBER
    ======================================================== */

    const loadTOGNumber = useCallback(async () => {
        setLoadingNumber(true);

        try {
            const response = await axios.get(
                `${API_URL}/tognumber`
            );

            console.log(
                "TOG NUMBER RESPONSE:",
                response.data
            );

            const data = response.data;

            const togNo = firstValue(
                data?.TOGNo,
                data?.togNo,
                data?.togno,
                data?.TOGNumber,
                data?.togNumber,
                data?.number,

                data?.data?.TOGNo,
                data?.data?.togNo,
                data?.data?.togno,
                data?.data?.TOGNumber,
                data?.data?.togNumber,
                data?.data?.number,

                data?.recordset?.[0]?.TOGNo,
                data?.recordset?.[0]?.togNo,
                data?.recordset?.[0]?.togno
            );

            if (!togNo) {
                throw new Error(
                    "Server did not return a TOG number."
                );
            }

            setForm((prev) => ({
                ...prev,
                togNo: String(togNo)
            }));
        } catch (err) {
            console.error(
                "TOG NUMBER ERROR:",
                err
            );

            setError(
                err?.response?.data?.message ||
                err?.message ||
                "Unable to generate TOG number."
            );
        } finally {
            setLoadingNumber(false);
        }
    }, []);

    /* ========================================================
       LOAD LOCATIONS
    ======================================================== */

    const loadLocations = useCallback(async () => {
        setLoadingLocations(true);

        try {
            const response = await axios.get(
                `${API_URL}/locations`
            );

            console.log(
                "LOCATIONS RESPONSE:",
                response.data
            );

            const rows = getRows(
                response.data
            );

            console.log(
                "LOCATION ROWS:",
                rows
            );

            setLocations(rows);

            if (rows.length === 0) {
                setError(
                    "No locations were returned from the server."
                );
            }
        } catch (err) {
            console.error(
                "LOCATION LOAD ERROR:",
                err
            );

            setLocations([]);

            setError(
                err?.response?.data?.message ||
                err?.message ||
                "Unable to load locations."
            );
        } finally {
            setLoadingLocations(false);
        }
    }, []);

    /* ========================================================
       INITIAL LOAD
    ======================================================== */

    useEffect(() => {
        loadTOGNumber();
        loadLocations();
    }, [
        loadTOGNumber,
        loadLocations
    ]);

    /* ========================================================
       HANDLE FORM CHANGE
    ======================================================== */

    const handleChange = (e) => {
        const {
            name,
            value
        } = e.target;

        clearMessages();

        /* -----------------------------------------------
           FROM LOCATION
        ------------------------------------------------ */

        if (
            name === "fromLocationID"
        ) {
            setForm((prev) => ({
                ...prev,
                fromLocationID: value,
                toLocationID: ""
            }));

            setItems([]);
            setProducts([]);
            setProductSearch("");

            return;
        }

        /* -----------------------------------------------
           TO LOCATION
        ------------------------------------------------ */

        if (
            name === "toLocationID"
        ) {
            setForm((prev) => ({
                ...prev,
                toLocationID: value
            }));

            return;
        }

        /* -----------------------------------------------
           OTHER FIELDS
        ------------------------------------------------ */

        setForm((prev) => ({
            ...prev,
            [name]: value
        }));
    };

    /* ========================================================
       SEARCH PRODUCTS
    ======================================================== */

    const searchProducts = async () => {
        clearMessages();

        const locationID =
            Number(form.fromLocationID);

        const searchText =
            productSearch.trim();

        if (!locationID) {
            setError(
                "Please select From Location first."
            );
            return;
        }

        if (!searchText) {
            setProducts([]);
            return;
        }

        setLoadingProducts(true);

        try {
            const response = await axios.get(
                `${API_URL}/api/tog/products`,
                {
                    params: {
                        locationID,
                        q: searchText,
                        search: searchText
                    }
                }
            );

            console.log(
                "PRODUCT RESPONSE:",
                response.data
            );

            if (
                response.data?.success === false
            ) {
                throw new Error(
                    response.data?.message ||
                    "Product search failed."
                );
            }

            const rows = getRows(
                response.data
            );

            setProducts(rows);

            if (rows.length === 0) {
                setMessage(
                    `No products found for "${searchText}" in ${
                        getLocationName(
                            locationID
                        ) ||
                        "selected location"
                    }.`
                );
            }
        } catch (err) {
            console.error(
                "PRODUCT SEARCH ERROR:",
                err
            );

            setProducts([]);

            setError(
                err?.response?.data?.message ||
                err?.message ||
                "Unable to search products."
            );
        } finally {
            setLoadingProducts(false);
        }
    };

    /* ========================================================
       PRODUCT ENTER
    ======================================================== */

    const handleProductKeyDown = (e) => {
        if (e.key === "Enter") {
            e.preventDefault();

            searchProducts();
        }
    };

    /* ========================================================
       GET ACTUAL STOCK
    ======================================================== */

    const getActualStock = async (
        product
    ) => {
        const productCode =
            getProductCode(product);

        const locationID =
            Number(form.fromLocationID);

        const fallbackStock =
            getStock(product);

        if (
            !productCode ||
            !locationID
        ) {
            return fallbackStock;
        }

        try {
            const response =
                await axios.get(
                    `${API_URL}/api/tog/stock/${locationID}/${encodeURIComponent(
                        productCode
                    )}`
                );

            const data =
                response.data;

            const stock =
                firstValue(
                    data?.Stock,
                    data?.stock,
                    data?.CurrentStock,
                    data?.currentStock,

                    data?.data?.Stock,
                    data?.data?.stock,
                    data?.data?.CurrentStock,
                    data?.data?.currentStock,

                    data?.recordset?.[0]?.Stock,
                    data?.recordset?.[0]?.stock
                );

            if (
                stock !== "" &&
                stock !== null &&
                stock !== undefined
            ) {
                return toNumber(
                    stock,
                    fallbackStock
                );
            }
        } catch (err) {
            console.warn(
                "STOCK API ERROR:",
                err?.response?.data ||
                err.message
            );
        }

        return fallbackStock;
    };

    /* ========================================================
       ADD PRODUCT
    ======================================================== */

    const addProduct = async (
        product
    ) => {
        clearMessages();

        const productCode =
            getProductCode(product);

        const productName =
            getProductName(product);

        if (!productCode) {
            setError(
                "Product code is missing."
            );
            return;
        }

        if (!form.fromLocationID) {
            setError(
                "Please select From Location."
            );
            return;
        }

        if (!form.toLocationID) {
            setError(
                "Please select To Location."
            );
            return;
        }

        if (
            String(
                form.fromLocationID
            ) ===
            String(
                form.toLocationID
            )
        ) {
            setError(
                "From Location and To Location cannot be the same."
            );
            return;
        }

        const alreadyExists =
            items.some(
                (item) =>
                    String(
                        item.productCode
                    ).toLowerCase() ===
                    String(
                        productCode
                    ).toLowerCase()
            );

        if (alreadyExists) {
            setError(
                `${productCode} is already added.`
            );
            return;
        }

        const stock =
            await getActualStock(
                product
            );

        if (stock <= 0) {
            setError(
                `${
                    productName ||
                    productCode
                } has no available stock in ${
                    getLocationName(
                        form.fromLocationID
                    ) ||
                    "the selected location"
                }.`
            );
            return;
        }

        const newItem = {
            id:
                firstValue(
                    product?.InvProductStockMasterID,
                    product?.InvProductMasterID,
                    product?.ProductID,
                    product?.productID
                ) ||
                `${productCode}-${Date.now()}`,

            productCode,

            productName,

            stock,

            costPrice:
                getCostPrice(product),

            sellingPrice:
                getSellingPrice(product),

            qty: 1
        };

        setItems((prev) => [
            ...prev,
            newItem
        ]);

        setProducts([]);
        setProductSearch("");

        setMessage(
            `${productName || productCode} added to TOG.`
        );
    };

    /* ========================================================
       CHANGE QUANTITY
    ======================================================== */

    const changeQty = (
        id,
        value
    ) => {
        const qty =
            toNumber(value);

        setItems((prev) =>
            prev.map((item) => {
                if (
                    item.id !== id
                ) {
                    return item;
                }

                if (
                    qty >
                    toNumber(
                        item.stock
                    )
                ) {
                    return {
                        ...item,
                        qty: toNumber(
                            item.stock
                        )
                    };
                }

                return {
                    ...item,
                    qty
                };
            })
        );
    };

    /* ========================================================
       REMOVE ITEM
    ======================================================== */

    const removeItem = (
        id
    ) => {
        setItems((prev) =>
            prev.filter(
                (item) =>
                    item.id !== id
            )
        );
    };

    /* ========================================================
       TOTAL QUANTITY
    ======================================================== */

    const totalQty = useMemo(
        () =>
            items.reduce(
                (
                    total,
                    item
                ) =>
                    total +
                    toNumber(
                        item.qty
                    ),
                0
            ),
        [items]
    );

    /* ========================================================
       VALIDATE TOG
    ======================================================== */

    const validateTOG = () => {
        if (!form.togNo) {
            return "TOG number is required.";
        }

        if (!form.togDate) {
            return "TOG date is required.";
        }

        if (!form.fromLocationID) {
            return "From Location is required.";
        }

        if (!form.toLocationID) {
            return "To Location is required.";
        }

        if (
            String(
                form.fromLocationID
            ) ===
            String(
                form.toLocationID
            )
        ) {
            return "From Location and To Location cannot be the same.";
        }

        if (
            items.length === 0
        ) {
            return "Please add at least one product.";
        }

        for (
            const item of items
        ) {
            const qty =
                toNumber(
                    item.qty
                );

            const stock =
                toNumber(
                    item.stock
                );

            if (!item.productCode) {
                return "Product code is missing.";
            }

            if (qty <= 0) {
                return `${item.productCode}: quantity must be greater than zero.`;
            }

            if (qty > stock) {
                return `${item.productCode}: transfer quantity cannot exceed available stock.`;
            }
        }

        return "";
    };

    /* ========================================================
       SAVE TOG
    ======================================================== */

    const saveTOG = async () => {
        clearMessages();

        const validationError =
            validateTOG();

        if (validationError) {
            setError(
                validationError
            );
            return;
        }

        setSaving(true);

        try {
            const payload = {
                TOGNo:
                    String(
                        form.togNo
                    ).trim(),

                TOGDate:
                    form.togDate,

                FromLocationID:
                    Number(
                        form.fromLocationID
                    ),

                ToLocationID:
                    Number(
                        form.toLocationID
                    ),

                ReferenceNo:
                    String(
                        form.referenceNo || ""
                    ).trim(),

                Remark:
                    String(
                        form.remark || ""
                    ).trim(),

                Username:
                    username,

                TotalQty:
                    totalQty,

                Items:
                    items.map(
                        (item) => ({
                            ProductCode:
                                item.productCode,

                            ProductName:
                                item.productName,

                            Qty:
                                toNumber(
                                    item.qty
                                ),

                            Stock:
                                toNumber(
                                    item.stock
                                ),

                            CostPrice:
                                toNumber(
                                    item.costPrice
                                ),

                            SellingPrice:
                                toNumber(
                                    item.sellingPrice
                                )
                        })
                    )
            };

            console.log(
                "================================"
            );

            console.log(
                "TOG SAVE PAYLOAD"
            );

            console.log(
                payload
            );

            const response =
                await axios.post(
                    `${API_URL}/TOG`,
                    payload
                );

            console.log(
                "TOG SAVE RESPONSE:",
                response.data
            );

            if (
                response.data?.success === false
            ) {
                throw new Error(
                    response.data?.message ||
                    "TOG save failed."
                );
            }

            setMessage(
                response.data?.message ||
                `TOG ${form.togNo} saved successfully.`
            );

            setItems([]);
            setProducts([]);
            setProductSearch("");

            setForm((prev) => ({
                ...prev,
                fromLocationID: "",
                toLocationID: "",
                referenceNo: "",
                remark: ""
            }));

            await loadTOGNumber();
        } catch (err) {
            console.error(
                "TOG SAVE ERROR:",
                err
            );

            setError(
                err?.response?.data?.message ||
                err?.message ||
                "Unable to save TOG."
            );
        } finally {
            setSaving(false);
        }
    };

    /* ========================================================
       NEW TOG
    ======================================================== */

    const newTOG = async () => {
        clearMessages();

        setForm({
            ...emptyForm,
            togDate: todayString()
        });

        setItems([]);
        setProducts([]);
        setProductSearch("");

        await loadTOGNumber();
    };

    /* ========================================================
       LOAD TOG LIST
    ======================================================== */

    const loadTOGList = async () => {
        try {
            const response =
                await axios.get(
                    `${API_URL}/api/tog`
                );

            console.log(
                "TOG LIST:",
                response.data
            );

            setTogList(
                getRows(
                    response.data
                )
            );
        } catch (err) {
            console.error(
                "TOG LIST ERROR:",
                err
            );

            setError(
                err?.response?.data?.message ||
                "Unable to load TOG list."
            );
        }
    };

    /* ========================================================
       LOAD GRN LIST
    ======================================================== */

    const loadGRNList = async () => {
        try {
            const response =
                await axios.get(
                    `${API_URL}/api/grn`
                );

            console.log(
                "GRN LIST:",
                response.data
            );

            setGrnList(
                getRows(
                    response.data
                )
            );
        } catch (err) {
            console.error(
                "GRN LIST ERROR:",
                err
            );

            setError(
                err?.response?.data?.message ||
                "Unable to load GRN list."
            );
        }
    };

    /* ========================================================
       OPEN RECALL
    ======================================================== */

    const openRecall = async (
        type
    ) => {
        clearMessages();

        setRecallType(type);
        setRecallSearch("");
        setShowRecall(true);
        setLoadingRecall(true);

        try {
            if (
                type === "GRN"
            ) {
                await loadGRNList();
            } else {
                await loadTOGList();
            }
        } finally {
            setLoadingRecall(false);
        }
    };

    /* ========================================================
       RECALL TOG
    ======================================================== */

    const recallTOG = async (
        row
    ) => {
        clearMessages();

        const togNo =
            getTOGNumber(row);

        if (!togNo) {
            setError(
                "Invalid TOG number."
            );
            return;
        }

        setLoadingRecall(true);

        try {
            const response =
                await axios.get(
                    `${API_URL}/api/tog/${encodeURIComponent(
                        togNo
                    )}`
                );

            const data =
                response.data;

            console.log(
                "RECALL TOG RESPONSE:",
                data
            );

            const header =
                data?.header ||
                data?.tog ||
                data?.data?.header ||
                data?.data?.tog ||
                data;

            const detailRows =
                getRows(
                    data?.items ||
                    data?.details ||
                    data?.data?.items ||
                    data?.data?.details ||
                    []
                );

            setForm({
                togNo:
                    String(
                        firstValue(
                            header?.TOGNo,
                            header?.togNo,
                            togNo
                        )
                    ),

                togDate:
                    String(
                        firstValue(
                            header?.TOGDate,
                            header?.togDate,
                            todayString()
                        )
                    ).substring(
                        0,
                        10
                    ),

                fromLocationID:
                    firstValue(
                        header?.FromLocationID,
                        header?.fromLocationID,
                        ""
                    ),

                toLocationID:
                    firstValue(
                        header?.ToLocationID,
                        header?.toLocationID,
                        ""
                    ),

                referenceNo:
                    firstValue(
                        header?.ReferenceNo,
                        header?.referenceNo,
                        ""
                    ),

                remark:
                    firstValue(
                        header?.Remark,
                        header?.remark,
                        ""
                    )
            });

            const mappedItems =
                detailRows
                    .map(
                        (
                            item,
                            index
                        ) => {
                            const code =
                                getProductCode(
                                    item
                                );

                            if (!code) {
                                return null;
                            }

                            return {
                                id:
                                    firstValue(
                                        item?.TOGDetailID,
                                        item?.togDetailID
                                    ) ||
                                    `${code}-${index}`,

                                productCode:
                                    code,

                                productName:
                                    getProductName(
                                        item
                                    ),

                                stock:
                                    getStock(
                                        item
                                    ),

                                costPrice:
                                    getCostPrice(
                                        item
                                    ),

                                sellingPrice:
                                    getSellingPrice(
                                        item
                                    ),

                                qty:
                                    getQty(
                                        item
                                    )
                            };
                        }
                    )
                    .filter(Boolean);

            setItems(
                mappedItems
            );

            setProducts([]);
            setProductSearch("");
            setShowRecall(false);

            setMessage(
                `TOG ${togNo} recalled successfully.`
            );
        } catch (err) {
            console.error(
                "RECALL TOG ERROR:",
                err
            );

            setError(
                err?.response?.data?.message ||
                err?.message ||
                "Unable to recall TOG."
            );
        } finally {
            setLoadingRecall(false);
        }
    };

    /* ========================================================
       RECALL GRN
    ======================================================== */

    const recallGRN = async (
        row
    ) => {
        clearMessages();

        const grnNo =
            getGRNNumber(row);

        if (!grnNo) {
            setError(
                "Invalid GRN number."
            );
            return;
        }

        setLoadingRecall(true);

        try {
            const response =
                await axios.get(
                    `${API_URL}/api/grn/${encodeURIComponent(
                        grnNo
                    )}`
                );

            const data =
                response.data;

            console.log(
                "RECALL GRN RESPONSE:",
                data
            );

            const header =
                data?.header ||
                data?.grn ||
                data?.data?.header ||
                data?.data?.grn ||
                data;

            const detailRows =
                getRows(
                    data?.items ||
                    data?.details ||
                    data?.data?.items ||
                    data?.data?.details ||
                    []
                );

            const grnLocation =
                firstValue(
                    header?.LocationID,
                    header?.locationID,
                    header?.locationId,
                    header?.Location,
                    header?.location,
                    ""
                );

            const selectedFromLocation =
                form.fromLocationID ||
                grnLocation;

            setForm((prev) => ({
                ...prev,

                fromLocationID:
                    prev.fromLocationID ||
                    grnLocation,

                referenceNo:
                    grnNo,

                remark:
                    prev.remark ||
                    `Recalled from GRN ${grnNo}`
            }));

            const mappedItems = [];

            for (
                let index = 0;
                index <
                detailRows.length;
                index++
            ) {
                const item =
                    detailRows[index];

                const code =
                    getProductCode(
                        item
                    );

                if (!code) {
                    continue;
                }

                let stock =
                    getStock(
                        item
                    );

                /* -----------------------------------------
                   Check actual stock
                ----------------------------------------- */

                if (
                    selectedFromLocation
                ) {
                    try {
                        const stockResponse =
                            await axios.get(
                                `${API_URL}/api/tog/stock/${Number(
                                    selectedFromLocation
                                )}/${encodeURIComponent(
                                    code
                                )}`
                            );

                        const serverStock =
                            firstValue(
                                stockResponse?.data?.Stock,
                                stockResponse?.data?.stock,

                                stockResponse?.data?.CurrentStock,
                                stockResponse?.data?.currentStock,

                                stockResponse?.data?.data?.Stock,
                                stockResponse?.data?.data?.stock,

                                stockResponse?.data?.recordset?.[0]?.Stock,
                                stockResponse?.data?.recordset?.[0]?.stock
                            );

                        if (
                            serverStock !== ""
                        ) {
                            stock =
                                toNumber(
                                    serverStock,
                                    stock
                                );
                        }
                    } catch (
                        stockError
                    ) {
                        console.warn(
                            "GRN STOCK CHECK ERROR:",
                            stockError
                        );
                    }
                }

                const grnQty =
                    getQty(item);

                const transferQty =
                    stock > 0
                        ? Math.min(
                            grnQty > 0
                                ? grnQty
                                : 1,
                            stock
                        )
                        : 0;

                mappedItems.push({
                    id:
                        firstValue(
                            item?.GRNDetailID,
                            item?.grnDetailID
                        ) ||
                        `${code}-${index}`,

                    productCode:
                        code,

                    productName:
                        getProductName(
                            item
                        ),

                    stock,

                    costPrice:
                        getCostPrice(
                            item
                        ),

                    sellingPrice:
                        getSellingPrice(
                            item
                        ),

                    qty:
                        transferQty
                });
            }

            setItems(
                mappedItems
            );

            setProducts([]);
            setProductSearch("");
            setShowRecall(false);

            if (
                mappedItems.length === 0
            ) {
                setError(
                    `No usable products found in GRN ${grnNo}.`
                );
            } else {
                setMessage(
                    `GRN ${grnNo} recalled successfully. ${mappedItems.length} product(s) loaded.`
                );
            }
        } catch (err) {
            console.error(
                "RECALL GRN ERROR:",
                err
            );

            setError(
                err?.response?.data?.message ||
                err?.message ||
                "Unable to recall GRN."
            );
        } finally {
            setLoadingRecall(false);
        }
    };

    /* ========================================================
       FILTER RECALL
    ======================================================== */

    const filteredRecallRows =
        useMemo(() => {
            const source =
                recallType === "GRN"
                    ? grnList
                    : togList;

            const q =
                recallSearch
                    .trim()
                    .toLowerCase();

            if (!q) {
                return source;
            }

            return source.filter(
                (row) => {
                    const text = [
                        getGRNNumber(row),
                        getTOGNumber(row),

                        row?.ReferenceNo,
                        row?.referenceNo,

                        row?.SupplierName,
                        row?.supplierName,

                        row?.SupplierCode,
                        row?.supplierCode
                    ]
                        .filter(Boolean)
                        .join(" ")
                        .toLowerCase();

                    return text.includes(q);
                }
            );
        }, [
            recallType,
            recallSearch,
            grnList,
            togList
        ]);

    /* ========================================================
       RENDER
    ======================================================== */

    return (
        <div className="min-h-screen bg-slate-100 p-4 md:p-6">

            <div className="mx-auto max-w-7xl">

                {/* ==================================================
                   HEADER
                ================================================== */}

                <div className="mb-5 flex flex-col gap-4 rounded-xl bg-white p-5 shadow-sm lg:flex-row lg:items-center lg:justify-between">

                    <div className="flex items-center gap-3">

                        <div className="rounded-xl bg-indigo-600 p-3 text-white">
                            <Package size={24} />
                        </div>

                        <div>
                            <h1 className="text-2xl font-bold text-slate-800">
                                Transfer Outgoing
                            </h1>

                            <p className="text-sm text-slate-500">
                                Transfer stock from one location to another
                            </p>
                        </div>

                    </div>

                    <div className="flex flex-wrap gap-2">

                        <button
                            type="button"
                            onClick={() =>
                                openRecall("GRN")
                            }
                            className="flex items-center gap-2 rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50"
                        >
                            <ClipboardList size={17} />
                            Recall GRN
                        </button>

                        <button
                            type="button"
                            onClick={() =>
                                openRecall("TOG")
                            }
                            className="flex items-center gap-2 rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50"
                        >
                            <RefreshCw size={17} />
                            Recall TOG
                        </button>

                        <button
                            type="button"
                            onClick={newTOG}
                            className="flex items-center gap-2 rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50"
                        >
                            <RefreshCw size={17} />
                            New
                        </button>

                        <button
                            type="button"
                            onClick={saveTOG}
                            disabled={
                                saving ||
                                loadingNumber
                            }
                            className="flex items-center gap-2 rounded-lg bg-indigo-600 px-5 py-2 text-sm font-bold text-white hover:bg-indigo-700 disabled:cursor-not-allowed disabled:opacity-50"
                        >
                            {saving ? (
                                <Loader2
                                    size={17}
                                    className="animate-spin"
                                />
                            ) : (
                                <Check size={17} />
                            )}

                            {saving
                                ? "Saving..."
                                : "Save TOG"}
                        </button>

                    </div>

                </div>

                {/* ==================================================
                   MESSAGES
                ================================================== */}

                {message && (
                    <div className="mb-4 flex items-center justify-between rounded-lg border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-medium text-emerald-700">

                        <span>
                            {message}
                        </span>

                        <button
                            type="button"
                            onClick={() =>
                                setMessage("")
                            }
                        >
                            <X size={17} />
                        </button>

                    </div>
                )}

                {error && (
                    <div className="mb-4 flex items-center justify-between rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700">

                        <span>
                            {error}
                        </span>

                        <button
                            type="button"
                            onClick={() =>
                                setError("")
                            }
                        >
                            <X size={17} />
                        </button>

                    </div>
                )}

                {/* ==================================================
                   TRANSFER HEADER
                ================================================== */}

                <div className="mb-5 rounded-xl bg-white p-5 shadow-sm">

                    <div className="mb-4 flex items-center gap-2">

                        <ClipboardList
                            size={19}
                            className="text-indigo-600"
                        />

                        <h2 className="font-bold text-slate-800">
                            Transfer Details
                        </h2>

                    </div>

                    <div className="grid grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-4">

                        {/* TOG NUMBER */}

                        <div>

                            <label className="mb-1 block text-xs font-semibold text-slate-600">
                                TOG Number
                            </label>

                            <div className="relative">

                                <input
                                    value={
                                        form.togNo
                                    }
                                    readOnly
                                    className="w-full rounded-lg border border-slate-300 bg-slate-100 px-3 py-2 text-sm font-bold text-slate-700"
                                />

                                {loadingNumber && (
                                    <Loader2
                                        size={16}
                                        className="absolute right-3 top-1/2 -translate-y-1/2 animate-spin text-indigo-600"
                                    />
                                )}

                            </div>

                        </div>

                        {/* DATE */}

                        <div>

                            <label className="mb-1 block text-xs font-semibold text-slate-600">
                                TOG Date *
                            </label>

                            <input
                                type="date"
                                name="togDate"
                                value={
                                    form.togDate
                                }
                                onChange={
                                    handleChange
                                }
                                className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100"
                            />

                        </div>

                        {/* FROM LOCATION */}

                        <div>

                            <label className="mb-1 block text-xs font-semibold text-slate-600">
                                From Location *
                            </label>

                            <select
                                name="fromLocationID"
                                value={
                                    form.fromLocationID ||
                                    ""
                                }
                                onChange={
                                    handleChange
                                }
                                disabled={
                                    loadingLocations ||
                                    locationOptions.length === 0
                                }
                                className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100 disabled:bg-slate-100"
                            >

                                <option value="">
                                    {loadingLocations
                                        ? "Loading locations..."
                                        : locationOptions.length === 0
                                            ? "No locations available"
                                            : "Select From Location"}
                                </option>

                                {locationOptions.map(
                                    (location) => (
                                        <option
                                            key={String(
                                                location.id
                                            )}
                                            value={String(
                                                location.id
                                            )}
                                        >
                                            {location.name ||
                                                `Location ${location.id}`}
                                        </option>
                                    )
                                )}

                            </select>

                        </div>

                        {/* TO LOCATION */}

                        <div>

                            <label className="mb-1 block text-xs font-semibold text-slate-600">
                                To Location *
                            </label>

                            <select
                                name="toLocationID"
                                value={
                                    form.toLocationID ||
                                    ""
                                }
                                onChange={
                                    handleChange
                                }
                                disabled={
                                    loadingLocations ||
                                    locationOptions.length === 0
                                }
                                className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100 disabled:bg-slate-100"
                            >

                                <option value="">
                                    {loadingLocations
                                        ? "Loading locations..."
                                        : locationOptions.length === 0
                                            ? "No locations available"
                                            : "Select To Location"}
                                </option>

                                {locationOptions.map(
                                    (location) => {

                                        const locationId =
                                            String(
                                                location.id
                                            );

                                        const fromId =
                                            String(
                                                form.fromLocationID ||
                                                ""
                                            );

                                        const isSame =
                                            fromId !== "" &&
                                            locationId ===
                                            fromId;

                                        return (
                                            <option
                                                key={
                                                    locationId
                                                }
                                                value={
                                                    locationId
                                                }
                                                disabled={
                                                    isSame
                                                }
                                            >
                                                {location.name ||
                                                    `Location ${location.id}`}
                                                {isSame
                                                    ? " (From Location)"
                                                    : ""}
                                            </option>
                                        );
                                    }
                                )}

                            </select>

                        </div>

                    </div>

                    {/* REFERENCE / REMARK */}

                    <div className="mt-4 grid grid-cols-1 gap-4 md:grid-cols-2">

                        <div>

                            <label className="mb-1 block text-xs font-semibold text-slate-600">
                                Reference No
                            </label>

                            <input
                                name="referenceNo"
                                value={
                                    form.referenceNo
                                }
                                onChange={
                                    handleChange
                                }
                                placeholder="Optional reference"
                                className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100"
                            />

                        </div>

                        <div>

                            <label className="mb-1 block text-xs font-semibold text-slate-600">
                                Remark
                            </label>

                            <input
                                name="remark"
                                value={
                                    form.remark
                                }
                                onChange={
                                    handleChange
                                }
                                placeholder="Optional remark"
                                className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100"
                            />

                        </div>

                    </div>

                </div>

                {/* ==================================================
                   PRODUCT SEARCH
                ================================================== */}

                <div className="mb-5 rounded-xl bg-white p-5 shadow-sm">

                    <div className="mb-4 flex flex-col gap-2 md:flex-row md:items-center md:justify-between">

                        <div className="flex items-center gap-2">

                            <Search
                                size={19}
                                className="text-indigo-600"
                            />

                            <h2 className="font-bold text-slate-800">
                                Search Product
                            </h2>

                        </div>

                        {form.fromLocationID && (
                            <div className="rounded-full bg-indigo-50 px-3 py-1 text-xs font-bold text-indigo-700">
                                Stock Location:{" "}
                                {getLocationName(
                                    form.fromLocationID
                                ) ||
                                    form.fromLocationID}
                            </div>
                        )}

                    </div>

                    <div className="flex flex-col gap-2 md:flex-row">

                        <div className="relative flex-1">

                            <Search
                                size={18}
                                className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"
                            />

                            <input
                                value={
                                    productSearch
                                }
                                onChange={(e) =>
                                    setProductSearch(
                                        e.target.value
                                    )
                                }
                                onKeyDown={
                                    handleProductKeyDown
                                }
                                disabled={
                                    !form.fromLocationID
                                }
                                placeholder={
                                    form.fromLocationID
                                        ? "Search product code or product name..."
                                        : "Select From Location first..."
                                }
                                className="w-full rounded-lg border border-slate-300 py-2.5 pl-10 pr-3 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100 disabled:bg-slate-100"
                            />

                        </div>

                        <button
                            type="button"
                            onClick={
                                searchProducts
                            }
                            disabled={
                                loadingProducts ||
                                !form.fromLocationID ||
                                !productSearch.trim()
                            }
                            className="flex items-center justify-center gap-2 rounded-lg bg-indigo-600 px-6 py-2.5 text-sm font-bold text-white hover:bg-indigo-700 disabled:cursor-not-allowed disabled:opacity-50"
                        >

                            {loadingProducts ? (
                                <Loader2
                                    size={17}
                                    className="animate-spin"
                                />
                            ) : (
                                <Search size={17} />
                            )}

                            Search

                        </button>

                    </div>

                    {/* SEARCH RESULTS */}

                    {products.length > 0 && (
                        <div className="mt-4 overflow-hidden rounded-lg border border-slate-200">

                            <div className="max-h-80 overflow-y-auto">

                                {products.map(
                                    (
                                        product,
                                        index
                                    ) => {

                                        const code =
                                            getProductCode(
                                                product
                                            );

                                        const name =
                                            getProductName(
                                                product
                                            );

                                        const stock =
                                            getStock(
                                                product
                                            );

                                        return (
                                            <div
                                                key={
                                                    firstValue(
                                                        product?.InvProductStockMasterID,
                                                        product?.InvProductMasterID,
                                                        product?.ProductID,
                                                        `${code}-${index}`
                                                    )
                                                }
                                                className="flex flex-col gap-3 border-b border-slate-100 p-4 last:border-0 hover:bg-slate-50 md:flex-row md:items-center md:justify-between"
                                            >

                                                <div className="min-w-0">

                                                    <div className="font-bold text-slate-800">
                                                        {name ||
                                                            "Unnamed Product"}
                                                    </div>

                                                    <div className="mt-1 flex flex-wrap gap-2">

                                                        <span className="rounded bg-slate-100 px-2 py-1 text-xs font-semibold text-slate-600">
                                                            {code}
                                                        </span>

                                                        <span
                                                            className={`rounded px-2 py-1 text-xs font-bold ${
                                                                stock >
                                                                0
                                                                    ? "bg-emerald-50 text-emerald-700"
                                                                    : "bg-red-50 text-red-700"
                                                            }`}
                                                        >
                                                            Stock:{" "}
                                                            {
                                                                stock
                                                            }
                                                        </span>

                                                    </div>

                                                </div>

                                                <button
                                                    type="button"
                                                    onClick={() =>
                                                        addProduct(
                                                            product
                                                        )
                                                    }
                                                    disabled={
                                                        stock <=
                                                        0
                                                    }
                                                    className="flex items-center justify-center gap-2 rounded-lg bg-emerald-600 px-5 py-2 text-sm font-bold text-white hover:bg-emerald-700 disabled:cursor-not-allowed disabled:bg-slate-300"
                                                >

                                                    <Plus
                                                        size={17}
                                                    />

                                                    {stock >
                                                    0
                                                        ? "Add"
                                                        : "No Stock"}

                                                </button>

                                            </div>
                                        );
                                    }
                                )}

                            </div>

                        </div>
                    )}

                </div>

                {/* ==================================================
                   ITEMS
                ================================================== */}

                <div className="overflow-hidden rounded-xl bg-white shadow-sm">

                    <div className="flex flex-col gap-3 border-b border-slate-200 p-5 md:flex-row md:items-center md:justify-between">

                        <div>

                            <h2 className="font-bold text-slate-800">
                                Transfer Items
                            </h2>

                            <p className="text-xs text-slate-500">
                                {items.length} product(s)
                            </p>

                        </div>

                        <div className="rounded-lg bg-indigo-50 px-4 py-2 text-sm font-bold text-indigo-700">

                            Total Qty:

                            <span className="ml-1 text-lg">
                                {totalQty}
                            </span>

                        </div>

                    </div>

                    <div className="overflow-x-auto">

                        <table className="min-w-full text-sm">

                            <thead className="bg-slate-50">

                                <tr>

                                    <th className="px-4 py-3 text-left text-xs font-bold uppercase text-slate-500">
                                        #
                                    </th>

                                    <th className="px-4 py-3 text-left text-xs font-bold uppercase text-slate-500">
                                        Product Code
                                    </th>

                                    <th className="px-4 py-3 text-left text-xs font-bold uppercase text-slate-500">
                                        Product Name
                                    </th>

                                    <th className="px-4 py-3 text-right text-xs font-bold uppercase text-slate-500">
                                        Stock
                                    </th>

                                    <th className="px-4 py-3 text-right text-xs font-bold uppercase text-slate-500">
                                        Qty
                                    </th>

                                    <th className="px-4 py-3 text-center text-xs font-bold uppercase text-slate-500">
                                        Action
                                    </th>

                                </tr>

                            </thead>

                            <tbody>

                                {items.length === 0 ? (

                                    <tr>

                                        <td
                                            colSpan="6"
                                            className="px-4 py-16 text-center"
                                        >

                                            <Package
                                                size={42}
                                                className="mx-auto mb-3 text-slate-300"
                                            />

                                            <div className="font-semibold text-slate-500">
                                                No products added
                                            </div>

                                            <div className="mt-1 text-xs text-slate-400">
                                                Search a product and click Add.
                                            </div>

                                        </td>

                                    </tr>

                                ) : (

                                    items.map(
                                        (
                                            item,
                                            index
                                        ) => (

                                            <tr
                                                key={
                                                    item.id
                                                }
                                                className="border-t border-slate-100"
                                            >

                                                <td className="px-4 py-3 text-slate-500">
                                                    {index + 1}
                                                </td>

                                                <td className="px-4 py-3 font-bold text-slate-700">
                                                    {
                                                        item.productCode
                                                    }
                                                </td>

                                                <td className="px-4 py-3 font-medium text-slate-800">
                                                    {
                                                        item.productName
                                                    }
                                                </td>

                                                <td className="px-4 py-3 text-right font-bold text-slate-600">
                                                    {
                                                        item.stock
                                                    }
                                                </td>

                                                <td className="px-4 py-3 text-right">

                                                    <input
                                                        type="number"
                                                        min="0"
                                                        max={
                                                            item.stock
                                                        }
                                                        step="0.001"
                                                        value={
                                                            item.qty
                                                        }
                                                        onChange={(
                                                            e
                                                        ) =>
                                                            changeQty(
                                                                item.id,
                                                                e.target.value
                                                            )
                                                        }
                                                        className="w-28 rounded-lg border border-slate-300 px-3 py-2 text-right font-bold outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100"
                                                    />

                                                </td>

                                                <td className="px-4 py-3 text-center">

                                                    <button
                                                        type="button"
                                                        onClick={() =>
                                                            removeItem(
                                                                item.id
                                                            )
                                                        }
                                                        className="rounded-lg p-2 text-red-500 hover:bg-red-50"
                                                        title="Remove"
                                                    >
                                                        <Trash2
                                                            size={18}
                                                        />
                                                    </button>

                                                </td>

                                            </tr>

                                        )
                                    )

                                )}

                            </tbody>

                        </table>

                    </div>

                </div>

                {/* ==================================================
                   FOOTER
                ================================================== */}

                <div className="mt-5 flex flex-col gap-3 rounded-xl bg-white p-4 shadow-sm md:flex-row md:items-center md:justify-between">

                    <div className="text-sm text-slate-500">

                        <span className="font-bold text-slate-700">
                            {getLocationName(
                                form.fromLocationID
                            ) ||
                                "From Location"}
                        </span>

                        <ArrowRight
                            size={16}
                            className="mx-2 inline"
                        />

                        <span className="font-bold text-slate-700">
                            {getLocationName(
                                form.toLocationID
                            ) ||
                                "To Location"}
                        </span>

                    </div>

                    <button
                        type="button"
                        onClick={
                            saveTOG
                        }
                        disabled={
                            saving ||
                            loadingNumber
                        }
                        className="flex items-center justify-center gap-2 rounded-lg bg-indigo-600 px-7 py-3 font-bold text-white hover:bg-indigo-700 disabled:cursor-not-allowed disabled:opacity-50"
                    >

                        {saving ? (
                            <Loader2
                                size={18}
                                className="animate-spin"
                            />
                        ) : (
                            <Check
                                size={18}
                            />
                        )}

                        {saving
                            ? "Saving TOG..."
                            : `Save TOG ${
                                form.togNo ||
                                ""
                            }`}

                    </button>

                </div>

            </div>

            {/* ======================================================
               RECALL MODAL
            ====================================================== */}

            {showRecall && (

                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">

                    <div className="flex max-h-[90vh] w-full max-w-5xl flex-col overflow-hidden rounded-xl bg-white shadow-2xl">

                        {/* MODAL HEADER */}

                        <div className="flex items-center justify-between border-b border-slate-200 p-5">

                            <div>

                                <h2 className="text-xl font-bold text-slate-800">
                                    Recall {recallType}
                                </h2>

                                <p className="text-xs text-slate-500">
                                    Select a document to load into TOG.
                                </p>

                            </div>

                            <button
                                type="button"
                                onClick={() =>
                                    setShowRecall(
                                        false
                                    )
                                }
                                className="rounded-lg p-2 text-slate-500 hover:bg-slate-100"
                            >
                                <X size={20} />
                            </button>

                        </div>

                        {/* TYPE BUTTONS */}

                        <div className="flex gap-2 border-b border-slate-200 p-4">

                            <button
                                type="button"
                                onClick={() =>
                                    openRecall(
                                        "GRN"
                                    )
                                }
                                className={`rounded-lg px-4 py-2 text-sm font-bold ${
                                    recallType ===
                                    "GRN"
                                        ? "bg-indigo-600 text-white"
                                        : "bg-slate-100 text-slate-600"
                                }`}
                            >
                                GRN
                            </button>

                            <button
                                type="button"
                                onClick={() =>
                                    openRecall(
                                        "TOG"
                                    )
                                }
                                className={`rounded-lg px-4 py-2 text-sm font-bold ${
                                    recallType ===
                                    "TOG"
                                        ? "bg-indigo-600 text-white"
                                        : "bg-slate-100 text-slate-600"
                                }`}
                            >
                                TOG
                            </button>

                        </div>

                        {/* SEARCH */}

                        <div className="border-b border-slate-200 p-4">

                            <div className="relative">

                                <Search
                                    size={18}
                                    className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"
                                />

                                <input
                                    value={
                                        recallSearch
                                    }
                                    onChange={(e) =>
                                        setRecallSearch(
                                            e.target.value
                                        )
                                    }
                                    placeholder={`Search ${recallType} number...`}
                                    className="w-full rounded-lg border border-slate-300 py-2.5 pl-10 pr-3 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100"
                                />

                            </div>

                        </div>

                        {/* DOCUMENT LIST */}

                        <div className="flex-1 overflow-y-auto">

                            {loadingRecall ? (

                                <div className="flex items-center justify-center py-16">

                                    <Loader2
                                        size={32}
                                        className="animate-spin text-indigo-600"
                                    />

                                </div>

                            ) : filteredRecallRows.length === 0 ? (

                                <div className="py-16 text-center text-slate-400">

                                    No {recallType} documents found.

                                </div>

                            ) : (

                                <div className="divide-y divide-slate-100">

                                    {filteredRecallRows.map(
                                        (
                                            row,
                                            index
                                        ) => {

                                            const documentNo =
                                                recallType ===
                                                "GRN"
                                                    ? getGRNNumber(
                                                        row
                                                    )
                                                    : getTOGNumber(
                                                        row
                                                    );

                                            const date =
                                                firstValue(
                                                    row?.TOGDate,
                                                    row?.togDate,
                                                    row?.GRNDate,
                                                    row?.grnDate,
                                                    row?.DocumentDate,
                                                    row?.documentDate,
                                                    ""
                                                );

                                            const from =
                                                firstValue(
                                                    row?.FromLocationID,
                                                    row?.fromLocationID,
                                                    ""
                                                );

                                            const to =
                                                firstValue(
                                                    row?.ToLocationID,
                                                    row?.toLocationID,
                                                    ""
                                                );

                                            return (

                                                <div
                                                    key={
                                                        firstValue(
                                                            row?.TOGID,
                                                            row?.togid,
                                                            row?.GRNID,
                                                            row?.grnid
                                                        ) ||
                                                        `${documentNo}-${index}`
                                                    }
                                                    className="flex flex-col gap-3 p-4 hover:bg-slate-50 md:flex-row md:items-center md:justify-between"
                                                >

                                                    <div>

                                                        <div className="font-bold text-slate-800">
                                                            {
                                                                documentNo ||
                                                                "Unknown"
                                                            }
                                                        </div>

                                                        {date && (
                                                            <div className="mt-1 text-xs text-slate-500">
                                                                {
                                                                    date
                                                                }
                                                            </div>
                                                        )}

                                                        {recallType ===
                                                            "TOG" &&
                                                            (from ||
                                                                to) && (

                                                                <div className="mt-1 text-xs font-medium text-slate-500">

                                                                    {
                                                                        getLocationName(
                                                                            from
                                                                        ) ||
                                                                        from
                                                                    }

                                                                    <ArrowRight
                                                                        size={
                                                                            13
                                                                        }
                                                                        className="mx-1 inline"
                                                                    />

                                                                    {
                                                                        getLocationName(
                                                                            to
                                                                        ) ||
                                                                        to
                                                                    }

                                                                </div>

                                                            )}

                                                    </div>

                                                    <button
                                                        type="button"
                                                        onClick={() =>
                                                            recallType ===
                                                            "GRN"
                                                                ? recallGRN(
                                                                    row
                                                                )
                                                                : recallTOG(
                                                                    row
                                                                )
                                                        }
                                                        disabled={
                                                            loadingRecall
                                                        }
                                                        className="flex items-center justify-center gap-2 rounded-lg bg-indigo-600 px-5 py-2 text-sm font-bold text-white hover:bg-indigo-700 disabled:cursor-not-allowed disabled:opacity-50"
                                                    >

                                                        {loadingRecall ? (
                                                            <Loader2
                                                                size={17}
                                                                className="animate-spin"
                                                            />
                                                        ) : (
                                                            <ChevronDown
                                                                size={17}
                                                            />
                                                        )}

                                                        Recall

                                                    </button>

                                                </div>

                                            );
                                        }
                                    )}

                                </div>

                            )}

                        </div>

                    </div>

                </div>

            )}

        </div>
    );
}

export default TOG;

