import React, { useEffect, useMemo, useState } from "react";
import axios from "axios";

const API = "http://localhost:5000/api";

export default function SalesOrder() {
    const [customers, setCustomers] = useState([]);

    const [customerCode, setCustomerCode] = useState("");
    const [customerName, setCustomerName] = useState("");

    const [soDate, setSoDate] = useState(
        new Date().toISOString().substring(0, 10)
    );

    const [remark, setRemark] = useState("");
    const [discount, setDiscount] = useState(0);

    const [items, setItems] = useState([]);

    const [showPOModal, setShowPOModal] = useState(false);
    const [poSearch, setPOSearch] = useState("");
    const [poItems, setPOItems] = useState([]);
    const [loadingPO, setLoadingPO] = useState(false);

    const [saving, setSaving] = useState(false);

    // ----------------------------------------------------
    // Load Customers
    // ----------------------------------------------------

    useEffect(() => {
        loadCustomers();
    }, []);

    async function loadCustomers() {
        try {
            const response = await axios.get(
                `${API}/sales-orders/customers`
            );

            setCustomers(response.data);
        } catch (error) {
            console.error(error);
            alert("Unable to load customers");
        }
    }

    // ----------------------------------------------------
    // Search PO
    // ----------------------------------------------------

    async function searchPO(value = "") {
        setLoadingPO(true);

        try {
            const response = await axios.get(
                `${API}/sales-orders/recall-po`,
                {
                    params: {
                        search: value,
                    },
                }
            );

            setPOItems(
                response.data.map((item) => ({
                    ...item,
                    selected: false,
                    saleQty: Number(item.AvailableQty),
                }))
            );
        } catch (error) {
            console.error(error);
            alert("Unable to load purchase orders");
        } finally {
            setLoadingPO(false);
        }
    }

    function openPOModal() {
        setShowPOModal(true);
        setPOSearch("");
        searchPO();
    }

    function closePOModal() {
        setShowPOModal(false);
        setPOItems([]);
        setPOSearch("");
    }

    // ----------------------------------------------------
    // PO Selection
    // ----------------------------------------------------

    function togglePOItem(index) {
        setPOItems((current) => {
            const copy = [...current];

            copy[index] = {
                ...copy[index],
                selected: !copy[index].selected,
            };

            return copy;
        });
    }

    function updatePOQty(index, value) {
        setPOItems((current) => {
            const copy = [...current];

            let qty = Number(value);

            if (Number.isNaN(qty)) {
                qty = 0;
            }

            const available = Number(
                copy[index].AvailableQty
            );

            if (qty < 0) {
                qty = 0;
            }

            if (qty > available) {
                qty = available;
            }

            copy[index] = {
                ...copy[index],
                saleQty: qty,
            };

            return copy;
        });
    }

    function selectAllPO() {
        setPOItems((current) =>
            current.map((item) => ({
                ...item,
                selected: true,
            }))
        );
    }

    function clearAllPO() {
        setPOItems((current) =>
            current.map((item) => ({
                ...item,
                selected: false,
            }))
        );
    }

    // ----------------------------------------------------
    // Add PO Products to SO
    // ----------------------------------------------------

    function addPOItems() {
        const selected = poItems.filter(
            (item) =>
                item.selected &&
                Number(item.saleQty) > 0
        );

        if (selected.length === 0) {
            alert("Please select at least one product");
            return;
        }

        setItems((current) => {
            const updated = [...current];

            selected.forEach((item) => {
                const existingIndex = updated.findIndex(
                    (x) =>
                        x.productCode === item.productcode &&
                        x.poID === item.poID
                );

                if (existingIndex >= 0) {
                    updated[existingIndex] = {
                        ...updated[existingIndex],
                        qty:
                            Number(
                                updated[existingIndex].qty
                            ) +
                            Number(item.saleQty),
                    };
                } else {
                    updated.push({
                        poID: item.poID,
                        pono: item.pono,

                        productCode:
                            item.productcode,

                        productName:
                            item.productname,

                        qty: Number(item.saleQty),

                        sellingPrice:
                            Number(item.sellingprice),

                        discountPercentage:
                            Number(
                                item.fixeddiscountpercentage ||
                                    0
                            ),
                    });
                }
            });

            return updated;
        });

        closePOModal();
    }

    // ----------------------------------------------------
    // Sales Order Items
    // ----------------------------------------------------

    function updateItem(index, field, value) {
        setItems((current) => {
            const copy = [...current];

            let newValue = value;

            if (
                field === "qty" ||
                field === "sellingPrice" ||
                field === "discountPercentage"
            ) {
                newValue = Number(value);

                if (Number.isNaN(newValue)) {
                    newValue = 0;
                }
            }

            copy[index] = {
                ...copy[index],
                [field]: newValue,
            };

            return copy;
        });
    }

    function removeItem(index) {
        setItems((current) =>
            current.filter((_, i) => i !== index)
        );
    }

    // ----------------------------------------------------
    // Calculations
    // ----------------------------------------------------

    const subTotal = useMemo(() => {
        return items.reduce((sum, item) => {
            const gross =
                Number(item.qty) *
                Number(item.sellingPrice);

            const discountAmount =
                (gross *
                    Number(
                        item.discountPercentage || 0
                    )) /
                100;

            return sum + gross - discountAmount;
        }, 0);
    }, [items]);

    const grandTotal =
        subTotal - Number(discount || 0);

    // ----------------------------------------------------
    // Save
    // ----------------------------------------------------

    async function saveSalesOrder() {
        if (!customerCode) {
            alert("Please select customer");
            return;
        }

        if (items.length === 0) {
            alert("Please add at least one product");
            return;
        }

        for (const item of items) {
            if (Number(item.qty) <= 0) {
                alert(
                    `Invalid quantity for ${item.productName}`
                );
                return;
            }
        }

        try {
            setSaving(true);

            const response = await axios.post(
                `${API}/sales-orders`,
                {
                    soDate,

                    customerCode,
                    customerName,

                    discount: Number(discount || 0),

                    remark,

                    createdUser: "admin",

                    items,
                }
            );

            alert(
                `Sales Order ${response.data.soNo} saved successfully`
            );

            setItems([]);
            setDiscount(0);
            setRemark("");
        } catch (error) {
            console.error(error);

            alert(
                error.response?.data?.message ||
                    "Unable to save Sales Order"
            );
        } finally {
            setSaving(false);
        }
    }

    // ----------------------------------------------------
    // Render
    // ----------------------------------------------------

    return (
        <div className="min-h-screen bg-slate-100 p-4 md:p-6">

            {/* PAGE HEADER */}
            <div className="mb-6 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">

                <div>
                    <h1 className="text-2xl font-bold text-slate-800">
                        Sales Order
                    </h1>

                    <p className="mt-1 text-sm text-slate-500">
                        Create a new sales order
                    </p>
                </div>

                <button
                    type="button"
                    onClick={openPOModal}
                    className="inline-flex items-center justify-center gap-2 rounded-lg bg-blue-600 px-5 py-2.5 text-sm font-semibold text-white shadow-sm transition hover:bg-blue-700 active:bg-blue-800"
                >
                    <span className="text-lg">
                        +
                    </span>

                    Recall From PO
                </button>
            </div>

            {/* HEADER CARD */}
            <div className="mb-6 rounded-xl border border-slate-200 bg-white p-5 shadow-sm">

                <div className="grid grid-cols-1 gap-5 md:grid-cols-3">

                    {/* SO DATE */}
                    <div>
                        <label className="mb-1.5 block text-sm font-medium text-slate-700">
                            SO Date
                        </label>

                        <input
                            type="date"
                            value={soDate}
                            onChange={(e) =>
                                setSoDate(
                                    e.target.value
                                )
                            }
                            className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm outline-none transition focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                        />
                    </div>

                    {/* CUSTOMER */}
                    <div>
                        <label className="mb-1.5 block text-sm font-medium text-slate-700">
                            Customer
                        </label>

                        <select
                            value={customerCode}
                            onChange={(e) => {
                                const code =
                                    e.target.value;

                                const customer =
                                    customers.find(
                                        (x) =>
                                            x.CustomerCode ===
                                            code
                                    );

                                setCustomerCode(code);

                                setCustomerName(
                                    customer?.CustomerName ||
                                        ""
                                );
                            }}
                            className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm outline-none transition focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                        >
                            <option value="">
                                Select Customer
                            </option>

                            {customers.map(
                                (customer) => (
                                    <option
                                        key={
                                            customer.CustomerCode
                                        }
                                        value={
                                            customer.CustomerCode
                                        }
                                    >
                                        {
                                            customer.CustomerCode
                                        }{" "}
                                        -{" "}
                                        {
                                            customer.CustomerName
                                        }
                                    </option>
                                )
                            )}
                        </select>
                    </div>

                    {/* REMARK */}
                    <div>
                        <label className="mb-1.5 block text-sm font-medium text-slate-700">
                            Remark
                        </label>

                        <input
                            type="text"
                            value={remark}
                            onChange={(e) =>
                                setRemark(
                                    e.target.value
                                )
                            }
                            placeholder="Optional remark"
                            className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm outline-none transition focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                        />
                    </div>

                </div>
            </div>

            {/* ITEMS CARD */}
            <div className="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">

                {/* TABLE HEADER */}
                <div className="flex items-center justify-between border-b border-slate-200 px-5 py-4">

                    <div>
                        <h2 className="font-semibold text-slate-800">
                            Order Items
                        </h2>

                        <p className="text-xs text-slate-500">
                            {items.length} item
                            {items.length !== 1
                                ? "s"
                                : ""}
                        </p>
                    </div>

                    <button
                        type="button"
                        onClick={openPOModal}
                        className="rounded-lg border border-blue-200 bg-blue-50 px-4 py-2 text-sm font-medium text-blue-700 hover:bg-blue-100"
                    >
                        + Recall From PO
                    </button>
                </div>

                {/* TABLE */}
                <div className="overflow-x-auto">

                    <table className="min-w-[1100px] w-full text-sm">

                        <thead className="bg-slate-50 text-xs uppercase text-slate-500">

                            <tr>

                                <th className="px-4 py-3 text-left">
                                    #
                                </th>

                                <th className="px-4 py-3 text-left">
                                    PO No
                                </th>

                                <th className="px-4 py-3 text-left">
                                    Product Code
                                </th>

                                <th className="px-4 py-3 text-left">
                                    Product
                                </th>

                                <th className="px-4 py-3 text-right">
                                    Qty
                                </th>

                                <th className="px-4 py-3 text-right">
                                    Price
                                </th>

                                <th className="px-4 py-3 text-right">
                                    Disc %
                                </th>

                                <th className="px-4 py-3 text-right">
                                    Disc
                                </th>

                                <th className="px-4 py-3 text-right">
                                    Total
                                </th>

                                <th className="px-4 py-3 text-center">
                                    Action
                                </th>

                            </tr>

                        </thead>

                        <tbody className="divide-y divide-slate-100">

                            {items.length === 0 ? (

                                <tr>

                                    <td
                                        colSpan="10"
                                        className="px-4 py-16 text-center"
                                    >
                                        <div className="text-slate-400">

                                            <div className="mb-2 text-4xl">
                                                🛒
                                            </div>

                                            <p className="font-medium">
                                                No products added
                                            </p>

                                            <p className="mt-1 text-sm">
                                                Click "Recall From PO"
                                                to add products
                                            </p>

                                        </div>
                                    </td>

                                </tr>

                            ) : (

                                items.map(
                                    (item, index) => {

                                        const gross =
                                            Number(
                                                item.qty
                                            ) *
                                            Number(
                                                item.sellingPrice
                                            );

                                        const discountAmount =
                                            (gross *
                                                Number(
                                                    item.discountPercentage ||
                                                        0
                                                )) /
                                            100;

                                        const total =
                                            gross -
                                            discountAmount;

                                        return (
                                            <tr
                                                key={`${item.poID}-${item.productCode}-${index}`}
                                                className="hover:bg-slate-50"
                                            >

                                                <td className="px-4 py-3 text-slate-500">
                                                    {index + 1}
                                                </td>

                                                <td className="px-4 py-3">

                                                    <span className="rounded-md bg-blue-50 px-2 py-1 text-xs font-medium text-blue-700">
                                                        {
                                                            item.pono
                                                        }
                                                    </span>

                                                </td>

                                                <td className="px-4 py-3 font-medium text-slate-700">
                                                    {
                                                        item.productCode
                                                    }
                                                </td>

                                                <td className="max-w-[250px] px-4 py-3 text-slate-700">
                                                    {
                                                        item.productName
                                                    }
                                                </td>

                                                <td className="px-4 py-3">

                                                    <input
                                                        type="number"
                                                        min="0"
                                                        step="0.001"
                                                        value={
                                                            item.qty
                                                        }
                                                        onChange={(
                                                            e
                                                        ) =>
                                                            updateItem(
                                                                index,
                                                                "qty",
                                                                e.target
                                                                    .value
                                                            )
                                                        }
                                                        className="w-24 rounded-md border border-slate-300 px-2 py-1.5 text-right outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                                                    />

                                                </td>

                                                <td className="px-4 py-3">

                                                    <input
                                                        type="number"
                                                        min="0"
                                                        step="0.01"
                                                        value={
                                                            item.sellingPrice
                                                        }
                                                        onChange={(
                                                            e
                                                        ) =>
                                                            updateItem(
                                                                index,
                                                                "sellingPrice",
                                                                e.target
                                                                    .value
                                                            )
                                                        }
                                                        className="w-28 rounded-md border border-slate-300 px-2 py-1.5 text-right outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                                                    />

                                                </td>

                                                <td className="px-4 py-3">

                                                    <input
                                                        type="number"
                                                        min="0"
                                                        max="100"
                                                        step="0.01"
                                                        value={
                                                            item.discountPercentage
                                                        }
                                                        onChange={(
                                                            e
                                                        ) =>
                                                            updateItem(
                                                                index,
                                                                "discountPercentage",
                                                                e.target
                                                                    .value
                                                            )
                                                        }
                                                        className="w-20 rounded-md border border-slate-300 px-2 py-1.5 text-right outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                                                    />

                                                </td>

                                                <td className="px-4 py-3 text-right text-slate-600">
                                                    {discountAmount.toFixed(
                                                        2
                                                    )}
                                                </td>

                                                <td className="px-4 py-3 text-right font-semibold text-slate-800">
                                                    {total.toFixed(
                                                        2
                                                    )}
                                                </td>

                                                <td className="px-4 py-3 text-center">

                                                    <button
                                                        type="button"
                                                        onClick={() =>
                                                            removeItem(
                                                                index
                                                            )
                                                        }
                                                        className="rounded-md p-2 text-red-500 hover:bg-red-50 hover:text-red-700"
                                                        title="Remove"
                                                    >
                                                        🗑
                                                    </button>

                                                </td>

                                            </tr>
                                        );
                                    }
                                )

                            )}

                        </tbody>

                    </table>
                </div>
            </div>

            {/* BOTTOM */}
            <div className="mt-6 flex flex-col-reverse gap-5 lg:flex-row lg:items-end lg:justify-between">

                <div className="text-sm text-slate-500">
                    <p>
                        Customer:
                        <span className="ml-1 font-medium text-slate-700">
                            {customerName ||
                                "Not selected"}
                        </span>
                    </p>

                    <p className="mt-1">
                        Products:
                        <span className="ml-1 font-medium text-slate-700">
                            {items.length}
                        </span>
                    </p>
                </div>

                <div className="w-full max-w-md rounded-xl border border-slate-200 bg-white p-5 shadow-sm">

                    <div className="flex items-center justify-between py-2 text-sm">
                        <span className="text-slate-500">
                            Sub Total
                        </span>

                        <span className="font-medium text-slate-800">
                            {subTotal.toFixed(2)}
                        </span>
                    </div>

                    <div className="flex items-center justify-between py-2 text-sm">

                        <span className="text-slate-500">
                            Order Discount
                        </span>

                        <input
                            type="number"
                            min="0"
                            value={discount}
                            onChange={(e) =>
                                setDiscount(
                                    e.target.value
                                )
                            }
                            className="w-28 rounded-md border border-slate-300 px-2 py-1.5 text-right outline-none focus:border-blue-500"
                        />

                    </div>

                    <div className="my-3 border-t border-slate-200" />

                    <div className="flex items-center justify-between">

                        <span className="text-lg font-semibold text-slate-800">
                            Grand Total
                        </span>

                        <span className="text-2xl font-bold text-blue-600">
                            {grandTotal.toFixed(2)}
                        </span>

                    </div>

                    <button
                        type="button"
                        disabled={saving}
                        onClick={saveSalesOrder}
                        className="mt-5 w-full rounded-lg bg-green-600 px-5 py-3 text-sm font-bold text-white shadow-sm transition hover:bg-green-700 disabled:cursor-not-allowed disabled:bg-slate-400"
                    >
                        {saving
                            ? "Saving..."
                            : "Save Sales Order"}
                    </button>

                </div>

            </div>

            {/* =====================================================
                PO MODAL
            ====================================================== */}

            {showPOModal && (

                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-3 md:p-6">

                    <div className="flex max-h-[92vh] w-full max-w-[1500px] flex-col overflow-hidden rounded-xl bg-white shadow-2xl">

                        {/* MODAL HEADER */}

                        <div className="flex items-center justify-between border-b border-slate-200 px-5 py-4">

                            <div>

                                <h2 className="text-lg font-bold text-slate-800">
                                    Recall Products From PO
                                </h2>

                                <p className="text-xs text-slate-500">
                                    Select products from an open purchase order
                                </p>

                            </div>

                            <button
                                type="button"
                                onClick={closePOModal}
                                className="rounded-lg p-2 text-2xl leading-none text-slate-400 hover:bg-slate-100 hover:text-slate-700"
                            >
                                ×
                            </button>

                        </div>

                        {/* SEARCH */}

                        <div className="border-b border-slate-200 bg-slate-50 p-4">

                            <div className="flex flex-col gap-3 md:flex-row">

                                <div className="relative flex-1">

                                    <span className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-slate-400">
                                        🔍
                                    </span>

                                    <input
                                        autoFocus
                                        type="text"
                                        value={poSearch}
                                        onChange={(e) => {

                                            const value =
                                                e.target.value;

                                            setPOSearch(value);

                                            searchPO(value);
                                        }}
                                        placeholder="Search PO No, product code, product name or supplier..."
                                        className="w-full rounded-lg border border-slate-300 bg-white py-2.5 pl-10 pr-3 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                                    />

                                </div>

                                <button
                                    type="button"
                                    onClick={selectAllPO}
                                    className="rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-medium text-slate-700 hover:bg-slate-100"
                                >
                                    Select All
                                </button>

                                <button
                                    type="button"
                                    onClick={clearAllPO}
                                    className="rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-medium text-slate-700 hover:bg-slate-100"
                                >
                                    Clear
                                </button>

                            </div>

                        </div>

                        {/* PO TABLE */}

                        <div className="flex-1 overflow-auto">

                            {loadingPO ? (

                                <div className="flex h-48 items-center justify-center">

                                    <div className="text-center">

                                        <div className="mx-auto mb-3 h-8 w-8 animate-spin rounded-full border-4 border-slate-200 border-t-blue-600" />

                                        <p className="text-sm text-slate-500">
                                            Loading purchase orders...
                                        </p>

                                    </div>

                                </div>

                            ) : poItems.length === 0 ? (

                                <div className="flex h-48 items-center justify-center">

                                    <div className="text-center text-slate-400">

                                        <div className="mb-2 text-3xl">
                                            📦
                                        </div>

                                        <p className="font-medium">
                                            No available PO products
                                        </p>

                                    </div>

                                </div>

                            ) : (

                                <table className="min-w-[1200px] w-full text-sm">

                                    <thead className="sticky top-0 z-10 bg-slate-100 text-xs uppercase text-slate-500">

                                        <tr>

                                            <th className="w-12 px-3 py-3 text-center">
                                                Select
                                            </th>

                                            <th className="px-3 py-3 text-left">
                                                PO No
                                            </th>

                                            <th className="px-3 py-3 text-left">
                                                Supplier
                                            </th>

                                            <th className="px-3 py-3 text-left">
                                                Product Code
                                            </th>

                                            <th className="px-3 py-3 text-left">
                                                Product
                                            </th>

                                            <th className="px-3 py-3 text-right">
                                                PO Qty
                                            </th>

                                            <th className="px-3 py-3 text-right">
                                                Received
                                            </th>

                                            <th className="px-3 py-3 text-right">
                                                Available
                                            </th>

                                            <th className="px-3 py-3 text-right">
                                                Sale Qty
                                            </th>

                                            <th className="px-3 py-3 text-right">
                                                Price
                                            </th>

                                        </tr>

                                    </thead>

                                    <tbody className="divide-y divide-slate-100">

                                        {poItems.map(
                                            (item, index) => (

                                                <tr
                                                    key={`${item.poID}-${item.productcode}`}
                                                    className={
                                                        item.selected
                                                            ? "bg-blue-50"
                                                            : "hover:bg-slate-50"
                                                    }
                                                >

                                                    <td className="px-3 py-3 text-center">

                                                        <input
                                                            type="checkbox"
                                                            checked={
                                                                item.selected
                                                            }
                                                            onChange={() =>
                                                                togglePOItem(
                                                                    index
                                                                )
                                                            }
                                                            className="h-4 w-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500"
                                                        />

                                                    </td>

                                                    <td className="px-3 py-3">

                                                        <span className="rounded-md bg-blue-100 px-2 py-1 text-xs font-semibold text-blue-700">
                                                            {
                                                                item.pono
                                                            }
                                                        </span>

                                                    </td>

                                                    <td className="px-3 py-3">

                                                        <div className="font-medium text-slate-700">
                                                            {
                                                                item.suppliername
                                                            }
                                                        </div>

                                                        <div className="text-xs text-slate-400">
                                                            {
                                                                item.suppliercode
                                                            }
                                                        </div>

                                                    </td>

                                                    <td className="px-3 py-3 font-medium text-slate-700">
                                                        {
                                                            item.productcode
                                                        }
                                                    </td>

                                                    <td className="px-3 py-3 text-slate-700">
                                                        {
                                                            item.productname
                                                        }
                                                    </td>

                                                    <td className="px-3 py-3 text-right">
                                                        {
                                                            item.qty
                                                        }
                                                    </td>

                                                    <td className="px-3 py-3 text-right text-slate-500">
                                                        {
                                                            item.ReceivedQty
                                                        }
                                                    </td>

                                                    <td className="px-3 py-3 text-right">

                                                        <span className="rounded-full bg-green-100 px-2.5 py-1 text-xs font-semibold text-green-700">
                                                            {
                                                                item.AvailableQty
                                                            }
                                                        </span>

                                                    </td>

                                                    <td className="px-3 py-3 text-right">

                                                        <input
                                                            type="number"
                                                            min="0"
                                                            max={
                                                                item.AvailableQty
                                                            }
                                                            step="0.001"
                                                            value={
                                                                item.saleQty
                                                            }
                                                            onChange={(
                                                                e
                                                            ) =>
                                                                updatePOQty(
                                                                    index,
                                                                    e.target
                                                                        .value
                                                                )
                                                            }
                                                            className="w-24 rounded-md border border-slate-300 px-2 py-1.5 text-right outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                                                        />

                                                    </td>

                                                    <td className="px-3 py-3 text-right font-medium">

                                                        {Number(
                                                            item.sellingprice
                                                        ).toFixed(
                                                            2
                                                        )}

                                                    </td>

                                                </tr>

                                            )
                                        )}

                                    </tbody>

                                </table>

                            )}

                        </div>

                        {/* MODAL FOOTER */}

                        <div className="flex flex-col-reverse gap-3 border-t border-slate-200 bg-slate-50 px-5 py-4 sm:flex-row sm:items-center sm:justify-between">

                          <div className="text-sm text-slate-500">
    Selected:{" "}
    <span className="font-semibold text-slate-800">
        {poItems.filter((x) => x.selected).length}
    </span>{" "}
    products
</div>

                            <div className="flex gap-3">

                                <button
                                    type="button"
                                    onClick={closePOModal}
                                    className="rounded-lg border border-slate-300 bg-white px-5 py-2.5 text-sm font-medium text-slate-700 hover:bg-slate-100"
                                >
                                    Cancel
                                </button>

                                <button
                                    type="button"
                                    onClick={
                                        addPOItems
                                    }
                                    className="rounded-lg bg-blue-600 px-5 py-2.5 text-sm font-semibold text-white hover:bg-blue-700"
                                >
                                    Add Selected Products
                                </button>

                            </div>

                        </div>

                    </div>

                </div>
            )}
        </div>
    );
}