import React, { useCallback, useEffect, useMemo, useState } from "react";
import {
  Search,
  Download,
  CalendarDays,
  ChevronDown,
  RefreshCw,
  Filter,
  X,
  ArrowUp,
  ArrowDown,
  Activity,
} from "lucide-react";
import * as XLSX from "xlsx";

const API_URL = "http://localhost:5000/api";

const AccountTransactionLogs = () => {
  const [transactions, setTransactions] = useState([]);
  const [accounts, setAccounts] = useState([]);
  const [types, setTypes] = useState([]);
  const [users, setUsers] = useState([]);

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const [search, setSearch] = useState("");
  const [accountId, setAccountId] = useState("");
  const [type, setType] = useState("");
  const [userName, setUserName] = useState("");
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");

  const loadAccounts = useCallback(async () => {
    try {
      const response = await fetch(
        `${API_URL}/account-transaction-logs/accounts`
      );

      if (!response.ok) {
        throw new Error("Failed to load accounts");
      }

      const result = await response.json();
      setAccounts(result.data || []);
    } catch (err) {
      console.error("Accounts error:", err);
    }
  }, []);

  const loadTypes = useCallback(async () => {
    try {
      const response = await fetch(
        `${API_URL}/account-transaction-logs/types`
      );

      if (!response.ok) {
        throw new Error("Failed to load transaction types");
      }

      const result = await response.json();
      const typeData = result.data || [];

      setTypes(
        typeData
          .map((item) =>
            typeof item === "string" ? item : item.TransactionType
          )
          .filter(Boolean)
      );
    } catch (err) {
      console.error("Transaction types error:", err);
    }
  }, []);

  const loadUsers = useCallback(async () => {
    try {
      const response = await fetch(
        `${API_URL}/account-transaction-logs/users`
      );

      if (!response.ok) {
        throw new Error("Failed to load users");
      }

      const result = await response.json();
      const userData = result.data || [];

      setUsers(
        userData
          .map((item) => (typeof item === "string" ? item : item.CreatedBy))
          .filter(Boolean)
      );
    } catch (err) {
      console.error("Users error:", err);
    }
  }, []);

  const loadTransactions = useCallback(async () => {
    try {
      setLoading(true);
      setError("");

      const params = new URLSearchParams();

      if (search.trim()) params.append("search", search.trim());
      if (accountId) params.append("accountId", accountId);
      if (type) params.append("type", type);
      if (userName) params.append("userName", userName);
      if (fromDate) params.append("fromDate", fromDate);
      if (toDate) params.append("toDate", toDate);

      const url =
        `${API_URL}/account-transaction-logs?${params.toString()}`;

      const response = await fetch(url);

      if (!response.ok) {
        throw new Error("Failed to load account transactions");
      }

      const result = await response.json();

      if (!result.success) {
        throw new Error(
          result.message || "Failed to load transactions"
        );
      }

      setTransactions(result.data || []);
    } catch (err) {
      console.error("Transaction error:", err);
      setTransactions([]);
      setError(err.message || "Unable to load transactions");
    } finally {
      setLoading(false);
    }
  }, [search, accountId, type, userName, fromDate, toDate]);

  useEffect(() => {
    loadAccounts();
    loadTypes();
    loadUsers();
  }, [loadAccounts, loadTypes, loadUsers]);

  useEffect(() => {
    const timer = setTimeout(() => {
      loadTransactions();
    }, 300);

    return () => clearTimeout(timer);
  }, [loadTransactions]);

  const clearFilters = () => {
    setSearch("");
    setAccountId("");
    setType("");
    setUserName("");
    setFromDate("");
    setToDate("");
  };

  const formatDateTime = (value) => {
    if (!value) return "-";

    const date = new Date(value);

    if (Number.isNaN(date.getTime())) return "-";

    const day = String(date.getDate()).padStart(2, "0");
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const year = date.getFullYear();

    const hours = String(date.getHours()).padStart(2, "0");
    const minutes = String(date.getMinutes()).padStart(2, "0");
    const seconds = String(date.getSeconds()).padStart(2, "0");

    return `${day}/${month}/${year}, ${hours}:${minutes}:${seconds}`;
  };

  const formatAmount = (value) => {
    return Number(value || 0).toLocaleString("en-US", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
  };

  const totalCredit = useMemo(() => {
    return transactions.reduce(
      (total, item) => total + Number(item.Credit || 0),
      0
    );
  }, [transactions]);

  const totalDebit = useMemo(() => {
    return transactions.reduce(
      (total, item) => total + Number(item.Debit || 0),
      0
    );
  }, [transactions]);

  const netAmount = useMemo(() => {
    return totalCredit - totalDebit;
  }, [totalCredit, totalDebit]);

  const activeFilterCount = useMemo(() => {
    return [
      search.trim(),
      accountId,
      type,
      userName,
      fromDate,
      toDate,
    ].filter(Boolean).length;
  }, [search, accountId, type, userName, fromDate, toDate]);

  const exportToExcel = () => {
    if (!transactions.length) {
      alert("There are no transactions to export.");
      return;
    }

    const excelData = transactions.map((item) => ({
      "Date & Time": formatDateTime(item.TransactionDate),
      Account: item.AccountName || "",
      "Account Type": item.AccountType || "",
      "Detail Type": item.DetailType || "",
      "Transaction Type": item.TransactionType || "",
      "Reference No": item.ReferenceNo || "",
      Description: item.Description || "",
      Debit: Number(item.Debit || 0),
      Credit: Number(item.Credit || 0),
      "Created By": item.CreatedBy || "",
      "Created Date": formatDateTime(item.CreatedDate),
    }));

    const worksheet = XLSX.utils.json_to_sheet(excelData);
    const workbook = XLSX.utils.book_new();

    XLSX.utils.book_append_sheet(
      workbook,
      worksheet,
      "Account Transactions"
    );

    XLSX.writeFile(
      workbook,
      "Account_Transaction_Logs.xlsx"
    );
  };

  const refreshTransactions = () => {
    loadTransactions();
  };

  return (
    <div className="min-h-screen bg-slate-100 p-3 sm:p-4 lg:p-6">
      <div className="mx-auto max-w-[1800px]">

        {/* Header */}
        <div className="mb-5 overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-slate-200">
          <div className="bg-gradient-to-r from-slate-900 via-slate-800 to-blue-900 px-5 py-6 sm:px-6">
            <div className="flex flex-col gap-5 lg:flex-row lg:items-center lg:justify-between">
              <div className="flex items-start gap-4">
                <div className="hidden rounded-xl bg-white/10 p-3 ring-1 ring-white/20 sm:block">
                  <Activity className="h-7 w-7 text-white" />
                </div>

                <div>
                  <h1 className="text-2xl font-bold tracking-tight text-white sm:text-3xl">
                    Account Transaction Logs
                  </h1>
                  <p className="mt-1 text-sm text-slate-300">
                    View all account transactions with user tracking
                  </p>
                </div>
              </div>

              <div className="flex flex-wrap gap-2">
                <button
                  type="button"
                  onClick={refreshTransactions}
                  disabled={loading}
                  title="Refresh transactions"
                  className="inline-flex items-center justify-center gap-2 rounded-xl border border-white/20 bg-white/10 px-4 py-2.5 text-sm font-semibold text-white backdrop-blur transition hover:bg-white/20 disabled:cursor-not-allowed disabled:opacity-50"
                >
                  <RefreshCw
                    size={17}
                    className={loading ? "animate-spin" : ""}
                  />
                  Refresh
                </button>

                <button
                  type="button"
                  onClick={exportToExcel}
                  className="inline-flex items-center justify-center gap-2 rounded-xl bg-white px-4 py-2.5 text-sm font-semibold text-slate-800 shadow-sm transition hover:bg-slate-100"
                >
                  <Download size={17} />
                  Export to Excel
                </button>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 divide-y divide-slate-200 sm:grid-cols-3 sm:divide-x sm:divide-y-0">
            <div className="flex items-center gap-3 px-5 py-4">
              <div className="rounded-lg bg-slate-100 p-2">
                <Activity className="h-5 w-5 text-slate-600" />
              </div>
              <div>
                <p className="text-xs font-medium uppercase tracking-wide text-slate-500">
                  Transactions
                </p>
                <p className="text-lg font-bold text-slate-800">
                  {transactions.length.toLocaleString()}
                </p>
              </div>
            </div>

            <div className="flex items-center gap-3 px-5 py-4">
              <div className="rounded-lg bg-emerald-50 p-2">
                <ArrowUp className="h-5 w-5 text-emerald-600" />
              </div>
              <div>
                <p className="text-xs font-medium uppercase tracking-wide text-slate-500">
                  Total Credit
                </p>
                <p className="text-lg font-bold text-emerald-600">
                  +{formatAmount(totalCredit)}
                </p>
              </div>
            </div>

            <div className="flex items-center gap-3 px-5 py-4">
              <div className="rounded-lg bg-red-50 p-2">
                <ArrowDown className="h-5 w-5 text-red-600" />
              </div>
              <div>
                <p className="text-xs font-medium uppercase tracking-wide text-slate-500">
                  Total Debit
                </p>
                <p className="text-lg font-bold text-red-600">
                  -{formatAmount(totalDebit)}
                </p>
              </div>
            </div>
          </div>
        </div>

        {/* Filters */}
        <div className="mb-5 rounded-2xl bg-white p-4 shadow-sm ring-1 ring-slate-200 sm:p-5">
          <div className="mb-4 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
            <div className="flex items-center gap-2">
              <div className="rounded-lg bg-blue-50 p-2">
                <Filter className="h-5 w-5 text-blue-600" />
              </div>

              <div>
                <h2 className="text-lg font-bold text-slate-800">
                  Filters
                </h2>
                <p className="text-xs text-slate-500">
                  Filter account transaction records
                </p>
              </div>
            </div>

            {activeFilterCount > 0 && (
              <div className="inline-flex w-fit items-center gap-2 rounded-full bg-blue-50 px-3 py-1.5 text-xs font-semibold text-blue-700">
                <span>
                  {activeFilterCount} active filter
                  {activeFilterCount === 1 ? "" : "s"}
                </span>

                <button
                  type="button"
                  onClick={clearFilters}
                  className="rounded-full p-0.5 hover:bg-blue-100"
                  title="Clear filters"
                >
                  <X size={14} />
                </button>
              </div>
            )}
          </div>

          <div className="grid grid-cols-1 gap-3 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-7">

            {/* Search */}
            <div className="relative 2xl:col-span-2">
              <label className="mb-1.5 block text-xs font-semibold text-slate-600">
                Search
              </label>

              <Search
                size={17}
                className="absolute left-3 top-[35px] -translate-y-1/2 text-slate-400"
              />

              <input
                type="text"
                value={search}
                placeholder="Description, reference..."
                onChange={(e) => setSearch(e.target.value)}
                className="w-full rounded-xl border border-slate-300 bg-white py-2.5 pl-10 pr-3 text-sm text-slate-700 outline-none transition placeholder:text-slate-400 hover:border-slate-400 focus:border-blue-500 focus:ring-4 focus:ring-blue-50"
              />
            </div>

            {/* Account */}
            <div>
              <label className="mb-1.5 block text-xs font-semibold text-slate-600">
                Account
              </label>

              <div className="relative">
                <select
                  value={accountId}
                  onChange={(e) => setAccountId(e.target.value)}
                  className="w-full appearance-none rounded-xl border border-slate-300 bg-white px-3 py-2.5 pr-10 text-sm text-slate-700 outline-none transition hover:border-slate-400 focus:border-blue-500 focus:ring-4 focus:ring-blue-50"
                >
                  <option value="">All Accounts</option>

                  {accounts.map((account) => (
                    <option
                      key={account.AccountID}
                      value={account.AccountID}
                    >
                      {account.AccountName}
                    </option>
                  ))}
                </select>

                <ChevronDown
                  size={17}
                  className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-slate-400"
                />
              </div>
            </div>

            {/* Type */}
            <div>
              <label className="mb-1.5 block text-xs font-semibold text-slate-600">
                Transaction Type
              </label>

              <div className="relative">
                <select
                  value={type}
                  onChange={(e) => setType(e.target.value)}
                  className="w-full appearance-none rounded-xl border border-slate-300 bg-white px-3 py-2.5 pr-10 text-sm text-slate-700 outline-none transition hover:border-slate-400 focus:border-blue-500 focus:ring-4 focus:ring-blue-50"
                >
                  <option value="">All Types</option>

                  {types.map((item) => (
                    <option key={item} value={item}>
                      {item}
                    </option>
                  ))}
                </select>

                <ChevronDown
                  size={17}
                  className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-slate-400"
                />
              </div>
            </div>

            {/* User */}
            <div>
              <label className="mb-1.5 block text-xs font-semibold text-slate-600">
                Created By
              </label>

              <div className="relative">
                <select
                  value={userName}
                  onChange={(e) => setUserName(e.target.value)}
                  className="w-full appearance-none rounded-xl border border-slate-300 bg-white px-3 py-2.5 pr-10 text-sm text-slate-700 outline-none transition hover:border-slate-400 focus:border-blue-500 focus:ring-4 focus:ring-blue-50"
                >
                  <option value="">All Users</option>

                  {users.map((user) => (
                    <option key={user} value={user}>
                      {user}
                    </option>
                  ))}
                </select>

                <ChevronDown
                  size={17}
                  className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-slate-400"
                />
              </div>
            </div>

            {/* From Date */}
            <div>
              <label className="mb-1.5 block text-xs font-semibold text-slate-600">
                From Date
              </label>

              <div className="relative">
                <input
                  type="date"
                  value={fromDate}
                  onChange={(e) => setFromDate(e.target.value)}
                  className="w-full rounded-xl border border-slate-300 bg-white px-3 py-2.5 text-sm text-slate-700 outline-none transition hover:border-slate-400 focus:border-blue-500 focus:ring-4 focus:ring-blue-50"
                />

                <CalendarDays
                  size={16}
                  className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-slate-400"
                />
              </div>
            </div>

            {/* To Date */}
            <div>
              <label className="mb-1.5 block text-xs font-semibold text-slate-600">
                To Date
              </label>

              <div className="relative">
                <input
                  type="date"
                  value={toDate}
                  min={fromDate || undefined}
                  onChange={(e) => setToDate(e.target.value)}
                  className="w-full rounded-xl border border-slate-300 bg-white px-3 py-2.5 text-sm text-slate-700 outline-none transition hover:border-slate-400 focus:border-blue-500 focus:ring-4 focus:ring-blue-50"
                />

                <CalendarDays
                  size={16}
                  className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-slate-400"
                />
              </div>
            </div>

            {/* Clear */}
            <div className="flex items-end">
              <button
                type="button"
                onClick={clearFilters}
                className="inline-flex w-full items-center justify-center gap-2 rounded-xl border border-slate-300 bg-slate-50 px-4 py-2.5 text-sm font-semibold text-slate-700 transition hover:bg-slate-100 hover:text-slate-900"
              >
                <X size={16} />
                Clear Filters
              </button>
            </div>
          </div>
        </div>

        {/* Error */}
        {error && (
          <div className="mb-5 flex items-start gap-3 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
            <div className="mt-0.5 rounded-full bg-red-100 p-1">
              <X size={14} />
            </div>
            <div>
              <p className="font-semibold">Unable to load transactions</p>
              <p className="mt-0.5">{error}</p>
            </div>
          </div>
        )}

        {/* Transaction Card */}
        <div className="overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-slate-200">

          {/* Table Header */}
          <div className="border-b border-slate-200 px-4 py-4 sm:px-5">
            <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">

              <div>
                <div className="flex items-center gap-2">
                  <h2 className="text-lg font-bold text-slate-800">
                    Transactions
                  </h2>

                  <span className="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-bold text-slate-600">
                    {transactions.length}
                  </span>
                </div>

                <p className="mt-1 text-xs text-slate-500">
                  Account ledger transaction history
                </p>
              </div>

              <div className="flex flex-wrap gap-2">
                <div className="rounded-xl border border-emerald-100 bg-emerald-50 px-3 py-2 text-sm">
                  <span className="text-emerald-700">
                    Credit:
                  </span>
                  <strong className="ml-1 text-emerald-700">
                    +{formatAmount(totalCredit)}
                  </strong>
                </div>

                <div className="rounded-xl border border-red-100 bg-red-50 px-3 py-2 text-sm">
                  <span className="text-red-700">
                    Debit:
                  </span>
                  <strong className="ml-1 text-red-700">
                    -{formatAmount(totalDebit)}
                  </strong>
                </div>

                <div
                  className={`rounded-xl border px-3 py-2 text-sm ${
                    netAmount >= 0
                      ? "border-blue-100 bg-blue-50"
                      : "border-amber-100 bg-amber-50"
                  }`}
                >
                  <span
                    className={
                      netAmount >= 0
                        ? "text-blue-700"
                        : "text-amber-700"
                    }
                  >
                    Net:
                  </span>
                  <strong
                    className={`ml-1 ${
                      netAmount >= 0
                        ? "text-blue-700"
                        : "text-amber-700"
                    }`}
                  >
                    {netAmount >= 0 ? "+" : "-"}
                    {formatAmount(Math.abs(netAmount))}
                  </strong>
                </div>
              </div>
            </div>
          </div>

          {/* Table */}
          <div className="overflow-x-auto">
            <table className="min-w-[1100px] w-full text-left text-sm">
              <thead className="border-b border-slate-200 bg-slate-50">
                <tr>
                  <th className="whitespace-nowrap px-5 py-3.5 text-xs font-bold uppercase tracking-wide text-slate-500">
                    Date &amp; Time
                  </th>

                  <th className="px-5 py-3.5 text-xs font-bold uppercase tracking-wide text-slate-500">
                    Account
                  </th>

                  <th className="whitespace-nowrap px-5 py-3.5 text-xs font-bold uppercase tracking-wide text-slate-500">
                    Type
                  </th>

                  <th className="whitespace-nowrap px-5 py-3.5 text-right text-xs font-bold uppercase tracking-wide text-slate-500">
                    Amount
                  </th>

                  <th className="px-5 py-3.5 text-xs font-bold uppercase tracking-wide text-slate-500">
                    Description
                  </th>

                  <th className="px-5 py-3.5 text-xs font-bold uppercase tracking-wide text-slate-500">
                    Reference
                  </th>

                  <th className="px-5 py-3.5 text-xs font-bold uppercase tracking-wide text-slate-500">
                    User
                  </th>
                </tr>
              </thead>

              <tbody className="divide-y divide-slate-100">

                {/* Loading */}
                {loading && (
                  <tr>
                    <td
                      colSpan="7"
                      className="px-5 py-16 text-center"
                    >
                      <div className="flex flex-col items-center justify-center">
                        <div className="mb-3 rounded-full bg-blue-50 p-3">
                          <RefreshCw
                            size={24}
                            className="animate-spin text-blue-600"
                          />
                        </div>

                        <p className="font-semibold text-slate-700">
                          Loading transactions...
                        </p>

                        <p className="mt-1 text-xs text-slate-400">
                          Please wait
                        </p>
                      </div>
                    </td>
                  </tr>
                )}

                {/* Empty */}
                {!loading && transactions.length === 0 && (
                  <tr>
                    <td
                      colSpan="7"
                      className="px-5 py-16 text-center"
                    >
                      <div className="mx-auto flex max-w-sm flex-col items-center">
                        <div className="mb-3 rounded-full bg-slate-100 p-4">
                          <Search
                            size={28}
                            className="text-slate-400"
                          />
                        </div>

                        <p className="font-semibold text-slate-700">
                          No transactions found
                        </p>

                        <small className="mt-1 text-slate-400">
                          Try changing your filters.
                        </small>

                        {activeFilterCount > 0 && (
                          <button
                            type="button"
                            onClick={clearFilters}
                            className="mt-4 rounded-lg bg-blue-600 px-4 py-2 text-xs font-semibold text-white hover:bg-blue-700"
                          >
                            Clear Filters
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                )}

                {/* Data */}
                {!loading &&
                  transactions.map((item) => {
                    const credit = Number(item.Credit || 0);
                    const debit = Number(item.Debit || 0);

                    const isCredit = credit > 0;
                    const amount = isCredit ? credit : debit;

                    return (
                      <tr
                        key={item.LedgerID}
                        className="group transition hover:bg-slate-50"
                      >
                        {/* Date */}
                        <td className="whitespace-nowrap px-5 py-4 align-top">
                          <div className="font-medium text-slate-700">
                            {formatDateTime(
                              item.TransactionDate
                            )}
                          </div>

                          {item.CreatedDate && (
                            <div className="mt-1 text-[11px] text-slate-400">
                              Created:{" "}
                              {formatDateTime(item.CreatedDate)}
                            </div>
                          )}
                        </td>

                        {/* Account */}
                        <td className="px-5 py-4 align-top">
                          <div className="font-semibold text-slate-800">
                            {item.AccountName || "-"}
                          </div>

                          {item.AccountType && (
                            <div className="mt-1 inline-flex rounded-md bg-slate-100 px-2 py-0.5 text-xs text-slate-500">
                              {item.AccountType}
                            </div>
                          )}

                          {item.DetailType && (
                            <div className="mt-1 text-xs text-slate-400">
                              {item.DetailType}
                            </div>
                          )}
                        </td>

                        {/* Type */}
                        <td className="px-5 py-4 align-top">
                          <span
                            className={`inline-flex items-center rounded-full px-2.5 py-1 text-xs font-bold ${
                              isCredit
                                ? "bg-emerald-100 text-emerald-700 ring-1 ring-emerald-200"
                                : "bg-red-100 text-red-700 ring-1 ring-red-200"
                            }`}
                          >
                            <span
                              className={`mr-1.5 h-1.5 w-1.5 rounded-full ${
                                isCredit
                                  ? "bg-emerald-500"
                                  : "bg-red-500"
                              }`}
                            />

                            {item.TransactionType ||
                              (isCredit
                                ? "CREDIT"
                                : "DEBIT")}
                          </span>
                        </td>

                        {/* Amount */}
                        <td className="px-5 py-4 text-right align-top">
                          <div
                            className={`font-bold ${
                              isCredit
                                ? "text-emerald-600"
                                : "text-red-600"
                            }`}
                          >
                            {isCredit ? "+" : "-"}
                            {formatAmount(amount)}
                          </div>

                          <div className="mt-1 text-[10px] uppercase tracking-wide text-slate-400">
                            {isCredit ? "Credit" : "Debit"}
                          </div>
                        </td>

                        {/* Description */}
                        <td className="max-w-[350px] px-5 py-4 align-top">
                          <div
                            className="truncate text-slate-600"
                            title={item.Description || ""}
                          >
                            {item.Description || "-"}
                          </div>
                        </td>

                        {/* Reference */}
                        <td className="px-5 py-4 align-top">
                          {item.ReferenceNo ? (
                            <span className="inline-flex rounded-lg bg-slate-100 px-2.5 py-1 font-mono text-xs font-medium text-slate-600">
                              {item.ReferenceNo}
                            </span>
                          ) : (
                            <span className="text-slate-400">
                              -
                            </span>
                          )}
                        </td>

                        {/* User */}
                        <td className="px-5 py-4 align-top">
                          <div className="font-medium text-slate-600">
                            {item.CreatedBy || "-"}
                          </div>
                        </td>
                      </tr>
                    );
                  })}
              </tbody>
            </table>
          </div>

          {/* Footer */}
          {!loading && transactions.length > 0 && (
            <div className="border-t border-slate-200 bg-slate-50 px-5 py-3">
              <div className="flex flex-col gap-2 text-xs text-slate-500 sm:flex-row sm:items-center sm:justify-between">
                <span>
                  Showing {transactions.length.toLocaleString()} transaction
                  {transactions.length === 1 ? "" : "s"}
                </span>

                <span>
                  Net balance:
                  <strong
                    className={`ml-1 ${
                      netAmount >= 0
                        ? "text-blue-700"
                        : "text-amber-700"
                    }`}
                  >
                    {netAmount >= 0 ? "+" : "-"}
                    {formatAmount(Math.abs(netAmount))}
                  </strong>
                </span>
              </div>
            </div>
          )}
        </div>

        {/* Mobile helper */}
        <div className="mt-3 flex items-center justify-center gap-2 text-center text-xs text-slate-400 lg:hidden">
          <span className="h-1 w-1 rounded-full bg-slate-400" />
          Swipe horizontally to view all transaction columns
          <span className="h-1 w-1 rounded-full bg-slate-400" />
        </div>
      </div>
    </div>
  );
};

export default AccountTransactionLogs;
