import React, { useEffect, useMemo, useState } from "react";
import axios from "axios";

const API_URL = "http://localhost:5000/api/bincard";
const LOCATIONS_URL = "http://localhost:5000/api/locations";

const transactionClass = (type = "") => {
  const value = type.toUpperCase();

  if (value === "GRN") return "text-green-600 font-semibold";
  if (value === "TOG IN") return "text-blue-600 font-semibold";
  if (value === "TOG OUT") return "text-orange-600 font-semibold";
  if (value === "SALES") return "text-red-600 font-semibold";
  if (value === "SALES RETURN") return "text-emerald-600 font-semibold";
  if (value === "PURCHASE RETURN") return "text-purple-600 font-semibold";
  if (value === "STOCK ADJUSTMENT IN") return "text-cyan-600 font-semibold";
  if (value === "STOCK ADJUSTMENT OUT") return "text-rose-600 font-semibold";

  return "text-gray-700";
};

const formatNumber = (value, decimals = 3) => {
  const number = Number(value || 0);

  return number.toLocaleString("en-US", {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  });
};

const formatAmount = (value) => {
  const number = Number(value || 0);

  return number.toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
};

const formatDate = (value) => {
  if (!value) return "";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return value;
  }

  return date.toLocaleDateString("en-GB");
};

// Matches: { success: true, locations: [{ LocationID, LocationCode, LocationName }] }
const normalizeLocations = (payload) => {
  const raw =
    payload?.locations ??
    payload?.data?.locations ??
    payload?.data?.data ??
    payload?.data ??
    payload?.result ??
    payload?.rows ??
    payload ??
    [];

  const list = Array.isArray(raw) ? raw : [];

  return list
    .map((loc) => {
      const id =
        loc?.LocationID ??
        loc?.locationID ??
        loc?.LocationId ??
        loc?.locationId ??
        loc?.id ??
        "";

      const name =
        loc?.LocationName ??
        loc?.locationName ??
        loc?.Name ??
        loc?.name ??
        String(id);

      const code = loc?.LocationCode ?? loc?.locationCode ?? "";

      return {
        id: String(id),
        code: String(code),
        name: String(name),
        label: code ? `${code} — ${name}` : String(name),
      };
    })
    .filter((loc) => loc.id !== "" && loc.id !== "undefined");
};

const BinCard = () => {
  const [productCode, setProductCode] = useState("");
  const [productName, setProductName] = useState("");
  const [locationID, setLocationID] = useState("");

  const [locations, setLocations] = useState([]);
  const [locationsLoading, setLocationsLoading] = useState(false);
  const [locationsError, setLocationsError] = useState("");

  const [rows, setRows] = useState([]);

  const [openingBalance, setOpeningBalance] = useState(0);
  const [closingBalance, setClosingBalance] = useState(0);
  const [totalIn, setTotalIn] = useState(0);
  const [totalOut, setTotalOut] = useState(0);

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  // ---------- Locations ----------
  const loadLocations = async () => {
    try {
      setLocationsLoading(true);
      setLocationsError("");

      const response = await axios.get(LOCATIONS_URL);

      const list = normalizeLocations(response.data);

      setLocations(list);
    } catch (err) {
      console.error("Locations Error:", err);

      setLocationsError(
        err.response?.data?.message ||
          err.message ||
          "Unable to load locations."
      );

      setLocations([]);
    } finally {
      setLocationsLoading(false);
    }
  };

  // ---------- Bin Card ----------
  const loadBinCard = async () => {
    try {
      setLoading(true);
      setError("");

      const response = await axios.get(API_URL, {
        params: {
          productCode,
          productName,
          locationID,
        },
      });

      if (!response.data?.success) {
        throw new Error(
          response.data?.message || "Failed to load bin card."
        );
      }

      setRows(response.data.data || []);
      setOpeningBalance(Number(response.data.openingBalance || 0));
      setClosingBalance(Number(response.data.closingBalance || 0));
      setTotalIn(Number(response.data.totalIn || 0));
      setTotalOut(Number(response.data.totalOut || 0));
    } catch (err) {
      console.error("Bin Card Error:", err);

      setError(
        err.response?.data?.message ||
          err.message ||
          "Unable to load bin card."
      );

      setRows([]);
      setOpeningBalance(0);
      setClosingBalance(0);
      setTotalIn(0);
      setTotalOut(0);
    } finally {
      setLoading(false);
    }
  };

  const clearFilters = () => {
    setProductCode("");
    setProductName("");
    setLocationID("");
  };

  const handleSearch = (e) => {
    e.preventDefault();
    loadBinCard();
  };

  // Load locations once on mount
  useEffect(() => {
    loadLocations();
  }, []);

  // Load bin card once on mount
  useEffect(() => {
    loadBinCard();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const productInfo = useMemo(() => {
    if (!rows.length) {
      return {
        code: productCode || "",
        name: productName || "",
      };
    }

    return {
      code: rows[0]?.productCode || productCode || "",
      name: rows[0]?.productName || productName || "",
    };
  }, [rows, productCode, productName]);

  const locationLabel = useMemo(() => {
    if (!locationID) return "All Locations";

    const found = locations.find(
      (loc) => String(loc.id) === String(locationID)
    );

    return found ? found.label : locationID;
  }, [locations, locationID]);

  return (
    <div className="min-h-screen bg-gray-100 p-4 md:p-6">
      <div className="mx-auto max-w-[1600px]">
        {/* =====================================================
            HEADER
        ====================================================== */}
        <div className="mb-6 flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
          <div>
            <h1 className="text-2xl font-bold text-gray-800">
              Bin Card
            </h1>

            <p className="mt-1 text-sm text-gray-500">
              Complete stock movement history by product and location
            </p>
          </div>

          <button
            type="button"
            onClick={() => window.print()}
            className="rounded-lg bg-gray-800 px-4 py-2 text-sm font-medium text-white hover:bg-gray-700 print:hidden"
          >
            Print
          </button>
        </div>

        {/* =====================================================
            FILTERS
        ====================================================== */}
        <form
          onSubmit={handleSearch}
          className="mb-6 rounded-xl bg-white p-4 shadow-sm print:hidden"
        >
          <div className="grid grid-cols-1 gap-4 md:grid-cols-4">
            {/* Product Code */}
            <div>
              <label className="mb-1 block text-sm font-medium text-gray-700">
                Product Code
              </label>

              <input
                type="text"
                value={productCode}
                onChange={(e) => setProductCode(e.target.value)}
                placeholder="Enter product code"
                className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
              />
            </div>

            {/* Product Name */}
            <div>
              <label className="mb-1 block text-sm font-medium text-gray-700">
                Product Name
              </label>

              <input
                type="text"
                value={productName}
                onChange={(e) => setProductName(e.target.value)}
                placeholder="Enter product name"
                className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
              />
            </div>

            {/* Location — dropdown from /api/locations */}
            <div>
              <label className="mb-1 block text-sm font-medium text-gray-700">
                Location
              </label>

              <select
                value={locationID}
                onChange={(e) => setLocationID(e.target.value)}
                disabled={locationsLoading}
                className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2 text-sm outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 disabled:cursor-not-allowed disabled:bg-gray-100"
              >
                <option value="">
                  {locationsLoading
                    ? "Loading locations..."
                    : "All Locations"}
                </option>

                {locations.map((loc) => (
                  <option key={loc.id} value={loc.id}>
                    {loc.label}
                  </option>
                ))}
              </select>

              {locationsError && (
                <p className="mt-1 text-xs text-red-600">
                  {locationsError}
                </p>
              )}
            </div>

            {/* Buttons */}
            <div className="flex items-end gap-2">
              <button
                type="submit"
                disabled={loading}
                className="flex-1 rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-60"
              >
                {loading ? "Loading..." : "Search"}
              </button>

              <button
                type="button"
                onClick={clearFilters}
                className="rounded-lg border border-gray-300 bg-white px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50"
              >
                Clear
              </button>
            </div>
          </div>
        </form>

        {/* =====================================================
            ERROR
        ====================================================== */}
        {error && (
          <div className="mb-6 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
            {error}
          </div>
        )}

        {/* =====================================================
            PRINT TITLE
        ====================================================== */}
        <div className="mb-4 hidden print:block">
          <h2 className="text-xl font-bold">Bin Card</h2>

          <div className="mt-2 text-sm text-gray-700">
            <div>
              <strong>Product Code:</strong>{" "}
              {productInfo.code || "All"}
            </div>

            <div>
              <strong>Product Name:</strong>{" "}
              {productInfo.name || "All"}
            </div>

            <div>
              <strong>Location:</strong> {locationLabel}
            </div>
          </div>
        </div>

        {/* =====================================================
            SUMMARY
        ====================================================== */}
        <div className="mb-6 grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
          {/* Opening */}
          <div className="rounded-xl bg-white p-5 shadow-sm">
            <p className="text-sm font-medium text-gray-500">
              Opening Balance
            </p>

            <p className="mt-2 text-2xl font-bold text-gray-800">
              {formatNumber(openingBalance)}
            </p>
          </div>

          {/* Total In */}
          <div className="rounded-xl bg-white p-5 shadow-sm">
            <p className="text-sm font-medium text-gray-500">
              Total In
            </p>

            <p className="mt-2 text-2xl font-bold text-green-600">
              {formatNumber(totalIn)}
            </p>
          </div>

          {/* Total Out */}
          <div className="rounded-xl bg-white p-5 shadow-sm">
            <p className="text-sm font-medium text-gray-500">
              Total Out
            </p>

            <p className="mt-2 text-2xl font-bold text-red-600">
              {formatNumber(totalOut)}
            </p>
          </div>

          {/* Closing */}
          <div className="rounded-xl bg-white p-5 shadow-sm">
            <p className="text-sm font-medium text-gray-500">
              Closing Balance
            </p>

            <p
              className={`mt-2 text-2xl font-bold ${
                closingBalance < 0
                  ? "text-red-600"
                  : "text-blue-600"
              }`}
            >
              {formatNumber(closingBalance)}
            </p>
          </div>
        </div>

        {/* =====================================================
            PRODUCT / LOCATION INFO
        ====================================================== */}
        {(productInfo.code ||
          productInfo.name ||
          locationID) && (
          <div className="mb-4 rounded-xl bg-white p-4 shadow-sm">
            <div className="grid grid-cols-1 gap-3 text-sm md:grid-cols-3">
              <div>
                <span className="text-gray-500">
                  Product Code
                </span>

                <div className="font-semibold text-gray-800">
                  {productInfo.code || "-"}
                </div>
              </div>

              <div>
                <span className="text-gray-500">
                  Product Name
                </span>

                <div className="font-semibold text-gray-800">
                  {productInfo.name || "-"}
                </div>
              </div>

              <div>
                <span className="text-gray-500">Location</span>

                <div className="font-semibold text-gray-800">
                  {locationLabel}
                </div>
              </div>
            </div>
          </div>
        )}

        {/* =====================================================
            TABLE
        ====================================================== */}
        <div className="overflow-hidden rounded-xl bg-white shadow-sm">
          <div className="overflow-x-auto">
            <table className="min-w-[1200px] w-full border-collapse">
              <thead>
                <tr className="bg-gray-800 text-left text-xs font-semibold uppercase tracking-wider text-white">
                  <th className="px-4 py-3">#</th>
                  <th className="px-4 py-3">Date</th>
                  <th className="px-4 py-3">Document No</th>
                  <th className="px-4 py-3">Transaction</th>
                  <th className="px-4 py-3">Product</th>
                  <th className="px-4 py-3">Reference</th>
                  <th className="px-4 py-3 text-right">In Qty</th>
                  <th className="px-4 py-3 text-right">Out Qty</th>
                  <th className="px-4 py-3 text-right">Balance</th>
                  <th className="px-4 py-3 text-right">Amount</th>
                  <th className="px-4 py-3">Location</th>
                </tr>
              </thead>

              <tbody className="divide-y divide-gray-200">
                {/* Opening Row */}
                <tr className="bg-blue-50">
                  <td className="px-4 py-3 text-sm text-gray-500">-</td>
                  <td className="px-4 py-3 text-sm text-gray-600">-</td>
                  <td className="px-4 py-3 text-sm font-semibold text-gray-700">
                    OPENING
                  </td>
                  <td className="px-4 py-3 text-sm font-semibold text-blue-700">
                    OPENING BALANCE
                  </td>
                  <td className="px-4 py-3 text-sm">
                    {productInfo.code || "-"}
                  </td>
                  <td className="px-4 py-3 text-sm">-</td>
                  <td className="px-4 py-3 text-right text-sm">-</td>
                  <td className="px-4 py-3 text-right text-sm">-</td>
                  <td className="px-4 py-3 text-right text-sm font-bold text-blue-700">
                    {formatNumber(openingBalance)}
                  </td>
                  <td className="px-4 py-3 text-right text-sm">-</td>
                  <td className="px-4 py-3 text-sm">
                    {locationLabel}
                  </td>
                </tr>

                {/* Loading */}
                {loading && (
                  <tr>
                    <td
                      colSpan={11}
                      className="px-4 py-12 text-center text-sm text-gray-500"
                    >
                      Loading bin card...
                    </td>
                  </tr>
                )}

                {/* Empty */}
                {!loading && rows.length === 0 && (
                  <tr>
                    <td
                      colSpan={11}
                      className="px-4 py-12 text-center text-sm text-gray-500"
                    >
                      No stock movements found.
                    </td>
                  </tr>
                )}

                {/* Data */}
                {!loading &&
                  rows.map((row, index) => (
                    <tr
                      key={`${row.documentID}-${row.detailID}-${index}`}
                      className="hover:bg-gray-50"
                    >
                      <td className="px-4 py-3 text-sm text-gray-500">
                        {index + 1}
                      </td>

                      <td className="whitespace-nowrap px-4 py-3 text-sm text-gray-700">
                        {formatDate(row.date)}
                      </td>

                      <td className="whitespace-nowrap px-4 py-3 text-sm font-medium text-gray-800">
                        {row.documentNo || "-"}
                      </td>

                      <td
                        className={`whitespace-nowrap px-4 py-3 text-sm ${transactionClass(
                          row.transactionType
                        )}`}
                      >
                        {row.transactionType || "-"}
                      </td>

                      <td className="px-4 py-3 text-sm">
                        <div className="font-medium text-gray-800">
                          {row.productCode || "-"}
                        </div>

                        <div className="max-w-[280px] truncate text-xs text-gray-500">
                          {row.productName || ""}
                        </div>
                      </td>

                      <td className="max-w-[180px] truncate px-4 py-3 text-sm text-gray-600">
                        {row.reference || "-"}
                      </td>

                      <td className="px-4 py-3 text-right text-sm font-medium text-green-600">
                        {row.inQty > 0
                          ? formatNumber(row.inQty)
                          : "-"}
                      </td>

                      <td className="px-4 py-3 text-right text-sm font-medium text-red-600">
                        {row.outQty > 0
                          ? formatNumber(row.outQty)
                          : "-"}
                      </td>

                      <td
                        className={`px-4 py-3 text-right text-sm font-bold ${
                          row.balance < 0
                            ? "text-red-600"
                            : "text-gray-800"
                        }`}
                      >
                        {formatNumber(row.balance)}
                      </td>

                      <td className="px-4 py-3 text-right text-sm text-gray-700">
                        {formatAmount(row.amount)}
                      </td>

                      <td className="px-4 py-3 text-sm text-gray-700">
                        {row.locationID || "-"}
                      </td>
                    </tr>
                  ))}

                {/* Total */}
                {!loading && rows.length > 0 && (
                  <tr className="border-t-2 border-gray-300 bg-gray-100 font-semibold">
                    <td
                      colSpan={6}
                      className="px-4 py-4 text-right text-sm text-gray-800"
                    >
                      TOTAL
                    </td>

                    <td className="px-4 py-4 text-right text-sm text-green-700">
                      {formatNumber(totalIn)}
                    </td>

                    <td className="px-4 py-4 text-right text-sm text-red-700">
                      {formatNumber(totalOut)}
                    </td>

                    <td className="px-4 py-4 text-right text-sm font-bold text-blue-700">
                      {formatNumber(closingBalance)}
                    </td>

                    <td className="px-4 py-4 text-right text-sm text-gray-800">
                      {formatAmount(
                        rows.reduce(
                          (sum, row) =>
                            sum + Number(row.amount || 0),
                          0
                        )
                      )}
                    </td>

                    <td />
                  </tr>
                )}
              </tbody>
            </table>
          </div>

          {/* Footer */}
          <div className="border-t bg-gray-50 px-4 py-3 text-xs text-gray-500">
            {rows.length} stock movement
            {rows.length === 1 ? "" : "s"} found
          </div>
        </div>
      </div>

      {/* =====================================================
          PRINT CSS
      ====================================================== */}
      <style>
        {`
          @media print {
            @page {
              size: landscape;
              margin: 10mm;
            }

            body {
              background: white !important;
            }

            .print\\\\:hidden {
              display: none !important;
            }

            .print\\\\:block {
              display: block !important;
            }

            table {
              width: 100% !important;
              font-size: 9px !important;
            }

            th,
            td {
              padding: 5px !important;
            }

            .shadow-sm {
              box-shadow: none !important;
            }
          }
        `}
      </style>
    </div>
  );
};

export default BinCard;