import React, { useCallback, useEffect, useMemo, useState } from "react";
import axios from "axios";
import { AuthContext } from "./SERVER/AuthContext.js";

// ← PERM
import { usePermissions } from "../hooks/usePermissions.jsx";

const API_URL = "http://localhost:5000";

const EMPTY_FORM = {
  CompanyID: "",
  CompanyName: "",
  LocationCode: "",
  LocationName: "",
  Address1: "",
  Mobile: "",
  Email: "",
  IsVat: "0",
  IsActive: "1",
};

function Location() {
  const { user } = React.useContext(AuthContext);

  // ============================================================
  // PERMISSIONS                                              // ← PERM
  // ============================================================
  const { can, loading: permissionsLoading } = usePermissions();   // ← PERM

  const canViewLocation   = can("Location", "View");               // ← PERM
  const canAddLocation    = can("Location", "Add");                // ← PERM
  const canEditLocation   = can("Location", "Edit");               // ← PERM
  const canDeleteLocation = can("Location", "Delete");             // ← PERM

  // ============================================================
  // STATE
  // ============================================================
  const [form, setForm] = useState(EMPTY_FORM);
  const [locations, setLocations] = useState([]);
  const [companies, setCompanies] = useState([]);
  const [editingId, setEditingId] = useState(null);

  const [loading, setLoading] = useState(false);
  const [loadingCompanies, setLoadingCompanies] = useState(false);
  const [saving, setSaving] = useState(false);

  const [search, setSearch] = useState("");
  const [companySearch, setCompanySearch] = useState("");
  const [showCompanyModal, setShowCompanyModal] = useState(false);

  // ============================================================
  // HELPERS
  // ============================================================
  const extractData = (response) => {
    if (Array.isArray(response?.data)) return response.data;
    if (Array.isArray(response?.data?.data)) return response.data.data;
    if (Array.isArray(response?.data?.recordset)) return response.data.recordset;
    return [];
  };

  const getCompanyID = (company) =>
    company?.CompanyID ?? company?.companyID ?? company?.ID ?? company?.Id ?? "";

  const getCompanyCode = (company) =>
    company?.CompanyCode ?? company?.companyCode ?? company?.Code ?? company?.code ?? "";

  const getCompanyName = (company) =>
    company?.CompanyName ?? company?.companyName ?? company?.Name ?? company?.name ?? "";

  const getLocationID = (location) =>
    location?.LocationID ?? location?.locationID ?? location?.ID ?? location?.Id;

  // ============================================================
  // LOAD LOCATIONS
  // ============================================================
  const loadLocations = useCallback(async () => {
    try {
      setLoading(true);

      const response = await axios.get(`${API_URL}/Locations`);
      const data = extractData(response);

      setLocations(data);
    } catch (error) {
      console.error("LOAD LOCATIONS ERROR:", error);
      alert(
        error.response?.data?.message || "Error loading locations."
      );
    } finally {
      setLoading(false);
    }
  }, []);

  // ============================================================
  // LOAD COMPANIES
  // ============================================================
  const loadCompanies = useCallback(async () => {
    try {
      setLoadingCompanies(true);

      const response = await axios.get(`${API_URL}/Companies`);
      const data = extractData(response);

      setCompanies(data);
    } catch (error) {
      console.error("LOAD COMPANIES ERROR:", error);
      alert(
        error.response?.data?.message || "Error loading companies."
      );
    } finally {
      setLoadingCompanies(false);
    }
  }, []);

  // ============================================================
  // INITIAL LOAD
  // ============================================================
  useEffect(() => {
    // ← PERM
    if (permissionsLoading) return;
    if (!canViewLocation) return;

    loadLocations();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loadLocations, canViewLocation, permissionsLoading]);         // ← PERM

  // ============================================================
  // INPUT CHANGE
  // ============================================================
  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  // ============================================================
  // RESET FORM
  // ============================================================
  const resetForm = useCallback(() => {
    setForm(EMPTY_FORM);
    setEditingId(null);
    setCompanySearch("");
  }, []);

  // ============================================================
  // GENERATE LOCATION CODE
  // ============================================================
  const generateLocationCode = useCallback(async () => {
    try {
      const response = await axios.get(`${API_URL}/Locationcode?q=`);
      const rows = extractData(response);

      if (!rows.length) return "01";

      const numbers = rows
        .map((row) => {
          const code = String(row?.LocationCode || "").trim();
          const match = code.match(/\d+/);
          return match ? parseInt(match[0], 10) : 0;
        })
        .filter((number) => !Number.isNaN(number));

      const highest = numbers.length ? Math.max(...numbers) : 0;
      return String(highest + 1).padStart(2, "0");
    } catch (error) {
      console.error("GENERATE LOCATION CODE ERROR:", error);
      return "01";
    }
  }, []);

  // ============================================================
  // NEW LOCATION
  // ============================================================
  const handleNew = async () => {
    // ← PERM
    if (!canAddLocation) {
      alert("You do not have permission to create locations.");
      return;
    }

    try {
      setSaving(true);

      const newCode = await generateLocationCode();

      setForm({ ...EMPTY_FORM, LocationCode: newCode });
      setEditingId(null);
    } catch (error) {
      console.error("NEW LOCATION ERROR:", error);
      setForm(EMPTY_FORM);
      setEditingId(null);
    } finally {
      setSaving(false);
    }
  };

  // ============================================================
  // COMPANY MODAL
  // ============================================================
  const openCompanyModal = async () => {
    // ← PERM: read-only users can't pick a company to save
    if (!canAddLocation && !canEditLocation) return;

    setCompanySearch("");

    if (companies.length === 0) {
      await loadCompanies();
    }

    setShowCompanyModal(true);
  };

  // ============================================================
  // F12 HANDLER
  // ============================================================
  const handleCompanyKeyDown = async (e) => {
    if (e.key === "F12") {
      e.preventDefault();
      await openCompanyModal();
    }
  };

  // ============================================================
  // SELECT COMPANY
  // ============================================================
  const handleCompanySelect = (company) => {
    const companyID = getCompanyID(company);
    const companyCode = getCompanyCode(company);
    const companyName = getCompanyName(company);

    if (!companyID) {
      alert("Selected company does not have a CompanyID.");
      return;
    }

    const displayName = companyCode
      ? `${companyCode} - ${companyName}`
      : companyName;

    setForm((prev) => ({
      ...prev,
      CompanyID: String(companyID),
      CompanyName: displayName,
    }));

    setShowCompanyModal(false);
  };

  // ============================================================
  // CLEAR COMPANY
  // ============================================================
  const clearCompany = () => {
    setForm((prev) => ({ ...prev, CompanyID: "", CompanyName: "" }));
  };

  // ============================================================
  // SAVE / UPDATE
  // ============================================================
  const handleSubmit = async (e) => {
    e.preventDefault();

    // ----- Permission guards (before validation) -----        // ← PERM
    if (editingId && !canEditLocation) {
      alert("You do not have permission to edit locations.");
      return;
    }
    if (!editingId && !canAddLocation) {
      alert("You do not have permission to create locations.");
      return;
    }

    // Company required
    if (!form.CompanyID || !String(form.CompanyID).trim()) {
      alert("Please select a Company before saving.");
      await openCompanyModal();
      return;
    }

    if (!form.LocationCode.trim()) {
      alert("Location Code is required.");
      return;
    }

    if (!form.LocationName.trim()) {
      alert("Location Name is required.");
      return;
    }

    const payload = {
      CompanyID: String(form.CompanyID).trim(),
      LocationCode: form.LocationCode.trim(),
      LocationName: form.LocationName.trim(),
      Address1: form.Address1.trim(),
      Mobile: form.Mobile.trim(),
      Email: form.Email.trim(),
      IsVat: Number(form.IsVat),
      IsActive: Number(form.IsActive),
      username: user?.username || "",
    };

    try {
      setSaving(true);

      let response;

      if (editingId) {
        response = await axios.put(
          `${API_URL}/Location/${editingId}`,
          payload
        );
      } else {
        response = await axios.post(`${API_URL}/Location`, payload);
      }

      if (response.data?.success) {
        alert(
          editingId
            ? "Location updated successfully."
            : "Location saved successfully."
        );

        await loadLocations();
        resetForm();
      } else {
        alert(response.data?.message || "Unable to save location.");
      }
    } catch (error) {
      console.error("SAVE LOCATION ERROR:", error);
      alert(error.response?.data?.message || "Error saving location.");
    } finally {
      setSaving(false);
    }
  };

  // ============================================================
  // EDIT
  // ============================================================
  const handleEdit = (location) => {
    // ← PERM
    if (!canEditLocation) {
      alert("You do not have permission to edit locations.");
      return;
    }

    const locationID = getLocationID(location);

    if (!locationID) {
      alert("Invalid LocationID.");
      return;
    }

    const companyID = location?.CompanyID ?? "";
    const companyCode = location?.CompanyCode ?? "";
    const companyName = location?.CompanyName ?? "";

    let displayCompany = companyName;

    if (companyCode && companyName) {
      displayCompany = `${companyCode} - ${companyName}`;
    } else if (companyCode) {
      displayCompany = companyCode;
    } else if (companyID) {
      displayCompany = String(companyID);
    }

    setEditingId(locationID);

    setForm({
      CompanyID:
        companyID !== null && companyID !== undefined ? String(companyID) : "",
      CompanyName: displayCompany || "",
      LocationCode: location?.LocationCode || "",
      LocationName: location?.LocationName || "",
      Address1: location?.Address1 || "",
      Mobile: location?.Mobile || "",
      Email: location?.Email || "",
      IsVat: location?.IsVat ? "1" : "0",
      IsActive: location?.IsActive === 0 ? "0" : "1",
    });

    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  // ============================================================
  // DELETE
  // ============================================================
  const handleDelete = async (location) => {
    // ← PERM
    if (!canDeleteLocation) {
      alert("You do not have permission to delete locations.");
      return;
    }

    console.log("LOCATION TO DELETE:", location);

    const locationID = getLocationID(location);
    console.log("LOCATION ID:", locationID);

    if (locationID === null) {
      alert(
        "Invalid Location ID. Please check the LocationID returned by /Locations."
      );
      return;
    }

    const locationName =
      location?.LocationName || location?.LocationCode || "this location";

    const confirmed = window.confirm(
      `Are you sure you want to delete "${locationName}"?`
    );
    if (!confirmed) return;

    try {
      setLoading(true);

      const response = await axios.delete(`${API_URL}/Location/${locationID}`);
      console.log("DELETE RESPONSE:", response.data);

      if (response.data?.success) {
        alert(response.data.message || "Location deleted successfully.");

        if (Number(editingId) === Number(locationID)) {
          resetForm();
        }

        await loadLocations();
      } else {
        alert(response.data?.message || "Unable to delete location.");
      }
    } catch (error) {
      console.error("DELETE LOCATION ERROR:", error);
      alert(
        error.response?.data?.message ||
          error.message ||
          "Error deleting location."
      );
    } finally {
      setLoading(false);
    }
  };

  // ============================================================
  // SEARCH LOCATIONS
  // ============================================================
  const filteredLocations = useMemo(() => {
    const value = search.trim().toLowerCase();
    if (!value) return locations;

    return locations.filter((location) => {
      const code = String(location?.LocationCode || "").toLowerCase();
      const name = String(location?.LocationName || "").toLowerCase();
      const companyID = String(location?.CompanyID || "").toLowerCase();
      const companyName = String(location?.CompanyName || "").toLowerCase();
      const address = String(location?.Address1 || "").toLowerCase();
      const mobile = String(location?.Mobile || "").toLowerCase();

      return (
        code.includes(value) ||
        name.includes(value) ||
        companyID.includes(value) ||
        companyName.includes(value) ||
        address.includes(value) ||
        mobile.includes(value)
      );
    });
  }, [locations, search]);

  // ============================================================
  // FILTER COMPANIES
  // ============================================================
  const filteredCompanies = useMemo(() => {
    const value = companySearch.trim().toLowerCase();
    if (!value) return companies;

    return companies.filter((company) => {
      const id = String(getCompanyID(company)).toLowerCase();
      const code = String(getCompanyCode(company)).toLowerCase();
      const name = String(getCompanyName(company)).toLowerCase();

      return id.includes(value) || code.includes(value) || name.includes(value);
    });
  }, [companies, companySearch]);

  // ============================================================
  // COMPANY NAME LOOKUP
  // ============================================================
  const getDisplayCompany = (location) => {
    if (location?.CompanyName) return location.CompanyName;
    if (location?.CompanyCode) return location.CompanyCode;
    return location?.CompanyID || "";
  };

  // ============================================================
  // COMPUTED                                                 // ← PERM
  // ============================================================
  const isEditing = Boolean(editingId);
  const saveAllowed =
    (isEditing && canEditLocation) || (!isEditing && canAddLocation);
  const readOnlyEdit = isEditing && !canEditLocation;

  // ============================================================
  // ACCESS GATE                                              // ← PERM
  // ============================================================
  if (permissionsLoading) {
    return (
      <div className="min-h-screen bg-gray-100 p-6 flex items-center justify-center text-gray-500">
        Checking permissions…
      </div>
    );
  }

  if (!canViewLocation) {
    return (
      <div className="min-h-screen bg-gray-100 p-6">
        <div className="mx-auto max-w-xl mt-20 bg-red-50 border border-red-200 rounded-xl p-8 text-center">
          <h2 className="text-lg font-bold text-red-700">Access Denied</h2>
          <p className="text-sm text-red-600 mt-2">
            You do not have permission to view Location Master.
          </p>
          <p className="text-xs text-red-400 mt-3">
            Module: <code>Location</code>
          </p>
        </div>
      </div>
    );
  }

  // ============================================================
  // UI
  // ============================================================
  return (
    <div className="min-h-screen bg-gray-100 p-4 md:p-6">
      <div className="max-w-7xl mx-auto">

        {/* HEADER */}
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-5 mb-5">
          <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
            <div>
              <h1 className="text-2xl md:text-3xl font-bold text-gray-800">
                Location Master
              </h1>
              <p className="text-sm text-gray-500 mt-1">
                Create and manage company locations
              </p>
            </div>

            <div className="flex items-center gap-2">
              {/* ← PERM: read-only badge */}
              {readOnlyEdit && (
                <span className="rounded-full bg-slate-200 px-3 py-1 text-xs font-semibold text-slate-600">
                  READ ONLY
                </span>
              )}

              {/* ← PERM: New button only when user can Add */}
              {canAddLocation && (
                <button
                  type="button"
                  onClick={handleNew}
                  disabled={saving}
                  className="px-5 py-2.5 rounded-lg bg-blue-600 text-white font-semibold hover:bg-blue-700 disabled:opacity-50"
                >
                  + New
                </button>
              )}

              <button
                type="button"
                onClick={loadLocations}
                disabled={loading}
                className="px-5 py-2.5 rounded-lg bg-gray-700 text-white font-semibold hover:bg-gray-800 disabled:opacity-50"
              >
                {loading ? "Loading..." : "Refresh"}
              </button>
            </div>
          </div>
        </div>

        {/* FORM */}
        <form
          onSubmit={handleSubmit}
          className="bg-white rounded-xl shadow-sm border border-gray-200 p-5 mb-5"
        >
          {/* EDITING INDICATOR */}
          {editingId && (
            <div className="mb-5 rounded-lg bg-yellow-50 border border-yellow-200 px-4 py-3">
              <div className="flex items-center justify-between">
                <div>
                  <p className="font-semibold text-yellow-800">
                    Editing Location
                  </p>
                  <p className="text-sm text-yellow-700">
                    Location ID: {editingId}
                  </p>
                </div>

                <button
                  type="button"
                  onClick={resetForm}
                  className="text-sm font-semibold text-yellow-800 hover:text-yellow-900"
                >
                  Cancel Edit
                </button>
              </div>
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">

            {/* COMPANY */}
            <div className="lg:col-span-2">
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Company <span className="text-red-500">*</span>
              </label>

              <div className="flex gap-2">
                <input
                  type="text"
                  name="CompanyID"
                  value={form.CompanyName || ""}
                  readOnly
                  onKeyDown={handleCompanyKeyDown}
                  onClick={openCompanyModal}
                  placeholder={
                    saveAllowed
                      ? "Press F12 to select company"
                      : "Company (read-only)"
                  }
                  className={`flex-1 border rounded-lg px-3 py-2.5 bg-white cursor-pointer outline-none focus:ring-2 ${
                    !form.CompanyID
                      ? "border-red-300 focus:ring-red-200"
                      : "border-gray-300 focus:ring-blue-200"
                  }`}
                />

                {/* ← PERM: picker button only when user can save */}
                {saveAllowed && (
                  <>
                    <button
                      type="button"
                      onClick={openCompanyModal}
                      className="px-4 py-2.5 rounded-lg bg-blue-600 text-white font-semibold hover:bg-blue-700"
                      title="Select Company - F12"
                    >
                      F12
                    </button>

                    {form.CompanyID && (
                      <button
                        type="button"
                        onClick={clearCompany}
                        className="px-4 py-2.5 rounded-lg bg-red-500 text-white font-semibold hover:bg-red-600"
                      >
                        Clear
                      </button>
                    )}
                  </>
                )}
              </div>

              {!form.CompanyID && (
                <p className="text-xs text-red-500 mt-1">
                  Please select a company.
                </p>
              )}

              {form.CompanyID && (
                <p className="text-xs text-green-600 mt-1">
                  Company ID: {form.CompanyID}
                </p>
              )}
            </div>

            {/* LOCATION CODE */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Location Code <span className="text-red-500">*</span>
              </label>
              <input
                type="text"
                name="LocationCode"
                value={form.LocationCode}
                onChange={handleChange}
                maxLength={15}
                placeholder="Location Code"
                className="w-full border border-gray-300 rounded-lg px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-200"
              />
            </div>

            {/* LOCATION NAME */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Location Name <span className="text-red-500">*</span>
              </label>
              <input
                type="text"
                name="LocationName"
                value={form.LocationName}
                onChange={handleChange}
                maxLength={50}
                placeholder="Location Name"
                className="w-full border border-gray-300 rounded-lg px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-200"
              />
            </div>

            {/* ADDRESS */}
            <div className="lg:col-span-2">
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Address
              </label>
              <input
                type="text"
                name="Address1"
                value={form.Address1}
                onChange={handleChange}
                maxLength={50}
                placeholder="Address"
                className="w-full border border-gray-300 rounded-lg px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-200"
              />
            </div>

            {/* MOBILE */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Mobile
              </label>
              <input
                type="text"
                name="Mobile"
                value={form.Mobile}
                onChange={handleChange}
                maxLength={50}
                placeholder="Mobile Number"
                className="w-full border border-gray-300 rounded-lg px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-200"
              />
            </div>

            {/* EMAIL */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Email
              </label>
              <input
                type="email"
                name="Email"
                value={form.Email}
                onChange={handleChange}
                maxLength={50}
                placeholder="Email"
                className="w-full border border-gray-300 rounded-lg px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-200"
              />
            </div>

            {/* VAT */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">
                VAT
              </label>
              <div className="flex gap-5">
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    name="IsVat"
                    value="1"
                    checked={form.IsVat === "1"}
                    onChange={handleChange}
                    className="w-4 h-4"
                  />
                  <span className="text-sm">Yes</span>
                </label>

                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    name="IsVat"
                    value="0"
                    checked={form.IsVat === "0"}
                    onChange={handleChange}
                    className="w-4 h-4"
                  />
                  <span className="text-sm">No</span>
                </label>
              </div>
            </div>

            {/* ACTIVE */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">
                Status
              </label>
              <div className="flex gap-5">
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    name="IsActive"
                    value="1"
                    checked={form.IsActive === "1"}
                    onChange={handleChange}
                    className="w-4 h-4"
                  />
                  <span className="text-sm">Active</span>
                </label>

                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    name="IsActive"
                    value="0"
                    checked={form.IsActive === "0"}
                    onChange={handleChange}
                    className="w-4 h-4"
                  />
                  <span className="text-sm">Inactive</span>
                </label>
              </div>
            </div>

          </div>

          {/* ACTION BUTTONS */}
          <div className="flex flex-wrap justify-end items-center gap-3 mt-6 pt-5 border-t border-gray-200">
            <button
              type="button"
              onClick={resetForm}
              disabled={saving}
              className="px-6 py-2.5 rounded-lg bg-gray-200 text-gray-800 font-semibold hover:bg-gray-300 disabled:opacity-50"
            >
              Clear
            </button>

            {/* ← PERM: Save button only when saveAllowed */}
            {saveAllowed && (
              <button
                type="submit"
                disabled={saving || !form.CompanyID}
                className={`px-7 py-2.5 rounded-lg text-white font-semibold ${
                  saving || !form.CompanyID
                    ? "bg-gray-400 cursor-not-allowed"
                    : "bg-green-600 hover:bg-green-700"
                }`}
              >
                {saving
                  ? "Saving..."
                  : isEditing
                  ? "Update Location"
                  : "Save Location"}
              </button>
            )}

            {/* ← PERM: helper text when blocked */}
            {readOnlyEdit && (
              <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-2.5 text-xs font-semibold text-slate-500">
                You have read-only access — editing is disabled.
              </div>
            )}

            {!isEditing && !canAddLocation && (
              <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-2.5 text-xs font-semibold text-slate-500">
                You do not have permission to create new locations.
              </div>
            )}
          </div>
        </form>

        {/* SEARCH + LIST */}
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-5">
          <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4 mb-5">
            <div>
              <h2 className="text-lg font-bold text-gray-800">
                Location List
              </h2>
              <p className="text-sm text-gray-500">
                {filteredLocations.length} location
                {filteredLocations.length === 1 ? "" : "s"}
              </p>
            </div>

            <div className="w-full md:w-96">
              <input
                type="text"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search code, name, company, mobile..."
                className="w-full border border-gray-300 rounded-lg px-4 py-2.5 outline-none focus:ring-2 focus:ring-blue-200"
              />
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full min-w-[900px] border-collapse">
              <thead>
                <tr className="bg-gray-50 border-b border-gray-200">
                  <th className="text-left px-4 py-3 text-xs font-bold text-gray-600 uppercase">#</th>
                  <th className="text-left px-4 py-3 text-xs font-bold text-gray-600 uppercase">Code</th>
                  <th className="text-left px-4 py-3 text-xs font-bold text-gray-600 uppercase">Location</th>
                  <th className="text-left px-4 py-3 text-xs font-bold text-gray-600 uppercase">Company</th>
                  <th className="text-left px-4 py-3 text-xs font-bold text-gray-600 uppercase">Mobile</th>
                  <th className="text-center px-4 py-3 text-xs font-bold text-gray-600 uppercase">VAT</th>
                  <th className="text-center px-4 py-3 text-xs font-bold text-gray-600 uppercase">Status</th>
                  <th className="text-center px-4 py-3 text-xs font-bold text-gray-600 uppercase">Actions</th>
                </tr>
              </thead>

              <tbody>
                {loading && (
                  <tr>
                    <td colSpan="8" className="text-center py-10 text-gray-500">
                      Loading locations...
                    </td>
                  </tr>
                )}

                {!loading && filteredLocations.length === 0 && (
                  <tr>
                    <td colSpan="8" className="text-center py-10 text-gray-500">
                      No locations found.
                    </td>
                  </tr>
                )}

                {!loading &&
                  filteredLocations.map((location, index) => {
                    const locationID = getLocationID(location);
                    const isActive = location?.IsActive !== 0;
                    const isVat =
                      location?.IsVat === 1 || location?.IsVat === true;

                    return (
                      <tr
                        key={locationID || index}
                        className="border-b border-gray-100 hover:bg-gray-50"
                      >
                        <td className="px-4 py-3 text-sm text-gray-600">
                          {index + 1}
                        </td>

                        <td className="px-4 py-3 text-sm font-semibold text-gray-800">
                          {location?.LocationCode || "-"}
                        </td>

                        <td className="px-4 py-3">
                          <div className="font-semibold text-gray-800">
                            {location?.LocationName || "-"}
                          </div>
                          {location?.Address1 && (
                            <div className="text-xs text-gray-500 mt-1">
                              {location.Address1}
                            </div>
                          )}
                        </td>

                        <td className="px-4 py-3 text-sm text-gray-700">
                          {getDisplayCompany(location)}
                        </td>

                        <td className="px-4 py-3 text-sm text-gray-700">
                          {location?.Mobile || "-"}
                        </td>

                        <td className="px-4 py-3 text-center">
                          <span
                            className={`inline-flex px-2.5 py-1 rounded-full text-xs font-semibold ${
                              isVat
                                ? "bg-blue-100 text-blue-700"
                                : "bg-gray-100 text-gray-600"
                            }`}
                          >
                            {isVat ? "VAT" : "Non-VAT"}
                          </span>
                        </td>

                        <td className="px-4 py-3 text-center">
                          <span
                            className={`inline-flex px-2.5 py-1 rounded-full text-xs font-semibold ${
                              isActive
                                ? "bg-green-100 text-green-700"
                                : "bg-red-100 text-red-700"
                            }`}
                          >
                            {isActive ? "Active" : "Inactive"}
                          </span>
                        </td>

                        {/* ← PERM: gate the action buttons */}
                        <td className="px-4 py-3">
                          <div className="flex justify-center gap-2">
                            {canEditLocation && (
                              <button
                                type="button"
                                onClick={() => handleEdit(location)}
                                className="px-3 py-1.5 rounded-lg bg-blue-600 text-white text-xs font-semibold hover:bg-blue-700"
                              >
                                Edit
                              </button>
                            )}

                            {canDeleteLocation && (
                              <button
                                type="button"
                                onClick={() => handleDelete(location)}
                                className="px-3 py-1.5 rounded-lg bg-red-600 text-white text-xs font-semibold hover:bg-red-700"
                              >
                                Delete
                              </button>
                            )}

                            {!canEditLocation && !canDeleteLocation && (
                              <span className="text-xs text-slate-400">
                                No actions
                              </span>
                            )}
                          </div>
                        </td>
                      </tr>
                    );
                  })}
              </tbody>
            </table>
          </div>
        </div>

      </div>

      {/* COMPANY MODAL */}
      {showCompanyModal && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4"
          onMouseDown={(e) => {
            if (e.target === e.currentTarget) setShowCompanyModal(false);
          }}
        >
          <div className="w-full max-w-4xl max-h-[90vh] bg-white rounded-xl shadow-2xl flex flex-col">
            <div className="flex items-center justify-between px-5 py-4 border-b border-gray-200">
              <div>
                <h2 className="text-xl font-bold text-gray-800">
                  Select Company
                </h2>
                <p className="text-sm text-gray-500 mt-1">
                  Select a company for this location
                </p>
              </div>

              <button
                type="button"
                onClick={() => setShowCompanyModal(false)}
                className="w-9 h-9 rounded-lg bg-gray-100 text-gray-600 hover:bg-gray-200 text-xl"
              >
                ×
              </button>
            </div>

            <div className="p-4 border-b border-gray-200">
              <input
                type="text"
                autoFocus
                value={companySearch}
                onChange={(e) => setCompanySearch(e.target.value)}
                placeholder="Search Company ID, Code or Name..."
                className="w-full border border-gray-300 rounded-lg px-4 py-2.5 outline-none focus:ring-2 focus:ring-blue-200"
              />
            </div>

            <div className="flex-1 overflow-y-auto p-4">
              {loadingCompanies ? (
                <div className="text-center py-10 text-gray-500">
                  Loading companies...
                </div>
              ) : filteredCompanies.length === 0 ? (
                <div className="text-center py-10 text-gray-500">
                  No companies found.
                </div>
              ) : (
                <div className="overflow-x-auto">
                  <table className="w-full">
                    <thead>
                      <tr className="bg-gray-50 border-b border-gray-200">
                        <th className="text-left px-4 py-3 text-xs font-bold text-gray-600 uppercase">
                          Company ID
                        </th>
                        <th className="text-left px-4 py-3 text-xs font-bold text-gray-600 uppercase">
                          Company Code
                        </th>
                        <th className="text-left px-4 py-3 text-xs font-bold text-gray-600 uppercase">
                          Company Name
                        </th>
                        <th className="text-center px-4 py-3 text-xs font-bold text-gray-600 uppercase">
                          Action
                        </th>
                      </tr>
                    </thead>

                    <tbody>
                      {filteredCompanies.map((company, index) => {
                        const companyID = getCompanyID(company);
                        const companyCode = getCompanyCode(company);
                        const companyName = getCompanyName(company);

                        return (
                          <tr
                            key={companyID || index}
                            className="border-b border-gray-100 hover:bg-blue-50"
                          >
                            <td className="px-4 py-3 text-sm text-gray-700">
                              {companyID || "-"}
                            </td>
                            <td className="px-4 py-3 text-sm font-semibold text-gray-800">
                              {companyCode || "-"}
                            </td>
                            <td className="px-4 py-3 text-sm text-gray-800">
                              {companyName || "-"}
                            </td>
                            <td className="px-4 py-3 text-center">
                              <button
                                type="button"
                                onClick={() => handleCompanySelect(company)}
                                className="px-4 py-1.5 rounded-lg bg-blue-600 text-white text-xs font-semibold hover:bg-blue-700"
                              >
                                Select
                              </button>
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              )}
            </div>

            <div className="flex justify-end px-5 py-4 border-t border-gray-200">
              <button
                type="button"
                onClick={() => setShowCompanyModal(false)}
                className="px-5 py-2.5 rounded-lg bg-gray-200 text-gray-800 font-semibold hover:bg-gray-300"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default Location;