import React, {
    useCallback,
    useContext,
    useEffect,
    useMemo,
    useState
} from "react";
import axios from "axios";
import {
    CheckCircle,
    Eye,
    RefreshCw,
    Search,
    X,
    Clock,
    Package,
    AlertTriangle
} from "lucide-react";

import { AuthContext } from "../pos/SERVER/AuthContext.js";

const API_URL = "http://localhost:5000";

function StockAdjustment() {

    const { user } = useContext(AuthContext);

    const [activeTab, setActiveTab] = useState("pending");

    const [pending, setPending] = useState([]);
    const [approved, setApproved] = useState([]);

    const [search, setSearch] = useState("");

    const [loading, setLoading] = useState(false);
    const [approving, setApproving] = useState(false);

    const [selected, setSelected] = useState(null);
    const [showModal, setShowModal] = useState(false);

    const [error, setError] = useState("");

    // ============================================================
    // USERNAME
    // ============================================================

    const username =
        user?.username ||
        user?.Username ||
        user?.U ||
        localStorage.getItem("username") ||
        "";

    // ============================================================
    // LOAD PENDING
    // ============================================================

    const loadPending = useCallback(async () => {

        try {

            setLoading(true);
            setError("");

            const response = await axios.get(
                `${API_URL}/stockadjustment/pending`
            );

            console.log("PENDING RESPONSE:", response.data);

            if (!response.data?.success) {

                throw new Error(
                    response.data?.message ||
                    "Unable to load pending stock counts"
                );
            }

            const rows = Array.isArray(response.data.data)
                ? response.data.data
                : [];

            setPending(rows);

        } catch (err) {

            console.error(
                "LOAD PENDING ERROR:",
                err.response?.data || err
            );

            setError(
                err.response?.data?.message ||
                err.message ||
                "Failed to load pending stock counts"
            );

            setPending([]);

        } finally {

            setLoading(false);
        }

    }, []);

    // ============================================================
    // LOAD APPROVED
    // ============================================================

    const loadApproved = useCallback(async () => {

        try {

            setLoading(true);
            setError("");

            const response = await axios.get(
                `${API_URL}/stockadjustment/approved`
            );

            console.log("APPROVED RESPONSE:", response.data);

            if (!response.data?.success) {

                throw new Error(
                    response.data?.message ||
                    "Unable to load approved adjustments"
                );
            }

            const rows = Array.isArray(response.data.data)
                ? response.data.data
                : [];

            setApproved(rows);

        } catch (err) {

            console.error(
                "LOAD APPROVED ERROR:",
                err.response?.data || err
            );

            setError(
                err.response?.data?.message ||
                err.message ||
                "Failed to load approved adjustments"
            );

            setApproved([]);

        } finally {

            setLoading(false);
        }

    }, []);

    // ============================================================
    // INITIAL LOAD
    // ============================================================

    useEffect(() => {

        loadPending();
        loadApproved();

    }, [loadPending, loadApproved]);

    // ============================================================
    // REFRESH
    // ============================================================

    const handleRefresh = async () => {

        if (activeTab === "pending") {

            await loadPending();

        } else {

            await loadApproved();
        }
    };

    // ============================================================
    // FILTER
    // ============================================================

    const filteredRows = useMemo(() => {

        const source =
            activeTab === "pending"
                ? pending
                : approved;

        const keyword = search
            .trim()
            .toLowerCase();

        if (!keyword) {
            return source;
        }

        return source.filter(row => {

            return (
                String(row.StockCountSessionID ?? "")
                    .toLowerCase()
                    .includes(keyword) ||

                String(row.StockAdjustmentID ?? "")
                    .toLowerCase()
                    .includes(keyword) ||

                String(row.SessionNo ?? "")
                    .toLowerCase()
                    .includes(keyword) ||

                String(row.DocumentNo ?? "")
                    .toLowerCase()
                    .includes(keyword) ||

                String(row.Username ?? "")
                    .toLowerCase()
                    .includes(keyword) ||

                String(row.Status ?? "")
                    .toLowerCase()
                    .includes(keyword)
            );

        });

    }, [
        activeTab,
        pending,
        approved,
        search
    ]);

    // ============================================================
    // VIEW PENDING SESSION
    // ============================================================

    const viewPending = async (row) => {

        const sessionId = Number(
            row?.StockCountSessionID
        );

        console.log(
            "VIEW PENDING SESSION ID:",
            sessionId
        );

        if (!Number.isInteger(sessionId) || sessionId <= 0) {

            alert(
                "Invalid StockCountSessionID: " +
                String(row?.StockCountSessionID)
            );

            return;
        }

        try {

            setLoading(true);

            const response = await axios.get(
                `${API_URL}/stockadjustment/session/${sessionId}`
            );

            console.log(
                "SESSION DETAILS:",
                response.data
            );

            if (!response.data?.success) {

                throw new Error(
                    response.data?.message ||
                    "Unable to load session"
                );
            }

            setSelected({
                type: "pending",
                session: response.data.data.session,
                details: response.data.data.details || []
            });

            setShowModal(true);

        } catch (err) {

            console.error(
                "VIEW SESSION ERROR:",
                err.response?.data || err
            );

            alert(
                err.response?.data?.message ||
                err.message ||
                "Failed to load session"
            );

        } finally {

            setLoading(false);
        }
    };

    // ============================================================
    // VIEW APPROVED
    // ============================================================

    const viewApproved = async (row) => {

        const adjustmentId = Number(
            row?.StockAdjustmentID
        );

        console.log(
            "VIEW APPROVED ADJUSTMENT ID:",
            adjustmentId
        );

        if (
            !Number.isInteger(adjustmentId) ||
            adjustmentId <= 0
        ) {

            alert(
                "Invalid StockAdjustmentID: " +
                String(row?.StockAdjustmentID)
            );

            return;
        }

        try {

            setLoading(true);

            const response = await axios.get(
                `${API_URL}/stockadjustment/${adjustmentId}`
            );

            console.log(
                "ADJUSTMENT DETAILS:",
                response.data
            );

            if (!response.data?.success) {

                throw new Error(
                    response.data?.message ||
                    "Unable to load adjustment"
                );
            }

            setSelected({
                type: "approved",
                adjustment: response.data.data.adjustment,
                details: response.data.data.details || []
            });

            setShowModal(true);

        } catch (err) {

            console.error(
                "VIEW APPROVED ERROR:",
                err.response?.data || err
            );

            alert(
                err.response?.data?.message ||
                err.message ||
                "Failed to load adjustment"
            );

        } finally {

            setLoading(false);
        }
    };

    // ============================================================
    // APPROVE SESSION
    // ============================================================

    const handleApprove = async (row) => {

        /*
         * IMPORTANT:
         * We get StockCountSessionID directly from the
         * pending StockCountSession row.
         */

        const sessionId = Number(
            row?.StockCountSessionID
        );

        console.log(
            "===================================="
        );

        console.log(
            "APPROVE CLICKED"
        );

        console.log(
            "FULL ROW:",
            row
        );

        console.log(
            "StockCountSessionID:",
            row?.StockCountSessionID
        );

        console.log(
            "Converted ID:",
            sessionId
        );

        console.log(
            "===================================="
        );

        if (
            !Number.isInteger(sessionId) ||
            sessionId <= 0
        ) {

            alert(
                "Invalid StockCountSessionID.\n\n" +
                "Received: " +
                String(row?.StockCountSessionID)
            );

            return;
        }

        const confirmApprove = window.confirm(
            "Approve Stock Count?\n\n" +
            "Session: " +
            String(row?.SessionNo || "") +
            "\n\n" +
            "This will update actual stock."
        );

        if (!confirmApprove) {
            return;
        }

        try {

            setApproving(true);
            setError("");

            console.log(
                "POST:",
                `${API_URL}/stockadjustment/approve-session/${sessionId}`
            );

            const response = await axios.post(
                `${API_URL}/stockadjustment/approve-session/${sessionId}`,
                {
                    username: username
                }
            );

            console.log(
                "APPROVE RESPONSE:",
                response.data
            );

            if (!response.data?.success) {

                throw new Error(
                    response.data?.message ||
                    "Approval failed"
                );
            }

            alert(
                response.data.message ||
                "Stock count approved successfully."
            );

            setShowModal(false);
            setSelected(null);

            await loadPending();
            await loadApproved();

        } catch (err) {

            console.error(
                "APPROVE ERROR:",
                err.response?.data || err
            );

            alert(
                err.response?.data?.message ||
                err.message ||
                "Stock count approval failed"
            );

        } finally {

            setApproving(false);
        }
    };

    // ============================================================
    // STATUS
    // ============================================================

    const getStatusClass = (status) => {

        const value =
            String(status || "")
                .toLowerCase();

        if (value === "approved") {

            return "bg-green-100 text-green-700";
        }

        if (
            value === "finished" ||
            value === "pending approval" ||
            value === "pending"
        ) {

            return "bg-yellow-100 text-yellow-700";
        }

        if (value === "rejected") {

            return "bg-red-100 text-red-700";
        }

        return "bg-gray-100 text-gray-700";
    };

    // ============================================================
    // FORMAT DATE
    // ============================================================

    const formatDate = (value) => {

        if (!value) {
            return "-";
        }

        const date = new Date(value);

        if (Number.isNaN(date.getTime())) {
            return String(value);
        }

        return date.toLocaleString();
    };

    // ============================================================
    // CLOSE MODAL
    // ============================================================

    const closeModal = () => {

        if (approving) {
            return;
        }

        setShowModal(false);
        setSelected(null);
    };

    // ============================================================
    // PENDING MODAL
    // ============================================================

    const renderPendingModal = () => {

        if (!selected?.session) {
            return null;
        }

        const session = selected.session;
        const details = selected.details || [];

        return (
            <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4">

                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-7xl max-h-[95vh] flex flex-col">

                    {/* HEADER */}

                    <div className="flex items-center justify-between px-6 py-4 border-b">

                        <div>

                            <h2 className="text-xl font-bold text-gray-800">
                                Stock Count Approval
                            </h2>

                            <p className="text-sm text-gray-500 mt-1">
                                Session: {session.SessionNo}
                            </p>

                        </div>

                        <button
                            type="button"
                            onClick={closeModal}
                            disabled={approving}
                            className="p-2 rounded-lg hover:bg-gray-100"
                        >
                            <X size={22} />
                        </button>

                    </div>

                    {/* SUMMARY */}

                    <div className="grid grid-cols-2 md:grid-cols-5 gap-3 p-5 bg-gray-50 border-b">

                        <SummaryCard
                            label="Session ID"
                            value={session.StockCountSessionID}
                        />

                        <SummaryCard
                            label="Total Items"
                            value={session.TotalItems}
                        />

                        <SummaryCard
                            label="Completed"
                            value={session.CompletedItems}
                        />

                        <SummaryCard
                            label="Missing"
                            value={session.MissingItems}
                        />

                        <SummaryCard
                            label="Variance"
                            value={session.TotalVariance}
                        />

                    </div>

                    {/* DETAILS */}

                    <div className="flex-1 overflow-auto p-5">

                        <div className="overflow-x-auto border rounded-xl">

                            <table className="w-full text-sm">

                                <thead className="bg-gray-100 sticky top-0">

                                    <tr>

                                        <th className="px-3 py-3 text-left">
                                            #
                                        </th>

                                        <th className="px-3 py-3 text-left">
                                            Product Code
                                        </th>

                                        <th className="px-3 py-3 text-left">
                                            Product Name
                                        </th>

                                        <th className="px-3 py-3 text-right">
                                            System
                                        </th>

                                        <th className="px-3 py-3 text-right">
                                            Store
                                        </th>

                                        <th className="px-3 py-3 text-right">
                                            Rack
                                        </th>

                                        <th className="px-3 py-3 text-right">
                                            Physical
                                        </th>

                                        <th className="px-3 py-3 text-right">
                                            Variance
                                        </th>

                                        <th className="px-3 py-3 text-center">
                                            Status
                                        </th>

                                    </tr>

                                </thead>

                                <tbody>

                                    {details.length === 0 ? (

                                        <tr>

                                            <td
                                                colSpan="9"
                                                className="text-center py-10 text-gray-500"
                                            >
                                                No stock count details found.
                                            </td>

                                        </tr>

                                    ) : (

                                        details.map((item, index) => {

                                            const physical =
                                                Number(item.PhysicalTotal ?? 0);

                                            const variance =
                                                Number(item.Variance ?? 0);

                                            return (
                                                <tr
                                                    key={
                                                        item.StockCountSessionDetID ||
                                                        index
                                                    }
                                                    className="border-t hover:bg-gray-50"
                                                >

                                                    <td className="px-3 py-3">
                                                        {index + 1}
                                                    </td>

                                                    <td className="px-3 py-3 font-medium">
                                                        {item.ProductCode || "-"}
                                                    </td>

                                                    <td className="px-3 py-3">
                                                        {item.ProductName || "-"}
                                                    </td>

                                                    <td className="px-3 py-3 text-right">
                                                        {item.SystemStock ?? 0}
                                                    </td>

                                                    <td className="px-3 py-3 text-right">
                                                        {item.StoreCount ?? 0}
                                                    </td>

                                                    <td className="px-3 py-3 text-right">
                                                        {item.RackCount ?? 0}
                                                    </td>

                                                    <td className="px-3 py-3 text-right font-semibold">
                                                        {physical}
                                                    </td>

                                                    <td
                                                        className={
                                                            "px-3 py-3 text-right font-bold " +
                                                            (
                                                                variance > 0
                                                                    ? "text-green-600"
                                                                    : variance < 0
                                                                        ? "text-red-600"
                                                                        : "text-gray-600"
                                                            )
                                                        }
                                                    >
                                                        {variance}
                                                    </td>

                                                    <td className="px-3 py-3 text-center">

                                                        <span
                                                            className={
                                                                "px-2 py-1 rounded-full text-xs font-medium " +
                                                                getStatusClass(item.Status)
                                                            }
                                                        >
                                                            {item.Status || "-"}
                                                        </span>

                                                    </td>

                                                </tr>
                                            );

                                        })

                                    )}

                                </tbody>

                            </table>

                        </div>

                    </div>

                    {/* FOOTER */}

                    <div className="flex items-center justify-between gap-3 px-6 py-4 border-t bg-gray-50">

                        <div className="text-sm text-gray-500">

                            Approval will update actual stock.

                        </div>

                        <div className="flex gap-3">

                            <button
                                type="button"
                                onClick={closeModal}
                                disabled={approving}
                                className="px-5 py-2.5 rounded-lg border bg-white hover:bg-gray-100"
                            >
                                Close
                            </button>

                            <button
                                type="button"
                                onClick={() => handleApprove(session)}
                                disabled={approving}
                                className="px-5 py-2.5 rounded-lg bg-green-600 text-white hover:bg-green-700 disabled:opacity-50 flex items-center gap-2"
                            >

                                {approving ? (
                                    <>
                                        <RefreshCw
                                            size={18}
                                            className="animate-spin"
                                        />
                                        Approving...
                                    </>
                                ) : (
                                    <>
                                        <CheckCircle size={18} />
                                        Approve
                                    </>
                                )}

                            </button>

                        </div>

                    </div>

                </div>

            </div>
        );
    };

    // ============================================================
    // APPROVED MODAL
    // ============================================================

    const renderApprovedModal = () => {

        if (!selected?.adjustment) {
            return null;
        }

        const adjustment = selected.adjustment;
        const details = selected.details || [];

        return (
            <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4">

                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-7xl max-h-[95vh] flex flex-col">

                    <div className="flex items-center justify-between px-6 py-4 border-b">

                        <div>

                            <h2 className="text-xl font-bold text-gray-800">
                                Approved Stock Adjustment
                            </h2>

                            <p className="text-sm text-gray-500 mt-1">
                                Document: {adjustment.DocumentNo}
                            </p>

                        </div>

                        <button
                            type="button"
                            onClick={closeModal}
                            className="p-2 rounded-lg hover:bg-gray-100"
                        >
                            <X size={22} />
                        </button>

                    </div>

                    <div className="grid grid-cols-2 md:grid-cols-5 gap-3 p-5 bg-gray-50 border-b">

                        <SummaryCard
                            label="Adjustment ID"
                            value={adjustment.StockAdjustmentID}
                        />

                        <SummaryCard
                            label="Document No"
                            value={adjustment.DocumentNo}
                        />

                        <SummaryCard
                            label="Location"
                            value={adjustment.LocationID}
                        />

                        <SummaryCard
                            label="Total Qty"
                            value={adjustment.TotalQty}
                        />

                        <SummaryCard
                            label="Status"
                            value={adjustment.Status}
                        />

                    </div>

                    <div className="flex-1 overflow-auto p-5">

                        <div className="overflow-x-auto border rounded-xl">

                            <table className="w-full text-sm">

                                <thead className="bg-gray-100 sticky top-0">

                                    <tr>

                                        <th className="px-3 py-3 text-left">
                                            #
                                        </th>

                                        <th className="px-3 py-3 text-left">
                                            Product Code
                                        </th>

                                        <th className="px-3 py-3 text-left">
                                            Product Name
                                        </th>

                                        <th className="px-3 py-3 text-right">
                                            Previous Stock
                                        </th>

                                        <th className="px-3 py-3 text-right">
                                            Adjustment Qty
                                        </th>

                                        <th className="px-3 py-3 text-right">
                                            New Stock
                                        </th>

                                        <th className="px-3 py-3 text-right">
                                            Cost
                                        </th>

                                        <th className="px-3 py-3 text-right">
                                            Selling
                                        </th>

                                    </tr>

                                </thead>

                                <tbody>

                                    {details.map((item, index) => {

                                        const previous =
                                            Number(item.Stock ?? 0);

                                        const qty =
                                            Number(item.Qty ?? 0);

                                        const newStock =
                                            previous + qty;

                                        return (
                                            <tr
                                                key={
                                                    item.StockAdjustmentDetID ||
                                                    index
                                                }
                                                className="border-t hover:bg-gray-50"
                                            >

                                                <td className="px-3 py-3">
                                                    {index + 1}
                                                </td>

                                                <td className="px-3 py-3 font-medium">
                                                    {item.ProductCode || "-"}
                                                </td>

                                                <td className="px-3 py-3">
                                                    {item.ProductName || "-"}
                                                </td>

                                                <td className="px-3 py-3 text-right">
                                                    {previous}
                                                </td>

                                                <td
                                                    className={
                                                        "px-3 py-3 text-right font-semibold " +
                                                        (
                                                            qty > 0
                                                                ? "text-green-600"
                                                                : qty < 0
                                                                    ? "text-red-600"
                                                                    : ""
                                                        )
                                                    }
                                                >
                                                    {qty}
                                                </td>

                                                <td className="px-3 py-3 text-right font-bold">
                                                    {newStock}
                                                </td>

                                                <td className="px-3 py-3 text-right">
                                                    {item.CostPrice ?? 0}
                                                </td>

                                                <td className="px-3 py-3 text-right">
                                                    {item.SellingPrice ?? 0}
                                                </td>

                                            </tr>
                                        );

                                    })}

                                </tbody>

                            </table>

                        </div>

                    </div>

                    <div className="flex justify-end px-6 py-4 border-t bg-gray-50">

                        <button
                            type="button"
                            onClick={closeModal}
                            className="px-5 py-2.5 rounded-lg border bg-white hover:bg-gray-100"
                        >
                            Close
                        </button>

                    </div>

                </div>

            </div>
        );
    };

    // ============================================================
    // MAIN UI
    // ============================================================

    return (
        <div className="min-h-screen bg-gray-100 p-4 md:p-6">

            <div className="max-w-[1600px] mx-auto">

                {/* HEADER */}

                <div className="bg-white rounded-2xl shadow-sm border p-5 mb-5">

                    <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">

                        <div>

                            <h1 className="text-2xl font-bold text-gray-800">
                                Stock Adjustment
                            </h1>

                            <p className="text-gray-500 text-sm mt-1">
                                Review stock counts and approve physical stock adjustments.
                            </p>

                        </div>

                        <button
                            type="button"
                            onClick={handleRefresh}
                            disabled={loading}
                            className="flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg bg-gray-800 text-white hover:bg-gray-900 disabled:opacity-50"
                        >

                            <RefreshCw
                                size={18}
                                className={loading ? "animate-spin" : ""}
                            />

                            Refresh

                        </button>

                    </div>

                </div>

                {/* TABS */}

                <div className="bg-white rounded-2xl shadow-sm border mb-5">

                    <div className="flex border-b">

                        <button
                            type="button"
                            onClick={() => {
                                setActiveTab("pending");
                                setSearch("");
                            }}
                            className={
                                "flex items-center gap-2 px-6 py-4 font-medium border-b-2 " +
                                (
                                    activeTab === "pending"
                                        ? "border-yellow-500 text-yellow-600"
                                        : "border-transparent text-gray-500"
                                )
                            }
                        >

                            <Clock size={18} />

                            Pending Approval

                            <span className="px-2 py-0.5 rounded-full bg-yellow-100 text-yellow-700 text-xs">
                                {pending.length}
                            </span>

                        </button>

                        <button
                            type="button"
                            onClick={() => {
                                setActiveTab("approved");
                                setSearch("");
                            }}
                            className={
                                "flex items-center gap-2 px-6 py-4 font-medium border-b-2 " +
                                (
                                    activeTab === "approved"
                                        ? "border-green-500 text-green-600"
                                        : "border-transparent text-gray-500"
                                )
                            }
                        >

                            <CheckCircle size={18} />

                            Approved

                            <span className="px-2 py-0.5 rounded-full bg-green-100 text-green-700 text-xs">
                                {approved.length}
                            </span>

                        </button>

                    </div>

                    {/* SEARCH */}

                    <div className="p-4">

                        <div className="relative">

                            <Search
                                size={19}
                                className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"
                            />

                            <input
                                type="text"
                                value={search}
                                onChange={(e) =>
                                    setSearch(e.target.value)
                                }
                                placeholder={
                                    activeTab === "pending"
                                        ? "Search session number, username, status..."
                                        : "Search document number, adjustment ID..."
                                }
                                className="w-full pl-10 pr-4 py-2.5 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                            />

                        </div>

                    </div>

                </div>

                {/* ERROR */}

                {error && (

                    <div className="mb-5 p-4 rounded-xl bg-red-50 border border-red-200 text-red-700 flex items-center gap-3">

                        <AlertTriangle size={20} />

                        <span>{error}</span>

                    </div>

                )}

                {/* TABLE */}

                <div className="bg-white rounded-2xl shadow-sm border overflow-hidden">

                    <div className="overflow-x-auto">

                        <table className="w-full text-sm">

                            <thead className="bg-gray-50">

                                {activeTab === "pending" ? (

                                    <tr>

                                        <th className="px-4 py-4 text-left">
                                            #
                                        </th>

                                        <th className="px-4 py-4 text-left">
                                            Session ID
                                        </th>

                                        <th className="px-4 py-4 text-left">
                                            Session No
                                        </th>

                                        <th className="px-4 py-4 text-left">
                                            Username
                                        </th>

                                        <th className="px-4 py-4 text-left">
                                            Location
                                        </th>

                                        <th className="px-4 py-4 text-right">
                                            System qty
                                        </th>

                                        <th className="px-4 py-4 text-right">
                                            Physical qty
                                        </th>

                                            <th className="px-4 py-4 text-right">
                                            Variance
                                        </th>

                                        <th className="px-4 py-4 text-left">
                                            Created
                                        </th>

                                        <th className="px-4 py-4 text-center">
                                            Status
                                        </th>

                                        <th className="px-4 py-4 text-center">
                                            Action
                                        </th>

                                    </tr>

                                ) : (

                                    <tr>

                                        <th className="px-4 py-4 text-left">
                                            #
                                        </th>

                                        <th className="px-4 py-4 text-left">
                                            Adjustment ID
                                        </th>

                                        <th className="px-4 py-4 text-left">
                                            Document No
                                        </th>

                                        <th className="px-4 py-4 text-left">
                                            Username
                                        </th>

                                        <th className="px-4 py-4 text-left">
                                            Location
                                        </th>

                                          <th className="px-4 py-4 text-left">
                                            System Qty
                                        </th>

                                        <th className="px-4 py-4 text-right">
                                            Total Qty
                                        </th>

                                        <th className="px-4 py-4 text-left">
                                            Approved By
                                        </th>

                                        <th className="px-4 py-4 text-left">
                                            Approved Date
                                        </th>

                                        <th className="px-4 py-4 text-center">
                                            Status
                                        </th>

                                        <th className="px-4 py-4 text-center">
                                            Action
                                        </th>

                                    </tr>

                                )}

                            </thead>

                            <tbody>

                                {loading ? (

                                    <tr>

                                        <td
                                            colSpan="10"
                                            className="py-12 text-center"
                                        >

                                            <RefreshCw
                                                size={28}
                                                className="mx-auto animate-spin text-gray-400"
                                            />

                                            <p className="mt-3 text-gray-500">
                                                Loading...
                                            </p>

                                        </td>

                                    </tr>

                                ) : filteredRows.length === 0 ? (

                                    <tr>

                                        <td
                                            colSpan="10"
                                            className="py-12 text-center text-gray-500"
                                        >

                                            <Package
                                                size={40}
                                                className="mx-auto text-gray-300"
                                            />

                                            <p className="mt-3">
                                                No records found.
                                            </p>

                                        </td>

                                    </tr>

                                ) : (

                                    filteredRows.map((row, index) => (

                                        <tr
                                            key={
                                                activeTab === "pending"
                                                    ? row.StockCountSessionID
                                                    : row.StockAdjustmentID
                                            }
                                            className="border-t hover:bg-gray-50"
                                        >

                                            <td className="px-4 py-4">
                                                {index + 1}
                                            </td>

                                            {activeTab === "pending" ? (

                                                <>
                                                    <td className="px-4 py-4 font-semibold">
                                                        {row.StockCountSessionID}
                                                    </td>

                                                    <td className="px-4 py-4 font-medium">
                                                        {row.SessionNo}
                                                    </td>

                                                    <td className="px-4 py-4">
                                                        {row.Username || "-"}
                                                    </td>

                                                    <td className="px-4 py-4">
                                                        {row.LocationID ?? "-"}
                                                    </td>

                                                    <td className="px-4 py-4 text-right">
                                                        {row.SystemStock ?? 0}
                                                    </td>

                                                       <td className="px-4 py-4 text-right">
                                                        {row.PhysicalTotal ?? 0}
                                                    </td>

                                                    <td className="px-4 py-4 text-right font-semibold">
                                                        {row.Variance ?? 0}
                                                    </td>

                                                    <td className="px-4 py-4">
                                                        {formatDate(row.CreatedDate)}
                                                    </td>

                                                    <td className="px-4 py-4 text-center">

                                                        <span
                                                            className={
                                                                "px-3 py-1 rounded-full text-xs font-semibold " +
                                                                getStatusClass(row.Status)
                                                            }
                                                        >
                                                            {row.Status}
                                                        </span>

                                                    </td>

                                                    <td className="px-4 py-4">

                                                        <div className="flex justify-center gap-2">

                                                            <button
                                                                type="button"
                                                                onClick={() =>
                                                                    viewPending(row)
                                                                }
                                                                className="p-2 rounded-lg bg-blue-50 text-blue-600 hover:bg-blue-100"
                                                                title="View"
                                                            >
                                                                <Eye size={18} />
                                                            </button>

                                                            <button
                                                                type="button"
                                                                onClick={() =>
                                                                    handleApprove(row)
                                                                }
                                                                disabled={approving}
                                                                className="p-2 rounded-lg bg-green-50 text-green-600 hover:bg-green-100 disabled:opacity-50"
                                                                title="Approve"
                                                            >
                                                                <CheckCircle size={18} />
                                                            </button>

                                                        </div>

                                                    </td>
                                                </>

                                            ) : (

                                                <>
                                                    <td className="px-4 py-4 font-semibold">
                                                        {row.StockAdjustmentID}
                                                    </td>

                                                    <td className="px-4 py-4 font-medium">
                                                        {row.DocumentNo}
                                                    </td>

                                                    <td className="px-4 py-4">
                                                        {row.Username || "-"}
                                                    </td>

                                                    <td className="px-4 py-4">
                                                        {row.LocationID ?? "-"}
                                                    </td>

                                                    <td className="px-4 py-4 text-right font-semibold">
                                                        {row.TotalQty ?? 0}
                                                    </td>

                                                    <td className="px-4 py-4">
                                                        {row.ApprovedBy || "-"}
                                                    </td>

                                                    <td className="px-4 py-4">
                                                        {formatDate(row.ApprovedDate)}
                                                    </td>

                                                    <td className="px-4 py-4 text-center">

                                                        <span
                                                            className={
                                                                "px-3 py-1 rounded-full text-xs font-semibold " +
                                                                getStatusClass(row.Status)
                                                            }
                                                        >
                                                            {row.Status}
                                                        </span>

                                                    </td>

                                                    <td className="px-4 py-4 text-center">

                                                        <button
                                                            type="button"
                                                            onClick={() =>
                                                                viewApproved(row)
                                                            }
                                                            className="p-2 rounded-lg bg-blue-50 text-blue-600 hover:bg-blue-100"
                                                            title="View"
                                                        >
                                                            <Eye size={18} />
                                                        </button>

                                                    </td>
                                                </>
                                            )}

                                        </tr>

                                    ))

                                )}

                            </tbody>

                        </table>

                    </div>

                </div>

            </div>

            {/* MODALS */}

            {showModal && selected?.type === "pending" &&
                renderPendingModal()
            }

            {showModal && selected?.type === "approved" &&
                renderApprovedModal()
            }

        </div>
    );
}

// ============================================================
// SUMMARY CARD
// ============================================================

function SummaryCard({
    label,
    value
}) {

    return (
        <div className="bg-white border rounded-xl p-3">

            <div className="text-xs text-gray-500">
                {label}
            </div>

            <div className="font-bold text-gray-800 mt-1">
                {value ?? "-"}
            </div>

        </div>
    );
}

export default StockAdjustment;