import React, { useEffect, useMemo, useState } from "react";

const API = "http://localhost:5000/api";

const emptyForm = {
  CheckBookID: null,
  CashAccountID: "",
  BookName: "",
  Prefix: "",
  StartNumber: "",
  EndNumber: "",
  IssueDate: "",
  Notes: "",
  Status: "Active",
};

const normalizeDate = (value) => {
  if (!value) return "";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return "";

  return date.toISOString().split("T")[0];
};

const formatDate = (value) => {
  if (!value) return "-";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return "-";

  return date.toLocaleDateString();
};

const getStatusClass = (status) => {
  const value = String(status || "").toLowerCase();

  if (value === "active") {
    return "bg-green-100 text-green-700";
  }

  if (value === "inactive") {
    return "bg-gray-100 text-gray-600";
  }

  if (value === "closed") {
    return "bg-red-100 text-red-700";
  }

  return "bg-yellow-100 text-yellow-700";
};

const getErrorMessage = async (response) => {
  try {
    const data = await response.json();

    return (
      data?.message ||
      data?.error ||
      `Request failed with status ${response.status}`
    );
  } catch {
    return `Request failed with status ${response.status}`;
  }
};

const normalizeAccountsResponse = (data) => {
  if (Array.isArray(data)) {
    return data;
  }

  if (Array.isArray(data?.accounts)) {
    return data.accounts;
  }

  if (Array.isArray(data?.data)) {
    return data.data;
  }

  return [];
};

const normalizeCheckBooksResponse = (data) => {
  if (Array.isArray(data)) {
    return data;
  }

  if (Array.isArray(data?.checkbooks)) {
    return data.checkbooks;
  }

  if (Array.isArray(data?.checkBooks)) {
    return data.checkBooks;
  }

  if (Array.isArray(data?.data)) {
    return data.data;
  }

  return [];
};

export default function CheckBooks() {
  const [checkBooks, setCheckBooks] = useState([]);
  const [accounts, setAccounts] = useState([]);

  const [loadingBooks, setLoadingBooks] = useState(true);
  const [loadingAccounts, setLoadingAccounts] = useState(true);

  const [booksError, setBooksError] = useState("");
  const [accountsError, setAccountsError] = useState("");

  const [showModal, setShowModal] = useState(false);
  const [form, setForm] = useState(emptyForm);

  const [saving, setSaving] = useState(false);
  const [deletingId, setDeletingId] = useState(null);
  const [updatingStatusId, setUpdatingStatusId] = useState(null);

  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");

  const [message, setMessage] = useState({
    type: "",
    text: "",
  });

  // ------------------------------------------------------------
  // LOAD CHECKBOOKS
  // ------------------------------------------------------------

  const loadCheckBooks = async () => {
    setLoadingBooks(true);
    setBooksError("");

    try {
      const response = await fetch(`${API}/checkbooks`);

      if (!response.ok) {
        throw new Error(await getErrorMessage(response));
      }

      const data = await response.json();

      console.log("CHECKBOOKS API RESPONSE:", data);

      const books = normalizeCheckBooksResponse(data);

      setCheckBooks(books);
    } catch (error) {
      console.error("LOAD CHECKBOOKS ERROR:", error);

      setBooksError(error.message || "Failed to load checkbooks");
      setCheckBooks([]);
    } finally {
      setLoadingBooks(false);
    }
  };

  // ------------------------------------------------------------
  // LOAD ACCOUNTS
  // ------------------------------------------------------------

  const loadAccounts = async () => {
    setLoadingAccounts(true);
    setAccountsError("");

    try {
      /*
       * Your backend returns:
       *
       * {
       *   success: true,
       *   accounts: [...]
       * }
       *
       * Therefore we MUST use data.accounts.
       */
      const response = await fetch(`${API}/accounts?type=all`);

      if (!response.ok) {
        throw new Error(await getErrorMessage(response));
      }

      const data = await response.json();

      console.log("ACCOUNTS API RESPONSE:", data);

      const loadedAccounts = normalizeAccountsResponse(data);

      console.log("NORMALIZED ACCOUNTS:", loadedAccounts);

      setAccounts(loadedAccounts);

      if (loadedAccounts.length === 0) {
        setAccountsError("No accounts were returned from the server.");
      }
    } catch (error) {
      console.error("LOAD ACCOUNTS ERROR:", error);

      setAccountsError(error.message || "Failed to load accounts");
      setAccounts([]);
    } finally {
      setLoadingAccounts(false);
    }
  };

  // ------------------------------------------------------------
  // INITIAL LOAD
  // ------------------------------------------------------------

  useEffect(() => {
    loadCheckBooks();
    loadAccounts();
  }, []);

  // ------------------------------------------------------------
  // MESSAGE
  // ------------------------------------------------------------

  const showMessage = (type, text) => {
    setMessage({
      type,
      text,
    });

    setTimeout(() => {
      setMessage({
        type: "",
        text: "",
      });
    }, 4000);
  };

  // ------------------------------------------------------------
  // FORM HANDLING
  // ------------------------------------------------------------

  const handleChange = (event) => {
    const { name, value } = event.target;

    setForm((previous) => ({
      ...previous,
      [name]: value,
    }));
  };

  const openAddModal = () => {
    setForm(emptyForm);
    setShowModal(true);
    setMessage({
      type: "",
      text: "",
    });
  };

  const openEditModal = (book) => {
    setForm({
      CheckBookID:
        book.CheckBookID ??
        book.checkBookID ??
        book.id ??
        null,

      CashAccountID:
        book.CashAccountID ??
        book.cashAccountID ??
        book.AccountID ??
        book.accountID ??
        "",

      BookName:
        book.BookName ??
        book.bookName ??
        "",

      Prefix:
        book.Prefix ??
        book.prefix ??
        "",

      StartNumber:
        book.StartNumber ??
        book.startNumber ??
        "",

      EndNumber:
        book.EndNumber ??
        book.endNumber ??
        "",

      IssueDate: normalizeDate(
        book.IssueDate ??
          book.issueDate
      ),

      Notes:
        book.Notes ??
        book.notes ??
        "",

      Status:
        book.Status ??
        book.status ??
        "Active",
    });

    setShowModal(true);
  };

  const closeModal = () => {
    if (saving) return;

    setShowModal(false);
    setForm(emptyForm);
  };

  // ------------------------------------------------------------
  // SAVE
  // ------------------------------------------------------------

  const handleSubmit = async (event) => {
    event.preventDefault();

    if (!form.CashAccountID) {
      showMessage("error", "Please select a cash/bank account.");
      return;
    }

    if (!form.BookName.trim()) {
      showMessage("error", "Please enter a checkbook name.");
      return;
    }

    if (
      form.StartNumber === "" ||
      form.StartNumber === null ||
      form.EndNumber === "" ||
      form.EndNumber === null
    ) {
      showMessage("error", "Please enter the check number range.");
      return;
    }

    const startNumber = Number(form.StartNumber);
    const endNumber = Number(form.EndNumber);

    if (!Number.isFinite(startNumber) || !Number.isFinite(endNumber)) {
      showMessage("error", "Start and end numbers must be valid numbers.");
      return;
    }

    if (endNumber < startNumber) {
      showMessage(
        "error",
        "End number cannot be less than start number."
      );
      return;
    }

    setSaving(true);

    try {
      const username =
        localStorage.getItem("username") ||
        localStorage.getItem("Username") ||
        "ADMIN";

      const payload = {
        cashAccountID: Number(form.CashAccountID),
        bookName: form.BookName.trim(),
        prefix: form.Prefix.trim(),
        startNumber,
        endNumber,
        issueDate: form.IssueDate || null,
        notes: form.Notes.trim(),
        status: form.Status || "Active",
        createdBy: username,
      };

      console.log("CHECKBOOK SAVE PAYLOAD:", payload);

      let response;

      if (form.CheckBookID) {
        response = await fetch(
          `${API}/checkbooks/${form.CheckBookID}`,
          {
            method: "PUT",
            headers: {
              "Content-Type": "application/json",
            },
            body: JSON.stringify(payload),
          }
        );
      } else {
        response = await fetch(`${API}/checkbooks`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify(payload),
        });
      }

      if (!response.ok) {
        throw new Error(await getErrorMessage(response));
      }

      const data = await response.json();

      console.log("CHECKBOOK SAVE RESPONSE:", data);

      showMessage(
        "success",
        form.CheckBookID
          ? "Checkbook updated successfully."
          : "Checkbook created successfully."
      );

      setShowModal(false);
      setForm(emptyForm);

      await loadCheckBooks();
    } catch (error) {
      console.error("SAVE CHECKBOOK ERROR:", error);

      showMessage(
        "error",
        error.message || "Failed to save checkbook."
      );
    } finally {
      setSaving(false);
    }
  };

  // ------------------------------------------------------------
  // STATUS
  // ------------------------------------------------------------

  const handleStatusChange = async (book) => {
    const id =
      book.CheckBookID ??
      book.checkBookID ??
      book.id;

    if (!id) return;

    const currentStatus =
      book.Status ??
      book.status ??
      "Active";

    const newStatus =
      String(currentStatus).toLowerCase() === "active"
        ? "Inactive"
        : "Active";

    setUpdatingStatusId(id);

    try {
      const response = await fetch(
        `${API}/checkbooks/${id}/status`,
        {
          method: "PATCH",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            status: newStatus,
          }),
        }
      );

      if (!response.ok) {
        throw new Error(await getErrorMessage(response));
      }

      await response.json();

      showMessage(
        "success",
        `Checkbook ${newStatus.toLowerCase()} successfully.`
      );

      await loadCheckBooks();
    } catch (error) {
      console.error("UPDATE STATUS ERROR:", error);

      showMessage(
        "error",
        error.message || "Failed to update status."
      );
    } finally {
      setUpdatingStatusId(null);
    }
  };

  // ------------------------------------------------------------
  // DELETE
  // ------------------------------------------------------------

  const handleDelete = async (book) => {
    const id =
      book.CheckBookID ??
      book.checkBookID ??
      book.id;

    if (!id) return;

    const bookName =
      book.BookName ??
      book.bookName ??
      "this checkbook";

    const confirmed = window.confirm(
      `Are you sure you want to delete "${bookName}"?`
    );

    if (!confirmed) return;

    setDeletingId(id);

    try {
      const response = await fetch(
        `${API}/checkbooks/${id}`,
        {
          method: "DELETE",
        }
      );

      if (!response.ok) {
        throw new Error(await getErrorMessage(response));
      }

      await response.json();

      showMessage(
        "success",
        "Checkbook deleted successfully."
      );

      await loadCheckBooks();
    } catch (error) {
      console.error("DELETE CHECKBOOK ERROR:", error);

      showMessage(
        "error",
        error.message || "Failed to delete checkbook."
      );
    } finally {
      setDeletingId(null);
    }
  };

  // ------------------------------------------------------------
  // ACCOUNT LOOKUP
  // ------------------------------------------------------------

  const accountMap = useMemo(() => {
    const map = new Map();

    accounts.forEach((account) => {
      const id =
        account.id ??
        account.AccountID ??
        account.accountID;

      if (id !== undefined && id !== null) {
        map.set(String(id), account);
      }
    });

    return map;
  }, [accounts]);

  const getAccountName = (book) => {
    const accountId =
      book.CashAccountID ??
      book.cashAccountID ??
      book.AccountID ??
      book.accountID;

    if (accountId === undefined || accountId === null) {
      return "-";
    }

    const account = accountMap.get(String(accountId));

    if (!account) {
      return `Account #${accountId}`;
    }

    return (
      account.name ??
      account.AccountName ??
      `Account #${accountId}`
    );
  };

  // ------------------------------------------------------------
  // FILTERED CHECKBOOKS
  // ------------------------------------------------------------

  const filteredCheckBooks = useMemo(() => {
    const searchValue = search.trim().toLowerCase();

    return checkBooks.filter((book) => {
      const bookName =
        book.BookName ??
        book.bookName ??
        "";

      const prefix =
        book.Prefix ??
        book.prefix ??
        "";

      const accountName = getAccountName(book);

      const status =
        book.Status ??
        book.status ??
        "";

      const matchesSearch =
        !searchValue ||
        String(bookName)
          .toLowerCase()
          .includes(searchValue) ||
        String(prefix)
          .toLowerCase()
          .includes(searchValue) ||
        String(accountName)
          .toLowerCase()
          .includes(searchValue);

      const matchesStatus =
        statusFilter === "all" ||
        String(status).toLowerCase() ===
          statusFilter.toLowerCase();

      return matchesSearch && matchesStatus;
    });
  }, [
    checkBooks,
    search,
    statusFilter,
    accountMap,
  ]);

  // ------------------------------------------------------------
  // FORM TOTAL
  // ------------------------------------------------------------

  const formTotalChecks = useMemo(() => {
    const start = Number(form.StartNumber);
    const end = Number(form.EndNumber);

    if (
      !Number.isFinite(start) ||
      !Number.isFinite(end) ||
      end < start
    ) {
      return 0;
    }

    return end - start + 1;
  }, [form.StartNumber, form.EndNumber]);

  // ------------------------------------------------------------
  // BOOK VALUES
  // ------------------------------------------------------------

  const getBookId = (book) =>
    book.CheckBookID ??
    book.checkBookID ??
    book.id;

  const getBookName = (book) =>
    book.BookName ??
    book.bookName ??
    "-";

  const getPrefix = (book) =>
    book.Prefix ??
    book.prefix ??
    "";

  const getStartNumber = (book) =>
    book.StartNumber ??
    book.startNumber ??
    0;

  const getEndNumber = (book) =>
    book.EndNumber ??
    book.endNumber ??
    0;

  const getIssueDate = (book) =>
    book.IssueDate ??
    book.issueDate;

  const getStatus = (book) =>
    book.Status ??
    book.status ??
    "Active";

  const getUsed = (book) => {
    const used =
      book.Used ??
      book.used ??
      book.UsedCount ??
      book.usedCount ??
      0;

    return Number(used) || 0;
  };

  const getNextNumber = (book) => {
    const explicitNext =
      book.NextNumber ??
      book.nextNumber;

    if (
      explicitNext !== undefined &&
      explicitNext !== null &&
      explicitNext !== ""
    ) {
      return explicitNext;
    }

    const start = Number(getStartNumber(book));
    const used = getUsed(book);

    if (!Number.isFinite(start)) {
      return "-";
    }

    return start + used;
  };

  const getTotalChecks = (book) => {
    const explicitTotal =
      book.TotalChecks ??
      book.totalChecks ??
      book.Total ??
      book.total;

    if (
      explicitTotal !== undefined &&
      explicitTotal !== null &&
      explicitTotal !== ""
    ) {
      return Number(explicitTotal) || 0;
    }

    const start = Number(getStartNumber(book));
    const end = Number(getEndNumber(book));

    if (
      !Number.isFinite(start) ||
      !Number.isFinite(end) ||
      end < start
    ) {
      return 0;
    }

    return end - start + 1;
  };

  // ------------------------------------------------------------
  // RENDER
  // ------------------------------------------------------------

  return (
    <div className="min-h-screen bg-gray-50 p-4 md:p-6">
      <div className="mx-auto max-w-7xl">

        {/* HEADER */}
        <div className="mb-6 flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
          <div>
            <h1 className="text-2xl font-bold text-gray-900">
              Check Books
            </h1>

            <p className="mt-1 text-sm text-gray-500">
              Manage checkbooks and check number ranges.
            </p>
          </div>

          <button
            type="button"
            onClick={openAddModal}
            className="inline-flex items-center justify-center rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white shadow-sm transition hover:bg-blue-700"
          >
            <span className="mr-2 text-lg">+</span>
            Add Check Book
          </button>
        </div>

        {/* MESSAGE */}
        {message.text && (
          <div
            className={`mb-5 rounded-lg border px-4 py-3 text-sm ${
              message.type === "success"
                ? "border-green-200 bg-green-50 text-green-700"
                : "border-red-200 bg-red-50 text-red-700"
            }`}
          >
            {message.text}
          </div>
        )}

        {/* ACCOUNTS ERROR */}
        {accountsError && (
          <div className="mb-5 rounded-lg border border-yellow-200 bg-yellow-50 px-4 py-3">
            <div className="font-semibold text-yellow-800">
              Account loading issue
            </div>

            <div className="mt-1 text-sm text-yellow-700">
              {accountsError}
            </div>

            <button
              type="button"
              onClick={loadAccounts}
              className="mt-3 rounded-md bg-yellow-600 px-3 py-1.5 text-xs font-semibold text-white hover:bg-yellow-700"
            >
              Retry Accounts
            </button>
          </div>
        )}

        {/* CHECKBOOK ERROR */}
        {booksError && (
          <div className="mb-5 rounded-lg border border-red-200 bg-red-50 px-4 py-3">
            <div className="font-semibold text-red-800">
              Checkbook loading issue
            </div>

            <div className="mt-1 text-sm text-red-700">
              {booksError}
            </div>

            <button
              type="button"
              onClick={loadCheckBooks}
              className="mt-3 rounded-md bg-red-600 px-3 py-1.5 text-xs font-semibold text-white hover:bg-red-700"
            >
              Retry Checkbooks
            </button>
          </div>
        )}

        {/* FILTERS */}
        <div className="mb-5 rounded-xl border border-gray-200 bg-white p-4 shadow-sm">
          <div className="grid grid-cols-1 gap-3 md:grid-cols-3">

            <div className="md:col-span-2">
              <label className="mb-1 block text-xs font-medium text-gray-600">
                Search
              </label>

              <input
                type="text"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search book name, prefix or account..."
                className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm outline-none transition focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
              />
            </div>

            <div>
              <label className="mb-1 block text-xs font-medium text-gray-600">
                Status
              </label>

              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
              >
                <option value="all">All Statuses</option>
                <option value="Active">Active</option>
                <option value="Inactive">Inactive</option>
                <option value="Closed">Closed</option>
              </select>
            </div>

          </div>
        </div>

        {/* TABLE */}
        <div className="overflow-hidden rounded-xl border border-gray-200 bg-white shadow-sm">
          <div className="overflow-x-auto">
            <table className="min-w-[1050px] w-full">
              <thead className="bg-gray-50">
                <tr className="border-b border-gray-200">
                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wide text-gray-500">
                    Book
                  </th>

                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wide text-gray-500">
                    Account
                  </th>

                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wide text-gray-500">
                    Range
                  </th>

                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wide text-gray-500">
                    Next Number
                  </th>

                  <th className="px-4 py-3 text-right text-xs font-semibold uppercase tracking-wide text-gray-500">
                    Total
                  </th>

                  <th className="px-4 py-3 text-right text-xs font-semibold uppercase tracking-wide text-gray-500">
                    Used
                  </th>

                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wide text-gray-500">
                    Issue Date
                  </th>

                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wide text-gray-500">
                    Status
                  </th>

                  <th className="px-4 py-3 text-right text-xs font-semibold uppercase tracking-wide text-gray-500">
                    Actions
                  </th>
                </tr>
              </thead>

              <tbody className="divide-y divide-gray-100">
                {loadingBooks ? (
                  <tr>
                    <td
                      colSpan="9"
                      className="px-4 py-12 text-center text-sm text-gray-500"
                    >
                      Loading checkbooks...
                    </td>
                  </tr>
                ) : filteredCheckBooks.length === 0 ? (
                  <tr>
                    <td
                      colSpan="9"
                      className="px-4 py-12 text-center"
                    >
                      <div className="text-sm font-medium text-gray-700">
                        No checkbooks found
                      </div>

                      <div className="mt-1 text-xs text-gray-400">
                        Add a checkbook or change your search filters.
                      </div>
                    </td>
                  </tr>
                ) : (
                  filteredCheckBooks.map((book) => {
                    const id = getBookId(book);
                    const status = getStatus(book);
                    const total = getTotalChecks(book);
                    const used = getUsed(book);
                    const nextNumber = getNextNumber(book);

                    return (
                      <tr
                        key={id}
                        className="transition hover:bg-gray-50"
                      >
                        {/* BOOK */}
                        <td className="px-4 py-4">
                          <div className="font-semibold text-gray-900">
                            {getBookName(book)}
                          </div>

                          {getPrefix(book) && (
                            <div className="mt-0.5 text-xs text-gray-500">
                              Prefix: {getPrefix(book)}
                            </div>
                          )}
                        </td>

                        {/* ACCOUNT */}
                        <td className="px-4 py-4">
                          <div className="font-medium text-gray-800">
                            {getAccountName(book)}
                          </div>
                        </td>

                        {/* RANGE */}
                        <td className="px-4 py-4 text-sm text-gray-700">
                          {getPrefix(book)}
                          {getStartNumber(book)}
                          {" - "}
                          {getPrefix(book)}
                          {getEndNumber(book)}
                        </td>

                        {/* NEXT */}
                        <td className="px-4 py-4">
                          <span className="font-semibold text-blue-600">
                            {getPrefix(book)}
                            {nextNumber}
                          </span>
                        </td>

                        {/* TOTAL */}
                        <td className="px-4 py-4 text-right text-sm font-medium text-gray-700">
                          {total}
                        </td>

                        {/* USED */}
                        <td className="px-4 py-4 text-right text-sm text-gray-700">
                          {used}
                        </td>

                        {/* DATE */}
                        <td className="px-4 py-4 text-sm text-gray-600">
                          {formatDate(getIssueDate(book))}
                        </td>

                        {/* STATUS */}
                        <td className="px-4 py-4">
                          <span
                            className={`inline-flex rounded-full px-2.5 py-1 text-xs font-semibold ${getStatusClass(
                              status
                            )}`}
                          >
                            {status}
                          </span>
                        </td>

                        {/* ACTIONS */}
                        <td className="px-4 py-4">
                          <div className="flex items-center justify-end gap-2">

                            <button
                              type="button"
                              onClick={() =>
                                openEditModal(book)
                              }
                              className="rounded-md border border-gray-300 px-2.5 py-1.5 text-xs font-medium text-gray-700 hover:bg-gray-50"
                            >
                              Edit
                            </button>

                            <button
                              type="button"
                              disabled={
                                updatingStatusId === id
                              }
                              onClick={() =>
                                handleStatusChange(book)
                              }
                              className="rounded-md border border-blue-200 px-2.5 py-1.5 text-xs font-medium text-blue-600 hover:bg-blue-50 disabled:cursor-not-allowed disabled:opacity-50"
                            >
                              {updatingStatusId === id
                                ? "..."
                                : String(status).toLowerCase() ===
                                  "active"
                                ? "Deactivate"
                                : "Activate"}
                            </button>

                            <button
                              type="button"
                              disabled={deletingId === id}
                              onClick={() =>
                                handleDelete(book)
                              }
                              className="rounded-md border border-red-200 px-2.5 py-1.5 text-xs font-medium text-red-600 hover:bg-red-50 disabled:cursor-not-allowed disabled:opacity-50"
                            >
                              {deletingId === id
                                ? "..."
                                : "Delete"}
                            </button>

                          </div>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>

          {/* FOOTER */}
          <div className="border-t border-gray-200 bg-gray-50 px-4 py-3">
            <div className="text-xs text-gray-500">
              Showing{" "}
              <span className="font-semibold text-gray-700">
                {filteredCheckBooks.length}
              </span>{" "}
              of{" "}
              <span className="font-semibold text-gray-700">
                {checkBooks.length}
              </span>{" "}
              checkbooks
            </div>
          </div>
        </div>
      </div>

      {/* ======================================================
          MODAL
      ====================================================== */}

      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
          <div className="max-h-[95vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white shadow-2xl">

            {/* MODAL HEADER */}
            <div className="flex items-center justify-between border-b border-gray-200 px-6 py-4">
              <div>
                <h2 className="text-lg font-bold text-gray-900">
                  {form.CheckBookID
                    ? "Edit Check Book"
                    : "Add Check Book"}
                </h2>

                <p className="mt-0.5 text-xs text-gray-500">
                  Configure the account and check number range.
                </p>
              </div>

              <button
                type="button"
                onClick={closeModal}
                disabled={saving}
                className="rounded-lg p-2 text-gray-400 hover:bg-gray-100 hover:text-gray-600 disabled:opacity-50"
              >
                ✕
              </button>
            </div>

            {/* FORM */}
            <form onSubmit={handleSubmit}>
              <div className="space-y-5 px-6 py-5">

                {/* ACCOUNT */}
                <div>
                  <label className="mb-1.5 block text-sm font-semibold text-gray-700">
                    Cash / Bank Account
                    <span className="ml-1 text-red-500">*</span>
                  </label>

                  <select
                    name="CashAccountID"
                    value={form.CashAccountID}
                    onChange={handleChange}
                    disabled={
                      Boolean(form.CheckBookID) ||
                      loadingAccounts
                    }
                    className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2.5 text-sm outline-none transition focus:border-blue-500 focus:ring-2 focus:ring-blue-100 disabled:cursor-not-allowed disabled:bg-gray-100"
                  >
                    <option value="">
                      {loadingAccounts
                        ? "Loading accounts..."
                        : accounts.length === 0
                        ? "No accounts available"
                        : "Select account"}
                    </option>

                    {accounts.map((account) => {
                      const accountId =
                        account.id ??
                        account.AccountID ??
                        account.accountID;

                      const accountName =
                        account.name ??
                        account.AccountName ??
                        "Unnamed Account";

                      const accountType =
                        account.type ??
                        account.AccountType ??
                        "";

                      const detailType =
                        account.detailType ??
                        account.DetailType ??
                        "";

                      const accountStatus =
                        account.status ??
                        account.Status ??
                        "";

                      return (
                        <option
                          key={accountId}
                          value={accountId}
                        >
                          {accountName}
                          {accountType
                            ? ` — ${accountType}`
                            : ""}
                          {detailType
                            ? ` / ${detailType}`
                            : ""}
                          {String(accountStatus).toLowerCase() ===
                            "inactive"
                            ? " — Inactive"
                            : ""}
                        </option>
                      );
                    })}
                  </select>

                  {accounts.length > 0 && (
                    <p className="mt-1.5 text-xs text-gray-500">
                      {accounts.length} account
                      {accounts.length !== 1 ? "s" : ""} available.
                    </p>
                  )}

                  {accounts.length === 0 &&
                    !loadingAccounts && (
                      <p className="mt-1.5 text-xs text-red-500">
                        No accounts were loaded. Check the Accounts API
                        and browser console.
                      </p>
                    )}
                </div>

                {/* BOOK NAME */}
                <div>
                  <label className="mb-1.5 block text-sm font-semibold text-gray-700">
                    Book Name
                    <span className="ml-1 text-red-500">*</span>
                  </label>

                  <input
                    type="text"
                    name="BookName"
                    value={form.BookName}
                    onChange={handleChange}
                    placeholder="e.g. Main Current Account"
                    className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                  />
                </div>

                {/* PREFIX */}
                <div>
                  <label className="mb-1.5 block text-sm font-semibold text-gray-700">
                    Prefix
                  </label>

                  <input
                    type="text"
                    name="Prefix"
                    value={form.Prefix}
                    onChange={handleChange}
                    placeholder="e.g. CHQ-"
                    maxLength={20}
                    className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                  />

                  <p className="mt-1 text-xs text-gray-400">
                    Optional prefix printed before the check number.
                  </p>
                </div>

                {/* RANGE */}
                <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">

                  <div>
                    <label className="mb-1.5 block text-sm font-semibold text-gray-700">
                      Start Number
                      <span className="ml-1 text-red-500">*</span>
                    </label>

                    <input
                      type="number"
                      name="StartNumber"
                      value={form.StartNumber}
                      onChange={handleChange}
                      disabled={Boolean(form.CheckBookID)}
                      min="0"
                      placeholder="1"
                      className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 disabled:cursor-not-allowed disabled:bg-gray-100"
                    />
                  </div>

                  <div>
                    <label className="mb-1.5 block text-sm font-semibold text-gray-700">
                      End Number
                      <span className="ml-1 text-red-500">*</span>
                    </label>

                    <input
                      type="number"
                      name="EndNumber"
                      value={form.EndNumber}
                      onChange={handleChange}
                      disabled={Boolean(form.CheckBookID)}
                      min="0"
                      placeholder="100"
                      className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 disabled:cursor-not-allowed disabled:bg-gray-100"
                    />
                  </div>

                </div>

                {/* TOTAL */}
                {form.StartNumber !== "" &&
                  form.EndNumber !== "" && (
                    <div className="rounded-lg border border-blue-100 bg-blue-50 px-4 py-3">
                      <div className="flex items-center justify-between">
                        <span className="text-sm font-medium text-blue-700">
                          Total Checks
                        </span>

                        <span className="text-lg font-bold text-blue-800">
                          {formTotalChecks}
                        </span>
                      </div>
                    </div>
                  )}

                {/* ISSUE DATE */}
                <div>
                  <label className="mb-1.5 block text-sm font-semibold text-gray-700">
                    Issue Date
                  </label>

                  <input
                    type="date"
                    name="IssueDate"
                    value={form.IssueDate}
                    onChange={handleChange}
                    className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                  />
                </div>

                {/* STATUS */}
                <div>
                  <label className="mb-1.5 block text-sm font-semibold text-gray-700">
                    Status
                  </label>

                  <select
                    name="Status"
                    value={form.Status}
                    onChange={handleChange}
                    className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                  >
                    <option value="Active">
                      Active
                    </option>

                    <option value="Inactive">
                      Inactive
                    </option>

                    <option value="Closed">
                      Closed
                    </option>
                  </select>
                </div>

                {/* NOTES */}
                <div>
                  <label className="mb-1.5 block text-sm font-semibold text-gray-700">
                    Notes
                  </label>

                  <textarea
                    name="Notes"
                    value={form.Notes}
                    onChange={handleChange}
                    rows={3}
                    placeholder="Optional notes..."
                    className="w-full resize-none rounded-lg border border-gray-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                  />
                </div>

              </div>

              {/* MODAL FOOTER */}
              <div className="flex items-center justify-end gap-3 border-t border-gray-200 bg-gray-50 px-6 py-4">

                <button
                  type="button"
                  onClick={closeModal}
                  disabled={saving}
                  className="rounded-lg border border-gray-300 bg-white px-4 py-2.5 text-sm font-semibold text-gray-700 hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-50"
                >
                  Cancel
                </button>

                <button
                  type="submit"
                  disabled={saving}
                  className="rounded-lg bg-blue-600 px-5 py-2.5 text-sm font-semibold text-white shadow-sm hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
                >
                  {saving
                    ? "Saving..."
                    : form.CheckBookID
                    ? "Update Check Book"
                    : "Save Check Book"}
                </button>

              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}