// Sidebar.js
import React, { useContext, useEffect, useMemo, useState } from "react";
import { Menu, X, Trash2, Lock } from "lucide-react";
import { useNavigate } from "react-router-dom";
import { AuthContext } from "./SERVER/AuthContext.js";

// ← PERM
import { usePermissions } from "../hooks/usePermissions.jsx";

const PRODUCT_MODULE = "Product";  // ← PERM
const SALES_MODULE   = "Sale";     // ← PERM

const Dashboard = () => {
  const navigate = useNavigate();
  const { user } = useContext(AuthContext);

  // =====================================================
  // PERMISSIONS                                            // ← PERM
  // =====================================================
  const {
    can,
    canField,
    loading: permissionsLoading,
  } = usePermissions();                                     // ← PERM

  const canViewProducts     = can(PRODUCT_MODULE, "View");            // ← PERM
  const canSell             = can(SALES_MODULE, "Add");               // ← PERM
  const canViewSellingPrice = canField(PRODUCT_MODULE, "SellingPrice"); // ← PERM

  // =====================================================
  // STATE
  // =====================================================
  const [isOpen, setIsOpen] = useState(true);
  const [search, setSearch] = useState("");
  const [selectedCategory, setSelectedCategory] = useState("All");
  const [results, setResults] = useState([]);
  const [pen, setPen] = useState([]);
  const [oo, isoo] = useState(false);
  const [cartItemCount, setCartItemCount] = useState(0);
  const [sections, setSections] = useState([]);

  // =====================================================
  // LOAD PRODUCTS
  // =====================================================
  const loadProducts = async (location) => {
    try {
      const res = await fetch(
        `http://localhost:5000/PRODUCTS?location=${location}`
      );
      const data = await res.json();
      setPen(Array.isArray(data) ? data : data.products || []);
    } catch (err) {
      console.error("LOAD PRODUCTS ERROR:", err);
      setPen([]);
    }
  };

  // =====================================================
  // LOAD DEPARTMENTS (used as the "Supplier" filter)
  // ---------------------------------------------------------
  // 🔧 FIX: moved out of handleSelect so useEffect can reach it.
  // =====================================================
  const loadDepartments = async () => {
    try {
      const res = await fetch(`http://localhost:5000/Department`);
      const data = await res.json();
      setResults(Array.isArray(data) ? data : data.departments || []);
    } catch (err) {
      console.error("LOAD DEPARTMENTS ERROR:", err);
      setResults([]);
    }
  };

  // =====================================================
  // ADD SECTION TO CART PANE
  // =====================================================
  const handleSelect = (product) => {
    // ← PERM
    if (!canSell) {
      alert("You do not have permission to add items to a sale.");
      return;
    }

    // 🔧 FIX: added qty: 1 so the row renders a real number
    setSections((prev) => {
      const lastSection = prev[prev.length - 1];

      if (!lastSection || lastSection.item) {
        return [
          ...prev,
          { id: prev.length + 1, item: product, qty: 1 },
        ];
      }

      const updated = [...prev];
      updated[updated.length - 1] = {
        ...lastSection,
        item: product,
        qty: 1,
      };
      return updated;
    });                                                     // 🔧 FIX: added `;`
  };                                                        // 🔧 FIX: moved closer here

  const handleDelete = (id) => {
    if (!canSell) return;                                   // ← PERM
    setSections((prev) => prev.filter((section) => section.id !== id));
  };

  // =====================================================
  // PAGE LOAD
  // =====================================================
  useEffect(() => {
    if (permissionsLoading) return;                         // ← PERM
    if (!canViewProducts) return;                           // ← PERM

    if (user?.location) {
      loadProducts(user.location);
      loadDepartments();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user, canViewProducts, permissionsLoading]);          // ← PERM

  // =====================================================
  // CART COUNT — driven by sections, not manual state      // 🔧 FIX
  // =====================================================
  useEffect(() => {
    const count = sections.reduce(
      (total, s) => total + Number(s.qty || 0),
      0
    );
    setCartItemCount(count);
  }, [sections]);

  // =====================================================
  // FILTER
  // =====================================================
  const filteredProducts = useMemo(() => {
    return (pen ?? []).filter((product) => {
      const matchesSearch = (product?.ProductName ?? "")
        .toLowerCase()
        .includes((search ?? "").toLowerCase());

      const matchesCategory =
        selectedCategory === "All" ||
        product?.Department === selectedCategory;

      return matchesSearch && matchesCategory;
    });
  }, [pen, search, selectedCategory]);

  // =====================================================
  // HELPERS                                                // ← PERM
  // =====================================================
  const priceOrMask = (value) =>
    canViewSellingPrice ? value : "—";                      // ← PERM

  const handleLogout = () => {                              // 🔧 FIX: was missing
    localStorage.removeItem("user");
    localStorage.removeItem("token");
    navigate("/");
  };

  // =====================================================
  // ACCESS GATE                                            // ← PERM
  // =====================================================
  if (permissionsLoading) {
    return (
      <div className="min-h-screen bg-gray-100 flex items-center justify-center text-gray-500">
        Checking permissions…
      </div>
    );
  }

  if (!canViewProducts) {
    return (
      <div className="min-h-screen bg-gray-100 flex items-center justify-center p-6">
        <div className="max-w-xl w-full rounded-xl border border-red-200 bg-red-50 p-8 text-center">
          <Lock className="mx-auto text-red-500 mb-3" size={32} />
          <h2 className="text-lg font-bold text-red-700">Access Denied</h2>
          <p className="text-sm text-red-600 mt-2">
            You do not have permission to view the product catalog.
          </p>
          <button
            onClick={handleLogout}
            className="mt-6 rounded-lg bg-red-600 px-5 py-2 text-sm font-semibold text-white hover:bg-red-700"
          >
            Log out
          </button>
        </div>
      </div>
    );
  }

  // =====================================================
  // UI
  // =====================================================
  return (
    <div className="flex">
      {/* Sidebar */}
      <div
        className={`bg-slate-800 text-white h-screen p-5 pt-8 relative duration-300 ${
          isOpen ? "w-64" : "w-20"
        }`}
      >
        <button
          className="absolute -right-3 top-9 bg-white text-black rounded-full p-1"
          onClick={() => setIsOpen(!isOpen)}
        >
          {isOpen ? <X size={18} /> : <Menu size={18} />}
        </button>

        <h1 className={`text-2xl font-bold mb-6 ${!isOpen && "hidden"}`}>
          MPOS
        </h1>

        <ul className="space-y-4">
          <li
            className="hover:bg-slate-700 p-2 rounded cursor-pointer"
            onClick={() => navigate("/home")}
          >
            Home
          </li>
          <li
            className="hover:bg-slate-700 p-2 rounded cursor-pointer"
            onClick={() => navigate("/Dashboard")}
          >
            Catelog
          </li>
          <li
            className="hover:bg-slate-700 p-2 rounded cursor-pointer"
            onClick={() => navigate("/Settingss")}
          >
            Settings
          </li>
          <li
            className="hover:bg-slate-700 p-2 rounded cursor-pointer"
            onClick={handleLogout}                          /* 🔧 FIX */
          >
            Logout
          </li>
        </ul>
      </div>

      {/* Main content */}
      <div className="flex-1 min-h-screen bg-gray-100">
        {/* Header */}
        <header className="bg-indigo-600 text-white shadow-md">
          <div className="max-w-7xl mx-auto px-6 py-4 flex justify-between items-center">
            <h1 className="text-2xl font-bold">Product Catalogue</h1>

            <input
              type="text"
              placeholder="Search products..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-72 px-4 py-2 rounded-lg text-black outline-none"
            />

            <button
              type="button"
              className="relative p-2 text-white hover:bg-indigo-500 rounded-full transition"
              onClick={() => isoo(true)}
              aria-label="Shopping Cart"
            >
              <svg
                xmlns="http://www.w3.org/2000/svg"
                fill="none"
                viewBox="0 0 24 24"
                strokeWidth="2"
                stroke="currentColor"
                className="w-6 h-6"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-1 5h12m-9 0a1 1 0 100 2 1 1 0 000-2zm8 0a1 1 0 100 2 1 1 0 000-2"
                />
              </svg>
              {cartItemCount > 0 && (
                <span className="absolute top-0 right-0 transform translate-x-1/2 -translate-y-1/3 min-w-5 h-5 bg-red-500 text-white text-xs font-bold rounded-full flex items-center justify-center px-1">
                  {cartItemCount}
                </span>
              )}
            </button>
          </div>
        </header>

        {/* ← PERM: read-only banner */}
        {!canSell && (
          <div className="max-w-7xl mx-auto mt-4 flex items-center gap-2 rounded-lg border border-amber-200 bg-amber-50 px-4 py-2 text-sm text-amber-700">
            <Lock size={14} /> Read-only mode — you cannot add items to a sale.
          </div>
        )}

        {/* Main content */}
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row gap-6 p-6">
          {/* Sidebar — Suppliers */}
          <aside className="w-full md:w-64 bg-white rounded-xl shadow-md p-5">
            <h2 className="text-lg font-semibold mb-4">Supplier</h2>
            <div className="space-y-2">
              <button
                onClick={() => setSelectedCategory("All")}
                className={`w-full text-left px-4 py-2 rounded-lg transition ${
                  selectedCategory === "All"
                    ? "bg-indigo-600 text-white"
                    : "bg-gray-100 hover:bg-gray-200"
                }`}
              >
                All
              </button>

              {results.map((supplier) => (
                <button
                  key={supplier.DepartmentCode}
                  onClick={() => setSelectedCategory(supplier.DepartmentName)}
                  className={`w-full text-left px-4 py-2 rounded-lg transition ${
                    selectedCategory === supplier.DepartmentName
                      ? "bg-indigo-600 text-white"
                      : "bg-gray-100 hover:bg-gray-200"
                  }`}
                >
                  {supplier.DepartmentName}
                </button>
              ))}
            </div>
          </aside>

          {/* Products */}
          <main className="flex-1">
            <p className="mb-4 text-gray-600">
              Showing {pen.length} products
            </p>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredProducts.map((product) => (
                <div
                  key={product.ProductCode || product.id}
                  className="bg-white rounded-xl shadow-md overflow-hidden hover:shadow-xl transition"
                >
                  <img
                    src={product.ProductImage || "https://via.placeholder.com/400x300?text=No+Image"}
                    alt={product.ProductName}
                    className="w-full h-56 object-cover"
                  />

                  <div className="p-4">
                    <span className="text-xs bg-indigo-100 text-indigo-600 px-2 py-1 rounded">
                      {product.Department}
                    </span>

                    <h3 className="mt-3 text-lg font-semibold">
                      {product.ProductName}
                    </h3>

                    <div className="flex justify-between items-center mt-4">
                      {/* ← PERM: masked price */}
                      <span className="text-xl font-bold text-indigo-600">
                        {priceOrMask(product.SellingPrice)}
                      </span>

                      {/* ← PERM: gated Add Cart */}
                      {canSell ? (
                        <button
                          className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg"
                          onClick={() => {
                            handleSelect(product);
                          }}
                        >
                          Add Cart
                        </button>
                      ) : (
                        <span className="rounded-lg bg-slate-100 px-4 py-2 text-xs font-semibold text-slate-500">
                          Selling disabled
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>

            {filteredProducts.length === 0 && (
              <div className="bg-white p-10 rounded-xl shadow text-center">
                <p className="text-gray-500">
                  No products found matching your search.
                </p>
              </div>
            )}
          </main>

          {/* Cart Modal */}
          {oo && (
            <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50 z-50">
              <div className="bg-white rounded-lg shadow-lg p-6 w-[32rem] max-w-full relative">
                <button
                  onClick={() => isoo(false)}
                  className="absolute top-2 right-2 text-gray-500 hover:text-black"
                >
                  ✕
                </button>

                <h2 className="text-lg font-bold mb-4">Cart</h2>

                <ul className="divide-y">
                  <li className="grid grid-cols-[2fr_1fr_1fr_1fr_0.5fr] gap-2 px-2 py-2 bg-gray-100 border-b text-xs font-semibold text-gray-600">
                    <span>ProductCode</span>
                    <span>Product</span>
                    <span>Discount</span>
                    <span>Qty</span>
                    <span>Price</span>
                  </li>
                </ul>

                {sections.length === 0 ? (
                  <p className="text-gray-400 text-center mt-10">
                    No items added
                  </p>
                ) : (
                  <ul className="divide-y">
                    {sections.map((section) => (
                      <li
                        key={section.id}
                        className="grid grid-cols-[2fr_1fr_1fr_1fr_0.5fr] gap-2 items-center py-3 px-2 hover:bg-gray-100"
                      >
                        <span className="text-sm font-medium truncate">
                          {section.item.ProductCode}
                        </span>
                        <span className="text-sm font-medium truncate">
                          {section.item.ProductName}
                        </span>
                        <span className="text-sm font-medium">
                          {section.item.FixedDiscountPercentage ?? 0}%
                        </span>
                        {/* 🔧 FIX: use section.qty, not item.qty */}
                        <span className="text-sm font-medium">
                          {section.qty}
                        </span>
                        <span className="text-sm font-medium flex items-center justify-between">
                          {/* ← PERM: masked price */}
                          <span>{priceOrMask(section.item.SellingPrice)}</span>

                          {canSell && (
                            <Trash2
                              size={16}
                              className="text-red-500 cursor-pointer hover:text-red-700"
                              onClick={() => handleDelete(section.id)}
                            />
                          )}
                        </span>
                      </li>
                    ))}
                  </ul>
                )}

                <div className="mt-6 flex justify-end gap-2">
                  <button
                    onClick={() => isoo(false)}
                    className="px-4 py-2 bg-gray-200 text-gray-700 rounded hover:bg-gray-300"
                  >
                    Close
                  </button>

                  {/* ← PERM: Apply button only when user can sell */}
                  {canSell && (
                    <button
                      onClick={() => isoo(false)}
                      className="px-4 py-2 bg-indigo-600 text-white rounded hover:bg-indigo-700"
                    >
                      Apply
                    </button>
                  )}
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;