import { useContext, useEffect, useState } from "react";
import axios from "axios";
import { AuthContext } from "../pos/SERVER/AuthContext.js";

export default function Salesreport() {
  const { user } = useContext(AuthContext);

  const [isOpen, setIsOpen] = useState(false);
  const [locations, setLocations] = useState([]);

  const [selectedLocation, setSelectedLocation] = useState({
    LocationCode: "",
    LocationName: "",
  });

  const [fromdate, setFromDate] = useState("");
  const [todate, setToDate] = useState("");

  const [invoice, setInvoice] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  // Load locations when F12 is pressed
  useEffect(() => {
    const handleKeyDown = (event) => {
      if (event.key === "F12") {
        event.preventDefault();
        setIsOpen(true);
        loadLocations();
      }
    };

    window.addEventListener("keydown", handleKeyDown);

    return () => {
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, []);

  const loadLocations = async () => {
    try {
      const res = await fetch("http://localhost:5000/location");
      const data = await res.json();

      setLocations(data);
    } catch (err) {
      console.error(err);
      setError("Failed to load locations.");
    }
  };

  const searchSalesReport = async (e) => {
    e.preventDefault();

    if (!selectedLocation.LocationID) {
      setError("Please select a location.");
      return;
    }

    if (!fromdate || !todate) {
      setError("Please select From Date and To Date.");
      return;
    }

    try {
      setLoading(true);
      setError("");

      const res = await axios.get(
        "http://localhost:5000/salesreport",
        {
          params: {
            fromdate,
            todate,
            location: selectedLocation.LocationID,
          },
        }
      );

      setInvoice(res.data);
    } catch (err) {
      console.error(err);
      setError("Failed to load sales report.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="w-full mx-auto mt-10 p-4">

      <div className="mb-4">
        {user?.username
          ? `Welcome, ${user.username}`
          : "No user logged in"}
      </div>

      {/* Search Form */}
      <div className="mt-6 p-4 bg-white border border-gray-100 rounded-2xl shadow-sm">

        <form onSubmit={searchSalesReport} className="space-y-4">

          <div className="grid grid-cols-6 gap-4 items-center">

            {/* Location */}
            <h3>Location</h3>

            <input
              type="text"
              name="location"
              placeholder="Location"
              value={selectedLocation.LocationID}
              readOnly
              onClick={() => {
                setIsOpen(true);
                loadLocations();
              }}
              className="w-full border p-2 rounded cursor-pointer"
              required
            />

            {/* From Date */}
            <h3>From Date</h3>

            <input
              type="datetime-local"
              value={fromdate}
              onChange={(e) => setFromDate(e.target.value)}
              className="w-full border p-2 rounded"
              required
            />

            {/* To Date */}
            <h3>To Date</h3>

            <input
              type="datetime-local"
              value={todate}
              onChange={(e) => setToDate(e.target.value)}
              className="w-full border p-2 rounded"
              required
            />

            {/* Search */}
            <button
              type="submit"
              disabled={loading}
              className="w-full bg-indigo-600 text-white py-2 rounded hover:bg-indigo-500 disabled:bg-gray-400"
            >
              {loading ? "Searching..." : "Search"}
            </button>

          </div>

        </form>

        {error && (
          <div className="mt-4 text-red-600">
            {error}
          </div>
        )}

      </div>

      {/* Sales Report Table */}
      <div className="w-full overflow-hidden rounded-lg shadow-lg border border-gray-200 bg-white mt-4">

        <div className="overflow-x-auto">

          <table className="w-full border-collapse text-left text-sm text-gray-700">

            <thead className="bg-gray-50 text-gray-800">
              <tr>
                <th className="px-6 py-4 font-medium">
                  Inv No
                </th>

                <th className="px-6 py-4 font-medium">
                  Product Code
                </th>

                <th className="px-6 py-4 font-medium">
                  Product Name
                </th>

                  <th className="px-6 py-4 font-medium">
                  Quantity
                </th>

                  <th className="px-6 py-4 font-medium">
                  Cost Price
                </th>

                  <th className="px-6 py-4 font-medium">
                  Selling Price
                </th>

                    <th className="px-6 py-4 font-medium">
                  Discount
                </th>

                <th className="px-6 py-4 font-medium">
                  Location
                </th>
              </tr>
            </thead>

            <tbody className="divide-y divide-gray-100 border-t border-gray-100">

              {invoice.length === 0 ? (
                <tr>
                  <td
                    colSpan="4"
                    className="px-6 py-8 text-center text-gray-500"
                  >
                    No sales found.
                  </td>
                </tr>
              ) : (
                invoice.map((row, index) => (
                  <tr
                    key={row.DocumentNo || index}
                    className="hover:bg-gray-50"
                  >

                    <td className="px-6 py-4 font-medium text-gray-900">
                      {row.Receipt}
                    </td>

                    <td className="px-6 py-4">
                      {row.ProductCode}
                    </td>

                    <td className="px-6 py-4">
                      {row.Descrip}
                    </td>

                     <td className="px-6 py-4">
                      {row.Qty}
                    </td>

                     <td className="px-6 py-4">
                      {row.Cost}
                    </td>

                     <td className="px-6 py-4">
                      {row.Price}
                    </td>

                     <td className="px-6 py-4">
                      {row.Price}
                    </td>

                    <td className="px-6 py-4">
                      {row.LocationID}
                    </td>

                  </tr>
                ))
              )}

            </tbody>

          </table>

        </div>

      </div>

      {/* Location Modal */}
      {isOpen && (
        <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50 z-50">

          <div className="bg-white rounded-lg shadow-lg p-6 w-[600px] max-w-[90%] relative">

            <button
              onClick={() => setIsOpen(false)}
              className="absolute top-2 right-2 text-gray-500 hover:text-black"
            >
              ✕
            </button>

            <h2 className="text-lg font-semibold mb-4">
              Select Location
            </h2>

            <div className="overflow-x-auto rounded-lg border border-gray-200">

              <table className="min-w-full bg-white">

                <thead className="bg-gray-100">
                  <tr>
                    <th className="px-6 py-3 text-center text-sm font-semibold text-gray-500">
                      Location Code
                    </th>

                    <th className="px-6 py-3 text-center text-sm font-semibold text-gray-500">
                      Location Name
                    </th>
                  </tr>
                </thead>

                <tbody className="divide-y divide-gray-200">

                  {locations.map((item, index) => (
                    <tr
                      key={item.LocationCode || index}
                      className="hover:bg-gray-50 cursor-pointer"
                      onClick={() => {
                        setSelectedLocation(item);
                        setIsOpen(false);
                      }}
                    >

                      <td className="px-6 py-4">
                        {item.LocationID}
                      </td>

                      <td className="px-6 py-4">
                        {item.LocationName}
                      </td>

                    </tr>
                  ))}

                </tbody>

              </table>

            </div>

            <button
              onClick={() => setIsOpen(false)}
              className="mt-4 bg-red-600 hover:bg-red-700 text-white py-2 px-4 rounded"
            >
              Close
            </button>

          </div>

        </div>
      )}

    </div>
  );
}