// src/hooks/usePermissions.jsx
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useState,
} from "react";
import axios from "axios";

const API = "http://localhost:5000";

// ----------------------------------------------------------------
// Context
// ----------------------------------------------------------------
const PermissionsContext = createContext(null);

// Safe fallback used when there is NO provider in the tree.
// Every check returns true so screens behave exactly like before.
const FALLBACK = {
  map: {},
  loading: false,
  can: () => true,
  canField: () => true,
  mask: (_m, _f, value) => value,
  reload: () => {},
};

// ----------------------------------------------------------------
// Provider
// ----------------------------------------------------------------
export function PermissionsProvider({ children }) {
  const [map, setMap] = useState({});
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    try {
      setLoading(true);

      // Prefer the dedicated /permissions/me endpoint if you built it.
      // If it 404s, fall back to reading from the logged-in user.
      let nextMap = {};

      try {
        const res = await axios.get(`${API}/permissions/me`);
        nextMap = res.data?.permissions || {};
      } catch (err) {
        // --- Fallback: build the map locally from the logged-in user ---
        try {
          const raw =
            localStorage.getItem("user") ||
            sessionStorage.getItem("user");
          const user = raw ? JSON.parse(raw) : null;

          const perms = user?.permissions || user?.Permissions || [];

          if (Array.isArray(perms)) {
            for (const row of perms) {
              const moduleName =
                row.ModuleName || row.moduleName || row.Module || "";
              const permissionName =
                row.PermissionName || row.permissionName || row.Permission || "";

              if (!moduleName || !permissionName) continue;

              const key = `${moduleName}.${permissionName}`;
              nextMap[`${key}.View`]         = Boolean(row.CanView);
              nextMap[`${key}.Add`]          = Boolean(row.CanAdd);
              nextMap[`${key}.Edit`]         = Boolean(row.CanEdit);
              nextMap[`${key}.Delete`]       = Boolean(row.CanDelete);
              nextMap[`${key}.Print`]        = Boolean(row.CanPrint);
              nextMap[`${key}.CostPrice`]    = Boolean(row.CanViewCostPrice);
              nextMap[`${key}.SellingPrice`] = Boolean(row.CanViewSellingPrice);
              nextMap[`${key}.Profit`]       = Boolean(row.CanViewProfit);
            }
          }
        } catch (parseErr) {
          console.error("Permission fallback parse error:", parseErr);
        }
      }

      setMap(nextMap);
    } catch (err) {
      console.error("Load permissions error:", err);
      setMap({});
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const can = useCallback(
    (moduleName, action) => {
      // If the server didn't return anything, be permissive.
      // Change to `return false` if you prefer deny-by-default.
      if (!map || Object.keys(map).length === 0) return true;

      const key = `${moduleName}.${action}`;
      return Boolean(map[key]);
    },
    [map]
  );

  const canField = useCallback(
    (moduleName, field) => {
      if (!map || Object.keys(map).length === 0) return true;

      const key = `${moduleName}.${field}`;
      return Boolean(map[key]);
    },
    [map]
  );

  const mask = useCallback(
    (moduleName, field, value, placeholder = "•••") =>
      canField(moduleName, field) ? value : placeholder,
    [canField]
  );

  const value = {
    map,
    loading,
    can,
    canField,
    mask,
    reload: load,
  };

  return (
    <PermissionsContext.Provider value={value}>
      {children}
    </PermissionsContext.Provider>
  );
}

// ----------------------------------------------------------------
// Hook — NEVER throws
// ----------------------------------------------------------------
export function usePermissions() {
  const ctx = useContext(PermissionsContext);

  // If a provider is present, use it.
  if (ctx) return ctx;

  // Otherwise return the safe fallback so the app keeps working.
  // (You can log a warning once to help track down where the
  //  provider is missing.)
  if (typeof window !== "undefined" && !window.__permWarned) {
    window.__permWarned = true;
    console.warn(
      "[usePermissions] No <PermissionsProvider> found. " +
        "All permission checks will return TRUE. " +
        "Wrap your app to enable real permission gating."
    );
  }

  return FALLBACK;
}

export default usePermissions;