import React, { useEffect, useMemo, useState } from "react";
import axios from "axios";
import {
    Clock3,
    Printer,
    CheckCircle,
    ChevronRight,
    ChevronDown,
    Power,
    RefreshCw
} from "lucide-react";

const API = "http://localhost:5000";

function money(value) {
    return Number(value || 0).toLocaleString("en-LK", {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
    });
}

function duration(minutes) {
    const m = Number(minutes || 0);
    const hours = Math.floor(m / 60);
    const mins = m % 60;

    if (hours === 0) return `${mins}m`;
    return `${hours}h ${mins}m`;
}

function dateText(value) {
    if (!value) return "-";

    return new Date(value).toLocaleDateString("en-US", {
        weekday: "long",
        year: "numeric",
        month: "long",
        day: "2-digit"
    });
}

function shortDate(value) {
    if (!value) return "";

    return new Date(value).toLocaleDateString("en-GB");
}

function timeText(value) {
    if (!value) return "-";

    return new Date(value).toLocaleTimeString("en-LK", {
        hour: "2-digit",
        minute: "2-digit"
    });
}

/*
 * POS_Sessions columns:
 *
 * SessionID
 * ComputerName
 * UserID
 * StartDateTime
 * EndDateTime
 * StartingAmount
 * CardSale
 * CashSale
 * CreditSale
 * ClosingAmount
 * ExpectedCash
 * Variance
 * Status
 * CreatedAt
 * ClosedAt
 *
 * The component uses the database column names directly.
 */

/* ======================================================
   SESSION FETCH HELPERS
====================================================== */

/*
 * Endpoints to try, in order, for closed sessions.
 * The first one that responds wins.
 *
 * Adjust this list to match whatever your backend exposes.
 */
const CLOSED_ENDPOINTS = [
    `${API}/session`,
    `${API}/session/history`,
    `${API}/session/all`
];

/*
 * Normalises any of the shapes the backend might return:
 *   [ ... ]
 *   { data: [ ... ] }
 *   { sessions: [ ... ] }
 *   { data: { sessions: [ ... ] } }
 */
function readSessionList(response) {
    const payload = response?.data;

    if (Array.isArray(payload)) return payload;
    if (Array.isArray(payload?.data)) return payload.data;
    if (Array.isArray(payload?.sessions)) return payload.sessions;
    if (Array.isArray(payload?.data?.sessions)) {
        return payload.data.sessions;
    }

    return [];
}

/*
 * Tries each closed-session endpoint until one responds.
 * 404 means "this route doesn't exist" — try the next one.
 * Any other error is logged and we move on.
 */
async function fetchClosedSessions() {
    for (const url of CLOSED_ENDPOINTS) {
        try {
            const res = await axios.get(url);
            const list = readSessionList(res);

            // Endpoint exists — trust its answer, even if empty.
            return list;
        } catch (err) {
            if (err.response?.status === 404) continue;

            console.warn(`GET ${url} failed:`, err.message);
        }
    }

    return [];
}

export default function CashCollection() {
    const [sessions, setSessions] = useState([]);
    const [expandedDays, setExpandedDays] = useState({});
    const [selectedDays, setSelectedDays] = useState([]);
    const [loading, setLoading] = useState(false);
    const [closing, setClosing] = useState(null);
    const [error, setError] = useState("");
    const [message, setMessage] = useState("");

    useEffect(() => {
        loadData();
    }, []);

    /* ==================================================
       LOAD DATA
       Fetches active + closed sessions and merges them.
    ================================================== */
    async function loadData() {
        try {
            setLoading(true);
            setError("");
            setMessage("");

            const [activeRes, closedList] = await Promise.all([
                axios.get(`${API}/session/active`),
                fetchClosedSessions()
            ]);

            const activeList = readSessionList(activeRes);

            /*
             * Merge active + closed, de-dupe by SessionID.
             * Closed entries are written last so the closed version
             * (with EndDateTime / ClosingAmount / Variance) wins if
             * a session appears in both lists.
             */
            const byId = new Map();

            [...activeList, ...closedList].forEach(session => {
                if (!session) return;

                const id = session.SessionID ?? session.id;

                if (id === undefined || id === null) return;

                byId.set(id, { ...session, SessionID: id });
            });

            setSessions(Array.from(byId.values()));
        } catch (err) {
            console.error("loadData error:", err);

            setError(
                err.response?.data?.message ||
                "Unable to load sessions."
            );
        } finally {
            setLoading(false);
        }
    }

    /* ==================================================
       CLOSE SESSION
       POST /session/close
       { sessionId, closingAmount }
    ================================================== */
    async function closeSession(session) {
        const expected = Number(session.ExpectedCash || 0);

        const value = window.prompt(
            `Enter actual cash.\nExpected cash: Rs.${money(expected)}`
        );

        if (value === null) {
            return;
        }

        const actual = Number(value);

        if (!Number.isFinite(actual) || actual < 0) {
            alert("Please enter a valid amount.");
            return;
        }

        try {
            setClosing(session.SessionID);
            setError("");
            setMessage("");

            const response = await axios.post(
                `${API}/session/close`,
                {
                    sessionId: session.SessionID,
                    closingAmount: actual
                }
            );

            if (response.data?.success) {
                setMessage("Session closed successfully.");
                await loadData();
            } else {
                throw new Error(
                    response.data?.message ||
                    "Unable to close session."
                );
            }
        } catch (err) {
            console.error("POST /session/close error:", err);

            alert(
                err.response?.data?.message ||
                "Unable to close session."
            );
        } finally {
            setClosing(null);
        }
    }

    /* ==================================================
       DERIVED LISTS
    ================================================== */
    const activeSessions = useMemo(() => {
        return sessions.filter(
            session =>
                String(session.Status || "").toUpperCase() === "OPEN"
        );
    }, [sessions]);

    const closedSessions = useMemo(() => {
        return sessions.filter(
            session =>
                String(session.Status || "").toUpperCase() !== "OPEN"
        );
    }, [sessions]);

    /*
     * Group closed sessions by calendar day (local time).
     */
    const closedDays = useMemo(() => {
        const groups = new Map();

        closedSessions.forEach(session => {
            const sourceDate =
                session.EndDateTime ||
                session.ClosedAt ||
                session.StartDateTime;

            const date = sourceDate ? new Date(sourceDate) : null;

            if (!date || Number.isNaN(date.getTime())) {
                return;
            }

            /*
             * Use local calendar date instead of UTC ISO date so
             * sessions do not move to the previous/next day.
             */
            const key = [
                date.getFullYear(),
                String(date.getMonth() + 1).padStart(2, "0"),
                String(date.getDate()).padStart(2, "0")
            ].join("-");

            if (!groups.has(key)) {
                groups.set(key, {
                    SessionDate: key,
                    sessions: []
                });
            }

            groups.get(key).sessions.push(session);
        });

        return Array.from(groups.values())
            .map(day => {
                const daySessions = day.sessions;

                return {
                    ...day,

                    Locations: new Set(
                        daySessions.map(
                            session =>
                                session.ComputerName || "Unknown"
                        )
                    ).size,

                    CashTotal: daySessions.reduce(
                        (sum, session) =>
                            sum + Number(session.CashSale || 0),
                        0
                    ),

                    CardTotal: daySessions.reduce(
                        (sum, session) =>
                            sum + Number(session.CardSale || 0),
                        0
                    ),

                    CreditTotal: daySessions.reduce(
                        (sum, session) =>
                            sum + Number(session.CreditSale || 0),
                        0
                    )
                };
            })
            .sort((a, b) => (a.SessionDate < b.SessionDate ? 1 : -1));
    }, [closedSessions]);

    /* ==================================================
       UI HANDLERS
    ================================================== */
    function toggleDay(day) {
        const key = String(day.SessionDate);

        setExpandedDays(previous => ({
            ...previous,
            [key]: !previous[key]
        }));
    }

    function toggleSelectedDay(date) {
        setSelectedDays(previous => {
            if (previous.includes(date)) {
                return previous.filter(x => x !== date);
            }

            return [...previous, date];
        });
    }

    /*
     * Approve selected days.
     *
     * If your backend does not have this endpoint yet, the error
     * will be shown instead of silently changing session data.
     */
    async function approveSelectedDays() {
        if (selectedDays.length === 0) {
            alert("Please select at least one day.");
            return;
        }

        try {
            setError("");
            setMessage("");

            const response = await axios.post(
                `${API}/cash-collection/approve-days`,
                {
                    dates: selectedDays,
                    approvedBy: "Admin"
                }
            );

            if (response.data?.success) {
                setMessage(
                    "Selected days approved successfully."
                );

                setSelectedDays([]);
                await loadData();
            } else {
                throw new Error(
                    response.data?.message ||
                    "Unable to approve days."
                );
            }
        } catch (err) {
            console.error(
                "POST /cash-collection/approve-days error:",
                err
            );

            alert(
                err.response?.data?.message ||
                "Unable to approve days."
            );
        }
    }

    /* ==================================================
       RENDER
    ================================================== */
    return (
        <div className="min-h-screen bg-white px-5 py-6 text-slate-900">
            <div className="mx-auto max-w-[1250px]">

                {/* HEADER */}
                <div>
                    <h1 className="text-3xl font-bold">
                        Cash Collection
                    </h1>

                    <p className="text-slate-500">
                        Manage session approvals and cash collection
                        across all locations
                    </p>
                </div>

                {/* TABS */}
                <div className="mt-4 inline-flex rounded-lg bg-slate-100 p-1">
                    <button
                        type="button"
                        className="rounded-md bg-white px-5 py-2 text-sm font-medium shadow-sm"
                    >
                        Sessions
                    </button>

                    <button
                        type="button"
                        className="px-5 py-2 text-sm text-slate-500"
                        onClick={() => {
                            alert(
                                "Till Statement is not connected yet."
                            );
                        }}
                    >
                        Till Statement
                    </button>
                </div>

                {/* ACTIONS */}
                <div className="mt-5 flex flex-wrap justify-end gap-3">
                    <button
                        type="button"
                        onClick={loadData}
                        disabled={loading}
                        className="flex items-center gap-2 rounded-xl border px-4 py-2.5 text-sm disabled:opacity-50"
                    >
                        <RefreshCw
                            size={17}
                            className={loading ? "animate-spin" : ""}
                        />

                        Refresh
                    </button>

                    <button
                        type="button"
                        onClick={() => window.print()}
                        className="flex items-center gap-2 rounded-xl border px-4 py-2.5 text-sm"
                    >
                        <Printer size={17} />
                        Print Report
                    </button>

                    <button
                        type="button"
                        onClick={approveSelectedDays}
                        disabled={selectedDays.length === 0}
                        className="flex items-center gap-2 rounded-xl bg-green-400 px-5 py-2.5 text-sm font-semibold text-white disabled:cursor-not-allowed disabled:opacity-50"
                    >
                        <CheckCircle size={18} />
                        Approve Selected Days
                    </button>
                </div>

                {/* ERROR */}
                {error && (
                    <div className="mt-5 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-red-700">
                        {error}
                    </div>
                )}

                {/* SUCCESS */}
                {message && (
                    <div className="mt-5 rounded-xl border border-green-200 bg-green-50 px-4 py-3 text-green-700">
                        {message}
                    </div>
                )}

                {/* ACTIVE SESSIONS */}
                <section className="mt-6 rounded-2xl border border-orange-200 bg-orange-50/70 p-5">
                    <h2 className="mb-5 flex items-center gap-2 text-xl font-semibold text-orange-300">
                        <Clock3 size={21} />
                        Active Sessions ({activeSessions.length})
                    </h2>

                    <div className="space-y-4">
                        {activeSessions.map(session => (
                            <ActiveSession
                                key={session.SessionID}
                                session={session}
                                closing={
                                    closing === session.SessionID
                                }
                                onClose={closeSession}
                            />
                        ))}

                        {activeSessions.length === 0 && (
                            <div className="rounded-xl border border-orange-200 bg-white p-8 text-center text-slate-500">
                                No active sessions
                            </div>
                        )}
                    </div>
                </section>

                {/* CLOSED SESSIONS */}
                <section className="mt-6 rounded-2xl border border-slate-300 bg-white p-5">
                    <h2 className="mb-5 text-2xl font-semibold">
                        Closed Sessions - Day → Location → Session View
                    </h2>

                    <div className="space-y-4">
                        {closedDays.map(day => {
                            const key = String(day.SessionDate);
                            const expanded = expandedDays[key];

                            return (
                                <div
                                    key={key}
                                    className="overflow-hidden rounded-xl border border-slate-300"
                                >
                                    {/* DAY ROW */}
                                    <div className="flex flex-col gap-4 px-4 py-4 md:flex-row md:items-center">
                                        <div className="flex flex-1 items-center gap-3">
                                            <input
                                                type="checkbox"
                                                checked={selectedDays.includes(
                                                    key
                                                )}
                                                onChange={() =>
                                                    toggleSelectedDay(key)
                                                }
                                                className="h-4 w-4 accent-orange-500"
                                            />

                                            <button
                                                type="button"
                                                onClick={() =>
                                                    toggleDay(day)
                                                }
                                                className="flex items-center gap-2"
                                            >
                                                {expanded ? (
                                                    <ChevronDown size={19} />
                                                ) : (
                                                    <ChevronRight size={19} />
                                                )}

                                                <span className="font-medium">
                                                    {dateText(
                                                        `${key}T00:00:00`
                                                    )}
                                                </span>
                                            </button>
                                        </div>

                                        <div className="grid grid-cols-2 gap-6 text-right md:grid-cols-4">
                                            <Total
                                                label="Locations"
                                                value={day.Locations}
                                            />

                                            <Total
                                                label="Cash Total"
                                                value={day.CashTotal}
                                                green
                                            />

                                            <Total
                                                label="Card Total"
                                                value={day.CardTotal}
                                                purple
                                            />

                                            <Total
                                                label="Credit Total"
                                                value={day.CreditTotal}
                                                blue
                                            />
                                        </div>
                                    </div>

                                    {/* DAY SESSIONS */}
                                    {expanded && (
                                        <div className="border-t bg-slate-50 p-4">
                                            {day.sessions.map(session => (
                                                <ClosedSession
                                                    key={session.SessionID}
                                                    session={session}
                                                />
                                            ))}

                                            {day.sessions.length === 0 && (
                                                <p className="py-5 text-center text-slate-500">
                                                    No sessions found.
                                                </p>
                                            )}
                                        </div>
                                    )}
                                </div>
                            );
                        })}

                        {closedDays.length === 0 && (
                            <div className="p-10 text-center text-slate-500">
                                No closed sessions found.
                            </div>
                        )}
                    </div>
                </section>
            </div>
        </div>
    );
}


/* ======================================================
   ACTIVE SESSION CARD
====================================================== */

function ActiveSession({
    session,
    closing,
    onClose
}) {
    const expectedCash =
        session.ExpectedCash !== null &&
        session.ExpectedCash !== undefined
            ? Number(session.ExpectedCash)
            : Number(session.StartingAmount || 0) +
              Number(session.CashSale || 0);

    const totalSales =
        Number(session.CashSale || 0) +
        Number(session.CardSale || 0) +
        Number(session.CreditSale || 0);

    const durationMinutes = calculateDuration(
        session.StartDateTime
    );

    return (
        <div className="rounded-xl border border-orange-200 bg-white/60 p-5">
            <div className="grid gap-6 lg:grid-cols-7 lg:items-center">

                {/* REGISTER / COMPUTER */}
                <div>
                    <Label>Register</Label>

                    <div className="mt-2 font-semibold text-orange-300">
                        {session.ComputerName || "Unknown"}
                    </div>

                    <div className="font-semibold text-orange-200">
                        User #{session.UserID ?? "-"}
                    </div>

                    <p className="mt-2 text-xs text-slate-500">
                        Started:{" "}
                        {shortDate(session.StartDateTime)}
                        {" "}
                        {timeText(session.StartDateTime)}
                    </p>
                </div>

                {/* CASH */}
                <Metric
                    label="Cash Sales"
                    value={session.CashSale}
                    color="green"
                    secondaryLabel="Starting Cash"
                    secondaryValue={session.StartingAmount}
                    secondaryColor="black"
                />

                {/* CARD */}
                <Metric
                    label="Card Sales"
                    value={session.CardSale}
                    color="purple"
                />

                {/* CREDIT */}
                <Metric
                    label="Credit Sales"
                    value={session.CreditSale}
                    color="blue"
                />

                {/* TOTAL */}
                <Metric
                    label="Total Sales"
                    value={totalSales}
                    color="green"
                    secondaryLabel="Expected Cash"
                    secondaryValue={expectedCash}
                    secondaryColor="black"
                />

                {/* SESSION */}
                <div>
                    <Label>Status</Label>

                    <p className="mt-2 font-medium">
                        {session.Status || "OPEN"}
                    </p>

                    <Label>Duration</Label>

                    <p className="mt-1 text-sm">
                        {duration(durationMinutes)}
                    </p>
                </div>

                {/* CLOSE */}
                <button
                    type="button"
                    onClick={() => onClose(session)}
                    disabled={closing}
                    className="flex items-center justify-center gap-2 rounded-xl border border-orange-200 bg-white px-4 py-3 font-medium text-orange-400 hover:bg-orange-50 disabled:opacity-50"
                >
                    <Power size={17} />

                    {closing ? "Closing..." : "Close Session"}
                </button>
            </div>
        </div>
    );
}


/* ======================================================
   CLOSED SESSION
====================================================== */

function ClosedSession({ session }) {
    const variance =
        session.Variance !== null &&
        session.Variance !== undefined
            ? Number(session.Variance)
            : null;

    return (
        <div className="mb-3 rounded-xl border border-slate-200 bg-white p-5">
            <div className="grid gap-5 md:grid-cols-7 md:items-center">

                {/* COMPUTER */}
                <div>
                    <p className="text-xs text-slate-500">
                        Computer
                    </p>

                    <p className="mt-1 font-semibold">
                        {session.ComputerName || "Unknown"}
                    </p>
                </div>

                {/* USER */}
                <div>
                    <p className="text-xs text-slate-500">
                        User
                    </p>

                    <p className="mt-1 font-semibold">
                        #{session.UserID ?? "-"}
                    </p>
                </div>

                {/* CASH */}
                <Metric
                    label="Cash"
                    value={session.CashSale}
                    color="green"
                />

                {/* CARD */}
                <Metric
                    label="Card"
                    value={session.CardSale}
                    color="purple"
                />

                {/* CREDIT */}
                <Metric
                    label="Credit"
                    value={session.CreditSale}
                    color="blue"
                />

                {/* CLOSING */}
                <Metric
                    label="Closing Cash"
                    value={session.ClosingAmount}
                    color="black"
                    secondaryLabel="Expected Cash"
                    secondaryValue={session.ExpectedCash}
                    secondaryColor="black"
                />

                {/* STATUS */}
                <div>
                    <p className="text-xs text-slate-500">
                        Status
                    </p>

                    <span className="mt-2 inline-block rounded-full bg-green-50 px-3 py-1 text-xs font-semibold text-green-700">
                        {session.Status || "CLOSED"}
                    </span>

                    {variance !== null && (
                        <p
                            className={`mt-2 text-sm font-semibold ${
                                variance === 0
                                    ? "text-green-600"
                                    : variance > 0
                                    ? "text-blue-600"
                                    : "text-red-600"
                            }`}
                        >
                            Variance: Rs.{money(variance)}
                        </p>
                    )}
                </div>
            </div>

            <div className="mt-4 flex flex-wrap gap-6 border-t pt-3 text-xs text-slate-500">
                <span>
                    Started:{" "}
                    {shortDate(session.StartDateTime)}{" "}
                    {timeText(session.StartDateTime)}
                </span>

                <span>
                    Closed:{" "}
                    {session.EndDateTime
                        ? `${shortDate(session.EndDateTime)} ${timeText(
                              session.EndDateTime
                          )}`
                        : "-"}
                </span>

                <span>
                    Session ID: {session.SessionID}
                </span>
            </div>
        </div>
    );
}


/* ======================================================
   METRIC
====================================================== */

function Metric({
    label,
    value,
    color,
    secondaryLabel,
    secondaryValue,
    secondaryColor
}) {
    const colors = {
        green: "text-green-500",
        purple: "text-purple-500",
        blue: "text-blue-500",
        red: "text-red-500",
        black: "text-slate-900"
    };

    return (
        <div>
            <Label>{label}</Label>

            <p
                className={`
                    mt-2
                    text-lg
                    font-semibold
                    ${colors[color] || colors.black}
                `}
            >
                Rs.{money(value)}
            </p>

            {secondaryLabel && (
                <>
                    <Label>{secondaryLabel}</Label>

                    <p
                        className={`
                            mt-1
                            text-sm
                            font-medium
                            ${
                                colors[
                                    secondaryColor || color
                                ] || colors.black
                            }
                        `}
                    >
                        Rs.{money(secondaryValue)}
                    </p>
                </>
            )}
        </div>
    );
}


/* ======================================================
   LABEL
====================================================== */

function Label({ children }) {
    return (
        <p className="text-sm text-slate-500">
            {children}
        </p>
    );
}


/* ======================================================
   TOTAL
====================================================== */

function Total({
    label,
    value,
    green,
    purple,
    blue
}) {
    let color = "text-slate-900";

    if (green) color = "text-green-500";
    if (purple) color = "text-purple-500";
    if (blue) color = "text-blue-500";

    return (
        <div>
            <p className="text-xs text-slate-500">
                {label}
            </p>

            <p className={`font-medium ${color}`}>
                {label === "Locations"
                    ? value
                    : `Rs.${money(value)}`}
            </p>
        </div>
    );
}


/* ======================================================
   HELPERS
====================================================== */

function calculateDuration(startDateTime) {
    if (!startDateTime) return 0;

    const start = new Date(startDateTime);

    if (Number.isNaN(start.getTime())) {
        return 0;
    }

    const now = new Date();

    const minutes = Math.floor(
        (now.getTime() - start.getTime()) / 60000
    );

    return Math.max(minutes, 0);
}