import React, { useEffect, useState } from "react";
import axios from "axios";
import {
  Gift,
  Ticket,
  Barcode,
  ArrowRightLeft,
  Plus,
  Search,
  Printer,
  RefreshCw,
  History,
  X
} from "lucide-react";

const API = "http://localhost:5000/api";

export default function GiftVoucher() {
  const [activeTab, setActiveTab] = useState("generation");
  const [voucherType, setVoucherType] = useState("Voucher");

  const [groups, setGroups] = useState([]);
  const [vouchers, setVouchers] = useState([]);
  const [selectedVouchers, setSelectedVouchers] = useState([]);

  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");

  /* =====================================================
     LOCATIONS
  ===================================================== */

  const [locations, setLocations] = useState([]);
  const [locationsLoading, setLocationsLoading] = useState(false);

  /* =====================================================
     GROUP FORM
  ===================================================== */

  const [groupForm, setGroupForm] = useState({
    groupCode: "",
    groupName: "",
    basedOn: "Book Serial",
    voucherValue: "",
    validityDays: "",
    percentageOfCoupon: ""
  });

  /* =====================================================
     BOOK FORM
  ===================================================== */

  const [bookForm, setBookForm] = useState({
    groupId: "",
    bookCode: "",
    bookName: "",
    startingNo: "1",
    serialLength: "8",
    noOfVouchers: "10",
    voucherPrefix: "",
    voucherValue: "",
    validityDays: ""
  });

  /* =====================================================
     SEARCH
  ===================================================== */

  const [search, setSearch] = useState({
    voucherNo: "",
    serial: "",
    status: ""
  });

  /* =====================================================
     TRANSFER
  ===================================================== */

  const [transfer, setTransfer] = useState({
    documentNo: "",
    toLocationId: "",
    reference: "",
    remark: ""
  });

  /* =====================================================
     TRANSFER HISTORY
  ===================================================== */

  const [transferHistory, setTransferHistory] = useState([]);
  const [showHistory, setShowHistory] = useState(false);
  const [transferDetails, setTransferDetails] = useState([]);
  const [showTransferDetails, setShowTransferDetails] =
    useState(false);
  const [selectedTransferId, setSelectedTransferId] =
    useState(null);

  /* =====================================================
     LOAD GROUPS
  ===================================================== */

  const loadGroups = async () => {
    try {
      const response = await axios.get(
        `${API}/gift-voucher/groups`
      );

      setGroups(response.data.data || []);
    } catch (error) {
      console.error("Error loading groups:", error);
      setMessage("Unable to load voucher groups");
    }
  };

  /* =====================================================
     LOAD LOCATIONS
  ===================================================== */

  const loadLocations = async () => {
    try {
      setLocationsLoading(true);

      const response = await axios.get(
        `${API}/locations`
      );

      let locationData = [];

      if (response.data && response.data.data) {
        locationData = response.data.data;
      } else if (
        response.data &&
        Array.isArray(response.data)
      ) {
        locationData = response.data;
      } else if (
        response.data &&
        response.data.locations
      ) {
        locationData = response.data.locations;
      } else {
        locationData = response.data || [];
      }

      const validLocations = locationData.filter(
        loc => loc.LocationID
      );

      setLocations(validLocations);

      if (validLocations.length === 0) {
        setMessage("No locations available");
      }
    } catch (error) {
      console.error("Error loading locations:", error);

      setMessage(
        "Unable to load locations. Please check the API endpoint."
      );
    } finally {
      setLocationsLoading(false);
    }
  };



  const renderVoucherTemplate = (
  layout,
  voucher
) => {
  const page = layout?.page || {};

  const width = page.width || 100;
  const height = page.height || 60;
  const unit = page.unit || "mm";

  const elements = Array.isArray(
    layout?.elements
  )
    ? layout.elements
    : [];

  const replaceValue = value => {
    if (value === null || value === undefined) {
      return "";
    }

    return String(value)
      .replace(
        /\{VoucherNo\}/g,
        voucher.VoucherNo ??
          voucher.VoucherNumber ??
          ""
      )
      .replace(
        /\{VoucherSerial\}/g,
        voucher.VoucherSerial ?? ""
      )
      .replace(
        /\{VoucherValue\}/g,
        voucher.VoucherValue ??
          voucher.Price ??
          ""
      )
      .replace(
        /\{VoucherType\}/g,
        voucher.VoucherType ?? ""
      )
      .replace(
        /\{ExpiryDate\}/g,
        voucher.ExpiryDate ?? ""
      )
      .replace(
        /\{Status\}/g,
        voucher.Status ?? ""
      );
  };

  const escapeHtml = value =>
    String(value ?? "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");

  const renderedElements = elements
    .filter(element => element.visible !== false)
    .map(element => {
      const x = element.x || 0;
      const y = element.y || 0;
      const elementWidth =
        element.width || 20;
      const elementHeight =
        element.height || 10;

      if (element.type === "barcode") {
        const barcodeValue =
          replaceValue(element.text);

        return `
          <div
            class="voucher-element voucher-barcode"
            data-barcode="${escapeHtml(
              barcodeValue
            )}"
            style="
              left:${x}${unit};
              top:${y}${unit};
              width:${elementWidth}${unit};
              height:${elementHeight}${unit};
            "
          >
            <svg
              class="barcode-svg"
              width="100%"
              height="100%"
            ></svg>
          </div>
        `;
      }

      const text =
        replaceValue(element.text);

      return `
        <div
          class="voucher-element"
          style="
            left:${x}${unit};
            top:${y}${unit};
            width:${elementWidth}${unit};
            height:${elementHeight}${unit};
            font-size:${element.fontSize || 10}pt;
            font-weight:${
              element.bold
                ? "700"
                : "400"
            };
            text-align:${
              element.align || "left"
            };
          "
        >
          ${escapeHtml(text)}
        </div>
      `;
    })
    .join("");

  return `
    <div
      class="voucher-page"
      style="
        width:${width}${unit};
        height:${height}${unit};
      "
    >
      ${renderedElements}
    </div>
  `;
};


const printVoucher = async voucher => {
  try {
    if (!voucher) {
      alert("Voucher information not available");
      return;
    }

    const voucherTypeId =
      voucher.VoucherTypeId ??
      voucher.VoucherTypeID ??
      voucher.VoucherTypeId ?? 1;

    if (!voucherTypeId) {
      alert(
        "VoucherTypeId is missing from this voucher."
      );
      return;
    }

    const response = await axios.get(
      `http://localhost:5000/voucher-templates/${voucherTypeId}`
    );

    console.log(
      "Voucher template response:",
      response.data
    );

    const template =
      response.data?.data ??
      response.data;

    const layout =
      template?.layout ??
      (
        typeof template?.LayoutJson ===
        "string"
          ? JSON.parse(
              template.LayoutJson
            )
          : template?.LayoutJson
      );

    if (
      !layout ||
      !Array.isArray(
        layout.elements
      )
    ) {
      alert(
        "Voucher template layout is empty or invalid."
      );
      return;
    }

    const voucherHtml =
      renderVoucherTemplate(
        layout,
        voucher
      );

    const popup = window.open(
      "",
      "_blank",
      "width=900,height=800"
    );

    if (!popup) {
      alert(
        "Please allow popups to print the voucher."
      );
      return;
    }

    popup.document.open();

    popup.document.write(`
      <!DOCTYPE html>
      <html>
        <head>
          <meta charset="UTF-8">

          <title>
            Gift Voucher ${
              voucher.VoucherNo ||
              voucher.VoucherSerial ||
              ""
            }
          </title>

          <style>
            @page {
              size: ${
                layout.page?.width ||
                100
              }mm ${
                layout.page?.height ||
                60
              }mm;
              margin: 0;
            }

            html,
            body {
              margin: 0;
              padding: 0;
              background: white;
            }

            body {
              font-family:
                Arial,
                Helvetica,
                sans-serif;
            }

            .voucher-page {
              position: relative;
              overflow: hidden;
              background: white;
            }

            .voucher-element {
              position: absolute;
              box-sizing: border-box;
              overflow: hidden;
              white-space: normal;
              line-height: 1.1;
            }

            .voucher-barcode {
              display: flex;
              align-items: center;
              justify-content: center;
            }

            .barcode-svg {
              width: 100%;
              height: 100%;
            }

            @media print {
              html,
              body {
                margin: 0;
                padding: 0;
              }
            }
          </style>
        </head>

        <body>

          ${voucherHtml}

          <script>
            window.onload = function () {

              const barcodes =
                document.querySelectorAll(
                  ".voucher-barcode"
                );

              barcodes.forEach(function (item) {

                const value =
                  item.getAttribute(
                    "data-barcode"
                  );

                const svg =
                  item.querySelector(
                    ".barcode-svg"
                  );

                if (
                  value &&
                  svg &&
                  window.JsBarcode
                ) {
                  try {
                    window.JsBarcode(
                      svg,
                      value,
                      {
                        format: "CODE128",
                        displayValue: true,
                        margin: 0,
                        width: 1.5,
                        height: 30
                      }
                    );
                  } catch (e) {
                    console.error(
                      "Barcode error:",
                      e
                    );
                  }
                }
              });

              setTimeout(
                function () {
                  window.print();
                },
                500
              );
            };
          </script>

          <script src="https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js"></script>

        </body>
      </html>
    `);

    popup.document.close();

  } catch (error) {
    console.error(
      "Error printing voucher:",
      error
    );

    alert(
      error.response?.data?.message ||
      error.message ||
      "Unable to load voucher template"
    );
  }
};
  /* =====================================================
     EXPORT CSV / TXT
  ===================================================== */

  const exportProducts = format => {
    if (!vouchers || vouchers.length === 0) {
      alert("No vouchers available to export");
      return;
    }

    const rows = [
      ["VoucherSerial", "Price"],

      ...vouchers.map(voucher => [
        voucher.VoucherSerial ?? "",
        voucher.VoucherValue ?? voucher.Price ?? ""
      ])
    ];

    const content = rows
      .map(row =>
        row
          .map(value => {
            const stringValue = String(value ?? "");

            if (
              stringValue.includes(",") ||
              stringValue.includes('"') ||
              stringValue.includes("\n") ||
              stringValue.includes("\r")
            ) {
              return `"${stringValue.replace(
                /"/g,
                '""'
              )}"`;
            }

            return stringValue;
          })
          .join(",")
      )
      .join("\r\n");

    const extension =
      format === "csv" ? "csv" : "txt";

    const mimeType =
      format === "csv"
        ? "text/csv;charset=utf-8;"
        : "text/plain;charset=utf-8;";

    const blob = new Blob(
      ["\uFEFF" + content],
      {
        type: mimeType
      }
    );

    const url = URL.createObjectURL(blob);

    const link = document.createElement("a");

    link.href = url;

    link.download =
      `Voucher_Export_${new Date()
        .toISOString()
        .slice(0, 10)}.${extension}`;

    document.body.appendChild(link);

    link.click();

    document.body.removeChild(link);

    URL.revokeObjectURL(url);
  };

  /* =====================================================
     LOAD VOUCHERS
  ===================================================== */

  const loadVouchers = async () => {
    try {
      setLoading(true);

      const params = {
        ...search
      };

      if (activeTab === "transfer") {
        params.status = "Available";
      }

      const response = await axios.get(
        `${API}/gift-voucher`,
        {
          params
        }
      );

      setVouchers(
        response.data.data || []
      );
    } catch (error) {
      console.error(
        "Error loading vouchers:",
        error
      );

      setMessage(
        "Unable to load vouchers"
      );
    } finally {
      setLoading(false);
    }
  };

  /* =====================================================
     LOAD TRANSFER HISTORY
  ===================================================== */

  const loadTransferHistory = async () => {
    try {
      const response = await axios.get(
        `${API}/gift-voucher/transfer/history`
      );

      setTransferHistory(
        response.data.data || []
      );
    } catch (error) {
      console.error(
        "Error loading transfer history:",
        error
      );

      setMessage(
        "Unable to load transfer history"
      );
    }
  };

  /* =====================================================
     LOAD TRANSFER DETAILS
  ===================================================== */

  const loadTransferDetails = async transferId => {
    try {
      const response = await axios.get(
        `${API}/gift-voucher/transfer/${transferId}/details`
      );

      setTransferDetails(
        response.data.data || []
      );

      setSelectedTransferId(
        transferId
      );

      setShowTransferDetails(true);
    } catch (error) {
      console.error(
        "Error loading transfer details:",
        error
      );

      setMessage(
        "Unable to load transfer details"
      );
    }
  };

  /* =====================================================
     INITIAL LOAD
  ===================================================== */

  useEffect(() => {
    loadGroups();
    loadLocations();
  }, []);

  /* =====================================================
     RELOAD VOUCHERS ON TAB CHANGE
  ===================================================== */

  useEffect(() => {
    if (activeTab === "transfer") {
      loadVouchers();
      setSelectedVouchers([]);
      loadTransferHistory();
    } else if (
      activeTab === "master" ||
      activeTab === "barcode"
    ) {
      loadVouchers();
    }
  }, [activeTab]);

  /* =====================================================
     GROUP CHANGE
  ===================================================== */

  const handleGroupChange = e => {
    setGroupForm({
      ...groupForm,
      [e.target.name]: e.target.value
    });
  };

  /* =====================================================
     BOOK CHANGE
  ===================================================== */

  const handleBookChange = e => {
    setBookForm({
      ...bookForm,
      [e.target.name]: e.target.value
    });
  };

  /* =====================================================
     SAVE GROUP
  ===================================================== */

  const saveGroup = async () => {
    try {
      if (!groupForm.groupCode) {
        alert("Enter group code");
        return;
      }

      if (!groupForm.groupName) {
        alert("Enter group name");
        return;
      }

      setLoading(true);

      await axios.post(
        `${API}/gift-voucher/groups`,
        {
          ...groupForm,
          voucherType,

          createdBy:
            JSON.parse(
              localStorage.getItem("user")
            )?.Username || "admin"
        }
      );

      alert(
        "Gift voucher group saved successfully"
      );

      setGroupForm({
        groupCode: "",
        groupName: "",
        basedOn: "Book Serial",
        voucherValue: "",
        validityDays: "",
        percentageOfCoupon: ""
      });

      await loadGroups();
    } catch (error) {
      console.error(error);

      alert(
        error.response?.data?.message ||
          "Unable to save group"
      );
    } finally {
      setLoading(false);
    }
  };

  /* =====================================================
     GENERATE VOUCHERS
  ===================================================== */

  const generateVouchers = async () => {
    try {
      if (!bookForm.groupId) {
        alert("Select Gift Voucher Group");
        return;
      }

      if (!bookForm.bookCode) {
        alert("Enter Book Code");
        return;
      }

      if (!bookForm.bookName) {
        alert("Enter Book Name");
        return;
      }

      if (
        !bookForm.noOfVouchers ||
        Number(bookForm.noOfVouchers) <= 0
      ) {
        alert("Enter valid voucher quantity");
        return;
      }

      setLoading(true);

      const response = await axios.post(
        `${API}/gift-voucher/books/generate`,
        {
          groupId:
            Number(bookForm.groupId),

          bookCode:
            bookForm.bookCode,

          bookName:
            bookForm.bookName,

          voucherType,

          startingNo:
            Number(bookForm.startingNo),

          serialLength:
            Number(bookForm.serialLength),

          noOfVouchers:
            Number(bookForm.noOfVouchers),

          voucherPrefix:
            bookForm.voucherPrefix,

          voucherValue:
            Number(
              bookForm.voucherValue || 0
            ),

          validityDays:
            Number(
              bookForm.validityDays || 0
            ),

          createdBy:
            JSON.parse(
              localStorage.getItem("user")
            )?.Username || "admin"
        }
      );

      setVouchers(
        response.data.vouchers || []
      );

      alert(response.data.message);

      setActiveTab("master");
    } catch (error) {
      console.error(error);

      alert(
        error.response?.data?.message ||
          "Voucher generation failed"
      );
    } finally {
      setLoading(false);
    }
  };

  /* =====================================================
     SELECT VOUCHER
  ===================================================== */

  const toggleVoucher = id => {
    setSelectedVouchers(previous => {
      if (previous.includes(id)) {
        return previous.filter(
          x => x !== id
        );
      }

      return [
        ...previous,
        id
      ];
    });
  };

  /* =====================================================
     SELECT ALL VOUCHERS
  ===================================================== */

  const selectAllVouchers = () => {
    const availableVouchers =
      vouchers.filter(
        v => v.Status === "Available"
      );

    if (
      selectedVouchers.length ===
      availableVouchers.length
    ) {
      setSelectedVouchers([]);
    } else {
      setSelectedVouchers(
        availableVouchers.map(
          v => v.GiftVoucherID
        )
      );
    }
  };

  /* =====================================================
     TRANSFER VOUCHERS
  ===================================================== */

  const transferVouchers = async () => {
    try {
      if (
        selectedVouchers.length === 0
      ) {
        alert("Select vouchers first");
        return;
      }

      if (!transfer.toLocationId) {
        alert("Select destination location");
        return;
      }

      if (!transfer.documentNo) {
        alert(
          "Generate or enter document number"
        );
        return;
      }

      setLoading(true);

      const selectedVoucherData =
        vouchers.filter(
          v =>
            selectedVouchers.includes(
              v.GiftVoucherID
            )
        );

      const invalidVouchers =
        selectedVoucherData.filter(
          v =>
            v.Status !== "Available"
        );

      if (
        invalidVouchers.length > 0
      ) {
        alert(
          `Cannot transfer ${invalidVouchers.length} voucher(s) as they are not in "Available" status.`
        );

        setLoading(false);

        return;
      }

      const transferData = {
        documentNo:
          transfer.documentNo,

        voucherType,

        fromLocationId:
          selectedVoucherData[0]
            ?.LocationID || null,

        toLocationId:
          transfer.toLocationId,

        reference:
          transfer.reference || null,

        remark:
          transfer.remark || null,

        voucherIds:
          selectedVouchers,

        createdBy:
          JSON.parse(
            localStorage.getItem("user")
          )?.Username || "admin"
      };

      const response =
        await axios.post(
          `${API}/gift-voucher/transfer`,
          transferData
        );

      alert(
        response.data.message ||
          "Voucher transfer completed successfully"
      );

      setSelectedVouchers([]);

      setTransfer({
        documentNo: "",
        toLocationId: "",
        reference: "",
        remark: ""
      });

      await loadVouchers();
      await loadTransferHistory();
    } catch (error) {
      console.error(error);

      alert(
        error.response?.data?.message ||
          "Transfer failed"
      );
    } finally {
      setLoading(false);
    }
  };

  /* =====================================================
     GET VOUCHER TEMPLATE
  ===================================================== */

  const getVoucherTemplate = async voucher => {
    /*
      VoucherTemplateID should normally come from the voucher.

      Expected API:
      GET /api/voucher-template/:id

      The fallback to template ID 1 is kept for compatibility with
      existing generated vouchers that do not yet contain the ID.
    */

    const templateId =
      voucher?.VoucherTemplateID ??
      voucher?.voucherTemplateID ??
      voucher?.VoucherTemplateId ??
      voucher?.templateID ??
      voucher?.TemplateID ??
      1;

    if (!templateId) {
      throw new Error(
        "VoucherTemplateID was not found for this voucher."
      );
    }

    /*
      The original code used:
        http://localhost:5000/voucher-templates/:id

      But API is defined as:
        http://localhost:5000/api

      and the documented route is:
        GET /api/voucher-template/:id

      Use the documented route first. The second URL is retained as
      a compatibility fallback for an older backend.
    */

    const urls = [
      `${API}/voucher-template/${templateId}`,
      `${API}/voucher-templates/${templateId}`,
      `http://localhost:5000/voucher-template/${templateId}`,
      `http://localhost:5000/voucher-templates/${templateId}`
    ];

    let response = null;
    let lastError = null;

    for (const url of urls) {
      try {
        response = await axios.get(url);
        break;
      } catch (error) {
        lastError = error;

        /*
          Only try the next route when the current route does not exist.
          Other errors should be reported immediately.
        */
        const status = error.response?.status;

        if (
          status !== 404 &&
          status !== 405
        ) {
          throw error;
        }
      }
    }

    if (!response) {
      throw (
        lastError ||
        new Error(
          "Unable to load voucher template."
        )
      );
    }

    console.log(
      "Voucher template API response:",
      response.data
    );

    /*
      Support common API response shapes:

      {
        data: {
          VoucherTemplateID: 1,
          TemplateHTML: "<div>...</div>"
        }
      }

      {
        data: {
          data: {
            VoucherTemplateID: 1,
            TemplateHTML: "<div>...</div>"
          }
        }
      }

      {
        VoucherTemplateID: 1,
        TemplateHTML: "<div>...</div>"
      }
    */

    const payload = response.data;

    const template =
      payload?.data?.data ??
      payload?.data ??
      payload?.template ??
      payload?.Template ??
      payload;

    if (!template) {
      throw new Error(
        "Voucher template was not found."
      );
    }

    /*
      Some APIs return the HTML string directly instead of
      returning an object containing TemplateHTML.
    */

    if (
      typeof template === "string"
    ) {
      return {
        TemplateHTML: template
      };
    }

    return template;
  };

  /* =====================================================
     REPLACE TEMPLATE VARIABLES
  ===================================================== */

  const replaceTemplateVariables = (
    template,
    voucher
  ) => {
    if (!template) {
      return "";
    }

    const expiryDate =
      voucher.ExpiryDate
        ? new Date(
            voucher.ExpiryDate
          ).toLocaleDateString()
        : "";

    const values = {
      VoucherNo:
        voucher.VoucherNo ?? "",

      VoucherSerial:
        voucher.VoucherSerial ?? "",

      VoucherValue:
        voucher.VoucherValue != null
          ? Number(
              voucher.VoucherValue
            ).toFixed(2)
          : "0.00",

      Price:
        voucher.VoucherValue != null
          ? Number(
              voucher.VoucherValue
            ).toFixed(2)
          : "0.00",

      BookCode:
        voucher.BookCode ?? "",

      BookName:
        voucher.BookName ?? "",

      Status:
        voucher.Status ?? "",

      ExpiryDate:
        expiryDate,

      VoucherType:
        voucher.VoucherType ??
        voucherType,

      LocationCode:
        voucher.LocationCode ?? "",

      LocationName:
        voucher.LocationName ?? ""
    };

    let html = String(template);

    Object.keys(values).forEach(key => {
      const value = String(
        values[key] ?? ""
      );

      /*
        Supports:

        {{VoucherNo}}
        {{ VoucherNo }}
        ${VoucherNo}
      */

      const patterns = [
        new RegExp(
          `\\{\\{\\s*${key}\\s*\\}\\}`,
          "gi"
        ),

        new RegExp(
          `\\$\\{\\s*${key}\\s*\\}`,
          "gi"
        )
      ];

      patterns.forEach(pattern => {
        html = html.replace(
          pattern,
          value
        );
      });
    });

    return html;
  };

  /* =====================================================
     PRINT VOUCHER USING VOUCHER TEMPLATE
  ===================================================== */



  /* =====================================================
     GENERATE DOCUMENT NO
  ===================================================== */

  const generateDocumentNo = () => {
    const now = new Date();

    const value =
      "TGV" +
      now.getFullYear() +
      String(
        now.getMonth() + 1
      ).padStart(2, "0") +
      String(
        now.getDate()
      ).padStart(2, "0") +
      String(
        now.getHours()
      ).padStart(2, "0") +
      String(
        now.getMinutes()
      ).padStart(2, "0") +
      String(
        now.getSeconds()
      ).padStart(2, "0");

    setTransfer({
      ...transfer,
      documentNo: value
    });
  };

  /* =====================================================
     SELECTED VOUCHER DETAILS
  ===================================================== */

  const getSelectedVoucherDetails = () => {
    return vouchers.filter(
      v =>
        selectedVouchers.includes(
          v.GiftVoucherID
        )
    );
  };

  /* =====================================================
     LOCATION NAME
  ===================================================== */

  const getLocationName = locationId => {
    if (!locationId) return "-";

    const location = locations.find(
      l =>
        l.LocationID === locationId
    );

    if (location) {
      return `${location.LocationCode || location.code || ""} - ${
        location.LocationName ||
        location.name ||
        ""
      }`;
    }

    return String(locationId);
  };

  return (
    <div className="min-h-screen bg-gray-100 p-5">

      {/* =================================================
          HEADER
      ================================================= */}

      <div className="
        bg-white
        rounded-xl
        shadow
        p-5
        mb-5
      ">

        <div className="
          flex
          items-center
          justify-between
        ">

          <div>

            <h1 className="
              text-2xl
              font-bold
              text-gray-800
            ">
              Gift Voucher Management
            </h1>

            <p className="
              text-gray-500
              mt-1
            ">
              Gift Voucher / Coupon Management System
            </p>

          </div>

          <div className="flex gap-2">

            <button
              onClick={() =>
                setVoucherType("Voucher")
              }
              className={`
                px-5
                py-2
                rounded-lg
                font-semibold
                transition-colors
                ${
                  voucherType === "Voucher"
                    ? "bg-orange-500 text-white"
                    : "bg-gray-100 hover:bg-gray-200"
                }
              `}
            >

              <Ticket
                size={18}
                className="inline mr-2"
              />

              Voucher

            </button>

            <button
              onClick={() =>
                setVoucherType("Coupon")
              }
              className={`
                px-5
                py-2
                rounded-lg
                font-semibold
                transition-colors
                ${
                  voucherType === "Coupon"
                    ? "bg-orange-500 text-white"
                    : "bg-gray-100 hover:bg-gray-200"
                }
              `}
            >

              <Gift
                size={18}
                className="inline mr-2"
              />

              Coupon

            </button>

          </div>

        </div>

      </div>

      {/* =================================================
          TABS
      ================================================= */}

      <div className="
        bg-white
        rounded-xl
        shadow
        mb-5
      ">

        <div className="
          flex
          border-b
          overflow-x-auto
        ">

          <TabButton
            active={
              activeTab === "generation"
            }
            onClick={() =>
              setActiveTab("generation")
            }
            icon={
              <Barcode size={18} />
            }
            text="Book Code Generation"
          />

          <TabButton
            active={
              activeTab === "master"
            }
            onClick={() =>
              setActiveTab("master")
            }
            icon={
              <Gift size={18} />
            }
            text="Gift Voucher Master"
          />

          <TabButton
            active={
              activeTab === "barcode"
            }
            onClick={() =>
              setActiveTab("barcode")
            }
            icon={
              <Barcode size={18} />
            }
            text="Gift Voucher Barcode"
          />

          <TabButton
            active={
              activeTab === "transfer"
            }
            onClick={() =>
              setActiveTab("transfer")
            }
            icon={
              <ArrowRightLeft size={18} />
            }
            text="Voucher Transfer"
          />

        </div>

      </div>

      {/* =================================================
          BOOK GENERATION
      ================================================= */}

      {activeTab === "generation" && (

        <div className="
          bg-white
          rounded-xl
          shadow
          p-6
        ">

          <h2 className="
            text-xl
            font-bold
            mb-5
          ">
            Gift Voucher Book Code Generation
          </h2>

          <div className="
            grid
            grid-cols-1
            md:grid-cols-2
            gap-5
          ">

            <Input
              label="Gift Voucher Group *"
              name="groupCode"
              value={groupForm.groupCode}
              onChange={handleGroupChange}
              placeholder="Enter group code"
            />

            <Input
              label="Group Name *"
              name="groupName"
              value={groupForm.groupName}
              onChange={handleGroupChange}
              placeholder="Enter group name"
            />

            <div>

              <label className="
                block
                font-medium
                mb-2
              ">
                Based On
              </label>

              <select
                name="basedOn"
                value={groupForm.basedOn}
                onChange={handleGroupChange}
                className="
                  w-full
                  border
                  rounded-lg
                  px-3
                  py-3
                "
              >

                <option>
                  Book Serial
                </option>

                <option>
                  Voucher Serial
                </option>

              </select>

            </div>

            <Input
              label="Gift Voucher Value"
              name="voucherValue"
              type="number"
              value={
                groupForm.voucherValue
              }
              onChange={handleGroupChange}
            />

            <Input
              label="Validity Period (Days)"
              name="validityDays"
              type="number"
              value={
                groupForm.validityDays
              }
              onChange={handleGroupChange}
            />

            <Input
              label="Percentage of Coupon (%)"
              name="percentageOfCoupon"
              type="number"
              value={
                groupForm.percentageOfCoupon
              }
              onChange={handleGroupChange}
            />

          </div>

          <div className="
            mt-6
            flex
            justify-end
            gap-3
          ">

            <button
              onClick={() =>
                setGroupForm({
                  groupCode: "",
                  groupName: "",
                  basedOn: "Book Serial",
                  voucherValue: "",
                  validityDays: "",
                  percentageOfCoupon: ""
                })
              }
              className="
                px-5
                py-3
                rounded-lg
                border
                hover:bg-gray-50
              "
            >
              Clear
            </button>

            <button
              onClick={saveGroup}
              disabled={loading}
              className="
                bg-orange-500
                text-white
                px-6
                py-3
                rounded-lg
                font-semibold
                hover:bg-orange-600
                disabled:opacity-50
              "
            >
              Save Group
            </button>

          </div>

          <hr className="my-8" />

          <h2 className="
            text-xl
            font-bold
            mb-5
          ">
            Generate Voucher Book
          </h2>

          <div className="
            grid
            grid-cols-1
            md:grid-cols-3
            gap-5
          ">

            <div>

              <label className="
                block
                font-medium
                mb-2
              ">
                Gift Voucher Group *
              </label>

              <select
                name="groupId"
                value={bookForm.groupId}
                onChange={handleBookChange}
                className="
                  w-full
                  border
                  rounded-lg
                  px-3
                  py-3
                "
              >

                <option value="">
                  Select Group
                </option>

                {groups.map(group => (
                  <option
                    key={
                      group.GiftVoucherGroupID
                    }
                    value={
                      group.GiftVoucherGroupID
                    }
                  >
                    {group.GroupCode}
                    {" - "}
                    {group.GroupName}
                  </option>
                ))}

              </select>

            </div>

            <Input
              label="Book Code *"
              name="bookCode"
              value={bookForm.bookCode}
              onChange={handleBookChange}
              placeholder="Enter book code"
            />

            <Input
              label="Book Name *"
              name="bookName"
              value={bookForm.bookName}
              onChange={handleBookChange}
              placeholder="Enter book name"
            />

            <Input
              label="Starting No *"
              name="startingNo"
              type="number"
              value={bookForm.startingNo}
              onChange={handleBookChange}
            />

            <Input
              label="Serial Length *"
              name="serialLength"
              type="number"
              value={bookForm.serialLength}
              onChange={handleBookChange}
            />

            <Input
              label="No of Vouchers on Book *"
              name="noOfVouchers"
              type="number"
              value={bookForm.noOfVouchers}
              onChange={handleBookChange}
            />

            <Input
              label="Voucher Prefix"
              name="voucherPrefix"
              value={bookForm.voucherPrefix}
              onChange={handleBookChange}
              placeholder="Optional prefix"
            />

            <Input
              label="Gift Voucher Value"
              name="voucherValue"
              type="number"
              value={bookForm.voucherValue}
              onChange={handleBookChange}
              placeholder="Override group value"
            />

            <Input
              label="Validity Period (Days)"
              name="validityDays"
              type="number"
              value={bookForm.validityDays}
              onChange={handleBookChange}
              placeholder="Override group validity"
            />

          </div>

          <div className="
            mt-6
            flex
            justify-end
          ">

            <button
              onClick={generateVouchers}
              disabled={loading}
              className="
                bg-orange-500
                hover:bg-orange-600
                text-white
                px-7
                py-3
                rounded-lg
                font-bold
                disabled:opacity-50
              "
            >

              <Plus
                size={18}
                className="inline mr-2"
              />

              Generate Vouchers

            </button>

          </div>

        </div>
      )}

      {/* =================================================
          MASTER
      ================================================= */}

      {activeTab === "master" && (

        <VoucherTable
          vouchers={vouchers}
          selectedVouchers={
            selectedVouchers
          }
          toggleVoucher={
            toggleVoucher
          }
          printVoucher={
            printVoucher
          }
          loadVouchers={
            loadVouchers
          }
          search={
            search
          }
          setSearch={
            setSearch
          }
          loading={
            loading
          }
          showSelect={true}
          exportProducts={
            exportProducts
          }
        />

      )}

      {/* =================================================
          BARCODE
      ================================================= */}

      {activeTab === "barcode" && (

        <div className="
          bg-white
          rounded-xl
          shadow
          p-6
        ">

          <h2 className="
            text-xl
            font-bold
            mb-5
          ">
            Gift Voucher Barcode
          </h2>

          <div className="
            grid
            md:grid-cols-3
            gap-4
            mb-5
          ">

            <Input
              label="Voucher No"
              value={
                search.voucherNo
              }
              onChange={e =>
                setSearch({
                  ...search,
                  voucherNo:
                    e.target.value
                })
              }
            />

            <Input
              label="Voucher Serial"
              value={
                search.serial
              }
              onChange={e =>
                setSearch({
                  ...search,
                  serial:
                    e.target.value
                })
              }
            />

            <div className="
              flex
              items-end
            ">

              <button
                onClick={loadVouchers}
                className="
                  w-full
                  bg-blue-600
                  text-white
                  py-3
                  rounded-lg
                  hover:bg-blue-700
                "
              >

                <Search
                  size={18}
                  className="inline mr-2"
                />

                Load Data

              </button>

            </div>

          </div>

          <VoucherTable
            vouchers={vouchers}
            selectedVouchers={[]}
            toggleVoucher={() => {}}
            printVoucher={
              printVoucher
            }
            loadVouchers={
              loadVouchers
            }
            search={
              search
            }
            setSearch={
              setSearch
            }
            loading={
              loading
            }
            showSelect={false}
            exportProducts={
              exportProducts
            }
          />

        </div>

      )}

      {/* =================================================
          TRANSFER
      ================================================= */}

      {activeTab === "transfer" && (

        <div className="
          bg-white
          rounded-xl
          shadow
          p-6
        ">

          <div className="
            flex
            justify-between
            items-center
            mb-5
          ">

            <h2 className="
              text-xl
              font-bold
            ">
              Gift Voucher Transfer
            </h2>

            <div className="flex gap-2">

              <button
                onClick={generateDocumentNo}
                className="
                  px-4
                  py-2
                  bg-gray-100
                  rounded-lg
                  hover:bg-gray-200
                  transition-colors
                "
              >
                Generate Document No
              </button>

              <button
                onClick={() => {
                  setShowHistory(
                    !showHistory
                  );

                  if (!showHistory) {
                    loadTransferHistory();
                  }

                  setShowTransferDetails(
                    false
                  );
                }}
                className="
                  px-4
                  py-2
                  bg-blue-100
                  text-blue-700
                  rounded-lg
                  hover:bg-blue-200
                  transition-colors
                "
              >

                <History
                  size={18}
                  className="inline mr-1"
                />

                {showHistory
                  ? "Hide History"
                  : "View History"}

              </button>

              <button
                onClick={loadLocations}
                className="
                  px-4
                  py-2
                  bg-green-100
                  text-green-700
                  rounded-lg
                  hover:bg-green-200
                  transition-colors
                "
                disabled={
                  locationsLoading
                }
              >

                <RefreshCw
                  size={18}
                  className={`inline mr-1 ${
                    locationsLoading
                      ? "animate-spin"
                      : ""
                  }`}
                />

                Refresh Locations

              </button>

            </div>

          </div>

          {/* Transfer History */}

          {showHistory && (

            <div className="
              mb-5
              p-4
              bg-gray-50
              rounded-lg
              max-h-80
              overflow-y-auto
            ">

              <h3 className="
                font-semibold
                mb-3
                flex
                justify-between
                items-center
              ">

                <span>
                  Transfer History
                </span>

                <button
                  onClick={() => {
                    setShowTransferDetails(
                      false
                    );

                    loadTransferHistory();
                  }}
                  className="
                    text-sm
                    text-blue-600
                    hover:text-blue-800
                  "
                >

                  <RefreshCw
                    size={14}
                    className="inline"
                  />

                  {" "}Refresh

                </button>

              </h3>

              {transferHistory.length === 0 ? (

                <p className="
                  text-gray-500
                  text-sm
                ">
                  No transfer history found
                </p>

              ) : (

                <table className="
                  w-full
                  text-sm
                ">

                  <thead>

                    <tr className="
                      text-left
                      bg-gray-200
                    ">

                      <th className="p-2">
                        Document No
                      </th>

                      <th className="p-2">
                        VoucherSerial
                      </th>

                      <th className="p-2">
                        To Location
                      </th>

                      <th className="p-2">
                        Vouchers Value
                      </th>

                      <th className="p-2">
                        Expiry Date
                      </th>

                      <th className="p-2">
                        Transfer Date
                      </th>

                      <th className="p-2">
                        UsedDate
                      </th>

                      <th className="p-2">
                        Receipt
                      </th>

                    </tr>

                  </thead>

                  <tbody>

                    {transferHistory.map(
                      (history, index) => (

                        <tr
                          key={`${history.DocumentNo}-${history.VoucherSerial}-${index}`}
                          className="
                            border-b
                            hover:bg-gray-100
                          "
                        >

                          <td className="
                            p-2
                            font-semibold
                          ">
                            {history.DocumentNo ||
                              "-"}
                          </td>

                          <td className="p-2">
                            {history.VoucherSerial ||
                              "-"}
                          </td>

                          <td className="p-2">
                            {getLocationName(
                              history.ToLocation
                            )}
                          </td>

                          <td className="
                            p-2
                            text-center
                          ">
                            {history.VoucherValue !=
                            null
                              ? Number(
                                  history.VoucherValue
                                ).toFixed(2)
                              : "0.00"}
                          </td>

                          <td className="p-2">
                            {history.ExpiryDate
                              ? new Date(
                                  history.ExpiryDate
                                ).toLocaleString()
                              : "-"}
                          </td>

                          <td className="p-2">
                            {history.TransferDate
                              ? new Date(
                                  history.TransferDate
                                ).toLocaleString()
                              : "-"}
                          </td>

                          <td className="p-2">
                            {history.UsedDate
                              ? new Date(
                                  history.UsedDate
                                ).toLocaleString()
                              : "-"}
                          </td>

                          <td className="
                            p-2
                            text-center
                          ">
                            {history.UsedReceipt ||
                              "-"}
                          </td>

                        </tr>

                      )
                    )}

                  </tbody>

                </table>

              )}

              {/* Transfer Details Modal */}

              {showTransferDetails &&
                transferDetails.length > 0 && (

                  <div className="
                    mt-4
                    p-4
                    bg-white
                    rounded-lg
                    border
                    border-gray-200
                  ">

                    <div className="
                      flex
                      justify-between
                      items-center
                      mb-3
                    ">

                      <h4 className="
                        font-semibold
                        text-gray-700
                      ">

                        Transfer Details -{" "}
                        {
                          transferDetails[0]
                            ?.DocumentNo
                        }

                      </h4>

                      <button
                        onClick={() =>
                          setShowTransferDetails(
                            false
                          )
                        }
                        className="
                          text-gray-500
                          hover:text-gray-700
                        "
                      >

                        <X size={18} />

                      </button>

                    </div>

                    <table className="
                      w-full
                      text-sm
                    ">

                      <thead>

                        <tr className="
                          text-left
                          bg-gray-100
                        ">

                          <th className="p-2">
                            Voucher No
                          </th>

                          <th className="p-2">
                            Serial
                          </th>

                          <th className="p-2">
                            Value
                          </th>

                        </tr>

                      </thead>

                      <tbody>

                        {transferDetails.map(
                          detail => (

                            <tr
                              key={
                                detail.GiftVoucherTransferDetID
                              }
                              className="border-b"
                            >

                              <td className="
                                p-2
                                font-semibold
                              ">
                                {
                                  detail.VoucherNo
                                }
                              </td>

                              <td className="p-2">
                                {
                                  detail.VoucherSerial
                                }
                              </td>

                              <td className="p-2">
                                Rs.{" "}
                                {Number(
                                  detail.VoucherValue
                                ).toFixed(2)}
                              </td>

                            </tr>

                          )
                        )}

                      </tbody>

                      <tfoot>

                        <tr className="font-bold">

                          <td
                            colSpan="2"
                            className="
                              p-2
                              text-right
                            "
                          >
                            Total:
                          </td>

                          <td className="p-2">
                            Rs.{" "}
                            {transferDetails
                              .reduce(
                                (
                                  sum,
                                  d
                                ) =>
                                  sum +
                                  Number(
                                    d.VoucherValue
                                  ),
                                0
                              )
                              .toFixed(2)}
                          </td>

                        </tr>

                      </tfoot>

                    </table>

                  </div>

                )}

            </div>

          )}

          <div className="
            grid
            md:grid-cols-3
            gap-5
          ">

            <Input
              label="Document No *"
              value={
                transfer.documentNo
              }
              onChange={e =>
                setTransfer({
                  ...transfer,
                  documentNo:
                    e.target.value
                })
              }
              placeholder="Enter document number"
            />

            <div>

              <label className="
                block
                font-medium
                mb-2
              ">
                To Location *
              </label>

              <select
                value={
                  transfer.toLocationId
                }
                onChange={e =>
                  setTransfer({
                    ...transfer,
                    toLocationId:
                      e.target.value
                  })
                }
                className="
                  w-full
                  border
                  border-gray-300
                  rounded-lg
                  px-3
                  py-3
                  outline-none
                  focus:ring-2
                  focus:ring-orange-400
                "
                disabled={
                  locationsLoading
                }
              >

                <option value="">
                  {locationsLoading
                    ? "Loading locations..."
                    : "Select Location"}
                </option>

                {locations.map(
                  location => (

                    <option
                      key={
                        location.LocationID
                      }
                      value={
                        location.LocationID
                      }
                    >
                      {
                        location.LocationCode
                      }
                      {" - "}
                      {
                        location.LocationName
                      }
                    </option>

                  )
                )}

              </select>

              {locations.length === 0 &&
                !locationsLoading && (

                  <p className="
                    text-red-500
                    text-sm
                    mt-1
                  ">
                    No locations available.
                    Please refresh locations.
                  </p>

                )}

            </div>

            <Input
              label="Reference"
              value={
                transfer.reference
              }
              onChange={e =>
                setTransfer({
                  ...transfer,
                  reference:
                    e.target.value
                })
              }
              placeholder="Enter reference number"
            />

            <Input
              label="Remark"
              value={
                transfer.remark
              }
              onChange={e =>
                setTransfer({
                  ...transfer,
                  remark:
                    e.target.value
                })
              }
              placeholder="Enter remarks"
            />

          </div>

          {/* Selected Vouchers Summary */}

          {selectedVouchers.length > 0 && (

            <div className="
              mt-4
              p-4
              bg-blue-50
              rounded-lg
              border
              border-blue-200
            ">

              <div className="
                flex
                justify-between
                items-center
              ">

                <h4 className="
                  font-semibold
                  text-blue-800
                ">
                  Selected Vouchers (
                  {selectedVouchers.length}
                  )
                </h4>

                <button
                  onClick={() =>
                    setSelectedVouchers([])
                  }
                  className="
                    text-red-500
                    text-sm
                    hover:text-red-700
                  "
                >
                  Clear All
                </button>

              </div>

              <div className="
                flex
                flex-wrap
                gap-2
                mt-2
              ">

                {getSelectedVoucherDetails().map(
                  v => (

                    <span
                      key={
                        v.GiftVoucherID
                      }
                      className="
                        bg-blue-100
                        text-blue-800
                        px-3
                        py-1
                        rounded-full
                        text-sm
                        flex
                        items-center
                        gap-2
                      "
                    >

                      {v.VoucherNo}

                      <button
                        onClick={() =>
                          toggleVoucher(
                            v.GiftVoucherID
                          )
                        }
                        className="
                          text-red-500
                          hover:text-red-700
                        "
                      >

                        <X size={14} />

                      </button>

                    </span>

                  )
                )}

              </div>

              {getSelectedVoucherDetails()
                .length > 0 && (

                <div className="
                  mt-3
                  text-sm
                  text-gray-600
                ">

                  Total Value: Rs.{" "}

                  {getSelectedVoucherDetails()
                    .reduce(
                      (sum, v) =>
                        sum +
                        Number(
                          v.VoucherValue
                        ),
                      0
                    )
                    .toFixed(2)}

                </div>

              )}

            </div>

          )}

          <div className="mt-6">

            <div className="
              flex
              justify-between
              items-center
              mb-3
            ">

              <h3 className="font-bold">
                Available Vouchers
              </h3>

              <button
                onClick={
                  selectAllVouchers
                }
                className="
                  text-sm
                  text-blue-600
                  hover:text-blue-800
                "
              >

                {selectedVouchers.length ===
                  vouchers.filter(
                    v =>
                      v.Status ===
                      "Available"
                  ).length &&
                vouchers.length > 0
                  ? "Deselect All"
                  : "Select All"}

              </button>

            </div>

            <VoucherTable
              vouchers={vouchers}
              selectedVouchers={
                selectedVouchers
              }
              toggleVoucher={
                toggleVoucher
              }
              printVoucher={
                printVoucher
              }
              loadVouchers={
                loadVouchers
              }
              search={
                search
              }
              setSearch={
                setSearch
              }
              loading={
                loading
              }
              showSelect={true}
              exportProducts={
                exportProducts
              }
            />

          </div>

          <div className="
            mt-5
            flex
            justify-end
            gap-3
          ">

            <button
              onClick={() => {
                setSelectedVouchers([]);

                setTransfer({
                  documentNo: "",
                  toLocationId: "",
                  reference: "",
                  remark: ""
                });
              }}
              className="
                border
                px-5
                py-3
                rounded-lg
                hover:bg-gray-50
                transition-colors
              "
            >
              Clear All
            </button>

            <button
              onClick={
                transferVouchers
              }
              disabled={
                loading ||
                selectedVouchers.length ===
                  0 ||
                !transfer.toLocationId ||
                !transfer.documentNo
              }
              className="
                bg-orange-500
                text-white
                px-7
                py-3
                rounded-lg
                font-bold
                disabled:opacity-50
                disabled:cursor-not-allowed
                hover:bg-orange-600
                transition-colors
              "
            >

              <ArrowRightLeft
                size={18}
                className="inline mr-2"
              />

              Transfer Selected (
              {selectedVouchers.length}
              )

            </button>

          </div>

        </div>

      )}

    </div>
  );
}

/* =========================================================
   TAB BUTTON
========================================================= */

function TabButton({
  active,
  onClick,
  icon,
  text
}) {
  return (
    <button
      onClick={onClick}
      className={`
        flex
        items-center
        gap-2
        px-5
        py-4
        whitespace-nowrap
        font-semibold
        border-b-2
        transition-colors
        ${
          active
            ? "border-orange-500 text-orange-500"
            : "border-transparent text-gray-600 hover:text-gray-800 hover:border-gray-300"
        }
      `}
    >
      {icon}
      {text}
    </button>
  );
}

/* =========================================================
   INPUT
========================================================= */

function Input({
  label,
  name,
  value,
  onChange,
  type = "text",
  placeholder = ""
}) {
  return (
    <div>

      <label className="
        block
        font-medium
        mb-2
      ">
        {label}
      </label>

      <input
        name={name}
        type={type}
        value={value}
        onChange={onChange}
        placeholder={placeholder}
        className="
          w-full
          border
          border-gray-300
          rounded-lg
          px-3
          py-3
          outline-none
          focus:ring-2
          focus:ring-orange-400
          transition-shadow
        "
      />

    </div>
  );
}

/* =========================================================
   VOUCHER TABLE
========================================================= */

function VoucherTable({
  vouchers,
  selectedVouchers,
  toggleVoucher,
  printVoucher,
  loadVouchers,
  search,
  setSearch,
  loading,
  showSelect = true,
  exportProducts
}) {
  return (
    <div className="
      bg-white
      rounded-xl
      shadow
      p-5
    ">

      {/* =================================================
          SEARCH + EXPORT BUTTONS
      ================================================= */}

      <div className="
        flex
        flex-wrap
        gap-3
        mb-5
      ">

        <input
          value={search.voucherNo}
          onChange={e =>
            setSearch({
              ...search,
              voucherNo:
                e.target.value
            })
          }
          placeholder="Search voucher no..."
          className="
            border
            rounded-lg
            px-3
            py-2
            outline-none
            focus:ring-2
            focus:ring-orange-400
          "
        />

        <input
          value={search.serial}
          onChange={e =>
            setSearch({
              ...search,
              serial:
                e.target.value
            })
          }
          placeholder="Search serial..."
          className="
            border
            rounded-lg
            px-3
            py-2
            outline-none
            focus:ring-2
            focus:ring-orange-400
          "
        />

        <button
          onClick={loadVouchers}
          className="
            bg-blue-600
            text-white
            px-5
            py-2
            rounded-lg
            hover:bg-blue-700
            transition-colors
          "
        >

          <Search
            size={17}
            className="inline mr-2"
          />

          Search

        </button>

        <button
          onClick={() =>
            setSearch({
              voucherNo: "",
              serial: "",
              status: ""
            })
          }
          className="
            border
            px-5
            py-2
            rounded-lg
            hover:bg-gray-50
            transition-colors
          "
        >

          <RefreshCw
            size={17}
            className="inline mr-2"
          />

          Clear

        </button>

        {/* =================================================
            EXPORT CSV
        ================================================= */}

        <button
          onClick={() =>
            exportProducts("csv")
          }
          disabled={
            !vouchers ||
            vouchers.length === 0
          }
          className="
            bg-green-600
            text-white
            px-5
            py-2
            rounded-lg
            hover:bg-green-700
            disabled:opacity-50
            disabled:cursor-not-allowed
            transition-colors
          "
        >
          Export CSV
        </button>

        {/* =================================================
            EXPORT TXT
        ================================================= */}

        <button
          onClick={() =>
            exportProducts("txt")
          }
          disabled={
            !vouchers ||
            vouchers.length === 0
          }
          className="
            bg-gray-700
            text-white
            px-5
            py-2
            rounded-lg
            hover:bg-gray-800
            disabled:opacity-50
            disabled:cursor-not-allowed
            transition-colors
          "
        >
          Export TXT
        </button>

      </div>

      {/* =================================================
          TABLE
      ================================================= */}

      <div className="
        overflow-x-auto
      ">

        <table className="
          w-full
          border-collapse
        ">

          <thead>

            <tr className="
              bg-gray-100
              text-left
            ">

              {showSelect && (
                <th className="p-3">
                  Select
                </th>
              )}

              <th className="p-3">
                Voucher No
              </th>

              <th className="p-3">
                Voucher Serial
              </th>

              <th className="p-3">
                Book
              </th>

              <th className="p-3">
                Value
              </th>

              <th className="p-3">
                Status
              </th>

              <th className="p-3">
                Expiry
              </th>

              <th className="p-3">
                Action
              </th>

            </tr>

          </thead>

          <tbody>

            {vouchers.length === 0 ? (

              <tr>

                <td
                  colSpan={
                    showSelect
                      ? "8"
                      : "7"
                  }
                  className="
                    text-center
                    p-8
                    text-gray-500
                  "
                >

                  {loading
                    ? "Loading..."
                    : "No vouchers found"}

                </td>

              </tr>

            ) : (

              vouchers.map(
                voucher => (

                  <tr
                    key={
                      voucher.GiftVoucherID
                    }
                    className="
                      border-b
                      hover:bg-gray-50
                    "
                  >

                    {showSelect && (
                      <td className="p-3">

                        <input
                          type="checkbox"
                          checked={selectedVouchers.includes(
                            voucher.GiftVoucherID
                          )}
                          onChange={() =>
                            toggleVoucher(
                              voucher.GiftVoucherID
                            )
                          }
                          disabled={
                            voucher.Status !==
                            "Available"
                          }
                          className="cursor-pointer"
                        />

                      </td>
                    )}

                    <td className="
                      p-3
                      font-semibold
                    ">
                      {voucher.VoucherNo}
                    </td>

                    {/* =================================================
                        VOUCHER SERIAL + PRINT BUTTON
                    ================================================= */}

                    <td className="p-3">

                      <div className="
                        flex
                        items-center
                        gap-2
                      ">

                        <span className="
                          font-mono
                          font-semibold
                        ">
                          {voucher.VoucherSerial}
                        </span>

                     

                      </div>

                    </td>

                    <td className="p-3">
                      {voucher.BookCode}
                    </td>

                    <td className="
                      p-3
                      font-bold
                    ">
                      Rs.{" "}
                      {Number(
                        voucher.VoucherValue
                      ).toFixed(2)}
                    </td>

                    <td className="p-3">

                      <span
                        className={`
                          px-3
                          py-1
                          rounded-full
                          text-xs
                          font-semibold
                          ${
                            voucher.Status ===
                            "Available"
                              ? "bg-green-100 text-green-700"
                              : voucher.Status ===
                                "Transferred"
                              ? "bg-blue-100 text-blue-700"
                              : voucher.Status ===
                                "Redeemed"
                              ? "bg-purple-100 text-purple-700"
                              : "bg-gray-100 text-gray-700"
                          }
                        `}
                      >
                        {voucher.Status ||
                          "Unknown"}
                      </span>

                    </td>

                    <td className="p-3">

                      {voucher.ExpiryDate
                        ? new Date(
                            voucher.ExpiryDate
                          ).toLocaleDateString()
                        : "-"}

                    </td>

                    <td className="p-3">

                      <button
                        onClick={() =>
                          printVoucher(
                            voucher
                          )
                        }
                        className="
                          bg-gray-800
                          text-white
                          px-3
                          py-2
                          rounded-lg
                          hover:bg-gray-700
                          transition-colors
                        "
                        title="Print Voucher"
                      >

                        <Printer
                          size={16}
                          className="inline"
                        />

                      </button>

                    </td>

                  </tr>

                )
              )

            )}

          </tbody>

        </table>

      </div>

    </div>
  );
}