import React, { useEffect, useState, useContext } from "react";
import axios from "axios";

// ← PERM: shared adapter (previously inlined in Employee.jsx)
import { usePermissions } from "../hooks/usePermissions.jsx";
import { AuthContext } from "./SERVER/AuthContext.js";

const API = "http://localhost:5000";

const emptyForm = {
  CashierID: 0,
  Code: "",
  LocationID: "",
  Name: "",
  LogName: "",
  Password: "",
  Encode: "",
  Type: 0,
};

export default function Cashier() {
  const { user } = useContext(AuthContext);              // ← PERM (optional, kept for symmetry)

  // =========================================================
  // PERMISSIONS                                            // ← PERM
  // =========================================================
  const { can } = usePermissions();                      // ← PERM

  const canViewCashier   = can("Cashier", "View");       // ← PERM
  const canAddCashier    = can("Cashier", "Add");        // ← PERM
  const canEditCashier   = can("Cashier", "Edit");       // ← PERM
  const canDeleteCashier = can("Cashier", "Delete");     // ← PERM

  const [form, setForm] = useState(emptyForm);
  const [cashiers, setCashiers] = useState([]);
  const [loading, setLoading] = useState(false);
  const [loadingList, setLoadingList] = useState(false);

  // =========================================================
  // LOAD CASHIERS
  // =========================================================
  const loadCashiers = async () => {
    try {
      setLoadingList(true);

      const response = await axios.get(`${API}/cashiers`);

      setCashiers(Array.isArray(response.data) ? response.data : []);
    } catch (error) {
      console.error("Load cashiers error:", error);
      alert(error.response?.data?.message || "Unable to load cashiers");
    } finally {
      setLoadingList(false);
    }
  };

  useEffect(() => {
    loadCashiers();
  }, []);

  // =========================================================
  // HANDLE INPUT
  // =========================================================
  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((previous) => ({ ...previous, [name]: value }));
  };

  // =========================================================
  // RESET FORM
  // =========================================================
  const clearForm = () => {
    setForm({ ...emptyForm });
  };

  // =========================================================
  // NEW CASHIER                                            // ← PERM (new helper)
  // =========================================================
  const handleNew = () => {
    if (!canAddCashier) {
      alert("You do not have permission to create cashiers.");
      return;
    }
    clearForm();
  };

  // =========================================================
  // SAVE CASHIER
  // =========================================================
  const saveCashier = async (e) => {
    e.preventDefault();

    // ----- Permission guards (before validation) -----      // ← PERM
    if (form.CashierID && !canEditCashier) {
      alert("You do not have permission to edit cashiers.");
      return;
    }
    if (!form.CashierID && !canAddCashier) {
      alert("You do not have permission to create cashiers.");
      return;
    }

    // -------------------------
    // Validation
    // -------------------------
    if (!form.Code.trim()) {
      alert("Cashier Code is required.");
      return;
    }
    if (!form.Name.trim()) {
      alert("Cashier Name is required.");
      return;
    }
    if (!form.LogName.trim()) {
      alert("Login Name is required.");
      return;
    }
    if (!form.LocationID) {
      alert("Location ID is required.");
      return;
    }
    if (!form.CashierID && !form.Password.trim()) {
      alert("Password is required when creating a cashier.");
      return;
    }

    try {
      setLoading(true);

      // =====================================================
      // UPDATE
      // =====================================================
      if (form.CashierID) {
        const payload = {
          CashierID: form.CashierID,
          Code: form.Code.trim(),
          LocationID: Number(form.LocationID),
          Name: form.Name.trim(),
          LogName: form.LogName.trim(),
          Type: Number(form.Type),
          Encode: form.Encode.trim(),
        };

        if (form.Password.trim()) {
          payload.Password = form.Password;
        }

        await axios.put(`${API}/cashiers/${form.CashierID}`, payload);
        alert("Cashier updated successfully.");
      }

      // =====================================================
      // CREATE
      // =====================================================
      else {
        const payload = {
          Code: form.Code.trim(),
          LocationID: Number(form.LocationID),
          Name: form.Name.trim(),
          LogName: form.LogName.trim(),
          Password: form.Password,
          Encode: form.Encode.trim(),
          Type: Number(form.Type),
        };

        await axios.post(`${API}/cashiers`, payload);
        alert("Cashier created successfully.");
      }

      clearForm();
      await loadCashiers();
    } catch (error) {
      console.error("Save cashier error:", error);
      alert(error.response?.data?.message || "Unable to save cashier.");
    } finally {
      setLoading(false);
    }
  };

  // =========================================================
  // EDIT CASHIER
  // =========================================================
  const editCashier = (cashier) => {
    if (!canEditCashier) {                                  // ← PERM
      alert("You do not have permission to edit cashiers.");
      return;
    }

    setForm({
      CashierID: cashier.CashierID ?? 0,
      Code: cashier.Code ?? "",
      LocationID: cashier.LocationID ?? "",
      Name: cashier.Name ?? "",
      LogName: cashier.LogName ?? "",
      Password: "",
      Encode: cashier.Encode ?? "",
      Type: cashier.Type ?? 0,
    });

    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  // =========================================================
  // DELETE CASHIER
  // =========================================================
  const deleteCashier = async (cashierID) => {
    if (!canDeleteCashier) {                                // ← PERM
      alert("You do not have permission to delete cashiers.");
      return;
    }

    const confirmed = window.confirm(
      "Are you sure you want to delete this cashier?"
    );
    if (!confirmed) return;

    try {
      await axios.delete(`${API}/cashiers/${cashierID}`);
      alert("Cashier deleted successfully.");

      if (form.CashierID === cashierID) {
        clearForm();
      }

      await loadCashiers();
    } catch (error) {
      console.error("Delete cashier error:", error);
      alert(error.response?.data?.message || "Unable to delete cashier.");
    }
  };

  // =========================================================
  // COMPUTED                                               // ← PERM
  // =========================================================
  const isEditing = Boolean(form.CashierID);
  const saveAllowed =
    (isEditing && canEditCashier) || (!isEditing && canAddCashier);
  const readOnlyEdit = isEditing && !canEditCashier;

  // =========================================================
  // READ-ONLY EARLY EXIT                                   // ← PERM (optional)
  // ---------------------------------------------------------
  // If the user has no View permission at all, don't even
  // render the module. The route-level <RequirePermission>
  // should catch this, but this is a defence-in-depth check.
  // =========================================================
  if (!canViewCashier) {
    return (
      <div className="p-6">
        <div className="rounded-xl border border-red-200 bg-red-50 p-6 text-red-700">
          <h2 className="text-lg font-bold">Access Denied</h2>
          <p className="text-sm mt-1">
            You do not have permission to view Cashiers.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6">
      {/* =====================================================
          PAGE TITLE
      ===================================================== */}
      <div className="mb-6 flex items-start justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">
            Cashier Management
          </h1>
          <p className="text-gray-500 mt-1">
            Create and manage system cashiers.
          </p>
        </div>

        {/* ← PERM: "New" shortcut, only when user can Add */}
        {canAddCashier && (
          <button
            type="button"
            onClick={handleNew}
            className="bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-lg font-medium"
          >
            + New Cashier
          </button>
        )}
      </div>

      {/* =====================================================
          FORM
      ===================================================== */}
      <div className="bg-white rounded-xl shadow p-6 mb-8">
        <div className="flex items-center justify-between mb-5">
          <h2 className="text-lg font-semibold text-gray-800">
            {isEditing ? "Edit Cashier" : "Create Cashier"}
          </h2>

          {/* ← PERM: read-only banner when editing without Edit permission */}
          {readOnlyEdit && (
            <span className="rounded-full bg-slate-200 px-3 py-1 text-xs font-semibold text-slate-600">
              READ ONLY
            </span>
          )}
        </div>

        <form
          onSubmit={saveCashier}
          className="grid grid-cols-1 md:grid-cols-2 gap-4"
        >
          {/* Cashier Code */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Cashier Code
            </label>
            <input
              type="text"
              name="Code"
              value={form.Code}
              onChange={handleChange}
              maxLength={50}
              placeholder="Enter cashier code"
              className="w-full border rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          {/* Cashier Name */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Cashier Name
            </label>
            <input
              type="text"
              name="Name"
              value={form.Name}
              onChange={handleChange}
              maxLength={250}
              placeholder="Enter cashier name"
              className="w-full border rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          {/* Login Name */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Login Name
            </label>
            <input
              type="text"
              name="LogName"
              value={form.LogName}
              onChange={handleChange}
              maxLength={250}
              placeholder="Enter login name"
              className="w-full border rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          {/* Password */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Password
              {isEditing && (
                <span className="text-gray-400 ml-2">
                  (leave blank to keep current password)
                </span>
              )}
            </label>
            <input
              type="password"
              name="Password"
              value={form.Password}
              onChange={handleChange}
              maxLength={250}
              placeholder={isEditing ? "New password" : "Enter password"}
              className="w-full border rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          {/* Location ID */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Location ID
            </label>
            <input
              type="number"
              name="LocationID"
              value={form.LocationID}
              onChange={handleChange}
              min="1"
              placeholder="Enter location ID"
              className="w-full border rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          {/* Type */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Cashier Type
            </label>
            <input
              type="number"
              name="Type"
              value={form.Type}
              onChange={handleChange}
              placeholder="Cashier type"
              className="w-full border rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          {/* Encode */}
          <div className="md:col-span-2">
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Encode
            </label>
            <input
              type="text"
              name="Encode"
              value={form.Encode}
              onChange={handleChange}
              maxLength={250}
              placeholder="Encode value (optional)"
              className="w-full border rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          {/* =================================================
              BUTTONS                                       // ← PERM
          ================================================= */}
          <div className="md:col-span-2 flex flex-wrap gap-3 pt-2">
            {saveAllowed && (
              <button
                type="submit"
                disabled={loading}
                className="bg-blue-600 hover:bg-blue-700 disabled:bg-blue-300 text-white px-6 py-3 rounded-lg font-medium"
              >
                {loading
                  ? "Saving..."
                  : isEditing
                  ? "Update Cashier"
                  : "Save Cashier"}
              </button>
            )}

            <button
              type="button"
              onClick={clearForm}
              disabled={loading}
              className="bg-gray-500 hover:bg-gray-600 text-white px-6 py-3 rounded-lg font-medium"
            >
              Clear
            </button>

            {readOnlyEdit && (
              <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 text-xs font-semibold text-slate-500">
                You have read-only access — editing is disabled.
              </div>
            )}

            {!isEditing && !canAddCashier && (
              <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 text-xs font-semibold text-slate-500">
                You do not have permission to create new cashiers.
              </div>
            )}
          </div>
        </form>
      </div>

      {/* =====================================================
          CASHIER TABLE
      ===================================================== */}
      <div className="bg-white rounded-xl shadow overflow-hidden">
        <div className="p-5 border-b">
          <h2 className="text-lg font-semibold">Cashiers</h2>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full">
            <thead className="bg-gray-100">
              <tr>
                <th className="p-3 text-left">ID</th>
                <th className="p-3 text-left">Code</th>
                <th className="p-3 text-left">Name</th>
                <th className="p-3 text-left">Login Name</th>
                <th className="p-3 text-left">Location</th>
                <th className="p-3 text-left">Type</th>
                <th className="p-3 text-center">Action</th>
              </tr>
            </thead>

            <tbody>
              {loadingList ? (
                <tr>
                  <td colSpan="7" className="p-8 text-center text-gray-500">
                    Loading cashiers...
                  </td>
                </tr>
              ) : cashiers.length === 0 ? (
                <tr>
                  <td colSpan="7" className="p-8 text-center text-gray-500">
                    No cashiers found.
                  </td>
                </tr>
              ) : (
                cashiers.map((cashier) => (
                  <tr
                    key={cashier.CashierID}
                    className="border-t hover:bg-gray-50"
                  >
                    <td className="p-3">{cashier.CashierID}</td>
                    <td className="p-3 font-medium">{cashier.Code}</td>
                    <td className="p-3">{cashier.Name}</td>
                    <td className="p-3">{cashier.LogName}</td>
                    <td className="p-3">{cashier.LocationID}</td>
                    <td className="p-3">{cashier.Type}</td>

                    {/* ← PERM: only render buttons the user can use */}
                    <td className="p-3">
                      <div className="flex justify-center gap-2">
                        {canEditCashier && (
                          <button
                            type="button"
                            onClick={() => editCashier(cashier)}
                            className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded"
                          >
                            Edit
                          </button>
                        )}

                        {canDeleteCashier && (
                          <button
                            type="button"
                            onClick={() => deleteCashier(cashier.CashierID)}
                            className="bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded"
                          >
                            Delete
                          </button>
                        )}

                        {!canEditCashier && !canDeleteCashier && (
                          <span className="text-xs text-slate-400">
                            No actions
                          </span>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}