import React, { useContext, useEffect, useMemo, useState } from "react";
import axios from "axios";
import { AuthContext } from "./SERVER/AuthContext.js";

// ← PERM
import { usePermissions } from "../hooks/usePermissions.jsx";

const API_URL = "http://localhost:5000";

const emptyForm = {
  InvSubCategoryID: "",
  DepartmentCode: "",
  Department: "",
  Category: "",
  SubCategoryCode: "",
  SubCategoryName: "",
  Remark: "",
  username: "",
};

function Subcatagory() {
  const { user } = useContext(AuthContext);

  // =====================================================
  // PERMISSIONS                                        // ← PERM
  // =====================================================
  const { can, loading: permissionsLoading } = usePermissions();  // ← PERM

  const canViewSubCategory   = can("SubCategory", "View");        // ← PERM
  const canAddSubCategory    = can("SubCategory", "Add");         // ← PERM
  const canEditSubCategory   = can("SubCategory", "Edit");        // ← PERM
  const canDeleteSubCategory = can("SubCategory", "Delete");      // ← PERM

  const [form, setForm] = useState(emptyForm);

  const [departments, setDepartments] = useState([]);
  const [categories, setCategories] = useState([]);
  const [subcategories, setSubcategories] = useState([]);

  const [search, setSearch] = useState("");
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);

  const [editMode, setEditMode] = useState(false);

  const username = user?.username || "";

  // --------------------------------------------------
  // HANDLE FORM CHANGE
  // --------------------------------------------------
  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  // --------------------------------------------------
  // LOAD DEPARTMENTS  (unchanged)
  // --------------------------------------------------
  const loadDepartments = async () => {
    try {
      const response = await axios.get(`${API_URL}/departments`);

      let departmentData = [];
      if (response.data && response.data.success && Array.isArray(response.data.data)) {
        departmentData = response.data.data;
      } else if (Array.isArray(response.data)) {
        departmentData = response.data;
      }

      setDepartments(departmentData);
    } catch (error) {
      console.error("LOAD DEPARTMENTS ERROR:", error.response?.data || error.message);
      setDepartments([]);
      alert(error.response?.data?.message || "Unable to load departments.");
    }
  };

  // --------------------------------------------------
  // LOAD CATEGORIES  (unchanged)
  // --------------------------------------------------
  const loadCategories = async () => {
    try {
      const response = await axios.get(`${API_URL}/subcategorycategories`);

      let categoryData = [];
      if (response.data && response.data.success && Array.isArray(response.data.data)) {
        categoryData = response.data.data;
      } else if (Array.isArray(response.data)) {
        categoryData = response.data;
      }

      setCategories(categoryData);
    } catch (error) {
      console.error("LOAD CATEGORIES ERROR:", error.response?.data || error.message);
      setCategories([]);
      alert(error.response?.data?.message || "Unable to load categories.");
    }
  };

  // --------------------------------------------------
  // LOAD SUBCATEGORIES  (unchanged)
  // --------------------------------------------------
  const loadSubCategories = async () => {
    try {
      setLoading(true);

      const response = await axios.get(`${API_URL}/subcategories`);

      let subcategoryData = [];
      if (response.data && response.data.success && Array.isArray(response.data.data)) {
        subcategoryData = response.data.data;
      } else if (Array.isArray(response.data)) {
        subcategoryData = response.data;
      }

      setSubcategories(subcategoryData);
    } catch (error) {
      console.error("LOAD SUBCATEGORIES ERROR:", error.response?.data || error.message);
      setSubcategories([]);
      alert(error.response?.data?.message || "Unable to load subcategories.");
    } finally {
      setLoading(false);
    }
  };

  // --------------------------------------------------
  // GENERATE NEXT SUBCATEGORY CODE  (unchanged)
  // --------------------------------------------------
  const generateSubCategoryCode = async () => {
    try {
      const response = await axios.get(`${API_URL}/subcategorycode`);

      let rows = [];
      if (response.data && response.data.success && Array.isArray(response.data.data)) {
        rows = response.data.data;
      } else if (Array.isArray(response.data)) {
        rows = response.data;
      }

      if (rows.length === 0) return "001";

      const lastCode = rows[0]?.SubCategoryCode || rows[0]?.subcategorycode || "";
      const numberPart = parseInt(String(lastCode).replace(/\D/g, ""), 10) || 0;

      return String(numberPart + 1).padStart(3, "0");
    } catch (error) {
      console.error("GENERATE SUBCATEGORY CODE ERROR:", error.response?.data || error.message);
      return "001";
    }
  };

  // --------------------------------------------------
  // INITIAL LOAD
  // --------------------------------------------------
  useEffect(() => {
    // ← PERM: wait for permissions + skip if no view
    if (permissionsLoading) return;                       // ← PERM
    if (!canViewSubCategory) return;                      // ← PERM

    const loadInitialData = async () => {
      await Promise.all([
        loadDepartments(),
        loadCategories(),
        loadSubCategories(),
      ]);
    };

    loadInitialData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [canViewSubCategory, permissionsLoading]);           // ← PERM

  // --------------------------------------------------
  // DEPARTMENT CHANGE  (unchanged)
  // --------------------------------------------------
  const handleDepartmentChange = (e) => {
    const departmentCode = e.target.value;

    const selectedDepartment = departments.find(
      (department) => String(department.DepartmentCode) === String(departmentCode)
    );

    const departmentName = selectedDepartment?.DepartmentName || "";
    const departmentText = departmentCode ? `${departmentCode} - ${departmentName}` : "";

    setForm((prev) => ({
      ...prev,
      DepartmentCode: departmentCode,
      Department: departmentText,
      Category: "",
    }));
  };

  // --------------------------------------------------
  // CATEGORY LIST FILTERED BY DEPARTMENT  (unchanged)
  // --------------------------------------------------
  const filteredCategories = useMemo(() => {
    if (!form.DepartmentCode) return [];

    return categories.filter((category) => {
      const categoryDepartment = String(category.Department || "").trim();
      const selectedCode = String(form.DepartmentCode || "").trim();
      const selectedDepartment = String(form.Department || "").trim();

      return (
        categoryDepartment === selectedCode ||
        categoryDepartment === selectedDepartment ||
        categoryDepartment.startsWith(`${selectedCode} -`)
      );
    });
  }, [categories, form.DepartmentCode, form.Department]);

  const handleCategoryChange = (e) => {
    const categoryValue = e.target.value;
    setForm((prev) => ({ ...prev, Category: categoryValue }));
  };

  // --------------------------------------------------
  // NEW
  // --------------------------------------------------
  const handleNew = async () => {
    // ← PERM
    if (!canAddSubCategory) {                              // ← PERM
      alert("You do not have permission to create subcategories.");
      return;
    }

    const nextCode = await generateSubCategoryCode();

    setForm((prev) => ({
      ...prev,
      DepartmentCode: prev.DepartmentCode,
      Department: prev.Department,
      Category: prev.Category,
      InvSubCategoryID: "",
      SubCategoryCode: nextCode,
      SubCategoryName: "",
      Remark: "",
      username,
    }));

    setEditMode(false);
  };

  // --------------------------------------------------
  // SAVE / UPDATE
  // --------------------------------------------------
  const handleSubmit = async (e) => {
    e.preventDefault();

    // ----- Permission guards -----                        // ← PERM
    if (editMode && form.InvSubCategoryID && !canEditSubCategory) {
      alert("You do not have permission to edit subcategories.");
      return;
    }
    if ((!editMode || !form.InvSubCategoryID) && !canAddSubCategory) {
      alert("You do not have permission to create subcategories.");
      return;
    }

    const departmentCode = String(form.DepartmentCode || "").trim();
    const category       = String(form.Category || "").trim();
    const subCategoryCode = String(form.SubCategoryCode || "").trim();
    const subCategoryName = String(form.SubCategoryName || "").trim();
    const remark          = String(form.Remark || "").trim();

    // VALIDATION
    if (!departmentCode)  { alert("Please select Department."); return; }
    if (!category)        { alert("Please select Category."); return; }
    if (!subCategoryCode) { alert("Please enter SubCategory Code."); return; }
    if (!subCategoryName) { alert("Please enter SubCategory Name."); return; }

    const payload = {
      Category: category,
      SubCategoryCode: subCategoryCode,
      SubCategoryName: subCategoryName,
      Remark: remark,
      username,
    };

    try {
      setSaving(true);

      if (editMode && form.InvSubCategoryID) {
        await axios.put(
          `${API_URL}/subcategory/${form.InvSubCategoryID}`,
          payload
        );
        alert("SubCategory updated successfully.");
      } else {
        await axios.post(`${API_URL}/subcategory`, payload);
        alert("SubCategory saved successfully.");
      }

      const currentDepartmentCode = form.DepartmentCode;
      const currentDepartment     = form.Department;
      const currentCategory       = form.Category;

      const nextCode = await generateSubCategoryCode();

      setForm({
        InvSubCategoryID: "",
        DepartmentCode: currentDepartmentCode,
        Department: currentDepartment,
        Category: currentCategory,
        SubCategoryCode: nextCode,
        SubCategoryName: "",
        Remark: "",
        username,
      });

      setEditMode(false);
      await loadSubCategories();
    } catch (error) {
      console.error("SAVE SUBCATEGORY ERROR:", error.response?.data || error.message);
      alert(error.response?.data?.message || "Error saving SubCategory.");
    } finally {
      setSaving(false);
    }
  };

  // --------------------------------------------------
  // EDIT
  // --------------------------------------------------
  const handleEdit = (item) => {
    // ← PERM
    if (!canEditSubCategory) {                             // ← PERM
      alert("You do not have permission to edit subcategories.");
      return;
    }

    const categoryValue =
      item.Category ||
      (item.CategoryCode && item.CategoryName
        ? `${item.CategoryCode} - ${item.CategoryName}`
        : "");

    let departmentCode = "";
    let departmentText = item.Department || "";

    if (item.DepartmentCode) {
      departmentCode = item.DepartmentCode;
    }

    if (!departmentCode && departmentText) {
      const departmentTextTrimmed = String(departmentText).trim();

      const foundDepartment = departments.find((department) => {
        const fullName = `${department.DepartmentCode} - ${department.DepartmentName}`;
        return (
          String(department.DepartmentCode).trim() === departmentTextTrimmed ||
          fullName.trim() === departmentTextTrimmed ||
          String(department.DepartmentName).trim() === departmentTextTrimmed
        );
      });

      if (foundDepartment) {
        departmentCode = foundDepartment.DepartmentCode;
        departmentText = `${foundDepartment.DepartmentCode} - ${foundDepartment.DepartmentName}`;
      }
    }

    if (!departmentCode && item.Department) {
      const departmentTextTrimmed = String(item.Department).trim();

      const foundDepartment = departments.find((department) => {
        const fullName = `${department.DepartmentCode} - ${department.DepartmentName}`;
        return (
          fullName.trim() === departmentTextTrimmed ||
          String(department.DepartmentName).trim() === departmentTextTrimmed ||
          String(department.DepartmentCode).trim() === departmentTextTrimmed
        );
      });

      if (foundDepartment) {
        departmentCode = foundDepartment.DepartmentCode;
        departmentText = `${foundDepartment.DepartmentCode} - ${foundDepartment.DepartmentName}`;
      }
    }

    setForm({
      InvSubCategoryID: item.InvSubCategoryID || "",
      DepartmentCode: departmentCode,
      Department: departmentText,
      Category: categoryValue,
      SubCategoryCode: item.SubCategoryCode || "",
      SubCategoryName: item.SubCategoryName || "",
      Remark: item.Remark || "",
      username,
    });

    setEditMode(true);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  // --------------------------------------------------
  // DELETE
  // --------------------------------------------------
  const handleDelete = async (id) => {
    // ← PERM
    if (!canDeleteSubCategory) {                           // ← PERM
      alert("You do not have permission to delete subcategories.");
      return;
    }

    if (!id) {
      alert("Invalid SubCategory ID.");
      return;
    }

    const confirmed = window.confirm(
      "Are you sure you want to delete this SubCategory?"
    );
    if (!confirmed) return;

    try {
      await axios.delete(`${API_URL}/subcategory/${id}`, {
        data: { username },
      });

      alert("SubCategory deleted successfully.");
      await loadSubCategories();

      if (String(form.InvSubCategoryID) === String(id)) {
        setEditMode(false);
        setForm((prev) => ({
          ...prev,
          InvSubCategoryID: "",
          SubCategoryCode: "",
          SubCategoryName: "",
          Remark: "",
        }));
      }
    } catch (error) {
      console.error("DELETE SUBCATEGORY ERROR:", error.response?.data || error.message);
      alert(error.response?.data?.message || "Error deleting SubCategory.");
    }
  };

  // --------------------------------------------------
  // CANCEL EDIT  (unchanged)
  // --------------------------------------------------
  const handleCancel = () => {
    setEditMode(false);
    setForm((prev) => ({
      ...prev,
      InvSubCategoryID: "",
      SubCategoryCode: "",
      SubCategoryName: "",
      Remark: "",
      username,
    }));
  };

  // --------------------------------------------------
  // SEARCH  (unchanged)
  // --------------------------------------------------
  const filteredSubCategories = useMemo(() => {
    const searchText = String(search || "").trim().toLowerCase();
    if (!searchText) return subcategories;

    return subcategories.filter((item) => {
      const code       = String(item.SubCategoryCode || "").toLowerCase();
      const name       = String(item.SubCategoryName || "").toLowerCase();
      const category   = String(item.Category || "").toLowerCase();
      const department = String(item.Department || "").toLowerCase();

      return (
        code.includes(searchText) ||
        name.includes(searchText) ||
        category.includes(searchText) ||
        department.includes(searchText)
      );
    });
  }, [subcategories, search]);

  // =====================================================
  // COMPUTED                                           // ← PERM
  // =====================================================
  const isEditing = Boolean(form.InvSubCategoryID) && editMode;
  const saveAllowed =
    (isEditing && canEditSubCategory) ||
    (!isEditing && canAddSubCategory);
  const readOnlyEdit = isEditing && !canEditSubCategory;

  // =====================================================
  // ACCESS GATE                                        // ← PERM
  // =====================================================
  if (permissionsLoading) {                                // ← PERM
    return (
      <div className="min-h-screen bg-gray-100 p-6 flex items-center justify-center text-gray-500">
        Checking permissions…
      </div>
    );
  }

  if (!canViewSubCategory) {                               // ← PERM
    return (
      <div className="min-h-screen bg-gray-100 p-6">
        <div className="mx-auto max-w-xl mt-20 rounded-xl border border-red-200 bg-red-50 p-8 text-center">
          <h2 className="text-lg font-bold text-red-700">Access Denied</h2>
          <p className="text-sm text-red-600 mt-2">
            You do not have permission to view SubCategory Master.
          </p>
          <p className="text-xs text-red-400 mt-3">
            Module: <code>SubCategory</code>
          </p>
        </div>
      </div>
    );
  }

  // --------------------------------------------------
  // RENDER
  // --------------------------------------------------
  return (
    <div className="min-h-screen bg-gray-100 p-4 md:p-6">
      <div className="mx-auto max-w-7xl">

        {/* HEADER */}
        <div className="mb-6 rounded-xl bg-white p-5 shadow-sm">
          <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
            <div>
              <h1 className="text-2xl font-bold text-gray-800">
                SubCategory Master
              </h1>
              <p className="mt-1 text-sm text-gray-500">
                Create and manage product subcategories
              </p>
            </div>

            <div className="flex items-center gap-2">
              {/* ← PERM: read-only badge */}
              {readOnlyEdit && (                            /* ← PERM */
                <span className="rounded-full bg-slate-200 px-3 py-1 text-xs font-semibold text-slate-600">
                  READ ONLY
                </span>
              )}

              {/* ← PERM: New button only when can Add */}
              {canAddSubCategory && (                       /* ← PERM */
                <button
                  type="button"
                  onClick={handleNew}
                  className="rounded-lg bg-blue-600 px-5 py-2.5 font-semibold text-white shadow-sm transition hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-300"
                >
                  + New
                </button>
              )}

              {editMode && (
                <button
                  type="button"
                  onClick={handleCancel}
                  className="rounded-lg bg-gray-500 px-5 py-2.5 font-semibold text-white transition hover:bg-gray-600"
                >
                  Cancel
                </button>
              )}
            </div>
          </div>
        </div>

        {/* FORM */}
        <div className="mb-6 rounded-xl bg-white p-5 shadow-sm">
          <form onSubmit={handleSubmit}>
            <div className="grid grid-cols-1 gap-5 md:grid-cols-2">

              {/* DEPARTMENT */}
              <div>
                <label className="mb-1 block text-sm font-semibold text-gray-700">
                  Department <span className="ml-1 text-red-500">*</span>
                </label>

                <select
                  value={form.DepartmentCode}
                  onChange={handleDepartmentChange}
                  className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2.5 text-sm text-gray-800 focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
                >
                  <option value="">-- Select Department --</option>
                  {departments.map((department) => (
                    <option
                      key={department.InvDepartmentID}
                      value={department.DepartmentCode}
                    >
                      {department.DepartmentCode} - {department.DepartmentName}
                    </option>
                  ))}
                </select>

                {departments.length === 0 && (
                  <p className="mt-1 text-xs text-red-500">No departments found.</p>
                )}
              </div>

              {/* CATEGORY */}
              <div>
                <label className="mb-1 block text-sm font-semibold text-gray-700">
                  Category <span className="ml-1 text-red-500">*</span>
                </label>

                <select
                  value={form.Category}
                  onChange={handleCategoryChange}
                  disabled={!form.DepartmentCode}
                  className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2.5 text-sm text-gray-800 disabled:cursor-not-allowed disabled:bg-gray-100 focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
                >
                  <option value="">
                    {!form.DepartmentCode
                      ? "-- Select Department First --"
                      : "-- Select Category --"}
                  </option>

                  {filteredCategories.map((category) => {
                    const value = `${category.CategoryCode} - ${category.CategoryName}`;
                    return (
                      <option key={category.InvCategoryID} value={value}>
                        {value}
                      </option>
                    );
                  })}
                </select>

                {form.DepartmentCode && filteredCategories.length === 0 && (
                  <p className="mt-1 text-xs text-orange-500">
                    No categories found for this department.
                  </p>
                )}
              </div>

              {/* SUBCATEGORY CODE */}
              <div>
                <label className="mb-1 block text-sm font-semibold text-gray-700">
                  SubCategory Code <span className="ml-1 text-red-500">*</span>
                </label>

                <input
                  type="text"
                  name="SubCategoryCode"
                  value={form.SubCategoryCode}
                  onChange={handleChange}
                  disabled={editMode}
                  placeholder="001"
                  className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm disabled:cursor-not-allowed disabled:bg-gray-100 focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
                />
              </div>

              {/* SUBCATEGORY NAME */}
              <div>
                <label className="mb-1 block text-sm font-semibold text-gray-700">
                  SubCategory Name <span className="ml-1 text-red-500">*</span>
                </label>

                <input
                  type="text"
                  name="SubCategoryName"
                  value={form.SubCategoryName}
                  onChange={handleChange}
                  placeholder="Enter SubCategory Name"
                  maxLength={50}
                  className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
                />
              </div>

              {/* REMARK */}
              <div className="md:col-span-2">
                <label className="mb-1 block text-sm font-semibold text-gray-700">
                  Remark
                </label>

                <textarea
                  name="Remark"
                  value={form.Remark}
                  onChange={handleChange}
                  placeholder="Enter remark"
                  maxLength={150}
                  rows={3}
                  className="w-full resize-none rounded-lg border border-gray-300 px-3 py-2.5 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
                />
              </div>
            </div>

            {/* BUTTONS */}
            <div className="mt-6 flex flex-wrap gap-3">
              {/* ← PERM: Save / Update only when saveAllowed */}
              {saveAllowed && (                             /* ← PERM */
                <button
                  type="submit"
                  disabled={saving}
                  className="rounded-lg bg-green-600 px-6 py-2.5 font-semibold text-white shadow-sm transition hover:bg-green-700 disabled:cursor-not-allowed disabled:opacity-60"
                >
                  {saving
                    ? "Saving..."
                    : editMode
                    ? "Update SubCategory"
                    : "Save SubCategory"}
                </button>
              )}

              {editMode && (
                <button
                  type="button"
                  onClick={handleCancel}
                  className="rounded-lg bg-gray-500 px-6 py-2.5 font-semibold text-white transition hover:bg-gray-600"
                >
                  Cancel
                </button>
              )}

              {/* ← PERM: helper text when blocked */}
              {readOnlyEdit && (                            /* ← PERM */
                <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-2.5 text-xs font-semibold text-slate-500">
                  You have read-only access — editing is disabled.
                </div>
              )}

              {!editMode && !canAddSubCategory && (         /* ← PERM */
                <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-2.5 text-xs font-semibold text-slate-500">
                  You do not have permission to create new subcategories.
                </div>
              )}
            </div>
          </form>
        </div>

        {/* SEARCH */}
        <div className="mb-4 rounded-xl bg-white p-4 shadow-sm">
          <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
            <div className="w-full md:max-w-md">
              <label className="mb-1 block text-sm font-semibold text-gray-700">
                Search SubCategories
              </label>
              <input
                type="text"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search code, name, category..."
                className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
              />
            </div>

            <div className="text-sm text-gray-500">
              Total:{" "}
              <span className="font-semibold text-gray-800">
                {filteredSubCategories.length}
              </span>
            </div>
          </div>
        </div>

        {/* TABLE */}
        <div className="overflow-hidden rounded-xl bg-white shadow-sm">
          <div className="overflow-x-auto">
            <table className="min-w-full text-sm">
              <thead className="bg-gray-800 text-white">
                <tr>
                  <th className="whitespace-nowrap px-4 py-3 text-left font-semibold">#</th>
                  <th className="whitespace-nowrap px-4 py-3 text-left font-semibold">Department</th>
                  <th className="whitespace-nowrap px-4 py-3 text-left font-semibold">Category</th>
                  <th className="whitespace-nowrap px-4 py-3 text-left font-semibold">Code</th>
                  <th className="whitespace-nowrap px-4 py-3 text-left font-semibold">SubCategory Name</th>
                  <th className="whitespace-nowrap px-4 py-3 text-left font-semibold">Remark</th>
                  <th className="whitespace-nowrap px-4 py-3 text-center font-semibold">Actions</th>
                </tr>
              </thead>

              <tbody className="divide-y divide-gray-200">
                {loading ? (
                  <tr>
                    <td colSpan="7" className="px-4 py-8 text-center text-gray-500">
                      Loading SubCategories...
                    </td>
                  </tr>
                ) : filteredSubCategories.length === 0 ? (
                  <tr>
                    <td colSpan="7" className="px-4 py-8 text-center text-gray-500">
                      No SubCategories found.
                    </td>
                  </tr>
                ) : (
                  filteredSubCategories.map((item, index) => (
                    <tr
                      key={item.InvSubCategoryID || index}
                      className="transition hover:bg-gray-50"
                    >
                      <td className="px-4 py-3 text-gray-600">{index + 1}</td>
                      <td className="px-4 py-3 font-medium text-gray-700">
                        {item.Department || "-"}
                      </td>
                      <td className="px-4 py-3 text-gray-700">
                        {item.Category || "-"}
                      </td>
                      <td className="px-4 py-3 font-semibold text-blue-600">
                        {item.SubCategoryCode || "-"}
                      </td>
                      <td className="px-4 py-3 font-medium text-gray-800">
                        {item.SubCategoryName || "-"}
                      </td>
                      <td className="max-w-xs px-4 py-3 text-gray-600">
                        {item.Remark || "-"}
                      </td>

                      {/* ← PERM: gate action buttons */}
                      <td className="px-4 py-3">
                        <div className="flex justify-center gap-2">
                          {canEditSubCategory && (          /* ← PERM */
                            <button
                              type="button"
                              onClick={() => handleEdit(item)}
                              className="rounded-md bg-blue-500 px-3 py-1.5 text-xs font-semibold text-white hover:bg-blue-600"
                            >
                              Edit
                            </button>
                          )}

                          {canDeleteSubCategory && (        /* ← PERM */
                            <button
                              type="button"
                              onClick={() => handleDelete(item.InvSubCategoryID)}
                              className="rounded-md bg-red-500 px-3 py-1.5 text-xs font-semibold text-white hover:bg-red-600"
                            >
                              Delete
                            </button>
                          )}

                          {!canEditSubCategory && !canDeleteSubCategory && (
                            <span className="text-xs text-slate-400">
                              No actions
                            </span>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>

      </div>
    </div>
  );
}

export default Subcatagory;