import React, { useEffect, useMemo, useState } from "react";
import axios from "axios";

// ← PERM
import { usePermissions } from "../hooks/usePermissions.jsx";

const API = "http://localhost:5000";

export default function ProductManagement() {
  // =========================================================
  // PERMISSIONS                                            // ← PERM
  // =========================================================
  const {
    can,
    canField,
    loading: permissionsLoading,
  } = usePermissions();                                     // ← PERM

  const canViewProduct   = can("Product", "View");          // ← PERM
  const canAddProduct    = can("Product", "Add");           // ← PERM
  const canEditProduct   = can("Product", "Edit");          // ← PERM
  const canDeleteProduct = can("Product", "Delete");        // ← PERM

  const canViewCostPrice    = canField("Product", "CostPrice");     // ← PERM
  const canViewSellingPrice = canField("Product", "SellingPrice");  // ← PERM

  // =========================================================
  // BASIC STATES
  // =========================================================
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState("");
  const [typeFilter, setTypeFilter] = useState("All Types");
  const [mode, setMode] = useState("normal");
  const [priceMode, setPriceMode] = useState("retail");

  // LOCATION
  const [locations, setLocations] = useState([]);
  const [locationID, setLocationID] = useState("");
  const [loadingLocations, setLoadingLocations] = useState(false);

  // ADD PRODUCT
  const [showAddProduct, setShowAddProduct] = useState(false);
  const [newProduct, setNewProduct] = useState({
    ProductCode: "", BarCode: "", ReferenceCode1: "", ProductName: "",
    NameOnInvoice: "", Department: "", Category: "", SubCategory: "",
    Supplier: "", CostPrice: "", OrderPrice: "", SellingPrice: "",
    WholesalePrice: "", MinimumPrice: "", MaximumPrice: "",
    ReOrderLevel: "", ReOrderQty: "", ReOrderPeriod: "",
    IsActive: true, IsTax: false,
  });

  // EDIT PRODUCT
  const [editingProduct, setEditingProduct] = useState(null);

  // PRICE TIERS
  const [tiers, setTiers] = useState([]);
  const [showTierModal, setShowTierModal] = useState(false);
  const [tierLoading, setTierLoading] = useState(false);
  const [locationError, setLocationError] = useState("");

  const [newTier, setNewTier] = useState({
    Quantity: "", RetailCashPrice: "", RetailCreditPrice: "",
    WholesaleCashPrice: "", WholesaleCreditPrice: "",
  });

  // =========================================================
  // GET LOGGED USER
  // =========================================================
  const getCurrentUser = () => {
    try {
      return JSON.parse(localStorage.getItem("user") || "{}");
    } catch (error) {
      console.error("USER READ ERROR:", error);
      return {};
    }
  };

  // =========================================================
  // LOAD LOCATIONS
  // =========================================================
  const loadLocations = async () => {
    try {
      setLoadingLocations(true);
      setLocationError("");

      const response = await axios.get(`${API}/locations`);
      const data = response.data;

      const rows = Array.isArray(data)
        ? data
        : Array.isArray(data.locations)
          ? data.locations
          : Array.isArray(data.data)
            ? data.data
            : [];

      const normalizedLocations = rows
        .map((item) => ({
          LocationID: String(item.LocationID ?? item.locationID ?? item.id ?? ""),
          LocationName: item.LocationName ?? item.locationName ?? item.name ?? "",
        }))
        .filter((item) => item.LocationID && item.LocationName);

      setLocations(normalizedLocations);

      if (normalizedLocations.length === 0) {
        setLocationID("");
        setLocationError("No locations found.");
        return;
      }

      let savedLocationID = "";
      try {
        const savedUser = JSON.parse(localStorage.getItem("user") || "{}");
        savedLocationID = String(savedUser.LocationID ?? savedUser.locationID ?? "");
      } catch (e) {
        console.warn("Could not read saved user:", e);
      }

      const savedExists = normalizedLocations.some(
        (location) => location.LocationID === savedLocationID
      );

      if (savedExists) setLocationID(savedLocationID);
      else setLocationID(normalizedLocations[0].LocationID);
    } catch (error) {
      console.error("LOAD LOCATIONS ERROR:", error);
      setLocations([]);
      setLocationID("");

      if (error.response) {
        setLocationError(
          error.response.data?.message || `Server error: ${error.response.status}`
        );
      } else if (error.request) {
        setLocationError("Cannot connect to the backend server.");
      } else {
        setLocationError(error.message || "Failed to load locations.");
      }
    } finally {
      setLoadingLocations(false);
    }
  };

  useEffect(() => {
    // ← PERM
    if (permissionsLoading) return;
    if (!canViewProduct) return;

    loadLocations();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [canViewProduct, permissionsLoading]);              // ← PERM

  // =========================================================
  // LOAD PRODUCTS
  // =========================================================
  const fetchProducts = async () => {
    if (!locationID) {
      setProducts([]);
      return;
    }

    try {
      setLoading(true);

      const response = await axios.get(`${API}/product-management`, {
        params: { locationID: Number(locationID) },
      });

      if (response.data.success) {
        setProducts(response.data.products || []);
      } else {
        setProducts([]);
        alert(response.data.message || "Unable to load products");
      }
    } catch (error) {
      console.error("FETCH PRODUCTS ERROR:", error);
      setProducts([]);
      alert(error.response?.data?.message || "Unable to load products");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (locationID) fetchProducts();
    else setProducts([]);
  }, [locationID]);

  // =========================================================
  // SEARCH / FILTER
  // =========================================================
  const filteredProducts = useMemo(() => {
    return products.filter((product) => {
      const text = `${product.ProductCode || ""} ${product.ProductName || ""} ${product.Category || ""}`.toLowerCase();
      const searchMatch = text.includes(search.toLowerCase());
      const typeMatch = typeFilter === "All Types" || product.ProductType === typeFilter;
      return searchMatch && typeMatch;
    });
  }, [products, search, typeFilter]);

  // =========================================================
  // PRODUCT FORM CHANGE
  // =========================================================
  const handleProductChange = (e) => {
    const { name, value, type, checked } = e.target;
    setNewProduct((prev) => ({
      ...prev,
      [name]: type === "checkbox" ? checked : value,
    }));
  };

  const resetProductForm = () => {
    setNewProduct({
      ProductCode: "", BarCode: "", ReferenceCode1: "", ProductName: "",
      NameOnInvoice: "", Department: "", Category: "", SubCategory: "",
      Supplier: "", CostPrice: "", OrderPrice: "", SellingPrice: "",
      WholesalePrice: "", MinimumPrice: "", MaximumPrice: "",
      ReOrderLevel: "", ReOrderQty: "", ReOrderPeriod: "",
      IsActive: true, IsTax: false,
    });
  };

  // =========================================================
  // ADD PRODUCT
  // =========================================================
  const handleAddProduct = async () => {
    // ← PERM
    if (!canAddProduct) {
      alert("You do not have permission to add products.");
      return;
    }

    if (!locationID) { alert("Please select a location"); return; }
    if (!newProduct.ProductCode.trim()) { alert("Product code is required"); return; }
    if (!newProduct.ProductName.trim()) { alert("Product name is required"); return; }

    try {
      const user = getCurrentUser();

      const response = await axios.post(`${API}/product-master`, {
        ...newProduct,
        LocationID: Number(locationID),
        CreatedUser: user.Username || user.UserName || "SYSTEM",
      });

      if (response.data.success) {
        alert("Product added successfully");
        setShowAddProduct(false);
        resetProductForm();
        await fetchProducts();
      } else {
        alert(response.data.message || "Failed to add product");
      }
    } catch (error) {
      console.error("ADD PRODUCT ERROR:", error);
      alert(error.response?.data?.message || "Failed to add product");
    }
  };

  // =========================================================
  // EDIT PRODUCT
  // =========================================================
  const openEditProduct = (product) => {
    // ← PERM
    if (!canEditProduct) {
      alert("You do not have permission to edit products.");
      return;
    }

    setEditingProduct({ ...product });
  };

  const handleEditChange = (e) => {
    const { name, value } = e.target;
    setEditingProduct((prev) => ({ ...prev, [name]: value }));
  };

  const handleUpdateProduct = async () => {
    // ← PERM
    if (!canEditProduct) {
      alert("You do not have permission to edit products.");
      return;
    }

    if (!editingProduct) return;
    if (!locationID) { alert("Please select a location"); return; }

    try {
      const user = getCurrentUser();

      const response = await axios.put(
        `${API}/product-master/${editingProduct.InvProductMasterID}`,
        {
          ...editingProduct,
          LocationID: Number(locationID),
          ModifiedUser: user.Username || user.UserName || "SYSTEM",
        }
      );

      if (response.data.success) {
        alert("Product updated successfully");
        setEditingProduct(null);
        await fetchProducts();
      } else {
        alert(response.data.message || "Failed to update product");
      }
    } catch (error) {
      console.error("UPDATE PRODUCT ERROR:", error);
      alert(error.response?.data?.message || "Failed to update product");
    }
  };

  // =========================================================
  // DELETE PRODUCT
  // =========================================================
  const handleDeleteProduct = async (product) => {
    // ← PERM
    if (!canDeleteProduct) {
      alert("You do not have permission to delete products.");
      return;
    }

    const ok = window.confirm(`Delete ${product.ProductName}?`);
    if (!ok) return;

    if (!locationID) { alert("Please select a location"); return; }

    try {
      const response = await axios.delete(
        `${API}/product-master/${encodeURIComponent(product.ProductCode)}`,
        { params: { locationID: Number(locationID) } }
      );

      if (response.data.success) {
        alert("Product deleted successfully");
        await fetchProducts();
      } else {
        alert(response.data.message || "Failed to delete product");
      }
    } catch (error) {
      console.error("DELETE PRODUCT ERROR:", error);
      alert(error.response?.data?.message || "Failed to delete product");
    }
  };

  // =========================================================
  // LOAD TIERS
  // =========================================================
  const loadTiers = async () => {
    if (!locationID) { setTiers([]); return; }

    try {
      setTierLoading(true);

      const response = await axios.get(`${API}/product-price-tiers`, {
        params: { locationID: Number(locationID) },
      });

      if (response.data.success) setTiers(response.data.tiers || []);
      else setTiers([]);
    } catch (error) {
      console.error("LOAD TIERS ERROR:", error);
      setTiers([]);
    } finally {
      setTierLoading(false);
    }
  };

  useEffect(() => {
    // ← PERM: only load tiers if we could possibly edit them
    if (mode === "price" && locationID && canEditProduct) {   // ← PERM
      loadTiers();
    }
  }, [mode, locationID, canEditProduct]);                     // ← PERM

  const getProductTiers = (productCode) =>
    tiers
      .filter((tier) => String(tier.ProductCode) === String(productCode))
      .sort((a, b) => Number(a.Quantity) - Number(b.Quantity));

  const quantities = useMemo(() => {
    const quantitySet = new Set();
    tiers.forEach((tier) => {
      const quantity = Number(tier.Quantity);
      if (Number.isFinite(quantity) && quantity > 0) quantitySet.add(quantity);
    });
    return Array.from(quantitySet).sort((a, b) => a - b);
  }, [tiers]);

  // =========================================================
  // TIER OPERATIONS — all require Product.CanEdit         // ← PERM
  // =========================================================
  const openAddTier = () => {
    if (!canEditProduct) {                                  // ← PERM
      alert("You do not have permission to modify price tiers.");
      return;
    }

    if (!locationID) { alert("Please select a location"); return; }

    setNewTier({
      Quantity: "", RetailCashPrice: "", RetailCreditPrice: "",
      WholesaleCashPrice: "", WholesaleCreditPrice: "",
    });
    setShowTierModal(true);
  };

  const handleAddTier = async () => {
    if (!canEditProduct) {                                  // ← PERM
      alert("You do not have permission to modify price tiers.");
      return;
    }

    if (!locationID) { alert("Please select a location"); return; }

    const quantity = Number(newTier.Quantity);
    if (!quantity || quantity <= 0) { alert("Enter a valid quantity"); return; }

    const exists = quantities.some((q) => Number(q) === quantity);
    if (exists) { alert(`Q${quantity} already exists`); return; }

    try {
      const user = getCurrentUser();

      const response = await axios.post(`${API}/product-price-tier`, {
        LocationID: Number(locationID),
        Quantity: quantity,
        RetailCashPrice: Number(newTier.RetailCashPrice || 0),
        RetailCreditPrice: Number(newTier.RetailCreditPrice || 0),
        WholesaleCashPrice: Number(newTier.WholesaleCashPrice || 0),
        WholesaleCreditPrice: Number(newTier.WholesaleCreditPrice || 0),
        CreatedUser: user.Username || user.UserName || "SYSTEM",
      });

      if (response.data.success) {
        alert(`Q${quantity} tier added`);
        setShowTierModal(false);
        await loadTiers();
      } else {
        alert(response.data.message || "Failed to add tier");
      }
    } catch (error) {
      console.error("ADD TIER ERROR:", error);
      alert(error.response?.data?.message || "Failed to add tier");
    }
  };

  const updateTierPrice = (product, quantity, field, value) => {
    if (!canEditProduct) return;                            // ← PERM

    setTiers((prev) =>
      prev.map((tier) => {
        if (
          String(tier.ProductCode) === String(product.ProductCode) &&
          Number(tier.Quantity) === Number(quantity)
        ) {
          return { ...tier, [field]: value };
        }
        return tier;
      })
    );
  };

  const saveTier = async (product, quantity) => {
    if (!canEditProduct) return;                            // ← PERM
    if (!locationID) { alert("Please select a location"); return; }

    const tier = tiers.find(
      (x) =>
        String(x.ProductCode) === String(product.ProductCode) &&
        Number(x.Quantity) === Number(quantity)
    );
    if (!tier) return;

    try {
      const user = getCurrentUser();

      const response = await axios.put(`${API}/product-price-tier`, {
        LocationID: Number(locationID),
        ProductCode: product.ProductCode,
        Quantity: Number(quantity),
        RetailCashPrice: Number(tier.RetailCashPrice || 0),
        RetailCreditPrice: Number(tier.RetailCreditPrice || 0),
        WholesaleCashPrice: Number(tier.WholesaleCashPrice || 0),
        WholesaleCreditPrice: Number(tier.WholesaleCreditPrice || 0),
        ModifiedUser: user.Username || user.UserName || "SYSTEM",
      });

      if (!response.data.success) {
        alert(response.data.message || "Failed to save tier");
      }
    } catch (error) {
      console.error("SAVE TIER ERROR:", error);
      alert(error.response?.data?.message || "Failed to save tier");
    }
  };

  const updateBasePrice = (product, field, value) => {
    if (!canEditProduct) return;                            // ← PERM

    setProducts((prev) =>
      prev.map((p) =>
        p.InvProductMasterID === product.InvProductMasterID
          ? { ...p, [field]: value }
          : p
      )
    );
  };

  const saveBasePrice = async (product, field) => {
    if (!canEditProduct) return;                            // ← PERM
    if (!locationID) { alert("Please select a location"); return; }

    const value = product[field];

    try {
      const user = getCurrentUser();

      const response = await axios.put(`${API}/product-base-price`, {
        InvProductMasterID: product.InvProductMasterID,
        ProductCode: product.ProductCode,
        LocationID: Number(locationID),
        field,
        value: Number(value || 0),
        ModifiedUser: user.Username || user.UserName || "SYSTEM",
      });

      if (!response.data.success) {
        alert(response.data.message || "Failed to update price");
        await fetchProducts();
      }
    } catch (error) {
      console.error("BASE PRICE ERROR:", error);
      alert(error.response?.data?.message || "Failed to update price");
      await fetchProducts();
    }
  };

  // =========================================================
  // ACCESS GATE                                            // ← PERM
  // =========================================================
  if (permissionsLoading) {                                 // ← PERM
    return (
      <div className="min-h-screen bg-white p-6 flex items-center justify-center text-gray-500">
        Checking permissions…
      </div>
    );
  }

  if (!canViewProduct) {                                    // ← PERM
    return (
      <div className="min-h-screen bg-white p-6">
        <div className="mx-auto max-w-xl mt-20 rounded-2xl border border-red-200 bg-red-50 p-8 text-center">
          <h2 className="text-lg font-bold text-red-700">Access Denied</h2>
          <p className="text-sm text-red-600 mt-2">
            You do not have permission to view Product Management.
          </p>
          <p className="text-xs text-red-400 mt-3">
            Module: <code>Product</code>
          </p>
        </div>
      </div>
    );
  }

  // =========================================================
  // RENDER
  // =========================================================
  return (
    <div className="min-h-screen bg-white p-6">

      {/* HEADER */}
      <div className="flex items-center justify-between mb-7">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">
            Product Management
          </h1>
          <p className="text-gray-500">Manage your product inventory</p>

          {/* ← PERM: read-only badge */}
          {!canEditProduct && (                                /* ← PERM */
            <span className="mt-2 inline-block rounded-full bg-slate-200 px-3 py-1 text-xs font-semibold text-slate-600">
              READ ONLY
            </span>
          )}
        </div>

        <div className="flex gap-2">
          <button
            type="button"
            onClick={() => setMode("normal")}
            className={`px-5 py-3 rounded-xl border ${
              mode === "normal" ? "bg-gray-100" : "bg-white"
            }`}
          >
            ✎ Quick Edit Mode
          </button>

          {/* ← PERM: Price Change Mode requires Edit */}
          {canEditProduct && (                                 /* ← PERM */
            <button
              type="button"
              onClick={() => setMode(mode === "price" ? "normal" : "price")}
              className={`px-5 py-3 rounded-xl ${
                mode === "price" ? "bg-orange-500 text-white" : "border bg-white"
              }`}
            >
              ◇ {mode === "price" ? "Exit Price Change" : "Price Change Mode"}
            </button>
          )}

          {/* ← PERM: Add Product requires Add */}
          {canAddProduct && (                                  /* ← PERM */
            <button
              type="button"
              onClick={() => setShowAddProduct(true)}
              disabled={!locationID}
              className="px-5 py-3 rounded-xl bg-orange-500 text-white font-semibold hover:bg-orange-600 disabled:opacity-50"
            >
              ＋ Add Product
            </button>
          )}

          <button
            type="button"
            onClick={() => alert("Scale Download function can be connected here.")}
            className="px-5 py-3 rounded-xl border bg-white"
          >
            ⚖ Scale Download
          </button>
        </div>
      </div>

      {/* MAIN CARD */}
      <div className="border rounded-xl overflow-hidden">

        {/* CARD HEADER */}
        <div className="p-5">
          <h2 className="text-2xl font-bold mb-4">
            📦 Products ({filteredProducts.length} / {products.length})
          </h2>

          <div className="flex gap-4 items-center">
            <input
              type="text"
              placeholder="⌕  Search products..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-[380px] border rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-orange-400"
            />

            <select
              value={typeFilter}
              onChange={(e) => setTypeFilter(e.target.value)}
              className="border rounded-xl px-4 py-3"
            >
              <option value="All Types">All Types</option>
              <option value="Product">Product</option>
              <option value="Service">Service</option>
            </select>

            <select
              value={locationID}
              onChange={(e) => setLocationID(e.target.value)}
              disabled={loadingLocations}
              className="border rounded-xl px-4 py-3 min-w-[220px]"
            >
              <option value="">
                {loadingLocations ? "Loading locations..." : "Select Location"}
              </option>
              {locations.map((location) => (
                <option key={location.LocationID} value={location.LocationID}>
                  {location.LocationName}
                </option>
              ))}
            </select>

            <button
              type="button"
              onClick={fetchProducts}
              disabled={loading || !locationID}
              className="px-4 py-3 border rounded-xl hover:bg-gray-50 disabled:opacity-50"
            >
              ↻
            </button>
          </div>
        </div>

        {/* NORMAL MODE */}
        {mode === "normal" && (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead>
                <tr className="border-t border-b bg-gray-50">
                  <th className="text-left p-4">Image</th>
                  <th className="text-left p-4">Code</th>
                  <th className="text-left p-4">Name</th>
                  <th className="text-left p-4">Category</th>
                  <th className="text-left p-4">Stock</th>
                  <th className="text-left p-4">Location</th>
                  <th className="text-left p-4">Unit</th>
                  {/* ← PERM: hide price columns when user can't view */}
                  {canViewCostPrice && (                         /* ← PERM */
                    <th className="text-left p-4">Buying Price</th>
                  )}
                  {canViewSellingPrice && (                      /* ← PERM */
                    <th className="text-left p-4">Selling Price</th>
                  )}
                  <th className="text-left p-4">Status</th>
                  <th className="text-left p-4">Actions</th>
                </tr>
              </thead>

              <tbody>
                {loading ? (
                  <tr>
                    <td colSpan="11" className="text-center p-10">
                      Loading products...
                    </td>
                  </tr>
                ) : filteredProducts.length === 0 ? (
                  <tr>
                    <td colSpan="11" className="text-center p-10 text-gray-500">
                      {locationID ? "No products found" : "Please select a location"}
                    </td>
                  </tr>
                ) : (
                  filteredProducts.map((product) => {
                    const stock = Number(product.Stock || 0);

                    return (
                      <tr
                        key={product.InvProductMasterID}
                        className="border-b hover:bg-gray-50"
                      >
                        <td className="p-4">
                          <div className="w-12 h-12 bg-gray-100 rounded-lg flex items-center justify-center text-2xl">
                            📦
                          </div>
                        </td>

                        <td className="p-4 font-mono text-sm">{product.ProductCode}</td>
                        <td className="p-4 font-medium">{product.ProductName}</td>
                        <td className="p-4">{product.Category || "-"}</td>
                        <td className="p-4">{stock}</td>
                        <td className="p-4">{product.LocationID || locationID}</td>
                        <td className="p-4">{product.UnitName || "Nos"}</td>

                        {/* ← PERM: field-level masking */}
                        {canViewCostPrice && (                   /* ← PERM */
                          <td className="p-4">
                            LKR {Number(product.CostPrice || 0).toFixed(2)}
                          </td>
                        )}
                        {canViewSellingPrice && (                /* ← PERM */
                          <td className="p-4">
                            LKR {Number(product.SellingPrice || 0).toFixed(2)}
                          </td>
                        )}

                        <td className="p-4">
                          {stock < 0 ? (
                            <span className="bg-red-500 text-white px-3 py-1 rounded-full text-sm">
                              Negative Stock
                            </span>
                          ) : stock === 0 ? (
                            <span className="bg-gray-400 text-white px-3 py-1 rounded-full text-sm">
                              Out of Stock
                            </span>
                          ) : (
                            <span className="bg-orange-500 text-white px-3 py-1 rounded-full text-sm">
                              In Stock
                            </span>
                          )}
                        </td>

                        <td className="p-4">
                          <div className="flex gap-2">
                            {/* ← PERM: Edit button */}
                            {canEditProduct && (             /* ← PERM */
                              <button
                                type="button"
                                onClick={() => openEditProduct(product)}
                                className="w-10 h-10 border rounded-lg hover:bg-gray-100"
                              >
                                ✎
                              </button>
                            )}

                            {/* ← PERM: Delete button */}
                            {canDeleteProduct && (           /* ← PERM */
                              <button
                                type="button"
                                onClick={() => handleDeleteProduct(product)}
                                className="w-10 h-10 border rounded-lg text-red-500 hover:bg-red-50"
                              >
                                🗑
                              </button>
                            )}

                            {!canEditProduct && !canDeleteProduct && (
                              <span className="text-xs text-slate-400">
                                No actions
                              </span>
                            )}
                          </div>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
        )}

        {/* PRICE CHANGE MODE — only reachable when canEditProduct */}
        {mode === "price" && (                                   /* ← PERM */
          <div>
            {/* PRICE TABS */}
            <div className="px-5 pt-3">
              <div className="flex gap-2">
                <button
                  type="button"
                  onClick={() => setPriceMode("retail")}
                  className={`px-5 py-3 rounded-xl ${
                    priceMode === "retail" ? "bg-orange-500 text-white" : "border bg-white"
                  }`}
                >
                  Retail Prices
                </button>
                <button
                  type="button"
                  onClick={() => setPriceMode("wholesale")}
                  className={`px-5 py-3 rounded-xl ${
                    priceMode === "wholesale" ? "bg-orange-500 text-white" : "border bg-white"
                  }`}
                >
                  Wholesale Prices
                </button>
              </div>

              <div className="bg-orange-50 border-l-4 border-orange-500 p-3 mt-4 text-sm text-gray-600">
                {priceMode === "retail"
                  ? "Retail Mode - Edit retail prices"
                  : "Wholesale Mode - Edit wholesale prices"}
              </div>
            </div>

            {/* PRICE TABLE */}
            <div className="overflow-auto max-h-[650px] mt-4">
              <table className="w-full min-w-[1200px]">
                <thead className="sticky top-0 z-10">
                  <tr>
                    <th colSpan="6" className="bg-blue-100 p-4 text-center border-r-4 border-blue-400">
                      Product Master
                    </th>
                    <th colSpan={quantities.length + 1} className="bg-green-100 p-4 text-center">
                      Quantity Price Tiers
                    </th>
                  </tr>

                  <tr className="bg-blue-50">
                    <th className="p-3 text-left">Code</th>
                    <th className="p-3 text-left">Product</th>
                    {/* ← PERM: hide Cost header */}
                    {canViewCostPrice && (                    /* ← PERM */
                      <th className="p-3">Cost</th>
                    )}
                    {canViewSellingPrice && (                 /* ← PERM */
                      <th className="p-3">MRP</th>
                    )}
                    <th className="p-3">Stock</th>
                    <th className="p-3 border-r-4 border-blue-400">
                      Q1 Base
                      <div className="text-xs text-gray-500">Base Price</div>
                    </th>

                    {quantities.map((quantity) => (
                      <th key={quantity} className="p-3 min-w-[190px] bg-green-50">
                        Q{quantity}
                        <div className="text-xs text-gray-500">Cash / Credit</div>
                      </th>
                    ))}

                    <th className="p-3 bg-green-50">
                      <button
                        type="button"
                        onClick={openAddTier}
                        className="text-orange-500 text-2xl font-bold hover:text-orange-700"
                      >
                        +
                      </button>
                    </th>
                  </tr>
                </thead>

                <tbody>
                  {tierLoading && filteredProducts.length === 0 ? (
                    <tr>
                      <td colSpan={7 + quantities.length} className="p-10 text-center">
                        Loading price tiers...
                      </td>
                    </tr>
                  ) : filteredProducts.length === 0 ? (
                    <tr>
                      <td colSpan={7 + quantities.length} className="p-10 text-center text-gray-500">
                        No products found
                      </td>
                    </tr>
                  ) : (
                    filteredProducts.map((product) => {
                      const productTiers = getProductTiers(product.ProductCode);

                      const cashField =
                        priceMode === "retail"
                          ? "RetailCashPrice"
                          : "WholesaleCashPrice";
                      const creditField =
                        priceMode === "retail"
                          ? "RetailCreditPrice"
                          : "WholesaleCreditPrice";

                      return (
                        <tr key={product.InvProductMasterID} className="border-b">
                          <td className="p-3 font-mono text-sm">{product.ProductCode}</td>

                          <td className="p-3">
                            <div className="flex items-center gap-2">
                              <span>{product.ProductName}</span>
                              <button
                                type="button"
                                onClick={openAddTier}
                                className="text-orange-500 font-bold text-xl"
                              >
                                +
                              </button>
                            </div>
                          </td>

                          {/* ← PERM: cost cell */}
                          {canViewCostPrice && (           /* ← PERM */
                            <td className="p-3">
                              <input
                                type="number"
                                value={product.CostPrice ?? ""}
                                onChange={(e) => updateBasePrice(product, "CostPrice", e.target.value)}
                                onBlur={() =>
                                  saveBasePrice(
                                    { ...product, CostPrice: product.CostPrice },
                                    "CostPrice"
                                  )
                                }
                                className="w-24 border rounded px-2 py-1"
                              />
                            </td>
                          )}

                          {/* ← PERM: MRP cell */}
                          {canViewSellingPrice && (        /* ← PERM */
                            <td className="p-3">
                              <input
                                type="number"
                                value={product.MaximumPrice ?? ""}
                                onChange={(e) => updateBasePrice(product, "MaximumPrice", e.target.value)}
                                onBlur={() => saveBasePrice(product, "MaximumPrice")}
                                className="w-24 border rounded px-2 py-1"
                              />
                            </td>
                          )}

                          <td className="p-3 text-center">{product.Stock}</td>

                          {/* BASE PRICE */}
                          <td className="p-3 border-r-4 border-blue-400">
                            <div className="flex items-center gap-1">
                              <input
                                type="number"
                                value={
                                  priceMode === "retail"
                                    ? product.SellingPrice ?? ""
                                    : product.WholesalePrice ?? ""
                                }
                                onChange={(e) =>
                                  updateBasePrice(
                                    product,
                                    priceMode === "retail" ? "SellingPrice" : "WholesalePrice",
                                    e.target.value
                                  )
                                }
                                onBlur={() =>
                                  saveBasePrice(
                                    product,
                                    priceMode === "retail" ? "SellingPrice" : "WholesalePrice"
                                  )
                                }
                                className="w-24 bg-blue-50 border rounded px-2 py-1"
                              />
                            </div>
                          </td>

                          {/* DYNAMIC TIERS */}
                          {quantities.map((quantity) => {
                            const tier = productTiers.find(
                              (x) => Number(x.Quantity) === Number(quantity)
                            );

                            return (
                              <td key={quantity} className="p-3">
                                {tier ? (
                                  <div className="flex items-center gap-1">
                                    <input
                                      type="number"
                                      value={tier[cashField] ?? ""}
                                      onChange={(e) =>
                                        updateTierPrice(product, quantity, cashField, e.target.value)
                                      }
                                      className="w-20 border rounded px-2 py-1"
                                    />
                                    <span>/</span>
                                    <input
                                      type="number"
                                      value={tier[creditField] ?? ""}
                                      onChange={(e) =>
                                        updateTierPrice(product, quantity, creditField, e.target.value)
                                      }
                                      onBlur={() => saveTier(product, quantity)}
                                      className="w-20 border rounded px-2 py-1"
                                    />
                                    <button
                                      type="button"
                                      onClick={() => saveTier(product, quantity)}
                                      title="Save tier"
                                      className="ml-1 w-8 h-8 border rounded bg-white hover:bg-orange-50 text-orange-500"
                                    >
                                      ✓
                                    </button>
                                  </div>
                                ) : (
                                  <button
                                    type="button"
                                    onClick={openAddTier}
                                    className="text-orange-500 text-xl"
                                  >
                                    +
                                  </button>
                                )}
                              </td>
                            );
                          })}

                          {/* ADD TIER */}
                          <td className="p-3">
                            <button
                              type="button"
                              onClick={openAddTier}
                              className="text-orange-500 text-2xl font-bold"
                            >
                              +
                            </button>
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>

      {/* ADD PRODUCT MODAL */}
      {showAddProduct && canAddProduct && (                    /* ← PERM */
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl shadow-2xl w-[850px] max-h-[90vh] overflow-auto">
            <div className="flex justify-between items-center p-6 border-b">
              <div>
                <h2 className="text-2xl font-bold">Add New Product</h2>
                <p className="text-gray-500">Create a new product</p>
              </div>
              <button
                type="button"
                onClick={() => setShowAddProduct(false)}
                className="text-2xl text-gray-500"
              >
                ×
              </button>
            </div>

            <div className="p-6 grid grid-cols-2 gap-4">
              {[
                ["ProductCode", "Product Code"],
                ["BarCode", "Barcode"],
                ["ReferenceCode1", "Reference Code"],
                ["ProductName", "Product Name"],
                ["NameOnInvoice", "Name On Invoice"],
                ["Department", "Department"],
                ["Category", "Category"],
                ["SubCategory", "Sub Category"],
                ["Supplier", "Supplier"],
                // ← PERM: skip price fields the user can't view
                ...(canViewCostPrice ? [["CostPrice", "Cost Price"]] : []),
                ...(canViewCostPrice ? [["OrderPrice", "Order Price"]] : []),
                ...(canViewSellingPrice ? [["SellingPrice", "Selling Price"]] : []),
                ...(canViewSellingPrice ? [["WholesalePrice", "Wholesale Price"]] : []),
                ...(canViewSellingPrice ? [["MinimumPrice", "Minimum Price"]] : []),
                ...(canViewSellingPrice ? [["MaximumPrice", "Maximum Price"]] : []),
                ["ReOrderLevel", "Reorder Level"],
                ["ReOrderQty", "Reorder Quantity"],
                ["ReOrderPeriod", "Reorder Period"],
              ].map(([name, label]) => (
                <div key={name}>
                  <label className="block mb-1 font-medium">{label}</label>
                  <input
                    name={name}
                    type={[
                      "CostPrice", "OrderPrice", "SellingPrice", "WholesalePrice",
                      "MinimumPrice", "MaximumPrice", "ReOrderLevel", "ReOrderQty",
                      "ReOrderPeriod",
                    ].includes(name)
                      ? "number"
                      : "text"}
                    value={newProduct[name]}
                    onChange={handleProductChange}
                    className="w-full border rounded-lg px-3 py-2"
                  />
                </div>
              ))}

              <label className="flex items-center gap-2">
                <input
                  type="checkbox"
                  name="IsActive"
                  checked={newProduct.IsActive}
                  onChange={handleProductChange}
                />
                Active
              </label>

              <label className="flex items-center gap-2">
                <input
                  type="checkbox"
                  name="IsTax"
                  checked={newProduct.IsTax}
                  onChange={handleProductChange}
                />
                Tax Product
              </label>
            </div>

            <div className="flex justify-end gap-3 p-6 border-t">
              <button
                type="button"
                onClick={() => setShowAddProduct(false)}
                className="px-5 py-3 border rounded-lg"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={handleAddProduct}
                className="px-6 py-3 bg-orange-500 text-white rounded-lg font-semibold"
              >
                Save Product
              </button>
            </div>
          </div>
        </div>
      )}

      {/* EDIT PRODUCT MODAL */}
      {editingProduct && canEditProduct && (                   /* ← PERM */
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl shadow-xl w-[650px] p-6">
            <div className="flex justify-between">
              <h2 className="text-2xl font-bold">Edit Product</h2>
              <button
                type="button"
                onClick={() => setEditingProduct(null)}
                className="text-xl"
              >
                ×
              </button>
            </div>

            <div className="grid grid-cols-2 gap-4 mt-6">
              <div>
                <label>Product Code</label>
                <input
                  name="ProductCode"
                  value={editingProduct.ProductCode || ""}
                  onChange={handleEditChange}
                  className="w-full border rounded-lg p-2"
                />
              </div>

              <div>
                <label>Product Name</label>
                <input
                  name="ProductName"
                  value={editingProduct.ProductName || ""}
                  onChange={handleEditChange}
                  className="w-full border rounded-lg p-2"
                />
              </div>

              {/* ← PERM: hide price fields the user can't view */}
              {canViewCostPrice && (                            /* ← PERM */
                <div>
                  <label>Cost Price</label>
                  <input
                    name="CostPrice"
                    type="number"
                    value={editingProduct.CostPrice ?? ""}
                    onChange={handleEditChange}
                    className="w-full border rounded-lg p-2"
                  />
                </div>
              )}

              {canViewSellingPrice && (                         /* ← PERM */
                <>
                  <div>
                    <label>Selling Price</label>
                    <input
                      name="SellingPrice"
                      type="number"
                      value={editingProduct.SellingPrice ?? ""}
                      onChange={handleEditChange}
                      className="w-full border rounded-lg p-2"
                    />
                  </div>

                  <div>
                    <label>Wholesale Price</label>
                    <input
                      name="WholesalePrice"
                      type="number"
                      value={editingProduct.WholesalePrice ?? ""}
                      onChange={handleEditChange}
                      className="w-full border rounded-lg p-2"
                    />
                  </div>

                  <div>
                    <label>Maximum Price / MRP</label>
                    <input
                      name="MaximumPrice"
                      type="number"
                      value={editingProduct.MaximumPrice ?? ""}
                      onChange={handleEditChange}
                      className="w-full border rounded-lg p-2"
                    />
                  </div>
                </>
              )}

              <div>
                <label>Reorder Level</label>
                <input
                  name="ReOrderLevel"
                  type="number"
                  value={editingProduct.ReOrderLevel ?? ""}
                  onChange={handleEditChange}
                  className="w-full border rounded-lg p-2"
                />
              </div>

              <div>
                <label>Reorder Quantity</label>
                <input
                  name="ReOrderQty"
                  type="number"
                  value={editingProduct.ReOrderQty ?? ""}
                  onChange={handleEditChange}
                  className="w-full border rounded-lg p-2"
                />
              </div>
            </div>

            <div className="flex justify-end gap-3 mt-6">
              <button
                type="button"
                onClick={() => setEditingProduct(null)}
                className="px-5 py-2 border rounded-lg"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={handleUpdateProduct}
                className="px-5 py-2 bg-orange-500 text-white rounded-lg"
              >
                Update
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ADD TIER MODAL */}
      {showTierModal && canEditProduct && (                    /* ← PERM */
        <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl shadow-2xl w-[520px]">
            <div className="p-6 border-b">
              <div className="flex justify-between">
                <div>
                  <h2 className="text-xl font-bold">＋ Add New Quantity Tier</h2>
                  <p className="text-gray-500 mt-1">
                    Add a new quantity tier column for all products
                  </p>
                </div>
                <button
                  type="button"
                  onClick={() => setShowTierModal(false)}
                  className="text-xl text-gray-500"
                >
                  ×
                </button>
              </div>
            </div>

            <div className="p-6">
              <div className="grid grid-cols-3 gap-3">
                <div>
                  <label className="block text-sm mb-1">Quantity</label>
                  <input
                    type="number"
                    placeholder="e.g. 25"
                    value={newTier.Quantity}
                    onChange={(e) =>
                      setNewTier((prev) => ({ ...prev, Quantity: e.target.value }))
                    }
                    className="w-full border rounded-lg px-3 py-2"
                  />
                </div>

                <div>
                  <label className="block text-sm mb-1">Retail Cash</label>
                  <input
                    type="number"
                    placeholder="Price"
                    value={newTier.RetailCashPrice}
                    onChange={(e) =>
                      setNewTier((prev) => ({ ...prev, RetailCashPrice: e.target.value }))
                    }
                    className="w-full border rounded-lg px-3 py-2"
                  />
                </div>

                <div>
                  <label className="block text-sm mb-1">Retail Credit</label>
                  <input
                    type="number"
                    placeholder="Price"
                    value={newTier.RetailCreditPrice}
                    onChange={(e) =>
                      setNewTier((prev) => ({ ...prev, RetailCreditPrice: e.target.value }))
                    }
                    className="w-full border rounded-lg px-3 py-2"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3 mt-4">
                <div>
                  <label className="block text-sm mb-1">Wholesale Cash</label>
                  <input
                    type="number"
                    placeholder="Price"
                    value={newTier.WholesaleCashPrice}
                    onChange={(e) =>
                      setNewTier((prev) => ({ ...prev, WholesaleCashPrice: e.target.value }))
                    }
                    className="w-full border rounded-lg px-3 py-2"
                  />
                </div>

                <div>
                  <label className="block text-sm mb-1">Wholesale Credit</label>
                  <input
                    type="number"
                    placeholder="Price"
                    value={newTier.WholesaleCreditPrice}
                    onChange={(e) =>
                      setNewTier((prev) => ({ ...prev, WholesaleCreditPrice: e.target.value }))
                    }
                    className="w-full border rounded-lg px-3 py-2"
                  />
                </div>
              </div>

              <p className="text-sm text-gray-500 mt-4">
                This will add a Q{newTier.Quantity || "?"} column. You can then set
                prices for each product row.
              </p>
            </div>

            <div className="p-6 border-t flex justify-end gap-3">
              <button
                type="button"
                onClick={() => setShowTierModal(false)}
                className="px-5 py-2 border rounded-lg"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={handleAddTier}
                className="px-5 py-2 bg-orange-500 text-white rounded-lg font-semibold"
              >
                Add Tier
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}