import React, { useContext, useEffect, useState } from "react";
import axios from "axios";
import { AuthContext } from "./SERVER/AuthContext.js";

// ← PERM
import { usePermissions } from "../hooks/usePermissions.jsx";

const API = "http://localhost:5000";

const emptyForm = {
  SupplierID: "",
  code: "",
  suppliername: "",
  Gender: "",
  address: "",
  mobileno: "",
  email: "",
  contactperson: "",
  paymentMethod: "",
  creditlimit: "",
  CreditPeriod: "",
  chequelimit: "",
  ChequePeriod: "",
  Currancytype: "",
  username: "",
};

function Supplier() {
  const { user } = useContext(AuthContext);

  // =========================================================
  // PERMISSIONS                                            // ← PERM
  // =========================================================
  const {
    can,
    canField,
    loading: permissionsLoading,
  } = usePermissions();                                     // ← PERM

  const canViewSupplier     = can("Supplier", "View");        // ← PERM
  const canAddSupplier      = can("Supplier", "Add");         // ← PERM
  const canEditSupplier     = can("Supplier", "Edit");        // ← PERM
  const canDeleteSupplier   = can("Supplier", "Delete");      // ← PERM

  const canViewCreditLimit  = canField("Supplier", "CreditLimit"); // ← PERM

  const [form, setForm] = useState(emptyForm);
  const [suppliers, setSuppliers] = useState([]);
  const [search, setSearch] = useState("");
  const [loading, setLoading] = useState(false);
  const [editMode, setEditMode] = useState(false);

  // ==========================================================
  // LOAD SUPPLIERS
  // ==========================================================
  const loadSuppliers = async () => {
    try {
      setLoading(true);

      const response = await axios.get(`${API}/suppliers`);
      setSuppliers(Array.isArray(response.data) ? response.data : []);
    } catch (error) {
      console.error("LOAD SUPPLIERS ERROR:", error);
      alert(error.response?.data?.message || "Unable to load suppliers.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    // ← PERM: wait for permissions + skip if no view
    if (permissionsLoading) return;                       // ← PERM
    if (!canViewSupplier) return;                         // ← PERM

    loadSuppliers();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [canViewSupplier, permissionsLoading]);              // ← PERM

  // ==========================================================
  // HANDLE CHANGE  (unchanged)
  // ==========================================================
  const handleChange = (e) => {
    const { name, value } = e.target;

    setForm((prev) => {
      const updated = { ...prev, [name]: value };

      if (name === "paymentMethod" && value === "Cash") {
        updated.creditlimit = "0";
        updated.CreditPeriod = "0";
      }
      if (name === "paymentMethod" && value === "Credit") {
        updated.creditlimit = "";
        updated.CreditPeriod = "";
      }

      return updated;
    });
  };

  // ==========================================================
  // GENERATE SUPPLIER CODE
  // ==========================================================
  const handleNewSupplier = async () => {
    // ← PERM
    if (!canAddSupplier) {                                // ← PERM
      alert("You do not have permission to create suppliers.");
      return;
    }

    try {
      setLoading(true);

      const response = await axios.get(`${API}/suppliercode`);
      const data = response.data;

      let nextNumber = 1;

      if (Array.isArray(data) && data.length > 0) {
        const lastCode = data[0]?.SupplierCode;

        if (lastCode) {
          const match = String(lastCode).match(/^S(\d+)$/i);
          if (match) {
            const lastNumber = parseInt(match[1], 10);
            if (!Number.isNaN(lastNumber)) nextNumber = lastNumber + 1;
          }
        }
      }

      const nextCode = `S${String(nextNumber).padStart(4, "0")}`;

      setEditMode(false);
      setForm({
        ...emptyForm,
        code: nextCode,
        username: user?.username || "",
      });
    } catch (error) {
      console.error("NEW SUPPLIER ERROR:", error);
      alert(error.response?.data?.message || "Unable to generate supplier code.");
    } finally {
      setLoading(false);
    }
  };

  // ==========================================================
  // VALIDATION  (unchanged)
  // ==========================================================
  const validateForm = () => {
    const code    = String(form.code ?? "").trim();
    const name    = String(form.suppliername ?? "").trim();
    const gender  = String(form.Gender ?? "").trim();
    const address = String(form.address ?? "").trim();
    const mobile  = String(form.mobileno ?? "").trim();
    const email   = String(form.email ?? "").trim();
    const contact = String(form.contactperson ?? "").trim();
    const payment = String(form.paymentMethod ?? "").trim();

    if (!code)    { alert("Supplier code is required."); return false; }
    if (!name)    { alert("Supplier name is required."); return false; }
    if (!gender)  { alert("Please select gender."); return false; }
    if (!address) { alert("Address is required."); return false; }
    if (!mobile)  { alert("Mobile number is required."); return false; }
    if (!email)   { alert("Email is required."); return false; }
    if (!contact) { alert("Contact person is required."); return false; }
    if (!payment) { alert("Please select payment method."); return false; }

    if (payment === "Credit" && form.creditlimit === "") {
      alert("Credit limit is required."); return false;
    }
    if (payment === "Credit" && form.CreditPeriod === "") {
      alert("Credit period is required."); return false;
    }
    if (form.chequelimit === "") {
      alert("Cheque limit is required."); return false;
    }
    if (!form.ChequePeriod) {
      alert("Cheque period is required."); return false;
    }
    if (!form.Currancytype) {
      alert("Please select currency."); return false;
    }

    return true;
  };

  // ==========================================================
  // SAVE / UPDATE
  // ==========================================================
  const handleSubmit = async (e) => {
    e.preventDefault();

    // ----- Permission guards -----                        // ← PERM
    if (editMode && !canEditSupplier) {                   // ← PERM
      alert("You do not have permission to edit suppliers.");
      return;
    }
    if (!editMode && !canAddSupplier) {                   // ← PERM
      alert("You do not have permission to create suppliers.");
      return;
    }

    if (!validateForm()) return;

    try {
      setLoading(true);

      const data = {
        code:         String(form.code || "").trim(),
        suppliername: String(form.suppliername || "").trim(),
        Gender:       String(form.Gender || "").trim(),
        address:      String(form.address || "").trim(),
        mobileno:     String(form.mobileno || "").trim(),
        email:        String(form.email || "").trim(),
        contactperson:String(form.contactperson || "").trim(),
        paymentMethod:String(form.paymentMethod || "").trim(),

        // ← PERM: only send creditlimit / CreditPeriod when user can view.
        // Otherwise the server-side values would be overwritten by the form.
        ...(canViewCreditLimit                                    // ← PERM
          ? {
              creditlimit:
                form.paymentMethod === "Cash"
                  ? 0
                  : Number(form.creditlimit || 0),
              CreditPeriod:
                form.paymentMethod === "Cash"
                  ? 0
                  : Number(form.CreditPeriod || 0),
            }
          : {}),

        chequelimit:  Number(form.chequelimit || 0),
        ChequePeriod: Number(form.ChequePeriod || 0),
        Currancytype: String(form.Currancytype || "").trim(),
        username:     user?.username || form.username || "",
      };

      let response;

      if (editMode) {
        response = await axios.put(
          `${API}/supplier/${form.SupplierID}`,
          data,
          { headers: { "Content-Type": "application/json" } }
        );
        alert(response.data?.message || "Supplier updated successfully.");
      } else {
        response = await axios.post(
          `${API}/supplier`,
          data,
          { headers: { "Content-Type": "application/json" } }
        );
        alert(response.data?.message || "Supplier saved successfully.");
      }

      setForm({ ...emptyForm, username: user?.username || "" });
      setEditMode(false);

      await loadSuppliers();
    } catch (error) {
      console.error("SAVE/UPDATE SUPPLIER ERROR:", error);
      alert(error.response?.data?.message || "Failed to save supplier.");
    } finally {
      setLoading(false);
    }
  };

  // ==========================================================
  // EDIT
  // ==========================================================
  const handleEdit = (supplier) => {
    // ← PERM
    if (!canEditSupplier) {                               // ← PERM
      alert("You do not have permission to edit suppliers.");
      return;
    }

    const currency =
      Number(supplier.CurrencyID) === 1
        ? "LKR"
        : Number(supplier.CurrencyID) === 2
        ? "USD"
        : "";

    setForm({
      SupplierID:    supplier.SupplierID || "",
      code:          supplier.SupplierCode || "",
      suppliername:  supplier.SupplierName || "",
      Gender:        supplier.Gender || "",
      address:       supplier.BillingAddress1 || "",
      mobileno:      supplier.BillingMobile || "",
      email:         supplier.Email || "",
      contactperson: supplier.ContactPersonName || "",
      paymentMethod: supplier.PaymentMethod || "",
      creditlimit:   supplier.CreditLimit ?? "",
      CreditPeriod:  supplier.CreditPeriod ?? "",
      chequelimit:   supplier.ChequeLimit ?? "",
      ChequePeriod:  supplier.ChequePeriod ?? "",
      Currancytype:  currency,
      username:
        user?.username ||
        supplier.ModifiedUser ||
        supplier.CreatedUser ||
        "",
    });

    setEditMode(true);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  // ==========================================================
  // DELETE
  // ==========================================================
  const handleDelete = async (supplier) => {
    // ← PERM
    if (!canDeleteSupplier) {                             // ← PERM
      alert("You do not have permission to delete suppliers.");
      return;
    }

    if (!supplier?.SupplierID) {
      alert("Invalid supplier.");
      return;
    }

    const supplierName =
      supplier.SupplierName || supplier.SupplierCode || "this supplier";

    const confirmed = window.confirm(
      `Are you sure you want to delete "${supplierName}"?`
    );
    if (!confirmed) return;

    try {
      setLoading(true);

      const response = await axios.delete(
        `${API}/supplier/${supplier.SupplierID}`,
        { data: { username: user?.username || "" } }
      );

      alert(response.data?.message || "Supplier deleted successfully.");

      if (String(form.SupplierID) === String(supplier.SupplierID)) {
        setForm({ ...emptyForm, username: user?.username || "" });
        setEditMode(false);
      }

      await loadSuppliers();
    } catch (error) {
      console.error("DELETE SUPPLIER ERROR:", error);
      alert(error.response?.data?.message || "Failed to delete supplier.");
    } finally {
      setLoading(false);
    }
  };

  // ==========================================================
  // CANCEL EDIT  (unchanged)
  // ==========================================================
  const handleCancel = () => {
    setForm({ ...emptyForm, username: user?.username || "" });
    setEditMode(false);
  };

  // ==========================================================
  // SEARCH  (unchanged)
  // ==========================================================
  const filteredSuppliers = suppliers.filter((supplier) => {
    const text = search.toLowerCase().trim();
    if (!text) return true;

    return (
      String(supplier.SupplierCode || "").toLowerCase().includes(text) ||
      String(supplier.SupplierName || "").toLowerCase().includes(text) ||
      String(supplier.ContactPersonName || "").toLowerCase().includes(text) ||
      String(supplier.BillingMobile || "").toLowerCase().includes(text) ||
      String(supplier.Email || "").toLowerCase().includes(text)
    );
  });

  // ==========================================================
  // COMPUTED                                               // ← PERM
  // ==========================================================
  const saveAllowed =
    (editMode && canEditSupplier) || (!editMode && canAddSupplier);
  const readOnlyEdit = editMode && !canEditSupplier;

  // ==========================================================
  // ACCESS GATE                                            // ← PERM
  // ==========================================================
  if (permissionsLoading) {                               // ← PERM
    return (
      <div className="min-h-screen bg-gray-100 p-6 flex items-center justify-center text-gray-500">
        Checking permissions…
      </div>
    );
  }

  if (!canViewSupplier) {                                 // ← PERM
    return (
      <div className="min-h-screen bg-gray-100 p-6">
        <div className="mx-auto max-w-xl mt-20 rounded-xl border border-red-200 bg-red-50 p-8 text-center">
          <h2 className="text-lg font-bold text-red-700">Access Denied</h2>
          <p className="text-sm text-red-600 mt-2">
            You do not have permission to view Supplier Master.
          </p>
          <p className="text-xs text-red-400 mt-3">
            Module: <code>Supplier</code>
          </p>
        </div>
      </div>
    );
  }

  // ==========================================================
  // UI
  // ==========================================================
  return (
    <div className="min-h-screen bg-gray-100 p-4 md:p-6">

      {/* HEADER */}
      <div className="mb-6 flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Supplier Master</h1>
          <p className="text-sm text-gray-500">Create, edit and manage suppliers</p>
        </div>

        <div className="flex items-center gap-3">
          {/* ← PERM: read-only badge */}
          {readOnlyEdit && (                              /* ← PERM */
            <span className="rounded-full bg-slate-200 px-3 py-1 text-xs font-semibold text-slate-600">
              READ ONLY
            </span>
          )}

          {/* ← PERM: New button only when can Add */}
          {canAddSupplier && (                            /* ← PERM */
            <button
              type="button"
              onClick={handleNewSupplier}
              disabled={loading}
              className="rounded-lg bg-blue-600 px-5 py-2.5 font-semibold text-white shadow hover:bg-blue-700 disabled:opacity-50"
            >
              + New Supplier
            </button>
          )}
        </div>
      </div>

      {/* FORM */}
      <form onSubmit={handleSubmit} className="rounded-xl bg-white p-5 shadow-md">

        <div className="mb-5 flex items-center justify-between border-b pb-3">
          <h2 className="text-lg font-bold text-gray-800">
            {editMode ? "Edit Supplier" : "Supplier Details"}
          </h2>

          {editMode && (
            <span className="rounded-full bg-yellow-100 px-3 py-1 text-xs font-semibold text-yellow-800">
              EDIT MODE
            </span>
          )}
        </div>

        {/* ROW 1 */}
        <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
          <div>
            <label className="mb-1 block text-sm font-semibold text-gray-700">
              Supplier Code
            </label>

            <div className="flex gap-2">
              <input
                type="text"
                name="code"
                value={form.code}
                onChange={handleChange}
                readOnly={editMode}
                className={`w-full rounded-lg border px-3 py-2 outline-none ${
                  editMode ? "bg-gray-100" : "focus:border-blue-500"
                }`}
              />

              {/* ← PERM: New button only when can Add */}
              {!editMode && canAddSupplier && (           /* ← PERM */
                <button
                  type="button"
                  onClick={handleNewSupplier}
                  className="rounded-lg bg-gray-700 px-4 text-white hover:bg-gray-800"
                >
                  New
                </button>
              )}
            </div>
          </div>

          <div>
            <label className="mb-1 block text-sm font-semibold text-gray-700">
              Supplier Name
            </label>
            <input
              type="text"
              name="suppliername"
              value={form.suppliername}
              onChange={handleChange}
              className="w-full rounded-lg border px-3 py-2 outline-none focus:border-blue-500"
            />
          </div>

          <div>
            <label className="mb-1 block text-sm font-semibold text-gray-700">
              Gender
            </label>
            <select
              name="Gender"
              value={form.Gender}
              onChange={handleChange}
              className="w-full rounded-lg border px-3 py-2 outline-none focus:border-blue-500"
            >
              <option value="">Select Gender</option>
              <option value="Male">Male</option>
              <option value="Female">Female</option>
              <option value="Company">Company</option>
            </select>
          </div>
        </div>

        {/* ROW 2 */}
        <div className="mt-4 grid grid-cols-1 gap-4 md:grid-cols-2">
          <div>
            <label className="mb-1 block text-sm font-semibold text-gray-700">
              Address
            </label>
            <textarea
              name="address"
              value={form.address}
              onChange={handleChange}
              rows="3"
              className="w-full rounded-lg border px-3 py-2 outline-none focus:border-blue-500"
            />
          </div>

          <div className="grid grid-cols-1 gap-4">
            <div>
              <label className="mb-1 block text-sm font-semibold text-gray-700">
                Mobile
              </label>
              <input
                type="text"
                name="mobileno"
                value={form.mobileno}
                onChange={handleChange}
                className="w-full rounded-lg border px-3 py-2 outline-none focus:border-blue-500"
              />
            </div>

            <div>
              <label className="mb-1 block text-sm font-semibold text-gray-700">
                Email
              </label>
              <input
                type="email"
                name="email"
                value={form.email}
                onChange={handleChange}
                className="w-full rounded-lg border px-3 py-2 outline-none focus:border-blue-500"
              />
            </div>
          </div>
        </div>

        {/* ROW 3 */}
        <div className="mt-4 grid grid-cols-1 gap-4 md:grid-cols-3">
          <div>
            <label className="mb-1 block text-sm font-semibold text-gray-700">
              Contact Person
            </label>
            <input
              type="text"
              name="contactperson"
              value={form.contactperson}
              onChange={handleChange}
              className="w-full rounded-lg border px-3 py-2 outline-none focus:border-blue-500"
            />
          </div>

          <div>
            <label className="mb-1 block text-sm font-semibold text-gray-700">
              Payment Method
            </label>
            <select
              name="paymentMethod"
              value={form.paymentMethod}
              onChange={handleChange}
              className="w-full rounded-lg border px-3 py-2 outline-none focus:border-blue-500"
            >
              <option value="">Select Payment</option>
              <option value="Cash">Cash</option>
              <option value="Credit">Credit</option>
            </select>
          </div>

          <div>
            <label className="mb-1 block text-sm font-semibold text-gray-700">
              Currency
            </label>
            <select
              name="Currancytype"
              value={form.Currancytype}
              onChange={handleChange}
              className="w-full rounded-lg border px-3 py-2 outline-none focus:border-blue-500"
            >
              <option value="">Select Currency</option>
              <option value="LKR">LKR</option>
              <option value="USD">USD</option>
            </select>
          </div>
        </div>

        {/* CREDIT — only shown when paymentMethod = Credit
            AND user can view CreditLimit */}
        {form.paymentMethod === "Credit" && canViewCreditLimit && (   /* ← PERM */
          <div className="mt-5 rounded-lg border border-blue-200 bg-blue-50 p-4">
            <h3 className="mb-3 font-bold text-blue-800">Credit Details</h3>

            <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
              <div>
                <label className="mb-1 block text-sm font-semibold">
                  Credit Limit
                </label>
                <input
                  type="number"
                  min="0"
                  name="creditlimit"
                  value={form.creditlimit}
                  onChange={handleChange}
                  className="w-full rounded-lg border px-3 py-2"
                />
              </div>

              <div>
                <label className="mb-1 block text-sm font-semibold">
                  Credit Period
                </label>
                <select
                  name="CreditPeriod"
                  value={form.CreditPeriod}
                  onChange={handleChange}
                  className="w-full rounded-lg border px-3 py-2"
                >
                  <option value="">Select Period</option>
                  <option value="45">45 Days</option>
                  <option value="90">90 Days</option>
                </select>
              </div>
            </div>
          </div>
        )}

        {/* ← PERM: notice when credit is hidden */}
        {form.paymentMethod === "Credit" && !canViewCreditLimit && (  /* ← PERM */
          <div className="mt-5 rounded-lg border border-amber-200 bg-amber-50 px-4 py-3 text-xs font-medium text-amber-700">
            Credit Limit and Credit Period are hidden by your permission level.
            Existing values will be preserved.
          </div>
        )}

        {/* CHEQUE — unchanged */}
        <div className="mt-5 rounded-lg border border-gray-200 bg-gray-50 p-4">
          <h3 className="mb-3 font-bold text-gray-800">Cheque Details</h3>

          <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
            <div>
              <label className="mb-1 block text-sm font-semibold">
                Cheque Limit
              </label>
              <input
                type="number"
                min="0"
                name="chequelimit"
                value={form.chequelimit}
                onChange={handleChange}
                className="w-full rounded-lg border px-3 py-2"
              />
            </div>

            <div>
              <label className="mb-1 block text-sm font-semibold">
                Cheque Period
              </label>
              <select
                name="ChequePeriod"
                value={form.ChequePeriod}
                onChange={handleChange}
                className="w-full rounded-lg border px-3 py-2"
              >
                <option value="">Select Period</option>
                <option value="45">45 Days</option>
                <option value="90">90 Days</option>
              </select>
            </div>
          </div>
        </div>

        {/* BUTTONS */}
        <div className="mt-6 flex flex-wrap items-center gap-3">
          {/* ← PERM: Save button only when saveAllowed */}
          {saveAllowed && (                               /* ← PERM */
            <button
              type="submit"
              disabled={loading}
              className={`rounded-lg px-6 py-2.5 font-semibold text-white ${
                editMode
                  ? "bg-orange-600 hover:bg-orange-700"
                  : "bg-green-600 hover:bg-green-700"
              } disabled:opacity-50`}
            >
              {loading
                ? "Processing..."
                : editMode
                ? "Update Supplier"
                : "Save Supplier"}
            </button>
          )}

          {editMode && (
            <button
              type="button"
              onClick={handleCancel}
              className="rounded-lg bg-gray-500 px-6 py-2.5 font-semibold text-white hover:bg-gray-600"
            >
              Cancel
            </button>
          )}

          {/* ← PERM: helper text when blocked */}
          {readOnlyEdit && (                              /* ← PERM */
            <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-2.5 text-xs font-semibold text-slate-500">
              You have read-only access — editing is disabled.
            </div>
          )}

          {!editMode && !canAddSupplier && (              /* ← PERM */
            <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-2.5 text-xs font-semibold text-slate-500">
              You do not have permission to create new suppliers.
            </div>
          )}
        </div>
      </form>

      {/* SEARCH */}
      <div className="mt-6 rounded-xl bg-white p-5 shadow-md">
        <div className="mb-4 flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
          <h2 className="text-lg font-bold text-gray-800">Supplier List</h2>

          <input
            type="text"
            placeholder="Search code, name, mobile, email..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full rounded-lg border px-4 py-2 outline-none focus:border-blue-500 md:w-96"
          />
        </div>

        {/* TABLE */}
        <div className="overflow-x-auto">
          <table className="min-w-full border-collapse">
            <thead>
              <tr className="bg-gray-800 text-left text-sm text-white">
                <th className="px-4 py-3">Code</th>
                <th className="px-4 py-3">Supplier Name</th>
                <th className="px-4 py-3">Contact Person</th>
                <th className="px-4 py-3">Mobile</th>
                <th className="px-4 py-3">Payment</th>
                {/* ← PERM: hide Credit Limit column when user can't view it */}
                {canViewCreditLimit && (                /* ← PERM */
                  <th className="px-4 py-3">Credit Limit</th>
                )}
                <th className="px-4 py-3">Currency</th>
                <th className="px-4 py-3 text-center">Actions</th>
              </tr>
            </thead>

            <tbody>
              {filteredSuppliers.length === 0 ? (
                <tr>
                  <td
                    colSpan={canViewCreditLimit ? 8 : 7}  /* ← PERM */
                    className="px-4 py-8 text-center text-gray-500"
                  >
                    No suppliers found.
                  </td>
                </tr>
              ) : (
                filteredSuppliers.map((supplier) => {
                  const currency =
                    Number(supplier.CurrencyID) === 1
                      ? "LKR"
                      : Number(supplier.CurrencyID) === 2
                      ? "USD"
                      : "-";

                  return (
                    <tr
                      key={supplier.SupplierID}
                      className="border-b hover:bg-gray-50"
                    >
                      <td className="px-4 py-3 font-semibold">
                        {supplier.SupplierCode}
                      </td>
                      <td className="px-4 py-3">{supplier.SupplierName}</td>
                      <td className="px-4 py-3">
                        {supplier.ContactPersonName || "-"}
                      </td>
                      <td className="px-4 py-3">
                        {supplier.BillingMobile || "-"}
                      </td>
                      <td className="px-4 py-3">
                        {supplier.PaymentMethod || "-"}
                      </td>

                      {/* ← PERM: hide Credit Limit cell */}
                      {canViewCreditLimit && (          /* ← PERM */
                        <td className="px-4 py-3">
                          {Number(supplier.CreditLimit || 0).toFixed(2)}
                        </td>
                      )}

                      <td className="px-4 py-3">{currency}</td>

                      {/* ← PERM: gate action buttons */}
                      <td className="px-4 py-3">
                        <div className="flex justify-center gap-2">
                          {canEditSupplier && (         /* ← PERM */
                            <button
                              type="button"
                              onClick={() => handleEdit(supplier)}
                              className="rounded-lg bg-blue-600 px-3 py-1.5 text-sm font-semibold text-white hover:bg-blue-700"
                            >
                              Edit
                            </button>
                          )}

                          {canDeleteSupplier && (       /* ← PERM */
                            <button
                              type="button"
                              onClick={() => handleDelete(supplier)}
                              className="rounded-lg bg-red-600 px-3 py-1.5 text-sm font-semibold text-white hover:bg-red-700"
                            >
                              Delete
                            </button>
                          )}

                          {!canEditSupplier && !canDeleteSupplier && (
                            <span className="text-xs text-slate-400">
                              No actions
                            </span>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

    </div>
  );
}

export default Supplier;