import React, {
    useCallback,
    useContext,
    useEffect,
    useMemo,
    useState
} from "react";

import axios from "axios";

import {
    Check,
    ChevronDown,
    ClipboardList,
    Loader2,
    Package,
    Plus,
    RefreshCw,
    Search,
    Trash2,
    X
} from "lucide-react";

import { AuthContext } from "../pos/SERVER/AuthContext.js";

const API_URL =
    process.env.REACT_APP_API_URL || "http://localhost:5000";


function StockCount() {

    const { user } = useContext(AuthContext);


    // ============================================================
    // USER DETAILS
    // ============================================================

    const username = useMemo(() => {

        return (
            user?.username ||
            user?.Username ||
            user?.U ||
            localStorage.getItem("username") ||
            localStorage.getItem("Username") ||
            localStorage.getItem("U") ||
            ""
        );

    }, [user]);


    const companyID = useMemo(() => {

        return (
            user?.companyID ??
            user?.CompanyID ??
            user?.companyId ??
            localStorage.getItem("CompanyID") ??
            localStorage.getItem("companyID") ??
            ""
        );

    }, [user]);


    const locationID = useMemo(() => {

        return (
            user?.locationID ??
            user?.LocationID ??
            user?.locationId ??
            user?.location ??
            localStorage.getItem("LocationID") ??
            localStorage.getItem("locationID") ??
            localStorage.getItem("location") ??
            ""
        );

    }, [user]);


    // ============================================================
    // FILTER STATE
    // ============================================================

    const [department, setDepartment] = useState("");
    const [category, setCategory] = useState("");
    const [supplier, setSupplier] = useState("");
    const [basket, setBasket] = useState("");

    const [productSearch, setProductSearch] = useState("");

    const [departments, setDepartments] = useState([]);
    const [categories, setCategories] = useState([]);
    const [suppliers, setSuppliers] = useState([]);
    const [baskets, setBaskets] = useState([]);


    // ============================================================
    // PRODUCT STATE
    // ============================================================

    const [products, setProducts] = useState([]);
    const [selectedProducts, setSelectedProducts] = useState([]);


    // ============================================================
    // SESSION STATE
    // ============================================================

    const [session, setSession] = useState(null);
    const [sessionItems, setSessionItems] = useState([]);

    const [sessionRemark, setSessionRemark] = useState("");


    // ============================================================
    // LOADING STATE
    // ============================================================

    const [loadingFilters, setLoadingFilters] = useState(false);
    const [loadingProducts, setLoadingProducts] = useState(false);
    const [startingSession, setStartingSession] = useState(false);
    const [saving, setSaving] = useState(false);
    const [finishing, setFinishing] = useState(false);
    const [deleting, setDeleting] = useState(false);


    // ============================================================
    // MESSAGE STATE
    // ============================================================

    const [error, setError] = useState("");
    const [success, setSuccess] = useState("");


    // ============================================================
    // LOAD FILTERS
    // ============================================================

    const loadFilters = useCallback(async () => {

        try {

            setLoadingFilters(true);
            setError("");

            const response = await axios.get(
                `${API_URL}/stockcount/filters`
            );

            if (!response.data?.success) {

                throw new Error(
                    response.data?.message ||
                    "Unable to load filters."
                );
            }

            setDepartments(
                Array.isArray(response.data.departments)
                    ? response.data.departments
                    : []
            );

            setCategories(
                Array.isArray(response.data.categories)
                    ? response.data.categories
                    : []
            );

            setSuppliers(
                Array.isArray(response.data.suppliers)
                    ? response.data.suppliers
                    : []
            );

            setBaskets(
                Array.isArray(response.data.baskets)
                    ? response.data.baskets
                    : []
            );

        } catch (err) {

            console.error("LOAD STOCK COUNT FILTERS ERROR:", err);

            setError(
                err.response?.data?.message ||
                err.message ||
                "Unable to load filters."
            );

        } finally {

            setLoadingFilters(false);
        }

    }, []);


    useEffect(() => {

        loadFilters();

    }, [loadFilters]);


    // ============================================================
    // SEARCH PRODUCTS
    // ============================================================

    const searchProducts = async () => {

        try {

            setLoadingProducts(true);
            setError("");
            setSuccess("");

            const params = new URLSearchParams();

            if (department) {
                params.append("department", department);
            }

            if (category) {
                params.append("category", category);
            }

            if (supplier) {
                params.append("supplier", supplier);
            }

            if (basket) {
                params.append("basket", basket);
            }

            if (productSearch.trim()) {
                params.append(
                    "search",
                    productSearch.trim()
                );
            }

            const response = await axios.get(
                `${API_URL}/stockcount/products?${params.toString()}`
            );

            if (!response.data?.success) {

                throw new Error(
                    response.data?.message ||
                    "Unable to load products."
                );
            }

            setProducts(
                Array.isArray(response.data.products)
                    ? response.data.products
                    : Array.isArray(response.data.data)
                        ? response.data.data
                        : []
            );

        } catch (err) {

            console.error("SEARCH STOCK COUNT PRODUCTS ERROR:", err);

            setProducts([]);

            setError(
                err.response?.data?.message ||
                err.message ||
                "Unable to load products."
            );

        } finally {

            setLoadingProducts(false);
        }

    };


    // ============================================================
    // SELECT PRODUCT
    // ============================================================

    const getProductID = (product) => {

        return (
            product.InvProductMasterID ??
            product.ProductID ??
            product.ProductMasterID ??
            null
        );

    };


    const isSelected = (product) => {

        const id = getProductID(product);

        return selectedProducts.some(
            item => Number(getProductID(item)) === Number(id)
        );

    };


    const toggleProduct = (product) => {

        const id = getProductID(product);

        if (!id) {
            return;
        }

        if (isSelected(product)) {

            setSelectedProducts(prev =>
                prev.filter(
                    item =>
                        Number(getProductID(item)) !== Number(id)
                )
            );

        } else {

            setSelectedProducts(prev => [
                ...prev,
                product
            ]);

        }

    };


    // ============================================================
    // SELECT ALL
    // ============================================================

    const allProductsSelected =
        products.length > 0 &&
        products.every(product =>
            isSelected(product)
        );


    const toggleSelectAll = () => {

        if (allProductsSelected) {

            const visibleIDs = new Set(
                products.map(product =>
                    Number(getProductID(product))
                )
            );

            setSelectedProducts(prev =>
                prev.filter(
                    item =>
                        !visibleIDs.has(
                            Number(getProductID(item))
                        )
                )
            );

        } else {

            setSelectedProducts(prev => {

                const existingIDs = new Set(
                    prev.map(item =>
                        Number(getProductID(item))
                    )
                );

                const additions = products.filter(
                    product =>
                        !existingIDs.has(
                            Number(getProductID(product))
                        )
                );

                return [
                    ...prev,
                    ...additions
                ];

            });

        }

    };


    // ============================================================
    // START SESSION
    // ============================================================

    const startSession = async () => {

        try {

            setError("");
            setSuccess("");

            if (!username) {

                setError(
                    "Username is not available. Please login again."
                );

                return;
            }



            if (!locationID) {

                setError(
                    "Location is not available for the logged-in user."
                );

                return;
            }


            if (selectedProducts.length === 0) {

                setError(
                    "Please select at least one product."
                );

                return;
            }


            setStartingSession(true);


            const productIDs = selectedProducts
                .map(product => getProductID(product))
                .filter(Boolean)
                .map(Number);


            const payload = {

                username,

                // IMPORTANT:
                // Location comes from logged-in user
                // and is sent to backend.

                companyID: Number(companyID),

                locationID: Number(locationID),

                department: department || null,

                category: category || null,

                supplier: supplier || null,

                basket: basket || null,

                productIDs

            };


            console.log(
                "START STOCK COUNT PAYLOAD:",
                payload
            );


            const response = await axios.post(
                `${API_URL}/stockcount/session/start`,
                payload
            );


            if (!response.data?.success) {

                throw new Error(
                    response.data?.message ||
                    "Unable to start stock count."
                );
            }


            setSession(
                response.data.session || {
                    StockCountSessionID:
                        response.data.StockCountSessionID,

                    SessionNo:
                        response.data.sessionNo,

                    Username:
                        username,

                    CompanyID:
                        Number(companyID),

                    LocationID:
                        Number(locationID),

                    Status:
                        "Open"
                }
            );


            setSessionItems(
                Array.isArray(response.data.items)
                    ? response.data.items
                    : []
            );


            setSuccess(
                `Stock count session ${
                    response.data.sessionNo || ""
                } started successfully.`
            );


            setSelectedProducts([]);

            setProducts([]);

        } catch (err) {

            console.error(
                "START STOCK COUNT ERROR:",
                err
            );

            setError(
                err.response?.data?.message ||
                err.message ||
                "Unable to start stock count."
            );

        } finally {

            setStartingSession(false);
        }

    };


    // ============================================================
    // CHANGE COUNT
    // ============================================================

    const updateCount = (
        detailID,
        field,
        value
    ) => {

        setSessionItems(prev =>
            prev.map(item => {

                if (
                    Number(item.StockCountSessionDetID) !==
                    Number(detailID)
                ) {
                    return item;
                }


                return {
                    ...item,
                    [field]: value
                };

            })
        );

    };


    // ============================================================
    // CALCULATED VALUES
    // ============================================================

    const getStoreCount = (item) => {

        const value = Number(item.StoreCount);

        return Number.isFinite(value)
            ? value
            : 0;

    };


    const getRackCount = (item) => {

        const value = Number(item.RackCount);

        return Number.isFinite(value)
            ? value
            : 0;

    };


    const getSystemStock = (item) => {

        const value = Number(item.SystemStock);

        return Number.isFinite(value)
            ? value
            : 0;

    };


    const getPhysicalTotal = (item) => {

        return (
            getStoreCount(item) +
            getRackCount(item)
        );

    };


    const getVariance = (item) => {

        return (
            getPhysicalTotal(item) -
            getSystemStock(item)
        );

    };


    // ============================================================
    // SAVE SESSION
    // ============================================================

    const saveSession = async () => {

        try {

            setError("");
            setSuccess("");

            if (!session?.SessionNo) {

                setError(
                    "No active stock count session."
                );

                return;
            }


            if (sessionItems.length === 0) {

                setError(
                    "There are no items in this session."
                );

                return;
            }


            setSaving(true);


            const items = sessionItems.map(item => ({

                StockCountSessionDetID:
                    Number(
                        item.StockCountSessionDetID
                    ),

                storeCount:
                    item.StoreCount === "" ||
                    item.StoreCount === null ||
                    item.StoreCount === undefined
                        ? null
                        : Number(item.StoreCount),

                rackCount:
                    item.RackCount === "" ||
                    item.RackCount === null ||
                    item.RackCount === undefined
                        ? null
                        : Number(item.RackCount)

            }));


            const response = await axios.post(
                `${API_URL}/stockcount/session/save`,
                {
                    sessionNo:
                        session.SessionNo,

                    username,

                    items
                }
            );


            if (!response.data?.success) {

                throw new Error(
                    response.data?.message ||
                    "Unable to save stock count."
                );
            }


            if (Array.isArray(response.data.items)) {

                setSessionItems(
                    response.data.items
                );

            }


            if (response.data.session) {

                setSession(prev => ({
                    ...prev,
                    ...response.data.session
                }));

            }


            setSuccess(
                "Stock count saved successfully."
            );

        } catch (err) {

            console.error(
                "SAVE STOCK COUNT ERROR:",
                err
            );

            setError(
                err.response?.data?.message ||
                err.message ||
                "Unable to save stock count."
            );

        } finally {

            setSaving(false);
        }

    };


    // ============================================================
    // FINISH SESSION
    // ============================================================

    const finishSession = async () => {

        try {

            setError("");
            setSuccess("");


            if (!session?.SessionNo) {

                setError(
                    "No active stock count session."
                );

                return;
            }


            const incompleteItems =
                sessionItems.filter(item => {

                    return (
                        item.StoreCount === "" ||
                        item.StoreCount === null ||
                        item.StoreCount === undefined ||
                        item.RackCount === "" ||
                        item.RackCount === null ||
                        item.RackCount === undefined
                    );

                });


            if (incompleteItems.length > 0) {

                setError(
                    `${incompleteItems.length} item(s) do not have both Store Count and Rack Count.`
                );

                return;
            }


            setFinishing(true);


            // ----------------------------------------------------
            // FIRST SAVE COUNTS
            // ----------------------------------------------------

            const saveItems = sessionItems.map(item => ({

                StockCountSessionDetID:
                    Number(
                        item.StockCountSessionDetID
                    ),

                storeCount:
                    Number(item.StoreCount),

                rackCount:
                    Number(item.RackCount)

            }));


            const saveResponse = await axios.post(
                `${API_URL}/stockcount/session/save`,
                {
                    sessionNo:
                        session.SessionNo,

                    username,

                    items: saveItems
                }
            );


            if (!saveResponse.data?.success) {

                throw new Error(
                    saveResponse.data?.message ||
                    "Unable to save stock count."
                );
            }


            // ----------------------------------------------------
            // FINISH
            // ----------------------------------------------------

            const finishResponse = await axios.post(
                `${API_URL}/stockcount/session/finish`,
                {
                    sessionNo:
                        session.SessionNo,

                    username,

                    remark:
                        sessionRemark.trim() || null
                }
            );


            if (!finishResponse.data?.success) {

                throw new Error(
                    finishResponse.data?.message ||
                    "Unable to finish stock count."
                );
            }


            setSession(prev => ({
                ...prev,

                Status: "Finished",

                FinishedDate:
                    new Date().toISOString()

            }));


            setSuccess(
                "Stock count finished successfully and sent for approval."
            );


            setSessionRemark("");


        } catch (err) {

            console.error(
                "FINISH STOCK COUNT ERROR:",
                err
            );

            setError(
                err.response?.data?.message ||
                err.message ||
                "Unable to finish stock count."
            );

        } finally {

            setFinishing(false);
        }

    };


    // ============================================================
    // DELETE SESSION
    // ============================================================

    const deleteSession = async () => {

        try {

            setError("");
            setSuccess("");


            if (!session?.SessionNo) {

                setError(
                    "No active stock count session."
                );

                return;
            }


            const confirmed = window.confirm(
                `Delete stock count session ${session.SessionNo}?`
            );


            if (!confirmed) {
                return;
            }


            setDeleting(true);


            const response = await axios.delete(
                `${API_URL}/stockcount/session/${encodeURIComponent(
                    session.SessionNo
                )}`
            );


            if (!response.data?.success) {

                throw new Error(
                    response.data?.message ||
                    "Unable to delete session."
                );
            }


            setSession(null);
            setSessionItems([]);
            setSessionRemark("");


            setSuccess(
                "Stock count session deleted successfully."
            );


        } catch (err) {

            console.error(
                "DELETE STOCK COUNT ERROR:",
                err
            );

            setError(
                err.response?.data?.message ||
                err.message ||
                "Unable to delete stock count session."
            );

        } finally {

            setDeleting(false);
        }

    };


    // ============================================================
    // RESET SEARCH
    // ============================================================

    const clearSearch = () => {

        setDepartment("");
        setCategory("");
        setSupplier("");
        setBasket("");
        setProductSearch("");

        setProducts([]);
        setSelectedProducts([]);

        setError("");
        setSuccess("");

    };


    // ============================================================
    // SESSION TOTALS
    // ============================================================

    const sessionTotals = useMemo(() => {

        let total = sessionItems.length;
        let completed = 0;
        let missing = 0;
        let variance = 0;


        sessionItems.forEach(item => {

            const store =
                item.StoreCount !== null &&
                item.StoreCount !== undefined &&
                item.StoreCount !== "";

            const rack =
                item.RackCount !== null &&
                item.RackCount !== undefined &&
                item.RackCount !== "";


            if (store && rack) {
                completed++;
            } else {
                missing++;
            }


            variance += getVariance(item);

        });


        return {
            total,
            completed,
            missing,
            variance
        };

    }, [sessionItems]);


    // ============================================================
    // RENDER
    // ============================================================

    return (

        <div className="min-h-screen bg-gray-100 p-4 md:p-6">

            <div className="mx-auto max-w-7xl">


                {/* ==================================================
                    HEADER
                ================================================== */}

                <div className="mb-6 flex flex-col gap-4 md:flex-row md:items-center md:justify-between">

                    <div>

                        <div className="flex items-center gap-3">

                            <div className="rounded-xl bg-blue-600 p-3 text-white">

                                <ClipboardList
                                    size={25}
                                />

                            </div>

                            <div>

                                <h1 className="text-2xl font-bold text-gray-800">
                                    Stock Count
                                </h1>

                                <p className="text-sm text-gray-500">
                                    Count physical stock by location
                                </p>

                            </div>

                        </div>

                    </div>


                    <button
                        type="button"
                        onClick={loadFilters}
                        disabled={loadingFilters}
                        className="inline-flex items-center justify-center gap-2 rounded-lg border bg-white px-4 py-2 text-sm font-medium text-gray-700 shadow-sm hover:bg-gray-50 disabled:opacity-50"
                    >

                        <RefreshCw
                            size={17}
                            className={
                                loadingFilters
                                    ? "animate-spin"
                                    : ""
                            }
                        />

                        Refresh

                    </button>

                </div>


                {/* ==================================================
                    MESSAGE
                ================================================== */}

                {error && (

                    <div className="mb-4 flex items-start gap-3 rounded-lg border border-red-200 bg-red-50 p-4 text-sm text-red-700">

                        <X
                            size={18}
                            className="mt-0.5 shrink-0"
                        />

                        <div className="flex-1">
                            {error}
                        </div>

                        <button
                            type="button"
                            onClick={() => setError("")}
                        >
                            <X size={16} />
                        </button>

                    </div>

                )}


                {success && (

                    <div className="mb-4 flex items-start gap-3 rounded-lg border border-green-200 bg-green-50 p-4 text-sm text-green-700">

                        <Check
                            size={18}
                            className="mt-0.5 shrink-0"
                        />

                        <div>
                            {success}
                        </div>

                    </div>

                )}


                {/* ==================================================
                    USER / LOCATION INFORMATION
                ================================================== */}

                <div className="mb-6 grid grid-cols-1 gap-4 md:grid-cols-3">


                    <div className="rounded-xl border bg-white p-4 shadow-sm">

                        <div className="mb-1 text-xs font-medium uppercase tracking-wide text-gray-500">
                            User
                        </div>

                        <div className="font-semibold text-gray-800">
                            {username || "Not available"}
                        </div>

                    </div>


                    <div className="rounded-xl border bg-white p-4 shadow-sm">

                        <div className="mb-1 text-xs font-medium uppercase tracking-wide text-gray-500">
                            Company
                        </div>

                        <div className="font-semibold text-gray-800">
                            {companyID || "Not available"}
                        </div>

                    </div>


                    <div className="rounded-xl border border-blue-200 bg-blue-50 p-4 shadow-sm">

                        <div className="mb-1 text-xs font-medium uppercase tracking-wide text-blue-600">
                            Counting Location
                        </div>

                        <div className="font-semibold text-blue-900">
                            {user?.location || "Not available"}
                        </div>

                        <div className="mt-1 text-xs text-blue-700">
                            Location is taken from the logged-in user.
                        </div>

                    </div>

                </div>


                {/* ==================================================
                    ACTIVE SESSION
                ================================================== */}

                {session && (

                    <div className="mb-6 rounded-xl border bg-white shadow-sm">


                        <div className="border-b p-4">

                            <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">

                                <div>

                                    <div className="flex flex-wrap items-center gap-3">

                                        <h2 className="text-lg font-bold text-gray-800">
                                            Active Session
                                        </h2>

                                        <span className="rounded-full bg-blue-100 px-3 py-1 text-xs font-semibold text-blue-700">
                                            {session.SessionNo}
                                        </span>

                                        <span className="rounded-full bg-green-100 px-3 py-1 text-xs font-semibold text-green-700">
                                            {session.Status || "Open"}
                                        </span>

                                    </div>


                                    <div className="mt-2 text-sm text-gray-500">

                                        Location:
                                        <span className="ml-1 font-semibold text-gray-700">
                                            {session.LocationID || locationID}
                                        </span>

                                    </div>

                                </div>


                                <div className="flex flex-wrap gap-2">


                                    <button
                                        type="button"
                                        onClick={saveSession}
                                        disabled={
                                            saving ||
                                            finishing ||
                                            session.Status !== "Open"
                                        }
                                        className="inline-flex items-center gap-2 rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
                                    >

                                        {saving ? (
                                            <Loader2
                                                size={17}
                                                className="animate-spin"
                                            />
                                        ) : (
                                            <Check size={17} />
                                        )}

                                        Save

                                    </button>


                                    <button
                                        type="button"
                                        onClick={finishSession}
                                        disabled={
                                            saving ||
                                            finishing ||
                                            session.Status !== "Open"
                                        }
                                        className="inline-flex items-center gap-2 rounded-lg bg-green-600 px-4 py-2 text-sm font-semibold text-white hover:bg-green-700 disabled:cursor-not-allowed disabled:opacity-50"
                                    >

                                        {finishing ? (
                                            <Loader2
                                                size={17}
                                                className="animate-spin"
                                            />
                                        ) : (
                                            <Check size={17} />
                                        )}

                                        Finish Session

                                    </button>


                                    <button
                                        type="button"
                                        onClick={deleteSession}
                                        disabled={
                                            deleting ||
                                            saving ||
                                            finishing ||
                                            session.Status !== "Open"
                                        }
                                        className="inline-flex items-center gap-2 rounded-lg border border-red-200 bg-white px-4 py-2 text-sm font-semibold text-red-600 hover:bg-red-50 disabled:cursor-not-allowed disabled:opacity-50"
                                    >

                                        {deleting ? (
                                            <Loader2
                                                size={17}
                                                className="animate-spin"
                                            />
                                        ) : (
                                            <Trash2 size={17} />
                                        )}

                                        Delete

                                    </button>

                                </div>

                            </div>

                        </div>


                        {/* SESSION SUMMARY */}

                        <div className="grid grid-cols-2 gap-3 border-b p-4 md:grid-cols-4">


                            <div className="rounded-lg bg-gray-50 p-3">

                                <div className="text-xs text-gray-500">
                                    Total Items
                                </div>

                                <div className="mt-1 text-xl font-bold text-gray-800">
                                    {sessionTotals.total}
                                </div>

                            </div>


                            <div className="rounded-lg bg-green-50 p-3">

                                <div className="text-xs text-green-600">
                                    Completed
                                </div>

                                <div className="mt-1 text-xl font-bold text-green-700">
                                    {sessionTotals.completed}
                                </div>

                            </div>


                            <div className="rounded-lg bg-orange-50 p-3">

                                <div className="text-xs text-orange-600">
                                    Missing
                                </div>

                                <div className="mt-1 text-xl font-bold text-orange-700">
                                    {sessionTotals.missing}
                                </div>

                            </div>


                            <div className="rounded-lg bg-blue-50 p-3">

                                <div className="text-xs text-blue-600">
                                    Total Variance
                                </div>

                                <div className="mt-1 text-xl font-bold text-blue-700">
                                    {sessionTotals.variance.toFixed(2)}
                                </div>

                            </div>

                        </div>


                        {/* REMARK */}

                        <div className="border-b p-4">

                            <label className="mb-2 block text-sm font-medium text-gray-700">
                                Remark
                            </label>

                            <input
                                type="text"
                                value={sessionRemark}
                                onChange={e =>
                                    setSessionRemark(
                                        e.target.value
                                    )
                                }
                                disabled={
                                    session.Status !== "Open"
                                }
                                placeholder="Optional remark before finishing..."
                                className="w-full rounded-lg border px-3 py-2 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 disabled:bg-gray-100"
                            />

                        </div>


                        {/* SESSION ITEMS */}

                        <div className="overflow-x-auto">

                            <table className="min-w-full text-sm">

                                <thead className="bg-gray-50">

                                    <tr>

                                        <th className="whitespace-nowrap px-4 py-3 text-left font-semibold text-gray-600">
                                            #
                                        </th>

                                        <th className="whitespace-nowrap px-4 py-3 text-left font-semibold text-gray-600">
                                            Product Code
                                        </th>

                                        <th className="whitespace-nowrap px-4 py-3 text-left font-semibold text-gray-600">
                                            Product Name
                                        </th>

                                        <th className="whitespace-nowrap px-4 py-3 text-right font-semibold text-gray-600">
                                            System Stock
                                        </th>

                                        <th className="whitespace-nowrap px-4 py-3 text-right font-semibold text-gray-600">
                                            Store Count
                                        </th>

                                        <th className="whitespace-nowrap px-4 py-3 text-right font-semibold text-gray-600">
                                            Rack Count
                                        </th>

                                        <th className="whitespace-nowrap px-4 py-3 text-right font-semibold text-gray-600">
                                            Physical Total
                                        </th>

                                        <th className="whitespace-nowrap px-4 py-3 text-right font-semibold text-gray-600">
                                            Variance
                                        </th>

                                        <th className="whitespace-nowrap px-4 py-3 text-center font-semibold text-gray-600">
                                            Status
                                        </th>

                                    </tr>

                                </thead>


                                <tbody className="divide-y">

                                    {sessionItems.length === 0 ? (

                                        <tr>

                                            <td
                                                colSpan="9"
                                                className="px-4 py-10 text-center text-gray-500"
                                            >
                                                No products in this session.
                                            </td>

                                        </tr>

                                    ) : (

                                        sessionItems.map(
                                            (item, index) => {

                                                const variance =
                                                    getVariance(item);

                                                const completed =
                                                    item.StoreCount !== null &&
                                                    item.StoreCount !== undefined &&
                                                    item.StoreCount !== "" &&
                                                    item.RackCount !== null &&
                                                    item.RackCount !== undefined &&
                                                    item.RackCount !== "";


                                                return (

                                                    <tr
                                                        key={
                                                            item.StockCountSessionDetID
                                                        }
                                                        className="hover:bg-gray-50"
                                                    >

                                                        <td className="px-4 py-3 text-gray-500">
                                                            {index + 1}
                                                        </td>


                                                        <td className="px-4 py-3 font-medium text-gray-800">
                                                            {item.ProductCode || "-"}
                                                        </td>


                                                        <td className="px-4 py-3 text-gray-700">
                                                            {item.ProductName || "-"}
                                                        </td>


                                                        <td className="px-4 py-3 text-right font-medium text-gray-700">
                                                            {getSystemStock(item).toFixed(2)}
                                                        </td>


                                                        <td className="px-4 py-3">

                                                            <input
                                                                type="number"
                                                                min="0"
                                                                step="0.01"
                                                                value={
                                                                    item.StoreCount ??
                                                                    ""
                                                                }
                                                                disabled={
                                                                    session.Status !==
                                                                    "Open"
                                                                }
                                                                onChange={e =>
                                                                    updateCount(
                                                                        item.StockCountSessionDetID,
                                                                        "StoreCount",
                                                                        e.target.value
                                                                    )
                                                                }
                                                                className="w-28 rounded-lg border px-3 py-2 text-right outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 disabled:bg-gray-100"
                                                            />

                                                        </td>


                                                        <td className="px-4 py-3">

                                                            <input
                                                                type="number"
                                                                min="0"
                                                                step="0.01"
                                                                value={
                                                                    item.RackCount ??
                                                                    ""
                                                                }
                                                                disabled={
                                                                    session.Status !==
                                                                    "Open"
                                                                }
                                                                onChange={e =>
                                                                    updateCount(
                                                                        item.StockCountSessionDetID,
                                                                        "RackCount",
                                                                        e.target.value
                                                                    )
                                                                }
                                                                className="w-28 rounded-lg border px-3 py-2 text-right outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 disabled:bg-gray-100"
                                                            />

                                                        </td>


                                                        <td className="px-4 py-3 text-right font-semibold text-gray-800">

                                                            {getPhysicalTotal(
                                                                item
                                                            ).toFixed(2)}

                                                        </td>


                                                        <td
                                                            className={`px-4 py-3 text-right font-bold ${
                                                                variance < 0
                                                                    ? "text-red-600"
                                                                    : variance > 0
                                                                        ? "text-green-600"
                                                                        : "text-gray-600"
                                                            }`}
                                                        >

                                                            {variance > 0
                                                                ? "+"
                                                                : ""}

                                                            {variance.toFixed(2)}

                                                        </td>


                                                        <td className="px-4 py-3 text-center">

                                                            {completed ? (

                                                                <span className="inline-flex items-center gap-1 rounded-full bg-green-100 px-3 py-1 text-xs font-semibold text-green-700">

                                                                    <Check
                                                                        size={13}
                                                                    />

                                                                    Completed

                                                                </span>

                                                            ) : (

                                                                <span className="rounded-full bg-orange-100 px-3 py-1 text-xs font-semibold text-orange-700">
                                                                    Missing
                                                                </span>

                                                            )}

                                                        </td>

                                                    </tr>

                                                );

                                            }
                                        )

                                    )}

                                </tbody>

                            </table>

                        </div>

                    </div>

                )}


                {/* ==================================================
                    NEW SESSION AREA
                ================================================== */}

                {!session && (

                    <div className="rounded-xl border bg-white shadow-sm">


                        <div className="border-b p-5">

                            <div className="flex items-center gap-3">

                                <div className="rounded-lg bg-blue-100 p-2 text-blue-600">

                                    <Plus size={20} />

                                </div>

                                <div>

                                    <h2 className="text-lg font-bold text-gray-800">
                                        Start Stock Count
                                    </h2>

                                    <p className="text-sm text-gray-500">
                                        Select products to include in the stock count.
                                    </p>

                                </div>

                            </div>

                        </div>


                        {/* FILTERS */}

                        <div className="grid grid-cols-1 gap-4 p-5 md:grid-cols-2 lg:grid-cols-4">


                            {/* DEPARTMENT */}

                            <div>

                                <label className="mb-1 block text-sm font-medium text-gray-700">
                                    Department
                                </label>

                                <div className="relative">

                                    <select
                                        value={department}
                                        onChange={e =>
                                            setDepartment(
                                                e.target.value
                                            )
                                        }
                                        className="w-full appearance-none rounded-lg border bg-white px-3 py-2.5 pr-9 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                                    >

                                        <option value="">
                                            All Departments
                                        </option>

                                        {departments.map(
                                            (item, index) => {

                                                const value =
                                                    typeof item ===
                                                    "object"
                                                        ? item.value ||
                                                          item.Department ||
                                                          item.department ||
                                                          item.Name ||
                                                          ""
                                                        : item;

                                                const label =
                                                    typeof item === "object"
                                                        ? item.label || value
                                                        : value;

                                                return (

                                                    <option
                                                        key={`${value}-${index}`}
                                                        value={value}
                                                    >
                                                        {label}
                                                    </option>

                                                );

                                            }
                                        )}

                                    </select>

                                    <ChevronDown
                                        size={17}
                                        className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400"
                                    />

                                </div>

                            </div>


                            {/* CATEGORY */}

                            <div>

                                <label className="mb-1 block text-sm font-medium text-gray-700">
                                    Category
                                </label>

                                <div className="relative">

                                    <select
                                        value={category}
                                        onChange={e =>
                                            setCategory(
                                                e.target.value
                                            )
                                        }
                                        className="w-full appearance-none rounded-lg border bg-white px-3 py-2.5 pr-9 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                                    >

                                        <option value="">
                                            All Categories
                                        </option>

                                        {categories.map(
                                            (item, index) => {

                                                const value =
                                                    typeof item ===
                                                    "object"
                                                        ? item.value ||
                                                          item.Category ||
                                                          item.category ||
                                                          item.Name ||
                                                          ""
                                                        : item;

                                                const label =
                                                    typeof item === "object"
                                                        ? item.label || value
                                                        : value;

                                                return (

                                                    <option
                                                        key={`${value}-${index}`}
                                                        value={value}
                                                    >
                                                        {label}
                                                    </option>

                                                );

                                            }
                                        )}

                                    </select>

                                    <ChevronDown
                                        size={17}
                                        className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400"
                                    />

                                </div>

                            </div>


                            {/* SUPPLIER */}

                            <div>

                                <label className="mb-1 block text-sm font-medium text-gray-700">
                                    Supplier
                                </label>

                                <div className="relative">

                                    <select
                                        value={supplier}
                                        onChange={e =>
                                            setSupplier(
                                                e.target.value
                                            )
                                        }
                                        className="w-full appearance-none rounded-lg border bg-white px-3 py-2.5 pr-9 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                                    >

                                        <option value="">
                                            All Suppliers
                                        </option>

                                        {suppliers.map(
                                            (item, index) => {

                                                const value =
                                                    typeof item ===
                                                    "object"
                                                        ? item.value ||
                                                          item.Supplier ||
                                                          item.supplier ||
                                                          item.Name ||
                                                          ""
                                                        : item;

                                                const label =
                                                    typeof item === "object"
                                                        ? item.label || value
                                                        : value;

                                                return (

                                                    <option
                                                        key={`${value}-${index}`}
                                                        value={value}
                                                    >
                                                        {label}
                                                    </option>

                                                );

                                            }
                                        )}

                                    </select>

                                    <ChevronDown
                                        size={17}
                                        className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400"
                                    />

                                </div>

                            </div>


                            {/* BASKET */}

                            <div>

                                <label className="mb-1 block text-sm font-medium text-gray-700">
                                    Basket
                                </label>

                                <div className="relative">

                                    <select
                                        value={basket}
                                        onChange={e =>
                                            setBasket(
                                                e.target.value
                                            )
                                        }
                                        className="w-full appearance-none rounded-lg border bg-white px-3 py-2.5 pr-9 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                                    >

                                        <option value="">
                                            All Baskets
                                        </option>

                                        {baskets.map(
                                            (item, index) => {

                                                const value =
                                                    typeof item ===
                                                    "object"
                                                        ? item.Basket ||
                                                          item.basket ||
                                                          item.Name ||
                                                          ""
                                                        : item;

                                                return (

                                                    <option
                                                        key={`${value}-${index}`}
                                                        value={value}
                                                    >
                                                        {value}
                                                    </option>

                                                );

                                            }
                                        )}

                                    </select>

                                    <ChevronDown
                                        size={17}
                                        className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400"
                                    />

                                </div>

                            </div>

                        </div>


                        {/* SEARCH */}

                        <div className="flex flex-col gap-3 border-y bg-gray-50 p-5 md:flex-row">

                            <div className="relative flex-1">

                                <Search
                                    size={18}
                                    className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"
                                />

                                <input
                                    type="text"
                                    value={productSearch}
                                    onChange={e =>
                                        setProductSearch(
                                            e.target.value
                                        )
                                    }
                                    onKeyDown={e => {

                                        if (e.key === "Enter") {
                                            searchProducts();
                                        }

                                    }}
                                    placeholder="Search product code or product name..."
                                    className="w-full rounded-lg border bg-white py-2.5 pl-10 pr-3 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                                />

                            </div>


                            <button
                                type="button"
                                onClick={searchProducts}
                                disabled={loadingProducts}
                                className="inline-flex items-center justify-center gap-2 rounded-lg bg-blue-600 px-5 py-2.5 text-sm font-semibold text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
                            >

                                {loadingProducts ? (

                                    <Loader2
                                        size={17}
                                        className="animate-spin"
                                    />

                                ) : (

                                    <Search size={17} />

                                )}

                                Search Products

                            </button>


                            <button
                                type="button"
                                onClick={clearSearch}
                                className="inline-flex items-center justify-center gap-2 rounded-lg border bg-white px-5 py-2.5 text-sm font-semibold text-gray-700 hover:bg-gray-50"
                            >

                                <X size={17} />

                                Clear

                            </button>

                        </div>


                        {/* PRODUCT SELECTION */}

                        <div className="overflow-x-auto">

                            <table className="min-w-full text-sm">

                                <thead className="bg-gray-50">

                                    <tr>

                                        <th className="px-4 py-3 text-left">

                                            <input
                                                type="checkbox"
                                                checked={
                                                    allProductsSelected
                                                }
                                                onChange={
                                                    toggleSelectAll
                                                }
                                                disabled={
                                                    products.length === 0
                                                }
                                                className="h-4 w-4"
                                            />

                                        </th>

                                        <th className="px-4 py-3 text-left font-semibold text-gray-600">
                                            Product Code
                                        </th>

                                        <th className="px-4 py-3 text-left font-semibold text-gray-600">
                                            Product Name
                                        </th>

                                        <th className="px-4 py-3 text-left font-semibold text-gray-600">
                                            Department
                                        </th>

                                        <th className="px-4 py-3 text-left font-semibold text-gray-600">
                                            Category
                                        </th>

                                        <th className="px-4 py-3 text-left font-semibold text-gray-600">
                                            Supplier
                                        </th>

                                        <th className="px-4 py-3 text-right font-semibold text-gray-600">
                                            Stock
                                        </th>

                                    </tr>

                                </thead>


                                <tbody className="divide-y">

                                    {products.length === 0 ? (

                                        <tr>

                                            <td
                                                colSpan="7"
                                                className="px-4 py-12 text-center"
                                            >

                                                <Package
                                                    size={40}
                                                    className="mx-auto mb-3 text-gray-300"
                                                />

                                                <div className="font-medium text-gray-600">
                                                    No products found
                                                </div>

                                                <div className="mt-1 text-sm text-gray-400">
                                                    Select filters and click Search Products.
                                                </div>

                                            </td>

                                        </tr>

                                    ) : (

                                        products.map(
                                            (product, index) => {

                                                const productID =
                                                    getProductID(
                                                        product
                                                    );

                                                return (

                                                    <tr
                                                        key={
                                                            productID ||
                                                            index
                                                        }
                                                        className="hover:bg-gray-50"
                                                    >

                                                        <td className="px-4 py-3">

                                                            <input
                                                                type="checkbox"
                                                                checked={
                                                                    isSelected(
                                                                        product
                                                                    )
                                                                }
                                                                onChange={() =>
                                                                    toggleProduct(
                                                                        product
                                                                    )
                                                                }
                                                                className="h-4 w-4"
                                                            />

                                                        </td>


                                                        <td className="px-4 py-3 font-medium text-gray-800">

                                                            {
                                                                product.ProductCode ||
                                                                "-"
                                                            }

                                                        </td>


                                                        <td className="px-4 py-3 text-gray-700">

                                                            {
                                                                product.ProductName ||
                                                                "-"
                                                            }

                                                        </td>


                                                        <td className="px-4 py-3 text-gray-600">

                                                            {
                                                                product.Department ||
                                                                "-"
                                                            }

                                                        </td>


                                                        <td className="px-4 py-3 text-gray-600">

                                                            {
                                                                product.Category ||
                                                                "-"
                                                            }

                                                        </td>


                                                        <td className="px-4 py-3 text-gray-600">

                                                            {
                                                                product.Supplier ||
                                                                "-"
                                                            }

                                                        </td>

                                                        <td className="px-4 py-3 text-right font-semibold text-gray-700">

                                                            {Number(
                                                                product.SystemStock ??
                                                                product.Stock ??
                                                                product.CurrentStock ??
                                                                product.Qty ??
                                                                product.Quantity ??
                                                                0
                                                            ).toFixed(2)}

                                                        </td>

                                                    </tr>

                                                );

                                            }
                                        )

                                    )}

                                </tbody>

                            </table>

                        </div>


                        {/* SELECTION FOOTER */}

                        <div className="flex flex-col gap-4 border-t bg-gray-50 p-5 md:flex-row md:items-center md:justify-between">


                            <div>

                                <div className="text-sm font-medium text-gray-700">

                                    Selected Products:
                                    <span className="ml-2 rounded-full bg-blue-100 px-3 py-1 text-blue-700">
                                        {selectedProducts.length}
                                    </span>

                                </div>

                                <div className="mt-1 text-xs text-gray-500">
                                    Location: {locationID || "Not available"}
                                </div>

                            </div>


                            <button
                                type="button"
                                onClick={startSession}
                                disabled={
                                    startingSession ||
                                    selectedProducts.length === 0 ||
                                   
                                    !locationID
                                }
                                className="inline-flex items-center justify-center gap-2 rounded-lg bg-green-600 px-6 py-3 text-sm font-bold text-white hover:bg-green-700 disabled:cursor-not-allowed disabled:opacity-50"
                            >

                                {startingSession ? (

                                    <Loader2
                                        size={18}
                                        className="animate-spin"
                                    />

                                ) : (

                                    <Plus size={18} />

                                )}

                                Start Stock Count

                            </button>

                        </div>

                    </div>

                )}

            </div>

        </div>

    );

}


export default StockCount;