// ============================================================
// CreateProduct.jsx — with Cashier Permissions
// ============================================================
import React, {
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import axios from "axios";
import * as XLSX from "xlsx";
import { AuthContext } from "./SERVER/AuthContext.js";
import { usePermissions as usePermissionsContext } from "../context/PermissionsContext";

// ------------------------------------------------------------
// Adapter: exposes the API products.jsx expects —
//   can(module, "Add" | "Edit" | "Delete" | "View" | "Print")
//   canField(module, "CostPrice" | "SellingPrice" | "Profit")
// backed by the PermissionsContext.
// ------------------------------------------------------------
const ACTION_TO_COLUMN = {
  View:   "CanView",
  Add:    "CanAdd",
  Edit:   "CanEdit",
  Delete: "CanDelete",
  Print:  "CanPrint",
};

const FIELD_TO_COLUMN = {
  CostPrice:    "CanViewCostPrice",
  SellingPrice: "CanViewSellingPrice",
  Profit:       "CanViewProfit",
};

function usePermissions() {
  const ctx = usePermissionsContext();

  const can = useCallback(
    (moduleName, action = "View") => {
      const column = ACTION_TO_COLUMN[action] || action;
      return ctx.can(moduleName, null, column);
    },
    [ctx]
  );

  const canField = useCallback(
    (moduleName, field) => {
      const column = FIELD_TO_COLUMN[field];
      if (!column) return true; // unknown field → don't hide it
      return ctx.can(moduleName, null, column);
    },
    [ctx]
  );

  return {
    permissions: ctx.permissions,
    loading: ctx.loading,
    error: ctx.error,
    reload: ctx.reload,
    can,
    canField,
  };
}

const API_URL = "http://localhost:5000";

const EMPTY_FORM = {
  code: "",
  productname: "",
  Description: "",
  Costprice: "",
  Sellingprice: "",
  Discountprice: "",
  Maximumprice: "",
  Minimumprice: "",
  discountPercentage: "",
  dollarprice: "",
  Department: "",
  Category: "",
  SubCategory: "",
  WholesalePrice: "",
  isactive: "1",
  istax: "0",
  reorderlevel: "",
  reorderqty: "",
  supplier: "",
  expirydate: "",
  Isprintable: "0",
  ProductType: "Standard",
  Unit: "Nos",
};

// ============================================================
// HELPERS
// ============================================================

const normalizeArrayResponse = (response) => {
  const payload = response?.data;
  if (Array.isArray(payload)) return payload;
  if (Array.isArray(payload?.data)) return payload.data;
  if (Array.isArray(payload?.recordset)) return payload.recordset;
  return [];
};

const firstValue = (...values) => {
  for (const value of values) {
    if (value !== undefined && value !== null && value !== "") {
      return value;
    }
  }
  return "";
};

const toBitString = (value, fallback = "0") => {
  if (value === undefined || value === null || value === "") return fallback;
  if (typeof value === "boolean") return value ? "1" : "0";

  const text = String(value).trim().toLowerCase();
  if (["1", "true", "yes", "y", "active"].includes(text)) return "1";
  if (["0", "false", "no", "n", "inactive"].includes(text)) return "0";

  const parsed = Number(text);
  return Number.isFinite(parsed) && parsed ? "1" : "0";
};

const formatDateTimeLocal = (value) => {
  if (value === undefined || value === null || value === "") return "";

  const date = value instanceof Date ? value : new Date(value);
  if (!Number.isNaN(date.getTime())) {
    const pad = (n) => String(n).padStart(2, "0");
    return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(
      date.getDate()
    )}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
  }

  const text = String(value);
  if (text.includes("T")) return text.substring(0, 16);
  if (text.includes(" ")) return text.replace(" ", "T").substring(0, 16);
  return "";
};

const getDepartmentText = (item) => {
  const code = firstValue(item?.DepartmentCode, item?.departmentCode);
  const name = firstValue(item?.DepartmentName, item?.departmentName);
  if (code && name) return `${code} - ${name}`;
  return firstValue(name, code, item?.Department);
};

const getCategoryText = (item) => {
  const code = firstValue(item?.CategoryCode, item?.categoryCode);
  const name = firstValue(item?.CategoryName, item?.categoryName);
  if (code && name) return `${code} - ${name}`;
  return firstValue(name, code, item?.Category);
};

const getSubCategoryText = (item) => {
  const code = firstValue(item?.SubCategoryCode, item?.subcategoryCode);
  const name = firstValue(item?.SubCategoryName, item?.subcategoryName);
  if (code && name) return `${code} - ${name}`;
  return firstValue(name, code, item?.SubCategory);
};

const getSupplierText = (item) => {
  const code = firstValue(item?.SupplierCode, item?.supplierCode);
  const name = firstValue(item?.SupplierName, item?.supplierName);
  if (code && name) return `${code} - ${name}`;
  return firstValue(name, code, item?.Supplier);
};

const money = (value) =>
  Number(value || 0).toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });

// ============================================================
// COMPONENT
// ============================================================

function CreateProduct() {
  const { user } = useContext(AuthContext);
  const locationID = user?.location || "";

  // ------------------------------------------------------------
  // PERMISSIONS
  // ------------------------------------------------------------
  const { can, canField } = usePermissions();

  const canViewCost    = canField("Products", "CostPrice");
  const canViewSelling = canField("Products", "SellingPrice");
  const canViewProfit  = canField("Products", "Profit");

  const canAddProduct    = can("Products", "Add");
  const canEditProduct   = can("Products", "Edit");
  const canDeleteProduct = can("Products", "Delete");

  // ============================================================
  // STATE
  // ============================================================
  const [form, setForm] = useState(EMPTY_FORM);

  const [results, setResults] = useState([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [searchOpen, setSearchOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(0);

  const [comboSearch, setComboSearch] = useState("");
  const [comboSearchResults, setComboSearchResults] = useState([]);
  const [comboComponents, setComboComponents] = useState([]);
  const [comboSearchLoading, setComboSearchLoading] = useState(false);

  const [departments, setDepartments] = useState([]);
  const [categories, setCategories] = useState([]);
  const [subCategories, setSubCategories] = useState([]);
  const [suppliers, setSuppliers] = useState([]);

  const [lookupModal, setLookupModal] = useState(null);
  const [lookupSearch, setLookupSearch] = useState("");

  const [excelData, setExcelData] = useState([]);
  const [excelLoading, setExcelLoading] = useState(false);

  const [imageFile, setImageFile] = useState(null);
  const [imagePreview, setImagePreview] = useState("");

  const [loading, setLoading] = useState(false);
  const [lookupLoading, setLookupLoading] = useState(false);

  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  const [isEditMode, setIsEditMode] = useState(false);

  const searchRef = useRef(null);
  const fileInputRef = useRef(null);
  const lookupInputRef = useRef(null);

  // ============================================================
  // FORM CHANGE
  // ============================================================
  const handleChange = (event) => {
    const { name, value } = event.target;
    setForm((previous) => ({ ...previous, [name]: value }));
  };

  // ============================================================
  // IMAGE PREVIEW
  // ============================================================
  useEffect(() => {
    if (!imageFile) {
      setImagePreview("");
      return undefined;
    }

    const objectUrl = URL.createObjectURL(imageFile);
    setImagePreview(objectUrl);

    return () => URL.revokeObjectURL(objectUrl);
  }, [imageFile]);

  // ============================================================
  // PRODUCT SEARCH
  // ============================================================
  const handleSearch = useCallback(
    async (value) => {
      const searchValue = String(value || "").trim();
      setSearchQuery(value);

      if (!searchValue) {
        setResults([]);
        setSearchOpen(false);
        setActiveIndex(0);
        return;
      }

      try {
        setError("");
        const response = await axios.get(`${API_URL}/search`, {
          params: { LocationID: locationID, q: searchValue },
        });
        const rows = normalizeArrayResponse(response);
        setResults(rows);
        setSearchOpen(rows.length > 0);
        setActiveIndex(0);
      } catch (err) {
        console.error("PRODUCT SEARCH ERROR:", err);
        setResults([]);
        setSearchOpen(false);
        setError(err?.response?.data?.message || "Unable to search products.");
      }
    },
    [locationID]
  );

  const handleProductSearchKeyDown = (event) => {
    if (event.key === "ArrowDown") {
      event.preventDefault();
      if (!results.length) return;
      setSearchOpen(true);
      setActiveIndex((prev) => (prev < results.length - 1 ? prev + 1 : 0));
    }
    if (event.key === "ArrowUp") {
      event.preventDefault();
      if (!results.length) return;
      setSearchOpen(true);
      setActiveIndex((prev) => (prev > 0 ? prev - 1 : results.length - 1));
    }
    if (event.key === "Enter") {
      event.preventDefault();
      if (searchOpen && results.length && results[activeIndex]) {
        loadProduct(results[activeIndex]);
      }
    }
    if (event.key === "Escape") setSearchOpen(false);
  };

  // ============================================================
  // LOAD PRODUCT
  // ============================================================
  const loadProduct = useCallback(async (item) => {
    if (!item) return;

    const code = String(
      firstValue(item.ProductCode, item.productCode, item.code)
    ).trim();
    if (!code) return;

    try {
      setLoading(true);
      setError("");

      const detail = await axios.get(
        `${API_URL}/api/products/${encodeURIComponent(code)}`
      );
      const full = detail?.data?.data;

      if (!detail?.data?.success || !full) {
        throw new Error(
          "Complete product details were not returned by the server."
        );
      }

      const loadedForm = {
        code: String(firstValue(full.ProductCode, full.productCode, full.code)),
        productname: String(
          firstValue(full.ProductName, full.productName, full.productname)
        ),
        Unit: String(
          firstValue(full.Unit, full.unit, full.Units, full.units, "Nos")
        ),
        Description: String(firstValue(full.Description, full.description)),
        Costprice: firstValue(full.CostPrice, full.costPrice, full.Costprice),
        Sellingprice: firstValue(
          full.SellingPrice,
          full.sellingPrice,
          full.Sellingprice
        ),
        Discountprice: firstValue(
          full.FixedDiscount,
          full.DiscountPrice,
          full.discountPrice,
          full.Discountprice
        ),
        Maximumprice: firstValue(full.MaximumPrice, full.maximumPrice),
        Minimumprice: firstValue(full.MinimumPrice, full.minimumPrice),
        discountPercentage: firstValue(
          full.FixedDiscountPercentage,
          full.DiscountPercentage,
          full.discountPercentage
        ),
        dollarprice: firstValue(
          full.ForigenPrice,
          full.ForeignPrice,
          full.foreignPrice,
          full.DollarPrice,
          full.dollarPrice
        ),
        Department: firstValue(full.Department, full.department),
        Category: firstValue(full.Category, full.category),
        SubCategory: firstValue(full.SubCategory, full.subCategory),
        WholesalePrice: firstValue(full.WholesalePrice, full.wholesalePrice),
        isactive: toBitString(
          firstValue(full.IsActive, full.isactive, full.Isactive, full.Status),
          "1"
        ),
        istax: toBitString(firstValue(full.IsTax, full.istax, full.ISTax), "0"),
        Isprintable: toBitString(
          firstValue(full.Isprintable, full.IsPrintable, full.isprintable),
          "0"
        ),
        reorderlevel: firstValue(
          full.ReOrderLevel,
          full.ReorderLevel,
          full.reorderlevel
        ),
        reorderqty: firstValue(full.ReOrderQty, full.ReorderQty, full.reorderqty),
        supplier: firstValue(full.Supplier, full.supplier),
        expirydate: formatDateTimeLocal(
          firstValue(
            full.Expirydate,
            full.ExpiryDate,
            full.expirydate,
            full.ExpiryDateTime
          )
        ),
        ProductType: String(
          firstValue(
            full.ProductType,
            full.productType,
            full.producttype,
            "Standard"
          )
        ),
      };

      setForm(loadedForm);

      const savedCombo = firstValue(
        full.comboComponents,
        full.ComboComponents,
        []
      );

      setComboComponents(
        Array.isArray(savedCombo)
          ? savedCombo
              .map((component) => ({
                code: String(
                  firstValue(
                    component.ComponentProductCode,
                    component.ProductCode,
                    component.code
                  )
                ),
                name: String(
                  firstValue(
                    component.ComponentProductName,
                    component.ProductName,
                    component.name
                  )
                ),
                quantity: Number(
                  firstValue(component.Quantity, component.quantity, 1)
                ),
              }))
              .filter((component) => component.code)
          : []
      );

      setComboSearch("");
      setComboSearchResults([]);
      setIsEditMode(true);
      setSearchQuery(`${loadedForm.code} - ${loadedForm.productname}`);
      setSearchOpen(false);
      setResults([]);
      setMessage("");
      setError("");
      setImageFile(null);

      setImagePreview(full.imageUrl || "");
    } catch (err) {
      console.error("LOAD PRODUCT ERROR:", err);
      setError(
        err?.response?.data?.message ||
          err?.message ||
          "Unable to load complete product details."
      );
    } finally {
      setLoading(false);
    }
  }, []);

  // ============================================================
  // GENERATE PRODUCT CODE
  // ============================================================
  const handleGenerateProductCode = async () => {
    try {
      setError("");
      setMessage("");

      const response = await axios.get(`${API_URL}/productcode`, {
        params: { LocationID: locationID },
      });
      const rows = normalizeArrayResponse(response);

      if (!rows.length) {
        setForm((prev) => ({ ...prev, code: "001" }));
        setIsEditMode(false);
        setSearchQuery("");
        setMessage("New product code generated: 001");
        return;
      }

      const numericCodes = rows
        .map((item) =>
          Number(
            firstValue(
              item.ProductCode,
              item.productcode,
              item.productCode,
              item.code
            )
          )
        )
        .filter((value) => Number.isFinite(value));

      const highestCode =
        numericCodes.length > 0 ? Math.max(...numericCodes) : 0;
      const nextCode = String(highestCode + 1).padStart(3, "0");

      setForm((prev) => ({ ...prev, code: nextCode }));
      setIsEditMode(false);
      setSearchQuery("");
      setMessage(`New product code generated: ${nextCode}`);
    } catch (err) {
      console.error("GENERATE PRODUCT CODE ERROR:", err);
      setError(
        err?.response?.data?.message || "Unable to generate product code."
      );
    }
  };

  // ============================================================
  // LOOKUPS
  // ============================================================
  const loadDepartments = async () => {
    try {
      setLookupLoading(true);
      setError("");
      const response = await axios.get(`${API_URL}/departments`);
      setDepartments(normalizeArrayResponse(response));
    } catch (err) {
      console.error("LOAD DEPARTMENTS ERROR:", err);
      setError(err?.response?.data?.message || "Unable to load departments.");
    } finally {
      setLookupLoading(false);
    }
  };

  const loadCategories = async () => {
    try {
      setLookupLoading(true);
      setError("");
      const response = await axios.get(`${API_URL}/Category`);
      setCategories(normalizeArrayResponse(response));
    } catch (err) {
      console.error("LOAD CATEGORIES ERROR:", err);
      setError(err?.response?.data?.message || "Unable to load categories.");
    } finally {
      setLookupLoading(false);
    }
  };

  const loadSubCategories = async () => {
    try {
      setLookupLoading(true);
      setError("");
      const response = await axios.get(`${API_URL}/SubCategory`);
      setSubCategories(normalizeArrayResponse(response));
    } catch (err) {
      console.error("LOAD SUBCATEGORIES ERROR:", err);
      setError(err?.response?.data?.message || "Unable to load subcategories.");
    } finally {
      setLookupLoading(false);
    }
  };

  const loadSuppliers = async () => {
    try {
      setLookupLoading(true);
      setError("");
      const response = await axios.get(`${API_URL}/Supplier`);
      setSuppliers(normalizeArrayResponse(response));
    } catch (err) {
      console.error("LOAD SUPPLIERS ERROR:", err);
      setError(err?.response?.data?.message || "Unable to load suppliers.");
    } finally {
      setLookupLoading(false);
    }
  };

  const openLookup = async (type) => {
    setLookupModal(type);
    setLookupSearch("");
    setError("");

    if (type === "department") await loadDepartments();
    if (type === "category") await loadCategories();
    if (type === "subcategory") await loadSubCategories();
    if (type === "supplier") await loadSuppliers();
  };

  // ============================================================
  // F12 LOOKUP SHORTCUTS
  // ============================================================
  useEffect(() => {
    const handleF12 = (event) => {
      if (event.key !== "F12") return;
      event.preventDefault();

      const target = event.target;
      if (!target || !target.name) return;

      if (target.name === "Department") openLookup("department");
      if (target.name === "Category") openLookup("category");
      if (target.name === "SubCategory") openLookup("subcategory");
      if (target.name === "supplier") openLookup("supplier");
    };

    window.addEventListener("keydown", handleF12);
    return () => window.removeEventListener("keydown", handleF12);
  });

  // ============================================================
  // COMBO COMPONENT SEARCH
  // ============================================================
  useEffect(() => {
    const query = comboSearch.trim();

    if (form.ProductType !== "Combo" || !query) {
      setComboSearchResults([]);
      setComboSearchLoading(false);
      return undefined;
    }

    let cancelled = false;

    const timer = setTimeout(async () => {
      try {
        setComboSearchLoading(true);

        const response = await axios.get(`${API_URL}/search`, {
          params: { LocationID: locationID, q: query },
        });

        const rows = normalizeArrayResponse(response).filter((item) => {
          const code = String(
            firstValue(item.ProductCode, item.productCode, item.code)
          ).trim();
          return (
            code &&
            code !== String(form.code).trim() &&
            !comboComponents.some((c) => c.code === code)
          );
        });

        if (!cancelled) setComboSearchResults(rows);
      } catch (err) {
        if (!cancelled) setComboSearchResults([]);
        console.error("COMBO COMPONENT SEARCH ERROR:", err);
      } finally {
        if (!cancelled) setComboSearchLoading(false);
      }
    }, 250);

    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [comboSearch, form.ProductType, form.code, locationID, comboComponents]);

  const addComboComponent = (item) => {
    const code = String(
      firstValue(item.ProductCode, item.productCode, item.code)
    ).trim();
    const name = String(
      firstValue(item.ProductName, item.productName, item.productname)
    ).trim();

    if (!code || code === String(form.code).trim()) return;

    setComboComponents((prev) =>
      prev.some((c) => c.code === code)
        ? prev
        : [...prev, { code, name, quantity: 1 }]
    );

    setComboSearch("");
    setComboSearchResults([]);
  };

  const updateComboQuantity = (code, quantity) => {
    setComboComponents((prev) =>
      prev.map((c) =>
        c.code === code
          ? { ...c, quantity: Math.max(0.01, Number(quantity) || 1) }
          : c
      )
    );
  };

  // ============================================================
  // LOOKUP SEARCH FILTER
  // ============================================================
  const filteredLookupData = useMemo(() => {
    const search = lookupSearch.trim().toLowerCase();

    let source = [];
    if (lookupModal === "department") source = departments;
    if (lookupModal === "category") source = categories;
    if (lookupModal === "subcategory") source = subCategories;
    if (lookupModal === "supplier") source = suppliers;

    if (!search) return source;

    return source.filter((item) => {
      const text = [
        item?.DepartmentCode,
        item?.DepartmentName,
        item?.CategoryCode,
        item?.CategoryName,
        item?.SubCategoryCode,
        item?.SubCategoryName,
        item?.SupplierCode,
        item?.SupplierName,
        item?.Code,
        item?.Name,
      ]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();

      return text.includes(search);
    });
  }, [lookupModal, lookupSearch, departments, categories, subCategories, suppliers]);

  useEffect(() => {
    if (!lookupModal) return;
    const timer = setTimeout(() => lookupInputRef.current?.focus(), 50);
    return () => clearTimeout(timer);
  }, [lookupModal]);

  const handleLookupKeyDown = (event) => {
    if (event.key === "Escape") {
      setLookupModal(null);
      return;
    }
    if (event.key === "Enter") {
      event.preventDefault();
      if (filteredLookupData.length === 1) {
        selectLookupItem(filteredLookupData[0]);
      }
    }
  };

  // ============================================================
  // SELECT LOOKUP ITEM
  // ============================================================
  const selectLookupItem = (item) => {
    if (!item) return;

    if (lookupModal === "department") {
      setForm((prev) => ({
        ...prev,
        Department: getDepartmentText(item),
        Category: "",
        SubCategory: "",
      }));
    }
    if (lookupModal === "category") {
      setForm((prev) => ({
        ...prev,
        Category: getCategoryText(item),
        SubCategory: "",
      }));
    }
    if (lookupModal === "subcategory") {
      setForm((prev) => ({ ...prev, SubCategory: getSubCategoryText(item) }));
    }
    if (lookupModal === "supplier") {
      setForm((prev) => ({ ...prev, supplier: getSupplierText(item) }));
    }

    setLookupModal(null);
    setLookupSearch("");
  };

  // ============================================================
  // EXCEL IMPORT
  // ============================================================
  const handleFileUpload = async (event) => {
    const file = event.target.files?.[0];
    if (!file) return;

    try {
      setExcelLoading(true);
      setError("");
      setMessage("");

      const buffer = await file.arrayBuffer();
      const workbook = XLSX.read(buffer, { type: "array" });
      const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
      const json = XLSX.utils.sheet_to_json(firstSheet, { defval: "" });

      setExcelData(json);

      if (!json.length) {
        setMessage("The Excel file contains no data.");
        return;
      }

      const formData = new FormData();
      formData.append("file", file);

      const response = await axios.post(`${API_URL}/api/import`, formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });

      setMessage(
        response?.data?.message ||
          `Excel import completed. ${json.length} rows loaded.`
      );
    } catch (err) {
      console.error("EXCEL IMPORT ERROR:", err);
      setError(err?.response?.data?.message || "Excel import failed.");
    } finally {
      setExcelLoading(false);
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  // ============================================================
  // RESET FORM
  // ============================================================
  const resetForm = () => {
    setForm({ ...EMPTY_FORM });
    setImageFile(null);
    setImagePreview("");
    setComboComponents([]);
    setComboSearch("");
    setComboSearchResults([]);
    setSearchQuery("");
    setResults([]);
    setSearchOpen(false);
    setIsEditMode(false);
    setExcelData([]);
    setMessage("");
    setError("");
  };

  // ============================================================
  // SAVE PRODUCT (guarded)
  // ============================================================
  const handleSubmit = async (event) => {
    event.preventDefault();

    setMessage("");
    setError("");

    if (isEditMode && !canEditProduct) {
      setError("You do not have permission to edit products.");
      return;
    }
    if (!isEditMode && !canAddProduct) {
      setError("You do not have permission to create products.");
      return;
    }

    if (!form.code.trim()) {
      setError("Product code is required.");
      return;
    }
    if (!form.productname.trim()) {
      setError("Product name is required.");
      return;
    }
    if (form.ProductType === "Combo" && comboComponents.length === 0) {
      setError("Select at least one component product for a combo product.");
      return;
    }

    try {
      setLoading(true);

      const formData = new FormData();

      Object.entries(form).forEach(([key, value]) => {
        if (key === "Costprice" && !canViewCost) return;
        if (key === "Sellingprice" && !canViewSelling) return;
        formData.append(key, value ?? "");
      });

      formData.append(
        "comboComponents",
        JSON.stringify(form.ProductType === "Combo" ? comboComponents : [])
      );

      if (user?.username) formData.append("username", user.username);
      if (locationID) formData.append("LocationID", locationID);
      if (imageFile) formData.append("image", imageFile);

      let response;

      if (isEditMode) {
        response = await axios.put(
          `${API_URL}/api/products/${encodeURIComponent(form.code)}`,
          formData,
          { headers: { "Content-Type": "multipart/form-data" } }
        );
      } else {
        response = await axios.post(`${API_URL}/api/products`, formData, {
          headers: { "Content-Type": "multipart/form-data" },
        });
      }

      setMessage(
        response?.data?.message ||
          (isEditMode
            ? "Product updated successfully."
            : "Product saved successfully.")
      );

      setIsEditMode(false);
    } catch (err) {
      console.error(
        isEditMode ? "UPDATE PRODUCT ERROR:" : "SAVE PRODUCT ERROR:",
        err
      );
      setError(
        err?.response?.data?.message ||
          (isEditMode
            ? "Unable to update product."
            : "Unable to save product.")
      );
    } finally {
      setLoading(false);
    }
  };

  // ============================================================
  // DELETE PRODUCT (guarded)
  // ============================================================
  const handleDelete = async () => {
    if (!canDeleteProduct) {
      setError("You do not have permission to delete products.");
      return;
    }
    if (!form.code.trim()) {
      setError("Select a product before deleting.");
      return;
    }

    const confirmed = window.confirm(
      `Are you sure you want to delete product "${form.code} - ${form.productname}"?`
    );
    if (!confirmed) return;

    try {
      setLoading(true);
      setMessage("");
      setError("");

      const response = await axios.delete(
        `${API_URL}/api/products/${encodeURIComponent(form.code)}`,
        {
          data: {
            username: user?.username || "",
            LocationID: locationID,
          },
        }
      );

      setMessage(response?.data?.message || "Product deleted successfully.");
      resetForm();
    } catch (err) {
      console.error("DELETE PRODUCT ERROR:", err);
      setError(err?.response?.data?.message || "Unable to delete product.");
    } finally {
      setLoading(false);
    }
  };

  // ============================================================
  // SMALL UTILS
  // ============================================================
  const getResultImage = (item) => item?.imageUrl || item?.ImageUrl || "";

  const lookupTitle = {
    department: "Select Department",
    category: "Select Category",
    subcategory: "Select SubCategory",
    supplier: "Select Supplier",
  };

  const getLookupPrimary = (item) => {
    if (lookupModal === "department") return getDepartmentText(item);
    if (lookupModal === "category") return getCategoryText(item);
    if (lookupModal === "subcategory") return getSubCategoryText(item);
    if (lookupModal === "supplier") return getSupplierText(item);
    return "";
  };

  const getLookupSecondary = (item) => {
    if (lookupModal === "department") return firstValue(item?.Remark, item?.remark);
    if (lookupModal === "category") return firstValue(item?.Department, item?.Remark);
    if (lookupModal === "subcategory") return firstValue(item?.Category, item?.Remark);
    if (lookupModal === "supplier") {
      return firstValue(
        item?.ContactPersonName,
        item?.Email,
        item?.BillingMobile
      );
    }
    return "";
  };

  const liveProfit = useMemo(() => {
    const cost = Number(form.Costprice) || 0;
    const selling = Number(form.Sellingprice) || 0;
    const profit = selling - cost;
    const margin = selling > 0 ? (profit / selling) * 100 : 0;
    return { cost, selling, profit, margin };
  }, [form.Costprice, form.Sellingprice]);

  const saveAllowed =
    (isEditMode && canEditProduct) || (!isEditMode && canAddProduct);

  // ============================================================
  // RENDER
  // ============================================================
  return (
    <div className="min-h-screen bg-slate-100 p-4 md:p-6">
      <div className="mx-auto max-w-7xl">
        {/* ============ HEADER ============ */}
        <div className="mb-5 rounded-xl bg-white shadow-sm border border-slate-200">
          <div className="flex flex-col gap-4 p-5 lg:flex-row lg:items-center lg:justify-between">
            <div>
              <h1 className="text-2xl font-bold text-slate-800">
                Product Master
              </h1>
              <p className="mt-1 text-sm text-slate-500">
                Create, search, edit and delete products
              </p>
            </div>

            <div className="flex flex-wrap gap-2">
              {canAddProduct && (
                <>
                  <button
                    type="button"
                    onClick={() => fileInputRef.current?.click()}
                    disabled={excelLoading}
                    className="rounded-lg bg-emerald-600 px-4 py-2.5 text-sm font-semibold text-white shadow-sm transition hover:bg-emerald-700 disabled:cursor-not-allowed disabled:opacity-50"
                  >
                    {excelLoading ? "Importing..." : "Import Excel"}
                  </button>

                  <input
                    ref={fileInputRef}
                    type="file"
                    accept=".xlsx,.xls,.csv"
                    onChange={handleFileUpload}
                    className="hidden"
                  />
                </>
              )}

              <button
                type="button"
                onClick={resetForm}
                className="rounded-lg bg-slate-600 px-4 py-2.5 text-sm font-semibold text-white shadow-sm transition hover:bg-slate-700"
              >
                New / Clear
              </button>
            </div>
          </div>
        </div>

        {/* ============ MESSAGES ============ */}
        {message && (
          <div className="mb-4 rounded-lg border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-medium text-emerald-700">
            {message}
          </div>
        )}

        {error && (
          <div className="mb-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700">
            {error}
          </div>
        )}

        {/* ============ PRODUCT SEARCH ============ */}
        <div className="mb-5 rounded-xl border border-slate-200 bg-white p-5 shadow-sm">
          <div className="mb-2 flex items-center justify-between">
            <label className="text-sm font-semibold text-slate-700">
              Search Existing Product
            </label>
            <span className="text-xs text-slate-400">
              ↑ ↓ Navigate &nbsp; Enter Select &nbsp; Esc Close
            </span>
          </div>

          <div ref={searchRef} className="relative">
            <input
              type="text"
              value={searchQuery}
              onChange={(event) => handleSearch(event.target.value)}
              onKeyDown={handleProductSearchKeyDown}
              placeholder="Search by product code or product name..."
              className="w-full rounded-lg border border-slate-300 bg-white px-4 py-3 text-sm outline-none transition focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
            />

            {searchOpen && results.length > 0 && (
              <div className="absolute z-40 mt-1 max-h-80 w-full overflow-y-auto rounded-lg border border-slate-200 bg-white shadow-xl">
                {results.map((item, index) => {
                  const code = firstValue(
                    item.ProductCode,
                    item.productCode,
                    item.code
                  );
                  const name = firstValue(
                    item.ProductName,
                    item.productName,
                    item.productname
                  );
                  const image = getResultImage(item);

                  const showSellPrice =
                    canViewSelling &&
                    item.SellingPrice !== undefined &&
                    item.SellingPrice !== null;

                  const showCostPrice =
                    canViewCost &&
                    item.CostPrice !== undefined &&
                    item.CostPrice !== null;

                  return (
                    <button
                      key={`${code}-${index}`}
                      type="button"
                      onMouseDown={(event) => {
                        event.preventDefault();
                        loadProduct(item);
                      }}
                      className={`flex w-full items-center gap-3 border-b border-slate-100 px-4 py-3 text-left transition last:border-b-0 ${
                        index === activeIndex ? "bg-blue-50" : "hover:bg-slate-50"
                      }`}
                    >
                      {image ? (
                        <img
                          src={image}
                          alt={name}
                          className="h-12 w-12 rounded-lg border border-slate-200 object-cover"
                        />
                      ) : (
                        <div className="flex h-12 w-12 items-center justify-center rounded-lg bg-slate-100 text-xs text-slate-400">
                          No Image
                        </div>
                      )}

                      <div className="min-w-0 flex-1">
                        <div className="font-semibold text-slate-800">
                          {code}
                        </div>
                        <div className="truncate text-sm text-slate-500">
                          {name}
                        </div>
                      </div>

                      {(showSellPrice || showCostPrice) && (
                        <div className="text-right text-xs text-slate-500">
                          {showSellPrice && (
                            <div>
                              Sell:{" "}
                              <span className="font-semibold text-slate-700">
                                {money(item.SellingPrice)}
                              </span>
                            </div>
                          )}
                          {showCostPrice && (
                            <div>
                              Cost:{" "}
                              <span className="font-semibold text-slate-700">
                                {money(item.CostPrice)}
                              </span>
                            </div>
                          )}
                        </div>
                      )}

                      {index === activeIndex && (
                        <span className="text-xs font-semibold text-blue-600">
                          ENTER
                        </span>
                      )}
                    </button>
                  );
                })}
              </div>
            )}
          </div>
        </div>

        {/* ============ EXCEL PREVIEW ============ */}
        {excelData.length > 0 && (
          <div className="mb-5 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
            <div className="flex items-center justify-between border-b border-slate-200 px-5 py-4">
              <div>
                <h2 className="font-semibold text-slate-800">Excel Preview</h2>
                <p className="text-xs text-slate-500">
                  {excelData.length} rows
                </p>
              </div>

              <button
                type="button"
                onClick={() => setExcelData([])}
                className="rounded-lg bg-slate-100 px-3 py-2 text-xs font-semibold text-slate-600 hover:bg-slate-200"
              >
                Close Preview
              </button>
            </div>

            <div className="max-h-72 overflow-auto">
              <table className="min-w-full text-left text-xs">
                <thead className="sticky top-0 bg-slate-100">
                  <tr>
                    {Object.keys(excelData[0]).map((key) => (
                      <th
                        key={key}
                        className="whitespace-nowrap border-b border-slate-200 px-3 py-2 font-bold text-slate-700"
                      >
                        {key}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {excelData.slice(0, 100).map((row, rowIndex) => (
                    <tr key={rowIndex} className="hover:bg-slate-50">
                      {Object.keys(excelData[0]).map((key) => (
                        <td
                          key={key}
                          className="whitespace-nowrap border-b border-slate-100 px-3 py-2 text-slate-600"
                        >
                          {row[key]}
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* ============ PRODUCT FORM ============ */}
        <form
          onSubmit={handleSubmit}
          className="rounded-xl border border-slate-200 bg-white shadow-sm"
        >
          <div className="border-b border-slate-200 bg-slate-50 px-5 py-4">
            <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
              <div>
                <h2 className="text-lg font-bold text-slate-800">
                  Product Details
                </h2>
                <p className="text-xs text-slate-500">
                  {isEditMode ? "Edit existing product" : "Create new product"}
                </p>
              </div>

              <div className="flex items-center gap-2">
                {isEditMode && (
                  <span className="w-fit rounded-full bg-amber-100 px-3 py-1 text-xs font-bold text-amber-700">
                    EDIT MODE
                  </span>
                )}
                {isEditMode && !canEditProduct && (
                  <span className="w-fit rounded-full bg-slate-200 px-3 py-1 text-xs font-bold text-slate-600">
                    READ ONLY
                  </span>
                )}
              </div>
            </div>
          </div>

          <div className="p-5">
            {/* ---------- BASIC INFORMATION ---------- */}
            <div className="mb-6">
              <h3 className="mb-3 border-b border-slate-200 pb-2 text-sm font-bold uppercase tracking-wide text-slate-700">
                Basic Information
              </h3>

              <div className="grid grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-3">
                <div>
                  <label className="mb-1 block text-sm font-semibold text-slate-700">
                    Product Code
                  </label>
                  <div className="flex gap-2">
                    <input
                      name="code"
                      value={form.code}
                      onChange={handleChange}
                      disabled={isEditMode}
                      className="min-w-0 flex-1 rounded-lg border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 disabled:bg-slate-100"
                      placeholder="Product Code"
                    />
                    {!isEditMode && (
                      <button
                        type="button"
                        onClick={handleGenerateProductCode}
                        className="rounded-lg bg-blue-600 px-3 py-2 text-xs font-bold text-white hover:bg-blue-700"
                      >
                        New
                      </button>
                    )}
                  </div>
                </div>

                <div>
                  <label className="mb-1 block text-sm font-semibold text-slate-700">
                    Product Name
                  </label>
                  <input
                    name="productname"
                    value={form.productname}
                    onChange={handleChange}
                    className="w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                    placeholder="Product Name"
                  />
                </div>

                <div>
                  <label className="mb-1 block text-sm font-semibold text-slate-700">
                    Unit
                  </label>
                  <select
                    name="Unit"
                    value={form.Unit}
                    onChange={handleChange}
                    className="w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                  >
                    <option value="KG">KG</option>
                    <option value="piece">piece</option>
                    <option value="Nos">Nos</option>
                    <option value="pack">pack</option>
                    <option value="ml">ml</option>
                    <option value="g">g</option>
                    <option value="pcs">pcs</option>
                    <option value="bottle">bottle</option>
                  </select>
                </div>

                <div className="md:col-span-2 lg:col-span-1">
                  <label className="mb-1 block text-sm font-semibold text-slate-700">
                    Description
                  </label>
                  <input
                    name="Description"
                    value={form.Description}
                    onChange={handleChange}
                    className="w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                    placeholder="Description"
                  />
                </div>
              </div>
            </div>

            {/* ---------- PRODUCT OPTIONS ---------- */}
            <div className="mb-6 rounded-xl border border-slate-200 p-4">
              <h3 className="mb-4 border-b border-slate-200 pb-2 text-sm font-bold uppercase tracking-wide text-slate-700">
                Product Options
              </h3>

              <div className="grid grid-cols-1 gap-5 md:grid-cols-2">
                <div>
                  <label className="mb-1 block text-sm font-semibold text-slate-700">
                    Product Type
                  </label>
                  <select
                    name="ProductType"
                    value={form.ProductType}
                    onChange={(event) => {
                      const ProductType = event.target.value;
                      setForm((prev) => ({ ...prev, ProductType }));
                      if (ProductType !== "Combo") {
                        setComboComponents([]);
                        setComboSearch("");
                        setComboSearchResults([]);
                      }
                    }}
                    className="w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                  >
                    <option value="Standard">
                      Standard — physical SKU, deducts stock
                    </option>
                    <option value="Menu Item">
                      Menu Item — restaurant only, no stock
                    </option>
                    <option value="Template">
                      Template — variants drive real SKUs
                    </option>
                    <option value="Combo">
                      Combo — explodes into components on sale
                    </option>
                  </select>
                </div>

                <fieldset>
                  <legend className="mb-2 block text-sm font-semibold text-slate-700">
                    Printable
                  </legend>
                  <div className="flex gap-5 pt-2">
                    <label className="flex items-center gap-2 text-sm text-slate-700">
                      <input
                        type="radio"
                        name="Isprintable"
                        value="1"
                        checked={String(form.Isprintable) === "1"}
                        onChange={handleChange}
                      />
                      Yes
                    </label>
                    <label className="flex items-center gap-2 text-sm text-slate-700">
                      <input
                        type="radio"
                        name="Isprintable"
                        value="0"
                        checked={String(form.Isprintable) !== "1"}
                        onChange={handleChange}
                      />
                      No
                    </label>
                  </div>
                </fieldset>
              </div>

              {form.ProductType === "Combo" && (
                <div className="mt-5 border-t border-slate-100 pt-4">
                  <label className="mb-1 block text-sm font-semibold text-slate-700">
                    Search component products
                  </label>
                  <p className="mb-2 text-xs text-slate-500">
                    Search existing products such as Bottle, Cap, or Insert, then
                    add each component to this combo.
                  </p>

                  <input
                    value={comboSearch}
                    onChange={(event) => setComboSearch(event.target.value)}
                    placeholder="Type product code or name..."
                    className="w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                  />

                  {(comboSearchLoading ||
                    comboSearchResults.length > 0 ||
                    comboSearch.trim()) && (
                    <div className="mt-2 max-h-52 overflow-y-auto rounded-lg border border-slate-200">
                      {comboSearchLoading && (
                        <div className="px-3 py-2 text-sm text-slate-500">
                          Searching products...
                        </div>
                      )}

                      {!comboSearchLoading &&
                        comboSearchResults.map((item, index) => {
                          const code = String(
                            firstValue(
                              item.ProductCode,
                              item.productCode,
                              item.code
                            )
                          );
                          const name = String(
                            firstValue(
                              item.ProductName,
                              item.productName,
                              item.productname
                            )
                          );

                          return (
                            <button
                              key={`${code}-${index}`}
                              type="button"
                              onClick={() => addComboComponent(item)}
                              className="flex w-full items-center justify-between border-b border-slate-100 px-3 py-2 text-left text-sm last:border-b-0 hover:bg-blue-50"
                            >
                              <span>
                                <span className="font-semibold text-slate-800">
                                  {code}
                                </span>
                                <span className="ml-2 text-slate-600">
                                  {name}
                                </span>
                              </span>
                              <span className="font-semibold text-blue-600">
                                Add
                              </span>
                            </button>
                          );
                        })}

                      {!comboSearchLoading &&
                        comboSearch.trim() &&
                        comboSearchResults.length === 0 && (
                          <div className="px-3 py-2 text-sm text-slate-500">
                            No matching products found (or all matches are
                            already selected).
                          </div>
                        )}
                    </div>
                  )}

                  <div className="mt-4 overflow-x-auto">
                    <table className="min-w-full text-left text-sm">
                      <thead className="bg-slate-50 text-xs uppercase text-slate-500">
                        <tr>
                          <th className="px-3 py-2">Component Code</th>
                          <th className="px-3 py-2">Product</th>
                          <th className="px-3 py-2">Quantity</th>
                          <th className="px-3 py-2">Action</th>
                        </tr>
                      </thead>
                      <tbody>
                        {comboComponents.map((component) => (
                          <tr
                            key={component.code}
                            className="border-t border-slate-100"
                          >
                            <td className="px-3 py-2 font-semibold">
                              {component.code}
                            </td>
                            <td className="px-3 py-2">{component.name}</td>
                            <td className="px-3 py-2">
                              <input
                                type="number"
                                min="0.01"
                                step="0.01"
                                value={component.quantity}
                                onChange={(event) =>
                                  updateComboQuantity(
                                    component.code,
                                    event.target.value
                                  )
                                }
                                className="w-24 rounded border border-slate-300 px-2 py-1"
                              />
                            </td>
                            <td className="px-3 py-2">
                              <button
                                type="button"
                                onClick={() =>
                                  setComboComponents((prev) =>
                                    prev.filter(
                                      (row) => row.code !== component.code
                                    )
                                  )
                                }
                                className="font-semibold text-red-600 hover:text-red-700"
                              >
                                Remove
                              </button>
                            </td>
                          </tr>
                        ))}

                        {comboComponents.length === 0 && (
                          <tr>
                            <td
                              colSpan="4"
                              className="px-3 py-4 text-center text-slate-400"
                            >
                              No component products selected.
                            </td>
                          </tr>
                        )}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}
            </div>

            {/* ---------- PRICING ---------- */}
            <div className="mb-6">
              <h3 className="mb-3 border-b border-slate-200 pb-2 text-sm font-bold uppercase tracking-wide text-slate-700">
                Pricing
              </h3>

              <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
                {canViewCost && (
                  <PriceInput
                    label="Cost Price"
                    name="Costprice"
                    value={form.Costprice}
                    onChange={handleChange}
                  />
                )}

                {canViewSelling && (
                  <PriceInput
                    label="Selling Price"
                    name="Sellingprice"
                    value={form.Sellingprice}
                    onChange={handleChange}
                  />
                )}

                <PriceInput
                  label="Discount Price"
                  name="Discountprice"
                  value={form.Discountprice}
                  onChange={handleChange}
                />
                <PriceInput
                  label="Discount %"
                  name="discountPercentage"
                  value={form.discountPercentage}
                  onChange={handleChange}
                />
                <PriceInput
                  label="Maximum Price"
                  name="Maximumprice"
                  value={form.Maximumprice}
                  onChange={handleChange}
                />
                <PriceInput
                  label="Minimum Price"
                  name="Minimumprice"
                  value={form.Minimumprice}
                  onChange={handleChange}
                />
                <PriceInput
                  label="Wholesale Price"
                  name="WholesalePrice"
                  value={form.WholesalePrice}
                  onChange={handleChange}
                />
                <PriceInput
                  label="Dollar Price"
                  name="dollarprice"
                  value={form.dollarprice}
                  onChange={handleChange}
                />
              </div>

              {(!canViewCost || !canViewSelling) && (
                <div className="mt-3 rounded-lg border border-amber-200 bg-amber-50 px-4 py-2 text-xs font-medium text-amber-700">
                  Some price fields are hidden by your permission level. Contact
                  an administrator if you need access.
                </div>
              )}
            </div>

            {/* ---------- PROFIT PREVIEW ---------- */}
            {canViewProfit && canViewCost && canViewSelling && (
              <div
                className={`mb-6 rounded-xl border p-4 ${
                  liveProfit.profit >= 0
                    ? "border-emerald-200 bg-emerald-50"
                    : "border-red-200 bg-red-50"
                }`}
              >
                <div className="flex flex-wrap items-center justify-between gap-4">
                  <div>
                    <div
                      className={`text-xs font-bold uppercase tracking-wide ${
                        liveProfit.profit >= 0
                          ? "text-emerald-600"
                          : "text-red-600"
                      }`}
                    >
                      Profit (live)
                    </div>
                    <div
                      className={`mt-1 text-2xl font-bold ${
                        liveProfit.profit >= 0
                          ? "text-emerald-700"
                          : "text-red-700"
                      }`}
                    >
                      {money(liveProfit.profit)}
                    </div>
                  </div>

                  <div>
                    <div
                      className={`text-xs font-bold uppercase tracking-wide ${
                        liveProfit.profit >= 0
                          ? "text-emerald-600"
                          : "text-red-600"
                      }`}
                    >
                      Margin
                    </div>
                    <div
                      className={`mt-1 text-2xl font-bold ${
                        liveProfit.profit >= 0
                          ? "text-emerald-700"
                          : "text-red-700"
                      }`}
                    >
                      {liveProfit.margin.toFixed(2)}%
                    </div>
                  </div>

                  <div className="text-right text-xs text-slate-500">
                    <div>Cost: {money(liveProfit.cost)}</div>
                    <div>Selling: {money(liveProfit.selling)}</div>
                  </div>
                </div>
              </div>
            )}

            {/* ---------- CLASSIFICATION ---------- */}
            <div className="mb-6">
              <h3 className="mb-3 border-b border-slate-200 pb-2 text-sm font-bold uppercase tracking-wide text-slate-700">
                Classification
              </h3>

              <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
                <LookupInput
                  label="Department"
                  name="Department"
                  value={form.Department}
                  placeholder="Press F12 or click Search"
                  onChange={handleChange}
                  onLookup={() => openLookup("department")}
                />
                <LookupInput
                  label="Category"
                  name="Category"
                  value={form.Category}
                  placeholder="Press F12 or click Search"
                  onChange={handleChange}
                  onLookup={() => openLookup("category")}
                />
                <LookupInput
                  label="SubCategory"
                  name="SubCategory"
                  value={form.SubCategory}
                  placeholder="Press F12 or click Search"
                  onChange={handleChange}
                  onLookup={() => openLookup("subcategory")}
                />
                <LookupInput
                  label="Supplier"
                  name="supplier"
                  value={form.supplier}
                  placeholder="Press F12 or click Search"
                  onChange={handleChange}
                  onLookup={() => openLookup("supplier")}
                />
              </div>
            </div>

            {/* ---------- STOCK ---------- */}
            <div className="mb-6">
              <h3 className="mb-3 border-b border-slate-200 pb-2 text-sm font-bold uppercase tracking-wide text-slate-700">
                Stock / Reorder
              </h3>

              <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
                <PriceInput
                  label="Reorder Level"
                  name="reorderlevel"
                  value={form.reorderlevel}
                  onChange={handleChange}
                />
                <PriceInput
                  label="Reorder Quantity"
                  name="reorderqty"
                  value={form.reorderqty}
                  onChange={handleChange}
                />
                <div>
                  <label className="mb-1 block text-sm font-semibold text-slate-700">
                    Expiry Date
                  </label>
                  <input
                    type="datetime-local"
                    name="expirydate"
                    value={form.expirydate}
                    onChange={handleChange}
                    className="w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                  />
                </div>
              </div>
            </div>

            {/* ---------- STATUS ---------- */}
            <div className="mb-6">
              <h3 className="mb-3 border-b border-slate-200 pb-2 text-sm font-bold uppercase tracking-wide text-slate-700">
                Product Status
              </h3>

              <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
                <div className="rounded-lg border border-slate-200 bg-slate-50 p-4">
                  <div className="mb-2 text-sm font-semibold text-slate-700">
                    Product Status
                  </div>
                  <div className="flex flex-wrap gap-5">
                    <label className="flex cursor-pointer items-center gap-2 text-sm">
                      <input
                        type="radio"
                        name="isactive"
                        value="1"
                        checked={String(form.isactive) === "1"}
                        onChange={handleChange}
                        className="h-4 w-4"
                      />
                      <span className="font-medium text-emerald-700">
                        Active
                      </span>
                    </label>
                    <label className="flex cursor-pointer items-center gap-2 text-sm">
                      <input
                        type="radio"
                        name="isactive"
                        value="0"
                        checked={String(form.isactive) === "0"}
                        onChange={handleChange}
                        className="h-4 w-4"
                      />
                      <span className="font-medium text-red-700">Inactive</span>
                    </label>
                  </div>
                </div>

                <div className="rounded-lg border border-slate-200 bg-slate-50 p-4">
                  <div className="mb-2 text-sm font-semibold text-slate-700">
                    Tax
                  </div>
                  <div className="flex flex-wrap gap-5">
                    <label className="flex cursor-pointer items-center gap-2 text-sm">
                      <input
                        type="radio"
                        name="istax"
                        value="1"
                        checked={String(form.istax) === "1"}
                        onChange={handleChange}
                        className="h-4 w-4"
                      />
                      <span className="font-medium text-blue-700">Taxable</span>
                    </label>
                    <label className="flex cursor-pointer items-center gap-2 text-sm">
                      <input
                        type="radio"
                        name="istax"
                        value="0"
                        checked={String(form.istax) === "0"}
                        onChange={handleChange}
                        className="h-4 w-4"
                      />
                      <span className="font-medium text-slate-700">
                        Non-Taxable
                      </span>
                    </label>
                  </div>
                </div>
              </div>
            </div>

            {/* ---------- IMAGE ---------- */}
            <div className="mb-6">
              <h3 className="mb-3 border-b border-slate-200 pb-2 text-sm font-bold uppercase tracking-wide text-slate-700">
                Product Image
              </h3>

              <div className="grid grid-cols-1 gap-5 md:grid-cols-2">
                <div>
                  <label className="mb-2 block text-sm font-semibold text-slate-700">
                    Upload Image
                  </label>
                  <input
                    type="file"
                    accept="image/*"
                    onChange={(event) => {
                      const file = event.target.files?.[0];
                      if (file) setImageFile(file);
                    }}
                    className="block w-full rounded-lg border border-slate-300 bg-white text-sm file:mr-4 file:border-0 file:bg-slate-100 file:px-4 file:py-2.5 file:text-sm file:font-semibold file:text-slate-700 hover:file:bg-slate-200"
                  />
                  {imageFile && (
                    <p className="mt-2 text-xs text-slate-500">
                      {imageFile.name}
                    </p>
                  )}
                </div>

                <div className="flex min-h-36 items-center justify-center rounded-xl border-2 border-dashed border-slate-300 bg-slate-50 p-3">
                  {imagePreview ? (
                    <img
                      src={imagePreview}
                      alt="Product preview"
                      className="h-40 w-40 rounded-xl object-contain"
                    />
                  ) : (
                    <div className="text-center text-sm text-slate-400">
                      No image selected
                    </div>
                  )}
                </div>
              </div>
            </div>

            {/* ---------- BUTTONS ---------- */}
            <div className="flex flex-col gap-3 border-t border-slate-200 pt-5 sm:flex-row sm:justify-end">
              <button
                type="button"
                onClick={resetForm}
                disabled={loading}
                className="rounded-lg bg-slate-200 px-6 py-3 text-sm font-bold text-slate-700 transition hover:bg-slate-300 disabled:opacity-50"
              >
                Clear
              </button>

              {isEditMode && canDeleteProduct && (
                <button
                  type="button"
                  onClick={handleDelete}
                  disabled={loading}
                  className="rounded-lg bg-red-600 px-6 py-3 text-sm font-bold text-white transition hover:bg-red-700 disabled:cursor-not-allowed disabled:opacity-50"
                >
                  {loading ? "Processing..." : "Delete Product"}
                </button>
              )}

              {saveAllowed && (
                <button
                  type="submit"
                  disabled={loading}
                  className={`rounded-lg px-7 py-3 text-sm font-bold text-white transition disabled:cursor-not-allowed disabled:opacity-50 ${
                    isEditMode
                      ? "bg-amber-600 hover:bg-amber-700"
                      : "bg-blue-600 hover:bg-blue-700"
                  }`}
                >
                  {loading
                    ? "Processing..."
                    : isEditMode
                    ? "Update Product"
                    : "Save Product"}
                </button>
              )}

              {isEditMode && !canEditProduct && (
                <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 text-xs font-semibold text-slate-500">
                  You have read-only access — editing is disabled.
                </div>
              )}

              {!isEditMode && !canAddProduct && (
                <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 text-xs font-semibold text-slate-500">
                  You do not have permission to create new products.
                </div>
              )}
            </div>
          </div>
        </form>
      </div>

      {/* ============ LOOKUP MODAL ============ */}
      {lookupModal && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4"
          onMouseDown={(event) => {
            if (event.target === event.currentTarget) {
              setLookupModal(null);
            }
          }}
        >
          <div className="flex max-h-[85vh] w-full max-w-3xl flex-col overflow-hidden rounded-2xl bg-white shadow-2xl">
            <div className="flex items-center justify-between border-b border-slate-200 bg-slate-50 px-5 py-4">
              <div>
                <h2 className="text-lg font-bold text-slate-800">
                  {lookupTitle[lookupModal]}
                </h2>
                <p className="text-xs text-slate-500">
                  Select an item or press Enter when one result remains
                </p>
              </div>

              <button
                type="button"
                onClick={() => setLookupModal(null)}
                className="rounded-lg px-3 py-2 text-lg font-bold text-slate-500 hover:bg-slate-200 hover:text-slate-800"
              >
                ×
              </button>
            </div>

            <div className="border-b border-slate-200 p-4">
              <input
                ref={lookupInputRef}
                type="text"
                value={lookupSearch}
                onChange={(event) => setLookupSearch(event.target.value)}
                onKeyDown={handleLookupKeyDown}
                placeholder="Search..."
                className="w-full rounded-lg border border-slate-300 px-4 py-3 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
              />
            </div>

            <div className="flex-1 overflow-y-auto p-3">
              {lookupLoading ? (
                <div className="py-10 text-center text-sm text-slate-500">
                  Loading...
                </div>
              ) : filteredLookupData.length === 0 ? (
                <div className="py-10 text-center text-sm text-slate-500">
                  No records found.
                </div>
              ) : (
                <div className="overflow-hidden rounded-lg border border-slate-200">
                  {filteredLookupData.map((item, index) => {
                    const primary = getLookupPrimary(item);
                    const secondary = getLookupSecondary(item);

                    return (
                      <button
                        key={firstValue(
                          item?.InvDepartmentID,
                          item?.InvCategoryID,
                          item?.InvSubCategoryID,
                          item?.SupplierID,
                          item?.id,
                          index
                        )}
                        type="button"
                        onClick={() => selectLookupItem(item)}
                        className="flex w-full items-center justify-between border-b border-slate-100 px-4 py-3 text-left transition last:border-b-0 hover:bg-blue-50"
                      >
                        <div className="min-w-0">
                          <div className="font-semibold text-slate-800">
                            {primary}
                          </div>
                          {secondary && (
                            <div className="mt-1 truncate text-xs text-slate-500">
                              {secondary}
                            </div>
                          )}
                        </div>
                        <span className="ml-3 shrink-0 rounded-md bg-slate-100 px-2 py-1 text-xs font-semibold text-slate-500">
                          Select
                        </span>
                      </button>
                    );
                  })}
                </div>
              )}
            </div>

            <div className="flex justify-end border-t border-slate-200 bg-slate-50 px-5 py-3">
              <button
                type="button"
                onClick={() => setLookupModal(null)}
                className="rounded-lg bg-slate-600 px-5 py-2.5 text-sm font-semibold text-white hover:bg-slate-700"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// =============================================================
// PRICE INPUT
// =============================================================
function PriceInput({ label, name, value, onChange }) {
  return (
    <div>
      <label className="mb-1 block text-sm font-semibold text-slate-700">
        {label}
      </label>
      <input
        type="number"
        step="0.01"
        name={name}
        value={value}
        onChange={onChange}
        className="w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
        placeholder="0.00"
      />
    </div>
  );
}

// =============================================================
// LOOKUP INPUT
// =============================================================
function LookupInput({
  label,
  name,
  value,
  placeholder,
  onChange,
  onLookup,
}) {
  return (
    <div>
      <label className="mb-1 flex items-center justify-between text-sm font-semibold text-slate-700">
        <span>{label}</span>
        <span className="text-xs font-normal text-slate-400">F12</span>
      </label>
      <div className="flex gap-2">
        <input
          name={name}
          value={value}
          onChange={onChange}
          placeholder={placeholder}
          className="min-w-0 flex-1 rounded-lg border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
        />
        <button
          type="button"
          onClick={onLookup}
          className="rounded-lg bg-indigo-600 px-4 py-2 text-xs font-bold text-white hover:bg-indigo-700"
          title={`Open ${label} lookup`}
        >
          Search
        </button>
      </div>
    </div>
  );
}

export default CreateProduct;