import React, { useEffect, useMemo, useState } from "react";   // ← PERM (added useMemo)
import axios from "axios";

// ← PERM
import { usePermissions } from "../hooks/usePermissions.jsx";

const API = "http://localhost:5000";

/* =====================================================
   TOGGLE / TAB BUTTON  (unchanged)
===================================================== */
function Toggle({ checked, onChange, disabled = false }) {   // ← PERM (added disabled)
    return (
        <button
            type="button"
            onClick={() => !disabled && onChange(!checked)}   // ← PERM
            disabled={disabled}                                // ← PERM
            className={`relative h-6 w-11 shrink-0 rounded-full transition ${
                checked ? "bg-[#e99a00]" : "bg-gray-300"
            } ${disabled ? "opacity-50 cursor-not-allowed" : ""}`}   // ← PERM
        >
            <span
                className={`absolute top-1 h-4 w-4 rounded-full bg-white transition-all ${
                    checked ? "left-6" : "left-1"
                }`}
            />
        </button>
    );
}

function TabButton({ active, onClick, icon, children }) {
    return (
        <button
            type="button"
            onClick={onClick}
            className={`flex items-center gap-2 rounded-xl px-5 py-2.5 text-sm font-medium transition ${
                active
                    ? "bg-white text-gray-900 shadow-sm"
                    : "text-gray-600 hover:bg-white/60 hover:text-gray-900"
            }`}
        >
            <span>{icon}</span>
            {children}
        </button>
    );
}

/* =====================================================
   MAIN LOYALTY
===================================================== */
function Loyalty() {
    // ← PERM
    const { can, loading: permissionsLoading } = usePermissions();

    const canViewLoyalty = can("Loyalty", "View");      // ← PERM
    const canAddLoyalty  = can("Loyalty", "Add");       // ← PERM
    const canEditLoyalty = can("Loyalty", "Edit");      // ← PERM

    const [activeTab, setActiveTab] = useState("configuration");

    const [settings, setSettings] = useState({
        pointsPerAmount: 100,
        amountPerPoint: 1,
        pointsExpiryDays: 365,
        minimumRedeemPoints: 0,
        otpRequired: true,
        autoEnroll: true,
    });

    const [loading, setLoading] = useState(false);
    const [message, setMessage] = useState("");
    const [error, setError] = useState("");

    /* =================================================
       AVAILABLE TABS (all four require CanView)     // ← PERM
    ================================================= */
    const availableTabs = useMemo(() => {                 // ← PERM
        if (!canViewLoyalty) return [];
        return ["configuration", "categories", "customers", "transactions"];
    }, [canViewLoyalty]);

    /* =================================================
       AUTO-SELECT FIRST VISIBLE TAB                 // ← PERM
    ================================================= */
    useEffect(() => {                                     // ← PERM
        if (permissionsLoading) return;
        if (availableTabs.length === 0) return;
        if (!availableTabs.includes(activeTab)) {
            setActiveTab(availableTabs[0]);
        }
    }, [availableTabs, activeTab, permissionsLoading]);

    useEffect(() => {
        // ← PERM: skip if no view
        if (permissionsLoading) return;
        if (!canViewLoyalty) return;

        loadSettings();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [canViewLoyalty, permissionsLoading]);

    /* =================================================
       LOAD SETTINGS  (unchanged, trimmed whitespace)
    ================================================= */
    const loadSettings = async () => {
        try {
            setLoading(true);
            setError("");

            const response = await axios.get(`${API}/loyalty/settings`);

            if (response.data.success) {
                const data = response.data.settings || {};

                setSettings({
                    pointsPerAmount: Number(data.PointsPerAmount ?? 100),
                    amountPerPoint: Number(data.AmountPerPoint ?? 1),
                    pointsExpiryDays: Number(data.PointsExpiryDays ?? 365),
                    minimumRedeemPoints: Number(data.MinimumRedeemPoints ?? 0),
                    otpRequired:
                        data.OTPRequired === undefined
                            ? true
                            : Boolean(Number(data.OTPRequired)),
                    autoEnroll:
                        data.AutoEnroll === undefined
                            ? true
                            : Boolean(Number(data.AutoEnroll)),
                });
            }
        } catch (err) {
            console.error(err);
            setError(
                err.response?.data?.message || "Unable to load loyalty settings"
            );
        } finally {
            setLoading(false);
        }
    };

    const handleChange = (e) => {
        const { name, value } = e.target;
        setSettings((prev) => ({ ...prev, [name]: value === "" ? "" : Number(value) }));
    };

    /* =================================================
       SAVE SETTINGS                                  // ← PERM guard
    ================================================= */
    const handleSave = async () => {
        if (!canEditLoyalty) {                            // ← PERM
            setError("You do not have permission to modify loyalty settings.");
            return;
        }

        try {
            setLoading(true);
            setMessage("");
            setError("");

            const payload = {
                pointsPerAmount: Number(settings.pointsPerAmount),
                amountPerPoint: Number(settings.amountPerPoint),
                pointsExpiryDays: Number(settings.pointsExpiryDays),
                minimumRedeemPoints: Number(settings.minimumRedeemPoints),
                otpRequired: Boolean(settings.otpRequired),
                autoEnroll: Boolean(settings.autoEnroll),
            };

            const response = await axios.put(`${API}/loyalty/settings`, payload);

            if (response.data.success) {
                setMessage("Loyalty settings saved successfully.");
            }
        } catch (err) {
            console.error(err);
            setError(err.response?.data?.message || "Failed to save settings");
        } finally {
            setLoading(false);
        }
    };

    /* =================================================
       EXPIRE POINTS                                  // ← PERM guard
    ================================================= */
    const expirePoints = async () => {
        if (!canEditLoyalty) {                            // ← PERM
            setError("You do not have permission to run expiry.");
            return;
        }

        try {
            setLoading(true);
            setMessage("");
            setError("");

            const response = await axios.post(`${API}/loyalty/expire`);

            if (response.data.success) {
                setMessage(
                    `${response.data.expiredCount ?? 0} point batches expired.`
                );
            }
        } catch (err) {
            console.error(err);
            setError(err.response?.data?.message || "Failed to expire points");
        } finally {
            setLoading(false);
        }
    };

    /* =================================================
       CALCULATIONS  (unchanged)
    ================================================= */
    const pointsRate = Number(settings.pointsPerAmount) || 1;
    const pointValue = Number(settings.amountPerPoint) || 0;
    const earnedPoints = Math.floor(10000 / pointsRate);
    const redemptionValue = earnedPoints * pointValue;

    /* =================================================
       ACCESS GATE                                    // ← PERM
    ================================================= */
    if (permissionsLoading) {                             // ← PERM
        return (
            <div className="min-h-screen bg-white flex items-center justify-center text-gray-500">
                Checking permissions…
            </div>
        );
    }

    if (!canViewLoyalty) {                                // ← PERM
        return (
            <div className="min-h-screen bg-white p-6">
                <div className="mx-auto max-w-xl mt-20 rounded-xl border border-red-200 bg-red-50 p-8 text-center">
                    <h2 className="text-lg font-bold text-red-700">Access Denied</h2>
                    <p className="text-sm text-red-600 mt-2">
                        You do not have permission to view the Loyalty module.
                    </p>
                    <p className="text-xs text-red-400 mt-3">
                        Module: <code>Loyalty</code>
                    </p>
                </div>
            </div>
        );
    }

    /* =================================================
       UI
    ================================================= */
    return (
        <div className="min-h-screen bg-white text-gray-900">

            {/* HEADER */}
            <header className="flex flex-col gap-4 px-5 py-5 md:flex-row md:items-center md:justify-between">
                <div className="flex items-center gap-3">
                    <div className="flex h-11 w-11 items-center justify-center rounded-xl bg-[#fff1c9]">
                        <svg
                            className="h-6 w-6 text-[#e99a00]"
                            fill="none"
                            viewBox="0 0 24 24"
                            stroke="currentColor"
                            strokeWidth="2"
                        >
                            <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9L12 3z"
                            />
                        </svg>
                    </div>

                    <div>
                        <h1 className="text-2xl font-bold">Loyalty Points</h1>
                        <p className="text-sm text-gray-500">
                            Manage customer loyalty program
                        </p>
                    </div>
                </div>

                <div className="flex items-center gap-2">
                    {/* ← PERM: read-only badge when user can't edit */}
                    {!canEditLoyalty && (
                        <span className="rounded-full bg-slate-200 px-3 py-1 text-xs font-semibold text-slate-600">
                            READ ONLY
                        </span>
                    )}

                    <span className="w-fit rounded-full bg-green-100 px-4 py-2 text-xs font-semibold text-green-700">
                        Active
                    </span>
                </div>
            </header>

            {/* NAVIGATION — only tabs the user can View */}
            <div className="overflow-x-auto px-3">
                <div className="flex w-max rounded-xl bg-gray-100 p-1">
                    {availableTabs.includes("configuration") && (     /* ← PERM */
                        <TabButton
                            active={activeTab === "configuration"}
                            onClick={() => setActiveTab("configuration")}
                            icon="⚙"
                        >
                            Configuration
                        </TabButton>
                    )}

                    {availableTabs.includes("categories") && (        /* ← PERM */
                        <TabButton
                            active={activeTab === "categories"}
                            onClick={() => setActiveTab("categories")}
                            icon="◇"
                        >
                            Category Rates
                        </TabButton>
                    )}

                    {availableTabs.includes("customers") && (         /* ← PERM */
                        <TabButton
                            active={activeTab === "customers"}
                            onClick={() => setActiveTab("customers")}
                            icon="♧"
                        >
                            Customers
                        </TabButton>
                    )}

                    {availableTabs.includes("transactions") && (      /* ← PERM */
                        <TabButton
                            active={activeTab === "transactions"}
                            onClick={() => setActiveTab("transactions")}
                            icon="◷"
                        >
                            Transactions
                        </TabButton>
                    )}
                </div>
            </div>

            {/* MAIN */}
            <main className="p-3">
                {activeTab === "configuration" && (
                    <Configuration
                        settings={settings}
                        setSettings={setSettings}
                        loading={loading}
                        message={message}
                        error={error}
                        handleChange={handleChange}
                        handleSave={handleSave}
                        expirePoints={expirePoints}
                        earnedPoints={earnedPoints}
                        redemptionValue={redemptionValue}
                        readOnly={!canEditLoyalty}          /* ← PERM */
                    />
                )}

                {activeTab === "categories" && <CategoryRates />}
                {activeTab === "customers" && (
                    <Customers canAdd={canAddLoyalty} />       /* ← PERM */
                )}
                {activeTab === "transactions" && <Transactions />}
            </main>
        </div>
    );
}

/* =====================================================
   CONFIGURATION
===================================================== */
function Configuration({
    settings,
    setSettings,
    loading,
    message,
    error,
    handleChange,
    handleSave,
    expirePoints,
    earnedPoints,
    redemptionValue,
    readOnly = false,                                       // ← PERM
}) {
    return (
        <section className="rounded-xl border border-gray-300 bg-white shadow-sm">
            <div className="border-b px-6 py-6">
                <h2 className="text-2xl font-semibold">Loyalty Configuration</h2>
                <p className="mt-1 text-sm text-gray-500">
                    Configure customer loyalty points, redemption and expiry.
                </p>
            </div>

            {message && (
                <div className="mx-6 mt-5 rounded-lg border border-green-300 bg-green-50 p-4 text-sm text-green-700">
                    {message}
                </div>
            )}
            {error && (
                <div className="mx-6 mt-5 rounded-lg border border-red-300 bg-red-50 p-4 text-sm text-red-700">
                    {error}
                </div>
            )}

            {/* ← PERM: read-only banner */}
            {readOnly && (                                       /* ← PERM */
                <div className="mx-6 mt-5 rounded-lg border border-amber-200 bg-amber-50 p-3 text-xs font-medium text-amber-700">
                    Read-only mode — you cannot modify settings or run expiry.
                </div>
            )}

            <div className="grid grid-cols-1 gap-x-16 gap-y-8 px-6 py-8 md:grid-cols-2">

                {/* All the number inputs (pointsPerAmount, amountPerPoint,
                    minimumRedeemPoints, pointsExpiryDays) — add disabled={readOnly} */}
                <div>
                    <label className="text-sm font-medium">Default Points Rate</label>
                    <div className="mt-2 flex items-center gap-2">
                        <span className="text-sm text-gray-500">1 point per Rs.</span>
                        <input
                            type="number"
                            min="1"
                            step="0.01"
                            name="pointsPerAmount"
                            value={settings.pointsPerAmount}
                            onChange={handleChange}
                            disabled={readOnly}                  /* ← PERM */
                            className="w-28 rounded-xl border border-gray-200 px-3 py-3 text-sm outline-none transition focus:border-[#e99a00] focus:ring-2 focus:ring-[#e99a00]/20 disabled:bg-gray-100"
                        />
                    </div>
                    <p className="mt-2 text-xs text-gray-500">
                        Example: 200 means 1 point for every Rs.200 spent.
                    </p>
                </div>

                <div>
                    <label className="text-sm font-medium">Point Redemption Value</label>
                    <div className="mt-2 flex items-center gap-2">
                        <span className="text-sm text-gray-500">1 point = Rs.</span>
                        <input
                            type="number"
                            min="0.01"
                            step="0.01"
                            name="amountPerPoint"
                            value={settings.amountPerPoint}
                            onChange={handleChange}
                            disabled={readOnly}                  /* ← PERM */
                            className="w-28 rounded-xl border border-gray-200 px-3 py-3 text-sm outline-none transition focus:border-[#e99a00] focus:ring-2 focus:ring-[#e99a00]/20 disabled:bg-gray-100"
                        />
                    </div>
                </div>

                <div>
                    <label className="text-sm font-medium">Minimum Points to Redeem</label>
                    <input
                        type="number"
                        min="0"
                        step="1"
                        name="minimumRedeemPoints"
                        value={settings.minimumRedeemPoints}
                        onChange={handleChange}
                        disabled={readOnly}                      /* ← PERM */
                        className="mt-3 w-32 rounded-xl border border-gray-200 px-3 py-3 text-sm outline-none focus:border-[#e99a00] focus:ring-2 focus:ring-[#e99a00]/20 disabled:bg-gray-100"
                    />
                </div>

                <div>
                    <label className="text-sm font-medium">Points Expiry Period</label>
                    <div className="mt-2 flex items-center gap-2">
                        <input
                            type="number"
                            min="1"
                            step="1"
                            name="pointsExpiryDays"
                            value={settings.pointsExpiryDays}
                            onChange={handleChange}
                            disabled={readOnly}                  /* ← PERM */
                            className="w-28 rounded-xl border border-gray-200 px-3 py-3 text-sm outline-none focus:border-[#e99a00] focus:ring-2 focus:ring-[#e99a00]/20 disabled:bg-gray-100"
                        />
                        <span className="text-sm text-gray-500">days</span>
                    </div>
                </div>

                {/* Toggles */}
                <div className="flex items-start gap-4">
                    <Toggle
                        checked={settings.otpRequired}
                        disabled={readOnly}                      /* ← PERM */
                        onChange={(value) =>
                            setSettings((prev) => ({ ...prev, otpRequired: value }))
                        }
                    />
                    <div>
                        <h3 className="text-sm font-medium">Require OTP for Redemption</h3>
                        <p className="mt-1 text-xs text-gray-500">
                            Send OTP to customer and admin for verification.
                        </p>
                    </div>
                </div>

                <div className="flex items-start gap-4">
                    <Toggle
                        checked={settings.autoEnroll}
                        disabled={readOnly}                      /* ← PERM */
                        onChange={(value) =>
                            setSettings((prev) => ({ ...prev, autoEnroll: value }))
                        }
                    />
                    <div>
                        <h3 className="text-sm font-medium">Auto-enroll Retail Customers</h3>
                        <p className="mt-1 text-xs text-gray-500">
                            Automatically enroll retail customers in the loyalty program.
                        </p>
                    </div>
                </div>
            </div>

            {/* Example panel (unchanged) */}
            <div className="mx-6 mb-6 rounded-xl border bg-gray-50 p-5">
                <h3 className="mb-4 font-semibold">Example</h3>
                <div className="grid gap-3 text-sm md:grid-cols-4">
                    <div>
                        <span className="text-gray-500">Sale</span>
                        <div className="mt-1 font-semibold">Rs.10,000</div>
                    </div>
                    <div>
                        <span className="text-gray-500">Points</span>
                        <div className="mt-1 font-semibold">{earnedPoints}</div>
                    </div>
                    <div>
                        <span className="text-gray-500">Expiry</span>
                        <div className="mt-1 font-semibold">
                            {settings.pointsExpiryDays} days
                        </div>
                    </div>
                    <div>
                        <span className="text-gray-500">Value</span>
                        <div className="mt-1 font-semibold">
                            Rs.{Number(redemptionValue).toFixed(2)}
                        </div>
                    </div>
                </div>
            </div>

            {/* ← PERM: hide action buttons entirely in read-only mode */}
            {!readOnly && (                                       /* ← PERM */
                <div className="flex flex-col gap-3 border-t border-gray-200 px-6 py-5 sm:flex-row sm:justify-end">
                    <button
                        type="button"
                        onClick={expirePoints}
                        disabled={loading}
                        className="rounded-xl border border-[#e99a00] px-5 py-3 text-sm font-semibold text-[#e99a00] transition hover:bg-[#fff7e6] disabled:cursor-not-allowed disabled:opacity-50"
                    >
                        {loading ? "Processing..." : "Expire Points Now"}
                    </button>

                    <button
                        type="button"
                        onClick={handleSave}
                        disabled={loading}
                        className="rounded-xl bg-[#e99a00] px-6 py-3 text-sm font-semibold text-white shadow-sm transition hover:bg-[#d88d00] disabled:cursor-not-allowed disabled:opacity-50"
                    >
                        {loading ? "Saving..." : "Save Settings"}
                    </button>
                </div>
            )}
        </section>
    );
}

/* =====================================================
   CATEGORY RATES
===================================================== */
function CategoryRates() {
    // ← PERM
    const { can } = usePermissions();                         // ← PERM
    const canEditLoyalty = can("Loyalty", "Edit");            // ← PERM

    const [categories, setCategories] = useState([]);
    const [loading, setLoading] = useState(false);
    const [savingId, setSavingId] = useState(null);
    const [error, setError] = useState("");
    const [message, setMessage] = useState("");

    const loadCategories = async () => {
        try {
            setLoading(true);
            setError("");
            setMessage("");

            const response = await axios.get(`${API}/loyalty/category`);

            if (response.data.success) {
                const list = response.data.data || [];

                const formattedCategories = list.map((category) => ({
                    ...category,
                    PointsPerAmount: category.PointsPerAmount ?? 100,
                    IsActive:
                        category.IsActive === undefined
                            ? true
                            : Boolean(Number(category.IsActive)),
                }));

                setCategories(formattedCategories);
            } else {
                setCategories([]);
                setError(response.data.message || "Failed to load categories");
            }
        } catch (err) {
            console.error("LOAD CATEGORIES ERROR:", err);
            setError(err.response?.data?.message || "Failed to load categories");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        loadCategories();
    }, []);

    const handleRateChange = (categoryName, value) => {
        if (!canEditLoyalty) return;                          // ← PERM
        setCategories((prev) =>
            prev.map((category) =>
                String(category.CategoryName).trim().toLowerCase() ===
                String(categoryName).trim().toLowerCase()
                    ? { ...category, PointsPerAmount: value }
                    : category
            )
        );
    };

    const handleToggle = async (category) => {
        if (!canEditLoyalty) return;                          // ← PERM

        const newStatus = !category.IsActive;

        setCategories((prev) =>
            prev.map((item) =>
                String(item.CategoryName).trim().toLowerCase() ===
                String(category.CategoryName).trim().toLowerCase()
                    ? { ...item, IsActive: newStatus }
                    : item
            )
        );

        try {
            setSavingId(category.CategoryName);
            setError("");
            setMessage("");

            const response = await axios.put(
                `${API}/loyalty/categories/${encodeURIComponent(category.CategoryName)}`,
                {
                    categoryCode: category.CategoryCode,
                    categoryName: category.CategoryName,
                    pointsPerAmount: Number(category.PointsPerAmount),
                    isActive: newStatus,
                }
            );

            if (response.data.success) {
                setMessage(
                    `${category.CategoryName} ${
                        newStatus ? "enabled" : "disabled"
                    } successfully.`
                );
            } else {
                throw new Error(response.data.message || "Failed to update category");
            }
        } catch (err) {
            console.error("TOGGLE CATEGORY ERROR:", err);
            setCategories((prev) =>
                prev.map((item) =>
                    String(item.CategoryName).trim().toLowerCase() ===
                    String(category.CategoryName).trim().toLowerCase()
                        ? { ...item, IsActive: category.IsActive }
                        : item
                )
            );
            setError(err.response?.data?.message || "Failed to update category");
        } finally {
            setSavingId(null);
        }
    };

    const saveRate = async (category) => {
        if (!canEditLoyalty) return;                          // ← PERM

        const rate = Number(category.PointsPerAmount);

        if (!rate || Number.isNaN(rate) || rate <= 0) {
            setError(`Please enter a valid points rate for ${category.CategoryName}.`);
            return;
        }

        try {
            setSavingId(category.CategoryName);
            setError("");
            setMessage("");

            const response = await axios.post(`${API}/loyalty/categories`, {
                categoryCode: category.CategoryCode,
                categoryName: category.CategoryName,
                pointsPerAmount: rate,
                isActive: category.IsActive,
            });

            if (response.data.success) {
                setMessage(`${category.CategoryName} rate saved successfully.`);
            } else {
                throw new Error(response.data.response?.message || "Failed to save category rate");
            }
        } catch (err) {
            console.error("SAVE CATEGORY RATE ERROR:", err);
            setError(err.response?.data?.message || "Failed to save category rate");
        } finally {
            setSavingId(null);
        }
    };

    return (
        <section className="rounded-xl border border-gray-300 bg-white shadow-sm">
            <div className="border-b px-6 py-6">
                <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
                    <div>
                        <h2 className="text-2xl font-semibold">Category Rates</h2>
                        <p className="mt-1 text-sm text-gray-500">
                            Set loyalty points rates for each product category.
                        </p>
                    </div>

                    <button
                        type="button"
                        onClick={loadCategories}
                        disabled={loading}
                        className="w-fit rounded-xl border border-gray-300 px-4 py-2.5 text-sm font-medium transition hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-50"
                    >
                        {loading ? "Loading..." : "↻ Refresh"}
                    </button>
                </div>
            </div>

            {/* ← PERM: read-only banner */}
            {!canEditLoyalty && (                                 /* ← PERM */
                <div className="mx-6 mt-5 rounded-lg border border-amber-200 bg-amber-50 p-3 text-xs font-medium text-amber-700">
                    Read-only mode — you cannot modify rates.
                </div>
            )}

            {message && (
                <div className="mx-6 mt-5 rounded-lg border border-green-300 bg-green-50 p-4 text-sm text-green-700">
                    {message}
                </div>
            )}
            {error && (
                <div className="mx-6 mt-5 rounded-lg border border-red-300 bg-red-50 p-4 text-sm text-red-700">
                    {error}
                </div>
            )}

            <div className="overflow-x-auto p-6">
                <table className="w-full min-w-[800px] text-left text-sm">
                    <thead className="bg-gray-50">
                        <tr>
                            <th className="px-5 py-4 font-semibold">Category Code</th>
                            <th className="px-5 py-4 font-semibold">Category Name</th>
                            <th className="px-5 py-4 font-semibold">Points Rate</th>
                            <th className="px-5 py-4 font-semibold">Status</th>
                            <th className="px-5 py-4 text-right font-semibold">Action</th>
                        </tr>
                    </thead>

                    <tbody>
                        {categories.map((category) => {
                            const isSaving = savingId === category.CategoryName;

                            return (
                                <tr
                                    key={category.CategoryCode || category.CategoryName}
                                    className="border-t border-gray-100 transition hover:bg-[#fffaf0]"
                                >
                                    <td className="px-5 py-4">
                                        <span className="rounded-lg bg-gray-100 px-3 py-1.5 text-xs font-semibold text-gray-700">
                                            {category.CategoryCode || "-"}
                                        </span>
                                    </td>

                                    <td className="px-5 py-4">
                                        <div className="font-medium text-gray-900">
                                            {category.CategoryName}
                                        </div>
                                    </td>

                                    <td className="px-5 py-4">
                                        <div className="flex items-center gap-2">
                                            <span className="whitespace-nowrap text-gray-500">
                                                1 point / Rs.
                                            </span>
                                            <input
                                                type="number"
                                                min="1"
                                                step="0.01"
                                                value={category.PointsPerAmount}
                                                onChange={(e) =>
                                                    handleRateChange(category.CategoryName, e.target.value)
                                                }
                                                disabled={!canEditLoyalty || isSaving}   /* ← PERM */
                                                className="w-28 rounded-xl border border-gray-200 px-3 py-2.5 text-sm outline-none transition focus:border-[#e99a00] focus:ring-2 focus:ring-[#e99a00]/20 disabled:bg-gray-100"
                                            />
                                        </div>
                                    </td>

                                    <td className="px-5 py-4">
                                        <div className="flex items-center gap-3">
                                            <button
                                                type="button"
                                                onClick={() => handleToggle(category)}
                                                disabled={isSaving || !canEditLoyalty}   /* ← PERM */
                                                className={`relative h-6 w-11 shrink-0 rounded-full transition ${
                                                    category.IsActive
                                                        ? "bg-[#e99a00]"
                                                        : "bg-gray-300"
                                                } disabled:opacity-50 disabled:cursor-not-allowed`}   /* ← PERM */
                                            >
                                                <span
                                                    className={`absolute top-1 h-4 w-4 rounded-full bg-white transition-all ${
                                                        category.IsActive ? "left-6" : "left-1"
                                                    }`}
                                                />
                                            </button>
                                            <span
                                                className={`text-xs font-semibold ${
                                                    category.IsActive
                                                        ? "text-green-600"
                                                        : "text-gray-500"
                                                }`}
                                            >
                                                {category.IsActive ? "Enabled" : "Disabled"}
                                            </span>
                                        </div>
                                    </td>

                                    <td className="px-5 py-4 text-right">
                                        {/* ← PERM: hide Save when user can't edit */}
                                        {canEditLoyalty && (                  /* ← PERM */
                                            <button
                                                type="button"
                                                onClick={() => saveRate(category)}
                                                disabled={isSaving}
                                                className="rounded-xl bg-[#e99a00] px-5 py-2.5 text-sm font-semibold text-white shadow-sm transition hover:bg-[#d88d00] disabled:cursor-not-allowed disabled:opacity-50"
                                            >
                                                {isSaving ? "Saving..." : "Save"}
                                            </button>
                                        )}
                                    </td>
                                </tr>
                            );
                        })}
                    </tbody>
                </table>

                {loading && (
                    <div className="p-10 text-center text-sm text-gray-500">
                        Loading product categories...
                    </div>
                )}
                {!loading && categories.length === 0 && (
                    <div className="p-10 text-center text-sm text-gray-500">
                        No product categories found.
                    </div>
                )}
            </div>
        </section>
    );
}

/* =====================================================
   CUSTOMERS
===================================================== */
function Customers({ canAdd = false }) {                      /* ← PERM (new prop) */
    const [allCustomers, setAllCustomers] = useState([]);
    const [customers, setCustomers] = useState([]);
    const [selectedCustomerId, setSelectedCustomerId] = useState("");
    const [search, setSearch] = useState("");
    const [loading, setLoading] = useState(false);
    const [saving, setSaving] = useState(false);
    const [error, setError] = useState("");
    const [message, setMessage] = useState("");

    const [form, setForm] = useState({
        customerName: "",
        phone: "",
        customerType: "Retail",
        isEnrolled: true,
    });

    const loadAllCustomers = async () => {
        try {
            setLoading(true);
            setError("");

            const response = await axios.get(`${API}/loyalty/customers`);

            if (response.data.success) {
                const list = response.data.customers || [];
                setAllCustomers(list);
                setCustomers(list);

                if (list.length > 0 && !selectedCustomerId) {
                    setSelectedCustomerId(String(list[0].Id));
                }
            }
        } catch (err) {
            console.error(err);
            setError(err.response?.data?.message || "Failed to load customers");
        } finally {
            setLoading(false);
        }
    };

    const loadCustomers = async (searchValue = search) => {
        try {
            setLoading(true);
            setError("");

            const response = await axios.get(`${API}/loyalty/customers`, {
                params: { search: searchValue },
            });

            if (response.data.success) {
                setCustomers(response.data.customers || []);
            }
        } catch (err) {
            console.error(err);
            setError(err.response?.data?.message || "Failed to load customers");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => { loadAllCustomers(); }, []);

    useEffect(() => {
        const timer = setTimeout(() => loadCustomers(search), 300);
        return () => clearTimeout(timer);
    }, [search]);

    const selectedCustomer =
        allCustomers.find(
            (customer) => String(customer.Id) === String(selectedCustomerId)
        ) || null;

    const updateForm = (name, value) => {
        setForm((prev) => ({ ...prev, [name]: value }));
    };

    const addCustomer = async () => {
        // ← PERM
        if (!canAdd) {                                        /* ← PERM */
            setError("You do not have permission to add customers.");
            return;
        }

        if (!form.customerName.trim()) {
            setError("Customer name is required.");
            return;
        }

        try {
            setSaving(true);
            setError("");
            setMessage("");

            const response = await axios.post(`${API}/loyalty/customers`, {
                ...form,
                customerName: form.customerName.trim(),
                phone: form.phone.trim(),
            });

            if (response.data.success) {
                setForm({
                    customerName: "",
                    phone: "",
                    customerType: "Retail",
                    isEnrolled: true,
                });

                setMessage("Customer added successfully.");
                await loadAllCustomers();
                await loadCustomers(search);
            }
        } catch (err) {
            console.error(err);
            setError(err.response?.data?.message || "Failed to add customer");
        } finally {
            setSaving(false);
        }
    };

    return (
        <section className="rounded-xl border border-gray-300 bg-white shadow-sm">
            <div className="border-b px-6 py-6">
                <h2 className="text-2xl font-semibold">Customers</h2>
                <p className="mt-1 text-sm text-gray-500">
                    Manage customers enrolled in the loyalty program.
                </p>
            </div>

            {message && (
                <div className="mx-6 mt-5 rounded-lg border border-green-300 bg-green-50 p-4 text-sm text-green-700">
                    {message}
                </div>
            )}
            {error && (
                <div className="mx-6 mt-5 rounded-lg border border-red-300 bg-red-50 p-4 text-sm text-red-700">
                    {error}
                </div>
            )}

            {/* ← PERM: read-only banner if no Add */}
            {!canAdd && (                                         /* ← PERM */
                <div className="mx-6 mt-5 rounded-lg border border-amber-200 bg-amber-50 p-3 text-xs font-medium text-amber-700">
                    Read-only mode — you cannot add new customers.
                </div>
            )}

            {/* Customer dropdown (unchanged) */}
            <div className="border-b p-6">
                <div className="max-w-xl">
                    <label className="mb-2 block text-sm font-semibold">
                        Select Customer
                    </label>
                    <select
                        value={selectedCustomerId}
                        onChange={(e) => setSelectedCustomerId(e.target.value)}
                        disabled={loading}
                        className="w-full rounded-xl border border-gray-200 bg-white px-4 py-3 text-sm outline-none focus:border-[#e99a00] focus:ring-2 focus:ring-[#e99a00]/20"
                    >
                        <option value="">
                            {loading
                                ? "Loading customers..."
                                : allCustomers.length === 0
                                ? "No customers available"
                                : "Select Customer"}
                        </option>
                        {allCustomers.map((customer) => (
                            <option key={customer.Id} value={customer.Id}>
                                {customer.CustomerCode} - {customer.CustomerName}
                            </option>
                        ))}
                    </select>
                </div>

                {selectedCustomer && (
                    <div className="mt-4 grid gap-4 rounded-xl border bg-gray-50 p-5 sm:grid-cols-2 lg:grid-cols-4">
                        <div>
                            <p className="text-xs text-gray-500">Customer</p>
                            <p className="mt-1 font-semibold">
                                {selectedCustomer.CustomerName}
                            </p>
                            <p className="text-xs text-gray-500">
                                {selectedCustomer.CustomerCode}
                            </p>
                        </div>
                        <div>
                            <p className="text-xs text-gray-500">Phone</p>
                            <p className="mt-1 font-semibold">
                                {selectedCustomer.Phone || "-"}
                            </p>
                        </div>
                        <div>
                            <p className="text-xs text-gray-500">Loyalty Points</p>
                            <p className="mt-1 text-xl font-bold text-[#e99a00]">
                                {selectedCustomer.LoyaltyPoints ?? 0}
                            </p>
                        </div>
                        <div>
                            <p className="text-xs text-gray-500">Status</p>
                            <p className="mt-1 font-semibold">
                                {selectedCustomer.IsEnrolled ? "Enrolled" : "Not Enrolled"}
                            </p>
                        </div>
                    </div>
                )}
            </div>

            {/* ← PERM: hide Add Customer row entirely when user can't Add */}
            {canAdd && (                                          /* ← PERM */
                <div className="grid gap-3 border-b bg-gray-50 p-6 md:grid-cols-5">
                    <input
                        placeholder="Customer name"
                        value={form.customerName}
                        onChange={(e) => updateForm("customerName", e.target.value)}
                        className="rounded-xl border border-gray-200 bg-white px-4 py-3 text-sm outline-none focus:border-[#e99a00] focus:ring-2 focus:ring-[#e99a00]/20"
                    />
                    <input
                        placeholder="Phone"
                        value={form.phone}
                        onChange={(e) => updateForm("phone", e.target.value)}
                        className="rounded-xl border border-gray-200 bg-white px-4 py-3 text-sm outline-none focus:border-[#e99a00] focus:ring-2 focus:ring-[#e99a00]/20"
                    />
                    <select
                        value={form.customerType}
                        onChange={(e) => updateForm("customerType", e.target.value)}
                        className="rounded-xl border border-gray-200 bg-white px-4 py-3 text-sm outline-none focus:border-[#e99a00]"
                    >
                        <option value="Retail">Retail</option>
                        <option value="Wholesale">Wholesale</option>
                    </select>
                    <button
                        type="button"
                        onClick={addCustomer}
                        disabled={saving}
                        className="rounded-xl bg-[#e99a00] px-5 py-3 text-sm font-semibold text-white transition hover:bg-[#d88d00] disabled:opacity-50"
                    >
                        {saving ? "Adding..." : "Add Customer"}
                    </button>
                </div>
            )}

            {/* Search + table (unchanged) */}
            <div className="border-b p-6">
                <input
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                    placeholder="Search by code, name or phone..."
                    className="w-full max-w-md rounded-xl border border-gray-200 px-4 py-3 text-sm outline-none focus:border-[#e99a00] focus:ring-2 focus:ring-[#e99a00]/20"
                />
            </div>

            <div className="overflow-x-auto">
                <table className="w-full min-w-[850px] text-left text-sm">
                    <thead className="bg-gray-50">
                        <tr>
                            <th className="px-6 py-4">Code</th>
                            <th className="px-6 py-4">Customer</th>
                            <th className="px-6 py-4">Type</th>
                            <th className="px-6 py-4">Points</th>
                            <th className="px-6 py-4">Earned</th>
                            <th className="px-6 py-4">Redeemed</th>
                            <th className="px-6 py-4">Status</th>
                        </tr>
                    </thead>
                    <tbody>
                        {customers.map((customer) => (
                            <tr
                                key={customer.Id}
                                onClick={() => setSelectedCustomerId(String(customer.Id))}
                                className={`cursor-pointer border-t border-gray-100 transition hover:bg-[#fffaf0] ${
                                    String(selectedCustomerId) === String(customer.Id)
                                        ? "bg-[#fff7e6]"
                                        : ""
                                }`}
                            >
                                <td className="px-6 py-4 font-medium">
                                    {customer.CustomerCode}
                                </td>
                                <td className="px-6 py-4">
                                    <div className="font-medium">{customer.CustomerName}</div>
                                    <div className="text-xs text-gray-500">
                                        {customer.Phone || "-"}
                                    </div>
                                </td>
                                <td className="px-6 py-4">{customer.CustomerType}</td>
                                <td className="px-6 py-4">
                                    <span className="font-bold text-[#e99a00]">
                                        {customer.LoyaltyPoints ?? 0}
                                    </span>
                                </td>
                                <td className="px-6 py-4">{customer.TotalEarned ?? 0}</td>
                                <td className="px-6 py-4">{customer.TotalRedeemed ?? 0}</td>
                                <td className="px-6 py-4">
                                    <span
                                        className={`rounded-full px-3 py-1 text-xs font-semibold ${
                                            customer.IsEnrolled
                                                ? "bg-green-100 text-green-700"
                                                : "bg-gray-100 text-gray-600"
                                        }`}
                                    >
                                        {customer.IsEnrolled ? "Enrolled" : "Not Enrolled"}
                                    </span>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>

                {loading && (
                    <div className="p-10 text-center text-sm text-gray-500">
                        Loading customers...
                    </div>
                )}
                {!loading && customers.length === 0 && (
                    <div className="p-10 text-center text-sm text-gray-500">
                        No customers found.
                    </div>
                )}
            </div>
        </section>
    );
}

/* =====================================================
   TRANSACTIONS (view only — no changes needed)
===================================================== */
function Transactions() {
    const [transactions, setTransactions] = useState([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState("");

    const loadTransactions = async () => {
        try {
            setLoading(true);
            setError("");

            const response = await axios.get(`${API}/loyalty/transactions`);

            if (response.data.success) {
                setTransactions(response.data.transactions || []);
            }
        } catch (err) {
            console.error(err);
            setError(err.response?.data?.message || "Failed to load transactions");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => { loadTransactions(); }, []);

    return (
        <section className="rounded-xl border border-gray-300 bg-white shadow-sm">
            <div className="flex flex-col gap-4 border-b px-6 py-6 sm:flex-row sm:items-center sm:justify-between">
                <div>
                    <h2 className="text-2xl font-semibold">Transactions</h2>
                    <p className="mt-1 text-sm text-gray-500">
                        View loyalty points earned and redeemed by customers.
                    </p>
                </div>

                <button
                    type="button"
                    onClick={loadTransactions}
                    disabled={loading}
                    className="w-fit rounded-xl border border-gray-300 px-4 py-2 text-sm font-medium hover:bg-gray-50 disabled:opacity-50"
                >
                    ↻ Refresh
                </button>
            </div>

            {error && (
                <div className="mx-6 mt-5 rounded-lg border border-red-300 bg-red-50 p-4 text-sm text-red-700">
                    {error}
                </div>
            )}

            <div className="overflow-x-auto">
                <table className="w-full min-w-[1100px] text-left text-sm">
                    <thead className="bg-gray-50">
                        <tr>
                            <th className="px-6 py-4">Date</th>
                            <th className="px-6 py-4">Customer</th>
                            <th className="px-6 py-4">Type</th>
                            <th className="px-6 py-4">Reference</th>
                            <th className="px-6 py-4">Amount</th>
                            <th className="px-6 py-4">Points</th>
                            <th className="px-6 py-4">Payment</th>
                            <th className="px-6 py-4">Category</th>
                        </tr>
                    </thead>
                    <tbody>
                        {transactions.map((transaction) => (
                            <tr
                                key={transaction.Id}
                                className="border-t border-gray-100"
                            >
                                <td className="whitespace-nowrap px-6 py-4">
                                    {transaction.CreatedAt
                                        ? new Date(transaction.CreatedAt).toLocaleString()
                                        : "-"}
                                </td>
                                <td className="px-6 py-4">
                                    <div className="font-medium">
                                        {transaction.CustomerName}
                                    </div>
                                    <div className="text-xs text-gray-500">
                                        {transaction.CustomerCode}
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                    <span
                                        className={`rounded-full px-3 py-1 text-xs font-semibold ${
                                            String(transaction.TransactionType).toUpperCase() === "EARN"
                                                ? "bg-green-100 text-green-700"
                                                : "bg-red-100 text-red-700"
                                        }`}
                                    >
                                        {transaction.TransactionType}
                                    </span>
                                </td>
                                <td className="px-6 py-4">
                                    {transaction.ReferenceNo || "-"}
                                </td>
                                <td className="px-6 py-4">
                                    Rs.{Number(transaction.Amount || 0).toFixed(2)}
                                </td>
                                <td className="px-6 py-4 font-semibold">
                                    {transaction.Points}
                                </td>
                                <td className="px-6 py-4">
                                    {transaction.PaymentMethod || "-"}
                                </td>
                                <td className="px-6 py-4">
                                    {transaction.CategoryName || "-"}
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>

                {loading && (
                    <div className="p-10 text-center text-sm text-gray-500">
                        Loading transactions...
                    </div>
                )}
                {!loading && transactions.length === 0 && (
                    <div className="p-10 text-center text-sm text-gray-500">
                        No loyalty transactions found.
                    </div>
                )}
            </div>
        </section>
    );
}

export default Loyalty;