// Reorder.jsx — keyed by ProductCode (+ LocationID), one Reorder Level /
// Reorder Qty that writes to BOTH ProductMaster and ProductStockMaster.
import React, { useCallback, useEffect, useMemo, useState } from "react";
import axios from "axios";
import { usePermissions as usePermissionsContext } from "../context/PermissionsContext";

const API =
  (typeof process !== "undefined" &&
    process.env &&
    process.env.REACT_APP_API_URL) ||
  "http://localhost:5000";

const TOKEN_KEYS = [
  "token", "authToken", "access_token", "accessToken",
  "jwt", "authorization", "Authorization",
];
const TOKEN_KEY_PATTERN = /(auth|user|session|login|token)/i;

const isUsableToken = (value) =>
  typeof value === "string" &&
  value.trim() !== "" &&
  value !== "null" &&
  value !== "undefined";

const tokenFromValue = (value) => {
  if (isUsableToken(value)) return value.trim();
  if (value && typeof value === "object") {
    const nested =
      value.token ?? value.accessToken ?? value.access_token ??
      value.jwt ?? value.authorization;
    if (isUsableToken(nested)) return nested.trim();
    for (const key of ["auth", "user", "session", "data"]) {
      const result = tokenFromValue(value[key]);
      if (result) return result;
    }
  }
  if (typeof value === "string") {
    try {
      const parsed = JSON.parse(value);
      if (parsed && typeof parsed === "object") return tokenFromValue(parsed);
    } catch {
      /* not JSON */
    }
  }
  return null;
};

const readToken = () => {
  if (typeof window === "undefined") return null;
  for (const storage of [window.localStorage, window.sessionStorage]) {
    try {
      for (const key of TOKEN_KEYS) {
        const raw = storage.getItem(key);
        if (!raw) continue;
        const token = tokenFromValue(raw);
        if (token) return token;
      }
      for (let i = 0; i < storage.length; i += 1) {
        const key = storage.key(i);
        if (!key || !TOKEN_KEY_PATTERN.test(key)) continue;
        const raw = storage.getItem(key);
        if (!raw) continue;
        const token = tokenFromValue(raw);
        if (token) return token;
      }
    } catch (error) {
      console.warn("Unable to read authentication storage:", error);
    }
  }
  return null;
};

const clearTokens = () => {
  if (typeof window === "undefined") return;
  try {
    for (const storage of [window.localStorage, window.sessionStorage]) {
      const doomed = [];
      for (let i = 0; i < storage.length; i += 1) {
        const key = storage.key(i);
        if (!key) continue;
        if (TOKEN_KEYS.includes(key) || TOKEN_KEY_PATTERN.test(key)) {
          doomed.push(key);
        }
      }
      doomed.forEach((key) => storage.removeItem(key));
    }
  } catch (error) {
    console.warn("Unable to clear authentication storage:", error);
  }
};

const redirectToLogin = () => {
  if (typeof window === "undefined") return;
  clearTokens();
  if (window.location.pathname !== "/login") window.location.href = "/login";
};

const AUTH_FAILURE_MESSAGES = new Set([
  "authorization token required",
  "authorization token is required",
  "token required",
  "no token provided",
  "invalid token",
  "token expired",
]);

const isAuthFailure = (body) =>
  body &&
  body.success === false &&
  typeof body.message === "string" &&
  AUTH_FAILURE_MESSAGES.has(body.message.trim().toLowerCase());

const reorderApi = axios.create();

reorderApi.interceptors.request.use((config) => {
  const token = readToken();
  config.headers = config.headers || {};
  if (!config.headers.Authorization && token) {
    config.headers.Authorization = /^Bearer\s/i.test(token)
      ? token
      : `Bearer ${token}`;
  }
  if (
    !config.headers.Authorization &&
    process.env.NODE_ENV !== "production"
  ) {
    console.warn("Reorder request has no Authorization header.");
  }
  return config;
});

reorderApi.interceptors.response.use(
  (response) => {
    if (isAuthFailure(response?.data)) {
      const message = response.data.message;
      redirectToLogin();
      return Promise.reject(new Error(message));
    }
    return response;
  },
  (error) => {
    if (error.response?.status === 401) redirectToLogin();
    return Promise.reject(error);
  }
);

const ACTION_TO_COLUMN = {
  View: "CanView",
  Add: "CanAdd",
  Edit: "CanEdit",
  Delete: "CanDelete",
  Print: "CanPrint",
};

const FIELD_TO_COLUMN = {
  CostPrice: "CanViewCostPrice",
  SellingPrice: "CanViewSellingPrice",
  Profit: "CanViewProfit",
};

function usePermissions() {
  const ctx = usePermissionsContext();

  const can = useCallback(
    (moduleName, action = "View") => {
      const column = ACTION_TO_COLUMN[action] || action;
      return ctx.can(moduleName, null, column);
    },
    [ctx]
  );

  const canField = useCallback(
    (moduleName, field) => {
      const column = FIELD_TO_COLUMN[field];
      if (!column) return true;
      return ctx.can(moduleName, null, column);
    },
    [ctx]
  );

  return {
    permissions: ctx.permissions,
    loading: ctx.loading,
    error: ctx.error,
    reload: ctx.reload,
    can,
    canField,
  };
}

const REORDER_MODULE = "Reorder";

const formatNumber = (value) =>
  Number(value || 0).toLocaleString("en-US", { maximumFractionDigits: 3 });

const isBlank = (value) =>
  value === "" || value === null || value === undefined;

// Row identity is ProductCode + LocationID.
const rowKeyOf = (item) =>
  `${item.ProductCode ?? "?"}-${item.LocationID ?? "n"}`;

// Return the first candidate that parses to a finite number (0 is valid).
// Returns null only when nothing usable is present, so we can tell "0" apart
// from "no value".
const firstNumeric = (candidates) => {
  for (const candidate of candidates) {
    if (candidate === null || candidate === undefined) continue;
    if (typeof candidate === "string" && candidate.trim() === "") continue;
    const n = Number(candidate);
    if (Number.isFinite(n)) return n;
  }
  return null;
};

// Normalize whatever the backend sends into { ReOrderLevel, ReOrderQty }.
// Level priority:  ReOrderLevel > ProductReOrderLevel > StockReOrderLevel
// Qty   priority:  ReOrderQty  > ProductReOrderQty  > StockReOrderQty
//                                                   > StockReOrderQuantity
const normalizePayload = (payload) => {
  let rows = null;
  let errorMessage = null;

  if (Array.isArray(payload)) {
    rows = payload;
  } else if (payload && typeof payload === "object") {
    if (payload.success === false) {
      errorMessage = payload.message || "Unable to load products.";
    } else if (Array.isArray(payload.data)) {
      rows = payload.data;
    }
  }

  if (!rows) return { rows: null, errorMessage };

  let missingCodeWarned = false;

  const normalized = rows.map((row) => {
    const level = firstNumeric([
      row.ReOrderLevel,
      row.ProductReOrderLevel,
      row.StockReOrderLevel,
    ]);
    const qtyValue = firstNumeric([
      row.ReOrderQty,
      row.ProductReOrderQty,
      row.StockReOrderQty,
      row.ReOrderQuantity,
    ]);

    const next = {
      ...row,
      ReOrderLevel: level ?? 0,
      ReOrderQty: qtyValue ?? 0,
    };

    if (
      !missingCodeWarned &&
      (next.ProductCode == null || String(next.ProductCode).trim() === "")
    ) {
      missingCodeWarned = true;
      console.warn(
        "Reorder: server response is missing ProductCode. Saving will fail " +
          "until the backend returns ProductCode (and ideally LocationID) " +
          "inside a { success: true, data: [...] } envelope."
      );
    }

    return next;
  });

  return { rows: normalized, errorMessage: null };
};

function Reorder() {
  const [products, setProducts] = useState([]);
  const [search, setSearch] = useState("");
  const [loading, setLoading] = useState(true);
  const [savingId, setSavingId] = useState(null);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  const { can, loading: permsLoading } = usePermissions();
  const canViewReorder = can(REORDER_MODULE, "View");
  const canEditReorder = can(REORDER_MODULE, "Edit");
  const canPrintReorder = can(REORDER_MODULE, "Print");

  const describeError = useCallback((err, fallback) => {
    const status = err.response?.status;
    if (status === 401)
      return "Your session has expired. Please log in again.";
    if (status === 403) {
      return (
        err.response?.data?.message ||
        "You do not have permission to perform this action."
      );
    }
    return (
      err.response?.data?.message ||
      err.response?.data?.error ||
      err.message ||
      fallback
    );
  }, []);

  const loadProducts = useCallback(async () => {
    try {
      setLoading(true);
      setError("");
      setMessage("");
      const response = await reorderApi.get(`${API}/reorder`);
      const { rows, errorMessage } = normalizePayload(response.data);
      if (rows) {
        setProducts(rows);
      } else {
        setProducts([]);
        setError(errorMessage || "Unexpected response from server.");
      }
    } catch (err) {
      console.error("LOAD REORDER PRODUCTS ERROR:", err);
      setError(describeError(err, "Unable to load products."));
    } finally {
      setLoading(false);
    }
  }, [describeError]);

  useEffect(() => {
    if (permsLoading) return;
    if (!canViewReorder) {
      setLoading(false);
      setProducts([]);
      return;
    }
    loadProducts();
  }, [permsLoading, canViewReorder, loadProducts]);

  useEffect(() => {
    if (!message && !error) return undefined;
    const timer = setTimeout(() => {
      setMessage("");
      setError("");
    }, 4000);
    return () => clearTimeout(timer);
  }, [message, error]);

  const filteredProducts = useMemo(() => {
    const value = search.trim().toLowerCase();
    if (!value) return products;
    return products.filter((item) => {
      const code = String(item.ProductCode || "").toLowerCase();
      const name = String(item.ProductName || "").toLowerCase();
      const locationName = String(item.LocationName || "").toLowerCase();
      const locationId = String(item.LocationID || "").toLowerCase();
      return (
        code.includes(value) ||
        name.includes(value) ||
        locationName.includes(value) ||
        locationId.includes(value)
      );
    });
  }, [products, search]);

  const handleFieldChange = (targetKey, field, value) => {
    if (!canEditReorder) return;
    setProducts((current) =>
      current.map((row) =>
        rowKeyOf(row) === targetKey ? { ...row, [field]: value } : row
      )
    );
  };

  const saveProduct = async (item, rowKey) => {
    if (!canEditReorder) {
      setError("You do not have permission to edit reorder settings.");
      return;
    }

    const productCode = item.ProductCode;
    const locationID = item.LocationID;

    if (isBlank(productCode)) {
      setError("Product Code is missing from the server response.");
      return;
    }

    if (isBlank(item.ReOrderLevel) || isBlank(item.ReOrderQty)) {
      setError("Reorder Level and Reorder Qty are required. Enter 0 if none.");
      return;
    }

    const reOrderLevel = Number(item.ReOrderLevel);
    const reOrderQtyValue = Number(item.ReOrderQty);

    if (
      !Number.isFinite(reOrderLevel) ||
      !Number.isFinite(reOrderQtyValue)
    ) {
      setError(
        `Invalid reorder value for ${item.ProductName || item.ProductCode}.`
      );
      return;
    }

    if (reOrderLevel < 0 || reOrderQtyValue < 0) {
      setError("Reorder values cannot be negative.");
      return;
    }

    try {
      setSavingId(rowKey);
      setMessage("");
      setError("");

      const response = await reorderApi.put(`${API}/reorder`, {
        productCode,
        locationID,
        reOrderLevel,
        reOrderQty: reOrderQtyValue,
      });

      const ok =
        response.data?.success === true ||
        (response.data?.success === undefined && response.status < 300);

      if (ok) {
        const label = item.ProductName || item.ProductCode || "Item";
        setMessage(`${label} saved successfully.`);

        setProducts((current) =>
          current.map((row) =>
            rowKeyOf(row) === rowKey
              ? {
                  ...row,
                  ReOrderLevel: reOrderLevel,
                  ReOrderQty: reOrderQtyValue,
                }
              : row
          )
        );
      } else {
        setError(response.data?.message || "Save failed.");
      }
    } catch (err) {
      console.error("SAVE REORDER ERROR:", err);
      setError(describeError(err, "Unable to save reorder settings."));
    } finally {
      setSavingId(null);
    }
  };

  if (permsLoading || loading) {
    return (
      <div className="min-h-screen bg-slate-100 p-4 md:p-6">
        <div className="mx-auto max-w-7xl">
          <div className="rounded-xl border border-slate-200 bg-white p-6 shadow-sm">
            <div className="text-sm text-slate-500">
              Loading reorder settings...
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (!canViewReorder) {
    return (
      <div className="min-h-screen bg-slate-100 p-4 md:p-6">
        <div className="mx-auto max-w-7xl">
          <div className="rounded-xl border border-red-200 bg-red-50 p-6 shadow-sm">
            <h1 className="text-lg font-bold text-red-800">Access denied</h1>
            <p className="mt-1 text-sm text-red-700">
              You do not have permission to view reorder settings.
            </p>
          </div>
        </div>
      </div>
    );
  }

  const inputClass =
    "w-28 rounded-lg border bg-white px-3 py-2 text-right text-sm outline-none focus:ring-2 disabled:cursor-not-allowed disabled:bg-slate-100 disabled:text-slate-500";
  const levelInputClass = `${inputClass} border-blue-300 focus:border-blue-500 focus:ring-blue-100`;
  const qtyInputClass = `${inputClass} border-emerald-300 focus:border-emerald-500 focus:ring-emerald-100`;

  return (
    <div className="min-h-screen bg-slate-100 p-4 md:p-6">
      <div className="mx-auto max-w-7xl">
        <div className="mb-5 rounded-xl border border-slate-200 bg-white shadow-sm print:hidden">
          <div className="flex flex-col gap-4 p-5 lg:flex-row lg:items-center lg:justify-between">
            <div>
              <h1 className="text-2xl font-bold text-slate-800">
                Reorder Level &amp; Quantity
              </h1>
              <p className="mt-1 text-sm text-slate-500">
                One value per row — saving updates both ProductMaster and
                ProductStockMaster.
              </p>
            </div>
            <div className="flex flex-wrap gap-2">
              {canPrintReorder && (
                <button
                  type="button"
                  onClick={() => window.print()}
                  className="rounded-lg bg-slate-800 px-4 py-2.5 text-sm font-semibold text-white shadow-sm transition hover:bg-slate-700"
                >
                  Print
                </button>
              )}
              <button
                type="button"
                onClick={loadProducts}
                className="rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white shadow-sm transition hover:bg-blue-700"
              >
                Refresh
              </button>
            </div>
          </div>
        </div>

        {message && (
          <div className="mb-4 rounded-lg border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-medium text-emerald-700 print:hidden">
            {message}
          </div>
        )}
        {error && (
          <div className="mb-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700 print:hidden">
            {error}
          </div>
        )}

        <div className="mb-5 rounded-xl border border-slate-200 bg-white p-5 shadow-sm print:hidden">
          <div className="flex flex-col gap-3 md:flex-row md:items-end">
            <div className="flex-1">
              <label
                htmlFor="reorder-search"
                className="mb-1 block text-sm font-semibold text-slate-700"
              >
                Search Product
              </label>
              <input
                id="reorder-search"
                type="text"
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search by product code, product name or location..."
                className="w-full rounded-lg border border-slate-300 bg-white px-4 py-3 text-sm outline-none transition focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
              />
            </div>
            <button
              type="button"
              onClick={() => setSearch("")}
              className="rounded-lg bg-slate-600 px-5 py-3 text-sm font-semibold text-white shadow-sm transition hover:bg-slate-700"
            >
              Clear
            </button>
          </div>
          <div className="mt-3 text-xs text-slate-500">
            Showing{" "}
            <strong className="text-slate-700">{filteredProducts.length}</strong>{" "}
            of <strong className="text-slate-700">{products.length}</strong>{" "}
            products
          </div>
        </div>

        {!canEditReorder && (
          <div className="mb-4 rounded-lg border border-amber-200 bg-amber-50 px-4 py-3 text-sm font-medium text-amber-700 print:hidden">
            Read-only access — you can view reorder settings but not change them.
          </div>
        )}

        <div className="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm print:rounded-none print:border-0 print:shadow-none">
          <div className="overflow-x-auto">
            <table className="w-full min-w-[900px] border-collapse">
              <thead>
                <tr className="bg-slate-800 text-left text-xs font-semibold uppercase tracking-wider text-white print:bg-white print:text-black">
                  <th className="whitespace-nowrap border border-slate-700 px-4 py-3 print:border-slate-400">
                    Product Code
                  </th>
                  <th className="whitespace-nowrap border border-slate-700 px-4 py-3 print:border-slate-400">
                    Product Name
                  </th>
                  <th className="whitespace-nowrap border border-slate-700 px-4 py-3 print:border-slate-400">
                    Location
                  </th>
                  <th className="whitespace-nowrap border border-slate-700 px-4 py-3 text-right print:border-slate-400">
                    Current Stock
                  </th>
                  <th className="whitespace-nowrap border border-slate-700 px-4 py-3 text-center print:border-slate-400">
                    Reorder Level
                  </th>
                  <th className="whitespace-nowrap border border-slate-700 px-4 py-3 text-center print:border-slate-400">
                    Reorder Qty
                  </th>
                  <th className="whitespace-nowrap border border-slate-700 px-4 py-3 text-center print:hidden">
                    Action
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-200">
                {filteredProducts.length === 0 ? (
                  <tr>
                    <td
                      colSpan="7"
                      className="px-4 py-12 text-center text-sm text-slate-500"
                    >
                      No products found.
                    </td>
                  </tr>
                ) : (
                  filteredProducts.map((item) => {
                    const rowKey = rowKeyOf(item);
                    const isSaving = savingId === rowKey;
                    const readonly = !canEditReorder;
                    const rowLabel =
                      item.ProductName || item.ProductCode || "item";

                    return (
                      <tr
                        key={rowKey}
                        className="transition hover:bg-slate-50"
                      >
                        <td className="whitespace-nowrap px-4 py-3 text-sm font-semibold text-slate-800">
                          {item.ProductCode || "-"}
                        </td>
                        <td className="min-w-[220px] px-4 py-3 text-sm text-slate-700">
                          {item.ProductName || "-"}
                        </td>
                        <td className="whitespace-nowrap px-4 py-3 text-sm text-slate-700">
                          {item.LocationName || item.LocationID || "-"}
                        </td>
                        <td className="whitespace-nowrap px-4 py-3 text-right text-sm font-semibold text-slate-800">
                          {formatNumber(item.Stock)}
                        </td>
                        <td className="bg-blue-50/60 px-4 py-3 text-center print:bg-white">
                          <input
                            type="number"
                            min="0"
                            step="0.01"
                            disabled={readonly}
                            value={item.ReOrderLevel ?? 0}
                            aria-label={`Reorder level for ${rowLabel}`}
                            onChange={(event) =>
                              handleFieldChange(
                                rowKey,
                                "ReOrderLevel",
                                event.target.value
                              )
                            }
                            className={`${levelInputClass} print:border-0`}
                          />
                        </td>
                        <td className="bg-emerald-50/60 px-4 py-3 text-center print:bg-white">
                          <input
                            type="number"
                            min="0"
                            step="0.01"
                            disabled={readonly}
                            value={item.ReOrderQty ?? 0}
                            aria-label={`Reorder quantity for ${rowLabel}`}
                            onChange={(event) =>
                              handleFieldChange(
                                rowKey,
                                "ReOrderQty",
                                event.target.value
                              )
                            }
                            className={`${qtyInputClass} print:border-0`}
                          />
                        </td>
                        <td className="px-4 py-3 text-center print:hidden">
                          {canEditReorder ? (
                            <button
                              type="button"
                              disabled={isSaving}
                              onClick={() => saveProduct(item, rowKey)}
                              className={`rounded-lg px-4 py-2 text-xs font-bold text-white shadow-sm transition ${
                                isSaving
                                  ? "cursor-not-allowed bg-slate-400"
                                  : "bg-blue-600 hover:bg-blue-700"
                              }`}
                            >
                              {isSaving ? "Saving..." : "Save"}
                            </button>
                          ) : (
                            <span className="text-xs font-semibold text-slate-400">
                              Read only
                            </span>
                          )}
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
          <div className="border-t border-slate-200 bg-slate-50 px-4 py-3 text-xs text-slate-500 print:hidden">
            {filteredProducts.length} of {products.length} products shown
          </div>
        </div>
      </div>
    </div>
  );
}

export default Reorder;