import React, { useEffect, useMemo, useState } from "react";

const API_BASE = "http://localhost:5000/api";

const PAYMENT_METHODS = [
    "Cash",
    "Bank Transfer",
    "Cheque",
    "Card",
    "Other"
];

const initialForm = {
    paymentDate: new Date().toISOString().split("T")[0],
    paymentAmount: "",
    paymentMethod: "Cash",
    referenceNo: "",
    remark: ""
};

const SupplierPayment = () => {
    // ---------------------------------------------------------
    // State
    // ---------------------------------------------------------

    const [suppliers, setSuppliers] = useState([]);
    const [grns, setGrns] = useState([]);
    const [payments, setPayments] = useState([]);
    const [grnDetails, setGrnDetails] = useState([]);

    const [supplierCode, setSupplierCode] = useState("");
    const [selectedGRN, setSelectedGRN] = useState(null);

    const [form, setForm] = useState(initialForm);

    const [supplierSearch, setSupplierSearch] = useState("");
    const [grnSearch, setGrnSearch] = useState("");

    const [loadingSuppliers, setLoadingSuppliers] = useState(false);
    const [loadingGRNs, setLoadingGRNs] = useState(false);
    const [loadingDetails, setLoadingDetails] = useState(false);
    const [loadingHistory, setLoadingHistory] = useState(false);
    const [saving, setSaving] = useState(false);

    const [error, setError] = useState("");
    const [success, setSuccess] = useState("");

    // ---------------------------------------------------------
    // Initial load
    // ---------------------------------------------------------

    useEffect(() => {
        loadSuppliers();
    }, []);

    // ---------------------------------------------------------
    // Utility functions
    // ---------------------------------------------------------

    const formatMoney = (value) => {
        const number = Number(value || 0);

        return number.toLocaleString("en-US", {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2
        });
    };

    const formatQty = (value) => {
        const number = Number(value || 0);

        return number.toLocaleString("en-US", {
            minimumFractionDigits: 3,
            maximumFractionDigits: 3
        });
    };

    const formatDate = (value) => {
        if (!value) {
            return "-";
        }

        const date = new Date(value);

        if (Number.isNaN(date.getTime())) {
            return value;
        }

        return date.toLocaleDateString("en-GB");
    };

    const clearMessages = () => {
        setError("");
        setSuccess("");
    };

    // ---------------------------------------------------------
    // API helper
    // ---------------------------------------------------------

    const fetchJSON = async (url, options = {}) => {
        const response = await fetch(url, {
            ...options,
            headers: {
                "Content-Type": "application/json",
                ...(options.headers || {})
            }
        });

        let data;

        try {
            data = await response.json();
        } catch {
            data = {};
        }

        if (!response.ok || data.success === false) {
            throw new Error(
                data.message ||
                `Request failed with status ${response.status}`
            );
        }

        return data;
    };

    // ---------------------------------------------------------
    // Load suppliers
    // ---------------------------------------------------------

    const loadSuppliers = async () => {
        try {
            setLoadingSuppliers(true);
            setError("");

            const data = await fetchJSON(
                `http://localhost:5000/supplier`
            );

            setSuppliers(data || []);

        } catch (err) {
            console.error("Load suppliers:", err);

            setError(
                err.message || "Failed to load suppliers"
            );
        } finally {
            setLoadingSuppliers(false);
        }
    };

    // ---------------------------------------------------------
    // Load outstanding GRNs
    // ---------------------------------------------------------

    const loadGRNs = async (code) => {
        if (!code) {
            setGrns([]);
            return;
        }

        try {
            setLoadingGRNs(true);
            setError("");

            const data = await fetchJSON(
                `${API_BASE}/supplier-payments/grns/${encodeURIComponent(
                    code
                )}`
            );

            setGrns(data.grns || []);

        } catch (err) {
            console.error("Load GRNs:", err);

            setError(
                err.message || "Failed to load GRNs"
            );

            setGrns([]);
        } finally {
            setLoadingGRNs(false);
        }
    };

    // ---------------------------------------------------------
    // Load payment history
    // ---------------------------------------------------------

    const loadPaymentHistory = async (code) => {
        if (!code) {
            setPayments([]);
            return;
        }

        try {
            setLoadingHistory(true);

            const data = await fetchJSON(
                `${API_BASE}/supplier-payments/history/${encodeURIComponent(
                    code
                )}`
            );

            setPayments(data.payments || []);

        } catch (err) {
            console.error("Load payment history:", err);

            setError(
                err.message || "Failed to load payment history"
            );

            setPayments([]);
        } finally {
            setLoadingHistory(false);
        }
    };

    // ---------------------------------------------------------
    // Load GRN details
    // ---------------------------------------------------------

    const loadGRNDetails = async (grnId) => {
        if (!grnId) {
            setGrnDetails([]);
            return;
        }

        try {
            setLoadingDetails(true);

            const data = await fetchJSON(
                `${API_BASE}/supplier-payments/grn/${grnId}/details`
            );

            setGrnDetails(data.details || []);

        } catch (err) {
            console.error("Load GRN details:", err);

            setError(
                err.message || "Failed to load GRN details"
            );

            setGrnDetails([]);
        } finally {
            setLoadingDetails(false);
        }
    };

    // ---------------------------------------------------------
    // Supplier change
    // ---------------------------------------------------------

    const handleSupplierChange = async (event) => {
        const code = event.target.value;

        clearMessages();

        setSupplierCode(code);
        setSelectedGRN(null);
        setGrnDetails([]);
        setGrnSearch("");
        setForm(initialForm);

        if (!code) {
            setGrns([]);
            setPayments([]);
            return;
        }

        await Promise.all([
            loadGRNs(code),
            loadPaymentHistory(code)
        ]);
    };

    // ---------------------------------------------------------
    // Select GRN
    // ---------------------------------------------------------

    const handleSelectGRN = async (grn) => {
        clearMessages();

        setSelectedGRN(grn);

        setForm((previous) => ({
            ...previous,
            paymentAmount: Number(
                grn.BalanceAmount || 0
            ).toFixed(2)
        }));

        await loadGRNDetails(grn.GRNID);
    };

    // ---------------------------------------------------------
    // Form change
    // ---------------------------------------------------------

    const handleFormChange = (event) => {
        const {
            name,
            value
        } = event.target;

        setForm((previous) => ({
            ...previous,
            [name]: value
        }));

        clearMessages();
    };

    // ---------------------------------------------------------
    // Pay full balance
    // ---------------------------------------------------------

    const handlePayFullBalance = () => {
        if (!selectedGRN) {
            return;
        }

        setForm((previous) => ({
            ...previous,
            paymentAmount: Number(
                selectedGRN.BalanceAmount || 0
            ).toFixed(2)
        }));

        clearMessages();
    };

    // ---------------------------------------------------------
    // Clear selected GRN
    // ---------------------------------------------------------

    const clearSelectedGRN = () => {
        setSelectedGRN(null);
        setGrnDetails([]);

        setForm(initialForm);

        clearMessages();
    };

    // ---------------------------------------------------------
    // Submit payment
    // ---------------------------------------------------------

    const handleSubmit = async (event) => {
        event.preventDefault();

        clearMessages();

        if (!supplierCode) {
            setError("Please select a supplier.");
            return;
        }

        if (!selectedGRN) {
            setError("Please select a GRN.");
            return;
        }

        if (!form.paymentDate) {
            setError("Please select a payment date.");
            return;
        }

        const amount = Number(form.paymentAmount || 0);

        const balance = Number(
            selectedGRN.BalanceAmount || 0
        );

        if (!Number.isFinite(amount) || amount <= 0) {
            setError(
                "Payment amount must be greater than zero."
            );
            return;
        }

        if (balance <= 0) {
            setError(
                "This GRN has no outstanding balance."
            );
            return;
        }

        if (amount > balance + 0.001) {
            setError(
                `Payment amount cannot exceed the outstanding balance of ${formatMoney(
                    balance
                )}.`
            );
            return;
        }

        if (!form.paymentMethod) {
            setError("Please select a payment method.");
            return;
        }

        // Cheque and bank transfer should normally have
        // a reference number.
        if (
            (
                form.paymentMethod === "Cheque" ||
                form.paymentMethod === "Bank Transfer"
            ) &&
            !form.referenceNo.trim()
        ) {
            setError(
                `Reference number is required for ${form.paymentMethod}.`
            );
            return;
        }

        try {
            setSaving(true);

            const payload = {
                grnId: selectedGRN.GRNID,

                paymentDate: form.paymentDate,

                paymentAmount: Number(
                    amount.toFixed(2)
                ),

                paymentMethod: form.paymentMethod,

                referenceNo:
                    form.referenceNo.trim() || null,

                remark:
                    form.remark.trim() || null,

                locationId:
                    selectedGRN.LocationID,

                // IMPORTANT:
                // Replace this with your logged-in
                // username from your authentication context.
                username: "admin"
            };

            const data = await fetchJSON(
                `${API_BASE}/supplier-payments`,
                {
                    method: "POST",
                    body: JSON.stringify(payload)
                }
            );

            setSuccess(
                `Payment saved successfully. Payment ID: ${data.paymentId}`
            );

            // Reset payment form
            setForm({
                ...initialForm,
                paymentDate: new Date()
                    .toISOString()
                    .split("T")[0]
            });

            setSelectedGRN(null);
            setGrnDetails([]);

            // Refresh outstanding GRNs
            await loadGRNs(supplierCode);

            // Refresh payment history
            await loadPaymentHistory(supplierCode);

        } catch (err) {
            console.error("Save supplier payment:", err);

            setError(
                err.message ||
                "Failed to save supplier payment."
            );
        } finally {
            setSaving(false);
        }
    };

    // ---------------------------------------------------------
    // Filter suppliers
    // ---------------------------------------------------------

    const filteredSuppliers = useMemo(() => {
        const search = supplierSearch
            .trim()
            .toLowerCase();

        if (!search) {
            return suppliers;
        }

        return suppliers.filter((supplier) => {
            const code = String(
                supplier.SupplierCode || ""
            ).toLowerCase();

            const name = String(
                supplier.SupplierName || ""
            ).toLowerCase();

            return (
                code.includes(search) ||
                name.includes(search)
            );
        });
    }, [suppliers, supplierSearch]);

    // ---------------------------------------------------------
    // Filter GRNs
    // ---------------------------------------------------------

    const filteredGRNs = useMemo(() => {
        const search = grnSearch
            .trim()
            .toLowerCase();

        if (!search) {
            return grns;
        }

        return grns.filter((grn) => {
            const grnNo = String(
                grn.GRNNo || ""
            ).toLowerCase();

            const poNo = String(
                grn.PONo || ""
            ).toLowerCase();

            const referenceNo = String(
                grn.ReferenceNo || ""
            ).toLowerCase();

            return (
                grnNo.includes(search) ||
                poNo.includes(search) ||
                referenceNo.includes(search)
            );
        });
    }, [grns, grnSearch]);

    // ---------------------------------------------------------
    // Supplier totals
    // ---------------------------------------------------------

    const supplierTotals = useMemo(() => {
        return grns.reduce(
            (totals, grn) => {
                totals.totalNet += Number(
                    grn.TotalNet || 0
                );

                totals.totalPaid += Number(
                    grn.TotalPaid || 0
                );

                totals.balance += Number(
                    grn.BalanceAmount || 0
                );

                return totals;
            },
            {
                totalNet: 0,
                totalPaid: 0,
                balance: 0
            }
        );
    }, [grns]);

    // ---------------------------------------------------------
    // GRN item totals
    // ---------------------------------------------------------

    const detailTotals = useMemo(() => {
        return grnDetails.reduce(
            (totals, item) => {
                totals.qty += Number(
                    item.Qty || 0
                );

                totals.gross += Number(
                    item.GrossAmount || 0
                );

                totals.discount += Number(
                    item.DiscountAmount || 0
                );

                totals.net += Number(
                    item.NetAmount || 0
                );

                return totals;
            },
            {
                qty: 0,
                gross: 0,
                discount: 0,
                net: 0
            }
        );
    }, [grnDetails]);

    // ---------------------------------------------------------
    // Current payment preview
    // ---------------------------------------------------------

    const paymentPreview = useMemo(() => {
        if (!selectedGRN) {
            return {
                payment: 0,
                remaining: 0
            };
        }

        const payment = Number(
            form.paymentAmount || 0
        );

        const balance = Number(
            selectedGRN.BalanceAmount || 0
        );

        return {
            payment,
            remaining: Math.max(
                balance - payment,
                0
            )
        };
    }, [selectedGRN, form.paymentAmount]);

    // ---------------------------------------------------------
    // Render
    // ---------------------------------------------------------

    return (
        <div
            style={{
                width: "100%",
                padding: "24px",
                boxSizing: "border-box",
                fontFamily:
                    "Arial, Helvetica, sans-serif",
                background: "#f5f6f8",
                minHeight: "100vh"
            }}
        >

            {/* ================================================= */}
            {/* HEADER                                            */}
            {/* ================================================= */}

            <div
                style={{
                    background: "#ffffff",
                    borderRadius: "10px",
                    padding: "20px 24px",
                    marginBottom: "20px",
                    boxShadow:
                        "0 1px 4px rgba(0,0,0,0.08)"
                }}
            >
                <div
                    style={{
                        display: "flex",
                        justifyContent:
                            "space-between",
                        alignItems: "center",
                        gap: "15px",
                        flexWrap: "wrap"
                    }}
                >
                    <div>
                        <h2
                            style={{
                                margin: 0,
                                fontSize: "24px"
                            }}
                        >
                            Supplier Payment
                        </h2>

                        <div
                            style={{
                                marginTop: "5px",
                                color: "#666",
                                fontSize: "14px"
                            }}
                        >
                            Manage supplier payments
                            against GRNs
                        </div>
                    </div>

                    <button
                        type="button"
                        onClick={() => {
                            loadSuppliers();

                            if (supplierCode) {
                                loadGRNs(
                                    supplierCode
                                );

                                loadPaymentHistory(
                                    supplierCode
                                );
                            }
                        }}
                        disabled={
                            loadingSuppliers ||
                            loadingGRNs ||
                            loadingHistory
                        }
                        style={buttonStyle(
                            "#374151"
                        )}
                    >
                        Refresh
                    </button>
                </div>
            </div>

            {/* ================================================= */}
            {/* ALERTS                                            */}
            {/* ================================================= */}

            {error && (
                <div
                    style={{
                        background: "#fee2e2",
                        border:
                            "1px solid #fecaca",
                        color: "#991b1b",
                        padding: "12px 15px",
                        borderRadius: "8px",
                        marginBottom: "15px"
                    }}
                >
                    {error}
                </div>
            )}

            {success && (
                <div
                    style={{
                        background: "#dcfce7",
                        border:
                            "1px solid #bbf7d0",
                        color: "#166534",
                        padding: "12px 15px",
                        borderRadius: "8px",
                        marginBottom: "15px"
                    }}
                >
                    {success}
                </div>
            )}

            {/* ================================================= */}
            {/* SUPPLIER SELECTION                                 */}
            {/* ================================================= */}

            <div style={cardStyle}>

                <h3 style={sectionTitle}>
                    Supplier
                </h3>

                <div
                    style={{
                        display: "grid",
                        gridTemplateColumns:
                            "minmax(200px, 1fr) minmax(200px, 1fr)",
                        gap: "15px"
                    }}
                >

                    <div>
                        <label style={labelStyle}>
                            Search Supplier
                        </label>

                        <input
                            type="text"
                            value={supplierSearch}
                            onChange={(e) =>
                                setSupplierSearch(
                                    e.target.value
                                )
                            }
                            placeholder="Search code or name..."
                            style={inputStyle}
                        />
                    </div>

                    <div>
                        <label style={labelStyle}>
                            Supplier
                        </label>

                        <select
                            value={supplierCode}
                            onChange={
                                handleSupplierChange
                            }
                            style={inputStyle}
                            disabled={
                                loadingSuppliers
                            }
                        >
                            <option value="">
                                {loadingSuppliers
                                    ? "Loading suppliers..."
                                    : "Select Supplier"}
                            </option>

                            {filteredSuppliers.map(
                                (supplier) => (
                                    <option
                                        key={
                                            supplier.SupplierCode
                                        }
                                        value={
                                            supplier.SupplierCode
                                        }
                                    >
                                        {
                                            supplier.SupplierCode
                                        }{" "}
                                        -{" "}
                                        {
                                            supplier.SupplierName
                                        }
                                    </option>
                                )
                            )}
                        </select>
                    </div>

                </div>

            </div>

            {/* ================================================= */}
            {/* SUPPLIER SUMMARY                                   */}
            {/* ================================================= */}

            {supplierCode && (
                <div
                    style={{
                        display: "grid",
                        gridTemplateColumns:
                            "repeat(3, minmax(150px, 1fr))",
                        gap: "15px",
                        marginBottom: "20px"
                    }}
                >

                    <SummaryCard
                        title="Outstanding GRN Total"
                        value={formatMoney(
                            supplierTotals.totalNet
                        )}
                    />

                    <SummaryCard
                        title="Already Paid"
                        value={formatMoney(
                            supplierTotals.totalPaid
                        )}
                    />

                    <SummaryCard
                        title="Supplier Outstanding"
                        value={formatMoney(
                            supplierTotals.balance
                        )}
                    />

                </div>
            )}

            {/* ================================================= */}
            {/* OUTSTANDING GRNS                                   */}
            {/* ================================================= */}

            {supplierCode && (
                <div style={cardStyle}>

                    <div
                        style={{
                            display: "flex",
                            justifyContent:
                                "space-between",
                            alignItems: "center",
                            gap: "15px",
                            marginBottom: "15px",
                            flexWrap: "wrap"
                        }}
                    >
                        <h3
                            style={{
                                ...sectionTitle,
                                marginBottom: 0
                            }}
                        >
                            Outstanding GRNs
                        </h3>

                        <input
                            type="text"
                            value={grnSearch}
                            onChange={(e) =>
                                setGrnSearch(
                                    e.target.value
                                )
                            }
                            placeholder="Search GRN / PO / reference..."
                            style={{
                                ...inputStyle,
                                width: "300px",
                                maxWidth: "100%"
                            }}
                        />
                    </div>

                    {loadingGRNs ? (
                        <LoadingMessage text="Loading outstanding GRNs..." />
                    ) : (
                        <div
                            style={{
                                overflowX:
                                    "auto"
                            }}
                        >
                            <table
                                style={
                                    tableStyle
                                }
                            >
                                <thead>
                                    <tr>
                                        <th>
                                            GRN No
                                        </th>

                                        <th>
                                            Date
                                        </th>

                                        <th>
                                            PO No
                                        </th>

                                        <th>
                                            Reference
                                        </th>

                                        <th>
                                            Items
                                        </th>

                                        <th>
                                            Qty
                                        </th>

                                        <th>
                                            Net Total
                                        </th>

                                        <th>
                                            Paid
                                        </th>

                                        <th>
                                            Balance
                                        </th>

                                        <th>
                                            Action
                                        </th>
                                    </tr>
                                </thead>

                                <tbody>
                                    {filteredGRNs.length ===
                                    0 ? (
                                        <tr>
                                            <td
                                                colSpan="10"
                                                style={{
                                                    textAlign:
                                                        "center",
                                                    padding:
                                                        "30px",
                                                    color:
                                                        "#777"
                                                }}
                                            >
                                                No outstanding
                                                GRNs found.
                                            </td>
                                        </tr>
                                    ) : (
                                        filteredGRNs.map(
                                            (grn) => (
                                                <tr
                                                    key={
                                                        grn.GRNID
                                                    }
                                                    style={{
                                                        background:
                                                            selectedGRN?.GRNID ===
                                                            grn.GRNID
                                                                ? "#eff6ff"
                                                                : "#fff"
                                                    }}
                                                >
                                                    <td>
                                                        <strong>
                                                            {
                                                                grn.GRNNo
                                                            }
                                                        </strong>
                                                    </td>

                                                    <td>
                                                        {formatDate(
                                                            grn.GRNDate
                                                        )}
                                                    </td>

                                                    <td>
                                                        {
                                                            grn.PONo ||
                                                            "-"
                                                        }
                                                    </td>

                                                    <td>
                                                        {
                                                            grn.ReferenceNo ||
                                                            "-"
                                                        }
                                                    </td>

                                                    <td
                                                        style={{
                                                            textAlign:
                                                                "right"
                                                        }}
                                                    >
                                                        {
                                                            grn.ItemCount ??
                                                            "-"
                                                        }
                                                    </td>

                                                    <td
                                                        style={{
                                                            textAlign:
                                                                "right"
                                                        }}
                                                    >
                                                        {formatQty(
                                                            grn.TotalQty
                                                        )}
                                                    </td>

                                                    <td
                                                        style={{
                                                            textAlign:
                                                                "right"
                                                        }}
                                                    >
                                                        {formatMoney(
                                                            grn.TotalNet
                                                        )}
                                                    </td>

                                                    <td
                                                        style={{
                                                            textAlign:
                                                                "right"
                                                        }}
                                                    >
                                                        {formatMoney(
                                                            grn.TotalPaid
                                                        )}
                                                    </td>

                                                    <td
                                                        style={{
                                                            textAlign:
                                                                "right",
                                                            fontWeight:
                                                                "bold"
                                                        }}
                                                    >
                                                        {formatMoney(
                                                            grn.BalanceAmount
                                                        )}
                                                    </td>

                                                    <td>
                                                        <button
                                                            type="button"
                                                            onClick={() =>
                                                                handleSelectGRN(
                                                                    grn
                                                                )
                                                            }
                                                            style={buttonStyle(
                                                                "#2563eb"
                                                            )}
                                                        >
                                                            Select
                                                        </button>
                                                    </td>
                                                </tr>
                                            )
                                        )
                                    )}
                                </tbody>
                            </table>
                        </div>
                    )}

                </div>
            )}

            {/* ================================================= */}
            {/* SELECTED GRN                                      */}
            {/* ================================================= */}

            {selectedGRN && (
                <div style={cardStyle}>

                    <div
                        style={{
                            display: "flex",
                            justifyContent:
                                "space-between",
                            alignItems: "center",
                            marginBottom: "15px",
                            gap: "15px",
                            flexWrap: "wrap"
                        }}
                    >
                        <h3
                            style={{
                                ...sectionTitle,
                                marginBottom: 0
                            }}
                        >
                            GRN Details -{" "}
                            {selectedGRN.GRNNo}
                        </h3>

                        <button
                            type="button"
                            onClick={
                                clearSelectedGRN
                            }
                            style={buttonStyle(
                                "#6b7280"
                            )}
                        >
                            Close
                        </button>
                    </div>

                    {/* GRN HEADER */}

                    <div
                        style={{
                            display: "grid",
                            gridTemplateColumns:
                                "repeat(5, minmax(120px, 1fr))",
                            gap: "12px",
                            marginBottom: "20px"
                        }}
                    >

                        <InfoBox
                            label="GRN No"
                            value={
                                selectedGRN.GRNNo
                            }
                        />

                        <InfoBox
                            label="GRN Date"
                            value={formatDate(
                                selectedGRN.GRNDate
                            )}
                        />

                        <InfoBox
                            label="PO No"
                            value={
                                selectedGRN.PONo ||
                                "-"
                            }
                        />

                        <InfoBox
                            label="Reference"
                            value={
                                selectedGRN.ReferenceNo ||
                                "-"
                            }
                        />

                        <InfoBox
                            label="Payment Type"
                            value={
                                selectedGRN.PaymentType ||
                                "-"
                            }
                        />

                    </div>

                    {/* GRN TOTALS */}

                    <div
                        style={{
                            display: "grid",
                            gridTemplateColumns:
                                "repeat(5, minmax(140px, 1fr))",
                            gap: "12px",
                            marginBottom: "20px"
                        }}
                    >

                        <AmountBox
                            label="Gross"
                            value={
                                selectedGRN.TotalGross
                            }
                        />

                        <AmountBox
                            label="Discount"
                            value={
                                selectedGRN.TotalDiscount
                            }
                        />

                        <AmountBox
                            label="Net Total"
                            value={
                                selectedGRN.TotalNet
                            }
                        />

                        <AmountBox
                            label="Paid"
                            value={
                                selectedGRN.TotalPaid
                            }
                        />

                        <AmountBox
                            label="Balance"
                            value={
                                selectedGRN.BalanceAmount
                            }
                            strong
                        />

                    </div>

                    {/* ================================================= */}
                    {/* GRN ITEMS                                           */}
                    {/* ================================================= */}

                    <h4
                        style={{
                            margin: "10px 0"
                        }}
                    >
                        GRN Items
                    </h4>

                    {loadingDetails ? (
                        <LoadingMessage text="Loading GRN items..." />
                    ) : (
                        <div
                            style={{
                                overflowX:
                                    "auto",
                                marginBottom:
                                    "25px"
                            }}
                        >
                            <table
                                style={
                                    tableStyle
                                }
                            >
                                <thead>
                                    <tr>
                                        <th>
                                            #
                                        </th>

                                        <th>
                                            Product Code
                                        </th>

                                        <th>
                                            Product Name
                                        </th>

                                        <th>
                                            Qty
                                        </th>

                                        <th>
                                            Cost Price
                                        </th>

                                        <th>
                                            Discount %
                                        </th>

                                        <th>
                                            Gross
                                        </th>

                                        <th>
                                            Discount
                                        </th>

                                        <th>
                                            Net Amount
                                        </th>
                                    </tr>
                                </thead>

                                <tbody>
                                    {grnDetails.length ===
                                    0 ? (
                                        <tr>
                                            <td
                                                colSpan="9"
                                                style={{
                                                    textAlign:
                                                        "center",
                                                    padding:
                                                        "25px"
                                                }}
                                            >
                                                No GRN
                                                items
                                                found.
                                            </td>
                                        </tr>
                                    ) : (
                                        grnDetails.map(
                                            (
                                                item,
                                                index
                                            ) => (
                                                <tr
                                                    key={
                                                        item.GRNDetailID
                                                    }
                                                >
                                                    <td>
                                                        {index +
                                                            1}
                                                    </td>

                                                    <td>
                                                        {
                                                            item.ProductCode
                                                        }
                                                    </td>

                                                    <td>
                                                        {
                                                            item.ProductName ||
                                                            "-"
                                                        }
                                                    </td>

                                                    <td
                                                        style={{
                                                            textAlign:
                                                                "right"
                                                        }}
                                                    >
                                                        {formatQty(
                                                            item.Qty
                                                        )}
                                                    </td>

                                                    <td
                                                        style={{
                                                            textAlign:
                                                                "right"
                                                        }}
                                                    >
                                                        {formatMoney(
                                                            item.CostPrice
                                                        )}
                                                    </td>

                                                    <td
                                                        style={{
                                                            textAlign:
                                                                "right"
                                                        }}
                                                    >
                                                        {Number(
                                                            item.FixedDiscountPercentage ||
                                                                0
                                                        ).toFixed(
                                                            2
                                                        )}
                                                        %
                                                    </td>

                                                    <td
                                                        style={{
                                                            textAlign:
                                                                "right"
                                                        }}
                                                    >
                                                        {formatMoney(
                                                            item.GrossAmount
                                                        )}
                                                    </td>

                                                    <td
                                                        style={{
                                                            textAlign:
                                                                "right"
                                                        }}
                                                    >
                                                        {formatMoney(
                                                            item.DiscountAmount
                                                        )}
                                                    </td>

                                                    <td
                                                        style={{
                                                            textAlign:
                                                                "right",
                                                            fontWeight:
                                                                "bold"
                                                        }}
                                                    >
                                                        {formatMoney(
                                                            item.NetAmount
                                                        )}
                                                    </td>
                                                </tr>
                                            )
                                        )
                                    )}
                                </tbody>

                                {grnDetails.length >
                                    0 && (
                                    <tfoot>
                                        <tr>
                                            <th
                                                colSpan="3"
                                            >
                                                Total
                                            </th>

                                            <th
                                                style={{
                                                    textAlign:
                                                        "right"
                                                }}
                                            >
                                                {formatQty(
                                                    detailTotals.qty
                                                )}
                                            </th>

                                            <th></th>

                                            <th></th>

                                            <th
                                                style={{
                                                    textAlign:
                                                        "right"
                                                }}
                                            >
                                                {formatMoney(
                                                    detailTotals.gross
                                                )}
                                            </th>

                                            <th
                                                style={{
                                                    textAlign:
                                                        "right"
                                                }}
                                            >
                                                {formatMoney(
                                                    detailTotals.discount
                                                )}
                                            </th>

                                            <th
                                                style={{
                                                    textAlign:
                                                        "right"
                                                }}
                                            >
                                                {formatMoney(
                                                    detailTotals.net
                                                )}
                                            </th>
                                        </tr>
                                    </tfoot>
                                )}

                            </table>
                        </div>
                    )}

                    {/* ================================================= */}
                    {/* PAYMENT FORM                                        */}
                    {/* ================================================= */}

                    <div
                        style={{
                            borderTop:
                                "1px solid #e5e7eb",
                            paddingTop: "20px"
                        }}
                    >

                        <h4
                            style={{
                                marginTop: 0
                            }}
                        >
                            Make Payment
                        </h4>

                        <form
                            onSubmit={
                                handleSubmit
                            }
                        >

                            <div
                                style={{
                                    display: "grid",
                                    gridTemplateColumns:
                                        "repeat(2, minmax(200px, 1fr))",
                                    gap: "15px"
                                }}
                            >

                                {/* DATE */}

                                <div>
                                    <label
                                        style={
                                            labelStyle
                                        }
                                    >
                                        Payment Date *
                                    </label>

                                    <input
                                        type="date"
                                        name="paymentDate"
                                        value={
                                            form.paymentDate
                                        }
                                        onChange={
                                            handleFormChange
                                        }
                                        required
                                        style={
                                            inputStyle
                                        }
                                    />
                                </div>

                                {/* AMOUNT */}

                                <div>
                                    <label
                                        style={
                                            labelStyle
                                        }
                                    >
                                        Payment Amount *
                                    </label>

                                    <div
                                        style={{
                                            display:
                                                "flex",
                                            gap: "8px"
                                        }}
                                    >
                                        <input
                                            type="number"
                                            name="paymentAmount"
                                            value={
                                                form.paymentAmount
                                            }
                                            onChange={
                                                handleFormChange
                                            }
                                            min="0.01"
                                            max={Number(
                                                selectedGRN.BalanceAmount ||
                                                    0
                                            )}
                                            step="0.01"
                                            required
                                            style={{
                                                ...inputStyle,
                                                flex: 1
                                            }}
                                        />

                                        <button
                                            type="button"
                                            onClick={
                                                handlePayFullBalance
                                            }
                                            style={buttonStyle(
                                                "#059669"
                                            )}
                                        >
                                            Full
                                        </button>
                                    </div>

                                    <div
                                        style={{
                                            fontSize:
                                                "12px",
                                            marginTop:
                                                "5px",
                                            color:
                                                "#666"
                                        }}
                                    >
                                        Maximum:{" "}
                                        {formatMoney(
                                            selectedGRN.BalanceAmount
                                        )}
                                    </div>
                                </div>

                                {/* PAYMENT METHOD */}

                                <div>
                                    <label
                                        style={
                                            labelStyle
                                        }
                                    >
                                        Payment Method *
                                    </label>

                                    <select
                                        name="paymentMethod"
                                        value={
                                            form.paymentMethod
                                        }
                                        onChange={
                                            handleFormChange
                                        }
                                        required
                                        style={
                                            inputStyle
                                        }
                                    >
                                        {PAYMENT_METHODS.map(
                                            (
                                                method
                                            ) => (
                                                <option
                                                    key={
                                                        method
                                                    }
                                                    value={
                                                        method
                                                    }
                                                >
                                                    {
                                                        method
                                                    }
                                                </option>
                                            )
                                        )}
                                    </select>
                                </div>

                                {/* REFERENCE */}

                                <div>
                                    <label
                                        style={
                                            labelStyle
                                        }
                                    >
                                        Reference No
                                        {(form.paymentMethod ===
                                            "Cheque" ||
                                            form.paymentMethod ===
                                                "Bank Transfer") &&
                                            " *"}
                                    </label>

                                    <input
                                        type="text"
                                        name="referenceNo"
                                        value={
                                            form.referenceNo
                                        }
                                        onChange={
                                            handleFormChange
                                        }
                                        maxLength="100"
                                        placeholder={
                                            form.paymentMethod ===
                                                "Cheque"
                                                ? "Cheque number"
                                                : form.paymentMethod ===
                                                  "Bank Transfer"
                                                ? "Bank reference"
                                                : "Optional"
                                        }
                                        style={
                                            inputStyle
                                        }
                                    />
                                </div>

                            </div>

                            {/* REMARK */}

                            <div
                                style={{
                                    marginTop:
                                        "15px"
                                }}
                            >
                                <label
                                    style={
                                        labelStyle
                                    }
                                >
                                    Remark
                                </label>

                                <textarea
                                    name="remark"
                                    value={
                                        form.remark
                                    }
                                    onChange={
                                        handleFormChange
                                    }
                                    maxLength="500"
                                    rows="3"
                                    placeholder="Optional remark..."
                                    style={{
                                        ...inputStyle,
                                        resize: "vertical"
                                    }}
                                />
                            </div>

                            {/* PAYMENT PREVIEW */}

                            <div
                                style={{
                                    marginTop:
                                        "20px",
                                    padding:
                                        "15px",
                                    borderRadius:
                                        "8px",
                                    background:
                                        "#f8fafc",
                                    border:
                                        "1px solid #e2e8f0",
                                    display:
                                        "grid",
                                    gridTemplateColumns:
                                        "repeat(3, 1fr)",
                                    gap: "15px"
                                }}
                            >

                                <AmountBox
                                    label="Current Balance"
                                    value={
                                        selectedGRN.BalanceAmount
                                    }
                                />

                                <AmountBox
                                    label="Payment"
                                    value={
                                        paymentPreview.payment
                                    }
                                />

                                <AmountBox
                                    label="Balance After Payment"
                                    value={
                                        paymentPreview.remaining
                                    }
                                    strong
                                />

                            </div>

                            {/* BUTTONS */}

                            <div
                                style={{
                                    display:
                                        "flex",
                                    justifyContent:
                                        "flex-end",
                                    gap: "10px",
                                    marginTop:
                                        "20px"
                                }}
                            >

                                <button
                                    type="button"
                                    onClick={
                                        clearSelectedGRN
                                    }
                                    disabled={
                                        saving
                                    }
                                    style={buttonStyle(
                                        "#6b7280"
                                    )}
                                >
                                    Cancel
                                </button>

                                <button
                                    type="submit"
                                    disabled={
                                        saving ||
                                        loadingDetails
                                    }
                                    style={{
                                        ...buttonStyle(
                                            "#2563eb"
                                        ),
                                        minWidth:
                                            "150px"
                                    }}
                                >
                                    {saving
                                        ? "Saving..."
                                        : "Save Payment"}
                                </button>

                            </div>

                        </form>

                    </div>

                </div>
            )}

            {/* ================================================= */}
            {/* PAYMENT HISTORY                                    */}
            {/* ================================================= */}

            {supplierCode && (
                <div style={cardStyle}>

                    <div
                        style={{
                            display: "flex",
                            justifyContent:
                                "space-between",
                            alignItems: "center",
                            marginBottom:
                                "15px"
                        }}
                    >
                        <h3
                            style={{
                                ...sectionTitle,
                                marginBottom: 0
                            }}
                        >
                            Payment History
                        </h3>

                        {loadingHistory && (
                            <span
                                style={{
                                    fontSize:
                                        "13px",
                                    color:
                                        "#666"
                                }}
                            >
                                Loading...
                            </span>
                        )}
                    </div>

                    <div
                        style={{
                            overflowX:
                                "auto"
                        }}
                    >
                        <table
                            style={
                                tableStyle
                            }
                        >
                            <thead>
                                <tr>
                                    <th>
                                        Payment ID
                                    </th>

                                    <th>
                                        GRN No
                                    </th>

                                    <th>
                                        Date
                                    </th>

                                    <th>
                                        Amount
                                    </th>

                                    <th>
                                        Method
                                    </th>

                                    <th>
                                        Reference
                                    </th>

                                    <th>
                                        Remark
                                    </th>

                                    <th>
                                        User
                                    </th>

                                    <th>
                                        Created
                                    </th>
                                </tr>
                            </thead>

                            <tbody>
                                {payments.length ===
                                0 ? (
                                    <tr>
                                        <td
                                            colSpan="9"
                                            style={{
                                                textAlign:
                                                    "center",
                                                padding:
                                                    "30px",
                                                color:
                                                    "#777"
                                            }}
                                        >
                                            No payment
                                            history
                                            found.
                                        </td>
                                    </tr>
                                ) : (
                                    payments.map(
                                        (
                                            payment
                                        ) => (
                                            <tr
                                                key={
                                                    payment.PaymentID
                                                }
                                            >
                                                <td>
                                                    {
                                                        payment.PaymentID
                                                    }
                                                </td>

                                                <td>
                                                    {
                                                        payment.GRNNo
                                                    }
                                                </td>

                                                <td>
                                                    {formatDate(
                                                        payment.PaymentDate
                                                    )}
                                                </td>

                                                <td
                                                    style={{
                                                        textAlign:
                                                            "right",
                                                        fontWeight:
                                                            "bold"
                                                    }}
                                                >
                                                    {formatMoney(
                                                        payment.PaymentAmount
                                                    )}
                                                </td>

                                                <td>
                                                    {
                                                        payment.PaymentMethod
                                                    }
                                                </td>

                                                <td>
                                                    {
                                                        payment.ReferenceNo ||
                                                        "-"
                                                    }
                                                </td>

                                                <td>
                                                    {
                                                        payment.Remark ||
                                                        "-"
                                                    }
                                                </td>

                                                <td>
                                                    {
                                                        payment.Username ||
                                                        "-"
                                                    }
                                                </td>

                                                <td>
                                                    {formatDate(
                                                        payment.CreatedDate
                                                    )}
                                                </td>
                                            </tr>
                                        )
                                    )
                                )}
                            </tbody>
                        </table>
                    </div>

                </div>
            )}

        </div>
    );
};

// =============================================================
// Reusable components
// =============================================================

const SummaryCard = ({
    title,
    value
}) => {
    return (
        <div
            style={{
                background: "#ffffff",
                borderRadius: "10px",
                padding: "18px",
                boxShadow:
                    "0 1px 4px rgba(0,0,0,0.08)"
            }}
        >
            <div
                style={{
                    fontSize: "13px",
                    color: "#6b7280",
                    marginBottom: "8px"
                }}
            >
                {title}
            </div>

            <div
                style={{
                    fontSize: "20px",
                    fontWeight: "700"
                }}
            >
                {value}
            </div>
        </div>
    );
};

const InfoBox = ({
    label,
    value
}) => {
    return (
        <div
            style={{
                background: "#f8fafc",
                border:
                    "1px solid #e5e7eb",
                borderRadius: "7px",
                padding: "12px"
            }}
        >
            <div
                style={{
                    fontSize: "11px",
                    color: "#6b7280",
                    marginBottom: "5px",
                    textTransform:
                        "uppercase"
                }}
            >
                {label}
            </div>

            <div
                style={{
                    fontWeight: "600",
                    wordBreak:
                        "break-word"
                }}
            >
                {value}
            </div>
        </div>
    );
};

const AmountBox = ({
    label,
    value,
    strong = false
}) => {
    return (
        <div
            style={{
                background: strong
                    ? "#eff6ff"
                    : "#f8fafc",
                border:
                    "1px solid #e5e7eb",
                borderRadius: "7px",
                padding: "12px"
            }}
        >
            <div
                style={{
                    fontSize: "12px",
                    color: "#6b7280",
                    marginBottom: "5px"
                }}
            >
                {label}
            </div>

            <div
                style={{
                    fontSize: "17px",
                    fontWeight: strong
                        ? "700"
                        : "600"
                }}
            >
                {Number(value || 0).toLocaleString(
                    "en-US",
                    {
                        minimumFractionDigits: 2,
                        maximumFractionDigits: 2
                    }
                )}
            </div>
        </div>
    );
};

const LoadingMessage = ({
    text
}) => {
    return (
        <div
            style={{
                padding: "30px",
                textAlign: "center",
                color: "#666"
            }}
        >
            {text}
        </div>
    );
};

// =============================================================
// Styles
// =============================================================

const cardStyle = {
    background: "#ffffff",
    borderRadius: "10px",
    padding: "20px",
    marginBottom: "20px",
    boxShadow:
        "0 1px 4px rgba(0,0,0,0.08)"
};

const sectionTitle = {
    margin: "0 0 15px 0",
    fontSize: "18px"
};

const labelStyle = {
    display: "block",
    fontSize: "13px",
    fontWeight: "600",
    marginBottom: "6px",
    color: "#374151"
};

const inputStyle = {
    width: "100%",
    boxSizing: "border-box",
    padding: "10px 12px",
    border: "1px solid #d1d5db",
    borderRadius: "6px",
    background: "#ffffff",
    fontSize: "14px",
    outline: "none"
};

const tableStyle = {
    width: "100%",
    borderCollapse: "collapse",
    fontSize: "13px"
};

const buttonStyle = (background) => ({
    background,
    color: "#ffffff",
    border: "none",
    borderRadius: "6px",
    padding: "10px 16px",
    cursor: "pointer",
    fontSize: "13px",
    fontWeight: "600"
});

export default SupplierPayment;