import React, {
  useEffect,
  useMemo,
  useState,
} from "react";

import axios from "axios";

import {
  Plus,
  X,
  Filter,
  Calendar,
  Search,
  ChevronDown,
  ChevronRight,
  Trash2,
  Pencil,
  BarChart3,
  MessageSquare,
  History,
  Wallet,
  IndianRupee,
} from "lucide-react";


// ======================================================
// API
// ======================================================

const API_URL = "http://localhost:5000/api";


// ======================================================
// HELPERS
// ======================================================

const getToday = () => {
  const date = new Date();

  const year = date.getFullYear();

  const month = String(
    date.getMonth() + 1
  ).padStart(2, "0");

  const day = String(
    date.getDate()
  ).padStart(2, "0");

  return `${year}-${month}-${day}`;
};


const getFirstDayOfMonth = () => {
  const date = new Date();

  const year = date.getFullYear();

  const month = String(
    date.getMonth() + 1
  ).padStart(2, "0");

  return `${year}-${month}-01`;
};


const getLastMonthDates = () => {
  const date = new Date();

  const first = new Date(
    date.getFullYear(),
    date.getMonth() - 1,
    1
  );

  const last = new Date(
    date.getFullYear(),
    date.getMonth(),
    0
  );

  return {
    from:
      `${first.getFullYear()}-${String(
        first.getMonth() + 1
      ).padStart(2, "0")}-01`,

    to:
      `${last.getFullYear()}-${String(
        last.getMonth() + 1
      ).padStart(2, "0")}-${String(
        last.getDate()
      ).padStart(2, "0")}`,
  };
};


const formatMoney = (value) => {
  return Number(
    value || 0
  ).toLocaleString(
    "en-LK",
    {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }
  );
};


const formatDate = (value) => {
  if (!value) {
    return "-";
  }

  const date = new Date(value);

  return date.toLocaleDateString(
    "en-GB"
  );
};


// ======================================================
// COMPONENT
// ======================================================

const ExpenseManagement = () => {

  // ====================================================
  // DATA
  // ====================================================

  const [
    expenses,
    setExpenses,
  ] = useState([]);


  // FROM ACCOUNT
  // GET /api/accounts
  // ====================================================

  const [
    fromAccounts,
    setFromAccounts,
  ] = useState([]);


  // TO ACCOUNT
  // GET /api/acc
  // ====================================================

  const [
    toAccounts,
    setToAccounts,
  ] = useState([]);


  // ====================================================
  // SUMMARY
  // ====================================================

  const [
    totalExpenses,
    setTotalExpenses,
  ] = useState(0);


  const [
    expenseCount,
    setExpenseCount,
  ] = useState(0);


  const [
    cashOnHand,
    setCashOnHand,
  ] = useState(0);


  // ====================================================
  // LOADING
  // ====================================================

  const [
    loading,
    setLoading,
  ] = useState(false);


  const [
    saving,
    setSaving,
  ] = useState(false);


  // ====================================================
  // MODAL
  // ====================================================

  const [
    showModal,
    setShowModal,
  ] = useState(false);


  // ====================================================
  // CATEGORY DROPDOWN
  // CATEGORY IS LOADED FROM /acc
  // ====================================================

  const [
    categoryOpen,
    setCategoryOpen,
  ] = useState(false);


  const [
    categorySearch,
    setCategorySearch,
  ] = useState("");


  // ====================================================
  // FILTERS
  // ====================================================

  const [
    filterAccount,
    setFilterAccount,
  ] = useState("");


  const [
    paymentMethod,
    setPaymentMethod,
  ] = useState("All");


  const [
    fromDate,
    setFromDate,
  ] = useState(
    getFirstDayOfMonth()
  );


  const [
    toDate,
    setToDate,
  ] = useState(
    getToday()
  );


  const [
    search,
    setSearch,
  ] = useState("");


  const [
    categoryFilter,
    setCategoryFilter,
  ] = useState("");


  // ====================================================
  // FORM
  // ====================================================

  const [
    form,
    setForm,
  ] = useState({
    expenseDate: getToday(),

    // FROM ACCOUNT
    // /api/accounts
    fromAccountID: "",

    // TO ACCOUNT
    // /api/acc
    toAccountID: "",

    // CATEGORY
    // /api/acc
    category: "",

    description: "",

    referenceNo: "",

    amount: "",
  });


  // ====================================================
  // ERROR
  // ====================================================

  const [
    error,
    setError,
  ] = useState("");


  const [
    success,
    setSuccess,
  ] = useState("");


  // ====================================================
  // LOAD FROM ACCOUNTS
  // API: /api/accounts
  // ====================================================

  const loadFromAccounts = async () => {
  try {
    const response = await axios.get(`${API_URL}/accounts`);

    console.log("FROM ACCOUNTS API:", response.data);

    if (response.data.success) {
      setFromAccounts(response.data.accounts || []);
    } else {
      setFromAccounts([]);
      setError(
        response.data.message ||
        "Unable to load from accounts"
      );
    }
  } catch (err) {
    console.error("Load from accounts error:", err);

    setFromAccounts([]);

    setError(
      err.response?.data?.message ||
      "Unable to load from accounts"
    );
  }
};

  // ====================================================
  // LOAD TO ACCOUNTS
  // API: /api/acc
  //
  // ALSO USED AS EXPENSE CATEGORY SOURCE
  // ====================================================

  const loadToAccounts =
    async () => {

      try {

        const response =
          await axios.get(
            `${API_URL}/acc`
          );


        if (
          response.data.success
        ) {

          setToAccounts(
            response.data.data || []
          );

        } else {

          setToAccounts([]);

        }

      } catch (err) {

        console.error(
          "Load to accounts error:",
          err
        );

        setError(
          err.response?.data?.message ||
          "Unable to load accounts"
        );

      }
    };


  // ====================================================
  // LOAD EXPENSES
  // ====================================================

  const loadExpenses =
    async () => {

      try {

        setLoading(true);

        const params = {};


        if (fromDate) {
          params.fromDate =
            fromDate;
        }


        if (toDate) {
          params.toDate =
            toDate;
        }


        if (filterAccount) {
          params.accountID =
            filterAccount;
        }


        if (categoryFilter) {
          params.category =
            categoryFilter;
        }


        if (search.trim()) {
          params.search =
            search.trim();
        }


        const response =
          await axios.get(
            `${API_URL}/expenses`,
            {
              params,
            }
          );


        if (
          response.data.success
        ) {

          setExpenses(
            response.data.data || []
          );

        } else {

          setExpenses([]);

        }

      } catch (err) {

        console.error(err);

        setError(
          err.response?.data?.message ||
          "Unable to load expenses"
        );

      } finally {

        setLoading(false);

      }
    };


  // ====================================================
  // LOAD SUMMARY
  // ====================================================

  const loadSummary =
    async () => {

      try {

        const params = {};


        if (fromDate) {
          params.fromDate =
            fromDate;
        }


        if (toDate) {
          params.toDate =
            toDate;
        }


        if (filterAccount) {
          params.accountID =
            filterAccount;
        }


        const [
          summaryResponse,
          cashResponse,
        ] =
          await Promise.all([

            axios.get(
              `${API_URL}/expenses/summary`,
              {
                params,
              }
            ),

            axios.get(
              `${API_URL}/expenses/cash-on-hand`,
              {
                params: {
                  accountID:
                    filterAccount ||
                    undefined,
                },
              }
            ),

          ]);


        if (
          summaryResponse.data.success
        ) {

          setTotalExpenses(
            Number(
              summaryResponse.data.data
                ?.TotalExpenses || 0
            )
          );


          setExpenseCount(
            Number(
              summaryResponse.data.data
                ?.ExpenseCount || 0
            )
          );

        }


        if (
          cashResponse.data.success
        ) {

          setCashOnHand(
            Number(
              cashResponse.data.cashOnHand ||
              0
            )
          );

        }

      } catch (err) {

        console.error(
          "Summary error:",
          err
        );

      }
    };


  // ====================================================
  // INITIAL LOAD
  // ====================================================

  useEffect(() => {

    loadFromAccounts();

    loadToAccounts();

  }, []);


  // ====================================================
  // LOAD WHEN FILTER CHANGES
  // ====================================================

  useEffect(() => {

    loadExpenses();

    loadSummary();

  }, [
    fromDate,
    toDate,
    filterAccount,
    categoryFilter,
  ]);


  // ====================================================
  // FILTERED LOCAL SEARCH
  // ====================================================

  const visibleExpenses =
    useMemo(() => {

      if (!search.trim()) {
        return expenses;
      }

      const value =
        search
          .toLowerCase()
          .trim();


      return expenses.filter(
        (expense) =>
          String(
            expense.Description || ""
          )
            .toLowerCase()
            .includes(value) ||

          String(
            expense.Category || ""
          )
            .toLowerCase()
            .includes(value) ||

          String(
            expense.ReferenceNo || ""
          )
            .toLowerCase()
            .includes(value)
      );

    }, [
      expenses,
      search,
    ]);


  // ====================================================
  // CATEGORY LIST FROM /acc
  // ====================================================

  const categoryOptions =
    useMemo(() => {

      const unique = new Map();

      toAccounts.forEach(
        (account) => {

          const category =
            account.AccountName ||
            account.Category ||
            account.Name;

          if (
            category &&
            String(category).trim()
          ) {

            const value =
              String(category).trim();

            unique.set(
              value,
              value
            );

          }

        }
      );

      return Array.from(
        unique.values()
      );

    }, [
      toAccounts,
    ]);


  // ====================================================
  // FILTER CATEGORY SEARCH
  // ====================================================

  const filteredCategories =
    categoryOptions.filter(
      (category) => {

        const searchValue =
          categorySearch
            .toLowerCase()
            .trim();


        if (!searchValue) {
          return true;
        }


        return category
          .toLowerCase()
          .includes(searchValue);

      }
    );


  // ====================================================
  // MONTH BUTTON
  // ====================================================

  const selectThisMonth =
    () => {

      setFromDate(
        getFirstDayOfMonth()
      );

      setToDate(
        getToday()
      );

    };


  const selectLastMonth =
    () => {

      const dates =
        getLastMonthDates();

      setFromDate(
        dates.from
      );

      setToDate(
        dates.to
      );

    };


  const selectAllTime =
    () => {

      setFromDate("");

      setToDate("");

    };


  // ====================================================
  // OPEN MODAL
  // ====================================================

  const openAddExpense =
    () => {

      setError("");

      setSuccess("");

      setForm({

        expenseDate:
          getToday(),

        fromAccountID:
          fromAccounts[0]
            ?.AccountID ||
          "",

        toAccountID:
          toAccounts[0]
            ?.AccountID ||
          "",

        category:
          "",

        description:
          "",

        referenceNo:
          "",

        amount:
          "",

      });

      setCategoryOpen(false);

      setCategorySearch("");

      setShowModal(true);
    };


  // ====================================================
  // CLOSE MODAL
  // ====================================================

  const closeModal =
    () => {

      if (saving) {
        return;
      }

      setShowModal(false);

      setCategoryOpen(false);

    };


  // ====================================================
  // FORM CHANGE
  // ====================================================

  const updateForm =
    (field, value) => {

      setForm(
        (previous) => ({
          ...previous,
          [field]: value,
        })
      );

    };


  // ====================================================
  // SELECT CATEGORY
  // ====================================================

  const selectCategory =
    (category) => {

      updateForm(
        "category",
        category
      );

      setCategoryOpen(false);

      setCategorySearch("");

    };


  // ====================================================
  // SAVE EXPENSE
  // ====================================================

 const saveExpense = async (event) => {
  event.preventDefault();

  setError("");
  setSuccess("");

  // ==========================================
  // CATEGORY
  // ==========================================


  // ==========================================
  // FROM ACCOUNT
  // faaccountId = DEBIT
  // ==========================================

  if (!form.fromAccountID) {
    setError("Please select a from account.");
    return;
  }

  // ==========================================
  // TO ACCOUNT
  // accountId = CREDIT
  // ==========================================

  if (!form.toAccountID) {
    setError("Please select a to account.");
    return;
  }

  // ==========================================
  // SAME ACCOUNT
  // ==========================================

  if (
    String(form.fromAccountID) ===
    String(form.toAccountID)
  ) {
    setError(
      "From Account and To Account cannot be the same."
    );
    return;
  }

  // ==========================================
  // AMOUNT
  // ==========================================

  const amount = Number(form.amount);

  if (!Number.isFinite(amount) || amount <= 0) {
    setError("Please enter a valid expense amount.");
    return;
  }

  // ==========================================
  // DATE
  // ==========================================

  if (!form.expenseDate) {
    setError("Expense date is required.");
    return;
  }

  try {
    setSaving(true);

    // ==========================================
    // BACKEND PAYLOAD
    // ==========================================

    const payload = {
      // accountId = CREDIT
      accountId: Number(form.toAccountID),

      // faccountId = DEBIT
      faccountId: Number(form.fromAccountID),

      amount: amount,

      category: form.category,

      description:
        form.description.trim() || null,

      referenceNo:
        form.referenceNo.trim() || null,

      locationId: null,

      sessionId: null,

      createdBy: "Admin",
    };

    console.log(
      "CREATE EXPENSE PAYLOAD:",
      payload
    );

    const response = await axios.post(
      `${API_URL}/cash-transactions/expense`,
      payload
    );

    if (response.data.success) {
      setSuccess(
        "Expense recorded successfully."
      );

      setShowModal(false);

      setForm({
        expenseDate: getToday(),
        fromAccountID: "",
        toAccountID: "",
        category: "",
        description: "",
        referenceNo: "",
        amount: "",
      });

      await loadExpenses();
      await loadSummary();
    } else {
      setError(
        response.data.message ||
        "Unable to save expense."
      );
    }
  } catch (err) {
    console.error(
      "Save expense error:",
      err
    );

    setError(
      err.response?.data?.message ||
      "Unable to save expense."
    );
  } finally {
    setSaving(false);
  }
};

  // ====================================================
  // DELETE EXPENSE
  // ====================================================

  const deleteExpense =
    async (transactionID) => {

      const confirmed =
        window.confirm(
          "Are you sure you want to delete this expense?"
        );


      if (!confirmed) {
        return;
      }


      try {

        await axios.delete(
          `${API_URL}/expenses/${transactionID}`
        );


        await loadExpenses();

        await loadSummary();


        setSuccess(
          "Expense deleted successfully."
        );

      } catch (err) {

        console.error(err);

        setError(
          err.response?.data?.message ||
          "Unable to delete expense."
        );

      }

    };


  // ====================================================
  // CLEAR FILTERS
  // ====================================================

  const clearFilters =
    () => {

      setFilterAccount("");

      setPaymentMethod("All");

      setCategoryFilter("");

      setSearch("");

      setFromDate(
        getFirstDayOfMonth()
      );

      setToDate(
        getToday()
      );

    };


  // ====================================================
  // RENDER
  // ====================================================

  return (

    <div className="
      min-h-screen
      bg-white
      px-5
      py-5
      md:px-9
    ">

      <div className="
        mx-auto
        max-w-[1220px]
      ">


        {/* =================================================
            HEADER
        ================================================= */}

        <div className="
          flex
          flex-col
          gap-4
          md:flex-row
          md:items-start
          md:justify-between
        ">

          <div>

            <h1 className="
              text-3xl
              font-bold
              text-slate-950
            ">
              Expense Management
            </h1>


            <p className="
              mt-1
              text-base
              text-slate-600
            ">

              {fromDate && toDate
                ? `Showing: ${formatDate(
                    fromDate
                  )} - ${formatDate(
                    toDate
                  )}`
                : "Showing: All dates"}

            </p>

          </div>


          <button
            type="button"
            onClick={
              openAddExpense
            }
            className="
              flex
              items-center
              justify-center
              gap-2
              rounded-xl
              bg-amber-500
              px-5
              py-3
              font-semibold
              text-white
              shadow-sm
              hover:bg-amber-600
            "
          >

            <Plus size={18} />

            Add Expense

          </button>

        </div>


        {/* =================================================
            DATE QUICK FILTERS
        ================================================= */}

        <div className="
          mt-6
          flex
          flex-wrap
          gap-2
        ">

          <button
            type="button"
            onClick={
              selectThisMonth
            }
            className="
              rounded-xl
              bg-amber-500
              px-4
              py-2.5
              text-sm
              font-semibold
              text-white
            "
          >
            This Month
          </button>


          <button
            type="button"
            onClick={
              selectLastMonth
            }
            className="
              rounded-xl
              border
              border-slate-200
              px-4
              py-2.5
              text-sm
              hover:bg-slate-50
            "
          >
            Last Month
          </button>


          <button
            type="button"
            onClick={
              selectAllTime
            }
            className="
              rounded-xl
              border
              border-slate-200
              px-4
              py-2.5
              text-sm
              hover:bg-slate-50
            "
          >
            All Time
          </button>

        </div>


        {/* =================================================
            MESSAGES
        ================================================= */}

        {success && (

          <div className="
            mt-5
            rounded-xl
            border
            border-green-200
            bg-green-50
            px-4
            py-3
            text-sm
            text-green-700
          ">
            {success}
          </div>

        )}


        {error && !showModal && (

          <div className="
            mt-5
            rounded-xl
            border
            border-red-200
            bg-red-50
            px-4
            py-3
            text-sm
            text-red-700
          ">
            {error}
          </div>

        )}


        {/* =================================================
            SUMMARY CARDS
        ================================================= */}

        <div className="
          mt-6
          grid
          grid-cols-1
          gap-4
          md:grid-cols-2
        ">


          {/* FILTERED EXPENSES */}

          <div className="
            rounded-2xl
            border
            border-slate-200
            bg-white
            p-6
            shadow-sm
          ">

            <div className="
              flex
              items-start
              justify-between
            ">

              <div>

                <p className="
                  text-sm
                  font-medium
                  text-slate-700
                ">
                  Filtered Expenses
                </p>


                <p className="
                  mt-2
                  text-2xl
                  font-bold
                  text-slate-950
                ">
                  Rs.{" "}
                  {formatMoney(
                    totalExpenses
                  )}
                </p>


                <p className="
                  mt-1
                  text-sm
                  text-slate-500
                ">
                  {expenseCount} expenses
                </p>

              </div>


              <div className="
                text-slate-500
              ">
                <IndianRupee size={16} />
              </div>

            </div>

          </div>


          {/* CASH ON HAND */}

          <div className="
            rounded-2xl
            border
            border-slate-200
            bg-white
            p-6
            shadow-sm
          ">

            <div className="
              flex
              items-start
              justify-between
            ">

              <div>

                <p className="
                  text-sm
                  font-medium
                  text-slate-700
                ">
                  Cash on Hand
                </p>


                <p className="
                  mt-2
                  text-2xl
                  font-bold
                  text-slate-950
                ">
                  Rs.{" "}
                  {formatMoney(
                    cashOnHand
                  )}
                </p>


                <p className="
                  mt-1
                  text-xs
                  font-medium
                  uppercase
                  text-slate-500
                ">
                  CASH ON HAND
                </p>

              </div>


              <Wallet
                size={17}
                className="text-slate-500"
              />

            </div>

          </div>

        </div>


        {/* =================================================
            EXPENSE HISTORY
        ================================================= */}

        <div className="
          mt-6
          rounded-2xl
          border
          border-slate-200
          bg-white
          p-5
          shadow-sm
          md:p-6
        ">


          {/* HISTORY HEADER */}

          <div className="
            flex
            flex-col
            gap-4
            xl:flex-row
            xl:items-start
            xl:justify-between
          ">

            <div>

              <h2 className="
                text-2xl
                font-bold
                text-slate-950
              ">
                Expense History
              </h2>


              <p className="
                mt-1
                text-sm
                text-slate-600
              ">
                View and filter expense transactions
              </p>

            </div>


            <div className="
              flex
              flex-wrap
              gap-2
            ">

              <button
                type="button"
                className="
                  flex
                  items-center
                  gap-2
                  rounded-lg
                  border
                  border-slate-200
                  px-3
                  py-2
                  text-sm
                  hover:bg-slate-50
                "
              >
                <Filter size={16} />
              </button>


              <button
                type="button"
                onClick={
                  clearFilters
                }
                className="
                  flex
                  items-center
                  gap-2
                  rounded-lg
                  border
                  border-slate-200
                  px-3
                  py-2
                  text-sm
                  hover:bg-slate-50
                "
              >
                <X size={15} />
                Clear Filters
              </button>


              <button
                type="button"
                className="
                  flex
                  items-center
                  gap-2
                  rounded-lg
                  border
                  border-slate-200
                  px-3
                  py-2
                  text-sm
                  hover:bg-slate-50
                "
              >
                <BarChart3 size={16} />
                Category Wise
              </button>


              <button
                type="button"
                className="
                  flex
                  items-center
                  gap-2
                  rounded-lg
                  border
                  border-slate-200
                  px-3
                  py-2
                  text-sm
                  hover:bg-slate-50
                "
              >
                <Calendar size={16} />
                Date Wise
              </button>


              <button
                type="button"
                className="
                  flex
                  items-center
                  gap-2
                  rounded-lg
                  border
                  border-slate-200
                  px-3
                  py-2
                  text-sm
                  hover:bg-slate-50
                "
              >
                <MessageSquare size={16} />
                Test SMS
              </button>


              <button
                type="button"
                className="
                  flex
                  items-center
                  gap-2
                  rounded-lg
                  border
                  border-slate-200
                  px-3
                  py-2
                  text-sm
                  hover:bg-slate-50
                "
              >
                <History size={16} />
                Modifications
              </button>

            </div>

          </div>


          {/* =================================================
              SEARCH
          ================================================= */}

          <div className="
            relative
            mt-5
          ">

            <Search
              size={17}
              className="
                absolute
                left-3
                top-3
                text-slate-400
              "
            />


            <input
              type="text"
              value={search}
              onChange={(e) =>
                setSearch(
                  e.target.value
                )
              }
              placeholder="
                Search description, category or reference...
              "
              className="
                w-full
                rounded-xl
                border
                border-slate-200
                py-2.5
                pl-10
                pr-3
                outline-none
                focus:border-amber-400
              "
            />

          </div>


          {/* =================================================
              FILTERS
          ================================================= */}

          <div className="
            mt-4
            grid
            grid-cols-1
            gap-4
            md:grid-cols-2
            xl:grid-cols-4
          ">


            {/* ACCOUNT */}

            <div>

              <label className="
                mb-2
                block
                text-sm
                font-medium
              ">
                Account
              </label>


              <div className="relative">

                <select
                  value={
                    filterAccount
                  }
                  onChange={(e) =>
                    setFilterAccount(
                      e.target.value
                    )
                  }
                  className="
                    w-full
                    appearance-none
                    rounded-xl
                    border
                    border-slate-200
                    bg-white
                    px-3
                    py-2.5
                    outline-none
                  "
                >

                  <option value="">
                    All accounts
                  </option>


                  {toAccounts.map(
                    (account) => (

                      <option
                        key={
                          account.AccountID
                        }
                        value={
                          account.AccountID
                        }
                      >

                        {
                          account.AccountName
                        }

                      </option>

                    )
                  )}

                </select>


                <ChevronDown
                  size={17}
                  className="
                    pointer-events-none
                    absolute
                    right-3
                    top-3.5
                    text-slate-400
                  "
                />

              </div>

            </div>


            {/* PAYMENT METHOD */}

            <div>

              <label className="
                mb-2
                block
                text-sm
                font-medium
              ">
                Payment Method
              </label>


              <select
                value={
                  paymentMethod
                }
                onChange={(e) =>
                  setPaymentMethod(
                    e.target.value
                  )
                }
                className="
                  w-full
                  rounded-xl
                  border
                  border-slate-200
                  bg-white
                  px-3
                  py-2.5
                  outline-none
                "
              >

                <option value="All">
                  All methods
                </option>

                <option value="Cash">
                  Cash
                </option>

                <option value="Bank">
                  Bank
                </option>

                <option value="Card">
                  Card
                </option>

              </select>

            </div>


            {/* FROM DATE */}

            <div>

              <label className="
                mb-2
                block
                text-sm
                font-medium
              ">
                From Date
              </label>


              <input
                type="date"
                value={fromDate}
                onChange={(e) =>
                  setFromDate(
                    e.target.value
                  )
                }
                className="
                  w-full
                  rounded-xl
                  border
                  border-slate-200
                  px-3
                  py-2.5
                  outline-none
                "
              />

            </div>


            {/* TO DATE */}

            <div>

              <label className="
                mb-2
                block
                text-sm
                font-medium
              ">
                To Date
              </label>


              <input
                type="date"
                value={toDate}
                onChange={(e) =>
                  setToDate(
                    e.target.value
                  )
                }
                className="
                  w-full
                  rounded-xl
                  border
                  border-slate-200
                  px-3
                  py-2.5
                  outline-none
                "
              />

            </div>

          </div>


          {/* CATEGORY FILTER */}

          <div className="
            mt-4
            max-w-md
          ">

            <label className="
              mb-2
              block
              text-sm
              font-medium
            ">
              Expense Category
            </label>


            <select
              value={
                categoryFilter
              }
              onChange={(e) =>
                setCategoryFilter(
                  e.target.value
                )
              }
              className="
                w-full
                rounded-xl
                border
                border-slate-200
                bg-white
                px-3
                py-2.5
                outline-none
              "
            >

              <option value="">
                All categories
              </option>


              {categoryOptions.map(
                (category) => (

                  <option
                    key={category}
                    value={category}
                  >
                    {category}
                  </option>

                )
              )}

            </select>

          </div>


          {/* =================================================
              TABLE
          ================================================= */}

          <div className="
            mt-6
            overflow-x-auto
          ">

            <table className="
              min-w-[1050px]
              w-full
              text-sm
            ">

              <thead>

                <tr className="
                  border-b
                  border-slate-200
                  text-slate-600
                ">

                  <th className="
                    px-4
                    py-3
                    text-left
                    font-medium
                  ">
                    Date
                  </th>


                  <th className="
                    px-4
                    py-3
                    text-left
                    font-medium
                  ">
                    Description
                  </th>


                  <th className="
                    px-4
                    py-3
                    text-left
                    font-medium
                  ">
                    Expense Category
                  </th>


                  <th className="
                    px-4
                    py-3
                    text-left
                    font-medium
                  ">
                    Type
                  </th>


                  <th className="
                    px-4
                    py-3
                    text-left
                    font-medium
                  ">
                    Payment Method
                  </th>


                  <th className="
                    px-4
                    py-3
                    text-right
                    font-medium
                  ">
                    Amount
                  </th>


                  <th className="
                    px-4
                    py-3
                    text-center
                    font-medium
                  ">
                    Actions
                  </th>

                </tr>

              </thead>


              <tbody>

                {visibleExpenses.map(
                  (expense) => (

                    <tr
                      key={
                        expense.TransactionID
                      }
                      className="
                        border-b
                        border-slate-100
                        hover:bg-slate-50
                      "
                    >

                      <td className="
                        whitespace-nowrap
                        px-4
                        py-4
                      ">
                        {formatDate(
                          expense.TransactionDate
                        )}
                      </td>


                      <td className="px-4 py-4">

                        <div className="
                          font-medium
                          text-slate-900
                        ">
                          {
                            expense.Description ||
                            "-"
                          }
                        </div>


                        {expense.ReferenceNo && (

                          <div className="
                            mt-1
                            text-xs
                            text-slate-500
                          ">

                            Ref:
                            {" "}
                            {
                              expense.ReferenceNo
                            }

                          </div>

                        )}

                      </td>


                      <td className="
                        px-4
                        py-4
                      ">

                        <span className="
                          rounded-lg
                          bg-amber-50
                          px-2.5
                          py-1
                          text-xs
                          font-medium
                          text-amber-700
                        ">

                          {
                            expense.Category
                          }

                        </span>

                      </td>


                      <td className="
                        px-4
                        py-4
                      ">

                        <span className="
                          rounded-lg
                          bg-red-50
                          px-2.5
                          py-1
                          text-xs
                          font-medium
                          text-red-600
                        ">
                          Expense
                        </span>

                      </td>


                      <td className="
                        px-4
                        py-4
                      ">

                        {expense.AccountName ||
                          expense.ToAccountName ||
                          "Cash"}

                      </td>


                      <td className="
                        px-4
                        py-4
                        text-right
                        font-semibold
                        text-red-600
                      ">

                        Rs.{" "}
                        {formatMoney(
                          expense.amount
                        )}

                      </td>


                      <td className="
                        px-4
                        py-4
                      ">

                        <div className="
                          flex
                          justify-center
                          gap-2
                        ">

                          <button
                            type="button"
                            title="Edit"
                            className="
                              rounded-lg
                              border
                              border-slate-200
                              p-2
                              hover:bg-slate-100
                            "
                          >

                            <Pencil
                              size={15}
                            />

                          </button>


                          <button
                            type="button"
                            title="Delete"
                            onClick={() =>
                              deleteExpense(
                                expense.TransactionID
                              )
                            }
                            className="
                              rounded-lg
                              border
                              border-red-100
                              p-2
                              text-red-500
                              hover:bg-red-50
                            "
                          >

                            <Trash2
                              size={15}
                            />

                          </button>

                        </div>

                      </td>

                    </tr>

                  )
                )}


                {!loading &&
                  visibleExpenses.length ===
                    0 && (

                    <tr>

                      <td
                        colSpan="7"
                        className="
                          px-5
                          py-14
                          text-center
                          text-slate-500
                        "
                      >

                        No expense transactions found.

                      </td>

                    </tr>

                  )}


                {loading && (

                  <tr>

                    <td
                      colSpan="7"
                      className="
                        px-5
                        py-14
                        text-center
                        text-slate-500
                      "
                    >

                      Loading expenses...

                    </td>

                  </tr>

                )}

              </tbody>

            </table>

          </div>

        </div>

      </div>


      {/* =====================================================
          ADD EXPENSE MODAL
      ===================================================== */}

      {showModal && (

        <div className="
          fixed
          inset-0
          z-[9999]
          flex
          items-center
          justify-center
          bg-black/60
          p-4
        ">


          <div className="
            flex
            max-h-[90vh]
            w-full
            max-w-[675px]
            flex-col
            overflow-hidden
            rounded-2xl
            bg-white
            shadow-2xl
          ">


            {/* =================================================
                MODAL HEADER
            ================================================= */}

            <div className="
              flex
              items-start
              justify-between
              border-b
              border-slate-100
              px-6
              py-5
            ">

              <div>

                <h2 className="
                  text-xl
                  font-semibold
                  text-slate-900
                ">
                  Record New Expense
                </h2>


                <p className="
                  mt-1
                  text-sm
                  text-slate-500
                ">
                  Add a new expense transaction
                </p>

              </div>


              <button
                type="button"
                onClick={
                  closeModal
                }
                className="
                  rounded-full
                  p-1.5
                  text-slate-500
                  hover:bg-slate-100
                "
              >

                <X size={20} />

              </button>

            </div>


            {/* =================================================
                FORM BODY
            ================================================= */}

            <form
              onSubmit={
                saveExpense
              }
              className="
                overflow-y-auto
                px-6
                py-5
              "
            >





              <label className="
                mt-5
                block
                text-sm
                font-medium
              ">

                From Account

                <span className="
                  ml-1
                  text-red-500
                ">
                  *
                </span>

              </label>


              <select
                value={
                  form.fromAccountID
                }
                onChange={(e) =>
                  updateForm(
                    "fromAccountID",
                    e.target.value
                  )
                }
                className="
                  mt-2
                  w-full
                  rounded-xl
                  border
                  border-slate-200
                  bg-white
                  px-4
                  py-3
                  outline-none
                  focus:border-amber-400
                "
              >

                <option value="">
                  Select from account
                </option>


                {fromAccounts.map(
                  (account) => (

                    <option
                      key={
                        account.id
                      }
                      value={
                        account.id
                      }
                    >

                      {
                        account.name
                      }

                      {account.AccountNumber
                        ? ` - ${account.AccountNumber}`
                        : ""}

                    </option>

                  )
                )}

              </select>





              <label className="
                mt-5
                block
                text-sm
                font-medium
              ">

                To Account

                <span className="
                  ml-1
                  text-red-500
                ">
                  *
                </span>

              </label>


              <select
                value={
                  form.toAccountID
                }
                onChange={(e) =>
                  updateForm(
                    "toAccountID",
                    e.target.value
                  )
                }
                className="
                  mt-2
                  w-full
                  rounded-xl
                  border
                  border-slate-200
                  bg-white
                  px-4
                  py-3
                  outline-none
                  focus:border-amber-400
                "
              >

                <option value="">
                  Select to account
                </option>


                {toAccounts.map(
                  (account) => (

                    <option
                      key={
                        account.AccountID
                      }
                      value={
                        account.AccountID
                      }
                    >

                      {
                        account.AccountName
                      }

                      {account.AccountNumber
                        ? ` - ${account.AccountNumber}`
                        : ""}

                    </option>

                  )
                )}

              </select>


            



              {/* =================================================
                  AMOUNT
              ================================================= */}

              <label className="
                mt-5
                block
                text-sm
                font-medium
              ">

                Amount

                <span className="
                  ml-1
                  text-red-500
                ">
                  *
                </span>

              </label>


              <input
                type="number"
                min="0.01"
                step="0.01"
                value={
                  form.amount
                }
                onChange={(e) =>
                  updateForm(
                    "amount",
                    e.target.value
                  )
                }
                placeholder="0.00"
                className="
                  mt-2
                  w-full
                  rounded-xl
                  border
                  border-slate-200
                  px-4
                  py-3
                  outline-none
                  focus:border-amber-400
                "
              />




              {/* =================================================
                  DESCRIPTION
              ================================================= */}

              <label className="
                mt-5
                block
                text-sm
                font-medium
              ">
                Expense Description
              </label>


              <textarea
                rows="3"
                value={
                  form.description
                }
                onChange={(e) =>
                  updateForm(
                    "description",
                    e.target.value
                  )
                }
                placeholder="Enter expense description"
                className="
                  mt-2
                  w-full
                  resize-none
                  rounded-xl
                  border
                  border-slate-200
                  px-4
                  py-3
                  outline-none
                  focus:border-amber-400
                "
              />


              {/* =================================================
                  REFERENCE
              ================================================= */}

              <label className="
                mt-5
                block
                text-sm
                font-medium
              ">

                Reference Number

                <span className="
                  ml-1
                  font-normal
                  text-slate-400
                ">
                  (Optional)
                </span>

              </label>


              <input
                type="text"
                value={
                  form.referenceNo
                }
                onChange={(e) =>
                  updateForm(
                    "referenceNo",
                    e.target.value
                  )
                }
                placeholder="Enter reference number"
                className="
                  mt-2
                  w-full
                  rounded-xl
                  border
                  border-slate-200
                  px-4
                  py-3
                  outline-none
                  focus:border-amber-400
                "
              />


              {/* =================================================
                  EXPENSE DATE
              ================================================= */}

              <label className="
                mt-5
                block
                text-sm
                font-medium
              ">
                Expense Date
              </label>


              <input
                type="date"
                value={
                  form.expenseDate
                }
                onChange={(e) =>
                  updateForm(
                    "expenseDate",
                    e.target.value
                  )
                }
                className="
                  mt-2
                  w-full
                  rounded-xl
                  border
                  border-slate-200
                  px-4
                  py-3
                  outline-none
                  focus:border-amber-400
                "
              />


              {/* =================================================
                  ERROR
              ================================================= */}

              {error && (

                <div className="
                  mt-4
                  rounded-xl
                  border
                  border-red-200
                  bg-red-50
                  px-4
                  py-3
                  text-sm
                  text-red-600
                ">

                  {error}

                </div>

              )}


              {/* =================================================
                  BUTTONS
              ================================================= */}

              <div className="
                mt-6
                flex
                justify-end
                gap-3
                border-t
                border-slate-100
                pt-5
              ">

                <button
                  type="button"
                  onClick={
                    closeModal
                  }
                  disabled={
                    saving
                  }
                  className="
                    rounded-xl
                    border
                    border-slate-200
                    px-5
                    py-3
                    font-medium
                    hover:bg-slate-50
                    disabled:opacity-50
                  "
                >
                  Cancel
                </button>


                <button
                  type="submit"
                  disabled={
                    saving
                  }
                  className="
                    rounded-xl
                    bg-amber-500
                    px-6
                    py-3
                    font-semibold
                    text-white
                    hover:bg-amber-600
                    disabled:opacity-50
                  "
                >

                  {saving
                    ? "Saving..."
                    : "Record Expense"}

                </button>

              </div>

            </form>

          </div>

        </div>

      )}

    </div>
  );
};


export default ExpenseManagement;