import React, {
    useEffect,
    useMemo,
    useState
} from "react";

import axios from "axios";

import {
    Search,
    RotateCcw,
    Save,
    Trash2,
    Plus,
    RefreshCw
} from "lucide-react";

const API_URL = "http://localhost:5000";

const EMPTY_ITEM = {
    ProductCode: "",
    ProductName: "",
    ReceivedQty: 0,
    AlreadyReturnedQty: 0,
    ReturnableQty: 0,
    ReturnQty: 0,
    CostPrice: 0,
    FixedDiscountPercentage: 0
};

function PurchaseReturn() {

    const [prn, setPrn] = useState({
        prnno: "",
        prndate:
            new Date()
                .toISOString()
                .split("T")[0],

        grnno: "",
        pono: "",

        suppliercode: "",
        suppliername: "",

        location: "",

        referenceno: "",

        remark: ""
    });

    const [items, setItems] =
        useState([]);

    const [loading, setLoading] =
        useState(false);

    const [saving, setSaving] =
        useState(false);

    const [message, setMessage] =
        useState("");

    const [errorMessage, setErrorMessage] =
        useState("");

    const [locations, setLocations] =
        useState([]);

    const [grnQuery, setGrnQuery] =
        useState("");

    const [showGrnSearch, setShowGrnSearch] =
        useState(false);

    // ==========================================
    // TOTALS
    // ==========================================

    const totals = useMemo(() => {

        let qty = 0;
        let gross = 0;
        let discount = 0;
        let net = 0;

        items.forEach(item => {

            const returnQty =
                Number(item.ReturnQty || 0);

            const cost =
                Number(item.CostPrice || 0);

            const disc =
                Number(
                    item.FixedDiscountPercentage ||
                    0
                );

            const itemGross =
                returnQty * cost;

            const itemDiscount =
                itemGross * disc / 100;

            const itemNet =
                itemGross - itemDiscount;

            qty += returnQty;
            gross += itemGross;
            discount += itemDiscount;
            net += itemNet;
        });

        return {
            qty,
            gross,
            discount,
            net
        };

    }, [items]);

    // ==========================================
    // LOAD PRN NUMBER
    // ==========================================

    const loadPRNNumber = async () => {

        try {

            const response =
                await axios.get(
                    `${API_URL}/prnnumber`
                );

            if (
                response.data?.success
            ) {

                setPrn(prev => ({
                    ...prev,

                    prnno:
                        response.data.prnno
                }));
            }

        } catch (error) {

            console.error(
                "PRN NUMBER ERROR:",
                error
            );
        }
    };

    // ==========================================
    // LOAD LOCATIONS
    // ==========================================

    const loadLocations = async () => {

        try {

            const response =
                await axios.get(
                    `${API_URL}/locations`
                );

            const data =
                Array.isArray(
                    response.data
                )
                    ? response.data
                    : response.data?.locations ||
                      response.data?.data ||
                      [];

            setLocations(data);

        } catch (error) {

            console.error(
                "LOCATION ERROR:",
                error
            );
        }
    };

    useEffect(() => {

        loadPRNNumber();

        loadLocations();

    }, []);

    // ==========================================
    // HANDLE HEADER
    // ==========================================

    const handleChange = e => {

        const {
            name,
            value
        } = e.target;

        setPrn(prev => ({
            ...prev,
            [name]: value
        }));
    };

    // ==========================================
    // RECALL GRN
    // ==========================================

    const recallGRN = async () => {

        const grnno =
            String(
                prn.grnno || ""
            ).trim();

        if (!grnno) {

            setErrorMessage(
                "Please enter GRN Number."
            );

            return;
        }

        try {

            setLoading(true);

            setMessage("");
            setErrorMessage("");

            const response =
                await axios.get(
                    `${API_URL}/api/prn/recall-grn/${encodeURIComponent(
                        grnno
                    )}`
                );

            const data =
                response.data;

            if (!data?.success) {

                setErrorMessage(
                    data?.message ||
                    "Unable to recall GRN."
                );

                return;
            }

            setPrn(prev => ({
                ...prev,

                grnno:
                    data.grn.GRNNo ||
                    grnno,

                pono:
                    data.grn.PONo ||
                    "",

                suppliercode:
                    data.grn.SupplierCode ||
                    "",

                suppliername:
                    data.grn.SupplierName ||
                    "",

                location:
                    String(
                        data.grn.Location ||
                        ""
                    ),

                referenceno:
                    data.grn.ReferenceNo ||
                    "",

                remark:
                    data.grn.Remark ||
                    ""
            }));

            const recalledItems =
                (data.items || [])
                    .map(item => ({

                        ...EMPTY_ITEM,

                        ProductCode:
                            item.ProductCode ||
                            "",

                        ProductName:
                            item.ProductName ||
                            "",

                        ReceivedQty:
                            Number(
                                item.ReceivedQty ||
                                0
                            ),

                        AlreadyReturnedQty:
                            Number(
                                item.AlreadyReturnedQty ||
                                0
                            ),

                        ReturnableQty:
                            Number(
                                item.ReturnableQty ||
                                0
                            ),

                        ReturnQty: 0,

                        CostPrice:
                            Number(
                                item.CostPrice ||
                                0
                            ),

                        FixedDiscountPercentage:
                            Number(
                                item.FixedDiscountPercentage ||
                                0
                            )
                    }));

            setItems(
                recalledItems
            );

            setMessage(
                `GRN ${grnno} recalled successfully.`
            );

        } catch (error) {

            console.error(
                "GRN RECALL ERROR:",
                error.response?.data ||
                error
            );

            setErrorMessage(
                error.response?.data?.message ||
                error.message ||
                "Unable to recall GRN."
            );

        } finally {

            setLoading(false);
        }
    };

    // ==========================================
    // UPDATE RETURN QTY
    // ==========================================

    const updateReturnQty = (
        index,
        value
    ) => {

        let qty =
            Number(value || 0);

        const max =
            Number(
                items[index]
                    ?.ReturnableQty || 0
            );

        if (qty < 0) {
            qty = 0;
        }

        if (qty > max) {
            qty = max;
        }

        setItems(prev =>
            prev.map(
                (item, i) =>
                    i === index
                        ? {
                            ...item,
                            ReturnQty:
                                qty
                        }
                        : item
            )
        );
    };

    // ==========================================
    // REMOVE ITEM
    // ==========================================

    const removeItem = index => {

        setItems(prev =>
            prev.filter(
                (_, i) =>
                    i !== index
            )
        );
    };

    // ==========================================
    // SAVE PRN
    // ==========================================

    const savePRN = async () => {

        setMessage("");
        setErrorMessage("");

        if (!prn.prnno) {

            setErrorMessage(
                "PRN Number is required."
            );

            return;
        }

        if (!prn.grnno) {

            setErrorMessage(
                "GRN Number is required."
            );

            return;
        }

        if (!prn.suppliercode) {

            setErrorMessage(
                "Supplier is required."
            );

            return;
        }

        if (!prn.location) {

            setErrorMessage(
                "Location is required."
            );

            return;
        }

        const returnItems =
            items.filter(
                item =>
                    Number(
                        item.ReturnQty || 0
                    ) > 0
            );

        if (
            returnItems.length === 0
        ) {

            setErrorMessage(
                "Enter return quantity for at least one product."
            );

            return;
        }

        // Frontend validation

        for (
            const item
            of returnItems
        ) {

            if (
                Number(item.ReturnQty) >
                Number(item.ReturnableQty)
            ) {

                setErrorMessage(
                    `Return quantity for ${item.ProductCode} cannot exceed ${item.ReturnableQty}.`
                );

                return;
            }
        }

        try {

            setSaving(true);

            const payload = {

                ...prn,

                username:
                    localStorage.getItem(
                        "username"
                    ) || "",

                items:
                    returnItems
            };

            const response =
                await axios.post(
                    `${API_URL}/PRN`,
                    payload
                );

            if (
                response.data?.success
            ) {

                setMessage(
                    response.data.message
                );

                // clear products

                setItems([]);

                // generate next PRN

                await loadPRNNumber();

                setPrn(prev => ({
                    ...prev,

                    grnno: "",
                    pono: "",
                    suppliercode: "",
                    suppliername: "",
                    location: "",
                    referenceno: "",
                    remark: ""
                }));
            }

        } catch (error) {

            console.error(
                "SAVE PRN ERROR:",
                error.response?.data ||
                error
            );

            setErrorMessage(
                error.response?.data?.message ||
                error.message ||
                "Unable to save Purchase Return."
            );

        } finally {

            setSaving(false);
        }
    };

    // ==========================================
    // CLEAR
    // ==========================================

    const clearForm = async () => {

        setItems([]);

        setMessage("");
        setErrorMessage("");

        setPrn({

            prnno: "",

            prndate:
                new Date()
                    .toISOString()
                    .split("T")[0],

            grnno: "",
            pono: "",

            suppliercode: "",
            suppliername: "",

            location: "",

            referenceno: "",

            remark: ""
        });

        await loadPRNNumber();
    };

    // ==========================================
    // RENDER
    // ==========================================

    return (

        <div className="min-h-screen bg-gray-100 p-4 md:p-6">

            <div className="mx-auto max-w-7xl">

                {/* HEADER */}

                <div className="mb-5 flex flex-col gap-3 rounded-xl bg-white p-5 shadow-sm md:flex-row md:items-center md:justify-between">

                    <div>

                        <h1 className="text-2xl font-bold text-gray-800">
                            Purchase Return Note
                        </h1>

                        <p className="text-sm text-gray-500">
                            Return received products to supplier
                        </p>

                    </div>

                    <div className="flex gap-2">

                        <button
                            type="button"
                            onClick={clearForm}
                            className="flex items-center gap-2 rounded-lg border border-gray-300 bg-white px-4 py-2 text-sm font-semibold text-gray-700 hover:bg-gray-50"
                        >
                            <RefreshCw size={16} />
                            Clear
                        </button>

                        <button
                            type="button"
                            onClick={savePRN}
                            disabled={saving}
                            className="flex items-center gap-2 rounded-lg bg-blue-600 px-5 py-2 text-sm font-semibold text-white hover:bg-blue-700 disabled:opacity-50"
                        >
                            <Save size={17} />

                            {saving
                                ? "Saving..."
                                : "Save PRN"}
                        </button>

                    </div>

                </div>

                {/* MESSAGES */}

                {message && (

                    <div className="mb-4 rounded-lg border border-green-200 bg-green-50 px-4 py-3 text-sm font-medium text-green-700">
                        {message}
                    </div>

                )}

                {errorMessage && (

                    <div className="mb-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700">
                        {errorMessage}
                    </div>

                )}

                {/* HEADER FORM */}

                <div className="mb-5 rounded-xl bg-white p-5 shadow-sm">

                    <div className="mb-4 border-b pb-3">

                        <h2 className="font-bold text-gray-800">
                            Return Information
                        </h2>

                    </div>

                    <div className="grid grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-4">

                        {/* PRN */}

                        <div>

                            <label className="mb-1 block text-sm font-semibold text-gray-700">
                                PRN Number
                            </label>

                            <input
                                type="text"
                                value={prn.prnno}
                                readOnly
                                className="w-full rounded-lg border bg-gray-100 px-3 py-2 text-sm font-semibold"
                            />

                        </div>

                        {/* DATE */}

                        <div>

                            <label className="mb-1 block text-sm font-semibold text-gray-700">
                                Return Date
                            </label>

                            <input
                                type="date"
                                name="prndate"
                                value={prn.prndate}
                                onChange={handleChange}
                                className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm"
                            />

                        </div>

                        {/* GRN */}

                        <div>

                            <label className="mb-1 block text-sm font-semibold text-gray-700">
                                GRN Number
                            </label>

                            <div className="flex gap-2">

                                <input
                                    type="text"
                                    name="grnno"
                                    value={prn.grnno}
                                    onChange={handleChange}
                                    placeholder="GRN00001"
                                    className="min-w-0 flex-1 rounded-lg border border-gray-300 px-3 py-2 text-sm"
                                />

                                <button
                                    type="button"
                                    onClick={recallGRN}
                                    disabled={
                                        loading ||
                                        !prn.grnno.trim()
                                    }
                                    className="flex items-center gap-1 rounded-lg bg-blue-600 px-3 py-2 text-white hover:bg-blue-700 disabled:opacity-50"
                                >
                                    <Search size={16} />

                                    {loading
                                        ? "..."
                                        : "Recall"}
                                </button>

                            </div>

                        </div>

                        {/* PO */}

                        <div>

                            <label className="mb-1 block text-sm font-semibold text-gray-700">
                                PO Number
                            </label>

                            <input
                                type="text"
                                name="pono"
                                value={prn.pono}
                                readOnly
                                className="w-full rounded-lg border bg-gray-100 px-3 py-2 text-sm"
                            />

                        </div>

                        {/* SUPPLIER CODE */}

                        <div>

                            <label className="mb-1 block text-sm font-semibold text-gray-700">
                                Supplier Code
                            </label>

                            <input
                                type="text"
                                value={prn.suppliercode}
                                readOnly
                                className="w-full rounded-lg border bg-gray-100 px-3 py-2 text-sm"
                            />

                        </div>

                        {/* SUPPLIER NAME */}

                        <div>

                            <label className="mb-1 block text-sm font-semibold text-gray-700">
                                Supplier Name
                            </label>

                            <input
                                type="text"
                                value={prn.suppliername}
                                readOnly
                                className="w-full rounded-lg border bg-gray-100 px-3 py-2 text-sm"
                            />

                        </div>

                        {/* LOCATION */}

                        <div>

                            <label className="mb-1 block text-sm font-semibold text-gray-700">
                                Location
                            </label>

                            <select
                                name="location"
                                value={prn.location}
                                onChange={handleChange}
                                className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2 text-sm"
                            >

                                <option value="">
                                    Select Location
                                </option>

                                {locations.map(
                                    (
                                        loc,
                                        index
                                    ) => {

                                        const id =
                                            loc.LocationID ??
                                            loc.locationID ??
                                            loc.locationid ??
                                            loc.ID ??
                                            loc.id ??
                                            loc.Code ??
                                            loc.code ??
                                            "";

                                        const name =
                                            loc.LocationName ??
                                            loc.locationName ??
                                            loc.locationname ??
                                            loc.Location ??
                                            loc.location ??
                                            loc.Name ??
                                            loc.name ??
                                            id;

                                        return (

                                            <option
                                                key={index}
                                                value={String(id)}
                                            >
                                                {name}
                                            </option>

                                        );
                                    }
                                )}

                            </select>

                        </div>

                        {/* REFERENCE */}

                        <div>

                            <label className="mb-1 block text-sm font-semibold text-gray-700">
                                Reference No
                            </label>

                            <input
                                type="text"
                                name="referenceno"
                                value={prn.referenceno}
                                onChange={handleChange}
                                className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm"
                            />

                        </div>

                    </div>

                    {/* REMARK */}

                    <div className="mt-4">

                        <label className="mb-1 block text-sm font-semibold text-gray-700">
                            Remark
                        </label>

                        <textarea
                            name="remark"
                            value={prn.remark}
                            onChange={handleChange}
                            rows={2}
                            className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm"
                            placeholder="Return reason / remark"
                        />

                    </div>

                </div>

                {/* PRODUCTS */}

                <div className="rounded-xl bg-white shadow-sm">

                    <div className="flex flex-col gap-3 border-b p-5 md:flex-row md:items-center md:justify-between">

                        <div>

                            <h2 className="font-bold text-gray-800">
                                Return Products
                            </h2>

                            <p className="text-xs text-gray-500">
                                Only received and not fully returned products are shown
                            </p>

                        </div>

                        <div className="rounded-lg bg-gray-100 px-4 py-2 text-sm">

                            Products:
                            <span className="ml-1 font-bold">
                                {items.length}
                            </span>

                        </div>

                    </div>

                    {/* TABLE */}

                    <div className="overflow-x-auto">

                        <table className="min-w-[1100px] w-full text-sm">

                            <thead className="bg-gray-50 text-left">

                                <tr>

                                    <th className="px-4 py-3">
                                        #
                                    </th>

                                    <th className="px-4 py-3">
                                        Product Code
                                    </th>

                                    <th className="px-4 py-3">
                                        Product Name
                                    </th>

                                    <th className="px-4 py-3 text-right">
                                        Received
                                    </th>

                                    <th className="px-4 py-3 text-right">
                                        Returned
                                    </th>

                                    <th className="px-4 py-3 text-right">
                                        Returnable
                                    </th>

                                    <th className="px-4 py-3 text-right">
                                        Return Qty
                                    </th>

                                    <th className="px-4 py-3 text-right">
                                        Cost
                                    </th>

                                    <th className="px-4 py-3 text-right">
                                        Discount %
                                    </th>

                                    <th className="px-4 py-3 text-right">
                                        Net
                                    </th>

                                    <th className="px-4 py-3">
                                        Action
                                    </th>

                                </tr>

                            </thead>

                            <tbody>

                                {items.length === 0 ? (

                                    <tr>

                                        <td
                                            colSpan="11"
                                            className="px-4 py-12 text-center text-gray-400"
                                        >

                                            <RotateCcw
                                                size={35}
                                                className="mx-auto mb-2 opacity-40"
                                            />

                                            Recall a GRN to load products

                                        </td>

                                    </tr>

                                ) : (

                                    items.map(
                                        (
                                            item,
                                            index
                                        ) => {

                                            const qty =
                                                Number(
                                                    item.ReturnQty ||
                                                    0
                                                );

                                            const cost =
                                                Number(
                                                    item.CostPrice ||
                                                    0
                                                );

                                            const disc =
                                                Number(
                                                    item.FixedDiscountPercentage ||
                                                    0
                                                );

                                            const gross =
                                                qty *
                                                cost;

                                            const discount =
                                                gross *
                                                disc /
                                                100;

                                            const net =
                                                gross -
                                                discount;

                                            return (

                                                <tr
                                                    key={
                                                        `${item.ProductCode}-${index}`
                                                    }
                                                    className="border-t hover:bg-gray-50"
                                                >

                                                    <td className="px-4 py-3">
                                                        {index + 1}
                                                    </td>

                                                    <td className="px-4 py-3 font-semibold">
                                                        {
                                                            item.ProductCode
                                                        }
                                                    </td>

                                                    <td className="px-4 py-3">
                                                        {
                                                            item.ProductName
                                                        }
                                                    </td>

                                                    <td className="px-4 py-3 text-right">
                                                        {
                                                            item.ReceivedQty
                                                        }
                                                    </td>

                                                    <td className="px-4 py-3 text-right text-orange-600">
                                                        {
                                                            item.AlreadyReturnedQty
                                                        }
                                                    </td>

                                                    <td className="px-4 py-3 text-right font-semibold text-green-600">
                                                        {
                                                            item.ReturnableQty
                                                        }
                                                    </td>

                                                    <td className="px-4 py-3">

                                                        <input
                                                            type="number"
                                                            min="0"
                                                            max={
                                                                item.ReturnableQty
                                                            }
                                                            step="0.001"
                                                            value={
                                                                item.ReturnQty
                                                            }
                                                            onChange={
                                                                e =>
                                                                    updateReturnQty(
                                                                        index,
                                                                        e.target.value
                                                                    )
                                                            }
                                                            className="w-28 rounded-lg border border-blue-300 px-2 py-2 text-right focus:outline-none focus:ring-2 focus:ring-blue-200"
                                                        />

                                                    </td>

                                                    <td className="px-4 py-3 text-right">
                                                        {
                                                            cost.toFixed(
                                                                2
                                                            )
                                                        }
                                                    </td>

                                                    <td className="px-4 py-3 text-right">
                                                        {
                                                            disc.toFixed(
                                                                2
                                                            )
                                                        }
                                                    </td>

                                                    <td className="px-4 py-3 text-right font-semibold">
                                                        {
                                                            net.toFixed(
                                                                2
                                                            )
                                                        }
                                                    </td>

                                                    <td className="px-4 py-3">

                                                        <button
                                                            type="button"
                                                            onClick={() =>
                                                                removeItem(
                                                                    index
                                                                )
                                                            }
                                                            className="rounded-lg p-2 text-red-500 hover:bg-red-50"
                                                        >

                                                            <Trash2
                                                                size={17}
                                                            />

                                                        </button>

                                                    </td>

                                                </tr>

                                            );
                                        }
                                    )

                                )}

                            </tbody>

                        </table>

                    </div>

                </div>

                {/* TOTALS */}

                <div className="mt-5 grid grid-cols-1 gap-4 md:grid-cols-4">

                    <div className="rounded-xl bg-white p-5 shadow-sm">

                        <p className="text-sm text-gray-500">
                            Return Qty
                        </p>

                        <p className="mt-1 text-2xl font-bold">
                            {totals.qty.toFixed(3)}
                        </p>

                    </div>

                    <div className="rounded-xl bg-white p-5 shadow-sm">

                        <p className="text-sm text-gray-500">
                            Gross Amount
                        </p>

                        <p className="mt-1 text-2xl font-bold">
                            {totals.gross.toFixed(2)}
                        </p>

                    </div>

                    <div className="rounded-xl bg-white p-5 shadow-sm">

                        <p className="text-sm text-gray-500">
                            Discount
                        </p>

                        <p className="mt-1 text-2xl font-bold text-orange-600">
                            {totals.discount.toFixed(2)}
                        </p>

                    </div>

                    <div className="rounded-xl bg-blue-600 p-5 text-white shadow-sm">

                        <p className="text-sm text-blue-100">
                            Net Return
                        </p>

                        <p className="mt-1 text-2xl font-bold">
                            {totals.net.toFixed(2)}
                        </p>

                    </div>

                </div>

                {/* BOTTOM SAVE */}

                <div className="mt-5 flex justify-end">

                    <button
                        type="button"
                        onClick={savePRN}
                        disabled={saving}
                        className="flex items-center gap-2 rounded-lg bg-blue-600 px-8 py-3 font-bold text-white shadow hover:bg-blue-700 disabled:opacity-50"
                    >

                        <Save size={18} />

                        {saving
                            ? "Saving Purchase Return..."
                            : "Save Purchase Return"}

                    </button>

                </div>

            </div>

        </div>
    );
}

export default PurchaseReturn;