import React, { useContext, useEffect, useState } from "react";
import axios from "axios";
import { AuthContext } from "./SERVER/AuthContext.js";

// ← PERM
import { usePermissions } from "../hooks/usePermissions.jsx";

function Department() {
  const { user } = useContext(AuthContext);

  const API_URL = "http://localhost:5000";

  // =========================================================
  // PERMISSIONS                                            // ← PERM
  // =========================================================
  const { can, loading: permissionsLoading } = usePermissions();    // ← PERM

  const canViewDepartment   = can("Department", "View");             // ← PERM
  const canAddDepartment    = can("Department", "Add");              // ← PERM
  const canEditDepartment   = can("Department", "Edit");             // ← PERM
  const canDeleteDepartment = can("Department", "Delete");           // ← PERM

  const emptyForm = {
    InvDepartmentID: "",
    departmentcode: "",
    departmentname: "",
    Remark: "",
    username: "",
  };

  const [form, setForm] = useState(emptyForm);
  const [departments, setDepartments] = useState([]);
  const [search, setSearch] = useState("");
  const [editing, setEditing] = useState(false);

  const [loading, setLoading] = useState(false);
  const [loadingCode, setLoadingCode] = useState(false);
  const [deleting, setDeleting] = useState(false);

  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  // =========================================================
  // LOAD DEPARTMENTS
  // =========================================================
  useEffect(() => {
    // ← PERM: skip until permissions resolve / if user can't view
    if (permissionsLoading) return;
    if (!canViewDepartment) return;

    loadDepartments();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [canViewDepartment, permissionsLoading]);              // ← PERM

  // =========================================================
  // UPDATE USERNAME
  // =========================================================
  useEffect(() => {
    setForm((prev) => ({ ...prev, username: user?.username || "" }));
  }, [user]);

  // =========================================================
  // GET DEPARTMENTS
  // =========================================================
  const loadDepartments = async () => {
    try {
      setLoading(true);
      setError("");

      const response = await axios.get(`${API_URL}/departments`);
      console.log("DEPARTMENT LIST:", response.data);

      let data = [];
      if (Array.isArray(response.data)) data = response.data;
      else if (Array.isArray(response.data?.data)) data = response.data.data;
      else if (Array.isArray(response.data?.departments)) data = response.data.departments;

      setDepartments(data);
    } catch (err) {
      console.error("LOAD DEPARTMENT ERROR:", err.response?.data || err);
      setError(
        err.response?.data?.message || "Unable to load departments."
      );
    } finally {
      setLoading(false);
    }
  };

  // =========================================================
  // INPUT CHANGE
  // =========================================================
  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
    setMessage("");
    setError("");
  };

  // =========================================================
  // GENERATE NEW DEPARTMENT CODE
  // =========================================================
  const handleNew = async () => {
    // ← PERM
    if (!canAddDepartment) {
      setError("You do not have permission to create departments.");
      return;
    }

    try {
      setLoadingCode(true);
      setMessage("");
      setError("");

      const response = await axios.get(`${API_URL}/departmentcode`);
      console.log("DEPARTMENT CODE RESPONSE:", response.data);

      let data = [];
      if (Array.isArray(response.data)) data = response.data;
      else if (Array.isArray(response.data?.data)) data = response.data.data;

      let nextCode = "D001";

      if (data.length > 0) {
        const lastCode =
          data[0]?.DepartmentCode ?? data[0]?.departmentcode ?? "";

        const numberPart = parseInt(String(lastCode).replace(/\D/g, ""), 10);

        if (!Number.isNaN(numberPart)) {
          nextCode = `D${String(numberPart + 1).padStart(3, "0")}`;
        }
      }

      setForm((prev) => ({
        ...prev,
        InvDepartmentID: "",
        departmentcode: nextCode,
        departmentname: "",
        Remark: "",
        username: user?.username || prev.username || "",
      }));

      setEditing(false);
      setMessage(`New department code generated: ${nextCode}`);
    } catch (err) {
      console.error("DEPARTMENT CODE ERROR:", err.response?.data || err);
      setError(
        err.response?.data?.message || "Unable to generate department code."
      );
    } finally {
      setLoadingCode(false);
    }
  };

  // =========================================================
  // SAVE / UPDATE
  // =========================================================
  const handleSubmit = async (e) => {
    e.preventDefault();

    setMessage("");
    setError("");

    // ----- Permission guards -----                          // ← PERM
    if (editing && !canEditDepartment) {
      setError("You do not have permission to edit departments.");
      return;
    }
    if (!editing && !canAddDepartment) {
      setError("You do not have permission to create departments.");
      return;
    }

    const departmentcode = String(form?.departmentcode ?? "").trim();
    const departmentname = String(form?.departmentname ?? "").trim();
    const Remark         = String(form?.Remark ?? "").trim();
    const username       = String(user?.username || form?.username || "").trim();

    // ----- Validation -----
    if (!departmentcode) {
      setError("Please generate or enter department code.");
      return;
    }
    if (!departmentname) {
      setError("Please enter department name.");
      return;
    }
    if (departmentcode.length > 15) {
      setError("Department code cannot exceed 15 characters.");
      return;
    }
    if (departmentname.length > 50) {
      setError("Department name cannot exceed 50 characters.");
      return;
    }
    if (Remark.length > 150) {
      setError("Remark cannot exceed 150 characters.");
      return;
    }

    const requestData = {
      departmentcode,
      departmentname,
      Remark: Remark || null,
      username: username || null,
    };

    console.log("DEPARTMENT REQUEST:", requestData);

    try {
      setLoading(true);

      if (editing) {
        const response = await axios.put(
          `${API_URL}/department/${form.InvDepartmentID}`,
          requestData,
          { headers: { "Content-Type": "application/json" } }
        );
        setMessage(
          response.data?.message || "Department updated successfully."
        );
      } else {
        const response = await axios.post(
          `${API_URL}/department`,
          requestData,
          { headers: { "Content-Type": "application/json" } }
        );
        setMessage(
          response.data?.message || "Department saved successfully."
        );
      }

      setForm({ ...emptyForm, username: user?.username || "" });
      setEditing(false);

      await loadDepartments();
    } catch (err) {
      console.error("DEPARTMENT SAVE ERROR:", err.response?.data || err);
      setError(
        err.response?.data?.message || "Error saving department."
      );
    } finally {
      setLoading(false);
    }
  };

  // =========================================================
  // EDIT
  // =========================================================
  const handleEdit = (department) => {
    // ← PERM
    if (!canEditDepartment) {
      setError("You do not have permission to edit departments.");
      return;
    }

    const id =
      department?.InvDepartmentID ??
      department?.invDepartmentID ??
      department?.DepartmentID ??
      "";

    const code =
      department?.DepartmentCode ??
      department?.departmentcode ??
      "";

    const name =
      department?.DepartmentName ??
      department?.departmentname ??
      "";

    const remark =
      department?.Remark ?? department?.remark ?? "";

    setForm({
      InvDepartmentID: id,
      departmentcode: code,
      departmentname: name,
      Remark: remark,
      username: user?.username || "",
    });

    setEditing(true);
    setMessage(`Editing ${code}`);
    setError("");

    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  // =========================================================
  // DELETE
  // =========================================================
  const handleDelete = async (department) => {
    // ← PERM
    if (!canDeleteDepartment) {
      setError("You do not have permission to delete departments.");
      return;
    }

    const id =
      department?.InvDepartmentID ??
      department?.invDepartmentID ??
      department?.DepartmentID ??
      "";

    const code =
      department?.DepartmentCode ??
      department?.departmentcode ??
      "";

    const name =
      department?.DepartmentName ??
      department?.departmentname ??
      "";

    if (!id) {
      setError("Department ID not found.");
      return;
    }

    const confirmed = window.confirm(
      `Are you sure you want to delete this department?\n\n${code} - ${name}`
    );
    if (!confirmed) return;

    try {
      setDeleting(true);
      setMessage("");
      setError("");

      const response = await axios.delete(`${API_URL}/department/${id}`);
      setMessage(
        response.data?.message || "Department deleted successfully."
      );

      if (String(form.InvDepartmentID) === String(id)) {
        setForm({ ...emptyForm, username: user?.username || "" });
        setEditing(false);
      }

      await loadDepartments();
    } catch (err) {
      console.error("DELETE DEPARTMENT ERROR:", err.response?.data || err);
      setError(
        err.response?.data?.message || "Error deleting department."
      );
    } finally {
      setDeleting(false);
    }
  };

  // =========================================================
  // CLEAR
  // =========================================================
  const handleClear = () => {
    setForm({ ...emptyForm, username: user?.username || "" });
    setEditing(false);
    setMessage("");
    setError("");
  };

  // =========================================================
  // SEARCH
  // =========================================================
  const searchText = String(search || "").toLowerCase().trim();

  const filteredDepartments = departments.filter((department) => {
    const code = String(
      department?.DepartmentCode ?? department?.departmentcode ?? ""
    ).toLowerCase();
    const name = String(
      department?.DepartmentName ?? department?.departmentname ?? ""
    ).toLowerCase();
    const remark = String(
      department?.Remark ?? department?.remark ?? ""
    ).toLowerCase();

    return (
      code.includes(searchText) ||
      name.includes(searchText) ||
      remark.includes(searchText)
    );
  });

  // =========================================================
  // COMPUTED                                               // ← PERM
  // =========================================================
  const saveAllowed = (editing && canEditDepartment) || (!editing && canAddDepartment);
  const readOnlyEdit = editing && !canEditDepartment;

  // =========================================================
  // ACCESS GATE                                            // ← PERM
  // =========================================================
  if (permissionsLoading) {
    return (
      <div className="min-h-screen bg-gray-100 flex items-center justify-center text-gray-500">
        Checking permissions…
      </div>
    );
  }

  if (!canViewDepartment) {
    return (
      <div className="min-h-screen bg-gray-100 p-6">
        <div className="mx-auto max-w-xl mt-20 rounded-xl border border-red-200 bg-red-50 p-8 text-center">
          <h2 className="text-lg font-bold text-red-700">Access Denied</h2>
          <p className="text-sm text-red-600 mt-2">
            You do not have permission to view Department Master.
          </p>
          <p className="text-xs text-red-400 mt-3">
            Module: <code>Department</code>
          </p>
        </div>
      </div>
    );
  }

  // =========================================================
  // UI
  // =========================================================
  return (
    <div className="min-h-screen bg-gray-100 p-4 sm:p-6">
      <div className="mx-auto max-w-7xl">

        {/* HEADER */}
        <div className="mb-5 rounded-xl border border-gray-200 bg-white shadow-sm">
          <div className="flex flex-col gap-4 px-5 py-4 md:flex-row md:items-center md:justify-between">
            <div>
              <h1 className="text-2xl font-bold text-gray-800">
                Department Master
              </h1>
              <p className="mt-1 text-sm text-gray-500">
                Create, edit and delete departments
              </p>
            </div>

            <div className="flex items-center gap-3">
              {/* ← PERM: read-only badge */}
              {readOnlyEdit && (
                <span className="rounded-full bg-slate-200 px-3 py-1 text-xs font-semibold text-slate-600">
                  READ ONLY
                </span>
              )}

              <div className="rounded-lg border border-gray-200 bg-gray-50 px-5 py-2">
                <p className="text-xs text-gray-500">Logged User</p>
                <p className="font-semibold text-gray-800">
                  {user?.username || "Not logged in"}
                </p>
              </div>
            </div>
          </div>
        </div>

        {/* SUCCESS */}
        {message && (
          <div className="mb-4 rounded-lg border border-green-200 bg-green-50 px-4 py-3 text-sm font-medium text-green-700">
            ✓ {message}
          </div>
        )}

        {/* ERROR */}
        {error && (
          <div className="mb-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700">
            ⚠ {error}
          </div>
        )}

        {/* FORM */}
        <div className="mb-6 overflow-hidden rounded-xl border border-gray-200 bg-white shadow-lg">
          <div className="flex items-center justify-between border-b border-gray-200 bg-gray-50 px-5 py-4">
            <div>
              <h2 className="text-lg font-semibold text-gray-800">
                {editing ? "Edit Department" : "Department Information"}
              </h2>
              {editing && (
                <p className="mt-1 text-xs text-orange-600">
                  Editing existing department
                </p>
              )}
            </div>

            {editing && (
              <span className="rounded-full bg-orange-100 px-3 py-1 text-xs font-bold text-orange-700">
                EDIT MODE
              </span>
            )}
          </div>

          <form onSubmit={handleSubmit} className="p-5">
            <div className="grid grid-cols-1 gap-5 md:grid-cols-2">

              {/* DEPARTMENT CODE */}
              <div>
                <label className="mb-1.5 block text-sm font-semibold text-gray-700">
                  Department Code <span className="ml-1 text-red-500">*</span>
                </label>

                <div className="flex gap-2">
                  <input
                    type="text"
                    name="departmentcode"
                    value={form.departmentcode || ""}
                    onChange={handleChange}
                    maxLength={15}
                    disabled={editing}
                    placeholder="D001"
                    className="w-full rounded-lg border border-gray-300 bg-gray-50 px-3 py-2.5 text-sm font-semibold text-gray-800 outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 disabled:bg-gray-100"
                  />

                  {/* ← PERM: New button only when user can Add */}
                  {!editing && canAddDepartment && (
                    <button
                      type="button"
                      onClick={handleNew}
                      disabled={loadingCode}
                      className="min-w-[90px] rounded-lg bg-indigo-600 px-4 py-2.5 text-sm font-semibold text-white hover:bg-indigo-700 disabled:bg-gray-400"
                    >
                      {loadingCode ? "..." : "New"}
                    </button>
                  )}
                </div>

                <p className="mt-1 text-xs text-gray-500">
                  Maximum 15 characters
                </p>
              </div>

              {/* DEPARTMENT NAME */}
              <div>
                <label className="mb-1.5 block text-sm font-semibold text-gray-700">
                  Department Name <span className="ml-1 text-red-500">*</span>
                </label>

                <input
                  type="text"
                  name="departmentname"
                  value={form.departmentname || ""}
                  onChange={handleChange}
                  maxLength={50}
                  placeholder="Enter department name"
                  className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm text-gray-800 outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200"
                />

                <p className="mt-1 text-right text-xs text-gray-400">
                  {String(form.departmentname || "").length}/50
                </p>
              </div>

              {/* REMARK */}
              <div className="md:col-span-2">
                <label className="mb-1.5 block text-sm font-semibold text-gray-700">
                  Remark
                </label>

                <textarea
                  name="Remark"
                  value={form.Remark || ""}
                  onChange={handleChange}
                  maxLength={150}
                  rows={3}
                  placeholder="Enter remark..."
                  className="w-full resize-none rounded-lg border border-gray-300 px-3 py-2.5 text-sm text-gray-800 outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200"
                />

                <p className="mt-1 text-right text-xs text-gray-400">
                  {String(form.Remark || "").length}/150
                </p>
              </div>
            </div>

            {/* BUTTONS */}
            <div className="mt-6 flex flex-col gap-3 border-t border-gray-200 pt-5 sm:flex-row sm:justify-end">
              <button
                type="button"
                onClick={handleClear}
                disabled={loading || deleting}
                className="rounded-lg border border-gray-300 bg-white px-6 py-2.5 text-sm font-semibold text-gray-700 hover:bg-gray-100 disabled:opacity-50"
              >
                Clear
              </button>

              {/* ← PERM: Save button only when saveAllowed */}
              {saveAllowed && (
                <button
                  type="submit"
                  disabled={loading || deleting}
                  className={`rounded-lg px-8 py-2.5 text-sm font-semibold text-white ${
                    editing
                      ? "bg-orange-600 hover:bg-orange-700"
                      : "bg-indigo-600 hover:bg-indigo-700"
                  } disabled:bg-gray-400`}
                >
                  {loading
                    ? "Saving..."
                    : editing
                    ? "Update Department"
                    : "Save Department"}
                </button>
              )}

              {/* ← PERM: helper text when blocked */}
              {readOnlyEdit && (
                <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-2.5 text-xs font-semibold text-slate-500">
                  You have read-only access — editing is disabled.
                </div>
              )}

              {!editing && !canAddDepartment && (
                <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-2.5 text-xs font-semibold text-slate-500">
                  You do not have permission to create new departments.
                </div>
              )}
            </div>
          </form>
        </div>

        {/* DEPARTMENT LIST */}
        <div className="overflow-hidden rounded-xl border border-gray-200 bg-white shadow-lg">
          <div className="flex flex-col gap-3 border-b border-gray-200 bg-gray-50 px-5 py-4 md:flex-row md:items-center md:justify-between">
            <div>
              <h2 className="text-lg font-semibold text-gray-800">
                Department List
              </h2>
              <p className="text-xs text-gray-500">
                {filteredDepartments.length} record(s)
              </p>
            </div>

            <input
              type="text"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search department..."
              className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2.5 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 md:w-80"
            />
          </div>

          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-100">
                <tr>
                  <th className="px-4 py-3 text-left text-xs font-bold uppercase text-gray-600">#</th>
                  <th className="px-4 py-3 text-left text-xs font-bold uppercase text-gray-600">Code</th>
                  <th className="px-4 py-3 text-left text-xs font-bold uppercase text-gray-600">Department Name</th>
                  <th className="px-4 py-3 text-left text-xs font-bold uppercase text-gray-600">Remark</th>
                  <th className="px-4 py-3 text-center text-xs font-bold uppercase text-gray-600">Actions</th>
                </tr>
              </thead>

              <tbody className="divide-y divide-gray-200 bg-white">
                {loading && departments.length === 0 ? (
                  <tr>
                    <td colSpan="5" className="px-4 py-10 text-center text-sm text-gray-500">
                      Loading departments...
                    </td>
                  </tr>
                ) : filteredDepartments.length === 0 ? (
                  <tr>
                    <td colSpan="5" className="px-4 py-10 text-center text-sm text-gray-500">
                      No departments found.
                    </td>
                  </tr>
                ) : (
                  filteredDepartments.map((department, index) => {
                    const id =
                      department?.InvDepartmentID ??
                      department?.invDepartmentID ??
                      department?.DepartmentID ??
                      "";

                    const code =
                      department?.DepartmentCode ??
                      department?.departmentcode ??
                      "";

                    const name =
                      department?.DepartmentName ??
                      department?.departmentname ??
                      "";

                    const remark =
                      department?.Remark ?? department?.remark ?? "";

                    return (
                      <tr
                        key={id || `${code}-${index}`}
                        className="hover:bg-gray-50"
                      >
                        <td className="px-4 py-3 text-sm text-gray-500">
                          {index + 1}
                        </td>

                        <td className="px-4 py-3">
                          <span className="rounded-md bg-indigo-50 px-2.5 py-1 text-sm font-bold text-indigo-700">
                            {code}
                          </span>
                        </td>

                        <td className="px-4 py-3 text-sm font-semibold text-gray-800">
                          {name}
                        </td>

                        <td className="max-w-xs truncate px-4 py-3 text-sm text-gray-500">
                          {remark || "-"}
                        </td>

                        {/* ← PERM: gate the action buttons */}
                        <td className="px-4 py-3">
                          <div className="flex justify-center gap-2">
                            {canEditDepartment && (
                              <button
                                type="button"
                                onClick={() => handleEdit(department)}
                                disabled={deleting}
                                className="rounded-lg bg-blue-600 px-3 py-2 text-xs font-semibold text-white hover:bg-blue-700 disabled:opacity-50"
                              >
                                ✏️ Edit
                              </button>
                            )}

                            {canDeleteDepartment && (
                              <button
                                type="button"
                                onClick={() => handleDelete(department)}
                                disabled={deleting}
                                className="rounded-lg bg-red-600 px-3 py-2 text-xs font-semibold text-white hover:bg-red-700 disabled:opacity-50"
                              >
                                🗑️ Delete
                              </button>
                            )}

                            {!canEditDepartment && !canDeleteDepartment && (
                              <span className="text-xs text-slate-400">
                                No actions
                              </span>
                            )}
                          </div>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
        </div>

      </div>
    </div>
  );
}

export default Department;