import React, { useEffect, useState } from "react";

const API = "http://localhost:5000/api";

const defaultTemplate = {
  templateName: "BOC",
  bankName: "BOC",

  checkWidth: 210,
  checkHeight: 102,
  stubWidth: 30,

  showCounterfoil: true,

  dateFontSize: 14,
  payeeFontSize: 14,
  amountWordsFontSize: 10,
  amountWordsLineHeight: 1.4,
  amountNumbersFontSize: 16,

  dateX: 160,
  dateY: 12,

  payeeX: 60,
  payeeY: 32,

  amountWordsX: 60,
  amountWordsY: 45,

  amountX: 160,
  amountY: 60,

  payeeLabel: "Pay",
  amountLabel: "Amount"
};

export default function CheckTemplate() {

  const [templates, setTemplates] = useState([]);
  const [accounts, setAccounts] = useState([]);

  const [selectedTemplateId, setSelectedTemplateId] = useState(null);

  const [form, setForm] = useState(defaultTemplate);

  const [selectedAccounts, setSelectedAccounts] = useState([]);

  const [loading, setLoading] = useState(false);

  const [message, setMessage] = useState("");

  const [activeElement, setActiveElement] = useState(null);


  /* =========================================================
     LOAD
  ========================================================= */

  useEffect(() => {

    loadTemplates();
    loadAccounts();

  }, []);


  async function loadTemplates() {

    try {

      const response = await fetch(
        `${API}/check-templates`
      );

      const data = await response.json();

      if (data.success) {
        setTemplates(data.templates || []);
      }

    } catch (error) {

      console.error(error);

    }

  }


  async function loadAccounts() {

    try {

      const response = await fetch(
        `${API}/check-template/accounts`
      );

      const data = await response.json();

      if (data.success) {

        setAccounts(data.accounts || []);

      }

    } catch (error) {

      console.error(error);

    }

  }


  /* =========================================================
     FORM
  ========================================================= */

  function updateField(name, value) {

    setForm(prev => ({
      ...prev,
      [name]: value
    }));

  }


  function numberField(name, value) {

    updateField(name, Number(value));

  }


  /* =========================================================
     ACCOUNT SELECTION
  ========================================================= */

  function toggleAccount(accountId) {

    setSelectedAccounts(prev => {

      if (prev.includes(accountId)) {

        return prev.filter(
          id => id !== accountId
        );

      }

      return [
        ...prev,
        accountId
      ];

    });

  }


  /* =========================================================
     NEW TEMPLATE
  ========================================================= */

  function newTemplate() {

    setSelectedTemplateId(null);

    setForm({
      ...defaultTemplate
    });

    setSelectedAccounts([]);

    setMessage("");

  }


  /* =========================================================
     EDIT TEMPLATE
  ========================================================= */

  async function editTemplate(id) {

    try {

      const response = await fetch(
        `${API}/check-templates/${id}`
      );

      const data = await response.json();

      if (!data.success) {
        alert(data.message);
        return;
      }

      const t = data.template;

      setSelectedTemplateId(id);

      setForm({

        templateName: t.TemplateName || "",
        bankName: t.BankName || "",

        checkWidth: Number(t.CheckWidth),
        checkHeight: Number(t.CheckHeight),
        stubWidth: Number(t.StubWidth),

        showCounterfoil:
          Boolean(t.ShowCounterfoil),

        dateFontSize:
          Number(t.DateFontSize),

        payeeFontSize:
          Number(t.PayeeFontSize),

        amountWordsFontSize:
          Number(t.AmountWordsFontSize),

        amountWordsLineHeight:
          Number(t.AmountWordsLineHeight),

        amountNumbersFontSize:
          Number(t.AmountNumbersFontSize),

        dateX: Number(t.DateX),
        dateY: Number(t.DateY),

        payeeX: Number(t.PayeeX),
        payeeY: Number(t.PayeeY),

        amountWordsX:
          Number(t.AmountWordsX),

        amountWordsY:
          Number(t.AmountWordsY),

        amountX: Number(t.AmountX),
        amountY: Number(t.AmountY),

        payeeLabel:
          t.PayeeLabel || "Pay",

        amountLabel:
          t.AmountLabel || "Amount"

      });

      setSelectedAccounts(
        data.accountIds || []
      );

    } catch (error) {

      console.error(error);

    }

  }


  /* =========================================================
     SAVE
  ========================================================= */

  async function saveTemplate() {

    if (!form.templateName.trim()) {

      alert("Please enter template name");

      return;

    }


    setLoading(true);

    setMessage("");


    try {

      const payload = {

        ...form,

        accountIds: selectedAccounts,

        createdBy: "ADMIN",

        modifiedBy: "ADMIN"

      };


      const url = selectedTemplateId

        ? `${API}/check-templates/${selectedTemplateId}`

        : `${API}/check-templates`;


      const method =
        selectedTemplateId ? "PUT" : "POST";


      const response = await fetch(url, {

        method,

        headers: {
          "Content-Type": "application/json"
        },

        body: JSON.stringify(payload)

      });


      const data = await response.json();


      if (!data.success) {

        alert(data.message);

        return;

      }


      setMessage(data.message);

      await loadTemplates();


      if (!selectedTemplateId && data.templateId) {

        setSelectedTemplateId(
          data.templateId
        );

      }


    } catch (error) {

      console.error(error);

      alert(
        "Unable to save template"
      );

    } finally {

      setLoading(false);

    }

  }


  /* =========================================================
     DELETE
  ========================================================= */

  async function deleteTemplate() {

    if (!selectedTemplateId) {
      return;
    }


    if (
      !window.confirm(
        "Delete this check template?"
      )
    ) {
      return;
    }


    try {

      const response = await fetch(
        `${API}/check-templates/${selectedTemplateId}`,
        {
          method: "DELETE"
        }
      );

      const data = await response.json();

      if (!data.success) {

        alert(data.message);

        return;

      }


      newTemplate();

      await loadTemplates();

    } catch (error) {

      console.error(error);

    }

  }


  /* =========================================================
     POSITION UPDATE
  ========================================================= */

  function moveElement(element, x, y) {

    if (element === "date") {

      setForm(prev => ({
        ...prev,
        dateX: x,
        dateY: y
      }));

    }

    if (element === "payee") {

      setForm(prev => ({
        ...prev,
        payeeX: x,
        payeeY: y
      }));

    }

    if (element === "words") {

      setForm(prev => ({
        ...prev,
        amountWordsX: x,
        amountWordsY: y
      }));

    }

    if (element === "amount") {

      setForm(prev => ({
        ...prev,
        amountX: x,
        amountY: y
      }));

    }

  }


  return (

    <div className="min-h-screen bg-gray-50 p-6">

      {/* ===================================================
          HEADER
      =================================================== */}

      <div className="flex items-center justify-between mb-6">

        <div>

          <h1 className="text-3xl font-bold text-gray-900">
            Check Templates
          </h1>

          <p className="text-gray-500 mt-1">
            Configure bank check printing templates
          </p>

        </div>


        <button
          onClick={newTemplate}
          className="bg-amber-500 hover:bg-amber-600 text-white px-5 py-3 rounded-lg font-semibold"
        >
          + New Template
        </button>

      </div>


      {/* ===================================================
          TEMPLATE SELECTOR
      =================================================== */}

      <div className="bg-white border rounded-xl p-5 mb-6">

        <div className="flex flex-wrap gap-3">

          {templates.map(template => (

            <button
              key={template.TemplateID}
              onClick={() =>
                editTemplate(
                  template.TemplateID
                )
              }
              className={`px-5 py-3 rounded-lg border ${
                selectedTemplateId ===
                template.TemplateID

                  ? "bg-amber-500 text-white border-amber-500"

                  : "bg-white hover:bg-gray-50"
              }`}
            >

              {template.TemplateName}

            </button>

          ))}

        </div>

      </div>


      {/* ===================================================
          TEMPLATE INFORMATION
      =================================================== */}

      <div className="bg-white border rounded-xl p-6 mb-6">

        <h2 className="text-xl font-semibold mb-5">
          Template Information
        </h2>


        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">

          <div>

            <label className="block text-sm font-medium mb-2">
              Template Name
            </label>

            <input
              value={form.templateName}
              onChange={e =>
                updateField(
                  "templateName",
                  e.target.value
                )
              }
              className="w-full border rounded-lg px-4 py-3"
              placeholder="BOC"
            />

          </div>


          <div>

            <label className="block text-sm font-medium mb-2">
              Bank Name
            </label>

            <input
              value={form.bankName}
              onChange={e =>
                updateField(
                  "bankName",
                  e.target.value
                )
              }
              className="w-full border rounded-lg px-4 py-3"
              placeholder="Bank name"
            />

          </div>

        </div>

      </div>


      {/* ===================================================
          ASSIGNED BANK ACCOUNTS
      =================================================== */}

      <div className="bg-white border rounded-xl p-6 mb-6">

        <div className="flex justify-between mb-5">

          <div>

            <h2 className="text-xl font-semibold">
              Assigned Bank Accounts
            </h2>

            <p className="text-sm text-gray-500 mt-1">
              Select accounts that will use this template
            </p>

          </div>

        </div>


        <div className="border rounded-xl p-5 grid grid-cols-1 md:grid-cols-2 gap-3">

          {accounts.map(account => {

            const id =
              Number(account.AccountID);

            const checked =
              selectedAccounts.includes(id);


            return (

              <label
                key={id}
                className={`flex items-start gap-3 p-3 rounded-lg cursor-pointer ${
                  checked
                    ? "bg-amber-50"
                    : "hover:bg-gray-50"
                }`}
              >

                <input
                  type="checkbox"
                  checked={checked}
                  onChange={() =>
                    toggleAccount(id)
                  }
                  className="mt-1 h-4 w-4 accent-amber-500"
                />


                <div>

                  <div className="font-medium">
                    {account.AccountName}
                  </div>

                  <div className="text-sm text-gray-500">

                    {account.AccountNumber}

                    {account.BankName &&
                      ` (${account.BankName})`
                    }

                  </div>

                </div>

              </label>

            );

          })}

        </div>

      </div>


      {/* ===================================================
          GLOBAL SETTINGS
      =================================================== */}

      <div className="bg-white border rounded-xl p-6 mb-6">

        <h2 className="text-xl font-semibold mb-5">
          Global Settings
        </h2>


        <div className="grid grid-cols-1 md:grid-cols-3 gap-5">

          <NumberInput
            label="Check Width (mm)"
            value={form.checkWidth}
            onChange={v =>
              numberField(
                "checkWidth",
                v
              )
            }
          />

          <NumberInput
            label="Check Height (mm)"
            value={form.checkHeight}
            onChange={v =>
              numberField(
                "checkHeight",
                v
              )
            }
          />

          <NumberInput
            label="Stub Width (mm)"
            value={form.stubWidth}
            onChange={v =>
              numberField(
                "stubWidth",
                v
              )
            }
          />

        </div>


        <div className="mt-5">

          <label className="flex items-center gap-3 cursor-pointer">

            <input
              type="checkbox"
              checked={form.showCounterfoil}
              onChange={e =>
                updateField(
                  "showCounterfoil",
                  e.target.checked
                )
              }
              className="h-5 w-5 accent-amber-500"
            />

            <span className="font-medium">
              Show Counterfoil / Stub
            </span>

          </label>

        </div>

      </div>


      {/* ===================================================
          FONT SETTINGS
      =================================================== */}

      <div className="bg-white border rounded-xl p-6 mb-6">

        <h2 className="text-xl font-semibold mb-5">
          Font Sizes (pixels)
        </h2>


        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">

          <NumberInput
            label="Date Font Size"
            value={form.dateFontSize}
            onChange={v =>
              numberField(
                "dateFontSize",
                v
              )
            }
          />


          <NumberInput
            label="Payee Font Size"
            value={form.payeeFontSize}
            onChange={v =>
              numberField(
                "payeeFontSize",
                v
              )
            }
          />


          <NumberInput
            label="Amount Words Font Size"
            value={form.amountWordsFontSize}
            onChange={v =>
              numberField(
                "amountWordsFontSize",
                v
              )
            }
          />


          <NumberInput
            label="Amount Words Line Height"
            value={form.amountWordsLineHeight}
            step="0.1"
            onChange={v =>
              numberField(
                "amountWordsLineHeight",
                v
              )
            }
          />


          <NumberInput
            label="Amount Numbers Font Size"
            value={form.amountNumbersFontSize}
            onChange={v =>
              numberField(
                "amountNumbersFontSize",
                v
              )
            }
          />

        </div>

      </div>


      {/* ===================================================
          LABEL SETTINGS
      =================================================== */}

      <div className="bg-white border rounded-xl p-6 mb-6">

        <h2 className="text-xl font-semibold mb-5">
          Check Labels
        </h2>


        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">

          <TextInput
            label="Payee Label"
            value={form.payeeLabel}
            onChange={v =>
              updateField(
                "payeeLabel",
                v
              )
            }
          />


          <TextInput
            label="Amount Label"
            value={form.amountLabel}
            onChange={v =>
              updateField(
                "amountLabel",
                v
              )
            }
          />

        </div>

      </div>


      {/* ===================================================
          POSITION SETTINGS
      =================================================== */}

      <div className="bg-white border rounded-xl p-6 mb-6">

        <h2 className="text-xl font-semibold mb-5">
          Element Positions
        </h2>

        <p className="text-sm text-gray-500 mb-5">
          All positions are in millimeters.
        </p>


        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">


          <PositionBox
            title="Date"
            x={form.dateX}
            y={form.dateY}
            onX={v =>
              numberField(
                "dateX",
                v
              )
            }
            onY={v =>
              numberField(
                "dateY",
                v
              )
            }
          />


          <PositionBox
            title="Payee"
            x={form.payeeX}
            y={form.payeeY}
            onX={v =>
              numberField(
                "payeeX",
                v
              )
            }
            onY={v =>
              numberField(
                "payeeY",
                v
              )
            }
          />


          <PositionBox
            title="Amount in Words"
            x={form.amountWordsX}
            y={form.amountWordsY}
            onX={v =>
              numberField(
                "amountWordsX",
                v
              )
            }
            onY={v =>
              numberField(
                "amountWordsY",
                v
              )
            }
          />


          <PositionBox
            title="Amount"
            x={form.amountX}
            y={form.amountY}
            onX={v =>
              numberField(
                "amountX",
                v
              )
            }
            onY={v =>
              numberField(
                "amountY",
                v
              )
            }
          />

        </div>

      </div>


      {/* ===================================================
          PREVIEW
      =================================================== */}

      <div className="bg-white border rounded-xl p-6 mb-6">

        <div className="text-center mb-5">

          <h2 className="text-xl font-semibold">
            Template: {form.templateName}
          </h2>

          <p className="text-gray-500">
            Bank: {form.bankName}
          </p>

          <p className="text-sm text-gray-400">
            All values in millimeters
          </p>

        </div>


        <div className="overflow-auto border rounded-lg p-8 bg-gray-50">

          <CheckPreview
            form={form}
            activeElement={activeElement}
            setActiveElement={setActiveElement}
          />

        </div>

      </div>


      {/* ===================================================
          BUTTONS
      =================================================== */}

      <div className="flex justify-end gap-3">

        {selectedTemplateId && (

          <button
            onClick={deleteTemplate}
            className="px-5 py-3 border border-red-300 text-red-600 rounded-lg hover:bg-red-50"
          >
            Delete
          </button>

        )}


        <button
          onClick={newTemplate}
          className="px-5 py-3 border rounded-lg"
        >
          Reset
        </button>


        <button
          onClick={saveTemplate}
          disabled={loading}
          className="px-6 py-3 bg-amber-500 hover:bg-amber-600 text-white rounded-lg font-semibold disabled:opacity-50"
        >
          {loading
            ? "Saving..."
            : selectedTemplateId
              ? "Update Template"
              : "Save Template"
          }
        </button>

      </div>


      {message && (

        <div className="mt-4 text-center text-green-600">
          {message}
        </div>

      )}

    </div>

  );

}


/* =========================================================
   NUMBER INPUT
========================================================= */

function NumberInput({
  label,
  value,
  onChange,
  step = "1"
}) {

  return (

    <div>

      <label className="block text-sm font-medium mb-2">
        {label}
      </label>

      <input
        type="number"
        step={step}
        value={value}
        onChange={e =>
          onChange(e.target.value)
        }
        className="w-full border rounded-lg px-4 py-3 focus:outline-none focus:ring-2 focus:ring-amber-400"
      />

    </div>

  );

}


/* =========================================================
   TEXT INPUT
========================================================= */

function TextInput({
  label,
  value,
  onChange
}) {

  return (

    <div>

      <label className="block text-sm font-medium mb-2">
        {label}
      </label>

      <input
        value={value}
        onChange={e =>
          onChange(e.target.value)
        }
        className="w-full border rounded-lg px-4 py-3 focus:outline-none focus:ring-2 focus:ring-amber-400"
      />

    </div>

  );

}


/* =========================================================
   POSITION BOX
========================================================= */

function PositionBox({
  title,
  x,
  y,
  onX,
  onY
}) {

  return (

    <div className="border rounded-xl p-4">

      <h3 className="font-semibold mb-4">
        {title}
      </h3>


      <div className="grid grid-cols-2 gap-4">

        <NumberInput
          label="X Position"
          value={x}
          onChange={onX}
          step="0.1"
        />


        <NumberInput
          label="Y Position"
          value={y}
          onChange={onY}
          step="0.1"
        />

      </div>

    </div>

  );

}


/* =========================================================
   CHECK PREVIEW
========================================================= */

function CheckPreview({
  form,
  setActiveElement
}) {

  const scale = 3;


  const width =
    Number(form.checkWidth) * scale;

  const height =
    Number(form.checkHeight) * scale;


  return (

    <div
      className="relative bg-white border-2 border-gray-300 shadow-xl mx-auto"
      style={{
        width,
        height
      }}
    >


      {/* BANK */}

      <div
        className="absolute left-5 top-4 font-bold text-lg"
      >
        {form.bankName || "BANK NAME"}
      </div>


      {/* DATE */}

      <PreviewElement
        name="date"
        label="Date"
        x={form.dateX}
        y={form.dateY}
        scale={scale}
        fontSize={form.dateFontSize}
        onClick={() =>
          setActiveElement("date")
        }
      >
        02/09/2026
      </PreviewElement>


      {/* PAYEE */}

      <PreviewElement
        name="payee"
        label={form.payeeLabel}
        x={form.payeeX}
        y={form.payeeY}
        scale={scale}
        fontSize={form.payeeFontSize}
        onClick={() =>
          setActiveElement("payee")
        }
      >

        TEST SUPPLIER PVT LTD

      </PreviewElement>


      {/* AMOUNT WORDS */}

      <PreviewElement
        name="words"
        label="Amount in Words"
        x={form.amountWordsX}
        y={form.amountWordsY}
        scale={scale}
        fontSize={form.amountWordsFontSize}
        onClick={() =>
          setActiveElement("words")
        }
        width={150}
      >

        Thirty Five Thousand Rupees Only

      </PreviewElement>


      {/* AMOUNT */}

      <PreviewElement
        name="amount"
        label={form.amountLabel}
        x={form.amountX}
        y={form.amountY}
        scale={scale}
        fontSize={form.amountNumbersFontSize}
        onClick={() =>
          setActiveElement("amount")
        }
      >

        Rs. 35,000.00

      </PreviewElement>


      {/* OR BEARER */}

      <div
        className="absolute border-b-2 border-gray-500"
        style={{
          right: 20,
          top: height * 0.35,
          width: 130
        }}
      >

        <span className="text-xs">
          Or Bearer
        </span>

      </div>


      {/* SIGNATURE */}

      <div
        className="absolute bottom-6 right-8 text-xs text-gray-500"
      >
        Authorized Signature
      </div>


      {/* COUNTERFOIL */}

      {form.showCounterfoil && (

        <div
          className="absolute left-0 top-0 h-full border-r-2 border-dashed border-gray-400 bg-gray-50"
          style={{
            width:
              Number(form.stubWidth) * scale
          }}
        >

          <div className="p-3 text-[10px] space-y-2">

            <div className="font-bold">
              COUNTERFOIL
            </div>

            <div>
              Check: 000123
            </div>

            <div>
              Date: 02/09/2026
            </div>

            <div>
              Pay: TEST SUPPLIER
            </div>

            <div>
              Amt: Rs. 35000.00
            </div>

          </div>

        </div>

      )}

    </div>

  );

}


/* =========================================================
   PREVIEW ELEMENT
========================================================= */

function PreviewElement({
  x,
  y,
  scale,
  fontSize,
  label,
  children,
  onClick,
  width
}) {

  return (

    <div
      onClick={onClick}
      className="absolute cursor-pointer border border-transparent hover:border-blue-400 hover:bg-blue-50/30 p-1 rounded"
      style={{
        left:
          Number(x) * scale,

        top:
          Number(y) * scale,

        fontSize:
          Number(fontSize),

        width:
          width
            ? width * scale
            : "auto"
      }}
    >

      <div className="text-xs text-gray-500">
        {label}
      </div>

      <div className="font-semibold whitespace-nowrap">
        {children}
      </div>

    </div>

  );

}