// ============================================================
// Employee.jsx — with Permission Support (mirrors products.jsx)
// ============================================================
import React, {
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
} from "react";
import axios from "axios";

import {
  Plus,
  Save,
  Search,
  Edit,
  Trash2,
  X,
  MapPin,
  RefreshCw,
  User,
  Users,
  Phone,
  CreditCard,
  Percent,
} from "lucide-react";

import { AuthContext } from "./SERVER/AuthContext.js";
import { usePermissions as usePermissionsContext } from "../context/PermissionsContext";

// ------------------------------------------------------------
// Adapter: exposes the API Employee.jsx expects —
//   can(module, "Add" | "Edit" | "Delete" | "View" | "Print")
//   canField(module, "MaximumDiscount" | "MinimumDiscount" |
//                    "CreditLimit" | "PurchaseLimit")
// backed by the PermissionsContext.
// ------------------------------------------------------------
const ACTION_TO_COLUMN = {
  View:   "CanView",
  Add:    "CanAdd",
  Edit:   "CanEdit",
  Delete: "CanDelete",
  Print:  "CanPrint",
};

const FIELD_TO_COLUMN = {
  MaximumDiscount: "CanViewMaximumDiscount",
  MinimumDiscount: "CanViewMinimumDiscount",
  CreditLimit:     "CanViewCreditLimit",
  PurchaseLimit:   "CanViewPurchaseLimit",
};

function usePermissions() {
  const ctx = usePermissionsContext();

  const can = useCallback(
    (moduleName, action = "View") => {
      const column = ACTION_TO_COLUMN[action] || action;
      return ctx.can(moduleName, null, column);
    },
    [ctx]
  );

  const canField = useCallback(
    (moduleName, field) => {
      const column = FIELD_TO_COLUMN[field];
      if (!column) return true; // unknown field → don't hide it
      return ctx.can(moduleName, null, column);
    },
    [ctx]
  );

  return {
    permissions: ctx.permissions,
    loading: ctx.loading,
    error: ctx.error,
    reload: ctx.reload,
    can,
    canField,
  };
}

const API_URL = "http://localhost:5000";

const EMPTY_FORM = {
  code: "",
  employeename: "",
  title: "",
  gender: "",
  referenceno: "",
  designation: "",
  address: "",
  mobile: "",
  location: "",
  locationName: "",
  maximumdiscount: "",
  minimumdiscount: "",
  creditlimit: "",
  purchaselimit: "",
  isactive: "1",
};

function Employee() {
  const { user } = useContext(AuthContext);

  // =========================================================
  // PERMISSIONS
  // =========================================================
  const { can, canField } = usePermissions();

  const canViewEmployee   = can("Employee", "View");
  const canAddEmployee    = can("Employee", "Add");
  const canEditEmployee   = can("Employee", "Edit");
  const canDeleteEmployee = can("Employee", "Delete");

  const canViewMinDiscount   = canField("Employee", "MinimumDiscount");
  const canViewMaxDiscount   = canField("Employee", "MaximumDiscount");
  const canViewCreditLimit   = canField("Employee", "CreditLimit");
  const canViewPurchaseLimit = canField("Employee", "PurchaseLimit");

  // =========================================================
  // FORM
  // =========================================================

  const [form, setForm] = useState(EMPTY_FORM);

  // =========================================================
  // DATA
  // =========================================================

  const [employees, setEmployees] = useState([]);
  const [locations, setLocations] = useState([]);

  // =========================================================
  // STATES
  // =========================================================

  const [editingID, setEditingID] = useState(null);

  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [generatingCode, setGeneratingCode] = useState(false);

  const [searchText, setSearchText] = useState("");

  const [showLocationModal, setShowLocationModal] = useState(false);
  const [locationSearch, setLocationSearch] = useState("");

  // =========================================================
  // REFS
  // =========================================================

  const codeRef = useRef(null);
  const employeeNameRef = useRef(null);
  const locationSearchRef = useRef(null);

  // =========================================================
  // LOAD EMPLOYEES
  // =========================================================

  const loadEmployees = async () => {
    try {
      setLoading(true);

      const response = await axios.get(`${API_URL}/employee`);

      if (response.data?.success) {
        setEmployees(response.data.data || []);
      } else {
        setEmployees([]);
        alert(response.data?.message || "Unable to load employees.");
      }
    } catch (error) {
      console.error("LOAD EMPLOYEES ERROR:", error);
      alert(
        error.response?.data?.message ||
          error.message ||
          "Unable to load employees."
      );
    } finally {
      setLoading(false);
    }
  };

  // =========================================================
  // LOAD LOCATIONS
  // =========================================================

  const loadLocations = async () => {
    try {
      const response = await axios.get(`${API_URL}/Locations`);

      if (response.data?.success) {
        setLocations(response.data.data || []);
      } else {
        setLocations([]);
        console.error(response.data?.message || "Unable to load locations.");
      }
    } catch (error) {
      console.error("LOAD LOCATIONS ERROR:", error);
      alert(
        error.response?.data?.message ||
          error.message ||
          "Unable to load locations."
      );
    }
  };

  // =========================================================
  // INITIAL LOAD
  // =========================================================

  useEffect(() => {
    loadEmployees();
    loadLocations();
  }, []);

  // =========================================================
  // HANDLE FORM CHANGE
  // =========================================================

  const handleChange = (event) => {
    const { name, value } = event.target;
    setForm((previous) => ({ ...previous, [name]: value }));
  };

  // =========================================================
  // GENERATE EMPLOYEE CODE
  // =========================================================

  const generateEmployeeCode = async () => {
    try {
      setGeneratingCode(true);

      const response = await axios.get(`${API_URL}/employee/next-code`);

      if (response.data?.success && response.data?.code) {
        setForm((previous) => ({ ...previous, code: response.data.code }));
      } else {
        throw new Error(
          response.data?.message || "Unable to generate employee code."
        );
      }
    } catch (error) {
      console.error("GENERATE EMPLOYEE CODE ERROR:", error);
      alert(
        error.response?.data?.message ||
          error.message ||
          "Unable to generate employee code."
      );
    } finally {
      setGeneratingCode(false);
    }
  };

  // =========================================================
  // NEW EMPLOYEE
  // =========================================================

  const handleNewEmployee = async () => {
    if (!canAddEmployee) {
      alert("You do not have permission to create employees.");
      return;
    }

    setEditingID(null);
    setForm({ ...EMPTY_FORM });
    setSearchText("");

    await generateEmployeeCode();

    setTimeout(() => {
      employeeNameRef.current?.focus();
    }, 100);
  };

  // =========================================================
  // CLEAR
  // =========================================================

  const handleClear = () => {
    setEditingID(null);
    setForm({ ...EMPTY_FORM });

    setTimeout(() => {
      employeeNameRef.current?.focus();
    }, 100);
  };

  // =========================================================
  // LOCATION DISPLAY
  // =========================================================

  const makeLocationText = (location) => {
    const code = location?.LocationCode || "";
    const name = location?.LocationName || "";

    if (code && name) {
      return `${code} - ${name}`;
    }

    return code || name || "";
  };

  // =========================================================
  // OPEN / CLOSE LOCATION MODAL
  // =========================================================

  const openLocationModal = () => {
    setLocationSearch("");
    setShowLocationModal(true);

    setTimeout(() => {
      locationSearchRef.current?.focus();
    }, 100);
  };

  const closeLocationModal = () => {
    setShowLocationModal(false);
    setLocationSearch("");
  };

  // =========================================================
  // SELECT LOCATION
  //
  // IMPORTANT:
  // Employee.location is NVARCHAR(150)
  // so we save the location text.
  // =========================================================

  const handleSelectLocation = (location) => {
    const locationText = makeLocationText(location);

    setForm((previous) => ({
      ...previous,
      location: locationText,
      locationName: locationText,
    }));

    closeLocationModal();

    setTimeout(() => {
      employeeNameRef.current?.focus();
    }, 100);
  };

  // =========================================================
  // KEYBOARD
  //
  // F12 = Location
  // ESC = Close Location
  // =========================================================

  const handleKeyDown = (event) => {
    if (event.key === "F12") {
      event.preventDefault();
      openLocationModal();
      return;
    }

    if (event.key === "Escape" && showLocationModal) {
      event.preventDefault();
      closeLocationModal();
    }
  };

  // =========================================================
  // EDIT
  // =========================================================

  const handleEdit = (employee) => {
    if (!canEditEmployee) {
      alert("You do not have permission to edit employees.");
      return;
    }

    if (!employee?.EmployeeID) {
      alert("Invalid Employee ID.");
      return;
    }

    setEditingID(employee.EmployeeID);

    const locationText = employee.location || "";

    setForm({
      code: employee.EmployeeCode || "",
      employeename: employee.EmployeeName || "",
      title:
        employee.EmployeeTitle !== null && employee.EmployeeTitle !== undefined
          ? String(employee.EmployeeTitle)
          : "",
      gender:
        employee.Gender !== null && employee.Gender !== undefined
          ? String(employee.Gender)
          : "",
      referenceno: employee.ReferenceNo || "",
      designation: employee.Designation || "",
      address: employee.Address1 || "",
      mobile: employee.Mobile || "",
      location: locationText,
      locationName: locationText,
      maximumdiscount:
        employee.MaximumDiscount !== null &&
        employee.MaximumDiscount !== undefined
          ? String(employee.MaximumDiscount)
          : "",
      minimumdiscount:
        employee.MinimumDiscount !== null &&
        employee.MinimumDiscount !== undefined
          ? String(employee.MinimumDiscount)
          : "",
      creditlimit:
        employee.CrLimit !== null && employee.CrLimit !== undefined
          ? String(employee.CrLimit)
          : "",
      purchaselimit:
        employee.PchLimit !== null && employee.PchLimit !== undefined
          ? String(employee.PchLimit)
          : "",
      isactive:
        employee.IsActive === true ||
        employee.IsActive === 1 ||
        employee.IsActive === "1"
          ? "1"
          : "0",
    });

    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  // =========================================================
  // DELETE
  // =========================================================

  const handleDelete = async (employee) => {
    if (!canDeleteEmployee) {
      alert("You do not have permission to delete employees.");
      return;
    }

    if (!employee?.EmployeeID) {
      alert("Invalid Employee ID.");
      return;
    }

    const confirmed = window.confirm(
      `Are you sure you want to delete employee "${employee.EmployeeName}"?`
    );

    if (!confirmed) return;

    try {
      setLoading(true);

      const response = await axios.delete(
        `${API_URL}/employee/${employee.EmployeeID}`
      );

      if (response.data?.success) {
        alert(response.data.message || "Employee deleted successfully.");

        if (String(editingID) === String(employee.EmployeeID)) {
          handleClear();
        }

        await loadEmployees();
      } else {
        alert(response.data?.message || "Unable to delete employee.");
      }
    } catch (error) {
      console.error("DELETE EMPLOYEE ERROR:", error);
      alert(
        error.response?.data?.message ||
          error.message ||
          "Unable to delete employee."
      );
    } finally {
      setLoading(false);
    }
  };

  // =========================================================
  // VALIDATE
  // =========================================================

  const validateForm = () => {
    if (!form.code.trim()) {
      alert("Employee Code is required.");
      codeRef.current?.focus();
      return false;
    }

    if (!form.employeename.trim()) {
      alert("Employee Name is required.");
      employeeNameRef.current?.focus();
      return false;
    }

    if (!form.location.trim()) {
      alert("Location is required.");
      return false;
    }

    if (canViewMinDiscount && form.minimumdiscount !== "") {
      const value = Number(form.minimumdiscount);
      if (Number.isNaN(value) || value < 0) {
        alert("Invalid Minimum Discount.");
        return false;
      }
    }

    if (canViewMaxDiscount && form.maximumdiscount !== "") {
      const value = Number(form.maximumdiscount);
      if (Number.isNaN(value) || value < 0) {
        alert("Invalid Maximum Discount.");
        return false;
      }
    }

    if (
      canViewMinDiscount &&
      canViewMaxDiscount &&
      form.minimumdiscount !== "" &&
      form.maximumdiscount !== ""
    ) {
      if (Number(form.minimumdiscount) > Number(form.maximumdiscount)) {
        alert("Minimum Discount cannot be greater than Maximum Discount.");
        return false;
      }
    }

    if (canViewCreditLimit && form.creditlimit !== "") {
      const value = Number(form.creditlimit);
      if (Number.isNaN(value) || value < 0) {
        alert("Invalid Credit Limit.");
        return false;
      }
    }

    if (canViewPurchaseLimit && form.purchaselimit !== "") {
      const value = Number(form.purchaselimit);
      if (Number.isNaN(value) || value < 0) {
        alert("Invalid Purchase Limit.");
        return false;
      }
    }

    return true;
  };

  // =========================================================
  // SAVE
  // =========================================================

  const handleSubmit = async (event) => {
    event.preventDefault();

    // ----- Permission guards -----
    if (editingID && !canEditEmployee) {
      alert("You do not have permission to edit employees.");
      return;
    }

    if (!editingID && !canAddEmployee) {
      alert("You do not have permission to create employees.");
      return;
    }

    if (!validateForm()) {
      return;
    }

    const payload = {
      code: form.code.trim(),
      employeename: form.employeename.trim(),
      title: form.title === "" ? 0 : Number(form.title),
      gender: form.gender === "" ? 0 : Number(form.gender),
      referenceno: form.referenceno.trim(),
      designation: form.designation.trim(),
      address: form.address.trim(),
      mobile: form.mobile.trim(),
      // IMPORTANT: NVARCHAR(150) — save text
      location: form.location.trim(),
      isactive: form.isactive === "1",
    };

    // Only include the fields the user can view, so we don't
    // overwrite values the user can't see when editing.
    if (canViewMaxDiscount) {
      payload.maximumdiscount =
        form.maximumdiscount === "" ? 0 : Number(form.maximumdiscount);
    }
    if (canViewMinDiscount) {
      payload.minimumdiscount =
        form.minimumdiscount === "" ? 0 : Number(form.minimumdiscount);
    }
    if (canViewCreditLimit) {
      payload.creditlimit =
        form.creditlimit === "" ? 0 : Number(form.creditlimit);
    }
    if (canViewPurchaseLimit) {
      payload.purchaselimit =
        form.purchaselimit === "" ? 0 : Number(form.purchaselimit);
    }

    try {
      setSaving(true);

      let response;

      if (editingID) {
        response = await axios.put(
          `${API_URL}/employee/${editingID}`,
          payload
        );
      } else {
        response = await axios.post(`${API_URL}/employee`, payload);
      }

      if (response.data?.success) {
        alert(
          response.data.message ||
            (editingID
              ? "Employee updated successfully."
              : "Employee saved successfully.")
        );

        await loadEmployees();

        setEditingID(null);
        setForm({ ...EMPTY_FORM });

        if (!editingID) {
          await generateEmployeeCode();
        }
      } else {
        alert(response.data?.message || "Unable to save employee.");
      }
    } catch (error) {
      console.error("SAVE EMPLOYEE ERROR:", error);
      alert(
        error.response?.data?.message ||
          error.message ||
          "Unable to save employee."
      );
    } finally {
      setSaving(false);
    }
  };

  // =========================================================
  // SEARCH EMPLOYEES
  // =========================================================

  const filteredEmployees = employees.filter((employee) => {
    const search = searchText.trim().toLowerCase();

    if (!search) return true;

    return (
      String(employee.EmployeeCode || "").toLowerCase().includes(search) ||
      String(employee.EmployeeName || "").toLowerCase().includes(search) ||
      String(employee.Designation || "").toLowerCase().includes(search) ||
      String(employee.Mobile || "").toLowerCase().includes(search) ||
      String(employee.location || "").toLowerCase().includes(search)
    );
  });

  // =========================================================
  // SEARCH LOCATIONS
  // =========================================================

  const filteredLocations = locations.filter((location) => {
    const search = locationSearch.trim().toLowerCase();

    if (!search) return true;

    return (
      String(location.LocationID || "").toLowerCase().includes(search) ||
      String(location.LocationCode || "").toLowerCase().includes(search) ||
      String(location.LocationName || "").toLowerCase().includes(search)
    );
  });

  // =========================================================
  // COMPUTED
  // =========================================================

  const saveAllowed =
    (editingID && canEditEmployee) || (!editingID && canAddEmployee);

  // =========================================================
  // RENDER
  // =========================================================

  return (
    <div
      className="min-h-screen bg-slate-100 p-4 md:p-6"
      onKeyDown={handleKeyDown}
    >
      {/* =====================================================
          HEADER
      ===================================================== */}

      <div className="mb-5 flex flex-col gap-3 rounded-xl bg-white p-4 shadow-sm md:flex-row md:items-center md:justify-between">
        <div className="flex items-center gap-3">
          <div className="rounded-lg bg-blue-600 p-2 text-white">
            <Users size={22} />
          </div>

          <div>
            <h1 className="text-xl font-bold text-slate-800">
              Employee Master
            </h1>
            <p className="text-sm text-slate-500">Employee management</p>
          </div>
        </div>

        <div className="flex flex-wrap gap-2">
          {canAddEmployee && (
            <button
              type="button"
              onClick={handleNewEmployee}
              disabled={saving || generatingCode}
              className="flex items-center gap-2 rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {generatingCode ? (
                <RefreshCw size={18} className="animate-spin" />
              ) : (
                <Plus size={18} />
              )}
              New Employee
            </button>
          )}

          <button
            type="button"
            onClick={loadEmployees}
            disabled={loading}
            className="flex items-center gap-2 rounded-lg border border-slate-300 bg-white px-4 py-2.5 text-sm font-semibold text-slate-700 hover:bg-slate-50 disabled:opacity-50"
          >
            <RefreshCw
              size={17}
              className={loading ? "animate-spin" : ""}
            />
            Refresh
          </button>
        </div>
      </div>

      {/* =====================================================
          FORM
      ===================================================== */}

      <form onSubmit={handleSubmit} className="mb-6 rounded-xl bg-white shadow-sm">
        <div className="flex flex-col gap-2 border-b border-slate-200 px-5 py-4 md:flex-row md:items-center md:justify-between">
          <div className="flex items-center gap-2">
            <User size={19} className="text-blue-600" />
            <h2 className="font-semibold text-slate-800">
              {editingID ? "Edit Employee" : "Employee Details"}
            </h2>
          </div>

          <div className="flex items-center gap-2">
            {editingID && (
              <span className="rounded-full bg-amber-100 px-3 py-1 text-xs font-semibold text-amber-700">
                Editing ID: {editingID}
              </span>
            )}
            {editingID && !canEditEmployee && (
              <span className="rounded-full bg-slate-200 px-3 py-1 text-xs font-semibold text-slate-600">
                READ ONLY
              </span>
            )}
          </div>
        </div>

        <div className="p-5">
          {/* =================================================
              BASIC DETAILS
          ================================================= */}

          <div className="grid grid-cols-1 gap-4 md:grid-cols-4">
            {/* CODE */}

            <div>
              <label className="mb-1.5 block text-sm font-medium text-slate-700">
                Employee Code
              </label>

              <div className="flex">
                <input
                  ref={codeRef}
                  type="text"
                  name="code"
                  value={form.code}
                  onChange={handleChange}
                  readOnly={!editingID}
                  maxLength={15}
                  className={`w-full rounded-l-lg border border-r-0 border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 ${
                    !editingID ? "bg-slate-100" : "bg-white"
                  }`}
                  placeholder="EMP001"
                />

                {!editingID && canAddEmployee && (
                  <button
                    type="button"
                    onClick={generateEmployeeCode}
                    disabled={generatingCode}
                    className="rounded-r-lg border border-blue-600 bg-blue-600 px-3 text-white hover:bg-blue-700 disabled:opacity-50"
                    title="Generate Employee Code"
                  >
                    <RefreshCw
                      size={17}
                      className={generatingCode ? "animate-spin" : ""}
                    />
                  </button>
                )}
              </div>

              {!editingID && (
                <p className="mt-1 text-xs text-slate-400">
                  Automatically generated
                </p>
              )}
            </div>

            {/* NAME */}

            <div>
              <label className="mb-1.5 block text-sm font-medium text-slate-700">
                Employee Name <span className="text-red-500">*</span>
              </label>

              <input
                ref={employeeNameRef}
                type="text"
                name="employeename"
                value={form.employeename}
                onChange={handleChange}
                maxLength={100}
                className="w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                placeholder="Employee name"
              />
            </div>

            {/* TITLE */}

            <div>
              <label className="mb-1.5 block text-sm font-medium text-slate-700">
                Title
              </label>

              <select
                name="title"
                value={form.title}
                onChange={handleChange}
                className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
              >
                <option value="">Select Title</option>
                <option value="1">Mr</option>
                <option value="2">Mrs</option>
                <option value="3">Miss</option>
              </select>
            </div>

            {/* GENDER */}

            <div>
              <label className="mb-1.5 block text-sm font-medium text-slate-700">
                Gender
              </label>

              <select
                name="gender"
                value={form.gender}
                onChange={handleChange}
                className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
              >
                <option value="">Select Gender</option>
                <option value="1">Male</option>
                <option value="2">Female</option>
              </select>
            </div>
          </div>

          {/* =================================================
              SECOND ROW
          ================================================= */}

          <div className="mt-4 grid grid-cols-1 gap-4 md:grid-cols-4">
            {/* DESIGNATION */}

            <div>
              <label className="mb-1.5 block text-sm font-medium text-slate-700">
                Designation
              </label>

              <input
                type="text"
                name="designation"
                value={form.designation}
                onChange={handleChange}
                maxLength={100}
                className="w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                placeholder="Designation"
              />
            </div>

            {/* REFERENCE */}

            <div>
              <label className="mb-1.5 block text-sm font-medium text-slate-700">
                Reference No
              </label>

              <input
                type="text"
                name="referenceno"
                value={form.referenceno}
                onChange={handleChange}
                maxLength={25}
                className="w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                placeholder="Reference number"
              />
            </div>

            {/* MOBILE */}

            <div>
              <label className="mb-1.5 block text-sm font-medium text-slate-700">
                Mobile
              </label>

              <div className="relative">
                <Phone
                  size={17}
                  className="absolute left-3 top-3 text-slate-400"
                />

                <input
                  type="text"
                  name="mobile"
                  value={form.mobile}
                  onChange={handleChange}
                  maxLength={50}
                  className="w-full rounded-lg border border-slate-300 py-2.5 pl-10 pr-3 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                  placeholder="Mobile number"
                />
              </div>
            </div>

            {/* LOCATION */}

            <div>
              <label className="mb-1.5 block text-sm font-medium text-slate-700">
                Location <span className="text-red-500">*</span>
              </label>

              <div className="flex">
                <input
                  type="text"
                  name="locationName"
                  value={form.locationName}
                  readOnly
                  onClick={openLocationModal}
                  onKeyDown={handleKeyDown}
                  className="w-full cursor-pointer rounded-l-lg border border-r-0 border-slate-300 bg-slate-50 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                  placeholder="Press F12"
                />

                <button
                  type="button"
                  onClick={openLocationModal}
                  className="rounded-r-lg border border-blue-600 bg-blue-600 px-3 text-white hover:bg-blue-700"
                  title="Select Location - F12"
                >
                  <MapPin size={17} />
                </button>
              </div>

              <p className="mt-1 text-xs text-slate-400">
                Press F12 to select location
              </p>
            </div>
          </div>

          {/* =================================================
              ADDRESS
          ================================================= */}

          <div className="mt-4">
            <label className="mb-1.5 block text-sm font-medium text-slate-700">
              Address
            </label>

            <input
              type="text"
              name="address"
              value={form.address}
              onChange={handleChange}
              maxLength={100}
              className="w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
              placeholder="Employee address"
            />
          </div>

          {/* =================================================
              LIMITS
          ================================================= */}

          <div className="mt-5 rounded-xl border border-slate-200 bg-slate-50 p-4">
            <div className="mb-4 flex items-center gap-2">
              <CreditCard size={18} className="text-blue-600" />
              <h3 className="font-semibold text-slate-700">
                Employee Limits
              </h3>
            </div>

            <div className="grid grid-cols-1 gap-4 md:grid-cols-4">
              {/* MIN DISCOUNT */}

              {canViewMinDiscount && (
                <div>
                  <label className="mb-1.5 block text-sm font-medium text-slate-700">
                    Minimum Discount %
                  </label>

                  <div className="relative">
                    <Percent
                      size={16}
                      className="absolute left-3 top-3 text-slate-400"
                    />

                    <input
                      type="number"
                      name="minimumdiscount"
                      value={form.minimumdiscount}
                      onChange={handleChange}
                      min="0"
                      step="0.01"
                      className="w-full rounded-lg border border-slate-300 bg-white py-2.5 pl-9 pr-3 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                      placeholder="0.00"
                    />
                  </div>
                </div>
              )}

              {/* MAX DISCOUNT */}

              {canViewMaxDiscount && (
                <div>
                  <label className="mb-1.5 block text-sm font-medium text-slate-700">
                    Maximum Discount %
                  </label>

                  <div className="relative">
                    <Percent
                      size={16}
                      className="absolute left-3 top-3 text-slate-400"
                    />

                    <input
                      type="number"
                      name="maximumdiscount"
                      value={form.maximumdiscount}
                      onChange={handleChange}
                      min="0"
                      step="0.01"
                      className="w-full rounded-lg border border-slate-300 bg-white py-2.5 pl-9 pr-3 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                      placeholder="0.00"
                    />
                  </div>
                </div>
              )}

              {/* CREDIT LIMIT */}

              {canViewCreditLimit && (
                <div>
                  <label className="mb-1.5 block text-sm font-medium text-slate-700">
                    Credit Limit
                  </label>

                  <input
                    type="number"
                    name="creditlimit"
                    value={form.creditlimit}
                    onChange={handleChange}
                    min="0"
                    step="0.01"
                    className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                    placeholder="0.00"
                  />
                </div>
              )}

              {/* PURCHASE LIMIT */}

              {canViewPurchaseLimit && (
                <div>
                  <label className="mb-1.5 block text-sm font-medium text-slate-700">
                    Purchase Limit
                  </label>

                  <input
                    type="number"
                    name="purchaselimit"
                    value={form.purchaselimit}
                    onChange={handleChange}
                    min="0"
                    step="0.01"
                    className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                    placeholder="0.00"
                  />
                </div>
              )}
            </div>

            {(!canViewMinDiscount ||
              !canViewMaxDiscount ||
              !canViewCreditLimit ||
              !canViewPurchaseLimit) && (
              <div className="mt-3 rounded-lg border border-amber-200 bg-amber-50 px-4 py-2 text-xs font-medium text-amber-700">
                Some limit fields are hidden by your permission level. Contact
                an administrator if you need access.
              </div>
            )}
          </div>

          {/* =================================================
              ACTIVE
          ================================================= */}

          <div className="mt-5 flex items-center gap-3">
            <input
              id="employee-active"
              type="checkbox"
              checked={form.isactive === "1"}
              onChange={(event) =>
                setForm((previous) => ({
                  ...previous,
                  isactive: event.target.checked ? "1" : "0",
                }))
              }
              className="h-4 w-4 rounded border-slate-300 text-blue-600"
            />

            <label
              htmlFor="employee-active"
              className="text-sm font-medium text-slate-700"
            >
              Employee is Active
            </label>
          </div>

          {/* =================================================
              BUTTONS
          ================================================= */}

          <div className="mt-6 flex flex-col gap-2 border-t border-slate-200 pt-5 sm:flex-row sm:justify-end">
            <button
              type="button"
              onClick={handleClear}
              disabled={saving}
              className="flex items-center justify-center gap-2 rounded-lg border border-slate-300 bg-white px-5 py-2.5 text-sm font-semibold text-slate-700 hover:bg-slate-50 disabled:opacity-50"
            >
              <X size={17} />
              Clear
            </button>

            {saveAllowed && (
              <button
                type="submit"
                disabled={saving || generatingCode}
                className="flex items-center justify-center gap-2 rounded-lg bg-blue-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
              >
                {saving ? (
                  <RefreshCw size={17} className="animate-spin" />
                ) : editingID ? (
                  <Save size={17} />
                ) : (
                  <Plus size={17} />
                )}

                {saving
                  ? "Saving..."
                  : editingID
                  ? "Update Employee"
                  : "Save Employee"}
              </button>
            )}

            {editingID && !canEditEmployee && (
              <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 text-xs font-semibold text-slate-500">
                You have read-only access — editing is disabled.
              </div>
            )}

            {!editingID && !canAddEmployee && (
              <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 text-xs font-semibold text-slate-500">
                You do not have permission to create new employees.
              </div>
            )}
          </div>
        </div>
      </form>

      {/* =====================================================
          EMPLOYEE TABLE
      ===================================================== */}

      <div className="rounded-xl bg-white shadow-sm">
        <div className="flex flex-col gap-3 border-b border-slate-200 p-4 md:flex-row md:items-center md:justify-between">
          <div>
            <h2 className="font-semibold text-slate-800">Employee List</h2>
            <p className="text-xs text-slate-500">
              {filteredEmployees.length} employee
              {filteredEmployees.length !== 1 ? "s" : ""}
            </p>
          </div>

          <div className="relative w-full md:w-96">
            <Search
              size={18}
              className="absolute left-3 top-3 text-slate-400"
            />

            <input
              type="text"
              value={searchText}
              onChange={(event) => setSearchText(event.target.value)}
              placeholder="Search employee..."
              className="w-full rounded-lg border border-slate-300 py-2.5 pl-10 pr-10 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
            />

            {searchText && (
              <button
                type="button"
                onClick={() => setSearchText("")}
                className="absolute right-3 top-2.5 text-slate-400 hover:text-slate-700"
              >
                <X size={18} />
              </button>
            )}
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="min-w-full text-sm">
            <thead>
              <tr className="border-b border-slate-200 bg-slate-50">
                <th className="px-4 py-3 text-left font-semibold text-slate-600">
                  #
                </th>
                <th className="px-4 py-3 text-left font-semibold text-slate-600">
                  Code
                </th>
                <th className="px-4 py-3 text-left font-semibold text-slate-600">
                  Employee Name
                </th>
                <th className="px-4 py-3 text-left font-semibold text-slate-600">
                  Designation
                </th>
                <th className="px-4 py-3 text-left font-semibold text-slate-600">
                  Mobile
                </th>
                <th className="px-4 py-3 text-left font-semibold text-slate-600">
                  Location
                </th>
                <th className="px-4 py-3 text-center font-semibold text-slate-600">
                  Status
                </th>
                <th className="px-4 py-3 text-center font-semibold text-slate-600">
                  Actions
                </th>
              </tr>
            </thead>

            <tbody>
              {loading && employees.length === 0 ? (
                <tr>
                  <td
                    colSpan="8"
                    className="px-4 py-10 text-center text-slate-500"
                  >
                    <RefreshCw
                      size={24}
                      className="mx-auto mb-2 animate-spin text-blue-600"
                    />
                    Loading employees...
                  </td>
                </tr>
              ) : filteredEmployees.length === 0 ? (
                <tr>
                  <td
                    colSpan="8"
                    className="px-4 py-10 text-center text-slate-500"
                  >
                    No employees found.
                  </td>
                </tr>
              ) : (
                filteredEmployees.map((employee, index) => {
                  const active =
                    employee.IsActive === true ||
                    employee.IsActive === 1 ||
                    employee.IsActive === "1";

                  return (
                    <tr
                      key={employee.EmployeeID}
                      className="border-b border-slate-100 hover:bg-blue-50/40"
                    >
                      <td className="px-4 py-3 text-slate-500">
                        {index + 1}
                      </td>

                      <td className="px-4 py-3 font-semibold text-blue-600">
                        {employee.EmployeeCode}
                      </td>

                      <td className="px-4 py-3 font-medium text-slate-800">
                        {employee.EmployeeName}
                      </td>

                      <td className="px-4 py-3 text-slate-600">
                        {employee.Designation}
                      </td>

                      <td className="px-4 py-3 text-slate-600">
                        {employee.Mobile}
                      </td>

                      <td className="px-4 py-3 text-slate-600">
                        <div className="flex items-center gap-2">
                          <MapPin size={15} className="text-blue-500" />
                          {employee.location}
                        </div>
                      </td>

                      <td className="px-4 py-3 text-center">
                        {active ? (
                          <span className="rounded-full bg-green-100 px-3 py-1 text-xs font-semibold text-green-700">
                            Active
                          </span>
                        ) : (
                          <span className="rounded-full bg-red-100 px-3 py-1 text-xs font-semibold text-red-700">
                            Inactive
                          </span>
                        )}
                      </td>

                      <td className="px-4 py-3">
                        <div className="flex justify-center gap-2">
                          {canEditEmployee && (
                            <button
                              type="button"
                              onClick={() => handleEdit(employee)}
                              className="flex items-center gap-1 rounded-lg border border-blue-200 bg-blue-50 px-3 py-1.5 text-xs font-semibold text-blue-600 hover:bg-blue-100"
                            >
                              <Edit size={14} />
                              Edit
                            </button>
                          )}

                          {canDeleteEmployee && (
                            <button
                              type="button"
                              onClick={() => handleDelete(employee)}
                              className="flex items-center gap-1 rounded-lg border border-red-200 bg-red-50 px-3 py-1.5 text-xs font-semibold text-red-600 hover:bg-red-100"
                            >
                              <Trash2 size={14} />
                              Delete
                            </button>
                          )}

                          {!canEditEmployee && !canDeleteEmployee && (
                            <span className="text-xs text-slate-400">
                              No actions
                            </span>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* =====================================================
          LOCATION MODAL
      ===================================================== */}

      {showLocationModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
          <div className="flex max-h-[85vh] w-full max-w-3xl flex-col overflow-hidden rounded-xl bg-white shadow-2xl">
            {/* HEADER */}

            <div className="flex items-center justify-between border-b border-slate-200 px-5 py-4">
              <div className="flex items-center gap-3">
                <div className="rounded-lg bg-blue-100 p-2 text-blue-600">
                  <MapPin size={20} />
                </div>

                <div>
                  <h2 className="font-semibold text-slate-800">
                    Select Location
                  </h2>
                  <p className="text-xs text-slate-500">
                    Select employee location
                  </p>
                </div>
              </div>

              <button
                type="button"
                onClick={closeLocationModal}
                className="rounded-lg p-2 text-slate-400 hover:bg-slate-100 hover:text-slate-700"
              >
                <X size={20} />
              </button>
            </div>

            {/* SEARCH */}

            <div className="border-b border-slate-200 p-4">
              <div className="relative">
                <Search
                  size={18}
                  className="absolute left-3 top-3 text-slate-400"
                />

                <input
                  ref={locationSearchRef}
                  type="text"
                  value={locationSearch}
                  onChange={(event) => setLocationSearch(event.target.value)}
                  placeholder="Search location..."
                  className="w-full rounded-lg border border-slate-300 py-2.5 pl-10 pr-4 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                />
              </div>
            </div>

            {/* TABLE */}

            <div className="flex-1 overflow-y-auto">
              <table className="min-w-full text-sm">
                <thead className="sticky top-0 bg-slate-50">
                  <tr className="border-b border-slate-200">
                    <th className="px-4 py-3 text-left font-semibold text-slate-600">
                      ID
                    </th>
                    <th className="px-4 py-3 text-left font-semibold text-slate-600">
                      Code
                    </th>
                    <th className="px-4 py-3 text-left font-semibold text-slate-600">
                      Location Name
                    </th>
                    <th className="px-4 py-3 text-center font-semibold text-slate-600">
                      Select
                    </th>
                  </tr>
                </thead>

                <tbody>
                  {filteredLocations.length === 0 ? (
                    <tr>
                      <td
                        colSpan="4"
                        className="px-4 py-10 text-center text-slate-500"
                      >
                        No locations found.
                      </td>
                    </tr>
                  ) : (
                    filteredLocations.map((location) => {
                      const locationText = makeLocationText(location);
                      const selected = form.location === locationText;

                      return (
                        <tr
                          key={location.LocationID}
                          onClick={() => handleSelectLocation(location)}
                          onDoubleClick={() => handleSelectLocation(location)}
                          className={`cursor-pointer border-b border-slate-100 hover:bg-blue-50 ${
                            selected ? "bg-blue-50" : ""
                          }`}
                        >
                          <td className="px-4 py-3 text-slate-500">
                            {location.LocationID}
                          </td>

                          <td className="px-4 py-3 font-semibold text-blue-600">
                            {location.LocationCode}
                          </td>

                          <td className="px-4 py-3 font-medium text-slate-700">
                            {location.LocationName}
                          </td>

                          <td className="px-4 py-3 text-center">
                            <button
                              type="button"
                              onClick={(event) => {
                                event.stopPropagation();
                                handleSelectLocation(location);
                              }}
                              className={`rounded-lg px-3 py-1.5 text-xs font-semibold ${
                                selected
                                  ? "bg-green-600 text-white"
                                  : "bg-blue-600 text-white hover:bg-blue-700"
                              }`}
                            >
                              {selected ? "Selected" : "Select"}
                            </button>
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>

            {/* FOOTER */}

            <div className="flex items-center justify-between border-t border-slate-200 bg-slate-50 px-5 py-3">
              <span className="text-xs text-slate-500">
                {filteredLocations.length} location
                {filteredLocations.length !== 1 ? "s" : ""}
              </span>

              <button
                type="button"
                onClick={closeLocationModal}
                className="rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-100"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default Employee;