import React, { useEffect, useMemo, useState, useContext } from "react";
import axios from "axios";
import {
  ShieldCheck, ShieldOff, Save, RefreshCw, Eye,
  DollarSign, TrendingUp, Check, X, Layers, AlertCircle, Lock,
} from "lucide-react";

import { usePermissions } from "../hooks/usePermissions.jsx";   // ← PERM
import { AuthContext } from "./SERVER/AuthContext.js";             // ← PERM

const API = "http://localhost:5000";

// Module that guards THIS page. Change if you prefer to piggyback
// on "Cashier" + CanEdit, or a shared "Security" module.
const PERMISSION_MODULE = "CashierPermission";                    // ← PERM

const COLUMNS = [
  { key: "CanView",             label: "View",          icon: Eye        },
  { key: "CanAdd",              label: "Add",           icon: Check      },
  { key: "CanEdit",             label: "Edit",          icon: Check      },
  { key: "CanDelete",           label: "Delete",        icon: X          },
  { key: "CanPrint",            label: "Print",         icon: Check      },
  { key: "CanViewCostPrice",    label: "Cost Price",    icon: DollarSign, accent: "amber"   },
  { key: "CanViewSellingPrice", label: "Selling Price", icon: DollarSign, accent: "blue"    },
  { key: "CanViewProfit",       label: "Profit",        icon: TrendingUp, accent: "emerald" },
];

const emptyPermission = {
  CanView: false, CanAdd: false, CanEdit: false, CanDelete: false, CanPrint: false,
  CanViewCostPrice: false, CanViewSellingPrice: false, CanViewProfit: false,
};

const pickArray = (payload) => {
  if (Array.isArray(payload)) return payload;
  if (Array.isArray(payload?.data)) return payload.data;
  if (Array.isArray(payload?.recordset)) return payload.recordset;
  if (Array.isArray(payload?.cashiers)) return payload.cashiers;
  if (Array.isArray(payload?.permissions)) return payload.permissions;
  return [];
};

const tryUrls = async (urls) => {
  const errors = [];
  for (const url of urls) {
    try {
      const res = await axios.get(url);
      console.log("[CashierPermission] GET", url, "→", res.data);
      return { ok: true, data: res.data, url };
    } catch (err) {
      const status = err?.response?.status;
      console.warn("[CashierPermission] GET", url, "FAILED status:", status);
      errors.push({ url, status, message: err.message });
    }
  }
  return { ok: false, errors };
};

export default function CashierPermission() {
  const { user } = useContext(AuthContext);                       // ← PERM

  // =========================================================
  // PERMISSIONS                                              // ← PERM
  // =========================================================
  const { can, loading: permissionsLoading } = usePermissions(); // ← PERM

  const canViewPermissionPage   = can(PERMISSION_MODULE, "View");   // ← PERM
  const canEditPermissionPage   = can(PERMISSION_MODULE, "Edit");   // ← PERM
  const canDeletePermissionPage = can(PERMISSION_MODULE, "Delete"); // ← PERM

  const [cashiers, setCashiers]               = useState([]);
  const [selectedCashier, setSelectedCashier] = useState("");
  const [permissions, setPermissions]         = useState([]);
  const [loading, setLoading]                 = useState(false);
  const [saving, setSaving]                   = useState(false);
  const [error, setError]                     = useState("");
  const [debugInfo, setDebugInfo]             = useState("");

  // =========================================================
  // LOAD CASHIERS
  // =========================================================
  useEffect(() => {
    if (!canViewPermissionPage) return;                           // ← PERM

    (async () => {
      setError("");
      const candidates = [
        `${API}/cashiers`, `${API}/Cashiers`,
        `${API}/cashier`,  `${API}/Cashier`,
      ];
      const result = await tryUrls(candidates);

      if (!result.ok) {
        const detail = result.errors
          .map((e) => `${e.url} → ${e.status || e.message}`)
          .join("\n");
        setError("Unable to load cashiers from any of:\n" + detail);
        setDebugInfo("Tried: " + candidates.join(", "));
        return;
      }

      const list = pickArray(result.data);
      console.log("[CashierPermission] Cashiers loaded:", list.length, list);
      setCashiers(list);

      if (list.length > 0) {
        const first = list[0];
        const id = first.CashierID ?? first.CashierId ?? first.id;
        if (id) {
          setSelectedCashier(String(id));
          loadPermissions(String(id));
        }
      } else {
        setDebugInfo(`Endpoint ${result.url} returned zero cashiers.`);
      }
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [canViewPermissionPage]);                                    // ← PERM

  // =========================================================
  // LOAD PERMISSIONS
  // =========================================================
  const loadPermissions = async (cashierID) => {
    if (!cashierID) {
      setPermissions([]);
      return;
    }

    try {
      setLoading(true);
      setError("");
      setDebugInfo("");

      const candidates = [
        `${API}/cashiers/${cashierID}/permissions`,
        `${API}/${cashierID}/permissions`,
      ];

      const result = await tryUrls(candidates);

      if (!result.ok) {
        const detail = result.errors
          .map((e) => `${e.url} → ${e.status || e.message}`)
          .join("\n");
        setError(
          "Unable to load permissions for cashier " + cashierID + ".\n" + detail
        );
        setPermissions([]);
        return;
      }

      const rows = pickArray(result.data);
      console.log(
        "[CashierPermission] Permission rows for cashier",
        cashierID, ":", rows.length
      );

      setPermissions(
        rows.map((row) => ({
          ...emptyPermission,
          ...row,
          CanView:             Boolean(row.CanView),
          CanAdd:              Boolean(row.CanAdd),
          CanEdit:             Boolean(row.CanEdit),
          CanDelete:           Boolean(row.CanDelete),
          CanPrint:            Boolean(row.CanPrint),
          CanViewCostPrice:    Boolean(row.CanViewCostPrice),
          CanViewSellingPrice: Boolean(row.CanViewSellingPrice),
          CanViewProfit:       Boolean(row.CanViewProfit),
        }))
      );

      if (rows.length === 0) {
        setDebugInfo(
          `Cashier ${cashierID} has no rows in CashierPermissions. ` +
            `Insert default rows before toggling.`
        );
      }
    } catch (err) {
      console.error("[CashierPermission] loadPermissions unexpected:", err);
      setError(err.message || "Unexpected error loading permissions.");
      setPermissions([]);
    } finally {
      setLoading(false);
    }
  };

  const handleCashierChange = (e) => {
    const id = e.target.value;
    setSelectedCashier(id);
    loadPermissions(id);
  };

  // =========================================================
  // TOGGLES                                                 // ← PERM (guarded)
  // =========================================================
  const changePermission = (permissionID, field) => {
    if (!canEditPermissionPage) return;                           // ← PERM
    setPermissions((prev) =>
      prev.map((permission) =>
        permission.PermissionID !== permissionID
          ? permission
          : { ...permission, [field]: !permission[field] }
      )
    );
  };

  const setAll = (field, value) => {
    if (!canEditPermissionPage) return;                           // ← PERM
    setPermissions((prev) =>
      prev.map((permission) => ({ ...permission, [field]: value }))
    );
  };

  const applyViewOnly = () => {
    if (!canEditPermissionPage) return;                           // ← PERM
    setPermissions((prev) =>
      prev.map((p) => ({
        ...p,
        CanView: true, CanAdd: false, CanEdit: false, CanDelete: false, CanPrint: true,
      }))
    );
  };

  const applyFullAccess = () => {
    if (!canEditPermissionPage) return;                           // ← PERM
    setPermissions((prev) =>
      prev.map((p) => ({
        CanView: true, CanAdd: true, CanEdit: true, CanDelete: true, CanPrint: true,
        CanViewCostPrice: true, CanViewSellingPrice: true, CanViewProfit: true,
        PermissionID: p.PermissionID,
        ModuleName: p.ModuleName,
        PermissionName: p.PermissionName,
      }))
    );
  };

  const clearAll = () => {
    if (!canEditPermissionPage) return;                           // ← PERM
    setPermissions((prev) =>
      prev.map((p) => ({
        ...emptyPermission,
        PermissionID: p.PermissionID,
        ModuleName: p.ModuleName,
        PermissionName: p.PermissionName,
      }))
    );
  };

  // =========================================================
  // SAVE
  // =========================================================
  const savePermissions = async () => {
    // ----- Permission guard -----                             // ← PERM
    if (!canEditPermissionPage) {
      alert("You do not have permission to modify cashier permissions.");
      return;
    }

    if (!selectedCashier) {
      alert("Please select a cashier");
      return;
    }

    const payload = { permissions, updatedBy: user?.UserID ?? 0 }; // ← PERM (audit trail)

    const candidates = [
      { url: `${API}/cashiers/${selectedCashier}/permissions`, method: "post" },
      { url: `${API}/${selectedCashier}/permissions`,          method: "post" },
    ];

    try {
      setSaving(true);
      setError("");

      let lastError = null;

      for (const c of candidates) {
        try {
          const res = await axios[c.method](c.url, payload);
          console.log("[CashierPermission] SAVE OK:", c.url, res.data);
          alert("Permissions saved successfully");
          setSaving(false);
          return;
        } catch (err) {
          const status = err?.response?.status;
          console.warn(
            "[CashierPermission] SAVE failed at", c.url, "status:", status
          );
          lastError = err;
        }
      }

      throw lastError || new Error("Save failed");
    } catch (err) {
      console.error("[CashierPermission] savePermissions:", err);
      alert(
        err?.response?.data?.message ||
          err.message ||
          "Unable to save permissions"
      );
    } finally {
      setSaving(false);
    }
  };

  // =========================================================
  // SUMMARY
  // =========================================================
  const summary = useMemo(() => {
    const totals = {};
    COLUMNS.forEach((c) => (totals[c.key] = 0));
    permissions.forEach((p) =>
      COLUMNS.forEach((c) => { if (p[c.key]) totals[c.key]++; })
    );
    return totals;
  }, [permissions]);

  const accent = {
    amber:   "bg-amber-100 text-amber-700 ring-amber-200",
    blue:    "bg-blue-100 text-blue-700 ring-blue-200",
    emerald: "bg-emerald-100 text-emerald-700 ring-emerald-200",
    default: "bg-gray-100 text-gray-700 ring-gray-200",
  };

  // =========================================================
  // ACCESS DENIED GATE                                      // ← PERM
  // ---------------------------------------------------------
  // Check this AFTER all hooks so we don't break the Rules of
  // Hooks. Waiting for permissionsLoading avoids a flash of
  // "Access Denied" on first paint.
  // =========================================================
  if (permissionsLoading) {
    return (
      <div className="p-6 flex items-center justify-center min-h-[60vh] text-gray-500">
        <RefreshCw className="animate-spin mr-2" size={18} />
        Checking permissions…
      </div>
    );
  }

  if (!canViewPermissionPage) {
    return (
      <div className="p-6">
        <div className="max-w-xl mx-auto rounded-xl border border-red-200 bg-red-50 p-8 text-center">
          <Lock className="mx-auto text-red-500 mb-3" size={32} />
          <h2 className="text-lg font-bold text-red-700">Access Denied</h2>
          <p className="text-sm text-red-600 mt-2">
            You do not have permission to manage cashier permissions.
          </p>
          <p className="text-xs text-red-400 mt-3">
            Module: <code>{PERMISSION_MODULE}</code>
          </p>
        </div>
      </div>
    );
  }

  // =========================================================
  // RENDER
  // =========================================================
  const readOnly = !canEditPermissionPage;                        // ← PERM

  return (
    <div className="p-6">
      {/* HEADER */}
      <div className="mb-6 flex items-center justify-between">
        <div>
          <h1 className="flex items-center gap-2 text-2xl font-bold text-gray-800">
            <ShieldCheck size={24} className="text-indigo-600" />
            Cashier Permissions
          </h1>
          <p className="text-gray-500 text-sm mt-1">
            Control module access and visibility of cost, selling price and profit
          </p>
        </div>

        {/* ← PERM: read-only badge */}
        {readOnly && (
          <span className="rounded-full bg-slate-200 px-3 py-1 text-xs font-semibold text-slate-600">
            READ ONLY
          </span>
        )}
      </div>

      {/* ERROR */}
      {error && (
        <div className="mb-4 flex items-start gap-3 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700 whitespace-pre-line">
          <AlertCircle size={18} className="mt-0.5 shrink-0" />
          <div className="flex-1">{error}</div>
          <button onClick={() => setError("")} className="text-red-500 hover:text-red-700">
            <X size={16} />
          </button>
        </div>
      )}

      {/* DEBUG INFO */}
      {debugInfo && (
        <div className="mb-4 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-xs text-amber-800 whitespace-pre-line">
          <strong>Debug:</strong> {debugInfo}
        </div>
      )}

      {/* CASHIER SELECTOR */}
      <div className="bg-white rounded-xl shadow p-5 mb-6">
        <label className="block mb-2 font-semibold text-gray-700">
          Select Cashier ({cashiers.length} loaded)
        </label>

        <select
          value={selectedCashier}
          onChange={handleCashierChange}
          className="border rounded-lg p-3 w-full md:w-96 outline-none focus:ring-2 focus:ring-indigo-200"
        >
          <option value="">-- Select Cashier --</option>
          {cashiers.map((cashier) => {
            const id   = cashier.CashierID ?? cashier.CashierId ?? cashier.id;
            const code = cashier.Code ?? cashier.CashierCode ?? "";
            const name = cashier.Name ?? cashier.CashierName ?? "";
            return (
              <option key={id} value={id}>
                {code} {code && name ? " - " : ""} {name}
              </option>
            );
          })}
        </select>
      </div>

      {/* PERMISSIONS */}
      {selectedCashier && (
        <div className="bg-white rounded-xl shadow overflow-hidden">
          <div className="p-4 border-b flex flex-wrap items-center gap-2 justify-between">
            <div className="flex flex-wrap items-center gap-2">
              <span className="text-sm font-semibold text-gray-600 mr-2">
                Presets:
              </span>

              {/* ← PERM: preset buttons only rendered when user can edit */}
              {canEditPermissionPage && (
                <>
                  <button
                    onClick={applyViewOnly}
                    className="flex items-center gap-1.5 bg-gray-100 hover:bg-gray-200 text-gray-700 px-3 py-2 rounded-lg text-sm font-medium"
                  >
                    <Eye size={15} /> View Only
                  </button>
                  <button
                    onClick={applyFullAccess}
                    className="flex items-center gap-1.5 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 px-3 py-2 rounded-lg text-sm font-medium"
                  >
                    <ShieldCheck size={15} /> Full Access
                  </button>
                  <button
                    onClick={clearAll}
                    className="flex items-center gap-1.5 bg-gray-50 hover:bg-gray-100 text-gray-600 px-3 py-2 rounded-lg text-sm font-medium"
                  >
                    <ShieldOff size={15} /> Clear
                  </button>
                </>
              )}

              <button
                onClick={() => loadPermissions(selectedCashier)}
                disabled={loading}
                className="flex items-center gap-1.5 bg-white border border-gray-200 hover:bg-gray-50 text-gray-700 px-3 py-2 rounded-lg text-sm font-medium disabled:opacity-50"
              >
                <RefreshCw size={15} className={loading ? "animate-spin" : ""} />
                Reload
              </button>
            </div>

            {/* ← PERM: Save button only when user can edit */}
            {canEditPermissionPage && (
              <button
                onClick={savePermissions}
                disabled={saving || loading || permissions.length === 0}
                className="flex items-center gap-2 bg-green-600 hover:bg-green-700 text-white px-5 py-2 rounded-lg font-semibold disabled:opacity-50"
              >
                <Save size={16} />
                {saving ? "Saving..." : "Save Permissions"}
              </button>
            )}

            {readOnly && (
              <div className="flex items-center gap-2 rounded-lg border border-slate-200 bg-slate-50 px-4 py-2 text-xs font-semibold text-slate-500">
                <Lock size={14} /> Read-only access — you cannot modify permissions.
              </div>
            )}
          </div>

          {loading ? (
            <div className="p-10 text-center text-gray-500">
              Loading permissions...
            </div>
          ) : permissions.length === 0 ? (
            <div className="p-10 text-center text-gray-500">
              No permission rows found for this cashier.
              <br />
              <span className="text-xs">
                Add rows to <code>CashierPermissions</code> for this cashier first.
              </span>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full min-w-[1000px]">
                <thead>
                  <tr className="bg-gray-50 border-b">
                    <th className="p-3 text-left text-xs font-bold uppercase tracking-wide text-gray-600">
                      Module
                    </th>
                    <th className="p-3 text-left text-xs font-bold uppercase tracking-wide text-gray-600">
                      Permission
                    </th>
                    {COLUMNS.map((col) => {
                      const Icon = col.icon;
                      const active = summary[col.key] > 0;
                      const cls = accent[col.accent || "default"];
                      return (
                        <th
                          key={col.key}
                          className="p-3 text-center text-xs font-bold uppercase tracking-wide text-gray-600 whitespace-nowrap"
                        >
                          <div className="flex flex-col items-center gap-1">
                            <div className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full ring-1 ${cls}`}>
                              <Icon size={12} />
                              {col.label}
                            </div>
                            <div className="text-[10px] font-medium text-gray-400">
                              {active ? `${summary[col.key]} on` : "all off"}
                            </div>
                          </div>
                        </th>
                      );
                    })}
                  </tr>

                  {/* ← PERM: "All rows → On/Off" row hidden in read-only mode */}
                  {canEditPermissionPage && (
                    <tr className="bg-white border-b">
                      <td colSpan={2} className="p-3 text-right text-xs text-gray-500 italic">
                        All rows →
                      </td>
                      {COLUMNS.map((col) => (
                        <td key={col.key} className="p-2 text-center">
                          <div className="flex items-center justify-center gap-1">
                            <button
                              onClick={() => setAll(col.key, true)}
                              className="text-[10px] px-2 py-0.5 rounded bg-gray-700 text-white hover:bg-gray-800"
                            >
                              On
                            </button>
                            <button
                              onClick={() => setAll(col.key, false)}
                              className="text-[10px] px-2 py-0.5 rounded bg-gray-200 text-gray-700 hover:bg-gray-300"
                            >
                              Off
                            </button>
                          </div>
                        </td>
                      ))}
                    </tr>
                  )}
                </thead>

                <tbody>
                  {permissions.map((permission, idx) => (
                    <tr
                      key={permission.PermissionID ?? idx}
                      className={idx % 2 ? "bg-gray-50/50" : "bg-white"}
                    >
                      <td className="p-3 text-sm font-medium text-gray-800">
                        {permission.ModuleName}
                      </td>
                      <td className="p-3 text-sm text-gray-600">
                        {permission.PermissionName}
                      </td>

                      {COLUMNS.map((col) => {
                        const isOn = Boolean(permission[col.key]);
                        return (
                          <td key={col.key} className="p-3 text-center">
                            <input
                              type="checkbox"
                              checked={isOn}
                              onChange={() =>
                                changePermission(permission.PermissionID, col.key)
                              }
                              disabled={readOnly}                 /* ← PERM */
                              className="w-5 h-5 rounded cursor-pointer accent-indigo-600 disabled:cursor-not-allowed disabled:opacity-50"
                            />
                          </td>
                        );
                      })}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          <div className="p-4 bg-gray-50 border-t flex flex-wrap gap-4 text-xs text-gray-500">
            <span className="flex items-center gap-1">
              <Layers size={13} /> Cost / Selling / Profit columns only affect
              whether the user <strong>sees</strong> those values.
            </span>
          </div>
        </div>
      )}
    </div>
  );
}